window.__BOOK__['p03'].push([{"id":"b46-1","bab":"الجزء 5","sec":"ذكر النابغة الجعدي ونسبه وأخباره","page":"ج5 ص5","text":"والسبب الذي من أجله قيل هذا الشعر هو على ما ذكر أبو عمرو الشيباني والقحذمي وهو الصحيح حبان بن قيس بن عبد الله بن وحوح بن عدس وقيل ابن عمرو بن عدس مكان وحوح ابن ربيعة بن جعدة بن كعب بن ربيعة بن عامر بن صعصعة بن معاوية بن بكر بن هوازن بن منصور بن عكرمة بن خصفة بن قيس بن عيلان ابن مضر هذا النسب الذي عليه الناس اليوم مجتمعون وقد روى ابن الكلبي وأبو اليقظان وأبو عبيدة وغيرهم في ذلك روايات تخالف هذا فمنها أن ابن الكلبي ذكر عن أبيه أن خصفة الذي يقول الناس إنه ابن قيس بن عيلان ليس كما قالوا وأن عكرمة ابن قيس بن عيلان وخصفة أمه وهي امرأة من أهل هجر وقيل بل هي حاضنته وكان قيس بن عيلان قد\nمات وعكرمة صغير فربته حتى كبر وكان قومه يقولون هذا عكرمة بن خصفة فبقيت عليه ومن لا يعلم يقول عكرمة بن خصفة بن قيس كما يقال خندف وإنما هي امرأة وزوجها إلياس بن مضر وقالوا في صعصعة بن معاوية إن الناقمية بنت عامر بن مالك وهو الناقم سمي بذلك لأنه انتقم بلطمة لطمها وهو ابن سعد بن جدان بن جديلة بن أسد بن ربيعة بن نزار كانت عند معاوية بن بكر بن هوازن فمات عنها أو طلقها وهي نسء فتزوجها سعد بن زيد مناة بن تميم فولدت على فراشه صعصعة ابن معاوية ثم ولدت هبيرة ونجدة وجنادة فلما مات سعد اقتسم بنوه الميراث وأخرجوا صعصعة منه وقالوا أنت ابن معاوية بن بكر فلما رأى ذلك أتى بني معاوية بن بكر فأقروا بنسبه ودفعوه عن الميراث فلما رأى ذلك أتى سعد بن الظرب العدواني فشكا إليه ما لقي فزوجه بنت أخيه عمرة\nبنت عامر بن الظرب وأبوها عامر الذي يقال له ذو الحلم وعمرة ابنته هذه هي التي كانت تقرع له العصا إذا سها في الحكم وله يقول الشاعر\n(لذي الحلم قبل اليوم ما تقرع العصا ... وما علم الإنسان إلا ليعلما)\nال وكانت عمرة يوم زوجها عمها نسئا من ملك من ملوك اليمن يقال له الغافق بن العاصي الأزدي والملك يومئذ في الأزد فولدت على فراش صعصعة عامر بن صعصعة فسماه صعصعة عامرا بجده عامر ابن الظرب وقال في ذلك حبيب بن وائل بن دهمان بن نصر بن معاوية بن بكر بن هوازن\n(أزعمت أن الغافقي أبوكم ... نسب لعمر أبيك غير مفند)\n(وأبوكم ملك ينتف باسته ... هلباء عافية كعرف الهدهد)\n(جنحت عجوزكم إليه فردها ... نسئا بعامركم ولما يويد)\nيكنى النابغة أبا ليلى وأخبرنا أبو خليفة عن محمد بن سلام قال هو قيس بن عبد الله بن عدس بن ربيعة بن جعدة بن كعب بن ربيعة بن عامر بن صعصعة وقال ابن الأعرابي هو قيس بن عبد الله بن عمرو بن عدس بن ربيعة بن جعدة بن كعب بن ربيعة ووافق ابن سلام في باقي نسبه وهذا وهم ممن قال إن اسمه قيس وليس يشك في أنه كان له أخ يقال له وحوح بن قيس وهو الذي قتله بنو أسد وخبره يذكر بعد هذا ليصدق نسب النابغة وأمه فاخرة بنت عمرو بن جابر بن شحنة الأسدي","topic":"ذكر النابغة الجعدي ونسبه وأخباره","topicNo":46,"sp":0,"spl":"ذكر النابغة الجعدي ونسبه وأخباره"},
{"id":"b46-2","bab":"الجزء 5","sec":"سبب لقبه النابغة","page":"ج5 ص8","text":"وإنما سمي النابغة لأنه أقام مدة لا يقول الشعر ثم نبغ فقاله أخبرني الحسين بن يحيى قال قال حماد قرأت على القحذمي قال الجعدي الشعر في الجاهلية ثم أجبل دهرا ثم نبغ بعد في الشعر في الإسلام أخبرني أحمد بن عبيد الله بن عمار عن محمد بن حبيب عن ابن الأعرابي قال\nأقام النابغة الجعدي ثلاثين سنة لا يتكلم ثم تكلم بالشعر قال القحذمي في رواية حماد عنه كان الجعدي أسن من نابغة بني ذبيان قال ابن سلام في رواية أبي خليفة عنه كان الجعدي النابغة قديما شاعرا طويلا مفلقا طويل البقاء في الجاهلية والإسلام وكان أكبر من الذبياني ويدل على ذلك قوله\n(ومن يك سائلا عني فإني ... من الفتيان أيام الخنان)\n(أتت مائة لعام ولدت فيه ... وعشر بعد ذاك وحجتان)\n(فقد أبقت خطوب الدهر مني ... كما أبقت من السيف اليماني)\nال وعمر بعد ذلك عمرا طويلا سئل محمد بن حبيب عن أيام الخنان ما هي فقال وقعة لهم فقال قائل منهم وقد لقوا عدوهم خنوهم بالرماح فسمي ذلك العام الخنان ويدل على أنه أقدم من النابغة الذبياني أنه عمر مع المنذر بن المحرق قبل النعمان بن المنذر وكان النابغة الذبياني مع النعمان بن المنذر وفي عصره ولم يكن له قدم إلا أنه مات قبل الجعدي ولم يدرك الإسلام والجعدي الذي يقول\n(تذكرت شيئا قد مضى لسبيله ... ومن عادة المحزون أن يتذكرا)\n(نداماي عند المنذر بن محرق ... أرى اليوم منهم ظاهر الأرض مقفرا)\n(كهول وفتيان كأن وجوههم ... دنانير مما شيف في أرض قيصرا)\nخبرني أحمد بن عبد العزيز و حبيب بن نصر قالا حدثنا عمر بن شبة قال حدثني عبد الله بن محمد بن حكيم عمن كان يأخذ العلم عنه ولم يسم إلي أحدا في هذا أن النابغة عمر مائة وثمانين سنة وهو القائل\n(لبست أناسا فأفنيتهم ... وأفنيت بعد أناس أناسا)\n(ثلاثة أهلين أفنيتهم ... وكان الإله هو المستآسا)\nهي قصيدة طويلة يقول فيها وفيه غناء صوت\n(وكنت غلاما أقاسي الحروب ... يلقى المقاسون مني مراسا)\n(فلما دنونا لجرس النباح ... لم نعرف الحي إلا التماسا)\n(أضاءت لنا النار وجها أغر ... ملتبسا بالفؤاد التباسا)\nنى في هذه الثلاثة الأبيات فليح بن أبي العوراء خفيف ثقيل أول بالوسطى رجع الخبر إلى رواية عمر بن شبة قال وقال أيضا\n(ألا زعمت بنو سعد بأني ... ألا كذبوا كبير السن فاني)\n(أتت مائة لعام ولدت فيه ... وعشر بعد ذاك وحجتان)\nال وأنشد عمر بن الخطاب رضي الله تعالى عنه أبياته التي يقول فيها\n(ثلاثة أهلين أفنيتهم ... )\nقال له عمر رضي الله تعالى عنه كم لبثت مع كل أهل قال ستين سنة","topic":"ذكر النابغة الجعدي ونسبه وأخباره","topicNo":46,"sp":1,"spl":"سبب لقبه النابغة — النابغة يعمر طويلا","partial":1},
{"id":"b46-3","bab":"الجزء 5","sec":"النابغة يعمر طويلا","page":"ج5 ص11","text":"وأخبرني بعض أصحابنا عن أبي بكر بن دريد عن عبد الرحمن ابن أخي الأصمعي عن عمه قال أنشد رجل من العجم قول النابغة الجعدي\n(لبست أناسا فأفنيتهم ... وأفنيت بعد أناس أناسا)\nفسر له فقال بدين شان بود أي هذا رجل مشؤوم وأما ابن قتيبة فإنه ذكر ما رواه لنا عنه إبراهيم بن محمد أنه عمر مائتين وعشرين سنة ومات بأصبهان وما ذاك بمنكر لأنه قال لعمر رضي الله تعالى عنه إنه أفنى ثلاثة قرون كل قرن ستون سنة فهذه مائة وثمانون ثم عمر بعده فمكث بعد قتل عمر خلافة عثمان وعلي ومعاوية ويزيد وقدم على\nعبد الله بن الزبير بمكة وقد دعا لنفسه فاستماحه ومدحه وبين عبد الله ابن الزبير وبين عمر نحو مما ذكر ابن قتيبة بل لا أشك أنه قد بلغ هذه السن وهاجى أوس بن مغراء بحضرة الأخطل والعجاج وكعب بن جعيل فغلبه أوس وكان مغلبا حدثنا أحمد بن عمر بن موسى القطان المعروف بابن زنجوية قال حدثنا إسماعيل بن عبد الله السكري قال حدثنا يعلى بن الأشدق العقيلي قال حدثني نابغة بني جعدة قال أنشدت النبي هذا الشعر فأعجب به\n(بلغنا السماء مجدنا وجدودنا ... وإنا لنبغي فوق ذلك مظهرا)\nفقال النبي \" فأين المظهر يا أبا ليلى \" فقلت الجنة فقال \" قل إن شاء الله \" فقلت إن شاء الله\n(ولا خير في حلم إذا لم يكن له ... بوادر تحمي صفوه أن يكدرا)\n(ولا خير في جهل إذا لم يكن له ... حليم إذا ما أورد الأمر أصدرا)\nقال النبي \" أجدت لا يفضض الله فاك \" قال فلقد رأيته وقد أتت عليه مائة سنة أو نحوها وما انفض من فيه سن","topic":"ذكر النابغة الجعدي ونسبه وأخباره","topicNo":46,"sp":1,"spl":"سبب لقبه النابغة — النابغة يعمر طويلا"},
{"id":"b46-4","bab":"الجزء 5","sec":"النابغة ممن أنكر الخمر والسكر في الجاهلية","page":"ج5 ص13","text":"أخبرني محمد بن الحسن بن دريد قال أخبرني أبو حاتم قال أخبرنا أبو عبيدة قال كان النابغة الجعدي ممن فكر في الجاهلية وأنكر الخمر والسكر وما يفعل بالعقل وهجر الأزلام والأوثان وقال في الجاهلية كلمته التي أولها\n(الحمد لله لا شريك له ... من لم يقلها فنفسه ظلما)\nكان يذكر دين إبراهيم والحنيفية ويصوم ويستغفر ويتوقى أشياء لعواقبها ووفد على النبي فقال\n(أتيت رسول الله إذ جاء بالهدى ... ويتلو كتابا كالمجرة نيرا)\n(وجاهدت حتى ما أحس ومن معي ... سهيلا إذا ما لاح ثمت غورا)\n(أقيم على التقوى وأرضى بفعلها ... وكنت من النار المخوفة أوجرا)\nحسن إسلامه وأنشد النبي فقال له \" لا يفضض الله فاك \" وشهد مع علي بن أبي طالب رضي الله تعالى عنه صفين وقد ذكر خبره مع عمر رضي الله عنه وأما خبره مع عثمان فأخبرنا به أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال قال مسلمة بن محارب دخل النابغة الجعدي على عثمان رضي الله تعالى عنه فقال أستودعك الله يا أمير المؤمنين قال وأين تريد يا أبا ليلى قال ألحق بإبلي فأشرب من ألبانها فإني منكر لنفسي فقال أتعربا بعد الهجرة يا أبا ليلى أما علمت أن ذلك مكروه قال ما علمته وما كنت لأخرج حتى أعلمك قال فأذن له وأجل له في ذلك أجلا فدخل على الحسن والحسين ابني علي فودعهما فقالا له أنشدنا من شعرك يا أبا ليلى فأنشدهما\n(الحمد لله لا شريك له ... من لم يقلها فنفسه ظلما)\nقالا يا أبا ليلى ما كنا نروي هذا الشعر إلا لأمية بن أبي\nالصلت فقال يا بني رسول الله إني لصاحب هذا الشعر وأول من قاله وإن السروق لمن سرق شعر أمية قال أبو زيد عمر بن شبة في خبره كان النابغة شاعرا متقدما وكان مغلبا ما هاجى قط إلا غلب هاجى أوس بن مغراء وليلى الأخيلية وكعب بن جعيل فغلبوه جميعا","topic":"ذكر النابغة الجعدي ونسبه وأخباره","topicNo":46,"sp":2,"spl":"النابغة ممن أنكر الخمر والسكر في الجاهلية"},
{"id":"b46-5","bab":"الجزء 5","sec":"النابغة وأوس بن مغراء","page":"ج5 ص15","text":"وقال أبو عمرو الشيباني كان بدء حديث النابغة وأوس بن مغراء أن معاوية لما وجه بسر بن أرطأة الفهري لقتل شيعة علي بن أبي طالب رضي الله تعالى عنه قام إليه معن بن يزيد بن الأخنس السلمي وزياد بن الأشهب ابن ورد بن عمرو بن ربيعة بن جعدة فقالا يا أمير المؤمنين نسألك بالله وبالرحم ألا تجعل لبسر على قيس سلطانا فيقتل قيسا بمن قتلت بنو سليم من بني فهر وبني كنانة يوم دخل رسول الله مكة فقال معاوية يا بسر لا أمر لك على قيس وسار بسر حتى أتى المدينة فقتل ابني عبيد الله\nابن العباس وفر أهل المدينة ودخلوا الحرة حرة بني سليم ثم سار بسر حتى أتى الطائف فقالت له ثقيف ما لك علينا سلطان نحن من قيس فسار حتى أتى همدان وهم في جبل لهم يقال له شبام فتحصنت فيه همدان ثم نادوا يا بسر نحن همدان وهذا شبام فلم يلتفت إليهم حتى إذا اغتروا ونزلوا إلى قراهم أغار عليهم فقتل وسبى نساءهم فكن أول مسلمات سبين في الإسلام ومر بحي من بني سعد نزول بين ظهري بني جعدة بالفلج فأغار بسر على الحي السعديين فقتل منهم وأسر فقال أوس بن مغراء في ذلك\n(مشرين ترعون النجيل وقد غدت ... بأوصال قتلاكم كلاب مزاحم)\nلمشر الذي قد بسط ثوبه في الشمس والنجيل جنس من الحمض فقال النابغة يجيبه\n(متى أكلت لحومكم كلابي ... أكلت يديك من جرب تهام)\nخبرنا أبو خليفة الفضل بن الحباب مما أجاز لنا روايته عنه من حديثه\nوأخباره مما ذكره منها عن محمد بن سلام الجمحي عن أبي الغراف وأخبرنا به أحمد بن عبد العزيز وحبيب بن نصر قالا حدثنا عمر بن شبة عن محمد بن سلام عن أبي الغراف أن النابغة هاجى أوس بن مغراء قال ولم يكن أوس مثله ولا قريبا منه في الشعر فقال النابغة إني وإياه لنبتدر بيتا أينا سبق إليه غلب صاحبه فلما بلغه قول أوس\n(لعمرك ما تبلى سرابيل عامر ... من اللؤم ما دامت عليها جلودها)\nال النابغة هذا البيت الذي كنا نبتدر إليه فغلب أوس عليه قال أبو زيد فحدثني المدائني أنهما اجتمعا في المربد فتنافرا وتهاجيا وحضرهما العجاج والأخطل وكعب بن جعيل فقال أوس\n(لما رأت جعدة منا ووردا ... ولوا نعاما في البلاد ربدا)\n(إن لنا عليكم معدا ... كاهلها وركنها الأشدا)\nقال العجاج\n(كل امرىء يعدو بما استعدا ... )\nقال الأخطل يعين أوس بن مغراء ويحكم به\n(وإني لقاض بين جعدة عامر ... وسعد قضاء بين الحق فيصلا)\n(أبو جعدة الذئب الخبيث طعامه ... وعوف بن كعب أكرم الناس أولا)\nقال كعب بن جعيل\n(إني لقاض قضاء سوف يتبعه ... من أم قصدا ولم يعدل إلى أود)\n(فصلا من القول تأتم القضاة به ... ولا أجور ولا أبغي على أحد)\n(ناكت بنو عامر سعدا وشاعرها ... كما تنيك بنو عبس بني أسد)","topic":"ذكر النابغة الجعدي ونسبه وأخباره","topicNo":46,"sp":3,"spl":"النابغة وأوس بن مغراء","partial":1},
{"id":"b46-6","bab":"الجزء 5","sec":"سبب مهاجاته ليلى الأخيلية","page":"ج5 ص18","text":"وقال أبو عمرو الشيباني كان سبب المهاجاة بين ليلى الأخيلية وبين الجعدي أن رجلا من قشير يقال له ابن الحيا وهي أمه واسمه سوار بن أوفى بن سبرة هجاه وسب أخواله من أزد في أمر كان بين قشير وبين بني جعدة وهم بأصبهان متجاورون فأجابه النابغة بقصيدته التي يقال لها الفاضحة سميت بذلك لأنه ذكر فيها مساوي قشير وعقيل وكل ما كانوا يسبون به وفخر بمآثر قومه وبما كان لسائر بطون بني عامر سوى هذين الحيين من قشير وعقيل\n(جهلت علي ابن الحيا وظلمتني ... وجمعت قولا جاء بيتا مضللا)\nقال في هذه القصة أيضا قصيدته التي أولها\n(إما ترى ظلل الأيام قد حسرت ... عني وشمرت ذيلا كان ذيالا)\nهي طويلة يقول فيها\n(ويوم مكة إذ ماجدتم نفرا ... حاموا على عقد الأحساب أزوالا)\n(عند النجاشي إذ تعطون أيديكم ... مقرنين ولا ترجون إرسالا)\n(إذ تستحبون عند الخذل أن لكم ... من آل جعدة أعماما وأخوالا)\n(لو تستطيعون أن تلقوا جلودكم ... وتجعلوا جلد عبد الله سربالا)\nعني عبد الله بن جعدة بن كعب\n(إذا تسربلتم فيه لينجيكم ... مما يقول ابن ذي الجدين إذ قالا)\n(حتى وهبتم لعبد الله صاحبه ... والقول فيكم بإذن الله ما فالا)\n(تلك المكارم لاقعبان من لبن ... شيبا بماء فعادا بعد أبوالا)\nعني بهذا البيت أن ابن الحيا فخر عليه بأنهم سقوا رجلا من جعدة أدركوه في سفر وقد جهد عطشا لبنا وماء فعاش وقال في هذه القصة أيضا قصيدته التي أولها\n(أبلغ قشيرا والحريش فما ... ذا رد في أيديكم شتمي)\nوفخر عليهم بقتل علقمة الجعفي يوم وادي نساح وقتل شراحيل بن الأصهب الجعفي وبيوم رحرحان أيضا فقال فيه\n(هلا سألت بيومي رحرحان وقد ... ظنت هوازن أن العز قد زالا)\nلما ذكر ذلك النابغة قال\n(تلك المكارم لا قعبان من لبن ... شيبا بماء فعادا بعد أبوالا)\nفخر بما له وغض مما لهم ودخلت ليلى الأخيلية بينهما فقالت\n(وما كنت لو قاذفت جل عشيرتي ... لأذكر قعبي حازر قد تثملا)\nوهي كلمة فلما بلغ النابغة قولها قال\n(ألا حييا ليلى وقولا لها هلا ... فقد ركبت أيرا أغر محجلا)\n(وقد أكلت بقلا وخيما نباته ... وقد شربت من آخر الصيف أيلا)\nعني ألبان الأيل\n(دعي عنك تهجاء الرجال وأقبلي ... على أذلغي يملأ استك فيشلا)\n(وكيف أهاجي شاعرا رمحه استه ... خضيب البنان لا يزال مكحلا)\nردت عليه ليلى الأخيلية فقالت\n(أنابغ لم تنبغ ولم تك أولا ... وكنت صنيا بين صدين مجهلا)\nلصني شعب صغير يسيل منه الماء وصدان جبلان\n(أنابغ إن تنبغ بلؤمك لا تجد ... للؤمك إلا وسط جعدة مجعلا)\n(تعيرني داء بأمك مثله ... وأي حصان لا يقال لها هلا)\nغلبته فلما أتى بني جعدة قولها هذا اجتمع ناس منهم فقالوا والله لنأتين صاحب المدينة أو أمير المؤمنين فليأخذن لنا بحقنا من هذه الخبيثة فإنها قد شتمت أعراضنا وافترت علينا فتهيؤوا لذلك وبلغها أنهم يريدون أن يستعدوا عليها فقالت\n(أتاني من الأنباء أن عشيرة ... بشوران يزجون المطي المذللا)\n(يروح ويغدو وفدهم بصحيفة ... ليستجلدوا لي ساء ذلك معملا)\nقد أخبرني ببعض هذه القصة أحمد بن عبد العزيز عن عمر بن شبة فجاء بها مختلطة وهذا أوضح وأصح","topic":"ذكر النابغة الجعدي ونسبه وأخباره","topicNo":46,"sp":4,"spl":"سبب مهاجاته ليلى الأخيلية — يوم وادي نساح"},
{"id":"b46-7","bab":"الجزء 5","sec":"يوم وادي نساح","page":"ج5 ص21","text":"قال أبو عمرو فأما ما فخر به النابغة من الأيام فمنها يوم علقمة الجعفي فإنه غدا في مذحج ومعه زهير الجعفي فأتى بني عقيل بن كعب فأغار عليهم وفي بني عقيل بطون من سليم يقال لهم بنو بجلة فأصاب سبيا وإبلا كثيرة ثم انصرف راجعا بما أصاب فاتبعه بنو كعب ولم يلحق\nبه من بني عقيل إلا عقال بن خويلد بن عامر بن عقيل فجعل يأخذ أبعار إبل الجعفيين فيبول عليها حتى ينديها ثم يلحق ببني كعب فيقول إيه فدى لكم أبواي قد لحقتم القوم حتى وردوا عليهم النخيل في يوم قائظ ورأس زهير في حجر جارية من سليم من بني بجلة سباها يومئذ وهي تفليه وهو متوسد قطيفة حمراء وهي تضفر سعفاته أي أعلى رأسه بهدب القطيفة فلم يشعروا إلا بالخيل فكان أول من لحق زهيرا ابن النهاضة فضرب وجه زهير بقوسه حتى كسر أنفه ثم لحقه عقال بن خويلد فبعج بطنه فسال من بطنه برير وحلب والبرير ثمر الأراك والحلب لبن كان قد اصطبحه فذلك يوم يقول أبو حرب أخو عقال بن خويلد والله لا أصطبح لبنا حتى آمن من الصباح قال وهذا اليوم هو يوم وادي نساح وهو باليمامة","topic":"ذكر النابغة الجعدي ونسبه وأخباره","topicNo":46,"sp":4,"spl":"سبب مهاجاته ليلى الأخيلية — يوم وادي نساح"},
{"id":"b46-8","bab":"الجزء 5","sec":"يوم شراحيل","page":"ج5 ص22","text":"قال وأما يوم شراحيل بن الأصهب الجعفي فإنه يوم مذكور تفتخر به مضر كلها وكان شراحيل خرج مغيرا في جمع عظيم من اليمن وكان قد طال عمره وكثر تبعه وبعد صيته واتصل ظفره وكان قد صالح بني عامر على أن يغزو العرب مارا بهم في بدأته وعودته لا يعرض أحد منهم لصاحبه فخرج غازيا في بعض غزواته فأبعد ثم رجع إليهم فمر على بني جعدة فقرته ونحرت له فعمد ناس من أصحابه سفهاء فتناولوا إبلا لبني جعدة فنحروها فشكت ذلك بنو جعدة إلى شراحيل فقالوا قريناك وأحسنا ضيافتك ثم لم تمنع أصحابك مما يصنعون فقال إنهم قوم\nمغيرون وقد أساؤوا لعمري وإنما يقيمون عندكم يوما أو يومين ثم يرتحلون عنكم فقال الرقاد بن عمرو بن ربيعة بن جعدة لأخيه ورد بن عمرو وقيل بل قال ذلك لابن أخيه الجعد بن ورد دعني أذهب إلى بني قشير قال وجعدة وقشير أخوان لأم وأب أمهما ريطة بنت قنفذ بن مالك بن عوف بن امرئ القيس بن بهثة بن سليم بن منصور فأدعوهم واصنع أنت يا هذا لشراحيل طعاما حسنا كثيرا وادعه وأدخله إليك فاقتله فإن احتجت إلينا فدخن فإني إذا رأيت الدخان أتيتك بهم فوضعنا سيوفنا على القوم فعمد ورد هذا إلى طعام فأصلحه ودعا شراحيل وناسا من أصحابه وأهله وبني عمه فجعلوا كلما دخل البيت رجل قتله ورد حتى انتصف النهار فجاء أصحاب شراحيل يتبعونه فقال لهم ورد تروحوا فإن صاحبكم قد شرب وثمل وسيروح فرجعوا ودخن ورد وجاءت قشير فقتلوا من أدركوا من أصحابه وسار سائرهم وبلغهم قتل شراحيل فمروا على بني عقيل وهم إخوتهم فقالوا لنقتلن مالك بن المنتفق فقال لهم مالك أنا آتيكم بورد فركب ببني عقيل إلى بني جعدة وقشير ليعطوهم وردا فامتنعوا من ذلك وساروا بأجمعهم فذبوا عن عقيل حتى تفرق من كان مع شراحيل فقال في ذلك بحير بن عبد الله بن سلمة\n(أحي يتبعون العير نحرا ... أحب إليك أم حيا هلال)\n(لعلك قاتل وردا ولما ... تساق الخيل بالأسل النهال)\n(ألا يا مال ويح سواك أقصر ... أما ينهاك حلمك عن ضلال)","topic":"ذكر النابغة الجعدي ونسبه وأخباره","topicNo":46,"sp":5,"spl":"يوم شراحيل — يوما رحرحان"},
{"id":"b46-9","bab":"الجزء 5","sec":"يوما رحرحان","page":"ج5 ص24","text":"وأما يوما رحرحان فأحدهما مشهور قد ذكر في موضع آخر من هذا الكتاب بعقب أخبار الحارث بن ظالم وهذا اليوم الثاني فكان الطماح الحنفي أغار في بني حنيفة وبني قيس بن ثعلبة على بني الحريش بن كعب وبني عبادة بن عقيل وطوائف من بني عبس يقال لهم بنو حذيفة فركبت بنو جعدة وبنو أبي بكر بن كلاب ولم يشهد ذلك من بني كلاب غير بني أبي بكر فأدركوا الطماح من يومهم فاستنقذوا ما أخذه وأصابوا ما كان معه وقتلوا عددا من أصحابه وهزموهم قال وأما ما ذكره من إدراكهم بثأر كعب الفوارس فإن كعب الفوارس وهو ابن معاوية بن عبادة بن البكاء مر على بني نهد وعليه سلاحه فحمل عليه رجل من نهد يقال له خليف فقتله وأخذ فرسه وسلاحه ثم إن خليفا بعد ذلك بدهر مر على بني جعدة فرآه مالك بن عبد الله بن\nجعدة وعليه جبة كعب وفيها أثر الطعنة وكان محرما فلم يقدر على قتله فقال يا هذا ألا رقعت هذا الخرق الذي في جبتك وجعل يترصده بعد ذلك حتى بلغه بعد دهر أنه مر ببني جعدة فركب مالك بن عبد الله بن جعدة فرسا له وقد أخبر أن خليفا مر بجنباتهم فأدركه فقتله ثم قال بؤ بكعب ثم غزا نواحيهم عبد الله بن ثور بن معاوية بن عبادة بن البكاء جرما ونهدا وهم يومئذ في بني الحارث فناداهم بنو البكاء ليس معنا أحد من قومنا غيرنا وإن النهدي قتل صاحبنا محرما فقاتلهم نهد وجرم جميعا يومئذ وكان عبد الله بن ثور يومئذ على فرس ورد فأصابوا من نهد يومئذ غنيمة عظيمة وقتلوا قتلى كثيرة فقال عبد الله في ذلك\n(فسائل بني جرم إذا ما لقيتهم ... ونهدا إذا ححت عليك بنو نهد)\n(فإن يخبروك الحق عنا تجدهم ... يقولون أبلى صاحب الفرس الورد)","topic":"ذكر النابغة الجعدي ونسبه وأخباره","topicNo":46,"sp":5,"spl":"يوم شراحيل — يوما رحرحان"},
{"id":"b46-10","bab":"الجزء 5","sec":"يوم الفلج","page":"ج5 ص25","text":"قال وأما يوم الفلج فإن بكر بن وائل بعثت عينا على بني كعب ابن ربيعة حتى جاء الفلج وهو ماء فوجد النعم بعضه قريبا من بعض ووجد الناس قد احتملوا فليس في النعم إلا من لا طباخ به من راع أو ضعيف فجاءهم عينهم بذلك فركبت بكر بن وائل يريدونهم حتى إذا كانوا منهم بحيث يسمعون أصواتهم سمعوا الصهيل وأصوات الرجال فقالوا لعينهم ما هذا ويلك قال والله ما أدري وإن هذا لمما لم أعهد فأرسلوا من يعلم علمهم فرجع فأخبرهم أن الرجال قد رجعوا ورأى جمعا عظيما وخيولا كثيرة فكروا راجعين من ليلتهم وأصبحت بنو\nكعب فرأوا الأثر فاتبعوهم فأصابوا من أخرياتهم رجالا وخيلا فرجعوا بها قال وأما قوله\n(لو تستطيعون أن تلقوا جلودكم ... وتجعلوا جلد عبد الله سربالا)\nإن السبب في ذلك أن هبيرة بن عامر بن سلمة بن قشير لقي خداش ابن زهير البكائي فتنافرا على مائة من الإبل وقال كل منهما لصاحبه أنا أكرم وأعز منك فحكما في ذلك رجلا من بني ذي الجدين فقضى بينهما أن أعزهما وأكرمهما أقربهما من عبد الله بن جعدة نسبا فقال خداش بن زهير أنا أقرب إليه أم عبد الله بن جعدة عمتي وهي أميمة بنت عمرو ابن عامر وإنما أنت أدنى إليه مني منزلة بأب فلم يزالا يختصمان في القرابة لعبد الله دون المكاثرة بآبائهما إقرارا له بذلك حتى فلج هبيرة القشيري وظفر","topic":"ذكر النابغة الجعدي ونسبه وأخباره","topicNo":46,"sp":6,"spl":"يوم الفلج — عبد الله بن جعدة السيد المطاع"},
{"id":"b46-11","bab":"الجزء 5","sec":"عبد الله بن جعدة السيد المطاع","page":"ج5 ص26","text":"قال أبو عمرو وكان عبد الله بن جعدة سيدا مطاعا وكانت له إتاوة بعكاظ يؤتى بها يأتيه بها هذا الحي من الأزد وغيرهم فجاء سمير بن سلمة القشيري وعبد الله جالس على ثياب قد جمعت له من إتاوته فأنزله عنها وجلس مكانه فجاء رياح بن عمرو بن ربيعة بن عقيل وهو الخليع\nسمي بذلك لتخلعه عن الملوك لا يعطيهم الطاعة فقال للقشيري مالك ولشيخنا تنزله عن إتاوته ونحن ها هنا حوله فقال القشيري كذبت ما هي له ثم مد القشيري رجله فقال هذه رجلي فاضربها إن كنت عزيزا قال لا لعمري لا أضرب رجلك فقال له القشيري فامدد لي رجلك حتى تعلم أأضربها أم لا فقال ولا أمد لك رجلي ولكن أفعل ما لا تنكره العشيرة وما هو أعز لي وأذل لك ثم أهوى إلى رجل القشيري فسحبه على قفاه ونحاه وأقعد عبد الله بن جعدة مكانه قال وعبد الله بن جعدة أول من صنع الدبابة وكان السبب في ذلك أنهم انتجعوا ناحية البحرين فهجموا على عبد لرجل يقال له كودن في قصر حصين فدخن العبد ودعا النساء والصبيان فظنوا أنه يطعمهم ثريدا حتى إذا امتلأ القصر منهم أغلقه عليهم فصاح النساء والصبيان وقام العبد ومن معه على شرف القصر فجعل لا يدنوا منه أحد إلا رماه فلما رأى ذلك عبد الله بن جعدة صنع دبابة على جذوع النخل وألبسها جلود الإبل ثم جاء بها والقوم يحملونها حتى أسندوها إلى القصر ثم حفروا حتى خرقوه فقتل العبد ومن كان معه واستنقذ صبيانهم ونساءهم فذلك قول النابغة\n(ويوم دعا ولدانكم عبد كودن ... فخالوا لدى الداعي ثريدا مفلفلا)\n(وقى ابن زياد وهو عقبة خيركم ... هبيرة ينزو في الحديد مكبلا)\nعنى هبيرة بن عامر بن سلمة بن قشير وكان عبد الله بن مالك بن عدس بن ربيعة بن جعدة خرج ومعه مالك بن عبد الله بن جعدة حتى مروا على بني زياد العبسيين والرجال غيب فأخذوا ابنا لأنس بن زياد وانطلقوا به يرجون الفداء وانطلق عمه عمارة بن زياد حتى أتى بني كعب فلقي هبيرة ابن عامر بن سلمة بن قشير فقال له يا هبيره إن الناس يقولون إنك بخيل قال معاذ الله قال فهب لي جبتك هذه فأهوى ليخلعها فلما وقعت في رأسه وثب عليه فأسره ثم بعث إلى بني قشير علي وعلي إن قبلت من هبيرة أقل من فدية حاجب إلا أن يأتوني بابن أخي الذي في أيدي بني جعدة فمشت بنو قشير إلى بني جعدة فاستوهبوه منهم فوهبوه لهم فافتدوا به هبيرة","topic":"ذكر النابغة الجعدي ونسبه وأخباره","topicNo":46,"sp":6,"spl":"يوم الفلج — عبد الله بن جعدة السيد المطاع"},
{"id":"b46-12","bab":"الجزء 5","sec":"خبر وحوح أخي النابغة","page":"ج5 ص28","text":"وأما خبر وحوح أخي النابغة الذي تقدم ذكره مع نسب أخيه النابغة فإن أبا عمرو ذكر أن بني كعب أغارت على بني أسد فأصابوا سبيا وأسرى فركبت بنو أسد في آثارهم حتى لحقوهم بالشريف فعطفت بنو عدس بن\nربيعة بن جعدة فذادوا بني أسد حتى قتلوا منهم ثلاثين رجلا وردوهم ولم يظفروا منهم بشيء وتعلقت امرأة من بني أسد بالحكم بن عمرو بن عبد الله ابن جعدة وقد أردفها خلفه فأخذت بضفيرته ومالت به فصرعته فعطف عليه عبد الله بن مالك بن عدس وهو أبو صفوان فضرب يدها بالسيف فقطعها وتخلصه وطعن يومئذ وحوح بن قيس أخو النابغة الجعدي فارتث في معركة القوم فأخذه خالد بن نضلة الأسدي وعطف عليه يومئذ أخوه النابغة فقال له خالد بن نضلة هلم إلي وأنت آمن فقال له النابغة لا حاجة لي في أمانك أنا على فرسي ومعي سلاحي وأصحابي قريب ولكني أوصيك بما في العوسجة يعني أخاه وحوح بن قيس فعدل إليه خالد فأخذه وضمه إليه ومنع من قتله وداواه حتى فدي بعد ذلك قال ففي ذلك يقول مدرك العبسي\n(أقمت على الحفاظ وغاب فرج ... وفي فرج عن الحسب انفراج)\n(كذلك فعلنا وحبال عمي ... وردن بوحوح فلج الفلاج)\nمما قاله النابغة في هذه المفاخرة وغني فيه قوله وقد جمع معه كل ما يغنى فيه من القصيدة\nصوت\n(هل بالديار الغداة من صمم ... أم هل بربع الأنيس من قدم)\n(أم ما تنادي من ماثل درج السيل ... عليه كالحوض منهدم)\n(غراء كالليلة المباركة القمراء ... تهدي أوائل الظلم)\n(أكني بغير اسمها وقد علم الله ... خفيات كل مكتتم)\n(كأن فاها إذا تبسم من ... طيب مشم وطيب مبتسم)\n(يسن بالضرو من براقش أو ... هيلان أو ضامر من العتم)\nروضه من المنسرح وفي الأول والثاني والثالث من الأبيات خفيف ثقيل أول بالخنصر في مجرى البنصر ذكره إسحاق ولم ينسبه إلى أحد وذكر ابن المكي والهشامي أنه لمعبد وأظنه من منحول يحيى\nوذكر حبش أنه لإبراهيم وفي الثالث وما بعده لابن سريج رمل بالبنصر وذكر حبش أن فيها لإسحاق رملا آخر ولابن مسجح فيها ثقيل أول بالبنصر أخبرني علي بن سليمان الأخفش قال أول من سبق إلى الكناية عن اسم من يعني بغيره في الشعر الجعدي فإنه قال\n(أكني بغير اسمها وقد علم الله ... خفيات كل مكتتم)\nسبق الناس جميعا إليه واتبعوه فيه وأحسن من أخذه وألطفه فيه أبو نواس حيث يقول\n(أسأل القادمين من حكمان ... كيف خلفتم أبا عثمان)\n(فيقولون لي جنان كما سرك ... في حالها فسل عن جنان)\n(ما لهم لا يبارك الله فيهم ... كيف لم يغن عندهم كتماني)\nخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثني أبو بكر الباهلي قال حدثني الأصمعي قال\nذكر الفرزدق نابغة بني جعدة فقال كان صاحب خلقان عنده مطرف بألف وخمار بواف يعني درهما","topic":"ذكر النابغة الجعدي ونسبه وأخباره","topicNo":46,"sp":7,"spl":"خبر وحوح أخي النابغة — النابغة وابن الزبير"},
{"id":"b46-13","bab":"الجزء 5","sec":"النابغة وابن الزبير","page":"ج5 ص32","text":"وحدثني خبره مع ابن الزبير جماعة منهم حبيب بن نصر المهلبي عمر بن عبد العزيز بن أحمد والحرمي بن أبي العلاء ووكيع ومحمد بن جرير الطبري حدثنيه من حفظه قالوا حدثنا الزبير بن بكار قال حدثنا أخي هارون بن أبي بكر عن يحيى بن إبراهيم عن سليمان بن محمد بن يحيى بن عروة عن أبيه عن عمه عبد الله بن عروة قال أقحمت السنة نابغة بني جعدة فدخل على ابن الزبير المسجد الحرام فأنشده\n(حكيت لنا الصديق لما وليتنا ... وعمثان والفاروق فارتاح معدم)\n(أتاك أبو ليلى يجوب به الدجى ... دجى الليل جواب الفلاة عثمثم)\n(لتجبر منه جانبا زعزعت به ... صروف الليالي والزمان المصمم)\nفقال له ابن الزبير هون عليك أبا ليلى فإن الشعر أهون وسائلك عندنا أما صفوة مالنا فلآل الزبير وأما عفوته فإن بني أسد بن عبد العزى تشغلها عنك وتيما معها ولكن لك في مال الله حقان حق برؤيتك رسول الله وحق بشركتك أهل الإسلام في فيئهم ثم أخذ بيده فدخل به دار النعم فأعطاه قلائص سبعا وجملا رجيلا وأوقر له الإبل برا وتمرا وثيابا فجعل النابغة يستعجل فيأكل الحب صرفا فقال ابن الزبير ويح أبي ليلى لقد بلغ به الجهد فقال النابغة أشهد أني سمعت رسول الله يقول \" ما وليت قريش فعدلت واسترحمت فرحمت وحدثت فصدقت ووعدت خيرا فأنجزت فأنا والنبيون فراط القاصفين \" وقال الحرمي فراط لها ضمن قال الزبيري كتب يحيى بن معين هذا الحديث عن أخي","topic":"ذكر النابغة الجعدي ونسبه وأخباره","topicNo":46,"sp":7,"spl":"خبر وحوح أخي النابغة — النابغة وابن الزبير"},
{"id":"b46-14","bab":"الجزء 5","sec":"النابغة يهجو أبا موسى الأشعري","page":"ج5 ص33","text":"أخبرني أبو الحسن الأسدي أحمد بن محمد بن عبد الله بن صالح\nوهاشم بن محمد الخزاعي أبو دلف قالا حدثنا الرياشي قال قال أبو سليمان عن الهيثم بن عدي قال رعت بنو عامر بالبصرة في الزرع فبعث أبو موسى الأشعري في طلبهم فتصارخوا يا آل عامر يا آل عامر فخرج النابغة الجعدي ومعه عصبة له فأتي به إلى أبي موسى الأشعري فقال له ما أخرجك قال سمعت داعية قومي قال فضربه أسواطا فقال النابغة\n(رأيت البكر بكر بني ثمود ... وأنت أراك بكر الأشعرينا)\n(فإن يكن ابن عفان أمينا ... فلم يبعث بك البر الأمينا)\n(فيا قبر النبي وصاحبيه ... ألا يا غوثنا لو تسمعونا)\n(ألا صلى إلهكم عليكم ... ولا صلى على الأمراء فينا)\nخبرنا أحمد بن عبد العزيز الجوهري ويحيى بن علي بن يحيى قالا حدثنا عمر بن شبة قال حدثنا بعض أصحابنا عن ابن دأب قال لما خرج علي رضي الله تعالى عنه إلى صفين خرج معه نابغة بني جعدة فساق به يوما فقال\n(قد علم المصران والعراق ... أن عليا فحلها العتاق)\n(أبيض جحجاج له رواق ... وأمه غالى بها الصداق)\n(أكرم من شد به نطاق ... إن الألى جاروك لا أفاقوا)\n(لهم سياق ولكم سياق ... قد علمت ذلكم الرفاق)\n(سقتم إلى نهج الهدىوساقوا ... إلى التي ليس لها عراق)\n(في ملة عادتها النفاق ... )\nلما قدم معاوية بن أبي سفيان الكوفة قام النابغة بين يديه فقال\n(ألم تأت أهل المشرقين رسالتي ... وأي نصيح لا يبيت على عتب)\n(ملكتم فكان الشر آخر عهدكم ... لئن لم تدارككم حلوم بني حرب)\nقد كان معاوية كتب إلى مروان فأخذ أهل النابغة وماله فدخل النابغة على معاوية وعنده عبد الله بن عامر ومروان فأنشده\n(من راكب يأتي ابن هند بحاجتي ... على النأي والأنباء تنمى وتجلب)\n(ويخبر عني ما أقول ابن عامر ... ونعم الفتى يأوي إليه المعصب)\n(فإن تأخذوا أهلي ومالي بظنة ... فإني لحراب الرجال محرب)\n(صبور على ما يكره المرء كله ... سوى الظلم إني إن ظلمت سأغضب)","topic":"ذكر النابغة الجعدي ونسبه وأخباره","topicNo":46,"sp":8,"spl":"النابغة يهجو أبا موسى الأشعري — النابغة وعقال بن خويلد","partial":1},
{"id":"b46-15","bab":"الجزء 5","sec":"النابغة وعقال بن خويلد","page":"ج5 ص36","text":"فالتفت معاوية إلى مروان فقال ما ترى قال أرى ألا ترد عليه شيئا فقال ما أهون والله عليك أن ينجحر هذا في غار ثم يقطع عرضي علي ثم تأخذه العرب فترويه أما والله إن كنت لممن يرويه أردد عليه كل شيء أخذته منه وهذا الشعر يقوله النابغة الجعدي لعقال بن خويلد العقيلي يحذره غب الظلم لما أجار بني وائل بن معن وكانوا قتلوا رجلا من جعدة فحذرهم مثل حرب البسوس إن أقاموا على ذلك فيهم قال أبو عمرو الشيباني كان السبب في قول الجعدي هذه القصيدة أن المنتشر الباهلي خرج فأغار على اليمن ثم رجع مظفرا فوجد بني جعدة قد قتلوا ابنا له يقال له سيدان وكانت باهلة في بني كعب بن ربيعة بن عامر بن صعصعة ثم في بني جعدة فلما أن علم ذلك المنتشر وأتاه الخبر أغار على بني جعدة ثم على بني سبيع في وجهه ذلك فقتل منهم ثلاثة نفر فلما فعل ذلك تصدعت باهلة فلحقت فرقة منهم يقال لهم بنو وائل\nبعقال بن خويلد العقيلي ولحقت فرقة أخرى يقال لهم بنو قتيبة وعليهم حجل الباهلي بيزيد بن عمرو بن الصعق الكلابي فأجارهم يزيد وأجار عقال وائلا فلما رأت ذلك بنو جعدة أرادوا قتالهم فقال لهم عقال لا تقاتلوهم فقد أجرتهم فأما أحد الثلاثة القتلى منكم فهو بالمقتول وأما الآخران فعلي عقلهما فقالوا لا نقبل إلا القتال ولا نريد من وائل غيرا يعني الدية فقال لا تفعلوا فقد أجرت القوم فلم يزل بهم حتى قبلوا الدية وانتقلت وائل إلى قومهم فقال النابغة في ذلك قصيدته التي ذكر فيها عقالا\n(فابلغ عقالا أن غاية داحس ... بكفيك فاستأخر لها أو تقدم)\n(تجير علينا وائلا في دمائنا ... كأنك عما ناب أشياعنا عم)\n(كليب لعمري كان أكثر ناصرا ... وأيسر جرما منك ضرج بالدم)\n(رمى ضرع ناب فاستمر بطعنة ... كحاشية البرد اليماني المسهم)\n(وما يشعر الرمح الأصم كعوبه ... بثروة رهط الأبلخ المتظلم)\n(وقال لجساس أغثني بشربة ... تفضل بها طولا علي وأنعم)\n(فقال تجاوزت الأحص وماءه ... وبطن شبيث وهو ذو مترسم)","topic":"ذكر النابغة الجعدي ونسبه وأخباره","topicNo":46,"sp":8,"spl":"النابغة يهجو أبا موسى الأشعري — النابغة وعقال بن خويلد"},
{"id":"b46-16","bab":"الجزء 5","sec":"حرب بكر وتغلب حرب البسوس","page":"ج5 ص39","text":"وكان السبب في قتل كليب بن ربيعة فيما ذكره أبو عبيدة عن مقاتل الأحول بن سنان بن مرثد بن عبد بن عمرو بن بشر بن عمرو بن مرثد أخي بني قيس بن ثعلبة ونسخت بعضه من رواية الكلبي وأخبرنا به محمد ابن العباس اليزيدي عن عمه عبيد الله عن ابن حبيب عن ابن الأعرابي عن المفضل فجمعت من روايتهم ما احتيج إلى ذكره مختصر اللفظ كامل المعنى أن كليبا كان قد عز وساد في ربيعة فبغى بغيا شديدا وكان هو الذي ينزلهم منازلهم ويرحلهم ولا ينزلون ولا يرحلون إلا بأمره فبلغ من عزه وبغيه أنه اتخذ جرو كلب فكان إذا نزل منزلا به كلأ قذف ذلك الجرو فيه فيعوي فلا يرعى أحد ذلك الكلأ إلا بإذنه وكان يفعل هذا بحياض الماء فلا يردها أحد إلا بإذنه أو من آذن بحرب فضرب به المثل في العز فقيل أعز من كليب وائل وكان يحمي الصيد ويقول صيد ناحية كذا وكذا\nفي جواري فلا يصيد أحد منه شيئا وكان لا يمر بين يديه أحد إذا جلس ولا يحتبي أحد في مجلسه غيره فقتله جساس بن مرة وقال أبو عبيدة قال أبو برزة القيسي وهو من ولد عمرو بن مرثد وكان كليب بن ربيعة ليس على الأرض بكري ولا تغلبي أجار رجلا ولا بعيرا إلى بإذنه ولا يحمي حمى إلا بأمره وكان إذا حمى حمى لا يقرب وكان لمرة بن ذهل بن شيبان بن ثعلبة عشرة بنين جساس أصغرهم وكانت أختهم عند كليب وقال مقاتل وفراس وأم جساس هيلة بنت منقذ بن سليمان بن كعب بن عمرو بن سعد بن زيد مناة ثم خلف عليها سعد ابن ضبيعة بن قيس بن ثعلبة بعد مرة بن ذهل فولدت له مالكا وعوفا وثعلبة قال فراس بن خندق البسوسي فهي أمنا وخالة جساس البسوس وقال أبو برزة البسوسية وهي التي يقال لها أشأم من البسوس فجاءت فنزلت على ابن أختها جساس فكانت جارة لبني مرة ومعها ابن لها ولهم ناقة خوارة من نعم بني سعد ومعها فصيل أخبرني علي بن سليمان قال قال أبو برزة وقد كان كليب قبل\nذلك قال لصاحبته أخت جساس هل تعلمين على الأرض عربيا أمنع مني ذمة فسكتت ثم أعاد عليها الثانية فسكتت ثم أعاد عليها الثالثة فقالت نعم أخي جساس وندمانه ابن عمه عمرو المزدلف بن أبي ربيعة بن ذهل ابن شيبان وزعم مقاتل أن امرأته كانت أخت جساس فبينا هي تغسل رأس كليب وتسرحه ذات يوم إذ قال من أعز وائل فصمتت فأعاد عليها فلما أكثر عليها قالت أخواي جساس وهمام فنزع رأسه من يدها وأخذ القوس فرمى فصيل ناقة البسوس خالة جساس وجارة بني مرة فقتله فأغمضوا على ما فيه وسكتوا على ذلك ثم لقي كليب ابن البسوس فقال ما فعل فصيل ناقتكم قال قتلته وأخليت لنا لبن أمه فأغمضوا على هذه أيضا ثم إن كليبا أعاد على امرأته فقال من أعز وائل فقالت أخواي فأضمرها وأسرها في نفسه وسكت حتى مرت به إبل جساس فرأى الناقة فأنكرها فقال ما هذه الناقة قالوا لخالة جساس قال أو قد بلغ من أمر ابن السعدية أن يجير علي بغير إذني ارم ضرعها يا غلام قال فراس فأخذ القوس فرمى ضرع الناقة فاختلط دمها بلبنها وراحت الرعاة على جساس فأخبروه بالأمر فقال احلبوا لها مكيالي لبن بمحلبها ولا تذكروا لها من هذا شيئا ثم أغمضوا عليها أيضا قال مقاتل حتى أصابتهم سماء فغدا في غبها يتمطر وركب جساس بن مرة وابن عمه عمرو بن الحارث ابن ذهل وقال أبو برزة بل عمرو بن أبي ربيعة وطعن عمرو كليبا فحطم صلبه وقال أبو برزة فسكت جساس حتى ظعن ابنا وائل فمرت بكر ابن وائل على نهي يقال له شبيث فنفاهم كليب عنه وقال لا يذوقون منه","topic":"ذكر النابغة الجعدي ونسبه وأخباره","topicNo":46,"sp":9,"spl":"حرب بكر وتغلب حرب البسوس"},
{"id":"b46-17","bab":"الجزء 5","sec":"حرب بكر وتغلب حرب البسوس","page":"ج5 ص39","text":"قطرة ثم مروا على نهي آخر يقال له الأحص فنفاهم عنه وقال لا يذوقون منه قطرة ثم مروا على بطن الجريب فمنعهم إياه فمضوا حتى نزلوا الذنائب واتبعهم كليب وحيه حتى نزلوا عليه ثم مر عليه جساس وهو واقف على غدير الذنائب فقال طردت أهلنا عن المياه حتى كدت تقتلهم عطشا فقال كليب ما منعناهم من ماء إلا ونحن له شاغلون فمضى جساس ومعه ابن عمه المزدلف وقال بعضهم بل جساس ناداه فقال هذا كفعلك بناقة خالتي فقال له أو قد ذكرتها أما إني لو وجدتها في غير إبل مرة لاستحللت تلك الإبل بها فعطف عليه جساس فرسه فطعنه برمح فأنفذ حضنيه فلما تداءمه الموت قال يا جساس اسقني من الماء قال ما عقلت استسقاءك الماء منذ ولدتك أمك إلا ساعتك هذه قال أبو برزة فعطف عليه المزدلف عمرو بن أبي ربيعة فاحتز رأسه وأما مقاتل فزعم أن عمرو بن الحارث بن ذهل الذي طعنه فقصم صلبه قال وفيه يقول مهلهل\n(قتيل ما قتيل المرء عمرو ... وجساس بن مرة ذو ضرير)\nوقال العباس بن مرداس السلمي يحذر كليب بن عهمة السلمي ثم الظفري لما مات حرب بن أمية وخنقت الجن مرداسا وكانوا شركاء في القرية فجحدهم كليب حظهم منها وسنذكر خبر ذلك في آخر هذه الأخبار إن شاء الله تعالى فحذره غب الظلم فقال\n(أكليب مالك كل يوم ظالما ... والظلم أنكد وجهه ملعون)\n(فافعل بقومك ما أراد بوائل ... يوم الغدير سميك المطعون)\nقال رجل من بني بكر بن وائل في الإسلام وهي تنحل للأعشى\n(ونحن قهرنا تغلب ابنة وائل ... بقتل كليب إذا طغى وتخيلا)\n(أبأناه بالناب التي شق ضرعها ... فأصبح موطوء الحمى متذللا)\nال ومقتل كليب بالذنائب عن يسار فلجة مصعدا إلى مكة وقبره بالذنائب وفيه يقول المهلهل\n(ولو نبش المقابر عن كليب ... فيخبر بالذنائب أي زير)\nال أبو برزة فلما قتله أمال يده بالفرس حتى انتهى إلى أهله قال وتقول أخته حين رأته لأبيها إن ذا لجساس أتى خارجا ركبتاه قال والله ما خرجت ركبتاه إلا لأمر عظيم قال فلما جاء قال ما وراءك يا بني قال ورائي إني قد طعنت طعنة لتشغلن بها شيوخ وائل زمنا قال أقتلت كليبا قال نعم قال وددت أنك وإخوتك كنتم متم قبل هذا ما بي إلا أن تتشاءم بي أبناء وائل وزعم مقاتل أن جساسا قال لأخيه نضلة بن مرة وكان يقال له عضد الحمار\n(وإني قد جنيت عليك حربا ... تغص الشيخ بالماء القراح)\n(مذكرة متى ما يصح عنها ... فتى نشبت بآخر غير صاح)\n(تنكل عن ذباب الغي قوما ... وتدعو آخرين إلى الصلاح)\nأجابه نضلة\n(فإن تك قد جنيت علي حربا ... فلا وان ولا رث السلاح)\nال أبو برزة\nوكان همام بن مرة آخى مهلهلا وعاقده ألا يكتمه شيئا فجاءت إليه أمة له فأسرت إليه قتل جساس كليبا فقال له مهلهل ما قالت فلم يخبره فذكره العهد بينهما فقال أخبرت أن جساسا قتل كليبا فقال است أخيك أضيق من ذلك وزعم مقاتل أن هماما كان آخى مهلهلا وكان عاقده ألا يكتمه شيئا فكانا جالسين فمر جساس يركض به فرسه مخرجا فخذيه فقال همام إن له لأمرا والله ما رأيته كاشفا فخذيه قط في ركض فلم يلبث إلا قليلا حتى جاءته الخادم فسارته أن جساسا قتل كليبا فقال له مهلهل ما أخبرتك قال أخبرتني أن أخي قتل أخاك قال هو أضيق استا من ذلك وتحمل القوم وغدا مهلهل بالخيل وقال المفضل في خبره فلما قتل كليب قالت بنو تغلب بعضهم لبعض لا تعجلوا على إخوتكم حتى تعذروا بينكم وبينهم فانطلق رهط من أشرافهم وذوي أسنانهم حتى أتوا مرة بن ذهل فعظموا ما بينهم وبينه وقالوا له اختر منا خصالا إما أن تدفع إلينا جساسا فنقتله بصاحبنا فلم يظلم من قتل قاتله وإما أن تدفع إلينا هماما وإما أن تقيدنا من نفسك فسكت وقد حضرته وجوه بني بكر بن وائل فقالوا تكلم غير مخذول فقال أما جساس فغلام حديث السن ركب رأسه فهرب حين خاف فلا علم","topic":"ذكر النابغة الجعدي ونسبه وأخباره","topicNo":46,"sp":10,"spl":"حرب بكر وتغلب حرب البسوس"},
{"id":"b46-18","bab":"الجزء 5","sec":"حرب بكر وتغلب حرب البسوس","page":"ج5 ص39","text":"لي به وأما همام فأبو عشرة وأخو عشرة ولو دفعته إليكم لصيح بنوه في وجهي وقالوا دفعت أبانا للقتل بجريرة غيره وأما أنا فلا أتعجل الموت وهل تزيد الخيل على أن تجول جولة فأكون أول قتيل ولكن هل لكم في غير ذلك هؤلاء بني فدونكم أحدهم فاقتلوه به وإن شئتم فلكم ألف ناقة تضمنها لكم بكر بن وائل فغضبوا وقالوا إنا لم نأتك لترذل لنا بنيك ولا لتسومنا اللبن فتفرقوا ووقعت الحرب وتكلم في ذلك عند الحارث بن عباد فقال لا ناقة لي في هذا ولا جمل وهو أول من قالها وأرسلها مثلا قالوا جميعا كانت حربهم أربعين سنة فيهن خمس وقعات مزاحفات وكانت تكون بينهم مغاورات وكان الرجل يلقى الرجل والرجلان الرجلين ونحو هذا وكان أول تلك الأيام يوم غنيزة وهي عند فلجة فتكافؤوا فيه لا لبكر ولا لتغلب وتصديق ذلك قول مهلهل\n(كأنا غدوة وبنى أبينا ... بجنب عنيزة رحيا مدير)\n(ولولا الريح أسمع من بحجر ... صليل البيض تقرع بالذكور)\nفتفرقوا ثم غبروا زمانا ثم التقوا يوم واردات وكان لتغلب على بكر وقتلوا بكرا أشد القتل وقتلوا بجيرا وذلك قول مهلهل\n(فإني قد تركت بواردات ... بجيرا في دم مثل العبير)\n(هتكت به بيوت بني عباد ... وبعض الغشم أشفى للصدور)\nال مقاتل إنه إنما التقط توا وسيجيء حديثه أسفل من هذا التو الفرد يقال وجدته توا أي وحده قال أبو برزة ثم انصرفوا بعد يوم واردات غير بني ثعلبة بن عكابة ورأسوا على أنفسهم الحارث بن عباد فاتبعتهم بنو ثعلبة بن عكابة حتى التقوا بالحنو فظهرت بنو ثعلبة على تغلب","topic":"ذكر النابغة الجعدي ونسبه وأخباره","topicNo":46,"sp":11,"spl":"حرب بكر وتغلب حرب البسوس — يوما القصيبات وقضة"},
{"id":"b46-19","bab":"الجزء 5","sec":"يوما القصيبات وقضة","page":"ج5 ص47","text":"قال مقاتل ثم التقوا يوم بطن السرو وهو يوم القصيبات وربما قبل يوم القصيبة وكان لبني تغلب على بكر حتى ظنت بكر أن سيقتلونها قال مقاتل وقتلوا يومئذ همام بن مرة ثم التقوا يوم قضة وهو يوم التحالق ويوم الثنية ويوم قضة ويوم الفصيل لبكر على تغلب قال أبو برزة اتبعت تغلب بكرا فقطعوا رملات خزازى والرغام ثم مالوا\nلبطن الحمارة فوردت بكر قضة فسقت وأسقت ثم صدرت وحلؤوا تغلب ونهضوا في نجعة يقال لها مويبة لا يجوز فيها إلا بعير بعير فلحق رجل من الأوس بن تغلب بغليم من بني تيم اللات بن ثعلبة يطرد ذودا له فطعن في بطنه بالرمح ثم رفعه فقال تحد بي أم البو على بوك فرآه عوف بن مالك بن ضبيعة بن قيس بن ثعلبة فقال أنفذوا جمل أسماء اينته فإنه أمضى جمالكم وأجودها منفذا فإذا نفذ تبعته النعم فوثب الجمل في المويبة حتى إذا نهض على يديه وارتفعت رجلاه ضرب عرقوبيه وقطع بطان الظعينة فوقع فسد الثنية ثم قال عوف أنا البرك أبرك حيث أدرك فسمي البرك ووقع الناس إلى الأرض لا يرون مجازا وتحالقوا لتعرفهم النساء فقال جحدر بن ضبيعة بن قيس أبو المسامعة واسمه\nربيعة قال وإنما سمي جحدرا لقصره لا تحلقوا رأسي فإني رجل قصير لا تشينوني ولكني أشتريه منكم بأول فارس يطلع عليكم من القوم فطلع ابن عناق فشد عليه فقتله فقال رجل من بكر بن وائل يمدح مسمع بن مالك بذلك\n(يابن الذي لما حلقنا اللمما ... ابتاع منا رأسه تكرما)\n(بفارس أول من تقدما ... )\nقال البكري\n(ومنا الذي فادى من القوم رأسه ... بمستلئم من جمعهم غير أعزلا)\n(فأدى إلينا بزه وسلاحه ... ومنفصلا من عنقه قد تزيلا)\nال وكان جحدر يرتجز يومئذ ويقول\n(ردوا علي الخيل إن ألمت ... إن لم أقاتلهم فجزوا لمتي)\nزعم عامر بن عبد الملك المسمعي أنه لم يقلها وأن صخر بن عمرو السلمي قائلها فقال مسمع كردين كذب عامر وقال البكري\n(ومنا الذي سد الثنية غدوة ... على خلفة لم يبق فيها تحللا)\n(بجهد يمين الله لا يطلعونها ... ولما نقاتل جمعهم حين أسهلا)\nوأما مقاتل فزعم أنهم قالوا اتخذوا علما يعرف به بعضكم بعضا فتحالقوا وفيه يقول طرفة صوت\n(سائلوا عنا الذي يعرفنا ... بقوانا يوم تحلاق اللمم)\n(يوم تبدي البيض عن أسؤقها ... وتلف الخيل أعراج النعم)\nنى في هذين البيتين ابن محرز خفيف ثقيل أول بالوسطى عن الهشامي وذكر أحمد بن المكي أنه لمعبد","topic":"ذكر النابغة الجعدي ونسبه وأخباره","topicNo":46,"sp":11,"spl":"حرب بكر وتغلب حرب البسوس — يوما القصيبات وقضة","partial":1},
{"id":"b46-20","bab":"الجزء 5","sec":"مقتل همام بن مرة","page":"ج5 ص50","text":"وزعم مقاتل أن همام بن مرة بن ذهل بن شيبان لم يزل قائد بكر حتى قتل يوم القصيبات وهو قبل يوم قضة ويوم قضة على أثره وكان من حديث مقتل همام أنه وجد غلاما مطروحا فالتقطه ورباه وسماه ناشرة فكان عنده لقيطا فلما شب تبين أنه من بني تغلب فلما التقوا يوم القصيبات جعل همام يقاتل فم يقاتل فإذا عطش رجع إلى قربة فشرب منها ثم وضع سلاحه فوجد ناشرة من همام غفلة فشد عليه بالعنزة فأقصده فقتله ولحق بقومه\nتغلب فقال باكي همام\n(لقد عيل الأقوام طعنة ناشره ... أناشر لا زالت يمينك آشره)\nم قتل ناشرة رجل من بني يشكر فلما كان يوم قضة وتجمعت إليهم بكر جاء إليهم الفند الزماني أحد بني زمان بن مالك بن صعب بن علي بن بكر بن وائل من اليمامة قال عامر بن عبد الملك المسمعي فرأسوه عليهم فقلت أنا لفراس بن خندق إن عامرا يزعم أن الفند كان رئيس بكر يوم قضة فقال رحم الله أبا عبد الله كان أقل الناس حظا في علم قومه وقال فراس كان رئيس بكر بعد همام الحارث بن عباد قال مقاتل وكان الحارث ابن عباد قد اعتزل يوم قتل كليب وقال لا أنا من هذا ولا ناقتي ولا جملي ولا عدلي وربما قال لست من هذا ولا جملي ولا رحلي وخذل بكرا عن تغلب واستعظم قتل كليب لسؤدده في ناقة فقال سعد بن مالك يحضض الحارث بن عباد\n(يا بؤس للحرب التي ... وضعت أراهط فاستراحوا)\n(والحرب لا يبقى لصاحبها ... التخيل والمراح)\n(إلا الفتى الصبار في النجدات ... والفرس الوقاح)\nفلما أخذ بجير بن الحارث بن عباد توا بواردات وإنما سل ولم يؤخذ في مزاحفة قال له مهلهل من خالك يا غلام قال امرؤ القيس بن أبان التغلبي لمهلهل إني أرى غلاما ليقتلن به رجل لا يسأل عن خاله وربما قال عن حاله قال فكان والله امرؤ القيس هو المقتول به قتله الحارث بن عباد يوم قضة بيده فقتله مهلهل قال فلما قتل مهلهل بجيرا قال بؤبشسع نعل كليب فقال له الغلام إن رضيت بذلك بنو ضبيعة بن قيس رضيت فلما بلغ الحارث قتل بجير ابن أخيه وقال أبو برزة بل بجير بن الحارث بن عباد نفسه قال نعم الغلام غلام أصلح بين ابني وائل وباء بكليب فلما سمعوا قول الحارث قالوا له إن مهلهلا لما قتله قال له بؤ بشسع نعل كليب وقال مهلهل\n(كل قتيل في كليب حلام ... حتى ينال القتل آل همام)\nقال أيضا\n(كل قتيل في كليب غره ... حتى ينال القتل آل مره)\nغضب الحارث عند ذلك فنادى بالرحيل قال مقاتل وقال الحارث ابن عباد\n(قربا مربط النعامة مني ... لقحت حرب وائل عن حيال)\n(لا بجير أغنى قتيلا ولا رهط ... كليب تزاجروا عن ضلال)\n(لم أكن من جناتها علم الله ... وإني بحرها اليوم صال)\nال ولم يصحح عامر ولا مسمع غير هذه الثلاثة الأبيات وزعم أبو برزة قال كان أول فارس لقي مهلهلا يوم واردات بجير بن الحارث بن عباد فقال من خالك يا غلام وبوأ نحوه الرمح فقال له امرؤ القيس بن أبان التغلبي وكان على مقدمتهم في حروبهم مهلا يا مهلهل فإن عم هذا وأهل بيته قد اعتزلوا حربنا ولم يدخلوا في شيء مما نكره ووالله لئن قتلته ليقتلن به رجل لا يسأل عن نسبه فلم يلتفت مهلهل إلى قوله وشد عليه فقتله وقال بؤبشسع نعل كليب فقال الغلام إن رضيت بهذا بنو ثعلبة فقد رضيته قال ثم غبروا زمانا ثم لقي همام بن مرة فقتله أيضا فأتى الحارث ابن عباد فقيل له قتل مهلهل هماما فغضب وقال ردوا الجمال على عكرها الأمر مخلوجة ليس بسكلى وجد في قتالهم قال مقاتل فكان حكم بكر بن وائل يوم قضة الحارث بن عباد وكان الرئيس الفند وكان فارسهم جحدر وكان شاعرهم سعد بن مالك بن ضبيعة وكان الذي سد الثنية عوف بن مالك بن ضبيعة وكان عوف أنبه من أخيه سعد","topic":"ذكر النابغة الجعدي ونسبه وأخباره","topicNo":46,"sp":12,"spl":"مقتل همام بن مرة"},
{"id":"b46-21","bab":"الجزء 5","sec":"المهلهل وأسره ونجاته","page":"ج5 ص54","text":"وقال فراس بن خندق بل كان رئيسهم يوم قضة الحارث بن عباد قال مقاتل فأسر الحارث بن عباد عديا وهو مهلهل بعد انهزام الناس وهو لا يعرفه فقال له دلني على المهلهل قال ولي دمي قال ولك دمك قال ولي ذمتك وذمة أبيك قال نعم ذلك لك قال فأنا مهلهل قال دلني على كفء لبجير قال لا أعلمه إلا امرأ القيس بن أبان هذاك علمه فجز ناصيته وقصد قصد امرئ القيس فشد عليه فقتله فقال الحارث في ذلك\n(لهف نفسي على عدي ولم أعرف ... عديا إذ أمكنتني اليدان)\n(طل من طل في الحروب ولم أوتر ... بجيرا أبأته ابن أبان)\n(فارس يضرب الكتيبة بالسيف ... وتسمو أمامه العينان)\nزعم حجر أن مهلهلا قال لا والله أو يعهد لي غيرك قال الحارث أختر من شئت قال أختار الشيخ القاعد عوف بن محلم قال الحارث يا عوف أجره قال لا حتى يقعد خلفي فأمره فقعد خلفه فقال أنا مهلهل وأما مقاتل فقال إنما أخذه في دور الرحى وحومة القتال ولم يقعد أحد بعد فكيف يقول الشيخ القاعد قال مقاتل وشد عليهم جحدر فاعتوره عمرو وعامر فطعن عمرا بعالية الرمح وطعن عامرا بسافلته\nفقتلهما عداء وجاء ببزهما قال عامر بن عبد الملك المسمعي فحدثني رجل عالم قال سألني الوليد بن يزيد من قتل عمرا وأخاه عامرا قلت جحدر قال صدقت فهل تدري كيف قتلهما قلت نعم قتل عمرا بسنان الرمح وقتل عامرا بزجه قال وقتل جحدر أيضا أبا مكنف قال مقاتل فلما رجع مهلهل بعد الوقعة والأسر إلى أهله جعل النساء والولدان يستخبرونه تسأل المرأة عن زوجها وابنها وأخيها والغلام عن أبيه وأخيه فقال\n(ليس مثلي يخبر الناس عن آبائهم ... قتلوا وينسى القتالا)\n(لم أرم عرصة الكتيبة حتى انتعل ... الورد من دماء نعالا)\n(عرفته رماح بكر فما يأخذن ... إلا لبانه والقذالا)\n(غلبونا ولا محالة يوما ... يقلب الدهر ذاك حالا فحالا)\nم خرج حتى لحق بأرض اليمن فكان في جنب فخطب إليه أحدهم ابنته فأبى أن يفعل فأكرهوه فأنكحها إياه فقال في ذلك مهلهل\n(أنكحها فقدها الأراقم في ... جنب وكان الحباء من أدم)\n(لو بأبانين جاء يخطبها ... ضرج ما أنف خاطب بدم)\n(أصبحت لا منفسا أصبت ولا ... أبت كريما حرا من الندم)\n(هان على تغلب بما لقيت ... أخت بني المالكين من جشم)\n(ليسوا بأكفائنا الكرام ولا ... يغنون من عيلة ولا عدم)\nم إن مهلهلا انحدر فأخذه عمرو بن مالك بن ضبيعة فطلب إليه أخواله بنو يشكر وأم مهلهل المرادة بنت ثعلبة بن جشم بن غبر اليشكرية وأختها منة بنت ثعلبة أم حيي بن وائل وكان المحلل بن ثعلبة خالهما فطلب إلى عمرو أن يدفعه إليه فيكون عنده ففعل فسقاه خمرا فلما طابت نفسه تغنى\n(طفلة ما ابنة المحلل بيضاء ... لعوب لذيذة في العناق)\nتى فرغ من القصيدة فأدى ذلك من سمعه من المهلهل إلى عمرو فحوله إليه واقسم ألا يذوق عنده خمرا ولا ماء ولا لبنا حتى يرد ربيب الهضاب جمل له كان أقل وروده في الصيف الخمس فقالوا له يا خير الفتيان أرسل إلى ربيب فلتؤت به قبل وروده ففعل فأوجره ذنوبا من ماء فلما\nتحلل من يمينه سقاه من ماء الحاضرة وهو أوبأ ماء رأيته فمات فتلك الهضاب التي كان يرعاها ربيب يقال لها هضاب ربيب طالما رعيتهن ورأيتهن قال مقاتل ولم يقاتل معنا من بني يشكر ولا من بني لجيم ولا ذهل ابن ثعلبة غير ناس من بني يشكر وذهل قاتلت بأخرة ثم جاء ناس من بني لجيم يوم قضة مع الفند وفي ذلك يقول سعد بن مالك\n(إن لجيما قد أبت كلها ... أن يرفدونا رجلا واحدا)\n(ويشكر أضحت على نأيها ... لم تسمع الآن لها حامدا)\n(ولا بنو ذهل وقد أصبحوا ... بها حلولا خلفا ماجدا)\n(القائدي الخيل لأرض العدا ... والضاربين الكوكب الوافدا)\nقال البكري\n(وصدت لجيم للبراءة إذ رأت ... أهاضيب موت تمطر الموت معضلا)\n(ويشكر قد مالت قديما وأرتعت ... ومنت بقرباها إليهم لتوصلا)\nقالوا جميعا مات جساس حتف أنفه ولم يقتل قال عامر بن عبد الملك لم يكن بينهم من قتلى تعد ولا تذكر إلا ثمانية نفر من تغلب وأربعة من بكر عددهم مهلهل في شعريه يعني قصيدتيه\n(أليلتنا بذي حسم أنيري ... إذا أنت انقضيت فلا تحوري)\n(فإن يك بالذنائب طال ليلي ... فقد أبكي من الليل القصير)\n(فلو نبش المقابر عن كليب ... فيعلم بالذنائب أي زير)\n(بيوم الشعثمين أقر عينا ... وكيف لقاء من تحت القبور)\n(وإني قد تركت بواردات ... بجيرا في دم مثل العبير)","topic":"ذكر النابغة الجعدي ونسبه وأخباره","topicNo":46,"sp":13,"spl":"المهلهل وأسره ونجاته"},
{"id":"b46-22","bab":"الجزء 5","sec":"المهلهل وأسره ونجاته","page":"ج5 ص54","text":"(هتكت به بيوت بني عباد ... وبعض الغشم أشفى للصدور)\n(على أن ليس يوفي من كليب ... إذا برزت مخبأة الخدور)\n(وهمام بن مرة قد تركنا ... عليه القشعمان من النسور)\n(ينوء بصدره والرمح فيه ... ويخلجه خدب كالبعير)\n(فلولا الريح أسمع من بحجر ... صليل البيض تقرع بالذكور)\n(فدى لبني شقيقة يوم جاؤوا ... كأسد الغاب لجت في الزئير)\n(كأن رماحهم أشطان بئر ... بعيد بين جاليها جرور)\n(غداة كأننا وبني أبينا ... بجنب عنيزة رحيا مدير)\n(تظل الخيل عاكفة عليهم ... كأن الخيل ترحض في غدير)\nهؤلاء أربعة من بني بكر بن وائل وقال أيضا\n(طفلة ما ابنة المحلل بيضاء ... لعوب لذيذة في العناق)\n(فاذهبي ما إليك غير بعيد ... لا يؤاتي العناق من في الوثاق)\n(ضربت نحرها إلي وقالت ... يا عديا لقد وقتك الأواقي)\n(ما أرجي في العيش بعد نداماي ... أراهم سقوا بكأس حلاق)\n(بعد عمرو وعامر وحيي ... وربيع الصدوف وابني عناق)\n(وامرئ القيس ميت يوم أودى ... ثم خلى علي ذات العراقي)\n(وكليب سم الفوارس إذ حم ... رماه الكماة بالإيفاق)\n(إن تحت الأحجار حدا ولينا ... وخصيما ألد ذا معلاق)\n(حية في الوجار أربد لا تنفع ... منه السليم نفثه راق)\nهؤلاء ثمانية من تغلب قال عامر والدليل على أن القتلى كانوا قليلا أن آباء القبائل هم الذين شهدوا تلك الحروب فعدوهم وعدوا بنيهم وبني بنيهم فإن كانوا خمسمائة فقد صدقوا فكم عسى أن يبلغ عدد القتلى والقبائل قال مسمع إن أخي مجنون وكيف يحتج بشعر المهلهل وقد قتل جحدر أبا مكنف يوم قضة فلم يذكره في شعره وقتل اليشكري ناشرة فلم يذكره في الشعر وقتل حبيب يوم واردات وقتل سعد بن مالك يوم قضة ابن القبيحة فلم يذكر فهؤلاء أربعة وقال البكري\n(تركنا حبيبا يوم أرجف جمعه ... صريعا بأعلى واردات مجدلا)\nقال مهلهل أيضا\n(لست أرجو لذة العيش ما ... أزمت أجلاد قد بساقي)\n(جللوني جلد حوب فقد ... جعلوا نفسي عند التراقي)\nقال آخر يفخر بيوم واردات\n(ومهراق الدماء بواردات ... تبيد المخزيات وما تبيد)\nقلت لعامر ما بال مسمع وما احتج به من هؤلاء الأربعة فقال عامر وما أربعة إن كنت أغفلتهم فيما يقولون إنهم قتلوا يوم كذا ثلاثة آلاف ويوم كذا أربعة آلاف والله ما أظن جميع القوم كانوا يومئذ ألفا فهاتوا فعدوا أسماء القبائل وأبناءهم وانزلوا معهم إلى أبناء أبنائهم فكم عسى أن يكونوا","topic":"ذكر النابغة الجعدي ونسبه وأخباره","topicNo":46,"sp":14,"spl":"المهلهل وأسره ونجاته"},
{"id":"b46-23","bab":"الجزء 5","sec":"نسبة ما في هذه الأخبار من الأغاني","page":"ج5 ص61","text":"صوت\n(أزجر العين أن تبكي الطلولا ... أن في الصدر من كليب غليلا)\n(إن في الصدر حاجة لن تقضى ... ما دعا في الغصون داع هديلا)\n(كيف أنساك يا كليب ولما ... أقض حزنا ينوبني وغليلا)\n(أيها القلب أنجز اليوم نحبا ... من بني الحصن إذ غدوا وذحولا)\n(كيف يبكي الطلول من هو رهن ... بطعان الأنام جيلا فجيلا)\n(أنبضوا معجس القسي وأبرقنا ... كما توعد الفحول الفحولا)\n(وصبرنا تحت البوارق حتى ... ركدت فيهم السيوف طويلا)\n(لم يطيقوا أن ينزلوا ونزلنا ... وأخو الحرب من أطاق النزولا)\nلشعر لمهلهل قال أبو عبيدة اسمه عدي وقال يعقوب بن السكيت اسمه امرؤ القيس وهو ابن ربيعة بن الحارث بن زهير بن جشم ابن بكر بن حبيب بن عمرو بن غنم بن تغلب وإنما لقب مهلهلا لطيب شعره ورقته وكان أحد من غني من العرب في شعره وقيل إنه أول من قصد القصائد وقال الغزل فقيل قد هلهل الشعر أي أرقه وهو أول من كذب في شعره وهو خال امرئ القيس بن حجر الكندي وكان فيه خنث ولين وكان كثير المحادثة للنساء فكان كليب يسميه زير النساء فذلك قوله\n(ولو نبش المقابر عن كليب ... فيعلم بالذنائب أي زير)\nلغناء لابن محرز في الأول والثاني من الأبيات ثقيل أول بالسبابة في مجرى\nالوسطى وللغريض فيهما لحن في هذه الطريقة والإصبع والمجرى والذي فيه سجحة منها لابن محرز ولمعبد لحنان أحدهما في الأول والسادس ثقيل أول مطلق في مجرى البنصر والآخر خفيف ثقيل أول بالبنصر ولإبراهيم في الأول والرابع ثقيل أول بالخنصر في مجرى الوسطى ولإسحاق في الأول والثالث ماخوري ولعلويه في الأول والثاني خفيف ثقيل أول بالبنصر ولمالك فيهما خفيف رمل بالسبابة في مجرى الوسطى ولابن سريج في السادس والسابع خفيف رمل بالسبابة في مجرى البنصر ولابن سريج أيضا في الأول والثامن خفيف ثقيل أول بالبنصر وللغريض في الأول والثاني خفيف ثقيل أول بالبنصر وللهذلي في الأول والثاني والسابع خفيف ثقيل أول\nبالوسطى من رواية حماد عن أبيه ولمالك في الأول والثاني والخامس خفيف ثقيل أول بالخنصر في مجرى البنصر عن إسحاق وعمرو بن بانة ومنها صوت\n(ثكلتني عند الثنية أمي ... وأتاها نعي عمي وخالي)\n(إن لم اشف النفوس من حي بكر ... وعدي تطاه بزل الجمال)\nغناه ابن سريج ثقيلا أول بإطلاق الوتر في مجرى الوسطى من رواية إسحاق وغناه الغريض ثقيلا أول بالبنصر على مذهب إسحاق من رواية عمرو ابن بانة ومنها صوت\n(قربا مربط النعامة مني ... لقحت حرب وائل عن حيال)\n(قرباها في مقربات عجال ... عابسات يثبن وثب السعالي)\n(لم أكن من جناتها علم الله ... وإني بحرها اليوم صال)\nالشعر للحارث بن عباد والغناء للغريض ثقيل أول بالبنصر وفيه لحن آخر يقال إنه لابن سريج ومنها صوت\n(يا لبكر أنشروا لي كليبا ... يا لبكر أين أين الفرار)\n(يا لبكر فاظعنوا أو فحلوا ... صرح الشر وبان السرار)\nلشعر لمهلهل والغناء لابن سريج ولحنه من القدر الأوسط من الثقيل الأول بالسبابة في مجرى البنصر من رواية إسحاق وغناه الأبجر خفيف رمل بالوسطى من رواية عمرو ومنها صوت\n(أليلتنا بذي حسم أنيري ... إذا أنت انقضيت فلا تحوري)\n(فإن يك بالذنائب طال ليلي ... فقد أبكي من الليل القصير)\n(كأن الجدي جدي بنات نعش ... يكب على اليدين بمستدير)\n(وتحبوا الشعريان إلى سهيل ... يلوح كقمة الجمل الكبير)\n(فولا الريح أسمع أهل حجر ... صليل البيض تقرع بالذكور)\nلشعر لمهلهل والغناء لابن محرز في الأول والثاني ثقيل أول بالبنصر وله في الأبيات كلها خفيف ثقيل أول مطلق في مجرى الوسطى عن إسحاق جميعا وفي الأبيات كلها على الولاء للأبجر ثاني ثقيل بالوسطى على مذهب إسحاق من رواية عمرو ويقال إن فيها لحنا للغريض أيضا","topic":"ذكر النابغة الجعدي ونسبه وأخباره","topicNo":46,"sp":15,"spl":"نسبة ما في هذه الأخبار من الأغاني"},
{"id":"b46-24","bab":"الجزء 5","sec":"الهجرس بن كليب وخاله جساس","page":"ج5 ص65","text":"أخبرني علي بن سليمان الأخفش قال أخبرنا الحسن بن الحسين السكري قال حدثنا محمد بن حبيب عن ابن الأعرابي عن المفضل عن أبي عبيدة أن آخر من قتل في حرب بكر وتغلب جساس بن مرة بن ذهل بن شيبان وهو قاتل كليب بن ربيعة وكانت أخته تحت كليب فقتله جساس وهي حامل فرجعت إلى أهلها ووقعت الحرب فكان من الفريقين ما كان ثم صاروا إلى الموادعة بعد ما كادت القبيلتان تتفانيان فولدت أخت جساس غلاما فسمته الهجرس ورباه جساس فكان لا يعرف أبا غيره وزوجه\nابنته فوقع بين الهجرس وبين رجل من بني بكر بن وائل كلام فقال له البكري ما أنت بمنته حتى نلحقك بأبيك فأمسك عنه ودخل إلى أمه كئيبا فسألته عما به فأخبرها الخبر فلما أوى إلى فراشه ونام إلى جنب امرأته وضع أنفه بين ثدييها فتنفس تنفسة تنفط ما بين ثدييها من حرارتها فقامت الجارية فزعة قد أقلتها رعدة حتى دخلت على أبيها فقصت عليه قصة الهجرس فقال جساس ثائر ورب الكعبة وبات جساس على مثل الرضف حتى أصبح فأرسل إلى الهجرس فأتاه فقال له إنما أنت ولدي ومني بالمكان الذي قد علمت وقد زوجتك ابنتي وأنت معي وقد كانت الحرب في أبيك زمانا طويلا حتى كدنا نتفانى وقد اصطلحنا وتحاجزنا وقد رأيت أن تدخل فيما دخل فيه الناس من الصلح وأن تنطلق حتى نأخذ عليك مثل ما أخذ علينا وعلى قومنا فقال الهجرس أنا فاعل ولكن مثلي لا يأتي قومه إلا بلأمته وفرسه فحمله جساس على فرس وأعطاه لأمة ودرعا فخرجا حتى أتيا جماعة من قومهما فقص عليهم جساس ما كانوا فيه من البلاء وما صاروا إليه من العافية ثم قال وهذا الفتى ابن أختي قد جاء ليدخل فيما دخلتم فيه ويعقد ما عقدتم فلما قربوا الدم وقاموا إلى العقد أخذ الهجرس\nبوسط رمحه ثم قال وفرسي وأذنيه ورمحي ونصليه وسيفي وغراريه لا يترك الرجل قاتل أبيه وهو ينظر إليه ثم طعن جساسا فقتله ثم لحق بقومه فكان آخر قتيل في بكر بن وائل قال أبو الفرج أخبرني محمد بن الحسن بن دريد قال حدثني عمي عن العباس بن هشام عن أبيه عن الشرقي بن القطامي قال لما قتل جساس بن مرة كليب بن ربيعة وكانت جليلة بنت مرة أخت جساس تحت كليب اجتمع نساء الحي للمأتم فقلن لأخت كليب رحلي جليلة عن مأتمك فإن قيامها فيه شماتة وعار علينا عند العرب فقالت لها يا هذه اخرجي عن مأتمنا فأنت أخت واترنا وشقيقة قاتلنا فخرجت وهي تجر أعطافها فلقيها أبوها مرة فقال لها ما وراءك يا جليلة فقالت ثكل العدد وحزن الأبد وفقد حليل وقتل أخ عن قليل وبين ذين غرس الأحقاد وتفتت الأكباد فقال لها أو يكف ذلك كرم الصفح وإغلاء الديات فقالت جليلة أمنية مخدوع ورب الكعبة أبالبدن تدع لك تغلب دم ربها قال ولما رحلت جليلة قالت أخت كليب رحلة المعتدي وفراق الشامت ويل غدا لآل مرة من الكرة بعد\nالكرة فبلغ قولها جليلة فقالت وكيف تشمت الحرة بهتك سترها وترقب وترها أسعد الله جد أختي أفلا قالت نفرة الحياء وخوف الاعتداء ثم أنشأت تقول\n(يا بنة الأقوام إن شئت فلا ... تعجلي باللوم حتى تسألي)\n(فإذا أنت تبينت الذي ... يوجب اللوم فلومي واعذلي)\n(إن تكن أخت امرئ ليمت على ... شفق منها عليه فافعلي)\n(جل عندي فعل جساس فيا ... حسرتي عما انجلت أو تنجلي)\n(فعل جساس على وجدي به ... قاطع ظهري ومدن أجلي)\n(لو بعين فقئت عيني سوى ... أختها فانفقأت لم أحفل)\n(تحمل العين قذى العين كما ... تحمل الأم أذى ما تفتلي)\n(يا قتيلا قوض الدهر به ... سقف بيتي جميعا من عل)\n(هدم البيت الذي استحدثته ... وانثنى في هدم بيتي الأول)\n(ورماني قتله من كثب ... رمية المصمي به المستأصل)\n(يا نسائي دونكن اليوم قد ... خصني الدهر برزء معضل)\n(خصني قتل كليب بلظى ... من ورائي ولظى مستقبلي)\n(ليس من يبكي ليومين كمن ... إنما يبكي ليوم ينجلي)\n(يشتفي المدرك بالثأر وفي ... دركي ثأري ثكل المثكل)\n(ليته كان دمي فاحتلبوا ... بدلا منه دما من أكحلي)\n(إنني قاتلة مقتولة ... ولعل الله أن يرتاح لي)","topic":"ذكر النابغة الجعدي ونسبه وأخباره","topicNo":46,"sp":16,"spl":"الهجرس بن كليب وخاله جساس"},
{"id":"b47-1","bab":"الجزء 5","sec":"ذكر الهذلي وأخباره","page":"ج5 ص70","text":"أخبرني محمد بن خلف وكيع قال حدثني هارون بن محمد بن عبد الملك قال حدثني حماد بن إسحاق عن أبيه قال الهذليان أخوان يقال لهما سعيد وعبد آل ابنا مسعود فالأكبر منهما يقال له سعيد ويكنى أبا مسعود وأمه امرأة يقال لها أم فيعل وكان كثيرا ما ينسب إليها وكان ينقش الحجارة بأبي قبيس وكان فتيان من قريش يروحون إليه كل عشية فيأتون بطحاء يقال لها بطحاء قريش فيجلسون عليها ويأتيهم فيغني لهم ويكون معهم وقد قيل إن الأكبر هو عبد آل والأصغر سعيد قال هارون وحدثني الزبير بن بكار قال حدثني حمزة بن عتبة اللهبي أن الهذلي كان نقاشا يعمل البرم من حجارة الجبل وكان يكنى أبا\nعبد الرحمن وكان إذا أمسى راح فأشرف على المسجد ثم غنى فلا يلبث أن يرى الجبل كقرص الخبيص صفرة وحمرة من أدرية قريش فيقولون يا أبا عبد الرحمن أعد فيقول أما والله وها هنا حجر أحتاج إليه لم يرد الأبطح فلا فيضعون أيديهم في الحجارة حتى يقطعوها له ويحدروها إلى الأبطح وينزل معهم حتى يجلس على أعظمها حجرا ويغني لهم قال هارون وحدثني حماد بن إسحاق عن أبي مسعود بن أبي جناح قال أخبرني أبو لطيف وعمارة قالا تغنى الهذلي الأكبر وكان من أنفسهم وكان فتيان قريش يروحون كل عشية حتى يأتوا بطحاء يقال لها بطحاء قريش قريبا من داره فيجلسون عليها ويأتيهم فيغنيهم قال وأخبرني ابن أبي طرفة عن الحسن بن عباد الكاتب مولى آل الزبير قال هجم الحارث بن خالد وهو يومئذ أمير مكة على الهذلي وهو مع\nفتيان قريش بالمفجر يغنيهم وعليه جدبة صوف فطرح عليه مقطعات خز فكانت هذه أول ما تحرك لها","topic":"ذكر الهذلي وأخباره","topicNo":47,"sp":0,"spl":"ذكر الهذلي وأخباره — نسبة ما في هذا الخبر من الأصوات"},
{"id":"b47-2","bab":"الجزء 5","sec":"الهذلي يتزوج بنت ابن سريج","page":"ج5 ص72","text":"قال هارون وحدثني حماد عن أبيه قال ذكر ابن جامع عن ابن عباد أن ابن سريج لما حضرته الوفاة نظر إلى ابنته فبكى فقالت له ما يبكيك قال أخشى عليك الضيعة بعدي فقالت له لا تخف فما من غنائك شيء إلا وقد أخذته قال فغنيني فغنته فقال قد طابت نفسي ثم دعا بالهذلي فزوجها منه فأخذ الهذلي غناء أبيها كله عنها فانتحل أكثره فعامة غناء الهذلي لابن سريج مما أخذه عن ابنته وهي زوجته أخبرني إسماعيل بن يونس قال حدثني عمر بن شبة قال حدثني محمد ابن يحيى أبو غسان قال كان الهذلي منزله بمنى وكان فتيان قريش يأتونه فيغنيهم هناك ثم أقبل مرة حتى جلس على جمرة العقبة فغنى هناك فحدره الحارث من منى وكان عاملا على مكة ثم أذن له فرجع إلى منى\nقال هارون وحدثني علي بن محمد النوفلي قال حدثني أبي قال كان الهذلي النقاش يغدو إليه فتيان قريش وقد عمل عمله بالليل ومعهم الطعام والشراب والدراهم فيقولون له غننا فيقول لهم الوظيفة فيقولون قد جئنا بها فيقول الوظيفة الأخرى أنزلوا أحجاري فيلقون ثيابهم ويأتزرون بأزرهم وينقلون الحجارة وينزلونها ثم يجلس على شنخوب من شناخيب الجبل فيجلسون تحته في السهل فيشربون وهو يغنيهم حتى المساء وكانوا كذلك مدة فقال له يوما ثلاثة فتية من قريش قد جاءك كل واحد منا بمثل وظيفتك على الجماعة من غير أن تنقص وظيفتك عليهم وقد اختار كل واحد منا صوتا من غنائك ليجعله حظه اليوم فإن وافقت الجماعة هوانا كان ذلك مشتركا بيننا وإن أبوا غنيت لهم ما أرادوا وجعلت هذه الثلاثة الأصوات لنا بقية يومنا قال هاتوا فاختار أحدهم\n(عفت عرفات فالمصايف من هند ... )\nاختار الآخر\n(ألم بنا طيف الخيال المهجد ... )\nواختار الآخر\n(هجرت سعدى فزادني كلفا ... )\nغناهم إياها فما سمع السامعون شيئا كان أحسن من ذلك فلما أرادوا الانصراف قال لهم إني قد صنعت صوتا البارحة ما سمعه أحد فهل لكم فيه قالوا هاته منعما بذلك فاندفع فغناهم\n(أأن هتفت ورقاء ظلت سفاهة ... تبكي على جمل لورقاء تهتف)\nقالوا أحسنت والله لا جرم لا يكون صبوحنا في غد إلا عليه فعادوا وغناهم إياه وأعطوه وظيفته ولم يزالوا يستعيدونه إياه باقي يومهم","topic":"ذكر الهذلي وأخباره","topicNo":47,"sp":0,"spl":"ذكر الهذلي وأخباره — نسبة ما في هذا الخبر من الأصوات","partial":1},
{"id":"b47-3","bab":"الجزء 5","sec":"نسبة ما في هذا الخبر من الأصوات","page":"ج5 ص74","text":"من ذلك صوت\n(عفت عرفات فالمصايف من هند ... فأوحش ما بين الجريبين فالنهد)\n(وغيرها طول التقادم والبلى ... فليست كما كانت تكون على العهد)\nلشعر للأحوص وقيل إنه لعمر والغناء للهذلي ولحنه من\nالقدر الأوسط من الثقيل الأول بالخنصر في مجرى البنصر ومنها صوت","topic":"ذكر الهذلي وأخباره","topicNo":47,"sp":0,"spl":"ذكر الهذلي وأخباره — نسبة ما في هذا الخبر من الأصوات"},
{"id":"b47-4","bab":"الجزء 5","sec":"من المائة المختارة","page":"ج5 ص75","text":"(ألم بنا طيف الخيال المهجد ... وقد كادت الجوزاء في الجو تصعد)\n(ألم يحيينا ومن دون أهلها ... فياف تغور الريح فيها وتنجد)\nروضه من الطويل لم يقع لنا اسم شاعره ونسبه والغناء للهذلي ثقيل أول بإطلاق الوتر في مجرى البنصر وهو اللحن المختار وفيه ليحيى المكي هزج ولحن الهذلي هذا مما اختير للرشيد والواثق بعده من المائة الصوت المذكورة ومنها صوت\n(هجرت سعدى فزادني كلفا ... هجران سعدى وأزمعت خلفا)\n(وقد على حبها حلفت لها ... لو أن سعدى تصدق الحلفا)\n(ما علق القلب غيرها بشرا ... ولا سواها من معلق عرفا)\n(فلم تجبني وأعرضت صلفا ... وغادرتني بحبها كلفا)\nالغناء للهذلي ثاني ثقيل بالسبابة في مجرى الوسطى أخبرني إسماعيل بن يونس الشيعي قال حدثنا عمر بن شبة عن إسحاق قال زوج ابن سريج لما حضرته الوفاة الهذلي الأكبر بابنته فأخذ عنها أكثر غناء أبيها وادعاه فغلب عليه قال وولدت منه ابنا فلما أيفع جاز يوما بأشعب وهو جالس في فتية من قريش فوثب فحمله على كتفه وجعل يرقصه ويقول هذا ابن دفتي المصحف وهذا ابن مزامير داود فقيل له ويلك ما تقول ومن هذا الصبي فقال أو ما تعرفونه هذا ابن الهذلي من ابنة ابن سريج ولد على عود واستهل بغناء وحنك بملوى وقطعت سرته بوتر وختن بمضراب وذكر يحيى بن علي بن يحيى عن أبيه عن عبد الله بن عيسى الماهاني قال دخلت يوما على إسحاق بن إبراهيم الموصلي في حاجة فرأيت عليه مطرف خز أسود ما رأيت قط أحسن منه فتحدثنا إلى أن أخذنا في أمر المطرف فقال لقد كان لكم أيام حسنة ودولة عجيبة فكيف ترى هذا فقلت له ما رأيت مثله فقال إن قيمته مائة ألف درهم وله حديث عجيب فقلت ما أقومه إلا بنحو مائة دينار فقال إسحاق شربنا يوما من\nالأيام فبت وأنا مثخن فانتبهت لرسول محمد الأمين فدخل علي فقال يقول لك أمير المؤمنين عجل وكان بخيلا على الطعام فكنت آكل قبل أن أذهب إليه فقمت فتسوكت وأصلحت شأني وأعجلني الرسول عن الغداء فقمت معه فدخلت عليه وإبراهيم بن المهدي قاعد عن يمينه وعليه هذا المطرف وجبة خز دكناء فقال لي محمد يا إسحاق أتغديت قلت نعم يا سيدي قال إنك لنهم أهذا وقت غداء فقلت أصبحت يا أمير المؤمنين وبي خمار فكان ذلك مما حداني على الأكل فقال لهم كم شربنا فقالوا ثلاثة أرطال فقال اسقوه إياها فقلت إن رأيت أن تفرق علي فقال يسقى رطلين ورطلا فدفع إلي رطلان فجعلت أشربهما وأنا أتوهم أن نفسي تسيل معهما ثم دفع إلي رطل آخر فشربته فكأن شيئا انجلى عني فقال غنني\n(كليب لعمري كان أكثر ناصرا ... )\nغنيته فقال أحسنت وطرب ثم قام فدخل وكان كثيرا ما يدخل إلى النساء ويدعنا فقمت في إثر قيامه فدعوت غلاما لي فقلت اذهب إلى بيتي وجئني ببزماوردتين ولفهما في منديل واذهب ركضا وعجل\nفمضى الغلام وجاءني بهما فلما وافى الباب ونزل عن دابته انقطع فنفق من شدة ما ركض عليه وأدخل إلي البزماوردتين فأكلتهما ورجعت نفسي إلي وعدت إلى مجلسي فقال لي إبراهيم لي إليك حاجة أحب أن تقضيها لي فقلت إنما أنا عبدك وابن عبدك فقل ما شئت قال تردد علي كليب لعمري وهذا المطرف لك فقلت أنا لا آخذ منك مطرفا على هذا ولكنني أصير إلى منزلك فألقيه على الجواري وأردده عليك مرارا فقال أحب أن تردده علي الساعة وأن تأخذ هذا فإنه من لبسك وهو من حاله كذا وكذا فرددت عليه الصوت مرارا حتى أخذه ثم سمعنا حركة محمد فقمنا حتى جاء وجلس ثم قعدنا فشرب وتحدثنا فغناه إبراهيم كليب لعمري فكأني والله لم أسمعه قبل ذلك حسنا وطرب محمد طربا شديدا وقال أحسنت والله يا غلام عشر بدر لعمي الساعة فجاؤوا بها فقال يا أمير المؤمنين إن لي فيها شريكا قال من هو قال إسحاق قال وكيف فقال إنما أخذته منه لما قمت فقلت أنا ولم أضاقت الأموال على أمير المؤمنين حتى تريد أن تشرك فيما يعطي قال أما أنا فأشركك وأمير المؤمنين أعلم فلما انصرفنا من المجلس أعطاني ثمانين ألفا وأعطاني هذا المطرف فهذا أخذ به مائة ألف درهم وهي قيمته","topic":"ذكر الهذلي وأخباره","topicNo":47,"sp":1,"spl":"من المائة المختارة","partialRef":{"sid":"b45-14","gi":5,"vi":0,"side":0},"partial":1},
{"id":"b48-1","bab":"الجزء 5","sec":"صوت من المائة المختارة","page":"ج5 ص78","text":"من رواية جحظة عن أصحابه\n(علل القوم يشربوا ... كي يلذوا ويطربوا)\n(إنما ضلل الفؤاد ... عزال مربب)\n(فرشته على النمارق ... سعدى وزينب)\n(حال دون الهوى ودون ... سرى الليل مصعب)\n(وسياط على اكف ... رجال تقلب)\nلشعر لعبيد الله بن قيس الرقيات والغناء في اللحن المختار لمالك بن أبي السمح ولحنه من الثقيل الأول بالسبابة في مجرى الوسطى وفيه لإسحاق ثقيل أول مطلق في مجرى البنصر ولابن سريج في الرابع والخامس والأول ثاني ثقيل في مجرى الوسطى ولمعبد في الثاني وما بعده خفيف ثقيل أول بالسبابة في مجرى الوسطى","topic":"ذكر عبيد الله بن قيس الرقيات ونسبه وأخباره","topicNo":48,"sp":0,"spl":"صوت من المائة المختارة — سبب لقبه بالرقيات"},
{"id":"b48-2","bab":"الجزء 5","sec":"ذكر عبيد الله بن قيس الرقيات ونسبه وأخباره","page":"ج5 ص79","text":"هو عبيد الله بن قيس بن شريح بن مالك بن ربيعة بن أهيب بن ضباب بن حجير بن عبد بن معيص بن عامر بن لؤي بن غالب وأمه قتيلة بنة وهب بن عبد الله بن ربيعة بن طريف بن عدي بن سعد بن ليث بن بكر بن عبد مناة بن كنانة أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني محمد ابن محمد بن أبي قلامة العمري قال حدثني محمد بن طلحة قال الزبير وحدثنيه أيضا محمد بن الحسن المخزومي قالا جميعا كان يقال لبني معيص بن عامر بن لؤي وبني محارب بن فهر الأجربان من أهل تهامة وكانا متحالفين وإنما قيل لهما الأجربان من شدة بأسهما وعرهما من ناوأهما كما يعر الجرب","topic":"ذكر عبيد الله بن قيس الرقيات ونسبه وأخباره","topicNo":48,"sp":0,"spl":"صوت من المائة المختارة — سبب لقبه بالرقيات"},
{"id":"b48-3","bab":"الجزء 5","sec":"سبب لقبه بالرقيات","page":"ج5 ص80","text":"وإنما لقب عبيد الله بن قيس الرقيات لأنه شبب بثلاث نسوة سمين جميعا رقية منهن رقيه بنت عبد الواحد بن أبي سعد بن قيس بن وهب بن أهبان بن ضباب بن حجير بن عبد بن معيص بن عامر بن لؤي وابنة عم لها يقال لها\nرقية وامرأة من بني أمية يقال لها رقية وكان هواه في رقية بنت عبد الواحد وكان عبد الواحد فيما أخبرني الحرمي بن أبي العلاء عن الزبير ينزل الرقة وإياه عنى ابن قيس بقوله\n(ما خبر عيش بالجزيرة بعد ما ... عثر الزمان ومات عبد الواحد)\nله في الرقيات عدة أشعار يغنى فيها تذكر بعقب هذا الخبر والأبيات الثانية التي فيها اللحن المختار يقولها في مصعب بن عبد الرحمن بن عوف الزهري وكان صاحب شرطة مروان بن الحكم بالمدينة أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عمي قال لما ولي مروان بن الحكم المدينة ولى مصعب بن عبد الرحمن بن عوف شرطته فقال إني لا أضبط المدينة بحرس المدينة فابغني رجالا من غيرها فأعانه بمائتي رجل من أهل أيلة فضبطها ضبطا شديدا فدخل المسور بن مخرمة على مروان فقال أما ترى ما يشكوه الناس من مصعب فقال\n(ليس بهذا من سياق عتب ... يمشي القطوف وينام الركب)\nقال غير مصعب في هذا الخبر وليس من رواية الحرمي إنه بقي إلى أن ولي عمرو بن سعيد المدينة وخرج الحسين رضي الله تعالى عنه وعبد الله بن الزبير فقال له عمرو اهدم دور بني هاشم وآل الزبير فقال لا أفعل فقال انتفخ سحرك يابن أم حريث ألق سيفنا فألقاه ولحق بابن الزبير وولى عمرو بن سعيد شرطته عمرو بن الزبير بن العوام وأمره بهدم دور بني هاشم وآل الزبير ففعل وبلغ منهم كل مبلغ وهدم دار ابن مطيع التي يقال لها العنقاء وضرب محمد بن المنذر بن الزبير مائة سوط ثم دعا بعروة\nابن الزبير ليضربه فقال له محمد أتضرب عروة فقال نعم يا سبلان إلا أن تحتمل ذلك عنه فقال أنا أحتمله فضربه مائة سوط أخرى ولحق عروة بأخيه وضرب عمرو الناس ضربا شديدا فهربوا منه إلى ابن الزبير وكان المسور بن مخرمة أحد من هرب منه ولما أفضى الأمر إلى ابن الزبير أقاد منه وضربه بالسوط ضربا مبرحا فمات فدفنه في غير مقابر المسلمين وقال للناس فيما ذكر عنه إن عمرا مات مرتدا عن الإسلام","topic":"ذكر عبيد الله بن قيس الرقيات ونسبه وأخباره","topicNo":48,"sp":0,"spl":"صوت من المائة المختارة — سبب لقبه بالرقيات"},
{"id":"b48-4","bab":"الجزء 5","sec":"كان شاعر قريش زبيري الهوى","page":"ج5 ص83","text":"أخبرني الحرمي قال حدثني الزبير قال سألت عمي مصعبا ومحمد بن الضحاك ومحمد بن حسن عن شاعر قريش في الإسلام فكلهم قالوا ابن قيس الرقيات وحكي ذلك عن عدي وعن الضحاك بن عثمان وحكاه محمد بن الحسن عن عثمان بن عبد الرحمن اليربوعي قال الزبير وحدثني بمثله غمامة بن عمرو السهمي عن مسور بن عبد الملك اليربوعي أخبرنا محمد بن العباس اليزيدي والحرمي بن أبي العلاء وغيرهما قالوا حدثنا الزبير بن بكار قال حدثنا عبد الرحمن بن عبد الله الزهري عن عمه محمد ابن عبد العزيز أن ابن قيس الرقيات أتى إلى طلحة بن عبد الله بن عوف الزهري\nفقال له يا عمي إني قد قلت شعرا فاسمعه فإنك ناصح لقومك فإن كان جيدا قلت وإن كان رديئا كففت فقال له أنشد فأنشده قصيدته التي يقول فيها\n(منع اللهو والهوى ... وسرى الليل مصعب)\n(وسياط على أكف ... رجال تقلب)\nقال قل يابن أخي فإنك شاعر وكان عبيد الله بن قيس الرقيات زبيري الهوى وخرج مع مصعب بن الزبير على عبد الملك فلما قتل مصعب وقتل عبد الله هرب فلجأ إلى عبد الله بن جعفر بن أبي طالب فسأل عبد الملك في أمره فأمنه وأخبرنا محمد بن العباس اليزيدي والحرمي بن أبي العلاء وغيرهما قالوا حدثنا الزبيري قال حدثني عبد الله بن البصير البربري مولى قيس بن عبد الله ابن الزبير عن أبيه قال قال عبيد الله بن قيس الرقيات خرجت مع مصعب بن الزبير حين بلغه شخوص عبد الملك بن مروان إليه فلما نزل مصعب بن الزبير بمسكن ورأى معالم الغدر ممن معه دعاني ودعا بمال ومناطق فملأ المناطق من ذلك\nالمال وألبسني منها وقال لي انطلق حيث شئت فإني مقتول فقلت له لا والله لا أريم حتى أرى سبيلك فأقمت معه حتى قتل ثم مضيت إلى الكوفة فأول بيت صرت إليه دخلته فإذا فيه امرأة لها ابنتان كأنهما ظبيتان فرقيت في درجة لها إلى مشربة فقعدت فيها فأمرت لي المرأة بما أحتاج إليه من الطعام والشراب والفرش والماء للوضوء فأقمت كذلك عندها أكثر من حول تقيم لي ما يصلحني وتغدو علي في كل صباح فتسألني بالصباح والحاجة ولا تسألني من أنا ولا أسألها من هي وأنا في ذلك أسمع الصياح في والجعل فلما طال بي المقام وفقدت الصياح في وغرضت بمكاني غدت علي تسألني بالصباح والحاجة فعرفتها أني قد غرضت وأحببت الشخوص إلى أهلي فقالت لي نأتيك بما تحتاج إليه إن شاء الله تعالى فلما أمسيت وضرب الليل بأرواقه رقيت إلي وقالت إذا شئت فنزلت وقد أعدت راحلتين عليهما ما أحتاج إليه ومعهما عبد وأعطت العبد نفقة الطريق وقالت العبد والراحلتان لك فركبت وركب العبد معي حتى طرقت أهل مكة فدققت منزلي فقالوا لي من هذا فقلت عبيد الله بن قيس الرقيات فولولوا وبكوا وقالوا ما فارقنا طلبك إلا في هذا الوقت فأقمت عندهم حتى أسحرت ثم نهضت ومعي العبد حتى قدمت المدينة فجئت عبد الله ابن جعفر بن أبي طالب عند المساء وهو يعشي أصحابه فجلست معهم وجعلت أتعاجم وأقول ياريار ابن طيار فلما خرج أصحابه كشفت له\nعن وجهي فقال ابن قيس فقلت ابن قيس جئتك عائذا بك قال ويحك ما أجدهم في طلبك وأحرصهم على الظفر بك ولكني سأكتب إلى أم البنين بنت عبد العزيز بن مروان فهي زوجة الوليد بن عبد الملك وعبد الملك أرق شيء عليها فكتب إليها يسألها أن تشفع له إلى عمها وكتب إلى أبيها يسأله أن يكتب إليها كتابا يسألها الشفاعة فدخل عليها عبد الملك كما كان يفعل وسألها هل من حاجة فقالت نعم لي حاجة فقال قد قضيت كل حاجة لك إلا ابن قيس الرقيات فقالت لا تستثن علي شيئا فنفح بيده فأصاب خدها فوضعت يدها على خدها فقال لها يابنتي ارفعي يدك فقد قضيت كل حاجة لك وإن كانت ابن قيس الرقيات فقالت إن حاجتي ابن قيس الرقيات تؤمنه فقد كتب إلي أبي يسألني أن أسألك ذلك قال فهو آمن فمريه يحضر مجلسي العشية فحضر ابن قيس وحضر الناس حين بلغهم مجلس عبد الملك فأخر الإذن ثم أذن للناس وأخر إذن ابن قيس الرقيات حتى أخذوا مجالسهم ثم أذن له فلما دخل عليه قال عبد الملك يا أهل الشأم أتعرفون هذا قالوا لا فقال هذا عبيد الله بن قيس الرقيات الذي يقول\n(كيف نومي على الفراش ولما ... تشمل الشأم غارة شعواء)\n(تذهل الشيخ عن بنيه وتبدي ... عن خدام العقيلة العذراء)","topic":"ذكر عبيد الله بن قيس الرقيات ونسبه وأخباره","topicNo":48,"sp":1,"spl":"كان شاعر قريش زبيري الهوى"},
{"id":"b48-5","bab":"الجزء 5","sec":"كان شاعر قريش زبيري الهوى","page":"ج5 ص83","text":"فقالوا يا أمير المؤمنين اسقنا دم هذا المنافق قال الآن وقد أمنته وصار في منزلي وعلى بساطي قد أخرت الإذن له لتقتلوه فلم تفعلوا فاستأذنه ابن قيس الرقيات أن ينشده مديحه فأذن له فأنشده قصيدته التي يقول فيها\n(عاد له من كثيرة الطرب ... فعينه بالدموع تنسكب)\n(كوفية نازح محلتها ... لا أمم دارها ولا صقب)\n(والله ما إن صبت إلي ولا ... إن كان بيني وبينها سبب)\n(إلا الذي أورثت كثيرة في القلب ... وللحب سورة عجب)\nتى قال فيها\n(إن الأعز الذي أبوه أبو العاصي ... عليه الوقار والحجب)\n(يعتدل التاج فوق مفرقه ... على جبين كأنه الذهب)\nقال له عبد الملك يابن قيس تمدحني بالتاج كأني من العجم وتقول في مصعب\n(إنما مصعب شهاب من الله ... تجلت عن وجهه الظلماء)\n(ملكه ملك عزة ليس فيه ... جبروت منه ولا كبرياء)\nما الأمان فقد سبق لك ولكن والله لا تأخذ مع المسلمين عطاء أبدا قال وقال ابن قيس الرقيات لعبد الله بن جعفر ما نفعني أماني\nتركت حيا كميت لا آخذ مع الناس عطاء أبدا فقال له عبد الله بن جعفر كم بلغت من السن قال ستين سنة قال فعمر نفسك قال عشرين سنة من ذي قبل فذلك ثمانون سنة قال كم عطاؤك قال ألفا درهم فأمر له بأربعين ألف درهم وقال ذلك لك علي إلى أن تموت على تعميرك نفسك فعند ذلك قال عبيد الله بن قيس الرقيات يمدح عبد الله بن جعفر\n(تقدت بي الشهباء نحو ابن جعفر ... سواء عليها ليلها ونهارها)\n(تزور امرأ قد يعلم الله أنه ... تجود له كف قليل غرارها)\n(أتيناك نثني بالذي أنت أهله ... عليك كما يثني على الروض جارها)\n(فوالله لولا أن تزور ابن جعفر ... لكان قليلا في دمشق قرارها)\n(إذا مت لم يوصل صديق ولم تقم ... طريق من المعروف أنت منارها)\n(ذكرتك أن فاض الفرات بأرضنا ... وفاض بأعلى الرقتين بحارها)\n(وعندي مما خول الله هجمة ... عطاؤك منها شولها وعشارها)\n(مباركة كانت عطاء مبارك ... تمانح كبراها وتنمي صغارها)\nخبرنا الحرمي بن أبي العلاء قال حدثنا الزبير قال حدثنا مصعب بن عبد الملك قال قال عبد الملك بن مروان لعبيد الله بن قيس الرقيات ويحك يابن قيس أما اتقيت الله حين تقول لابن جعفر\n(تزور امرأ قد يعلم الله أنه ... تجود له كف قليل غرارها)\nلا قلت قد يعلم الناس ولم تقل قد يعلم الله فقال ابن قيس قد والله علمه الله وعلمته أنت وعلمته أنا وعلمه الناس أخبرنا الحسين بن يحيى قال قال حماد بن إسحاق قرأت على أبي أن عبيد الله بن قيس الرقيات منعه عبد الملك بن مروان عطاءه من بيت المال وطلبه ليقتله فاستجار بعبد الله بن جعفر وقصده فألفاه نائما وكان صديقا لسائب خاثر فطلب الإذن على ابن جعفر فتعذر فجاء سائب خاثر ليستأذن له عليه قال سائب فجئت من قبل رجل عبد الله بن جعفر فنبحت نباح الجرو الصغير فانتبه ولم يفتح عينيه وركلني برجله فدرت إلى عند رأسه فنبحت نباح الكلب الهرم فانتبه وفتح عينيه\nفرآني فقال ما لك ويحك فقلت ابن قيس الرقيات بالباب قال ائذن له فأذنت له فدخل إليه فرحب ابن جعفر به وقربه فعرفه ابن قيس خبره فدعا بظبية فيها دنانير وقال عد له منها فجعلت أعد وأترنم وأحسن صوتي بجهدي حتى عددت ثلاثمائة دينار فسكت فقال لي عبد الله ما لك ويلك سكت ما هذا وقت قطع الصوت الحسن فجعلت أعد حتى نفذ ما كان في الظبية وفيها ثمانمائة دينار فدفعتها إليه فلما قبضها قال لابن جعفر اسأل أمير المؤمنين في أمري قال نعم فإذا دخلت إليه معي ودعا بالطعام فكل أكلا فاحشا فركب ابن جعفر فدخل معه إلى عبد الملك فلما قدم الطعام جعل يسيء الأكل فقال عبد الملك لابن جعفر من هذا فقال هذا إنسان لا يجوز إلا أن يكون صادقا إن استبقي وإن قتل كان أكذب الناس قال وكيف ذلك قال لأنه يقول\n(ما نقموا من بني أمية إلا ... أنهم يحلمون إن غضبوا)","topic":"ذكر عبيد الله بن قيس الرقيات ونسبه وأخباره","topicNo":48,"sp":2,"spl":"كان شاعر قريش زبيري الهوى"},
{"id":"b48-6","bab":"الجزء 5","sec":"كان شاعر قريش زبيري الهوى","page":"ج5 ص83","text":"إن قتلته لغضبك عليه أكذبته فيما مدحكم به قال فهو آمن ولكن لا أعطيه عطاء من بيت المال قال ولم وقد وهبته لي فأحب أن تهب لي عطاءه أيضا كما وهبت لي دمه وعفوت لي عن ذنبه قال قد فعلت قال وتعطيه ما فاته من العطاء قال قد فعلت وأمرت له بذلك أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عمي قال كان ابن قيس الرقيات منقطعا إلى ابن جعفر وكان يصله ويقضي عنه دينه ثم استأمن له عبد الملك فأمنه وحرمه عطاءه فأمره عبد الله أن يقدر لنفسه ما يكفيه أيام حياته ففعل ذلك فأعطاه عبد الله ما سأل وعوضه من عطائه أكثر منه ثم جاءت عبد الله صلة من عبد الملك وابن قيس\nغائب فأمر عبد الله خازنه فخبأ له صلته فلما قدم دفعها إليه وأعطاه جارية حسناء فقال ابن قيس\n(إذا زرت عبد الله نفسي فداؤه ... رجعت بفضل من نداه ونائل)\n(وإن غبت عنه كان للود حافظا ... ولم يك عني في المغيب بغافل)\n(تداركني عبد الإله وقد بدت ... لذي الحقد والشنآن مني مقاتلي)\n(فأنقذني من غمرة الموت بعد ما ... رأيت حياض الموت جم المناهل)\n(حباني لما جئته بعطية ... وجارية حسناء ذات خلاخل)","topic":"ذكر عبيد الله بن قيس الرقيات ونسبه وأخباره","topicNo":48,"sp":3,"spl":"كان شاعر قريش زبيري الهوى"},
{"id":"b48-7","bab":"الجزء 5","sec":"نسبة ما في هذه الأخبار من الأغاني","page":"ج5 ص91","text":"منها صوت\n(عاد له من كثيرة الطرب ... فعينه بالدموع تنسكب)\n(كوفية نازح محلتها ... لا أمم دارها ولا صقب)\n(والله ما إن صبت إلي ولا ... يعرف بيني وبينها سبب)\n(إلا الذي أورثت كثيرة في القلب ... وللحب سورة عجب)\nروضه من المنسرح غناه معبد ثقيلا أول بإطلاق الوتر في مجرى الوسطى قوله لا أمم دارها يعني أنها ليست بقريبة ويقال ما كلفتني أمما من الأمر فأفعله أي قريبا من الإمكان ويقال إن فلانا لأمم من أن يكون فعل كذا وكذا قال الشاعر\n(أطرقته أسماء أم حلما ... بل لم تكن من رحالنا أمما)\nي قريبة وقال الراجز\n(كلفها عمرو نقال الضبعان ... ما كلفت من أمم ولا دان)\nقال آخر\n(إنك إن سألت شيئا أمما ... جاء به الكري أو تحبشما)\nالصقب الملاصقة تقول والله ما صاقبت فلانا ولا صاقبني ودار فلان مصاقبة لدار فلان وفي الحديث الجار أحق بصقبه أي بما لاصقه أي إنه أحق بشفعته والسورة شدة الأمر ومنه يقال ساور فلان فلانا وتساور الرجلان إذا تغالبا وتشادا وقيل إن السورة البقية أيضا ومنها صوت\n(ما نقموا من بني أمية ... إلا أنهم يحلمون إن غضبوا)\n(وأنهم سادة الملوك فما ... تصلح إلا عليهم العرب)\nنت في هذين البيتين حبابة وهما من القصيدة التي أولها\n(عاد له من كثيرة الطرب ... )\nال الأصمعي كثيرة هذه امرأة نزل بها بالكوفة فآوته قال ابن\nقيس فأقمت عندها سنة تروح وتغدو علي بما أحتاج إليه ولا تسألني عن حالي ولا نسبي فبينا أنا بعد سنة مشرف من جناح إلى الطريق إذا أنا بمنادي عبد الملك ينادي ببراءة الذمة ممن أصبت عنده فأعلمت المرأة أني راحل فقالت لا يروعنك ما سمعت فإن هذا نداء شائع منذ نزلت بنا فإن أردت المقام ففي الرحب والسعة وإن أردت الانصراف أعلمتني فقلت لها لا بد لي من الانصراف فلما كان الليل قدمت إلي راحلة عليها جميع ما أحتاج إليه في سفري فقلت لها من أنت جعلت فداءك لأكافئك قالت ما فعلت هذا لتكافئني فانصرفت ولا والله ما عرفتها إلا أني سمعتها تدعى باسمها كثيرة فذكرتها في شعري وذكر الزبير بن بكار عن عمه مصعب أن عبد الله بن علي بن عبد الله ابن عباس صاحب بني أمية بنهر أبي فطرس إنما بعثه على قتلهم أنه أنشده بعض الشعراء ذات يوم مديحا مدح به بني هاشم فقال لبعضهم أين هذا مما كنتم تمدحون به فقال هيهات أن يمدح أحد بمثل قول ابن قيس فينا\n(ما نقموا من بني أمية إلا ... أنهم يحلمون إن غضبوا)\nلبيتين فقال له عبد الله بن علي ألا أرى المطمع في الملك في نفسك بعد يا ماص كذا من أمه ثم أوقع بهم أخبرنا محمد بن العباس اليزيدي قال حدثنا أحمد بن زهير قال حدثنا\nالزبير بن بكار قال حدثني عمي عن جدي عبد الله بن مصعب قال اعترض هارون الرشيد قينة فغنت\n(ما نقموا من بني أمية إلا ... أنهم يحلمون إن غضبوا)\nفلما ابتدأت به تغير وجه الرشيد وعلمت أنها قد غلطت وأنها إن مرت فيه قتلت فغنت\n(ما نقموا من بني أمية إلا ... أنهم يجهلون إن غضبوا)\n(وأنهم معدن النفاق فما ... تفسد إلا عليهم العرب)\nقال الرشيد ليحيى بن خالد أسمعت يا أبا علي فقال يا أمير المؤمنين تبتاع وتسنى لها الجائزة ويعجل لها الإذن ليسكن قلبها قال ذلك جزاؤها قومي فأنت مني بحيث تحبين قال فأغمي على الجارية فقال يحيى بن خالد\n(جزيت أمير المؤمنين بأمنها ... من الله جنات تفوز بعدنها)\nمنها\nصوت\n(تقدت بي الشهباء نحو ابن جعفر ... سواء عليها ليلها ونهارها)\n(تزور امرأ قد يعلم الله أنه ... تجود له كف بطيء غرارها)\n(ووالله لولا أن تزور ابن جعفر ... لكان قليلا في دمشق قرارها)\nروضه من الطويل غناه معبد ثاني ثقيل بالبنصر قوله تقدت أي سارت سيرا ليس بعجل ولا مبطئ فيقال تقدى فلان إذا سار سير من لا يخاف فوت مقصده فلم يعجل وقوله بطيء غرارها يعني أن منعها المعروف بطيء وأصل الغرار أن تمنع الناقة درتها ثم يستعار في كل ما أشبه ذلك ومنه قول الراجز\n(إن لكل نهلات شره ... ثم غرارا كغرار الدره)\nقال جميل في مثل ذلك\n(لاحت لعينك من بثينة نار ... فدموع عينك درة وغرار)","topic":"ذكر عبيد الله بن قيس الرقيات ونسبه وأخباره","topicNo":48,"sp":4,"spl":"نسبة ما في هذه الأخبار من الأغاني","partialRef":{"sid":"b48-5","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b48-8","bab":"الجزء 5","sec":"ما عيب عليه في شعره","page":"ج5 ص95","text":"قال الزبير وهذا البيت مما عيب على ابن قيس لأنه نقض صدره بعجزه فقال في أوله إنه سار سيرا بغير عجل ثم قال\n(سواء عليها ليلها ونهارها ... )\nوهذا غاية الدأب في السير فناقض معناه في بيت واحد ومما عيب على ابن قيس الرقيات قوله وفي هذين البيتين غناء\nصوت\n(ترضع شبلين وسط غيلهما ... قد ناهزا للفطام أو فطما)\n(ما مر يوم إلا وعندهما ... لحم رجال أو يولغان دما)\nناه الغريض خفيف ثقيل أول بالوسطى على مذهب إسحاق من رواية عمرو بن بانة وهي قصيدة مدح بها عبد العزيز بن مروان وفيها يقول\n(أعني ابن ليلى عبد العزيز ببابليون ... تغدو جفانه رذما)\n(الواهب النجب والولائد كالغزلان ... والخيل تعلك اللجما)\nوكان قال في قصيدته هذه أو يالغان دما بالألف وكذلك روي عنه ثم غيرته الرواة أخبرني أحمد بن عبيد الله بن عمار قال حدثنا أحمد بن الحارث الخراز قال سمعت ابن الأعرابي يقول سئل يونس عن قول ابن قيس الرقيات\n(ما مر يوم إلا وعندهما ... لحم رجال أو يولغان دما)\nقال يونس يجوز يولغان ولا يجوز يالغان فقيل له فقد قال ذلك ابن قيس الرقيات وهو حجازي فصيح فقال ليس بفصيح ولا ثقة شغل نفسه بالشرب بتكريت أخبرني الحسين بن يحيى قال قال حماد قرأت على أبي أو بلغك أن ابن أبي عتيق أنشد قول ابن قيس\n(سواء عليها ليلها ونهارها ... )\nقال كانت هذه يابن أم فيما أرى عمياء أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عمي مصعب عن جدي عن هشام بن سليمان المخزومي قال قال ابن أبي عتيق لعبيد الله بن قيس وقد مر به فسلم عليه فقال وعليك السلام يا فارس العمياء فقال له ما هذا الاسم الحادث يا أبا محمد بأبي أنت قال أنت سميت نفسك حيث تقول\n(سواء عليها ليلها ونهارها ... )\nفما يستوي الليل والنهار إلا على عمياء قال إنما عنيت التعب قال فبيتك هذا يحتاج إلى ترجمان يترجم عنه ومنها صوت\n(ذكرتك أن فاض الفرات بأرضنا ... وفاضت بأعلى الرقتين بحارها)\n(وحولي مما خول الله هجمة ... عطاؤك منها شولها وعشارها)\n(فجئناك نثني بالذي أنت أهله ... عليك كما أثنى على الروض جارها)\n(إذا مت لم يوصل صديق ولم تقم ... طريق من المعروف أنت منارها)\nلشول النوق التي شالت بأذنابها وكرهت الفحل وذلك حين تلقح واحدتها شائل غناه حكم الوادي ثقيلا أول بالوسطى","topic":"ذكر عبيد الله بن قيس الرقيات ونسبه وأخباره","topicNo":48,"sp":5,"spl":"ما عيب عليه في شعره — رجع الحديث إلى عبيد الله بن قيس الرقيات","partialRef":{"sid":"b48-5","gi":3,"vi":0,"side":1},"partial":1},
{"id":"b48-9","bab":"الجزء 5","sec":"حكم الوادي ودنانير","page":"ج5 ص98","text":"أخبرني إسماعيل بن يونس الشيعي قال حدثنا عمر بن شبة قال حدثنا إسحاق بن إبراهيم قال قال لي أبي قال حكم الوادي دخلت يوما على يحيى بن خالد فقال لي يا أبا يحيى ما رأيك في خمسمائة دينار قد حضرت قلت ومن لي بها قال تلقي لحنك في\nذكرتك أن فاض الفرات بأرضنا\nعلى دنانير فها هي ذه وهذا سلام واقف معك ومخرجها إليك وأنا راكب إلى أمير المؤمنين ولست أنصرف من مجلس المظالم إلى وقت الظهر فكدها فيه فإذا أحكمته فلك خمسمائة فقالت دنانير يا سيدي أبو يحيى يأخذ خمسمائة دينار وينصرف وأنا أبقى معك أقاسيك عمري كله فقال لها إن حفظتيه فلك ألف دينار وقام فمضى فقلت لها يا سيدتي اشغلي نفسك بذا فإنك أنت تهبين لي الخمسمائة الدينار بحفظك إياه وتفوزين بالألف الدينار وإلا بطل هذا فلم أزل معها أكدها ونفسي وتغنيني حتى انصرف يحيى فدعا بماء وطست ثم قال يا أبا يحيى غن الصوت كما كنت تغنيه فقلت هلكت يسمعه مني وليس هو بمن يخفى عليه ثم يسمعه منها فلا يرضاه فلم أجد بدا من الغناء ثم قال غنيه أنت الآن فغنت فقال والله ما أرى إلا خيرا فقلت جعلت فداءك أنا أمضغ هذا منذ أكثر من خمسين سنة كما أمضغ الخبز وهذه أخذته الساعة وهو يذل لها بعدي وتجترئ عليه ويزداد حسنا في صوتها فقال صدقت هات يا سلام خمسمائة دينار ولها ألف دينار ففعل فقالت له وحياتك يا سيدي لأشاطرن أستاذي الألف الدينار قال ذلك إليك ففعلت فانصرفت وقد أخذت بهذا الصوت ألف دينار","topic":"ذكر عبيد الله بن قيس الرقيات ونسبه وأخباره","topicNo":48,"sp":5,"spl":"ما عيب عليه في شعره — رجع الحديث إلى عبيد الله بن قيس الرقيات"},
{"id":"b48-10","bab":"الجزء 5","sec":"رجع الحديث إلى عبيد الله بن قيس الرقيات","page":"ج5 ص99","text":"قال الزبير بن بكار حدثني عبد الله بن النضير عن أبيه أن ابن قيس الرقيات قال في الكوفية التي نزل عليها\n(بانت لتحزننا كثيره ... ولقد تكون لنا أميره)\n(حلت فلاليج السواد ... وحل أهلي بالجزيره)\nال ولقد رحل من عندها وما يتعارفان قال وقال فيها أيضا وفيه لحن من خفيف الثقيل لابن المكي صوت\n(لججت بحبك أهل العراق ... ولولا كثيرة لم تلجج)\n(فليت كثيرة لم تلقني ... كثيرة أخت بني الخزرج)","topic":"ذكر عبيد الله بن قيس الرقيات ونسبه وأخباره","topicNo":48,"sp":5,"spl":"ما عيب عليه في شعره — رجع الحديث إلى عبيد الله بن قيس الرقيات"},
{"id":"b48-11","bab":"الجزء 5","sec":"ابن قيس الرقيات وسعيد بن المسيب","page":"ج5 ص100","text":"أخبرنا الحرمي قال حدثنا الزبير بن بكار قال حدثني عبد الله بن عاصم القحطاني قال حدثني أبي عن عبد الرحيم بن حرملة قال كنت عند سعيد بن المسيب فجاء ابن قيس الرقيات فهش وقال مرحبا بظفر من أظفار العشيرة ما أحدثت بعدي قال قد قلت أبياتا وأستفتيك في بيت منها فاسمعها قال هات فأنشده\n(هل للديار بأهلها علم ... أم هل تبين فينطق الرسم)\n(قالت رقية فيم تصرمنا ... أرقي ليس لوجهك الصرم)\n(تخطو بخلخالين حشوهما ... ساقان مار عليهما اللحم)\n(يا صاح هل أبكاك موقفنا ... أم هل علينا في البكا إثم)\nقال سعيد لا والله ما أبكاني قال ابن قيس الرقيات\n(بل ما بكاؤك منزلا خلقا ... قفرا يلوح كأنه الوشم)\nقال سعيد اعتذر الرجل ثم أنشد\n(أتلبث في تكريت لا في عشيرة ... شهود ولا السلطان منك قريب)\n(وأنت امرؤ للحزم عندك منزل ... وللدين والإسلام منك نصيب)\nفقال سعيد لا مقام على ذلك فاخرج منها قال قد فعلت قال قد أصبت أصاب الله بك","topic":"ذكر عبيد الله بن قيس الرقيات ونسبه وأخباره","topicNo":48,"sp":6,"spl":"ابن قيس الرقيات وسعيد بن المسيب — ابن قيس الرقيات وحمزة بن عبد الله بن الزبير"},
{"id":"b48-12","bab":"الجزء 5","sec":"نسبة ما في هذا الخبر من الغناء","page":"ج5 ص100","text":"صوت\n(قامت بخلخالين حشوهما ... ساقان مار عليهما اللحم)\n(يا صاح هل أبكاك موقفنا ... أم هل علينا في البكا إثم)\nنى فيهما ابن سريج رملا بالبنصر","topic":"ذكر عبيد الله بن قيس الرقيات ونسبه وأخباره","topicNo":48,"sp":6,"spl":"ابن قيس الرقيات وسعيد بن المسيب — ابن قيس الرقيات وحمزة بن عبد الله بن الزبير"},
{"id":"b48-13","bab":"الجزء 5","sec":"ابن قيس الرقيات وعمر بن أبي ربيعة","page":"ج5 ص101","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثنا محمد بن عبد الله البكري وهارون بن أبي بكر عن عبد الجبار بن سعيد المساحقي عن أبيه عن سعيد بن مسلم بن وهب مولى بني عامر بن لؤي عن أبيه قال\nدخلت مسجد رسول الله مع نوفل بن مساحق وإنه لمعتمد على يدي إذ مررنا بسعيد بن المسيب في مجلسه فسلمنا عليه فرد سلامنا ثم قال لنوفل يا أبا سعيد من أشعر أصاحبنا أم صاحبكم يعني عبيد الله ابن قيس الرقيات أو عمر بن أبي ربيعة فقال نوفل حين يقولان ماذا فقال حين يقول صاحبنا\n(خليلي ما بال المطي كأنما ... نراها على الأدبار بالقوم تنكص)\n(وقد أبعد الحادي سراهن وانتحى ... بهن فما يألو عجول مقلص)\n(وقد قطعت أعناقهن صبابة ... فأنفسنا مما تكلف شخص)\n(يزدن بنا قربا فيزداد شوقنا ... إذا زاد طول العهد والبعد ينقص)\nيقول صاحبكم ما شئت قال فقال له نوفل صاحبكم أشهر بالقول في الغزل أمتع الله بك وصاحبنا أكثر أفانين شعر قال صدقت فلما انقضى ما بينهما من ذكر الشعر جعل سعيد يستغفر الله ويعقد بيده ويعده بالخمس كلها حتى وفى مائة قال البكري في حديثه عن عبد الجبار فقال مسلم بن وهب فلما فارقناه قلت لنوفل أتراه استغفر الله من إنشاده الشعر في مسجد رسول الله قال كلا هو كثير الإنشاد والاستنشاد للشعر ولكني أحسبه للفخر بصاحبه","topic":"ذكر عبيد الله بن قيس الرقيات ونسبه وأخباره","topicNo":48,"sp":6,"spl":"ابن قيس الرقيات وسعيد بن المسيب — ابن قيس الرقيات وحمزة بن عبد الله بن الزبير"},
{"id":"b48-14","bab":"الجزء 5","sec":"ابن قيس الرقيات وحمزة بن عبد الله بن الزبير","page":"ج5 ص102","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير قال حدثنا محمد بن الضحاك عن أبيه قال استأذن عبيد الله بن قيس الرقيات على حمزة بن عبد الله بن الزبير فقالت له الجارية ليس عليه إذن الآن فقال أما إنه لو علم بمكاني ما احتجب عني قال فدخلت الجارية على حمزة فأخبرته فقال ينبغي أن يكون هذا ابن قيس الرقيات ائذني له فأذنت له فقال مرحبا بك يابن قيس هل من حاجة نزعت بك قال نعم زوجت بنين لي ثلاثة ببنات أخ لي ثلاث وزوجت ثلاثة من بني أخ لي بثلاث بنات لي قال فلبنيك الثلاثة أربعمائة دينار أربعمائة دينار ولبني أخيك الثلاثة أربعمائة دينار أربعمائة دينار ولبناتك الثلاث ثلاثمائة دينار ثلاثمائة دينار ولبنات أخيك الثلاث ثلاثمائة دينار ثلاثمائة دينار هل بقيت لك من حاجة يابن قيس قال لا والله إلا مؤونة السفر فأمر له بما يصلحه لسفره حتى رقاع أخفاف الإبل","topic":"ذكر عبيد الله بن قيس الرقيات ونسبه وأخباره","topicNo":48,"sp":6,"spl":"ابن قيس الرقيات وسعيد بن المسيب — ابن قيس الرقيات وحمزة بن عبد الله بن الزبير"},
{"id":"b48-15","bab":"الجزء 5","sec":"ذكر ما قاله ابن قيس الرقيات وغني فيه","page":"ج5 ص103","text":"صوت\n(أمست رقية دونها البشر ... فالرقة السوداء فالغمر)\nغناه يونس ثقيلا أول بالوسطى وفيه لعزة الميلاء ثاني ثقيل ومنها صوت\n(رقي بعيشكم لا تهجرينا ... ومنينا المنى ثم امطلينا)\n(عدينا في غد ما شئت إنا ... نحب وإن مطلت الواعدينا)\n(أغرك أنني لا صبر عندي ... على هجر وأنك تصبرينا)\n(ويوم تبعتكم وتركت أهلي ... حنين العود يتبع القرينا)\nروضه من الوافر غناه ابن محرز ثاني ثقيل بالسبابة في مجرى الوسطى ومنها صوت\n(رقية تيمت قلبي ... فواكبدي من الحب)\n(نهاني إخوتي عنها ... وما بالقلب من عتب)\nغناه مالك ثاني ثقيل أول بالبنصر على مذهب إسحاق من رواية عمرو ابن بانة وقد ذكرت بذل أن فيه لابن المكي لحنا","topic":"ذكر عبيد الله بن قيس الرقيات ونسبه وأخباره","topicNo":48,"sp":7,"spl":"ذكر ما قاله ابن قيس الرقيات وغني فيه — تشبيبه برقية بنت عبد الواحد"},
{"id":"b48-16","bab":"الجزء 5","sec":"رأي ابن أبي عتيق في شعره","page":"ج5 ص105","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير قال حدثني سعيد بن عمرو بن الزبير قال حدثني إبراهيم بن عبد الله قال أنشد كثير ابن أبي عتيق كلمته التي يقول فيها\n(ولست براض من خليل بنائل ... قليل ولا أرضى له بقليل)\nقال له هذا كلام مكافىء ليس بعاشق القرشيان أقنع وأصدق منك ابن أبي ربيعة حيث يقول\n(ليت حظي كلحظة العين منها ... وكثير منها القليل المهنا)\nوقوله أيضا\n(فعدي نائلا وإن لم تنيلي ... إنه يقنع المحب الرجاء)\nابن قيس الرقيات حيث يقول\n(رقي بعيشكم لا تهجرينا ... ومنينا المنى ثم امطلينا)\n(عدينا في غد ما شئت إنا ... نحب وإن مطلت الواعدينا)\n(فإما تنجزي عدتي وإما ... نعيش بما نؤمل منك حينا)\nال فذكرت ذلك لأبي السائب المخزومي ومعه ابن المولى فقال صدق ابن أبي عتيق وفقه الله ألا قال المديون كثير كما قال هذا حيث يقول\n(وأبكي فلا ليلى بكت من صبابة ... لباك ولا ليلى لذي الود تبذل)\n(وأخنع بالعتبى إذا كنت مذنبا ... وإن أذنبت كنت الذي أتنصل)","topic":"ذكر عبيد الله بن قيس الرقيات ونسبه وأخباره","topicNo":48,"sp":7,"spl":"ذكر ما قاله ابن قيس الرقيات وغني فيه — تشبيبه برقية بنت عبد الواحد"},
{"id":"b48-17","bab":"الجزء 5","sec":"تشبيبه برقية بنت عبد الواحد","page":"ج5 ص106","text":"أخبرني الحرمي قال حدثنا الزبير قال سمعت عبيدة بن أشعب بن جبير قال حدثني أبي قال حدثني فند مولى عائشة بنت سعد بن أبي وقاص قال حجت رقية بنت عبد الواحد بن أبي سعد العامرية فكنت آتيها وأحدثها فتستظرف حديثي وتضحك مني فطافت ليلة بالبيت ثم أهوت لتستلم الركن الأسود وقبلته وقد طفت مع عبيد الله بن قيس الرقيات فصادف فراغنا فراغها ولم أشعر بها فأهوى ابن قيس يستلم الركن الأسود ويقبله فصادفها قد سبقت إليه فنفحته بردنها فارتدع وقال لي من هذه فقلت أو لا تعرفها هذه رقية بنت عبد الواحد بن أبي سعد فعند ذلك قال\n(من عذيري ممن يضن بمبذول لغيري علي عند الطواف ... )\nريد أنها تقبل الحجر الأسود وتضن عنه بقبلتها وقال في ذلك\n(حدثوني هل على رجل ... عاشق في قبلة حرج)\nوفيه غناء ينسب بعد هذا الخبر قال ولما نفحته بردنها فاحت منه رائحة المسك حتى عجب من في المسجد وكأنما فتحت بين أهل المسجد لطيمة عطار فسبح من حول البيت قال وقال فند فقلت بعد انصرافها لابن قيس هل وجدت رائحة ردنها لشيء طيبا فعند ذلك قال أبياته التي يقول فيها صوت\n(سائلا فندا خليلي ... كيف أردان رقيه)\n(إنني علقت خودا ... ذات دل بختريه)\nناه فند ولحنه ثقيل أول بالبنصر عن حبش","topic":"ذكر عبيد الله بن قيس الرقيات ونسبه وأخباره","topicNo":48,"sp":7,"spl":"ذكر ما قاله ابن قيس الرقيات وغني فيه — تشبيبه برقية بنت عبد الواحد","partial":1},
{"id":"b48-18","bab":"الجزء 5","sec":"نسبة هذا الصوت الذي في الخبر المتقدم وخبره وهو أيضا مما قاله ابن قيس","page":"ج5 ص107","text":"في رقية\nصوت\n(حب ذاك الدل والغنج ... والتي في عينها دعج)\n(والتي إن حدثت كذبت ... والتي في وعدها خلج)\n(وترى في البيت صورتها ... مثلما في البيعة السرج)\n(خبروني هل على رجل ... عاشق في قبلة خرج)\nلشعر لابن قيس الرقيات يقوله في رقية بنت عبد الواحد والغناء\nلمالك خفيف ثقيل أول مطلق في مجرى البنصر وفيه خفيف ثقيل آخر لابن محرز من رواية عمرو بن بانة وقيل بل هو هذا أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني سليمان بن عياش السعدي قال حدثني سائب راوية كثير قال كان كثير مديونا فقال لي يوما ونحن بالمدينة اذهب بنا إلى ابن أبي عتيق نتحدث عنده قال فذهبت إليه معه فاستنشده ابن أبي عتيق فأنشده قوله\n(أبائنة سعدى نعم ستبين ... )\nتى بلغ إلى قوله\n(وأخلفن ميعادي وخن أمانتي ... وليس لمن خان الأمانة دين)\nقال له ابن أبي عتيق أعلى الأمانة تبعتها فانكف واستغضب نفسه وصاح وقال\n(كذبن صفاء الود يوم محله ... وأنكدنني من وعدهن ديون)\nقال له ابن أبي عتيق ويلك هذا أملح لهن وأدعى للقلوب إليهن سيدك ابن قيس الرقيات كان أعلم منك وأوضع للصواب موضعه فيهن أما سمعت قوله\n(حب ذاك الدل والغنج ... والتي في عينها دعج)\n(والتي إن حدثت كذبت ... والتي في وعدها خلج)\n(وترى في البيت صورتها ... مثلما في البيعة السرج)\n(خبروني هل على رجل ... عاشق في قبلة حرج)\nال فسكن كثير واستحلى ذلك وقال لا إن شاء الله فضحك ابن أبي عتيق حتى ذهب به\nأخبرنا الحرمي قال حدثنا الزبير قال حدثنا عبد الرحمن بن غرير الزهري قال أنشدت أبا السائب المخزومي قول ابن قيس الرقيات صوت\n(قد أتانا من آل سعدى رسول ... حبذا ما يقول لي وأقول)\n(من فتاة كأنها قرن شمس ... ضاق عنها دمالج وحجول)\n(حبذا ليلتي بمزة كلب ... غال عني بها الكوانين غول)\nفقال لي يابن الأمير ما تراه كان يقول وتقول فقلت\n(حديثا كما يسري الندى لو سمعته ... شفاك من ادواء كثير وأسقما)\nطرب وقال بأبي أنت وأمي ما زلت أحبك ولقد أضعف حبي إياك حين تفهم عني هذا الفهم غنى في هذه الأبيات ابن سريج ثقيلا أول بالوسطى ولمالك فيها ثاني ثقيل كلاهما عن الهشامي أخبرني محمد بن جعفر الصيدلاني النحوي صهر المبرد قال حدثني طلحة بن عبد الله أبو إسحاق الطلحي قال حدثنا الزبير بن بكار قال حدثني عبد الله بن محمد بن عبد الله بن عمرو بن عثمان بن عفان قال أنشد أشعب بن جبير أبي أبيات عبيد الله بن قيس الرقيات التي يقول فيها\n(قد أتانا من آل سعدى رسول ... حبذا ما يقول لي وأقول)\nفقال أبي ويحك يا أشعب ما تراه قال وقالت له فقال\n(حديثا لو أن اللحم يصلى بحره ... غريضا أتى أصحابه وهو منضج)\nكر شوقا ووصف توقا ووعد ووفى والتقيا بمزة كلب فشفى واشتفى فذلك قوله\n(حبذا ليلتي بمزة كلب ... غال عني بها الكوانين غول)\nقال له إنك لعلامة بهذه الأحوال قال أجل بأبي أنت فاسأل عالما عن علمه ومما في المائة الصوت المختارة من شعر عبيد الله بن قيس الرقيات","topic":"ذكر عبيد الله بن قيس الرقيات ونسبه وأخباره","topicNo":48,"sp":8,"spl":"نسبة هذا الصوت الذي في الخبر المتقدم وخبره وهو أيضا مما قاله ابن قيس","partial":1},
{"id":"b49-1","bab":"الجزء 5","sec":"صوت من المائة المختارة","page":"ج5 ص110","text":"(يا قلب ويحك لا تذهب بك الحرق ... إن الألى كنت تهواهم قد انطلقوا)\nوذكر أنه لوضاح وقد أخرج في وضع آخر","topic":"ذكر مالك بن أبي السمح وأخباره ونسبه","topicNo":49,"sp":0,"spl":"صوت من المائة المختارة — ذكر مالك بن أبي السمح وأخباره ونسبه"},
{"id":"b49-2","bab":"الجزء 5","sec":"ذكر مالك بن أبي السمح وأخباره ونسبه","page":"ج5 ص111","text":"هو مالك بن أبي السمح واسم أبي السمح جابر بن ثعلبة الطائي أحد بني ثعل ثم أحد بني عمرو بن درماء ويكنى أبا الوليد وأمه قرشية من بني مخزوم وقيل بل أم أبيه منهم وهو الصحيح وقال ابن الكلبي هو مالك بن أبي السمح بن سليمان بن أوس بن سماك بن سعد بن أوس بن عمرو بن درماء أحد بني ثعل وأم أبيه بنت مدرك بن عوف بن عبيد بن عمرو بن مخزوم وكان أبوه منقطعا إلى عبد الله ابن جعفر بن أبي طالب ويتيما في حجره أوصى به أبوه إليه فكان ابن جعفر يكفله ويمونه وأدخله وسائر إخوته في دعوة بني هاشم فهم معهم إلى اليوم وكان أحول طويلا أحنى قال الوليد بن يزيد فيه يعارض الحسين بن عبد الله بن عبيد الله بن العباس بن عبد المطلب في قوله فيه\n(أبيض كالبدر أو كما يلمع السارق ... في حالك من الظلم)\nفقال له الوليد بل أنت\n(أحول كالقرد أو كما يرقب السارق ... في حالك من الظلم)","topic":"ذكر مالك بن أبي السمح وأخباره ونسبه","topicNo":49,"sp":0,"spl":"صوت من المائة المختارة — ذكر مالك بن أبي السمح وأخباره ونسبه"},
{"id":"b49-3","bab":"الجزء 5","sec":"أساتذته في الغناء وموته","page":"ج5 ص112","text":"وأخذ الغناء عن جميلة ومعبد وعمر حتى أدرك الدولة العباسية وكان منقطعا إلى بني سليمان بن علي ومات في خلافة أبي جعفر المنصور أخبرني الحسين بن يحيى قال نسخت من كتاب حماد قرأت على أبي أن السبب في انقطاع أبي السمح إلى ابن جعفر أن السنة أقحمت طيئا فكان ثعلبة جد مالك أحدهم فولد أبو السمح بالمدينة وكان صديقا\nللحسين بن عبد الله الهاشمي وكان سبب ذلك مودة كانت بينه وبين آل شعيب السهميين فلما تزوج حسين عابدة بنت شعيب السهمية خاصمهم بسببها وكان جد مالك معه وعونا له مع من عاونه فنشبت بذلك حال بينه وبين بني هاشم حتى ولد مالك في دورهم فصارت دعوته فيهم أخبرني الحسين بن يحيى قال قال حماد قرأت على أبي وعمر مالك حتى أدرك دولة بني العباس وقدم على سليمان بن علي بالبصرة فمت إليه بخؤولته في قريش ودعوته لبني هاشم وانقطاعه إلى ابن جعفر فعجل له سليمان صلته وكساه وكتب له بأوساق من تمر أخبرني جعفر بن قدامة قال حدثني ميمون بن هارون قال حدثني القاسم بن يوسف قال أخبرني الورداني قال كان مالك بن أبي السمح المغني من طيىء فأصابتهم حطمة في بلادهم بالجبلين فقدمت به أمه وبإخوة له وأخوات أيتام لا شيء لهم فكان يسأل الناس على باب حمزة بن عبد الله بن الزبير وكان معبد منقطعا\nإلى حمزة يكون عنده في كل يوم يغنيه فسمع مالك غناءه فأعجبه واشتهاه فكان لا يفارق باب حمزة يسمع غناء معبد إلى الليل فلا يطوف بالمدينة ولا يطلب من أحد شيئا ولا يريم موضعه فينصرف إلى أمه ولم يكتسب شيئا فتضربه وهو مع ذلك يترنم بألحان معبد ويؤديها دورا دورا في مواضع صيحاته وإسجاحاته ونبراته نغما بغير لفظ ولا رواية شيء من الشعر وجعل حمزة كلما غدا وراح رآه ملازما لبابه فقال لغلامه يوما أدخل هذا الغلام الأعرابي إلي فأدخله فقال له من أنت فقال أنا غلام من طيىء أصابتنا حطمة بالجبلين فحطتنا إليكم ومعي أم لي وإخوة وإني لزمت بابك فسمعت من دارك صوتا أعجبني فلزمت بابك من أجله قال فهل تعرف منه شيئا قال أعرف لحنه كله ولا أعرف الشعر فقال إن كنت صادقا إنك لفهم ودعا بمعبد فأمره أن يغنى صوتا فغناه ثم قال لمالك هل تستطيع أن تقوله قال نعم قال هاته فاندفع فغناه فأدى نغمه بغير شعر يؤدي مداته ولياته وعطفاته ونبراته وتعليقاته لا يخرم حرفا فقال لمعبد خذ هذا الغلام إليك وخرجه فليكونن له شأن قال معبد ولم أفعل ذلك قال لتكون محاسنه منسوبة إليك وإلا عدل إلى غيرك فكانت محاسنه منسوبة إليه فقال صدق الأمير وأنا أفعل ما أمرتني به ثم قال حمزة لمالك كيف وجدت ملازمتك لبابنا قال أرأيت لو قلت فيك غير الذي أنت له مستحق من الباطل أكنت ترضى بذلك قال لا قال وكذلك لا يسرك أن تحمد بما لم تفعل قال نعم قال فوالله ما شبعت على بابك شبعة قط ولا انقلبت منه إلى أهل بخير فأمر له ولأمه ولإخوته بمنزل وأجرى لهم رزقا وكسوة وأمر لهم بخادم يخدمهم وعبد يسقيهم الماء وأجلس مالكا معه في مجالسه وأمر معبدا أن يطارحه فلم ينشب أن مهر\nوحذق وكان ذلك بعقب مقتل هدبة بن خشرم فخرج مالك يوما فسمع امرأة تنوح على زيادة الذي قتله هدبة بن خشرم بشعر أخي زيادة\n(أبعد الذي بالنعف نعف كويكب ... رهينة رمس ذي تراب وجندل)\n(أذكر بالبقيا على من أصابني ... وبقياي أني جاهد غير مؤتلي)\n(فلا يدعني قومي لزيد بن مالك ... لئن لم أعجل ضربة أو أعجل)\n(وإلا أنل ثأري من اليوم أو غد ... بني عمنا فالدهر ذو متطول)\n(أنختم علينا كلكل الحرب مرة ... فنحن منيخوها عليكم بكلكل)\nغني في هذا الشعر لحنين أحدهما نحا فيه نحو المرأة في نوحها ورققه وأصلحه وزاد فيه والآخر نحا فيه نحو معبد في غنائه ثم دخل على حمزة فقال له أيها الأمير إني قد صنعت غناء في شعر سمعت بعض أهل المدينة ينشده وقد أعجبني فإن أذن الأمير غنيته فيه قال هاته فغناه","topic":"ذكر مالك بن أبي السمح وأخباره ونسبه","topicNo":49,"sp":1,"spl":"أساتذته في الغناء وموته"},
{"id":"b49-4","bab":"الجزء 5","sec":"أساتذته في الغناء وموته","page":"ج5 ص112","text":"اللحن الذي نحا فيه نحو معبد فطرب حمزة وقال له أحسنت يا غلام هذا الغناء غناء معبد وطريقته فقال لا تعجل أيها الأمير واسمع مني شيئا ليس من غناء معبد ولا طريقته قال هات فغناه اللحن الذي تشبه فيه بنوح المرأة فطرب حمزة حتى ألقى عليه حلة كانت عليه قيمتها مائتا دينار ودخل معبد فرأى حلة حمزة عليه فأنكرها وعلم حمزة بذلك فأخبر معبدا بالسبب وأمر مالكا فغناه الصوتين فغضب معبد لما سمع الصوت الأول وقال قد كرهت أن آخذ هذا الغلام فيتعلم غنائي فيدعيه لنفسه فقال له حمزة لا تعجل واسمع غناء صنعه ليس من شأنك ولا غنائك وأمره أن يغني الصوت الآخر فغناه فأطرق معبد فقال له حمزة والله لو انفرد بهذا لضاهاك ثم يتزايد على الأيام وكلما كبر وزاد شخت أنت ونقصت فلأن يكون منسوبا إليك أجمل فقال له معبد وهو منكسر صدق الأمير فأمر حمزة لمعبد بخلعة من ثيابه وجائزة حتى سكن وطابت نفسه فقام مالك على رجله فقبل رأس معبد وقال له يا أبا عباد أساءك ما سمعت مني والله لا أغني لنفسي شيئا أبدا ما دمت حيا وإن غلبتني نفسي فغنيت في شعر استحسنته لا نسبته إلا إليك فطب نفسا وارض عني فقال له معبد أو تفعل هذا وتفي به قال إي والله وأزيد فكان مالك بعد ذلك إذا غنى صوتا وسئل عنه قال هذا لمعبد ما غنيت لنفسي شيئا قط وإنما آخذ غناء معبد فأنقله إلى الأشعار وأحسنه وأزيد فيه وأنقص منه أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه قال حدثنا الحسن بن عتبة اللهبي عن عبد الرحمن بن محمد بن عبيد الله أحد بني الحارث بن عبد المطلب قال خرجت من مكة أريد العراق فحملت معي مالك بن أبي السمح من\nالمدينة وذلك في أيام أبي العباس السفاح فكان إذا كانت عشية الخميس قال لنا يا معشر الرفقة إن الليلة ليلة الجمعة وأنا أعلم أنكم تسألوني الغناء وعلي وعلي إن غنيت ليلة الجمعة فإن أردتم شيئا فالساعة اقترحوا ما أحببتم فنسأله فيغنينا حتى إذا كادت الشمس أن تغيب طرب ثم صاح الحريق في دار شلمغان ثم يمر في الغناء فما يكون في ليلة أكثر غناء منه في تلك الليلة بعد الأيمان المغلظة","topic":"ذكر مالك بن أبي السمح وأخباره ونسبه","topicNo":49,"sp":2,"spl":"أساتذته في الغناء وموته"},
{"id":"b49-5","bab":"الجزء 5","sec":"مالك بن أبي السمح وسليمان بن علي","page":"ج5 ص117","text":"أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه قال كان سليمان بن علي يسمع من مالك بن أبي السمح بالسراة لأنه كان إذا قدم الشأم على الوليد بن يزيد عدل إليهم في بدأته وعودته لانقطاعه إليهم فيبرونه ويصلونه فلما أفضى إليهم الأمر رأى سليمان مالكا على باب ابنه جعفر فقال له يا بني لقد رأيت ببابك أشبه الناس بمالك فقال له جعفر ومن مالك يوهمه أنه لا يعرفه فتغافل عنه سليمان لئلا ينبهه عليه فيطلبه وتوهم أنه لم يعرفه ولا سمع غناءه قال حماد وحدثني أبي عن جدي إبراهيم أنه أخبره أنه رأى مالكا بالبصرة على باب جعفر بن سليمان أو أخيه محمد ولم يعرفه فسأل عنه بعد ذلك فعرفه وقد كان خرج عن البصرة قال فما لي حسرة مثل حسرتي بأني ما سمعت غناءه أخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة قال حدثنا أبو غسان محمد بن يحيى قال\nكان مالك بن أبي السمح يتيما في حجر عبد الله بن جعفر وكان أبوه أبو السمح صار إلى عبد الله بن جعفر انقطع إليه فلما احتضر أوصى بمالك إليه فكلفه وعاله ورباه وأدخله في دعوة بني هاشم فهو فيهم إلى اليوم ثم خطب حسين بن عبد الله بن عبيد الله بن العباس العابدة بنت شعيب بن محمد بن عبد الله بن عمرو بن العاص فمنعه بعض أهلها منها وخطبها لنفسه فعاون مالك حسينا وكانت العابدة تستنصحه وكانت بين أبيها شعيب وبينه مودة فأجابت حسينا وتزوجته فانقطع مالك إلى حسين فلما أفضى الأمر إلى بني هاشم قدم البصرة على سليمان بن علي فلما دخل إليه مت بصحبته عبد الله بن جعفر ودعوته في بني هاشم وانقطاعه إلى حسين فقال له سليمان أنا عارف بكل ما قلته يا مالك ولكنك كما تعلم وأخاف أن تفسد علي أولادي وأنا واصلك ومعطيك ما تريد وجاعل لك شيئا أبعث به إليك ما دمت حيا في كل عام على أن تخرج عن البصرة وترجع إلى بلدك قال أفعل جعلني الله فداك فأمر له بجائزة وكسوة وحمله وزوده إلى المدينة أخبرني عمي الحسن بن محمد قال حدثنا هارون بن محمد بن عبد الملك قال حدثني محمد بن هارون بن جناح قال أخبرني يعقوب بن إبراهيم الكوفي عمن أخبره قال دخلت المدينة حاجا فدخلت الحمام فبينا أنا فيه إذ دخل صاحب الحمام فغسله ونظفه ثم دخل شيخ أعمى له هيئة مؤتزر بمنديل أبيض فلما جلس خرجت إلى صاحب الحمام فقلت له من هذا الشيخ قال هذا مالك بن أبي السمح المغني فدخلت عليه فقلت له يا عماه من أحسن الناس غناء فقال يابن أخي على الخبير سقطت أحسن الناس غناء أحسنهم صوتا\nأخبرني عمي قال حدثني أبو أيوب المديني قال حدثني أبو يحيى العبادي عن إسحاق قال كان فتية من قريش جلوسا في مجلس فمر بهم مالك بن أبي السمح فقال بعضهم لبعض لو سألنا مالكا فغنانا صوتا فقام إليه بعضهم فسأله النزول عندهم فعدل إليهم فسألوه أن يغنيهم فقال نعم والله بالحب والكرامة ثم اندفع يغني أوقع بالمقرعة على قربوس سرجه فرفع صوته فلم يقدر ثم خفضه فلم يقدر فجعل يبكي ويقول واشباباه أخبرني عمي قال حدثني هارون بن محمد عن الزبير بن بكار عن عمه عن جده أنه كان في هؤلاء الفتية الذين كانوا سألوه الغناء وذكر باقي الخبر مثل ما ذكره إسحاق","topic":"ذكر مالك بن أبي السمح وأخباره ونسبه","topicNo":49,"sp":3,"spl":"مالك بن أبي السمح وسليمان بن علي"},
{"id":"b49-6","bab":"الجزء 5","sec":"مالك وعجاجة المخنث","page":"ج5 ص119","text":"أخبرني عمي قال حدثني أبو أيوب المديني قال حدثني عبد الرحمن ابن أخي الأصمعي عن عمه قال حدثني صالح بن أبي الصقر قال قدم مالك بن أبي السمح المغني البصرة فلقيه عجاجة المخنث وكان أشهر من بها من المخنثين وقال له فديتك يا أبا الوليد إني كنت أحب أن ألقاك وأن أعرض عليك صوتا من غنائك أخذته عن بعض المخنثين فإن رأيت أن تنزل عندي فعلت فنزل مالك عنده فبسط له المخنث جرد قطيفة كانت عنده فجلس ثم أخذ عجاجة الدف فغنى\n(حب إن الخمار كان عليها ... شاهدا يوم زارت الجوشنيه)\n(قد سبته بدلها حين جاءت ... تتهادى في مشية بختريه)\nفجعل مالك يقول له ويلك من قال هذا لعنة الله ويحك من غنى هذا قبحه الله ويحك من روى عني هذا أخزاه الله ثم قام فركب وهو يضحك عجبا من عجاجة أخبرني محمد بن خلف بن المرزبان قال أخبرني حماد بن إسحاق عن أبيه عن ابن جناح قال حدثني مصعب بن عثمان قال حدثني عبد الله بن محمد بن يحيى بن عروة بن الزبير قال حدثني مالك بن أبي السمح قال قدمنا على يزيد بن عبد الملك أول قدومنا عليه مع معبد وابن عائشة فغنيناه ليلة فأطربناه فأمر لكل واحد منا بألف دينار وكتب لنا بها إلى كاتبه فغدونا عليه بالكتاب فلما رآه أنكره وقال أيؤمر لمثلكم بألف دينار ألف دينار لا والله ولا حبا ولا كرامة فرجعنا إلى يزيد فأخبرناه بمقالته وكررنا عليه فقال كأنه استنكر ذلك فقلنا نعم فقال مثله والله يستنكره ودعاه فلما حضر ورآنا عنده استأمره فيها فأطرق مستحييا وقال له إني قد قلتها لهم ولا يجمل أن أرجع عما قلت ولكن قطعها\nعليهم قال مالك فمات والله يزيد وقد بقي لكل واحد منا أربعمائة دينار أخبرني الحسين بن يحيى قال نسخت من كتاب حماد قال قرأت على أبي وحدثنا الحسن بن محمد قال لما انهزم عبد الله بن علي من أبي مسلم قدم البصرة وكان عند سليمان بن علي وكان مالك بن أبي السمح يومئذ بها فاستزاره جعفر ومحمد فزارهما وغناهما مالك في جوف الليل في دار سليمان بن علي وبلغ الخبر سليمان فدخل عليهم فعذل جعفرا ومحمدا وقال نحن نتوقع الطامة الكبرى وأنتم تسمعون الغناء فقالا ألا تجلس وتسمع ففعل فغناهم مالك صوت\n(ما كنت أول من خاس الزمان به ... قد كنت ذا نجدة أخشى وذا باس)\n(أبلغ أبا معبد عني وإخوته ... شوقي إليهم وأحزاني ووسواسي)\nخرج وتركهم ولم ينكر عليهم شيئا","topic":"ذكر مالك بن أبي السمح وأخباره ونسبه","topicNo":49,"sp":4,"spl":"مالك وعجاجة المخنث — الحسين بن عبد الله يمدح مالكا"},
{"id":"b49-7","bab":"الجزء 5","sec":"الحسين بن عبد الله يمدح مالكا","page":"ج5 ص121","text":"وفي مالك بن أبي السمح يقول الحسين بن عبد الله بن عبيد الله بن العباس صوت\n(لا عيش إلا بمالك بن أبي السمح ... فلا تلحني ولا تلم)\n(أبيض كالبدر أو كما يلمع البارق ... في حالك من الظلم)\n(من ليس يعصيك إن رشدت ولا ... يهتك حق الإسلام والحرم)\n(يصيب من لذة الكريم ولا ... يجهل آي الترخيص في اللمم)\n(يارب ليل لنا كحاشية البرد ... ويوم كذاك لم يدم)\n(نعمت فيه ومالك بن أبي السمح ... الكريم الأخلاق والشيم)\nناه مالك في الأول والثاني والثالث رملا بالبنصر في مجراها فيقال إن مالكا قال له لا والله ولا إن غويت أيضا أعصيك ذكر ذلك الزبير عن عمه مصعب ويقال إنه قال هذه المقالة للوليد بن يزيد فسر بذلك وأجزل صلته","topic":"ذكر مالك بن أبي السمح وأخباره ونسبه","topicNo":49,"sp":4,"spl":"مالك وعجاجة المخنث — الحسين بن عبد الله يمدح مالكا"},
{"id":"b49-8","bab":"الجزء 5","sec":"غناؤه الوليد بن يزيد","page":"ج5 ص122","text":"أخبرني الحسين بن يحيى قال نسخت من كتاب حماد قال حدثني أبي قال قال ابن الكلبي قال الوليد بن يزيد لمعبد قد آذتني ولولتك هذه وقال لابن عائشة قد آذاني استهلالك هذا فانظر لي رجلا يكون مذهبه متوسطا بين مذهبيكما فقالا له مالك بن أبي السمح فكتب في إشخاصه إليه وسائر مغني الحجاز المذكورين فلما قدم مالك على الوليد بن يزيد فيمن معه من المغنين نزل على الغمر بن يزيد فأدخله على الوليد فغناه فلم يعجبه فلما انصرف الغمر قال له إن أمير المؤمنين لم يعجبه شيء من غنائك فقال له\nجعلني الله فداك اطلب لي الإذن عليه مرة واحدة فإن أعجبه شيء مما أغنيه وإلا انصرفت إلى بلادي فلما جلس الوليد في مجلس اللهو ذكره الغمر وطلب له الإذن وقال له إنه هابك فحضر قال فأذن له فبعث إليه فأمر مالك الغلام فسقاه ثلاث صراحيات صرفا فخرج حتى دخل عليه يخطر في مشيته وقال غير ابن الكلبي إنه قال لفراش للوليد اسقني عسا من شراب ولك دينار فسقاه إياه وأعطاه الدينار ثم قال له زدني آخر فأزيدك آخر ففعل حتى شرب ثلاثة ثم دخل على الوليد يخطر في مشيته فلما بلغ باب المجلس وقف ولم يسلم وأخذ بحلقة الباب فقعقعها ثم رفع صوته فغنى\n(لا عيش إلا بمالك بن أبي السمح ... فلا تلحني ولا تلم)\nطرب الوليد ورفع يديه حتى بدا إبطاه إليه مادا لهما وقام فاعتنقه قائما وقال له ادن يابن أخي فدنا حتى اعتنقه ثم أخذ في صوته ذلك فلم يزالوا فيه أياما وأجزل صلته حين أراد الانصراف قال ولما أتى مالك على قوله\n(أبيض كالسيف أو كما يلمع البارق ... في حالك من الظلم)\nال له الوليد\n(أحول كالقرد أو كما يرقب السارق ... في حالك من الظلم)","topic":"ذكر مالك بن أبي السمح وأخباره ونسبه","topicNo":49,"sp":5,"spl":"غناؤه الوليد بن يزيد — مالك يأخذ غناء الناس وأصواتهم"},
{"id":"b49-9","bab":"الجزء 5","sec":"مالك يأخذ غناء الناس وأصواتهم","page":"ج5 ص124","text":"وكان مالك طويلا أجنى فيه حول وقد قال قوم إن مالكا لم يصنع لحنا قط غير هذا أعني لا عيش إلا بمالك بن أبي السمح وإنه كان يأخذ غناء الناس فيزيد فيه وينقص منه وينسبه الناس إليه وكان إسحاق ينكر ذلك غاية الإنكار ويقول غناء مالك كله مذهب واحد لا تباين فيه ولو كان كما يقول الناس لاختلف غناؤه وإنما كان إذا غنى ألحان معبد الطوال خففها وحذف بعض نغمها وقال أطاله معبد ومططه وحذفته أنا وحسنته فأما ألا يكون صنع شيئا فلا أخبرني الحسين بن يحيى قال نسخت من كتاب حماد قرأت على أبي وذكر بكار بن النبال أن الوليد قال لمالك هل تصنع الغناء قال لا ولكني أزيد فيه وأنقص منه فقال له فأنت المحلي إذا قال إسحاق وذكر الحسن بن عتبة اللهبي عن عبد الرحمن بن محمد بن عبد الله الهاشمي الحارثي الذي يقال له سنابل وفيه يقول الشاعر\n(فإن هي ضنت عنك أو حيل دونها ... فدعها وقل في ابن الكرام سنابل)\nال خرجت من مكة أريد أبا العباس أمير المؤمنين فمررت على المدينة فحملت معي مالك بن أبي السمح فسألته يوما عن بعض ما ينسب إليه من الغناء فقال يا أبا الفضل عليه وعليه إن كان غنى صوتا قط ولكني آخذه وأحسنه وأهيئه وأطيبه فأصيب ويخطئون فينسب إلي قال إسحاق وليس الأمر هكذا لمالك صنعة كثيرة حسنة وصنعته تجري في أسلوب واحد ويشبه بعضها بعضا ولو كان كما قيل لاختلف غناؤه وقد قيل إن مالكا كان ينتفي من الصنعة لأن أكثر الأشراف هناك كانوا ينكرون\nعليه فكان يتبذل به عند من يراه وينكره عند من يذمه لمحله في بني هاشم وأخبرني بخبر سنابل هذا محمد بن مزيد قال حدثنا الزبير بن بكار قال حدثني حمزة بن عتبة اللهبي عن سنابل فذكر الخبر وخالف ما رواه إسحاق أن الحسن بن عتبة حدثه وحكاه عن حمزة بن عتبة أخيه أخبرني الحسين بن يحيى عن حماد عن أبيه عن هشام بن الكلبي عن أبيه عن محمد بن يزيد الليثي قال سئل مالك بن أبي السمح عن صنعته في\n(لاح بالدير من أمامة نار ... )\nقال أخذته والله من خربنده بالشأم يسوق أحمرة فكان يترنم بهذا اللحن بلا كلام فأخذته فكسوته هذا الشعر أخبرني الحسين بن يحيى عن حماد عن أبيه قال نزل مالك بن أبي السمح عند رجل بمكة مخزومي وكان له غلام حائك فأتاه آت فقال أما سمعت غناء غلامك الحائك قال لا أويغني قال نعم بشعر لأبي دهبل الجمحي فبعث إليه فأتاه فقال تغنه فقال ما أحسن ذاك إلا على حفي فخرج مولاه ومعه مالك إلى بيته فلما جلس على حفه تغنى\n(تطاول هذا الليل ما يتبلج ... )\nأخذه مالك عنه وغناه فنسبه الناس إليه وكان يقول والله ما غنيته قط ولا غناه إلا الحائك","topic":"ذكر مالك بن أبي السمح وأخباره ونسبه","topicNo":49,"sp":5,"spl":"غناؤه الوليد بن يزيد — مالك يأخذ غناء الناس وأصواتهم","partial":1},
{"id":"b49-10","bab":"الجزء 5","sec":"نسبة هذين الصوتين","page":"ج5 ص126","text":"صوت\n(لاح بالدير من أمامة نار ... لمحب له بيثرب دار)\n(قد تراها ولو تشاء من القرب ... لأغناك عن نداها السرار)\nلشعر للأحوص ويقال إنه لعبد الرحمن بن حسان بن ثابت والغناء لمالك بن أبي السمح ثقيل أول بإطلاق الوتر في مجرى البنصر وفيه لحن لمعبد ذكره إسحاق صوت\n(تطاول هذا الليل ما يتبلج ... وأعيت غواشي سكرتي ما تفرج)\n(أبيت بهم ما أنام كأنما ... خلال ضلوعي جمرة تتوهج)\n(فطورا أمني النفس من تكتم المنى ... وطورا إذا ما لج بي الحب أنشج)\nعروضه من الطويل الشعر لأبي دهبل والغناء لمالك بن أبي السمح\nثقيل أول بالبنصر على مذهب إسحاق من رواية عمرو بن بانة أخبرني الحسين بن يحيى عن حماد عن أبيه عن جده قال قال ابن عائشة حضرت الوليد بن يزيد يوم قتل وكان معنا مالك بن أبي السمح وكان من أحمق الناس فلما قتل الوليد قال اهرب بنا فقلت وما يريدون منا قال وما يؤمنك أن يأخذوا رأسينا فيجعلوا رأسه بينهما ليحسنوا أمرهم بذلك قال ابن عائشة فما رأيت منه عقلا قط قبل ذلك اليوم أخبرني محمد بن خلف وكيع قال قال الزبير بن بكار حدثتني ظبية قالت رأيت مالك بن أي السمح وهو على منامته يلقي على ابنه وقد كبر وانقطع صوت\n(اعتاد هذا القلب بلباله ... إذ قربت للبين أجماله)\n(خود إذا قامت إلى خدرها ... قامت قطوف المشي مكساله)\n(تفتر عن ذي أشر بارد ... عذب إذا ما ذيق سلساله)\nلشعر لعمر بن أبي ربيعة ولمالك بن أبي السمح فيه ثلاثة ألحان خفيف ثقيل مطلق في مجرى الوسطى وثقيل أول بالوسطى في مجراها جميعا عن إسحاق وخفيف رمل بالوسطى عن عمرو بن بانة وقيل إنه\nلابن سريج وفيه رمل ينسب إلى ابن جامع وابن سريج","topic":"ذكر مالك بن أبي السمح وأخباره ونسبه","topicNo":49,"sp":6,"spl":"نسبة هذين الصوتين — شعر في رثائه"},
{"id":"b49-11","bab":"الجزء 5","sec":"شعر في رثائه","page":"ج5 ص127","text":"أخبرني وكيع قال حدثني حماد بن إسحاق عن أبيه قال قال أبو عبيدة سمعت منشدا ينشد لنفسه يرثي مالكا بهذه القصيدة\n(يا مال إني قضت نفسي عليك وما ... بيني وبينك من قربى ولا رحم)\n(إلا الذي لك في قلبي خصصت به ... من المودة في ستر وفي كرم)\nال إسحاق قال أبو عبيدة هو مالك بن أبي السمح انقضت أخباره","topic":"ذكر مالك بن أبي السمح وأخباره ونسبه","topicNo":49,"sp":6,"spl":"نسبة هذين الصوتين — شعر في رثائه"},
{"id":"b50-1","bab":"الجزء 5","sec":"صوت من المائة المختارة","page":"ج5 ص128","text":"من رواية هارون بن الحسن بن سهل وابن المكي وأبي العبيس ومن روى جحظة عنه\n(فإلا تجللها يعالوك فوقها ... وكيف توقى ظهر ما أنت راكبه)\n(هم قتلوه كي يكونوا مكانه ... كما غدرت يوما بكسرى مرازبه)\n(بني هاشم ردوا سلاح ابن أختكم ... ولا تنهبوه لا تحل مناهبه)\nروضه من الطويل البيت الأول من الشعر لرجل من بني نهد\nجاهلي وباقي الأبيات للوليد بن عقبة بن أبي معيط والغناء لابن محرز ولحنه من الثقيل الأول بإطلاق الوتر في مجرى البنصر عن يونس وإسحاق وهو اللحن المختار وفيه للغريض ثقيل أول بالسبابة في مجرى البنصر عن إسحاق وفيه لمعبد ثقيل أول آخر مطلق في مجرى الوسطى عن عمرو وعن الهشامي وفيه لسلسل في الثاني والثالث ثقيل أول بالبنصر عن حبش وفيه لعطرد خفيف ثقيل","topic":"خبر النهدي في هذا الشعر وخبر الوليد بن عقبة وقد مضى نسبه في أول الكتاب","topicNo":50,"sp":0,"spl":"صوت من المائة المختارة"},
{"id":"b50-2","bab":"الجزء 5","sec":"خبر النهدي في هذا الشعر وخبر الوليد بن عقبة وقد مضى نسبه في أول الكتاب","page":"ج5 ص130","text":"أخبرني محمد بن الحسن بن دريد قال أخبرني عمي عن ابن الكلبي عن أبيه عن عبد الرحمن المدائني وكان عالما بأخبار قومه قال وحدثنيه أبو مسكين أيضا قالا كان الحارث بن مارية الغساني الجفني مكرما لزهير بن جناب الكلبي ينادمه ويحادثه فقدم على الملك رجلان من بني نهد بن زيد يقال لهما حزن وسهل ابنا رزاح وكان عندهما حديث من أحاديث العرب فاجتباهما الملك ونزلا بالمكان الأثير منه فحسدهما زهير بن جناب فقال أيها الملك وهما والله عين لذي القرنين عليك يعني المنذر الأكبر جد النعمان ابن المنذر وهما يكتبان إليه بعورتك وخلل ما يريان منك قال كلا فلم يزل به زهير حتى أوغر صدره وكان إذا ركب يبعث إليهما ببعيرين يركبان معه فبعث إليهما بناقة واحدة فعرفا الشر فلم يركب أحدهما وتوقف فقال له الآخر\n(فإلا تجللها يعالوك فوقها ... وكيف توقى ظهر ما أنت راكبه)\nفركبها مع أخيه ومضى بهما فقتلا ثم بحث عن أمرهما بعد ذلك\nفوجده باطلا فشتم زهيرا وطرده فانصرف إلى بلاد قومه وقدم رزاح أبو الغلامين إلى الملك وكان شيخا عالما مجربا فأكرمه الملك وأعطاه دية ابنيه وبلغ زهيرا مكانه فدعا ابنا له يقال له عامر وكان من فتيان العرب لسانا وبيانا فقال له إن رزاحا قد قدم على الملك فالحق به واحتل في أن تكفينيه وقال له اذممني عند الملك ونل مني وأثر به آثارا فخرج الغلام حتى قدم الشأم فتلطف للدخول على الملك حتى وصل إليه فأعجبه ما رأى منه فقال له من أنت قال أنا عامر بن زهير بن جناب قال فلا حياك الله ولا حيا أباك الغادر الكذوب الساعي فقال الغلام نعم فلا حياه الله أنظر أيها الملك ما صنع بظهري وأراه آثار الضرب فقبل ذلك منه وأدخله في ندمائه فبينا هو يحدثه يوما إذ قال له أيها الملك إن أبي وإن كان مسيئا فلست أدع أن أقول الحق قد والله نصحك أبي ثم أنشأ يقول\n(فيا لك نصحة لما نذقها ... أراها نصحة ذهبت ضلالا)\nم تركه أياما وقال له بعد ذلك أيها الملك ما تقول في حية قد قطع ذنبها وبقي رأسها قال ذاك أبوك وصنيعه بالرجلين ما صنع قال أبيت اللعن والله ما قدم رزاح إلا ليثأر بهما فقال له وما آية ذلك قال اسقه الخمر ثم ابعث إليه عينا يأتك بخبره فلما انتشى صرفه إلى قبته ومعه بنت له وبعث عليه عيونا فلما دخل قبته قامت إليه ابنته تسانده فقال\n(دعيني من سنادك إن حزنا ... وسهلا ليس بعدهما رقود)\n(ألا تسلين عن شبلي ماذا ... أصابهما إذا اهترش الأسود)\n(فإني لو ثأرت المرء حزنا ... وسهلا قد بدا لك ما أريد)\nفرجع القوم إلى الملك فأخبروه بما سمعوا فأمر بقتل النهدي رزاح ورد زهيرا إلى موضعه\nوقد أنشدني محمد بن العباس اليزيدي قال أنشدنا محمد بن حبيب أبيات الوليد هذه على الولاء وهي\n(ألا من لليل لا تغور كواكبه ... إذا لاح نجم لاح نجم يراقبه)\n(بني هاشم ردوا سلاح ابن اختكم ... ولا تنهبوه لا تحل مناهبه)\n(بني هاشم لا تعجلوا بإقادة ... سواء علينا قاتلوه وسالبه)\n(فقد يجبر العظم الكسير وينبري ... لذي الحق يوما حقه فيطالبه)\n(وإنا وإياكم وما كان منكم ... كصدع الصفا لا يرأب الصدع شاعبه)\n(بني هاشم كيف التعاقد بيننا ... وعند علي سيفه وحرائبه)\n(لعمرك لا أنسى ابن أروى وقتله ... وهل ينسين الماء ما عاش شاربه)\n(هم قتلوه كي يكونوا مكانه ... كما غدرت يوما بكسرى مرازبه)\n(وإني لمجتاب إليكم بجحفل ... يصم السميع جرسه وجلائبه)\nقد أجاب الفضل بن عباس بن عتبة بن أبي لهب الوليد عن هذه الأبيات وقيل بل أبوه العباس بن عتبة المجيب له أيضا والجواب صوت\n(فلا يسألونا بالسلاح فإنه ... أضيع وألقاه لدى الروع صاحبه)\n(وشبهته كسرى وقد كان مثله ... شبيها بكسرى هديه وعصائبه)\nذكر أحمد بن المكي أن لابن مسجح فيه لحنا وأن لحنه من الثقيل الأول بالسبابة في مجرى الوسطى وقال غيره إنه من منحول أبيه يحيى إلى ابن مسجح","topic":"خبر النهدي في هذا الشعر وخبر الوليد بن عقبة وقد مضى نسبه في أول الكتاب","topicNo":50,"sp":1,"spl":"خبر النهدي في هذا الشعر وخبر الوليد بن عقبة وقد مضى نسبه في أول الكتاب"},
{"id":"b51-1","bab":"الجزء 5","sec":"ذكر باقي خبر الوليد بن عقبة ونسبه","page":"ج5 ص134","text":"الوليد بن عقبة بن أبي معيط وقد مضى نسبه مع أخبار ابنه أبي قطيفة ويكنى الوليد أبا وهب وهو أخو عثمان بن عفان لأمه أمهما أروى بنت كريز وأمها البيضاء بنت عبد المطلب وكان من فتيان قريش وشعرائهم وشجعانهم وأجوادهم وكان فاسقا وولي لعثمان رضي الله عنه الكوفة بعد سعد بن أبي وقاص فشرب الخمر وشهد عليه بذلك فحده وعزله وهو الذي يقول يرثي عثمان رضي الله عنه ويحرض معاوية\n(والله ما هند بأمك إن مضى النهار ... ولم يثأر لعثمان ثائر)\n(أيقتل عبد القوم سيد أهله ... ولم تقتلوه ليت أمك عاقر)\n(وإنا متى نقتلهم لا يقد بهم ... مقيد فقد دارت عليك الدوائر)","topic":"ذكر باقي خبر الوليد بن عقبة ونسبه","topicNo":51,"sp":0,"spl":"ذكر باقي خبر الوليد بن عقبة ونسبه — منزلته عند عثمان رض"},
{"id":"b51-2","bab":"الجزء 5","sec":"منزلته عند عثمان رض","page":"ج5 ص135","text":"أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثنا عبد الله بن محمد بن حكيم عن خالد بن سعيد بن عمرو بن سعيد عن أبيه قال لم يكن يجلس مع عثمان رضي الله عنه على سريره إلا العباس بن عبد المطلب وأبو سفيان بن حرب والحكم بن أبي العاصي والوليد بن عقبة فأقبل الوليد يوما فجلس ثم أقبل الحكم فلما رآه عثمان زحل له عن مجلسه فلما قام الحكم قال له الوليد والله يا أمير المؤمنين لقد تلجلج في صدري بيتان قلتهما حين رأيتك آثرت عمك على ابن أمك\nفقال له عثمان رضي الله تعالى عنه إنه شيخ قريش فما البيتان اللذان قلتهما قال قلت\n(رأيت لعم المرء زلفى قرابة ... دوين أخيه حادثا لم يكن قدما)\n(فأملت عمرا أن يشب وخالدا ... لكي يدعواني يوم مزحمة عما)\nيعني عمرا وخالدا ابني عثمان قال فرق له عثمان وقال له قد وليتك العراق يعني الكوفة","topic":"ذكر باقي خبر الوليد بن عقبة ونسبه","topicNo":51,"sp":0,"spl":"ذكر باقي خبر الوليد بن عقبة ونسبه — منزلته عند عثمان رض"},
{"id":"b51-3","bab":"الجزء 5","sec":"الوليد بن عقبة وسعد بن أبي وقاص","page":"ج5 ص136","text":"أخبرني أحمد قال حدثني عمر بن شبة قال حدثني بعض أصحابنا عن ابن دأب قال لما ولي عثمان رضي الله عنه الوليد بن عقبة الكوفة قدمها وعليها سعد ابن أبي وقاص فأخبر بقدومه فقال وما صنع قال وقف في السوق فهو يحدث الناس هناك ولسنا ننكر شيئا من شأنه فلم يلبث أن جاءه نصف النهار فاستأذن على سعد فأذن له فسلم عليه بالإمرة وجلس معه فقال له سعد ما أقدمك أبا وهب قال أحببت زيارتك قال وعلى ذلك أجئت بريدا قال أنا أرزن من ذلك ولكن القوم احتاجوا إلى عملهم فسرحوني إليه وقد استعملني أمير المؤمنين على الكوفة فمكث طويلا ثم قال لا والله ما أدري أصلحت بعدنا أم فسدنا بعدك ثم قال\n(خذيني فجريني ضباع وأبشري ... بلحم امرئ لم يشهد اليوم ناصره)\nقال أما والله لأنا أقول للشعر وأروى له منك ولو شئت لأجبتك ولكني أدع ذلك لما تعلم نعم والله قد أمرت بمحاسبتك والنظر في أمر عمالك ثم بعث إلى عماله فحبسهم وضيق عليهم فكتبوا إلى سعد\nيستغيثون فكلمه فيهم فقال له أو للمعروف عندك موضع قال نعم والله فخلى سبيلهم أخبرني أحمد بن عبد العزيز قال حدثني عمر قال حدثنا جناد بن بشر قال حدثني جرير عن مغيرة بنحوه قال أبو زيد عمر بن شبة أخبرنا أبو بكر الباهلي قال حدثنا هشيم عن العوام بن حوشب أنه لما قدم على سعد قال له سعد ما أدري أكست بعدنا أم حمقنا بعدك فقال لا تجزعن أبا إسحاق فإنما هو الملك يتغداه قوم ويتعشاه آخرون فقال له سعد أراكم والله ستجعلونه ملكا أخبرني أحمد قال حدثني عمر قال حدثني المدائني عن بشر بن عاصم عن الأعمش عن شقيق بن سلمة قال قدم الوليد بن عقبة عاملا لعثمان على الكوفة وعبد الله بن مسعود على بيت المال وكان سعد قد أخذ مالا فقال الوليد لعبد الله خذه بالمال فكلمه عبد الله بمحضر من الوليد في ذلك فقال سعد آتي أمير\nالمؤمنين فإن أخذني به أديته فغمز الوليد عبد الله ونظر إليهما سعد فنهض وقال فعلتماها ودعا الله أن يغري بينهما وأدى المال أخبرني أحمد قال حدثني عمر بن شبة قال حدثنا هارون بن معروف قال حدثنا ضمرة بن ربيعة عن ابن شوذب قال صلى الوليد بن عقبة بأهل الكوفة الغداة أربع ركعات ثم التفت إليهم فقال أأزيدكم فقال عبد الله بن مسعود ما زلنا معك في زيادة منذ اليوم أخبرني أحمد قال حدثني عمر بن شبة قال حدثنا محمد بن حميد قال حدثنا جرير عن الأجلح عن الشعبي في حديث الوليد بن عقبة حين شهدوا عليه قال قال الحطيئة\n(شهد الحطيئة يوم يلقى ربه ... أن الوليد أحق بالعذر)\n(نادى وقد تمت صلاتهم ... أأزيدكم سكرا وما يدري)\n(فأبوا أبا وهب ولو أذنوا ... لقرنت بين الشفع والوتر)\n(كفوا عنانك إذ جريت ولو ... تركوا عنانك لم تزل تجري)\nقال الحطئية أيضا\n(تكلم في الصلاة وزاد فيها ... علانية وجاهر بالنفاق)\n(ومج الخمر في سنن المصلى ... ونادى والجميع إلى افتراق)\n(أزيدكم على أن تحمدوني ... وما لكم ومالي من خلاق)","topic":"ذكر باقي خبر الوليد بن عقبة ونسبه","topicNo":51,"sp":1,"spl":"الوليد بن عقبة وسعد بن أبي وقاص"},
{"id":"b51-4","bab":"الجزء 5","sec":"صلى بالناس وهو مخمور فضرب الحد","page":"ج5 ص139","text":"أخبرني محمد بن خلف وكيع قال قال حماد بن إسحاق حدثني أبي قال ذكر أبو عبيدة وهشام بن الكلبي والأصمعي قالوا كان الوليد بن عقبة زانيا شريب خمر فشرب الخمر بالكوفة وقام ليصلي بهم الصبح في المسجد الجامع فصلى بهم أربع ركعات ثم التفت إليهم وقال لهم أزيدكم وتقيأ في المحراب وقرأ بهم في الصلاة وهو رافع صوته\n(علق القلب الربابا ... بعد ما شابت وشابا)\nشخص أهل الكوفة إلى عثمان فأخبروه خبره وشهدوا عليه بشربه الخمر فأتي به فأمر رجلا بضربه الحد فلما دنا منه قال له نشدتك الله وقرابتي من أمير المؤمنين فتركه فخاف علي بن أبي طالب رضي الله عنه أن يعطل الحد فقام إليه فحده فقال له الوليد نشدتك بالله وبالقرابة فقال له علي اسكت أبا وهب فإنما هلكت بنو إسرائيل بتعطيلهم الحدود فضربه وقال لتدعوني قريش بعد هذا جلادها قال إسحاق فأخبرني مصعب الزبيري قال قال الوليد بن عقبة بعد ما جلد اللهم إنهم شهدوا علي\nبزور فلا ترضهم عن أمير ولا ترض عنهم أميرا فقال الحطيئة يكذب عنه\n(شهد الحطيئة يوم يلقى ربه ... أن الوليد أحق بالعذر)\n(خلعوا عنانك إذ جربت ولو ... تركوا عنانك لم تزل تجري)\n(ورأوا شمائل ماجد أنف ... يعطي على الميسور والعسر)\n(فنزعت مكذوبا عليك ولم ... تنرع إلى طمع ولا فقر)\nقال رجل من بني عجل يرد على الحطيئة\n(نادى وقد تمت صلاتهم ... أأزيدكم ثملا وما يدري)\n(ليزيدهم خيرا ولو قبلوا ... لقرنت بين الشفع والوتر)\n(فأبوا أبا وهب ولو فعلوا ... وصلت صلاتهم إلى العشر)\nروى العباس بن ميمون طائع عن ابن عائشة قال حدثني أبي قال لما أحضر عثمان رضي الله عنه الوليد لأهل الكوفة في شرب الخمر حضر الحطيئة فاستأذن على عثمان وعنده بنو أمية متوافرون فطمعوا أن يأتي الوليد بعذر فقال\n(شهد الحطيئة يوم يلقى ربه ... أن الوليد أحق بالعذر)\n(خلعوا عنانك إذ جريت ولو ... تركوا عنانك لم تزل تجري)\n(ورأوا شمائل ماجد أنف ... يعطي على الميسور والعسر)\n(فنزعت مكذوبا عليك ولم ... تنزع إلى طمع ولا فقر)\nال فسروا بذلك وظنوا أن قد قام بعذره فقال رجل من بني عجل يرد على الحطيئة\n(نادى وقد تمت صلاتهم ... أأزيدكم ثملا وما يدري)\n(فأبوا أبا وهب ولو فعلوا ... وصلت صلاتهم إلى العشر)\nوجم القوم وأطرقوا فأمر به عثمان رضي الله تعالى عنه فحد أخبرني محمد بن يحيى الصولي قال حدثني محمد بن الفضل من حفظه قال حدثنا عمر بن شبة من حفظه ونسخت من كتاب لهارون بن الزيات بخطه عن عمر بن شبة وروايته أتم فحكيت لفظه قال شهد رجل عند أبي العجاج وكان على البصرة على رجل من المعيطيين شهادة وكان الرجل الشاهد سكران فقال المشهود عليه وهو المعيطي أعزك الله إنه لا يحسن أن يقرأ من السكر فقال الشاهد بلى إني لأحسن فقال اقرأ فقال\n(علق القلب الربابا ... بعد ما شابت وشابا)\nال وإنما تماجن بذلك على المعيطي ليحكي به ما صنع الوليد بن عقبة في محراب الكوفة وقد تقدم للصلاة وهو سكران فأنشد في صلاته هذا الشعر وكان أبو العجاج محمقا فظن أن هذا قرآن فقال صدق الله ورسوله ويلكم فلم تعلمون ولا تعملون ولقد روي أيضا في الشهادة على الوليد في السكر غير ما ذكر من زيادته في الصلاة أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال عرضت على المدائني عن مبارك بن سلام عن فطر بن خليفة عن أبي الضحى قال كان أبو زينب الأزدي وأبو مورع يطلبان عثرة الوليد بن عقبة فجاءا","topic":"ذكر باقي خبر الوليد بن عقبة ونسبه","topicNo":51,"sp":2,"spl":"صلى بالناس وهو مخمور فضرب الحد"},
{"id":"b51-5","bab":"الجزء 5","sec":"صلى بالناس وهو مخمور فضرب الحد","page":"ج5 ص139","text":"يوما فلم يحضر الصلاة فسألا عنه وتلطفا حتى علما أنه يشرب فاقتحما عليه الدار فوجداه يقيء فاحتملاه وهو سكران فوضعاه على سريره وأخذا خاتمه من يده فأفاق فافتقد خاتمه فسأل عنه فقالوا لا ندري وقد رأينا رجلين دخلا الدار فاحتملاك فوضعاك على سريرك فقال صفوهما لي فقالوا أحدهما آدم طويل حسن الوجه والآخر عريض مربوع عليه خميصة فقال هذا أبو زينب وأبو مورع ولقي أبو زينب وصاحبه عبد الله بن حبيش الأسدي وعلقمة بن يزيد البكري وغيرهما فأخبراهم فقالوا اشخصوا إلى أمير المؤمنين فأعلموه فقال بعضهم لا يقبل قولنا في أخيه فشخصوا إليه وقالوا إنا جئناك في أمر ونحن مخرجوه إليك من أعناقنا وقد قلنا إنك لا تقبله قال وما هو قالوا رأينا الوليد وهو سكران من خمر قد شربها وهذا خاتمه أخذناه وهو لا يعقل فأرسل إلى علي رضي الله تعالى عنه فشاوره فقال أرى أن تشخصه فإن شهدوا عليه بمحضر منه حددته فكتب عثمان رضي الله تعالى عنه إلى الوليد بن عقبة فقدم عليه فشهد عليه أبو زينب وأبو مورع وجندب الأسدي وسعد بن مالك الأشعري ولم يشهد عليه إلا يمان فقال عثمان لعلي قم فاضربه فقال علي للحسن قم فاضربه فقال الحسن مالك ولهذا يكفيك غيرك فقال علي لعبد الله بن جعفر قم فاضربه فضربه بمخصرة فيها سير له رأسان فلما بلغ أربعين قال له علي حسبك","topic":"ذكر باقي خبر الوليد بن عقبة ونسبه","topicNo":51,"sp":3,"spl":"صلى بالناس وهو مخمور فضرب الحد"},
{"id":"b51-6","bab":"الجزء 5","sec":"ما وقع بين عثمان وعائشة بسببه","page":"ج5 ص143","text":"أخبرنا أحمد قال حدثنا عمر قال حدثنا المدائني عن الوقاصي عن الزهري قال خرج رهط من أهل الكوفة إلى عثمان في أمر الوليد فقال أكلما غضب رجل منكم على أميره رماه بالباطل لئن أصبحت لكم لأنكلن بكم فاستجاروا بعائشة وأصبح عثمان فسمع من حجرتها صوتا وكلاما فيه بعض الغلظة فقال أما يجد مراق أهل العراق وفساقهم ملجأ إلا بيت عائشة فسمعت فرفعت نعل رسول الله وقالت تركت سنة رسول الله صاحب هذه النعل فتسامع الناس فجاؤوا حتى ملؤوا المسجد فمن قائل أحسنت ومن قائل ما للنساء ولهذا حتى تحاصبوا و تضاربوا بالنعال ودخل رهط من أصحاب رسول الله على عثمان فقالوا له اتق الله ولا تعطل الحد واعزل أخاك عنهم فعزله عنهم أخبرني أحمد قال حدثنا عمر قال حدثنا المدائني عن أبي محمد الناجي عن مطر الوراق قال قدم رجل المدينة فقال لعثمان رضي الله عنه إني صليت الغداة خلف الوليد بن عقبة فالتفت إلينا فقال أأزيدكم إني أجد اليوم نشاطا وأنا أشم منه رائحة الخمر فضرب عثمان الرجل فقال الناس عطلت الحدود وضربت الشهود أخبرني أحمد قال حدثني عمر قال حدثنا أبو بكر الباهلي عن بعض من حدثه قال لما شهد على الوليد عند عثمان بشرب الخمر كتب إليه يأمره\nبالشخوص فخرج وخرج معه قوم يعذرونه فيهم عدي بن حاتم فنزل الوليد يوما يسوق بهم فقال يرتجز\n(لا تحسبنا قد نسينا الإيجاف ... والنشوات من عتيق أو صاف)\n(وعزف قينات علينا عزاف ... )\nقال عدي إلى أين تذهب بنا أقم أخبرني أحمد قال حدثنا عمر قال عرضت على المدائني عن قيس بن الربيع عن الأجلح عن الشعبي عن جندب قال كنت فيمن شهد على الوليد فلما استتممنا عليه الشهادة حبسه عثمان ثم ذكر باقي خبره وضرب علي عليه السلام إياه وقول الحسن ما لك ولهذا فزاد فيه فقال له علي لست إذا مسلما أو من المسلمين حدثنا إبراهيم بن عبد الله المخزومي قال حدثنا سعيد بن محمد المخزومي قال حدثنا ابن علية قال حدثنا سعيد بن أبي عروبة عن عبد الله\nالداناج قال سمعت الحضين بن المنذر أبا ساسان يحدث وأخبرني أحمد ابن عبد العزيز قال حدثنا عمر بن شبة قال حدثنا محمد بن حاتم قال حدثنا إسماعيل بن إبراهيم بن علية قال حدثنا سعيد بن أبي عروبة قال حدثنا عبد الله الداناج عن حضين أبي ساسان قال لما جيء بالوليد بن عقبة إلى عثمان بن عفان وقد شهدوا عليه بشرب الخمر قال لعلي دونك ابن عمك فأقم عليه الحد فأمر به فجلد أربعين ثم ذكر نحو هذا الحديث وقال فيه فقال علي للحسن بل ضعفت ووهنت وعجزت قم يا عبد الله بن جعفر فقام فجلده وعلي يعد حتى بلغ أربعين فقال علي أمسك جلد رسول الله أربعين وجلد أبو بكر أربعين وأتمها عمر ثمانين وكل سنة أخبرنا أحمد بن عبد العزيز قال حدثنا عمر قال حدثنا عبد الله بن محمد ابن حكيم عن خالد بن سعيد قال\nلما ضرب عثمان الوليد الحد قال إنك لتضربني اليوم بشهادة قوم ليقتلنك عاملا قابلا أخبرني محمد بن العباس اليزيدي عن عمه عبيد الله قال أخبرني محمد ابن حبيب عن ابن الأعرابي قال وأخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثنا عبد الله بن محمد بن حكيم عن خالد بن سعيد وأخبرني إبراهيم بن محمد بن أيوب قال حدثنا عبد الله بن مسلم قالوا جميعا كان أبو زبيد الطائي نديما للوليد بن عقبة أيام ولايته الكوفة فلما شهد عليه بالسكر من الخمر وخرج من الكوفة قال أبو زبيد واللفظ في القصيدة لليزيدي لأنها في روايته أتم\n(من يرى العير لابن أروى على ظهر ... المرورى حداتهن عجال)\n(مصعدات والبيت بيت أبي وهب ... خلاء تحن فيه الشمال)\n(يعرف الجاهل المضلل أن الدهر ... فيه النكراء والزلزال)\n(ليت شعري كذاكم العهد أم كانوا ... أناسا كمن يزول فزالوا)\n(بعد ما تعلمين يا أم زيد ... كان فيهم عز لنا وجمال)\n(ووجوه بودنا مشرقات ... ونوال إذا أريد النوال)\n(أصبح البيت قد تبدل بالحي وجوها كأنها الأقتال ... )\n(كل شيء يحتال فيه الرجال ... غير أن ليس للمنايا احتيال)\n(ولعمر الإله لو كان للسيف ... مصال أو للسان مقال)\n(ما تناسيتك الصفاء ولا الود ... ولا حال دونك الأشغال)\n(ولحرمت لحمك المتعضى ... ضلة ضل حلمهم ما اغتالوا)\n(قولهم شربك الحرام وقد كان ... شراب سوى الحرام حلال)\n(وأبى الظاهر العداوة إلا ... شنانا وقول ما لا يقال)","topic":"ذكر باقي خبر الوليد بن عقبة ونسبه","topicNo":51,"sp":4,"spl":"ما وقع بين عثمان وعائشة بسببه","partial":1},
{"id":"b51-7","bab":"الجزء 5","sec":"ما وقع بين عثمان وعائشة بسببه","page":"ج5 ص143","text":"(من رجال تقارضوا منكرات ... لينالوا الذي أرادوا فناولوا)\n(غير ما طالبين ذحلا ولكن ... مال دهر على أناس فمالوا)\n(من يخنك الصفاء أو يتبدل ... أو يزل مثل ما تزول الضلال)\n(فاعلمن أنني أخوك أخو الود ... حياتي حتى تزول الجبال)\n(ليس بخلا عليك عندي بمال ... أبدا ما أقل نعلا قبال)\n(ولك النصر باللسان وبالكف ... إذا كان لليدين مصال)","topic":"ذكر باقي خبر الوليد بن عقبة ونسبه","topicNo":51,"sp":5,"spl":"ما وقع بين عثمان وعائشة بسببه — نسبة ما في هذا الشعر من الغناء"},
{"id":"b51-8","bab":"الجزء 5","sec":"نسبة ما في هذا الشعر من الغناء","page":"ج5 ص147","text":"صوت\n(من يرى العير لابن أروى على ظهر ... المرورى حداتهن عجال)\n(مصعدات والبيت بيت أبي وهب ... خلاء تحن فيه الشمال)\nروضه من الخفيف المرورى جمع مروراة وهي الصحراء غنى الدلال فيه خفيف ثقيل بإطلاق الوتر في مجرى البنصر عن إسحاق وغيره\nأخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال لما قدم الوليد بن عقبة الكوفة قدم عليه أبو زبيد فأنزله دار عقيل بن أبي طالب على باب المسجد وهي دار القبطي فكان مما احتج به عليه أهل الكوفة أن أبا زبيد كان يخرج إليه من داره يخترق المسجد وهو نصراني فيجعله طريقا أخبرني محمد بن العباس اليزيدي قال حدثني عمي عبيد الله عن أبي حبيب بن جبلة عن ابن الأعرابي أن أبا زبيد وفد على الوليد حين استعمله عثمان على الكوفة فأنزله الوليد دارا لعقيل بن أبي طالب على باب المسجد فاستوهبها منه فوهبها له فكان ذلك أول الطعن عليه من أهل الكوفة لأن أبا زبيد كان يخرج من منزله حتى يشق الجامع إلى الوليد فيسمر عنده ويشرب معه ويخرج فيشق المسجد وهو سكران فذلك نبههم عليه","topic":"ذكر باقي خبر الوليد بن عقبة ونسبه","topicNo":51,"sp":5,"spl":"ما وقع بين عثمان وعائشة بسببه — نسبة ما في هذا الشعر من الغناء"},
{"id":"b51-9","bab":"الجزء 5","sec":"عمر يوليه صدقات بني تغلب","page":"ج5 ص149","text":"قال وقد كان عمر بن الخطاب رضي الله تعالى عنه ولى الوليد بن عقبة صدقات بني تغلب فبلغه عنه بيت قاله وهو\n(إذا ما شددت الرأس مني بمشوذ ... فغيك مني تغلب بنة وائل)\nعزله وكان أبو زبيد قد استودع بني كنانة بن تيم بن أسامة بن مالك بن بكر ابن حبيب بن غنم بن تغلب إبلا فلم يردوها عليه حين طلبها وكانت بنو تغلب أخوال أبي زبيد فوجد الوليد بني تغلب ظالمين لأبي زبيد فأخذ له الوليد بحقه فقال يمدح الوليد\n(يا ليت شعري بأنباء أنبؤها ... قد كان يعيا بها صدري وتقديري)\n(عن امرىء ما يزده الله من شرف ... أفرح به ومري غير مسرور)\nعني مري بن أوس بن حارثة بن لأم وهي طويلة يقول فيها\n(إن الوليد له عندي وحق له ... ود الخليل ونصح غير مذخور)\n(لقد رعاني وأدناني وأظهرني ... على الأعادي بنصر غير تعذير)\n(فشذب القوم عني غير مكترث ... حتى تناهوا على رغم وتصغير)\n(نفسي فداء أبي وهب وقل له ... يا أم عمرو فحلي اليوم أو سيري)\nفي رواية ابن حبيب يا أم زيد يعني يا أم أبي زبيد أخبرني محمد بن العباس عن عمه عن محمد بن حبيب عن ابن الأعرابي قال\nكان الوليد بن عقبة قد استعمل الربيع بن مري بن أوس بن حارثة بن لأم الطائي على الحمى فيما بين الجزيرة وظهر الحيرة فأجدبت الجزيرة وكان أبو زبيد في تغلب فخرج بهم ليرعيهم فأبى عليه الأوسي وقال إن شئت أن أرعيك وحدك فعلت وإلا فلا فأتى أبو زبيد الوليد بن عقبة فأعطاه ما بين القصور الحمر من الشأم إلى القصور الحمر من الحيرة وجعله له حمى وأخذها من الآخر هكذا روى ابن حبيب وأخبرنا أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال كانت الجنينة في يد مري بن أوس فلما قدم الوليد بن عقبة الكوفة انتزعها منه ودفعها إلى أبي زبيد والقول الأول أصح وشعر أبي زبيد يدل عليه في قوله في الوليد بن عقبة يمدحه\n(لعمر أبيك يابن أبي مري ... لغيرك من أباح لها الديارا)\n(أباح لها أبارق ذات نور ... ترعى القف منها والعرارا)\n(بحمد الله ثم فتى قريش ... أبى وهب غدت بطنا غزارا)\n(أباح لها ولا يحمى عليها ... إذا ما كنتم سنة جزارا)\nريد جزرا من الجدب والشدة\n(فتى طالت يداه إلى المعالي ... وطحطحتا المقطعة القصارا)\nهي أبيات\nقال عمر بن شبة في خبره خاصة فلما عزل الوليد ووليها سعيد انتزعها منه وأخرجها من يده فقال\n(ولقد مت غير أني حي ... يوم بانت بودها خنساء)\n(من بني عامر لها شق نفسي ... قسمة مثل ما يشق الرداء)\n(أشربت لون صفرة في بياض ... وهي في ذاك لدنة غيداء)\n(كل عين ممن يراها من الناس ... إليها مديمة حولاء)\n(فانتهوا إن للشدائد أهلا ... وذروا ما تزين الأهواء)\n(ليت شعري وأين مني ليت ... إن ليتا وإن لوا عناء)\n(أي ساع سعى ليقطع شربي ... حين لاحت للصابح الجوزاء)\n(واستظل العصفور كرها مع الضب ... وأوفى في عوده الحرباء)\n(ونفى الجندب الحصا بكراعيه ... وأذكت نيرانها المعزاء)\n(من سموم كأنها حر نار ... سفعتها ظهيرة غراء)\n(وإذا أهل بلدة أنكروني ... عرفتني الدوية الملساء)\n(عرفت ناقتي الشمائل مني ... فهي إلا بغامها خرساء)\n(عرفت ليلها الطويل وليلي ... إن ذا الليل للعيون غطاء)","topic":"ذكر باقي خبر الوليد بن عقبة ونسبه","topicNo":51,"sp":6,"spl":"عمر يوليه صدقات بني تغلب"},
{"id":"b51-10","bab":"الجزء 5","sec":"نسبة ما يغنى فيه من هذا الشعر","page":"ج5 ص152","text":"صوت\n(أي ساع سعى ليقطع شربي ... حين لاحت للصابح الجوزاء)\n(واستكن العصفور كرها مع الضب ... وأوفى في عوده الحرباء)\n(وإذا الدار أهلها أنكروني ... عرفتني الدوية الملساء)\n(عرفت ناقتي الشمائل مني ... فهي إلا بغامها خرساء)\n(عرفت ليلها الطويل وليلي ... إن ذا الليل للعيون غطاء)\nعروضه من الخفيف غناه ابن سريج خفيف رمل مطلق في مجرى البنصر عن إسحاق وغنى داود بن العباس الهاشمي في الخامس ثم الثالث خفيف ثقيل أول بالوسطى عن عمرو قال ابن حبيب في خبره وقال أبو زبيدة يتشوق إلى الوليد لما خرج عن الكوفة\n(لعمري لئن أمسى الوليد ببلدة ... سواي لقد أمسيت للدهر معورا)\nال ابن حبيب ويروى سوي لقد وهي لغة طيىء\n(خلا أن رزق الله غاد ورائح ... وأني له راج وإن سرت أشهرا)\n(وكان هو الحصن الذي ليس مسلمي ... إذا أنا بالنكراء هيجت معشرا)\n(إذا صادفوا دوني الوليد كأنما ... يرون بوادي ذي حماس مزعفرا)\n(خضيب بنان ما يزال براكب ... يخب وضاحي جلده قد تقشرا)\nوهي طويلة حدثني إسحاق بن بنان الأنماطي قال حدثنا حبيش بن مبشر قال حدثنا عبيد الله بن موسى قال حدثنا ابن أبي ليلى عن الحكم عن سعيد بن جبير عن ابن عباس قال قال الوليد بن عقبة لعلي بن أبي طالب رضي الله تعالى عنه أناأحد منك سنانا وأبسط منك لسانا وأملأ للكتيبة طعانا فقال له علي رضي الله تعالى عنه اسكت فإنما أنت فاسق فنزل القرآن ( أفمن كان مؤمنا كمن كان فاسقا لا يستوون\nخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثني محمد ابن حاتم قال حدثنا يونس بن محمد قال حدثنا شيبان عن قتادة في قوله تعالى ( إن جاءكم فاسق بنبإ\nقال هذا ابن أبي معيط الوليد بن عقبة بعثه النبي إلى بني المصطلق مصدقا فلما رأوه أقبلوا نحوه\nفهابهم فرجع إلى النبي فأخبره أنهم قد ارتدوا عن الإسلام فبعث النبي خالد بن الوليد وأمره أن يتثبت ولا يعجل فانطلق حتى أتاهم ليلا فبعث عيونه فلما جاؤوه أخبروه بأنهم متمسكون بالإسلام وسمعوا أذانهم وصلاتهم فلما أصبحوا أتاهم خالد فرأى ما يعجبه فرجع إلى النبي فأخبره أخبرنا أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثنا عبيد الله ابن موسى قال حدثنا نعيم بن حكيم عن أبي مريم عن علي أن امرأة الوليد بن عقبة جاءت إلى النبي تشتكي الوليد وقالت إنه يضربها فقال لها \" ارجعي وقولي إن رسول الله قد أجارني \" فانطلقت فمكثت ساعة ثم رجعت فقالت ما أقلع عني فقطع رسول الله هدبة من ثوبه ثم قال \" امضي بهذا ثم قولي إن رسول الله أجارني \" فانطلقت فمكثت ساعة ثم رجعت فقالت يا رسول الله ما زادني إلا ضربا فرفع يديه وقال \" اللهم عليك الوليد \" مرتين أو ثلاثا","topic":"ذكر باقي خبر الوليد بن عقبة ونسبه","topicNo":51,"sp":7,"spl":"نسبة ما يغنى فيه من هذا الشعر"},
{"id":"b51-11","bab":"الجزء 5","sec":"لم يمسسه النبي بسبب الخلوق","page":"ج5 ص154","text":"أخبرنا أحمد قال حدثنا عمر بن شبة وحدثني أبو عبيد الصيرفي قال حدثني الفضل بن الحسن البصري قال حدثنا عمر بن شبة قال حدثنا أيوب بن عمر قال حدثنا عمر بن أيوب قال حدثنا جعفر بن برقان عن ثابت بن الحجاج عن أبي موسى عبد الله الهمداني أن الوليد بن عقبة قال لما فتح رسول الله مكة جعل أهل مكة\nيأتونه بصبيانهم فيدعو لهم بالبركة ويمسح على رؤوسهم فجيء بي إليه وأنا مخلق فلم يمسسني وما منعه إلا أن أمي خلقتني بخلوق فلم يمسسني من أجل الخلوق أخبرنا أحمد قال حدثنا عمر قال حدثنا خلف بن الوليد قال حدثنا المبارك بن فضالة عن الحسن أن الوليد بن عقبة كان عنده ساحر يريه كتيبتين تقتتلان فتحمل إحداهما على الأخرى فتهزمها فقال له الساحر أيسرك أن أريك هذه المنهزمة تغلب الغالبة فتهزمها قال نعم وأخبر جندب بذلك فاشتمل على السيف ثم جاء فقال أفرجوا فضربه حتى قتله ففزع الناس وخرجوا فقال يا أيها الناس لا عليكم إنما قتلت هذا الساحر لئلا يفتنكم في دينكم فحبسه قليلا ثم تركه أخبرنا أحمد قال حدثنا عمر بن شبة قال حدثنا عمر بن سعيد الدمشقي وحدثنا سعيد بن عبد العزيز عن الزهري أن رجلا من الأنصار نظر إلى رجل يستعلن بالسحر فقال أو إن\nالسحر ليعلن به في دين محمد فقتله فأتي به الوليد بن عقبة فحبسه فقال له دينار بن دينار فيم حبست فأخبره فخلى سبيله فأرسل الوليد إلى دينار فقتله أخبرنا أحمد قال حدثنا عمر قال حدثنا موسى بن إسماعيل قال حدثنا حماد بن سلمة قال حدثنا أبو عمران الجوني أن ساحرا كان عند الوليد بن عقبة فجعل يدخل في جوف بقرة ويخرج منه فرآه جندب فذهب إلى بيته فاشتمل على سيف فلما دخل الساحر في جوف البقرة قال أتأتون السحر وأنتم تبصرون ثم ضرب وسط البقرة فقطعها وقطع الساحر في البقرة فانذعر الناس فسجنه الوليد وكتب بذلك إلى عثمان رضي الله عنه وكان السجان يفتح له الباب بالليل فيذهب إلى أهله فإذا أصبح دخل السجن","topic":"ذكر باقي خبر الوليد بن عقبة ونسبه","topicNo":51,"sp":8,"spl":"لم يمسسه النبي بسبب الخلوق"},
{"id":"b51-12","bab":"الجزء 5","sec":"جندب بن كعب الأسدي","page":"ج5 ص156","text":"أخبرني أحمد قال حدثنا عمر قال حدثنا حجاج بن نصير قال حدثنا قرة عن محمد بن سيرين قال انطلق بجندب بن كعب إلى سجن خارج من الكوفة وعلى السجن رجل نصراني فلما رأى جندب بن كعب يصوم النهار ويقوم الليل قال النصراني والله إن قوما هذا شرهم لقوم صدق فوكل بالسجن رجلا ودخل\nالكوفة فسأل عن أفضل أهل الكوفة فقالوا الأشعث بن قيس فاستضافه فجعل يرى أبا محمد ينام الليل ثم يصبح فيدعو بغدائه فخرج من عنده فسأل أي أهل الكوفة أفضل فقالوا جرير بن عبد الله فوجده ينام الليل ثم يصبح فيدعو بغدائه فاستقبل القبلة ثم قال ربي رب جندب وديني على دين جندب وأسلم حدثني عمي الحسن بن محمد قال حدثنا الخزاز عن المدائني عن علي ابن مجاهد عن محمد بن إسحاق عن يزيد بن رومان عن الزهري وغيره قالوا لما انصرف رسول الله من غزوة بني المصطلق نزل رجل فساق بالقوم ورجز ثم نزل آخر فساق بالقوم ورجز ثم بدا لرسول الله أن يواسي أصحابه فنزل فجعل يقول \" جندب وما جندب والأقطع الخير زيد فدنا منه أصحابه وقالوا يا رسول الله ما ينفعنا مشيك مخافة أن تلسعك دابة الأرض أو تصيبك نكبة فركب ودنوا منه فقالوا لقد قلت قولا ما ندري ما هو قال وما ذاك قالوا قولك جندب وما جندب والأقطع الخير زيد فقال رجلان يكونان في هذه الأمة يضرب أحدهما ضربة يفرق بين الحق والباطل وتقطع يد الآخر في سبيل الله فيتبع الله آخر\nجسده بأوله \" فكان زيد بن صوحان قطعت يده يوم جلولاء وقتل يوم الجمل مع علي وأما جندب فإنه رجل دخل على الوليد بن عقبة وعنده ساحر يكنى أبا شيبان يأخذ أعين الناس فيخرج مصارين بطنه ثم يعيدها فيه فجاء من خلفه فقتله وقال\n(العن وليدا وأبا شيبان ... وابن حبيش راكب الشيطان)\n(رسول فرعون إلى هامان ... )\nثمان ينزعه عن الكوفة أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثنا إبراهيم بن المنذر الحزامي قال حدثني ابن وهب عن يونس عن الزهري قال نزع عثمان بن عفان الوليد بن عقبة عن الكوفة وأمر عليها سعيد بن العاص\nقال أبو زيد فحدثني عبد الله بن عبد الرحمن قال حدثنا سعيد بن جامع الهجيمي قال لما أقبل سعيد من المدينة عامدا للكوفة بعد ما خرج واليا لعثمان جعل يرتجز في طريقه\n(ويل نسيات العراق مني ... كأنني سمعمع من جن)\nخبرني أحمد قال حدثني عمر قال حدثني المدائني عن أبي علقمة عن سعيد بن أشوع قال قال عدي بن حاتم قدم سعيد بن العاص الكوفة فقال اغسلوا هذا المنبر فإن الوليد كان رجسا نجسا فلم يصعده حتى غسل عيبا على الوليد وكان الوليد أسن منه وأسخى نفسا وألين جانبا وأرضى عندهم فقال بعض شعرائهم\n(يا ويلنا قد ذهب الوليد ... وجاءنا من بعده سيعد)\n(ينقص في الصاع ولا يزيد ... )\nقال آخر\n(فررت من الوليد إلى سعيد ... كأهل الحجر إذ جزعوا فباروا)\n(يلينا من قريش كل عام ... أمير محدث أو مستشار)\n(لنا نار تحرقنا فنخشى ... وليس لهم فلا يخشون نار)\nأخبرني أحمد بن عبد العزيز قال حدثنا عمر قال حدثنا المدائني قال قدم الوليد بن عقبة الكوفة زائرا للمغيرة بن شعبة فأتاه أشراف أهل الكوفة يسلمون عليه فقالوا والله ما رأينا بعدك مثلك فقال أخيرا أم شرا فقالوا بل خيرا قال ولكني والله ما رأيت بعدكم شرا منكم فأعادوا الثناء عليه فقال بعض ما تثنون به فوالله إن بغضكم لتلف وإن حبكم لصلف قال أبو زيد وذكروا أن قبيصة بن جابر كان ممن كثر على الوليد فقال معاوية يوما والوليد وقبيصة عنده يا قبيصة ما كان شأنك وشأن الوليد فقال خيرا يا أمير المؤمنين في أول وصل الرحم وأحسن الكلام فلا تسألن عن الشكر وحسن الثناء ثم غضب على الناس وغضبوا عليه وكنا منهم فإما ظالمون فنستغفر الله وإما مظلومون فغفر الله له وخذ في غير هذا يا أمير المؤمنين فإن الحديث ينسي القديم قال ولم فوالله لقد أحسن السيرة وبسط الخير وكف الشر قال فأنت أقدر على ذلك يا أمير المؤمنين منه فافعل قال اسكت لاسكت فسكت وسكت القوم فقال له ما لك لا تتحدث قال نهيتني عما كنت أحب فسكت عما أكره أخبرني أحمد قال حدثني عمر قال حدثني المدائني قال\nمات الوليد بن عقبة فويق الرقة ومات أبو زبيد فدفنا جميعا في موضع واحد فقال في ذلك أشجع السلمي وقد مر بقبريهما\n(مررت على عظام أبي زبيد ... وقد لاحت ببلقعة صلود)\n(وكان له الوليد نديم صدق ... فنادم قبره قبر الوليد)","topic":"ذكر باقي خبر الوليد بن عقبة ونسبه","topicNo":51,"sp":9,"spl":"جندب بن كعب الأسدي","partial":1},
{"id":"b51-13","bab":"الجزء 5","sec":"جندب بن كعب الأسدي","page":"ج5 ص156","text":"(وما أدري بمن تبدا المنايا ... بأحمد أو بأشجع أو يزيد)","topic":"ذكر باقي خبر الوليد بن عقبة ونسبه","topicNo":51,"sp":10,"spl":"جندب بن كعب الأسدي"},
{"id":"b51-14","bab":"الجزء 5","sec":"الوليد يخرج غازيا للروم","page":"ج5 ص161","text":"أخبرني الحسين بن يحيى عن حماد عن أبيه عن ابن الكلبي عن أبيه قال خرج الوليد بن عقبة غازيا للروم وعلى مقدمته عتبة بن فرقد فلقيه الروم فقاتلوه فقال له رجل من العرب نصراني لست على دينكم ولكني أنصحكم للنسب فالقوم مقاتلوكم إلى نصف النهار فإن رأوكم ضعفاء أفنوكم وإن صبرتم هربوا وتركوكم فقال سلمان بن ربيعة يا معشر المسلمين ما عذركم عند الله غدا إن أصيب عتبة بن فرقد وأصحابه ولم يعنهم أحد منكم فركب معه ثلاثة آلاف رجل على البغال يجنبون الخيل فلحقوا عتبة وأصحابه فقاتلوا معهم قتالا شديدا حتى هزم الله الروم فقال الوليد بن عقبة\n(أتاني من الفج الذي كنت آمنا ... بقية شذاذ من الخيل ظلع)\n(عليها العبيد يضربون جنوبها ... ونازل منا كل خرق سميذع)\n(فإني زعيم أن تصيح نساؤهم ... صياح دجاج القرية المتوزع)\nقال الحطيئة يمدح الوليد بذلك وكان قد وصله وكان الوليد جوادا\n(أرى لابن أروى خلتين اصطفاهما ... قتال إذا يلقى العدو ونائله)\n(فتى يملأ الشيزى ويروى بكفه ... سنان الرديني الأصم وعامله)\n(يؤم العدو حيث كان بجحفل ... يصم السميع جرسه وصواهله)\n(إذا حان منه منزل الليل أوقدت ... لأخراه في أعلى اليفاع أوائله)\n(نفيت الجعاد البيض عن حردارهم ... فلم يبق إلا حية أنت قاتله)\nقال الحليس بن نعيم النهدي يكذب الحطيئة\n(وأبلغ أبا وهب إذا ما لقيته ... فقد حاربتك الروم فيمن تحارب)\n(وفي الأرض حيات وأسد كثيرة ... عدو ولكن الحطيئة كاذب)\nأخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثنا علي ابن محمد عن أبي مخنف عن خالد بن قطن عن أبيه قال لما قتل عثمان أرسل علي فأخذ كل ما كان في داره من السلاح وإبلا من إبل الصدقة فلذلك قال الوليد بن عقبة\n(بني هاشم ردوا سلاح ابن أختكم ... ولا تنهبوه لا تحل مناهبه)\nيروي\n(ولا تهبوه لا تحل مواهبه ... )\n(بني هاشم كيف الهوادة بيننا ... وعند علي سيفه ونجائبه)\n(قتلتم أخي كيما تكونوا مكانه ... كما فعلت يوما بكسرى مرازبه)\nهكذا في الخبر\n(ولا تهبوه لا تحل مواهبه ... )\nخبرني الطوسي قال حدثنا الزبير بن بكار قال حدثني عبد الله بن إسحاق الجعفري أن الوليد بن عقبة بن أبي معيط لقي بجادا مولى عثمان فأخبره أن عثمان قد قتل فقال\n(ليت أني هلكت قبل حديث ... سل جسمي وريع منه فؤادي)\n(يوم لاقيت بالبلاط بجادا ... ليت أني هلكت قبل بجاد)\nقد زيد في هذا الشعر بيت ونقص منه آخر مكانه وغني فيه وهو\nصوت\n(طال ليلي وملني عوادي ... وتجافى عن الضلوع مهادي)\n(من حديث نمي إلي فما يرقأ ... دمعي ولا أحس رقادي)\n(يوم لاقيت بالبلاط بجادا ... ليت أني هلكت قبل بجاد)\n(وبنفسي التي أحب وأهلي ... وبمالي وطارفي وتلادي)\n(قلت لا تغضبي فذلك قولي ... بلساني وما يجن فؤادي)\nنى فيه ابن عباد ثاني ثقيل مطلق في مجرى البنصر في الأول والرابع من الأبيات وذكر عمرو بن بانة أنه لابن محرز ومن الناس من ينسبه إلى ابن سريج في هذه الطريقة في الأول والثاني وذكر ابن المكي أنه للغريض ثاني ثقيل بالخنصر في مجرى البنصر ووافقه يونس وذكر أن في هذا الشعر لابن سريج والغريض لحنين في الخمسة الأبيات وذكر حبش أن فيها لمعبد ثقيلا أول بالوسطى ولعبد الله بن العباس الربيعي ثاني ثقيل بالوسطى وللغريض خفيف رمل بالوسطى ولسليم ثقيل أول بالوسطى وذكر أحمد بن عبيد أن فيه رملا لابن جامع في البيت الأول وحده وأن فيه هزجا لا يعرف صانعه أخبرني أحمد بن جعفر جحظة قال حدثني هبة الله بن إبراهيم بن\nالمهدي قال حدثني أبي قال أرسل إلي محمد بن زبيدة في ليلة من ليالي الصيف مقمرة يا عم إن الحرب بيني وبين طاهر بن الحسين قد سكنت فصر إلي فإني إليك مشتاق فجئته وقد بسط له على سطح زبيدة وعنده سليمان بن جعفر عليه كساء روذباري وقلنسوة طويلة وجواريه بين يديه وضعف جاريته عنده فقال لها غنيني فقد سررت بعمومتي فاندفعت تغنيه\n(هم قتلوه كي يكونوا مكانه ... كما فعلت يوما بكسرى مرازبه)\n(بني هاشم كيف التواصل بيننا ... وعند أخيه سيفه ونجائبه)\nهكذا غنت وإنما هو\n(وعند علي سيفه ونجائبه ... )\nغضب وتطير وقال لها ما قصتك ويحك انثني وانتهي وغنيني ما\nيسرني فاندفعت وغنت\n(هذا مقام مطرد ... هدمت منازله ودوره)\nازداد تطيرا ثم قال لها ويحك انتهي غنيني غير هذا فغنت","topic":"ذكر باقي خبر الوليد بن عقبة ونسبه","topicNo":51,"sp":11,"spl":"الوليد يخرج غازيا للروم","partial":1},
{"id":"b51-15","bab":"الجزء 5","sec":"الوليد يخرج غازيا للروم","page":"ج5 ص161","text":"(كليب لعمري كان أكثر ناصرا ... وأيسر جرما منك ضرج بالدم)\nفقال لها قومي إلى لعنة الله فوثبت وكان بين يديه قدح بلور وكان لحبه إياه سماه باسمه محمدا فأصابه طرف ذيلها فسقط على بعض الصواني فانكسر وتفتت فأقبل علي وقال أرى والله يا عم أن هذا آخر أيامنا فقلت كلا بل يبقيك الله يا أمير المؤمنين ويسرك قال ودجلة والله يا بني هادئة ما فيها صوت مجداف ولا أحد يتحرك وهي كالطست هادئة فسمعت هاتفا يهتف قضي الأمر الذي فيه تستفتيان قال فقال لي أسمعت ما سمعت يا عم فقلت وما هو وقد والله سمعته فقال الصوت الذي جاء الساعة من دجلة فقلت ما سمعت شيئا وما هذا إلا توهم فإذا الصوت قد عاد يقول قضي الأمر الذي فيه تستفتيان فقال انصرف يا عم بيتك الله بخير فمحال ألا تكون الآن قد سمعت ما سمعت فانصرفت وكان آخر العهد به","topic":"ذكر باقي خبر الوليد بن عقبة ونسبه","topicNo":51,"sp":12,"spl":"الوليد يخرج غازيا للروم — انقضت أخبار الوليد بن عقبة صوت من المائة المختارة"},
{"id":"b51-16","bab":"الجزء 5","sec":"وفود الوليد بن عقبة على معاوية","page":"ج5 ص166","text":"أخبرني أحمد بن عبد العزيز الجوهري ومحمد بن يحيى الصولي واللفظ له قالا حدثنا محمد بن زكريا الغلابي قال حدثنا عبد الله بن الضحاك عن هشام بن محمد عن أبيه قال محمد وحدثنا عبد الله بن\nمحمد ومحمد بن عبد الرحمن جميعا عن مطرف بن عبد الله عن عيسى بن يزيد قال وفد الوليد بن عقبة وكان جوادا على معاوية فقيل له هذا الوليد ابن عقبة بالباب فقال والله ليرجعن معطيا غير معطى فإنه الآن قد أتانا يقول علي دين وعلي كذا وكذا يا غلام ائذن له فأذن له فسأله وتحدث معه ثم قال أما والله إن كنا لنحب إيثار مالك بالوادي وقد أعجب أمير المؤمنين فإن رأيت أن تهبه ليزيد فعلت فقال الوليد هو ليزيد ثم خرج وجعل يختلف إلى معاوية أياما فقال له يوما انظر يا أمير المؤمنين في شأني فإن علي مؤونة وقد أرهقني دين فقال له معاوية ألا تستحي لحسبك ونسبك تأخذ ما تأخذ فتبذره ثم لا تنفك تشكو دينا فقال له الوليد أفعل ثم انطلق مكانه فصار إلى الجزيرة فقال\n(فإذا سئلت تقول لا ... وإذا سألت تقول هات)\n(تأبى فعال الخير لا ... تروي وأنت على الفرات)\n(أفلا تميل إلى نعم ... أو ترك لا حتى الممات)\nال فبلغ معاوية مقدمه الجزيرة فخافه وكتب إليه أن أقبل إلي فكتب إليه\n(أعف وأستحيي كم قد أمرتني ... فأعط سواي ما بدا لك وانحل)\n(سأحدو ركابي عنك إن عزيمتي ... إذا نابني أمر كسلة منصل)\n(وإني امرؤ للرأي مني تطرف ... وليس شبا قفل علي بمقفل)\nورحل إلى الحجاز فبعث إليه معاوية بجائزة","topic":"ذكر باقي خبر الوليد بن عقبة ونسبه","topicNo":51,"sp":12,"spl":"الوليد يخرج غازيا للروم — انقضت أخبار الوليد بن عقبة صوت من المائة المختارة"},
{"id":"b51-17","bab":"الجزء 5","sec":"انقضت أخبار الوليد بن عقبة صوت من المائة المختارة","page":"ج5 ص168","text":"(ربما نبهني الإخوان ... والليل بهيم)\n(حين غارت وتدلت ... في مهاويها النجوم)\n(ونعاس الليل في عيني ... كالثاوي مقيم)\n(للتي تعصر لما ... أينعت منها الكروم)\n(أنا بالري مقيم ... في قرى الري أهيم)\n(ما أراني عن قرى الري ... مدى دهري أريم)\nلشعر والغناء لإبراهيم الموصلي ولحنه المختار ثقيل أول بإطلاق الوتر في مجرى البنصر عن إسحاق ولإبراهيم أيضا فيه خفيف ثقيل وقيل إنه لابنه إسحاق وفيه لأحمد بن يحيى المكي ثاني ثقيل بالوسطى عن الهشامي وأحمد بن عبيد","topic":"ذكر باقي خبر الوليد بن عقبة ونسبه","topicNo":51,"sp":12,"spl":"الوليد يخرج غازيا للروم — انقضت أخبار الوليد بن عقبة صوت من المائة المختارة"},
{"id":"b52-1","bab":"الجزء 5","sec":"نسب إبراهيم الموصلي وأخباره","page":"ج5 ص169","text":"هو فيما أخبرنا به يحيى بن علي بن يحيى المنجم عن حماد عن أبيه وأخبرني به عبد الله بن الربيع عن وسواسة وهو أحمد بن محمد بن إسماعيل بن إبراهيم الموصلي عن أبيه عن جده وعن حماد عن أبيه إبراهيم ابن ميمون أو ابن ماهان بن بهمن بن نسك وكان سبب نسبه إلى ميمون أنه كتب إلى صديق له فعنون كتابه من إبراهيم بن ماهان فقال له بعض فتيان الكوفة أما تستحي من هذا الاسم فقال هو اسم أبي فقال غيره فقال وكيف أغير فأخذ الكتاب فمحا ماهان وكتب ميمون فبقي إبراهيم ابن ميمون قال إسحاق عن أبيه وأصلنا من فارس ولنا بيت شريف في العجم وكان جدنا ميمون هرب من جور بعض عمال بني أمية فنزل بالكوفة في بني عبد الله بن دارم فكان بين إبراهيم وبين ولد نضلة بن نعيم رضاع وأم إبراهيم امرأة من بنات الدهاقين الذين هربوا من فارس لما هرب ميمون أبو إبراهيم فنزلوا جميعا بالكوفة في بني عبد الله بن دارم\nفتزوجها ماهان بالكوفة فولدت إبراهيم ومات في الطاعون الجارف وخلف إبراهيم طفلا وكان مولد إبراهيم سنة خمس وعشرين ومائة بالكوفة وتوفي ببغداد سنة ثمان وثمانين ومائة وله ثلاث وستون سنة","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":0,"spl":"نسب إبراهيم الموصلي وأخباره — مات أبوه وهو طفل"},
{"id":"b52-2","bab":"الجزء 5","sec":"مات أبوه وهو طفل","page":"ج5 ص170","text":"قال أحمد بن أحمد بن إسماعيل وسواسة في خبره ومات ماهان وخلف إبراهيم طفلا فكفله آل خزيمة بن خازم وقال يحيى بن علي في خبره إنه كان لإبراهيم لما مات أبوه سنتان أو ثلاث وخلف معه أخوين له من غير أمه أكبر منه فأقام إبراهيم مع أمه وأخواله حتى ترعرع فكان مع ولد خزيمة بن خازم في الكتاب فبهذا السبب صار ولاؤه لبني تميم وسأله الرشيد فقال ما السبب بينك وبين بني تميم فاقتص عليه قصته وقال ربونا يا أمير المؤمنين فأحسنوا تربيتنا ونشأت فيهم وكان بيننا رضاع فتولونا بهذا السبب فقال له الرشيد ويحك فما أراك إذا إلا مولاي فقال فهذه والله قصتي يا أمير المؤمنين قال يحيى بن علي في خبره وكان سبب قولهم إبراهيم الموصلي أنه\nلما نشأ واشتد وأدرك صحب الفتيان واشتهى الغناء فطلبه واشتد أخواله عليه في ذلك وبلغوا منه فهرب منهم إلى الموصل فأقام بها نحوا من سنة فلما رجع إلى الكوفة قال له إخوانه من الفتيان مرحبا بالفتى الموصلي فلقب به وقال أحمد في خبره إن سبب طلبه الغناء أنه خرج إلى الموصل فصحب جماعة من الصعاليك كانوا يصيبون الطريق ويصيبه معهم ويجمعون ما يفيدونه فيقصفون ويشربون ويغنون فتعلم منهم شيئا من الغناء وشدا فكان أطيبهم وأحذقهم فلما أحس بذلك من نفسه اشتهى الغناء وطلبه وسافر إلى المواضع البعيدة فيه وذكر ابن خرداذبه وهو قليل التحصيل لما يقوله ويضمنه كتبه أن سبب نسبته إلى الموصل أنه كان إذا سكر كثيرا ما يغني على سبيل الولع\n(أنا جت من طرق موصل ... أحمل قلل خمريا)\n(من شارب الملوك فلا ... بد من سكريا)\nما سمعت بهذه الحكاية إلا عنه وإنما ذكرتها على غثاثتها لشهرتها عند الناس وأنها عندهم كالصحيح من الرواية في نسبة إبراهيم إلى الموصل فذكرته دالا على عواره أخبرني الحسين بن يحيى المرداسي وابن أبي الأزهر قال حدثنا حماد ابن إسحاق عن أبيه قال أسلم أبي إلى الكتاب فكان لا يتعلم شيئا ولا يزال يضرب ويحبس ولا ينجع ذلك فيه فهرب إلى الموصل وهناك تعلم الغناء ثم صار إلى الري وتعلم بها أيضا ومهر وتزوج هناك امرأته دوشار وتفسير هذا الاسم أسدان وطال مقامه هناك وأخذ الغناء الفارسي والعربي وتزوج بها أيضا شاهك أم إسحاق ابنه وسائر ولده قال وفي دوشار هذه يقول إبراهيم وله فيه غناء من الهزج\n(دوشار يا سيدتي ... يا غايتي ومنيتي)\n(ويا سروري من جميع ... الناس ردي سنتي)\nقال إسحاق وحدثني أبي قال أول شيء أعطيته بالغناء أني كنت بالري أنادم أهلها بالسوية لا أرزؤهم شيئا ولا أنفق إلا من بقية مال كان معي انصرفت به من الموصل فمر بنا خادم أنفذه أبو جعفر المنصور إلى بعض عماله برسالة فسمعني عند رجل من أهل الري فشغف بي وخلع\nعلي دواج سمور له قيمة ومضى بالرسالة ورجع وقد وصله العامل بسبعة آلاف درهم وكساه كسوة كثيرة فجاءني إلى منزلي الذي كنت أسكنه فأقام عندي ثلاثة أيام ووهب لي نصف الكسوة التي معه وألفي درهم فكان ذلك أول ما اكتسبته بالغناء فقلت والله لا أنفق هذه الدراهم إلا على الصناعة التي أفادتنيها ووصف لي رجل بالأبلة يقال له جوانويه كان حاذقا فخرجت إليه وصحبت فتيانها فأخذت عنهم وغنيتهم فشغفوا بي","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":0,"spl":"نسب إبراهيم الموصلي وأخباره — مات أبوه وهو طفل"},
{"id":"b52-3","bab":"الجزء 5","sec":"إبراهيم وسبب اتصاله بالمهدي","page":"ج5 ص173","text":"أخبرني الحسين بن يحيى عن حماد عن أبيه عن جده قال لما أتيت جوانويه لم أصادفه في منزله فانتظرته حتى جاء فلما رآني احتشمني وكان مجوسيا فأخبرته بصناعتي والحال التي قصدته فيها فرحب بي وأفرد لي جناحا في داره ووكل بي أخته فقدمت إلي ما أحتاج إليه فلما كان العشي عاد إلى منزله ومعه جماعة من الفرس ممن يغني فنزلت إليه فجلسنا في مجلس قد صفي لنا فيه نبيذ وأعدت لنا فاكهة ورياحين فجلسنا وأخذوا في شأنهم وضربوا وغنوا فلم أجد عند أحد منهم فائدة وبلغت النوبة إلي فضربت وغنيت فقاموا كلهم إلي وقبلوا رأسي وقالوا سخرت منا نحن إلى تعليمك لنا أحوج منك إلينا فأقمت على تلك الحال أياما حتى بلغ محمد بن سليمان بن علي خبري فوجه إلي فأحضرني وأمرني بملازمته فقلت له أيها الأمير إني لست أتكسب\nبالغناء وإنما ألتذه فلذلك تعلمته وأريد العود إلى الكوفة فلم أنتفع بذلك عنده وأخذني بملازمته وسألني من أين أنا فانتسبت إلى الموصل فلزمتني وعرفت بها ولم أزل عنده أثيرا مكرما حتى قدم عليه خادم من خدم المهدي فلما رآني عنده قال له أمير المؤمنين أحوج إلى هذا منك فدافعه عني فلما قدم الرسول على المهدي سأله عما رأى في طريقه ومقصده فأخبره بذلك حتى انتهى إلى ذكري فوصفني له فأمره المهدي بالرجوع إلى محمد وإشخاصي إليه ففعل ذلك وجاء فأشخصني إلى المهدي فحظيت عنده وقدمني قال وسواسة في خبره عن إسحاق فحدثني أبي قال كان أول هاشمي صحبته علي بن سليمان بن علي أخو جعفر ومحمد وكان فتاهم ظرفا ولهوا وسماحة ووصفني له جوانويه ومضى بي إليه فوقعت من قلبه كل موقع وأول خليفة سمعني المهدي وصفت له فأخذني من علي بن سليمان وما سمع قبلي من المغنين أحدا سوى فليح بن أبي العوراء وسياط فإن الفضل بن الربيع وصلهما به قال إسحاق فحدثني أبي قال كان المهدي لا يشرب فأرادني على ملازمته وترك الشرب فأبيت عليه وكنت أغيب عنه الأيام فإذا جئته جئته منتشيا فغاظه ذلك مني فضربني وحبسني فحذقت الكتابة والقراءة في الحبس ثم دعاني يوما فعاتبني على شربي في منازل الناس والتبذل معهم فقلت يا أمير المؤمنين إنما تعلمت هذه الصناعة للذتي وعشرتي لإخواني ولو أمكنني تركها لتركتها وجميع ما أنا فيه لله جل وعز فغضب غضبا شديدا وقال لا تدخل على موسى وهارون البتة فوالله لئن دخلت\nعليهما لأفعلن ولأصنعن فقلت نعم ثم بلغه أني دخلت عليهما وشربت معهما وكانا مستهترين بالنبيذ فضربني ثلاثمائة سوط وقيدني وحبسني قال أحمد بن إسماعيل في خبره قال عمي إسحاق فحدثني أبي أنه كان معهما في نزهة لهما ومعهم أبان الخادم فسعى بهما وبي إلى المهدي وحدثه بما كنا فيه فدعاني فسألني فأنكرت فأمر بي فجردت فضربت ثلاثمائة وستين سوطا فقلت له وهو يضربني أن جرمي ليس من الأجرام التي يحل لك بها سفك دمي والله لو كان سر ابنيك تحت قدمي ما رفعتهما عنه ولو قطعتا ولو فعلت ذلك لكنت في حالة أبان الساعي العبد فلما قلت له هذا ضربني بالسيف في جفنه فشجني به وسقطت مغشيا علي ساعة ثم فتحت عيني فوقعتا على عيني المهدي فرأيتهما عيني نادم وقال لعبد الله بن مالك خذه إليك قال وقبل ذلك ما تناول عبد الله ابن مالك السوط من يد سلام الأبرش فضربني فكان ضرب عبد الله عندي بعد ضرب سلام عافية ثم أخرجني عبد الله إلى داره وأنا أرى الدنيا في عيني صفراء وخضراء وحمراء من حر السوط وأمره أن يتخذ لي شبيها بالقبر فيصيرني فيه فدعا عبد الله بكبش فذبح وسلخ وألبسني جلده ليسكن الضرب ودفعني إلى خادم له يقال له أبو عثمان سعيد التركي فصيرني في ذلك القبر ووكل بي جارية له يقال لها جشة فتأذيت بنز كان في ذلك القبر وبالبق وكان فيه حلي أستريح إليه فقلت لجشة اطلبي لي آجرة عليها فحم وكندر يذهب عني هذا البق فأتتني بذلك فلما دخنت أظلم القبر علي وكادت نفسي تخرج من الغم فاسترحت من أذاه إلى النز فألصقت به أنفي حتى خف الدخان فلما ظننت أني قد استرحت مما","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":1,"spl":"إبراهيم وسبب اتصاله بالمهدي"},
{"id":"b52-4","bab":"الجزء 5","sec":"إبراهيم وسبب اتصاله بالمهدي","page":"ج5 ص173","text":"كنت فيه إذا حيتان مقبلتان نحوي من شق القبر تدوران حولي بحفيف شديد فهممت أن آخذ واحدة بيدي اليمنى والأخرى بيدي اليسرى فإما علي وإما لي ثم كفيتهما فدخلتا من الثقب الذي خرجتا منه فمكثت في ذلك القبر ما شاء الله ثم أخرجت منه ووجهت إلى أبي عثمان الخادم أسأله أن يبيعني جشة لأكافئها عما أولتني ففعل فزوجتها من حاجب لي ولم تزل عندنا قال إسحاق مكثت عندنا حتى ماتت وبقيت بنت لها يقال لها جمعة فزوجتها من مولى لي في سنة أربع وثلاثين ومائتين قال إبراهيم وقلت في الحبس وأنا مقيد\n(ألا طال ليلي أراعي النجوم ... أعالج في الساق كبلا ثقيلا)\n(بدار الهوان وشر الديار ... أسام بها الخسف صبرا جميلا)\n(كثير الأخلاء عند الرخاء ... فلما حبست أراهم قليلا)\n(لطول بلائي مل الصديق ... فلا يأمنن خليل خليلا)\nال ثم أخرجني المهدي وأحلفني بالطلاق والعتاق وكل يمين لا فسحة لي فيها ألا أدخل على ابنيه موسى وهارون أبدا ولا أغنيهما وخلى سبيلي قال وصنعت في الحبس لحنا في شعر أبي العتاهية لما حبسه المهدي بسبب عتبة وهو صوت\n(أيا ويح قلبي من نجي البلابل ... ويا ويح ساقي من قروح السلاسل)\n(ويا ويح نفسي ويحها ثم ويحها ... ألم تنج يوما من شباك الحبائل)\n(ويا ويح عيني قد أضر بها البكا ... فلم يغن عنها طب ما في المكاحل)\n(ذريني أعلل نفسي اليوم إنها ... رهينة رمس في ثرى وجنادل)\n(ذريني أعلل بالشراب فقد أرى ... بقية عيشي هذه غير طائل)\nالشعر لأبي العتاهية وذكر حماد أنه لجده إبراهيم والغناء لإبراهيم رمل بالوسطى في الثلاثة الأبيات الأول وله في البيتين الأخيرين ثقيل أول بالوسطى","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":2,"spl":"إبراهيم وسبب اتصاله بالمهدي"},
{"id":"b52-5","bab":"الجزء 5","sec":"الهادي يطلبه","page":"ج5 ص177","text":"قال حماد فلما ولي موسى الهادي الخلافة استتر جدي منه ولم يظهر له بسبب الأيمان التي حلفه بها المهدي فكانت منازلنا تكبس في كل وقت وأهلنا يروعون بطلبه حتى أصابوه فمضوا به إليه فلما عاينه قال يا سيدي فارقت أم ولدي وأعز خلق الله علي ثم غناه لحنه في شعره صوت\n(يابن خير الملوك لا تتركني ... غرضا للعدو يرمي حيالي)\n(فلقد في هواك فارقت أهلي ... ثم عرضت مهجتي للزوال)\n(ولقد عفت في هواك حياتي ... وتغربت بين أهلي ومالي)\nلشعر والغناء لإبراهيم خفيف رمل بالوسطى قال إسحاق فموله والله الهادي وخوله وبحسبك أنه أخذ منه في يوم واحد مائة وخمسين ألف دينار ولو عاش لنا لبنينا حيطان دورنا بالذهب والفضة\nقال حماد قال لي أبي نظرت إلى ما صار إلى جدك من الأموال والغلات وثمن ما باع من جواريه فوجدته أربعة وعشرين ألف ألف درهم سوى أرزاقه الجارية وهي عشرة آلاف درهم في كل شهر وسوى غلات ضياعه وسوى الصلات النزرة التي لم يحفظها ولا والله ما رأيت أكمل مروءة منه كان له طعام معد في كل وقت فقلت لأبي أكان يمكنه ذلك فقال كان له في كل يوم ثلاث شياه واحدة مقطعة في القدور وأخرى مسلوخة ومعلقة وأخرى حية فإذا أتاه قوم طعموا ما في القدور فإذا فرغت قطعت الشاة المعلقة ونصبت القدور وذبحت الحية فعلقت وأتي بأخرى فجعلت وهي حية في المطبخ وكانت وظيفته لطعامه وطيبه وما يتخذ له في كل شهر ثلاثين ألف درهم سوى ما كان يجري وسوى كسوته ولقد اتفق عندنا مرة من الجواري الودائع لإخوانه ثمانون جارية ما منهن واحدة إلا ويجري عليها من الطعام والكسوة والطيب مثل ما يجري لأخص جواريه فإذا ردت الواحدة منهن إلى مولاها وصلها وكساها ومات وما في ملكه إلا ثلاثة آلاف دينار وعليه من الدين سبعمائة دينار قضيت منها أخبرني محمد بن خلف وكيع ويحيى بن علي بن يحيى وابن المرزبان قالوا أخبرنا حماد بن إسحاق قال كان أبي يحدث أن الرشيد اشترى من جدي جارية بستة وثلاثين ألف دينار فأقامت عنده ليلة ثم أرسل إلى الفضل بن الربيع إنا اشترينا\nهذه الجارية من إبراهيم ونحن نحسب أنها من بابتنا وليست كما ظننتها وما قربتها وقد ثقل علي الثمن وبينك وبينه ما بينكما فاذهب إليه فسله أن يحطنا من ثمنها ستة آلاف دينار قال فصار الفضل إليه فاستأذن عليه فخرج جدي فتلقاه فقال دعني من هذه الكرامة التي لا مؤنة بيننا فيها لست ممن يخدع وقد جئتك في أمر أصدقك عنه ثم أخبره الخبر كله فقال له إبراهيم إنه أراد أن يبلو قدرك عندي قال ذاك أراد قال فمالي كله صدقة من المساكين إن لم أضعفه لك قد حططتك اثني عشر ألف دينار فرجع الفضل إليه بالخبر فقال ويلك ادفع إلى هذا ماله فما رأيت سوقة قط أنبل نفسا منها قال أبي وكنت قد أتيت جدك فقلت ما كان لحطيطة هذا المال معنى وما هو بقليل فتغافل عني وقال أنت أحمق أنا أعرف الناس به والله لو أخذت المال منه كملا ما أخذته إلا وهو كاره ويحقد ذلك علي وكنت أكون عنده صغير القدر وقد مننت عليه وعلى الفضل وانبسطت نفسه ونشط وعظم قدري عنده وإنما اشتريت الجارية بأربعين ألف درهم وقد أخذت بها أربعة وعشرين ألف دينار فلما حمل المال إليه بلا حطيطة دعاني فقال لي كيف رأيت يا إسحاق من البصير أنا أم أنت فقلت بل أنت جعلني الله فداءك حدثني وكيع قال حدثنا حماد قال حدثني أبي قال لقي الفضل بن يحيى أبي وهو خارج من عند الفضل بن الربيع وكانا متجاورين في الشماسية فقال من أين يا أبا إسحاق أمن عند الفضل ابن الربيع قلت نعم غير معتذر من ذلك فقال خروج من عند\nالفضل بن الربيع إلى الفضل بن يحيى هذان والله أمران لا يجتمعان لك فقال والله لئن لم يكن في ما يتسع لكما حتى يكون الوفاء لكما جميعا واحدا ما في خير والله لا أترك واحدا منكما لصاحبه فمن قبلني على هذا قبلني ومن لم يقبلني فهو أعلم فقال له الفضل بن يحيى أنت عندي غير متهم والأمر كما قلت وقد قبلتك على ذلك","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":3,"spl":"الهادي يطلبه"},
{"id":"b52-6","bab":"الجزء 5","sec":"الرشيد يحبسه بالرقة ثم يطلقه ليغنيه","page":"ج5 ص180","text":"أخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة قال حدثني إسحاق قال حدثني أبي أن الرشيد غضب عليه فقيده وحبسه بالرقة ثم جلس للشرب يوما في مجلس قد زينه وحسنه فقال لعيسى بن جعفر هل لمجلسنا عيب قال نعم غيبة إبراهيم الموصلي عنه فأمر بإحضاري فأحضرت في قيودي ففكت عني بين يديه وأمرهم فناولوني عودا وقال غني\nيا إبراهيم فغنية\n(تضوع مسكا بطن نعمان أن مشت ... به زينب في نسوة خفرات)\nاستعاده وشرب وطرب وقال هنأتني يومي وسأهنئك بالصلة وقد وهبت لك الهنيء والمريء فانصرفت فلما أصبحت عوضت منهما مائتي ألف درهم","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":4,"spl":"الرشيد يحبسه بالرقة ثم يطلقه ليغنيه — نسبه هذا الصوت"},
{"id":"b52-7","bab":"الجزء 5","sec":"نسبه هذا الصوت","page":"ج5 ص181","text":"صوت\n(تضوع مسكا بطن نعمان أن مشت ... به زينب في نسوة خفرات)\n(مررن بفخ رائحات عشية ... يلبين للرحمن معتمرات)\n(يخمرن أطراف البنان من التقى ... ويقتلن بالألحاظ مقتدرات)\n(ولما رأت ركب النميري أعرضت ... وكن من أن يلقينه حذرات)\nالشعر للنميري الثقفي والغناء لابن سريج ثاني ثقيل بالخنصر في مجرى البنصر عن إسحاق ويحيى المكي وعمرو بن بانة وذكر حبش أن فيه لعزة الميلاء لحنا من الثقيل الأول أخبرني محمد بن مزيد وأحمد بن جعفر جحظة قالا حدثنا حماد بن إسحاق قال وأخبرني الصولي قال حدثني عون بن محمد جميعا عن إسحاق عن أبيه قال رأيت يحيى بن خالد خارجا من قصره الذي عند باب الشماسية يريد قصره الذي بباب البردان وهو يتمثل صوت\n(هوى بتهامة وهوى بنجد ... فأبلتني التهائم والنجود)\nال أبي فزدته عليه\n(أقيم بذا وأذكر عهد هذا ... فلي ما بين ذين هوى جديد)\nال وصنعت فيه لحنا قال الصولي في خبره وهو من خفيف الثقيل ثم صرت إليه فغنيته إياه فأمر لي بألف دينار وبدابته التي كانت تحته يومئذ بسرجها ولجامها فقلت له جزاك الله من سيد خيرا فإنك تأتي الأنفس وهي شوارد فتقرها والأهواء وهي سقيمة فتصحها فأمر لي بألف دينار أخرى\nقال إبراهيم ثم ضرب الدهر من ضربه فبينا أنا أسير معه إذ لقيه العباس بن الأحنف وكان ساخطا عليه لشيء بلغه عنه فترجل له وأنشده صوت\n(بالله يا غضبان إلا رضيت ... أذاكر للعهد أم قد نسيت)\nقال بل ذاكر يا أبا الفضل فأضفت إلى هذا البيت\n(لو كنت أبغي غير ما تشتهي ... دعوت أن تبلى كما قد بليت)\nصنعت فيه لحنا قال الصولي في خبره هو ثقيل أول قال وغنيته به فأمر لي بألفي دينار وضحك فقلت من أي شيء تضحك يا سيدي لا زلت ضاحكا مسرورا فقال ذكرت ما جرى في الصوت الأول وأنه كان مع الجائزة دابة بسرجه ولجامه ولن تنصرف الليلة إلا على مثله فقمت فقبلت يده فأمر لي بألفي دينار آخرين وقال تلك الكرة شكرت على الجائزة بكلام فزدناك والآن شكرت بفعل أوجب الزيادة ولولا أني مضيق في هذا الوقت لضاعفتها ولكن الدهر بيننا مستأنف جديد حدثني جحظة قال حدثني هبة الله بن إبراهيم بن المهدي عن أبيه قال\nلما نزل الرشيد في طريقه إلى طوس بشبداز جلس يشرب عنده فكان إبراهيم الموصلي أول من غناه فابتدأ بهذا الصوت والشعر له صوت\n(رأيت الدين والدنيا ... مقيمين بشبداز)\n(أقاما بين حجاج ... وغاز أيما غاز)\nهو من الثقيل الأول فأمر له بألف دينار ولم يستحسن الشعر وقال له يا إبراهيم صنعتك فيه أحسن من شعرك فخجل وقال يا سيدي شغل خاطري الغناء فقلت لوقتي ما حضرني فضحك الرشيد من قوله وقال له صدقت","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":4,"spl":"الرشيد يحبسه بالرقة ثم يطلقه ليغنيه — نسبه هذا الصوت"},
{"id":"b52-8","bab":"الجزء 5","sec":"كان محبا للأشراف وكان شاعرا وخطيبا","page":"ج5 ص184","text":"أخبرنا يحيى بن علي بن يحيى عن حماد عن أبيه قال كان جدك محبا للأشراف كثير الأصدقاء منه حتى إن كان الرشيد ليقول كثيرا ما أعرف أحد أكثر أصدقاء من إبراهيم قال إسحاق وما سمعت أحسن غناء من أربعة أبي وحكم الوادي وفليح بن أبي العوراء وسياط فقلت له ما بلغ من حذقهم قال كانوا يصنعون فيحسنون ويؤدون غناء غيرهم فيحسنون فقلت فأيهم كان أحذق قال كانوا بمنزلة خطيب أو كاتب أو شاعر يحسن\nصناعته فإذا انتقل عنها إلى غيرها لم يبلغ منها ما يبلغ من صناعته وكان جدك كرجل مفوه إن خطب أجزل وإن كتب رسالة أحسن وإن قال شعرا أحسن ولم يكن فيهم مثله أخبرني الحسين بن يحيى قال حدثنا حماد عن أبيه وأخبرني علي بن عبد العزيز عن ابن خرداذبه وأخبرني إسماعيل بن يونس عن عمر بن شبة جميعا عن إسحاق قال لم يكن الناس يعلمون الجارية الحسناء الغناء وإنما كانوا يعلمونه الصفر والسود وأول من علم الجواري المثمنات أبي فإنه بلغ بالقيان كل مبلغ ورفع من أقدارهن وفيه يقول أبو عيينة بن محمد بن أبي عيينة المهلبي وقد كان هوي جارية يقال لها أمان فأغلى بها مولاها السوم وجعل يرددها إلى إبراهيم وإسحاق ابنه فتأخذ عنهما فكلما زادت في الغناء زاد في سومه فقال أبو عيينة\n(قلت لما رأيت مولى أمان ... قد طغى سومه بها طغيانا)\n(لا جزى الله الموصلي أبا إسحاق ... عنا خيرا ولا إحسانا)\n(جاءنا مرسلا بوحي من الشيطان ... أغلى به علينا القيانا)\n(من عناء كأنه سكرات الحب ... يصبي القلوب والآذانا)\nوقال فيه ابن سيابة صوت\n(ما لإبراهيم في العلم ... بهذا الشأن ثاني)\n(إنما عمر أبي إسحاق ... زين للزمان)\n(جنة الدنيا أبو إسحاق ... في كل مكان)\n(فإذا غنى أبو إسحاق ... اجابته المثاني)\n(منه يجنى ثمر اللهو ... وريحان الجنان)\nإبراهيم في هذا الشعر لحنان خفيف ثقيل بالبنصر وخفيف رمل بالوسطى عن عمرو والهشامي أخبرني عمي عن أحمد بن أبي طاهر عن أبي دعامة قال كان سلم الخاسر عند أبي العتاهية فأخبره سلم أن الرشيد حبس إبراهيم الموصلي في المطبق فأقبل عليه أبو العتاهية فقال\n(سلم يا سلم ليس دونك ستر ... حبس الموصلي فالعيش مر)\n(ما استطاب اللذات مذ سكن المطبق ... رأس اللذات في الناس حر)\n(ترك الموصلي من خلق الله ... جميعا وعيشهم مقشعر)\n(حبس اللهو والسرور فما في الأرض ... شيء يلهى به أو يسر)\nأنشدني بعض أصحابنا عن ابن المرزبان عن أحمد بن أبي طاهر عن ابن أبي فنن لأبي العتاهية يخاطب إبراهيم الموصلي لما حبس\n(أيا غمي لغمك يا خليلي ... ويا ويلي عليك ويا عويلي)\n(يعز علي أنك لا تراني ... وأني لا أراك ولا رسولي)\n(وأنك في محل أذى وضنك ... وليس إلى لقائك من سبيل)\n(وأني لست أملك عنك دفعا ... وقد فوجئت بالخطب الجليل)","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":5,"spl":"كان محبا للأشراف وكان شاعرا وخطيبا — إبراهيم الموصلي وإبراهيم بن المهدي"},
{"id":"b52-9","bab":"الجزء 5","sec":"إبراهيم الموصلي وإبراهيم بن المهدي","page":"ج5 ص187","text":"أخبرني الحسن بن علي الخفاف قال حدثنا محمد بن القاسم بن مهرويه قال حدثنا عبد الله بن عمر قال حدثني أبو توبة صالح بن محمد عن القطراني المغني عن محمد بن جبر وكان المهدي رباه قال حدثني إبراهيم بن المهدي قال انصرفت ليلة من الشماسية فمررت بدار إبراهيم الموصلي وإذا هو في روشن له وقد صنع لحنه\n(ألا رب ندمان علي دموعه ... تفيض على الخدين سحا سجومها)\nهو يعيده ويلعب به بنغمه ويكرره لتستوي له أجزاءه وجواريه يضربن عليه فوقفت تحت الروشن حتى أخذتهم ثم انصرفت إلى منزلي فمازلت أعيده حتى بلغت فيه الغاية وأصبحت فغدوت إلى الشماسية واجتمعنا عند الرشيد فاندفع إبراهيم فغناه أول شيء غنى فلما سمعه الرشيد طرب واستحسنه وشرب عليه ثم قال له لمن هذا يا إبراهيم قال لي يا سيدي صنعته البارحة فقلت كذب يا أمير المؤمنين هذا الصوت قديم وأنا أغنيه فقال لي غنه يا حبيبي فغنيته كما غناه فبهت إبراهيم وغضب\nالرشيد وقال له يا ابن الفاجرة أتكذبني وتدعي ما ليس لك قال فظل إبراهيم بأسوأ حال فلما صليت العصر قلت للرشيد يا أمير المؤمنين الصوت وحياتك له وما كذب ولكني مررت به البارحة وهو يردده على جارية له فوقفت حتى دار لي واستوى فأخذته منه فدعا به الرشيد ورضي عنه وأمر له بخمسة آلاف دينار","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":5,"spl":"كان محبا للأشراف وكان شاعرا وخطيبا — إبراهيم الموصلي وإبراهيم بن المهدي"},
{"id":"b52-10","bab":"الجزء 5","sec":"نسبة هذا الصوت","page":"ج5 ص188","text":"صوت\n(ألا رب ندمان علي دموعه ... تفيض على الخدين سحا سجومها)\n(حليم إذا ما الكأس دارت وهرها ... رجال لديها قد تخف حلومها)\nلغناء لإبراهيم رمل بالسبابة في مجرى البنصر عن إسحاق أخبرني يحيى بن علي بن يحيى قال حدثنا أبي عن طياب بن إبراهيم الموصلي قال كان إبراهيم بن المهدي يقدم ابن جامع ولا يفضل عليه أحدا فأخبرني إبراهيم بن المهدي قال كنا في مجلس الرشيد وقد غلب النبيذ على ابن جامع فغنى صوتا فأخطأ في أقسامه فالتفت إلي إبراهيم فقال قد خري قد خري أستاذك فيه وفهمت صدقه فيما قال قال فقلت له انتبه أيها الشيخ وأعد الصوت ففطن وأعاده وتحفظ فيه وأصاب فغضب إبراهيم وأقبل علي فقال\n(أعلمه الرماية كل يوم ... فلما استد ساعده رماني)\nوتنكر لي وحلف ألا يكلمني فقلت للرشيد بعد أيام إن لي حاجة قال وما هي قلت تأمر إبراهيم الموصلي أن يرضى عني ويعود إلى ما كان عليه فقال ومن إبراهيم حتى يطلب رضاه فقلت يا أمير المؤمنين إن الذي أريده منه لا ينال إلا برضاه فقال قم إليه يا إبراهيم فقبل رأسه فقام إلي ليقبل رأسي فلما أكب علي قال تعود قلت لا قال قد رضيت عنك رضا صحيحا وعاد إلى ما كان عليه أخبرني أبو الحسن أحمد بن يحيى بن علي بن يحيى قال سمعت جدي عليا يحدث عن إسحاق قال قال أبي خرجت مع الرشيد إلى الحيرة فساعة نزل بها دعا بالغداء فتغدى ثم نام فاغتنمت قائلته فذهبت فركبت أدور في ظهر الحيرة فنظرت إلى بستان فقصدته فإذا على بابه شاب حسن الوجه فاستأذنته في الدخول فإذن لي فدخلت فإذا جنة من الجنان في أحسن تربة وأغزرها ماء فخرجت فقلت له لمن هذا البستان فقال لبعض الأشاعثة فقلت له أيباع فقال نعم وهو على سوم فقلت كم بلغ فقال أربعة عشر ألف دينار قلت وما يسمى هذا الموضع قال شمارى فقلت صوت\n(جنان شمارى ليس مثلك منظر ... لذي رمد أعيا عليه طبيب)\n(ترابك كافور ونورك زهرة ... لها أرج بعد الهدو يطيب)\nقال وحضرتني فيه صنعة حسنة فلما جلس الرشيد وأمر بالغناء غنيته إياه أول ما غنيت فقال ويلك وأين شمارى فأخبرته القصة فأمر لي بأربعة عشر ألف دينار وغمزني جعفر بن يحيى فقال خذ توقيعه بها إلي وتشاغل الرشيد عني فأعدت الصوت فقال ويلكم أعطوا هذا دنانيره فوثبت وقلت يا سيدي وقع لي بها إلى جعفر بن يحيى فقال أفعل ووقع لي بها إليه فلما حصل التوقيع عند جعفر أطلق لي المال وخمسة آلاف دينار من عنده فلما حصل المال عندي كان أحب إلي وأحسن في عيني من شمارى أخبرني جعفر بن قدامة قال أخبرني أبو العيناء قال خرج الفضل بن الربيع يوما من حضرة الرشيد ومعه رقعة فيها أربعة أبيات فقال إن أمير المؤمنين يأمر كل من حضر ممن يقول الشعر أن يجيزها وهي\n(أهدى الحبيب مع الجنوب سلامه ... فاردد إليه مع الشمال سلاما)\n(واعرف بقلبك ما تضمن قلبه ... وتداولا بهواكما الأياما)\n(وإذا بكيت له فأيقن أنه ... ستجود أدمعه عليك رهاما)\n(فاحبس دموعك رحمة لدموعه ... إن كنت تحفظ أو تحوط ذماما)\nفلم يوجد من يجيزها فأمر إبراهيم فغنى فيها لحنا من خفيف الثقيل أخبرني محمد بن خلف وكيع قال حدثني أبو العباس البصري قال حدثني عبد الله بن الفضل بن الربيع قال سمعت أبي يقول لما خرج الرشيد إلى الرقة أخرج معه إبراهيم الموصلي وكان به مشغوفا ففقده في بعض المنازل أياما وطلبه فلم يخبره أحد بقصته ثم أتاه فقال له ويحك ما خبرك وأين كانت غيبتك فقال يا أمير المؤمنين حديثي عجيب نزلنا بموضع كذا وكذا فوصف لي خمار من ظرفه ومن نظافة منزله كيت وكيت فتقدمت أمام ثقلي وأتيته مخفا فوافيت أطيب منزل وأوسع رحل وأطيب طعام وأسخى نفس من شاب حسن الوجه ظريف العشرة فأقمت عنده فلما أردت اللحاق بأمير المؤمنين أقسم علي وأخرج لي من الشراب ما هو أطيب وأجود مما رأيت فأقمت ثلاثا ووهبت له دنانير كانت معي وكسوة وقلت فيه صوت\n(سقيا لمنزل خمار قصفت به ... وسط الرصافة يوما بعد يومين)\n(ما زلت أرهن أثوابي وأشربها ... صفراء قد عتقت في الدن حولين)\n(حتى إذا نفدت مني بأجمعها ... عاودته بالربا دنا بدنين)\n(فقال إزل بشين حين ودعني ... وقد لعمرك زلنا عنه بالشين)\nالشعر والغناء لإبراهيم خفيف رمل بالبنصر قوله إزل بشين كلمة سريانية تفسيرها امض بسلام دعا له بها لما ودعه قال","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":6,"spl":"نسبة هذا الصوت"},
{"id":"b52-11","bab":"الجزء 5","sec":"نسبة هذا الصوت","page":"ج5 ص188","text":"إبراهيم فقال لي الرشيد غني هذا الصوت فعنيته إياه وزمر عليه برصوما فوهب لي الرشيد مائة ألف درهم وأقطعني ضيعة وبعث إلى الخمار فأحضر وأهدى إلى الرشيد من ذلك الشراب فوصله ووهب له إبراهيم عشرة آلاف درهم","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":7,"spl":"نسبة هذا الصوت — إبراهيم الموصلي وابن جامع"},
{"id":"b52-12","bab":"الجزء 5","sec":"إبراهيم الموصلي وابن جامع","page":"ج5 ص192","text":"أخبرني الحسين بن يحيى ومحمد بن مزيد ووكيع قالوا جميعا حدثنا حماد بن إسحاق قال حدثني أبي قال قال ابن جامع يوما لأبي رأيت في منامي كأني وإياك راكبان في محمل فسفلت حتى كدت تلصق بالأرض وعلا الشق الذي أنا فيه فلأعلونك في الغناء فقال إبراهيم الرؤيا حق والتأويل باطل إني وإياك كنا في ميزان فرجحت بك وشالت كفتك وعلوت فلصقت بالأرض فلأبقين بعدك ولتموتن قبلي قال إسحاق فكان كما قال أبي علا عليه وأفاد أكثر من فوائده ومات ابن جامع قبله وعاش أبي بعده أخبرني عبد الله بن الربيع الربيعي قال حدثتني خديجة بنت هارون بن عبد الله بن الربيع قالت حدثتني خمار جارية أبي وكانت قندهارية اشتراها جدي عبد الله وهي صبية ريض من آل يحيى بن معاذ بمائتي ألف درهم قالت\nألقى علي إبراهيم الموصلي لحنه في هذين البيتين صوت\n(إذا سرها أمر وفيه مساءتي ... قضيت لها فيما تريد على نفسي)\n(وما مر يوم أرتجي فيه راحة ... فأذكره إلا بكيت على أمس)\nلشعر لأبي حفص الشطرنجي والغناء لإبراهيم ثقيل أول بالوسطى فسمعني ابن جامع يوما وأنا أغنيه فسألني ممن أخذته فأخبرته فقال أعيديه فأعدته مرارا وما زال ابن جامع يتنغم به معي حتى ظننت أنه قد أخذه ثم كان كلما جاءنا قال لي يا صبية غني ذلك الصوت فكان صوته علي","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":7,"spl":"نسبة هذا الصوت — إبراهيم الموصلي وابن جامع"},
{"id":"b52-13","bab":"الجزء 5","sec":"إبراهيم الموصلي ومخارق","page":"ج5 ص193","text":"أخبرني إسماعيل بن يونس قال حدثني عمر بن شبة قال قال مخارق أذن لنا أمير المؤمنين الرشيد أن نقيم في منازلنا ثلاثة أيام وأعلمنا أنه مشتغل فيها مع الحرم فمضى الجلساء أجمعون إلى منازلهم وأخبرني وسواسة وهو أحمد بن محمد بن إسماعيل بن إبراهيم الموصلي بهذا الخبر فقال حدثني أبي عن أبيه عن مخارق قال اشتغل الرشيد يوما واصطبح مع الحرم وقد أصبحت السماء متغيمة فانصرفنا إلى منازلنا ولم يذكر في الخبر ما ذكره عمر بن شبة مما قدمت ذكره واتفقا هاهنا في أكثر الحكايات واللفظ فأكثره لرواية ابن الموصلي قال مخارق وأصبحت السماء متغيمة تطش طشا خفيفا فقلت والله لأذهبن إلى أستاذي إبراهيم فأعرف خبره ثم\nأعود فأمرت من عندي أنا يسووا مجلسا لنا إلى وقت رجوعي فجئت إلى إبراهيم الموصلي فإذا الباب مفتوح والدهليز قد كنس والبواب قاعد فقلت ما خبر أستاذي فقال ادخل فدخلت فإذا هو جالس في رواق له وبين يديه قدور تغرغر وأباريق تزهر والستارة منصوبة والجواري خلفها وإذا قدامه طست فيه رطلية وكوز وكأس فدخلت أترنم ببعض الأصوات وقلت له ما بال الستارة لست أسمع من ورائها صوتا فقال اقعد ويحك إني أصبحت على الذي ظننت فأتاني خبر ضيعة تجاورني قد والله طلبتها زمانا وتمنيتها فلم أملكها وقد أعطي بها مائة ألف درهم فقلت وما يمنعك منها فوالله لقد أعطاك الله أضعاف هذا المال وأكثر قال صدقت ولكن لست أطيب نفسا أن أخرج هذا المال فقلت فمن يعطيك الساعة مائة ألف درهم والله ما أطمع في ذلك من الرشيد فكيف بمن دونه فقال اجلس خذ هذا الصوت ونقر بقضيب معه على الدواة وألقى علي صوت\n(نام الخليون من هم ومن سقم ... وبت من كثرة الأحزان لم أنم)\n(يا طالب الجود والمعروف مجتهدا ... اعمد ليحني خليف الجود والكرم)\nلشعر لأبي النضير والغناء لإبراهيم الموصلي ثقيل أول بالبنصر\nقال فأخذته فأحكمته ثم قال لي امض الساعة إلى باب الوزير يحيى بن خالد فإنك تجد الناس عليه وتجد الباب قد فتح ولم يجلس بعد فاستاذن عليه قبل أن يصل إليه أحد فإنه سينكر عليك مجيئك ويقول من أين أقبلت في هذا الوقت فحدثه بقصدك إياي وما ألقيت إليك من خبر الضيعة وأعلمه أني صنعت هذا الصوت وأعجبني ولم أر أحدا يستحقه إلا فلانة جاريته وأني ألقيته عليك حتى أحكمته لتطرحه عليها فسيدعو بها ويأمر بالستارة أن تنصب ويوضع له كرسي ويقول لك اطرحه عليها بحضرتي فافعل وأتني بالخبر بعد ذلك قال فجئت باب يحيى فوجدته كما وصف وسألني فأعلمته ما أمرني به ففعل كل شيء قاله لي إبراهيم وأحضر الجارية فألقيته عليها ثم قال لي تقيم عندنا يا أبا المهنأ أو تنصرف فقلت أنصرف أطال الله بقاءك فقد علمت ما أذن لنا فيه قال يا غلام احمل مع أبي المهنأ عشرة آلاف درهم واحمل إلى أبي إسحاق مائة ألف درهم ثمن هذه الضيعة فحملت العشرة الآلاف الدرهم إلي وأتيت منزلي فقلت أسر يومي هذا وأسر من عندي ومضى الرسول إليه بالمال فدخلت منزلي ونثرت على من عندي من الجواري دراهم من تلك البدرة وتوسدتها وأكلت وشربت وطربت وسررت يومي كله فلما أصبحت قلت والله لآتين أستاذي ولأعرفن خبره فأتيته فوجدت الباب كهيئته بالأمس ودخلت فوجدته على مثل ما كان عليه فترنمت وطربت فلم يتلق ذلك بما يجب فقلت له ما الخبر ألم يأتك المال قال بلى\nفما كان خبرك أنت بالأمس فأخبرته بما كان وهب لي وقلت ما ينتظر من خلف الستارة فقال ارفع السجف فرفعته فإذا عشر بدر فقلت وأي شيء بقي عليك في أمر الضيعة قال ويحك ما هو والله إلا أن دخلت منزلي حتى شححت عليها فصارت مثل ما حويت قديما فقلت سبحان الله العظيم فتصنع ماذا قال قم حتى ألقي عليك صوتا صنعته يفوق ذلك الصوت فقمت وجلست بين يديه فألقى علي صوت\n(ويفرح بالمولود من آل برمك ... بغاة الندى والسيف والرمح ذو النصل)\n(وتنبسط الآمال فيه لفضله ... ولا سيما إن كان من ولد الفضل)","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":8,"spl":"إبراهيم الموصلي ومخارق"},
{"id":"b52-14","bab":"الجزء 5","sec":"إبراهيم الموصلي ومخارق","page":"ج5 ص193","text":"لشعر لأبي النضير والغناء لإبراهيم ثقيل أول بالبنصر عن الهشامي وذكر عمرو بن بانة أنه لإسحاق وهو الصحيح وفيه خفيف ثقيل أظنه لحن إبراهيم أخبرني إسماعيل بن يونس عن عمر بن شبة عن إسحاق أن أباه صنع هذا الصوت في طريقه خفيف الثقيل وعرضه على الفضل فاستحسنه وأمر مخارقا بإلقائه على جواريه فألقاه فى مراقش وقضيب فأخذتاه عنه قال مخارق فلما ألقى علي الصوت سمعت ما لم أسمع مثله قط وصغر عندي الأول فأحكمته ثم قال انهض الساعة إلى الفضل بن يحيى فإنك تجده لم يأذن لأحد بعد وهو يريد الخلوة مع جواريه اليوم فاستأذن عليه وحدثه بحديثنا أمس وما كان من أبيه إلينا وإليك وأعلمه أني قد صنعت هذا الصوت وكان عندي أرفع منزلة من الصوت الذي صنعته بالأمس وأني ألقيته عليك حتى أحكمته ووجهت بك قاصدا لتلقيه على فلانة جاريته فصرت إلى باب الفضل فوجدت الأمر على ما ذكر فاستأذنت فوصلت وسألني ما الخبر فأعلمته بخبري في اليوم الماضي وما وصل إلي وإليه من المال فقال أخزى الله إبراهيم فما أبخله\nعلى نفسه ثم دعا خادما فقال اضرب الستارة فضربها فقال لي ألقه فلما غنيته لم أتمه حتى أقبل يجر مطرفه ثم قعد على وسادة دون الستارة وقال أحسن والله أستاذك وأحسنت أنت يا مخارق فلم أخرج حتى أخذته الجارية وأحكمته فسر بذلك سرورا شديدا وقال أقم عندي اليوم فقلت يا سيدي إنما بقي لنا يوم واحد ولولا أني أحب سرورك لم أخرج من منزلي فقال يا غلام احمل مع أبي المهنأ عشرين ألف درهم واحمل إلى إبراهيم مائتي ألف درهم فانصرفت إلى منزلي بالمال ففتحت بدرة فنثرت منها على الجواري وشربت وسررت أنا ومن عندي يومنا فلما أصبحت بكرت إلى إبراهيم أتعرف خبره وأعرفه خبري فوجدته على الحال التي كان عليها أولا وآخرا فدخلت أترنم وأصفق فقال لي ادن فقلت ما بقي فقال اجلس وارفع سجف هذا الباب فإذا عشرون بدرة مع تلك العشر فقلت ما تنتظر الآن فقال ويحك ما هو والله إلا أن حصلت حتى جرت مجرى ما تقدم فقلت والله ما أظن أحدا نال في هذه الدولة ما نلته فلم تبخل على نفسك بشيء تمنيته دهرا وقد ملكك الله أضعافه ثم قال اجلس فخذ هذا الصوت وألقى علي صوتا أنساني والله صوتي الأولين صوت\n(أفي كل يوم أنت صب وليلة ... إلى أم بكر لا تفيق فتقصر)\n(أحب على الهجران أكناف بيتها ... فيا لك من بيت يحب ويهجر)\n(إلى جعفر سارت بنا كل جسرة ... طواها ثراها نحوه والتهجر)\n(إلى واسع للمجتدين فناؤه ... تروح عطاياه عليهم وتبكر)\nالشعر لمروان بن أبي حفصة يمدح به جعفر بن يحيى والغناء لإبراهيم ولم تقع إلينا طريقته قال مخارق ثم قال لي إبراهيم هل سمعت مثل هذا فقلت ما سمعت قط مثله فلم يزل يردده علي حتى أخذته ثم قال لي امض إلى جعفر فافعل به كما فعلت بأخيه وأبيه قال فمضيت ففعلت مثل ذلك وخبرته ما كان منهما وعرضت عليه الصوت فسر به ودعا خادما فأمره بضرب الستارة وأحضر الجارية وقعد على كرسي ثم قال هات يا مخارق فاندفعت فألقيت الصوت عليها حتى أخذته فقال أحسنت والله يا مخارق وأحسن أستاذك فهل لك في المقام عندنا اليوم فقلت يا سيدي هذا آخر أيامنا وإنما جئت لموقع الصوت مني حتى ألقيته على الجارية فقال يا غلام احمل معه ثلاثين ألف درهم وإلى الموصلي ثلاثمائة ألف درهم فصرت إلى منزلي بالمال فأقمت ومن معي مسرورين نشرب بقية يومنا ونطرب ثم بكرت إلى إبراهيم فتلقاني قائما وقال لي أحسنت يا مخارق فقلت ما الخبر فقال اجلس فجلست فقال لمن خلف الستارة خذوا فيما أنتم فيه ثم رفع السجف فإذا المال فقلت ما خبر الضيعة فأدخل يده تحت مسورة هو متكئ عليها فقال هذا صك الضيعة سئل عن صاحبها فوجد ببغداد فاشتراها منه يحيى بن خالد وكتب إلي قد علمت أنك لا تسخو نفسا بشراء الضيعة من مال يحصل لك ولو حيزت لك الدنيا كلها وقد ابتعتها لك من مالي ووجهت لك بصكها ووجه إلي بصكها وهذا المال كما ترى ثم بكى وقال لي\nيا مخارق إذا عاشرت فعاشر مثل هؤلاء وإذا خنكرت فخنكر لمثل هؤلاء هذه ستمائة ألف وضيعة بمائة ألف وستون ألف درهم لك حصلنا ذلك اجمع وأنا جالس في مجلسي لم أبرح منه فمتى يدرك مثل هؤلاء","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":9,"spl":"إبراهيم الموصلي ومخارق"},
{"id":"b52-15","bab":"الجزء 5","sec":"إبراهيم الموصلي وموسى الهادي","page":"ج5 ص199","text":"أخبرني يحيى بن علي بن يحيى قال أخبرني أبي عن إسحاق قال كان موسى الهادي شكس الأخلاق صعب المزاج من توقاه وعرف أخلاقه أعطاه ما أمل ومن فتح فاه فاتفق له أن يفتحه بغير ما يهواه أقصاه وأطرحه فكان لا يحتجب عن ندمائه ولا عن المغنين وكان يكثر جوائزهم وصلاتهم ويواترها فتغنى أبي عنده يوما فقال له يا إبراهيم غنني جنسا من الغناء ألذ به وأطرب له ولك حكمك فقال يا أمير المؤمنين إن لم يقابلني زحل ببرده رجوت أن أصيب ما في نفسك قال وكنت لا أراه يصغي إلى شيء من الأغاني إصغاءه إلى النسيب والرقيق منه وكان مذهب ابن سريج عنده أحمد من مذهب معبد فغنيته\n(وإني لتعروني لذكراك هزة ... كما انتفض العصفور بلله القطر)\nضرب بيده إلى جيب دراعته فحطها ذراعا ثم قال أحسنت والله زدني فغنيت\n(فيا حبها زدني جوى كل ليلة ... ويا سلوة الأيام موعدك الحشر)\nضرب بيده إلى دراعته فحطها ذراعا آخر أو نحوه وقال زدني ويلك أحسنت والله ووجب حكمك يا إبراهيم فغنيت\n(هجرتك حتى قيل لا يعرف الهوى ... وزرتك حتى قيل ليس له صبر)\nرفع صوته وقال أحسنت لله أبوك هات ما تريد قلت يا سيدي عين مروان بالمدينة فدارت عيناه في رأسه حتى صارتا كأنهما جمرتان وقال يابن اللخناء أردت أن تشهرني بهذا المجلس فيقول الناس أطربه فحكمه فتجعلني سمرا وحديثا يا إبراهيم الحراني خذ بيد هذا الجاهل إذا قمت فأدخله في بيت مال الخاصة فإن أخذ كل ما فيه فخله وإياه فدخلت فأخذت خمسين ألف دينار","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":10,"spl":"إبراهيم الموصلي وموسى الهادي — نسبة هذا الصوت"},
{"id":"b52-16","bab":"الجزء 5","sec":"نسبة هذا الصوت","page":"ج5 ص200","text":"صوت\n(عجبت لسعي الدهر بيني وبينها ... فلما انقضى ما بيننا سكن الدهر)\n(فيا حبها زدني جوى كل ليلة ... ويا سلوة الأيام موعدك الحشر)\n(ويا هجر ليلى قد بلغت بي المدى ... وزدت على ما ليس يبلغه الهجر)\n(وإني لتعروني لذكراك هزة ... كما انتفض العصفور بللة القطر)\n(هجرتك حتى قيل لا يعرف الهوى ... وزرتك حتى قيل ليس له صبر)\n(أما والذي أبكى وأضحك والذي ... أمات وأحيا والذي أمره أمر)\n(لقد تركتني أحسد الوحش أن أرى ... أليفين منها لا يروعهما الذعر)\nلشعر لأبي صخر الهذلي والغناء لمعبد وأول لحنه يا هجر ليلى وبعده الثاني ثم الأول من الأبيات ثاني ثقيل بالبنصر عن عمرو ولابن\nسريج في السادس والسابع والرابع والخامس ثقيل أول عن الهشامي ولعريب في السادس والسابع والرابع والخامس ثقيل أول أيضا وللواثق فيها رمل وهو مما صنعه الواثق قبلها فعارضته بلحنها وقد نسب قوم لحن معبد إلى ابن سريج ولحن ابن سريج إلى معبد أخبرني الحسين بن يحيى عن حماد بن إسحاق عن أبيه قال اشترى جدك إبراهيم لجعفر بن يحيى جارية مغنية بمال عظيم فقال جعفر أي شيء تحسن هذه الجارية حتى بلغت بها هذا المال كله قال لو لم تحسن شيئا إلا أنها تحكي قولي\n(لمن الديار ببرقة الروحان ... )\nكانت تساويه وزيادة فضحك جعفر وقال أفرطت","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":10,"spl":"إبراهيم الموصلي وموسى الهادي — نسبة هذا الصوت","partial":1},
{"id":"b52-17","bab":"الجزء 5","sec":"نسبة هذا الصوت","page":"ج5 ص201","text":"صوت\n(لمن الديار ببرقة الروحان ... إذ لا نبيع زماننا بزمان)\n(صدع الغواني إذ رمين فؤاده ... صدع الزجاجة ما لذاك تدان)\n(إن زرت أهلك لم أنول حاجة ... وإذا هجرتك شفني هجراني)\nلغناء لمعبد فيما ذكره الهشامي وأحمد بن المكي ثقيل أول\nبالوسطى ونسبه غيرهما إلى حنين وقال آخرون إنه للغريض وذكر حبش أنه ليزيد حوراء وفيه لإبراهيم خفيف رمل بالبنصر أخبرني الحسين عن حماد قال قال لي أبي صنع جدك تسعمائة صوت منها دينارية ومنها درهمية ومنهما فلسية وما رأيت أكثر من صنعة فأما ثلاثمائة منها فإنه تقدم الناس جميعا فيها وأما ثلاثمائة فشاركوه وشاركهم فيها وأما الثلاثمائة الباقية فلعب وطرب قال ثم أسقط أبي الثلاثمائة الآخرة بعد ذلك من غناء أبيه فكان إذا سئل عن صنعته أبيه قال هي ستمائة صوت وقال أحمد بن حمدون قال لي إسحاق من غناء أبي الذي أكرهه واستزريه صوته في شعر العباس بن الأحنف\n(أبكي ومثلي بكى من حب جارية ... )\nما أعلم له فيه معنى إلا استحسانه للشعر فإن العباس أحسن فيه جدا","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":10,"spl":"إبراهيم الموصلي وموسى الهادي — نسبة هذا الصوت","partial":1},
{"id":"b52-18","bab":"الجزء 5","sec":"نسبة هذا الصوت","page":"ج5 ص202","text":"صوت\n(أبكي ومثلي بكى من حب جارية ... لم يخلق الله لي في قلبها لينا)\n(هل تذكرين وقوفي عند بابكم ... نصف النهار وأهل الدار لاهونا)\nالشعر للعباس بن الأحنف والغناء لإبراهيم خفيف رمل بالوسطى أخبرني جحظة قال أخبرني حماد بن إسحاق قال قال رجل لأبي أخبرني عنك لم طعنت على أبيك في صنعته\n(قال لي فيها عتيق مقالا ... فجرت مما يقول الدموع)\nقال لأنه تعرض لابن عائشة وله في هذا الشعر صنعة وابن عائشة ممن لا يعارض فلم يقاربه وعلى أن صنعة أبي من جيد الغناء لو كان صنعها في غير هذا الشعر ولكنها اقترنت بصنعة ابن عائشة فلم تقاربها فسقط عندي لذلك","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":11,"spl":"نسبة هذا الصوت — المهدي يرق له ويطلقه من الحبس"},
{"id":"b52-19","bab":"الجزء 5","sec":"نسبة هذا الصوت","page":"ج5 ص203","text":"صوت\n(قال لي فيها عتيق مقالا ... فجرت مما يقول الدموع)\n(قال لي ودع سليمى ودعها ... فأجاب القلب لا أستطيع)\nلشعر لعمر بن أبي ربيعة والغناء لمعبد ثقيل أول بالوسطى عن عمرو وقيل إنه لابن عائشة وفيه ثاني ثقيل ينسب إلى الهذلي وفيه خفيف ثقيل ينسب إلى ابن عائشة وإلى إبراهيم أخبرني الحسن بن علي قال أخبرني عبد الله بن أبي سعد قال حدثني محمد بن عبد الله بن مالك قال حدثني إسحاق عن أبيه قال دخلت الري فكنت آلف فتيانا من أهل النعم بها وهم لا يعرفونني\nفطال ذلك علي إلى أن دعاني أحدهم ليلة إلى منزله فبت عنده فأخرج جارية له ومد لها ستارة فتغنت خلفها فرأيتها صالحة الأداء كثيرة الرواية فشوقتني إلى العراق وذكرتني أيامي بها فدعوت بعود فلما جيء به اندفعت فغنيت صوتي في شعري\n(أنا بالري مقيم ... في قرى الري أهيم)\nقد كنت صنعت هذا اللحن قديما بالري فخرجت الجارية من وراء الستارة مبادرة إلي فأكبت على رأسي وقالت أستاذي والله فقال لها مولاها أي أستاذيك هذا قالت إبراهيم الموصلي فإذا هي إحدى الجواري اللاتي أخذن عني وطال العهد بها فأكرمني مولاها وبرني وخلع علي فأقمت مدة بعد ذلك بالري وانتشر خبري بها ثم كتب بحملي إلى والي البلد فأشخصت","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":11,"spl":"نسبة هذا الصوت — المهدي يرق له ويطلقه من الحبس"},
{"id":"b52-20","bab":"الجزء 5","sec":"المهدي يرق له ويطلقه من الحبس","page":"ج5 ص204","text":"أخبرني الحسن قال حدثنا عبد الله بن أبي سعد قال حدثني أبو توبة صالح بن محمد قال حدثني القطراني عن محمد بن جبر عن يحيى المكي قال كنا يوما بين يدي المهدي وقد حبس إبراهيم الموصلي وضربه وأمر بأن يلبس جبة صوف وكان يخرج على تلك الحال فيطرح على الجواري فكتب إلينا ذات يوم ونحن مصطبحون وقد جادت السماء بمطر صيف وبحضرتنا شيء من ورد مبكر\n(ألا من مبلغ قوما ... من اخواني وجيراني)\n(هنيئا لكم الشرب ... على ورد وتهتان)\n(وأني مفرد وحدي ... بأشجاني وأحزاني)\n(فمن جف له جفن ... فجفناي يسيلان)\nال فوقف المهدي على رقعته وقرأها فرق له وأمر بطلبه في الوقت ثم أطلقه بعد بأيام أخبرني الحسن قال حدثنا هارون بن محمد بن عبد الملك قال حدثني ابن المكي عن أبيه قال كانت لعلي اليماني جارية مغنية فهويها إبراهيم واستهيم بها زمانا وقال فيها صوت\n(كنت حرا فصرت عبد اليماني ... من هوى شادن هواه براني)\n(وهو نصفان من قضيب ودعص ... زان صدر القضيب رمانتان)\nللحن لإبراهيم في هذين البيتين ثاني ثقيل بالبنصر عن عمرو وقد زعم قوم أن الشعر للحسين بن الضحاك\nأخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة عن إسحاق قال كان بعض أهل نهيك قد تعاطى الغناء فلما ظن أنه قد أحكمه شاورني وأبي حاضر فقلت له إن قبلت مني فلا تغن فلست فيه كما أرضى فصاح أبي علي صيحة شديدة ثم قال لي وما يدريك يا صبي ثم أقبل على الرجل فقال أنت يا حبيبي بضد ما قال وإن لزمت الصناعة برعت فيها فلما خلا بي قال لي يا أحمق ما عليك أن يخزي الله مائة ألف مثل هذا هؤلاء أغنياء ملوك وهم يعيروننا بالغناء فدعهم يتهتكوا به ويعيروا ويفتضحوا ويحتاجوا إلينا فننتفع بهم ويبين فضلنا لدى الناس بأمثالهم قال ولزمه النهيكي يأخذ عنه ويبره فيجزل فكان إذا غنى فأحسن قال له بارك الله فيك وإذا أساء قال بارك الله عليك وكثر ذلك منه حتى عرف النهيكي معناه فيه فغنى يوما وأبي ساه فسكت ولم يقل له شيئا فقال له جعلت فداك يا أستاذي أهذا الصوت من أصوات فيك أم عليك فضحك أبي ولم يكن علم أنه قد فطن لقوله ثم قال له والله لأقبلن عليك حتى تصير كما تشتهي فأنك ظريف أديب وعني به حتى حسن غناؤه وتقدم وفيه يقول أبي\n(أوجب الله لك الحق ... على مثلي بظرفك)\n(لن تراني بعد هذا ... ناطقا إلا بوصفك)\n(وترى القوة فيما ... تشتهيه بعد ضعفك)","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":11,"spl":"نسبة هذا الصوت — المهدي يرق له ويطلقه من الحبس"},
{"id":"b52-21","bab":"الجزء 5","sec":"إبراهيم الحاذق العالم بالغناء وأصوله","page":"ج5 ص206","text":"أخبرني إسماعيل قال حدثني عمر بن شبة عن إسحاق أخبرني به الصولي عن عون بن محمد عن إسحاق قال غنى مخارق بين يدي الرشيد صوتا فأخطأ في قسمته فقلت له أعد\nفأعاده وكان الخطأ خفيا فقلت للرشيد يا سيدي قد أخطأ فيه فقال لإبراهيم بن المهدي ما تقول فيما ذكره إسحاق قال ليس الأمر كما قال ولا هاهنا خطأ فقلت له أترضى بأبي قال إي والله وكان أبي في بقايا علة فأمر الرشيد بإحضاره ولو محمولا فجيء به محفة فقال لمخارق أعد الصوت فأعاده فقال ما عندك يا إبراهيم في هذا الصوت فقال قد أخطأ فيه فقال له هكذا قال ابنك إسحاق وذكر أخي إبراهيم أنه صحيح فنظر إلي ثم قال هاتوا دواة فأتي بها وكتب شيئا لم يقف عليه أحد ثم قطعه ووضعه بين يدي الرشيد وقال لي اكتب بذكر الموضع الفاسد من قسمة هذا الصوت فكتبته وألقيته فقرأه وسر وقام فألقاه بين يدي الرشيد فإذا الذي قلناه جميعا متفق فضحك وعجب ولم يبق أحد في المجلس إلا قرظ وأثنى ووصف ولا أحد خالف إلا خجل وذل وأذعن وقال أبي في ذلك\n(ليت من لا يحسن العلم ... كفانا شر علمه)\n(فاخبر الحق ابتداء ... وقس العلم بفهمه)\n(طيب الريحان لا تعرفه ... إلا بشمه)\nحدثني جحظة قال حدثني هبة الله وحدثني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه قال غنى أبي يوما بحضرة الرشيد\n(سلي هل قلاني من عشير صحبته ... وهل ذم رحلي في الرفاق رفيق)\nطرب واستعاده وأمر له بعشرين ألف درهم فلما كان بعد سنين\nخطر ببالي ذلك الصوت وذكرت قصته فغنيته إياه فطرب وشرب ثم قال لي يا إسحاق كأني في نفسك ذكرت حديث أبيك وأني أعطيته ألف دينار على هذا الصوت فطمعت في الجائزة فضحكت ثم قلت والله يا سيدي ما أخطأت فقال قد أخذ ثمنه أبوك مرة فلا تطمع فعجبت من قوله ثم قلت يا سيدي قد أخذ أبي منك أكثر من مائتي ألف دينار ما رأيتك ذكرت منها غير هذا الألف على بختي أنا فقال ويحك أكثر من مائتي ألف دينار قلت إي والله فوجم وقال أستغفر الله من ذلك ويحك فما الذي خلف منها قلت خلف علي ديونا مبلغها خمسة آلاف دينار قضيتها عنه فقال ما أدري أينا أشد تضييعا والله المستعان","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":12,"spl":"إبراهيم الحاذق العالم بالغناء وأصوله — كان يحفظ حتى صوت القطط"},
{"id":"b52-22","bab":"الجزء 5","sec":"نسبة هذا الصوت","page":"ج5 ص208","text":"صوت\n(سلي هل قلاني من عشير صحبته ... وهل ذم رحلي في الرفاق رفيق)\n(وهل يجتوي القوم الكرام صحابتي ... إذا اغبر مخشي الفجاج عميق)\n(ولو تعلمين الغيب أيقنت أنني ... لكم والهدايا المشعرات صديق)\nلشعر ينسب إلى مضرس بن قرط الهلالي وإلى قيس بن ذريح وفيه بيت يقال إنه لجرير والغناء مختلط في أشعار الثلاثة المذكورين\nونسبته تأتي في أخبار قيس بن ذريح إلا أن الغناء في هذه الثلاثة الأبيات لمعبد ثقيل أول بالخنصر في مجرى البنصر عن إسحاق","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":12,"spl":"إبراهيم الحاذق العالم بالغناء وأصوله — كان يحفظ حتى صوت القطط"},
{"id":"b52-23","bab":"الجزء 5","sec":"كان يحفظ حتى صوت القطط","page":"ج5 ص209","text":"أخبرني عمي قال حدثني عبد الله بن أبي سعد قال حدثتني نشوة الأشنانية قالت أخبرني أبو عثمان يحيى المكي قال تشوق يوما إبراهيم الموصلي إلى سرداب له وكانت فيه بركة ماء تدخل من موضع إليه وتخرج إلى بستان فقال أشتهي أن أشرب يومي وأبيت ليلتي في هذا السرداب ففعل ذلك فبينا هو نائم في نصف الليل فإذا سنورتان قد نزلتا من درجة السرداب بيضاء وسوداء فقالت إحداهما أتراه نائما فقالت السوداء هو نائم فاندفعت السوداء فغنت بأحسن صوت\n(عفا مزج إلى لصق ... إلى الهضبات من هكر)\n(إلى قاع النقير إلى ... قرار جلال ذي حدر)\nقال فمات إبراهيم فرحا وقال يا ليتهما أعاداه فأعاداه مرارا حتى أخذه ثم تحرك فقامت السنورتان وسمع إحداهما تقول للأخرى والله لا طرحه على أحد إلا جن فطرحه من غد على جارية له فجنت","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":12,"spl":"إبراهيم الحاذق العالم بالغناء وأصوله — كان يحفظ حتى صوت القطط"},
{"id":"b52-24","bab":"الجزء 5","sec":"نسبة هذا الصوت","page":"ج5 ص210","text":"الغناء فيه لمالك ثقيل أول بالوسطى عن يحيى المكي وعمرو بن بانة أخبرني الحسن بن علي وعمي قالا حدثنا عبد الله بن أبي سعد قال حدثني محمد بن عبد الله بن مالك قال حدثني أبو محمد إسحاق بن إبراهيم عن أبيه قال أتيت الفضل بن يحيى يوما فقلت له يا أبا العباس جعلت فداك هب لي دراهم فإن الخليفة قد حبس يده فقال ويحك يا أبا إسحاق ما عندي مال أرضاه لك ثم قال هاه إلا أن ها هنا خصلة أتانا رسول صاحب اليمن فقضينا حوائجه ووجه إلينا بخمسين ألف دينار يشتري لنا بها محبتنا فما فعلت ضياء جاريتك قلت عندي جعلت فداك قال فهو ذا أقول لهم يشترونها منك لا تنقصها من خمسين ألف دينار فقبلت رأسه ثم انصرفت فبكر علي رسول صاحب اليمن ومعه صديق لي فقال جاريتك فلانه عندك فقلت عندي فقال اعرضها علي فأخرجتها قال بكم قلت بخمسين ألف دينار ولا أنقص منها دينارا واحدا وقد أعطاني بها الفضل بن يحيى أمس هذه العطية فقال لي أريدها له فقلت له أنت أعلم إذا اشتريتها فصيرها لمن شئت فقال لي هل لك في ثلاثين ألف دينار مسلمة لك قال وكان شراء الجارية على أربعمائة دينار فلما وقع في أذني ذكر ثلاثين ألف أرتج علي ولحقني زمع وأشار علي صديقي الذي معه بالبيع وخفت والله أن\nيحدث بالجارية حدث أو بي أو بالفضل بن يحيى فسلمتها وأخذت المال ثم بكرت على الفضل بن يحيى فإذا هو جالس وحده فلما نظر إلي ضحك ثم قال لي يا ضيق الحوصلة حرمت نفسك عشرين ألف دينار فقلت له جعلت فداك دع ذا عنك فوالله لقد دخلني شيء أعجز عن وصفه وخفت أن تحدث بي حادثة أو بالجارية أو بالمشتري أو بك أعاذك الله من كل سوء فبادرت بقبول الثلاثين ألف دينار فقال لا ضير يا غلام جئ بالجارية فجاء بجاريتي بعينها فقال خذها مباركا لك فيها فإنما أردنا منفعتك ولم نرد الجارية فلما نهضت قال لي مكانك إن صاحب إرمينية قد جاءنا فقضينا حوائجه ونفذنا كتبه وذكر أنه قد جاءنا بثلاثين ألف دينار يشتري لنا بها ما نحب فاعرض عليه جاريتك هذه ولا تنقصها من ثلاثين ألف دينار فانصرفت بالجارية وبكر إلي رسول صاحب إرمينية ومعه صديق لي آخر فقاولني بالجارية فقلت لست أنقصها من ثلاثين ألف دينار فقال لي معي على الباب عشرون ألف دينار تأخذها مسلمة بارك الله لك فيها فدخلني والله مثل الذي دخلني في المرة الأولى وخفت مثل خوفي الأول فسلمتها وأخذت المال وبكرت على الفضل بن يحيى فإذا هو وحده فلما رأني ضحك وضرب برجله الأرض وقال ويحك حرمت نفسك عشرة آلاف دينار فقلت أصلحك الله خفت والله ما خفت في المرة الأولى قال لا ضير أخرج يا غلام جاريته فجاء بجاريتي بعينها فقال خذها ما أردناها ولا أردنا إلا منفعتك فلما ولت الجارية صحت بها ارجعي فرجعت فقلت أشهدك جعلت فداك أنها حرة لوجه الله وأني قد تزوجتها على عشرة آلاف درهم كسبت لي في يومين خمسين ألف دينار فما جزاؤها إلا هذا فقال وفقت إن شاء الله\nأخبرني الحسن بن علي قال أخبرني عبد الله بن أبي سعد قال حدثني محمد بن عبد الله بن مالك قال حدثني إسحاق قال قال لي أبي كنت في شبابي ألازم أصحاب قطربل وباري وبنى وما أشبه هذه المنازل فأتخذ فيهم الخمار اللطيف يحسبوني بالشراب الجيد ويخبؤه لي فجئت إلى باري يوما فلقيني خماري فقال لي يا أبا إسحاق عندي شيء من بابتك وقد كنت عملت لحني هذا صوت\n(اشرب الراح وكن في ... شربك الراح وقورا)\n(فاشرب الراح رواحا ... وظلاما وبكورا)\nلشعر والغناء لإبراهيم خفيف ثقيل بالسبابة في مجرى الوسطى وفيه لمنصور زلزل الضارب خفيف رمل عن حبش قال فدخلت بيته وبزلت دنه وجعلت أرجع الصوت فبهت ينظر إلي والنبيذ يجري حتى امتلأ الإناء وفاض فقلت له ويحك شرابك قد فاض فقال دعني\nمن شرابي بالله مات لك إنسان في هذه الأيام فقلت لا قال فما بال حلقك هذا حزينا أخبرني الحسن بن علي قال حدثنا هارون بن محمد بن عبد الملك الزيات قال حدثني حماد بن إسحاق عن عمه طيات بن إبراهيم قال دخلت على أبي يوما وعنده مخارق وأبي يلقي عليه هذا الصوت صوت\n(طربت وأنت معني كئيب ... وقد يشتاق ذو الحزن الغريب)\n(وشاقك بالموقر أهل خاخ ... فلا أمم هناك ولا قريب)\n(وكم لك دونها من عرض أرض ... كأن سرابها الجاري سبيب)\n(لعمرك إنني برقيم قيس ... وجارة أهلها لأنا الحريب)","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":13,"spl":"نسبة هذا الصوت"},
{"id":"b52-25","bab":"الجزء 5","sec":"نسبة هذا الصوت","page":"ج5 ص210","text":"لشعر للأحوص والغناء لإبراهيم ماخوري بالبنصر عن عمرو قال فلما أخذه مخارق جعل أبي يبكي ثم قال له يا مخارق نعم وسيلة إبليس أنت في الأرض أنت والله بعدي صاحب اللواء في هذا الشأن","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":14,"spl":"نسبة هذا الصوت — نسبة هذين الصوتين"},
{"id":"b52-26","bab":"الجزء 5","sec":"تفاخر مع ابنه في الغناء فحكم له","page":"ج5 ص213","text":"أخبرني الحسن بن علي وعمي قالا حدثنا عبد الله بن أبي سعد قال\nحدثني محمد بن عبد الله بن مالك عن إسحاق قال لما صنع أبي لحنه في\n(ليت هندا أنجزتنا ما تعد ... وشفت أنفسنا مما تجد)\nاصمته وعبته في صنعته وقلت له أما بإزائك من ينتقد أنفاسك ويعيب محاسنك وأنت لا تفكر تجيء إلى صوت قد عمل فيه ابن سريج لحنا فتعارضه بلحن لا يقاربه والشعر أوسع من ذلك فدع ما قد اعتورته صناعة القدماء وخذ في غيره فغضب وكنت لا أزال أفاخره بصنعتي وأعيب ما يعاب من صنعته فإن قبل مني فذلك وإن غضب درايته وترضيته فقال لي ما يعلم الله أني أدعك أو تفاخرني بخير صوت صنعته في الثقيل الثاني في طريقة هذا الصوت فلما رأيت الجد منه اخترت صنعتي في هذا اللحن\n(قل لمن صد عاتبا ... ونأى عنك جانبا)\n(قد بلغت الذي أردت ... وإن كنت لاعبا)\nكان ما تجاريناه ونحن نتساير خارجين إلى الصحراء نقطع فضلة خمار بنا فقال من تحب أن يحكم بيني وبينك فقلت من ترى أن يحكم هاهنا قال أول من يطلع علينا أغنيه لحني وتغنيه لحنك فطمعت فيه وقلت نعم فأقبل شيخ نبطي يحمل شوكا على حمار له فأقبل عليه أبي فقال إني وصاحبي هذا قد تراضينا بك في شيء قال وأي شيء هو فقلنا زعم كل واحد منا أنه أحسن غناء من صاحبه فتسمع مني ومنه وتحكم فقال على اسم الله فبدأ أبي فغنى لحنه وتبعته فغنيت لحني فلما فرغت أقبل علي فقال لي قد حكمت عليك عافاك الله ومضى فلطمني أبي لطمة ما مر بي مثلها منه قط وسكت فما أعدت عليه\nحرفا ولا راجعته بعد ذلك في هذا المعنى حتى افترقنا","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":14,"spl":"نسبة هذا الصوت — نسبة هذين الصوتين"},
{"id":"b52-27","bab":"الجزء 5","sec":"نسبة هذين الصوتين","page":"ج5 ص215","text":"صوت\n(ليت هندا أنجزتنا ما تعد ... وشفت أنفسنا مما تجد)\n(واستبدت مرة واحدة ... إنما العاجز من لا يستبد)\n(زعموها سألت جاراتها ... ذات يوم وتعرت تبترد)\n(أكما ينعتني تبصرنني ... عمركن الله أم لا يقتصد)\n(فتضاحكن وقد قلن لها ... حسن في كل عين من تود)\n(حسدا حملنه من أجلها ... وقديما كان في الناس الحسد)\nالشعر لعمر بن أبي ربيعة ولحن إبراهيم فيه ثاني ثقيل بالوسطى وفيه لابن سريج رمل بالخنصر في مجرى البنصر وفيه لمالك خفيف ثقيل بالخنصر والبنصر عن يحيى المكي وذكره إسحاق في هذه الطريقة ولم ينسبه إلى أحد وقال الهشامي أدل شيء على أنه لمالك شبهه للحنه\n(اسلمي يا دار من هند ... )\nفيه لمتيم ثقيل أول وأما لحن إسحاق الذي فاخر به صنعة أبيه فقد كتب شعره والصنعة فيه وهما جميعا لإسحاق ولحنه ثاني ثقيل بالوسطى عن عمرو في أخبار إسحاق\nوذكر أحمد بن أبي طاهر أن حماد بن إسحاق حدثه عن أبيه قال كان الرشيد قد وجد على منصور زلزل لشيء بلغه عنه فحبسه عشر سنين أو نحوها فقام الرشيد يوما لحاجته فجعل إبراهيم يغني صوتا صنعه في شعر كان قاله في حبس زلزل وهو\n(هل دهرنا بك راجع يا زلزل ... أيام يبغينا العدو المبطل)\n(أيام أنت من المكاره آمن ... والخير متسع علينا مقبل)\n(يا بؤس من فقد الإمام وقربه ... ماذا به من ذلة لو يعقل)\n(ما زلت بعدك في الهموم مرددا ... أبكي بأربعة كأني مثكل)\nلشعر والغناء لإبراهيم خفيف ثقيل بالوسطى عن عمرو قال ودخل الرشيد وهو في ذلك فجلس في مجلسه ثم قال يا إبراهيم أي شيء كنت تقول فقال خيرا يا سيدي فقال هاته فتلكأ فغضب الرشيد وقال هاته فلا مكروه عليك فرد الغناء فقال له أتحب أن تراه فقال وهل ينشر أهل القبور فقال هاتوا زلزلا فجاؤوا به وقد ابيض رأسه ولحيته فسر به إبراهيم وأمره فجلس وأمر إبراهيم فغنى وضرب عليه فزلزلا الدنيا وشرب الرشيد على ذلك رطلا وأمر بإطلاق زلزل وأسنى جائزتهما ورضي عنه وصرفه إلى منزله قال وزلزل أول من أحدث هذه العيدان الشبابيط وكانت قديما على عمل عيدان الفرس فجاءت عجبا من\nالعجب قال وكانت أخت زلزل تحت إبراهيم وقد ولدت منه","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":14,"spl":"نسبة هذا الصوت — نسبة هذين الصوتين","partialRef":{"sid":"b2-91","gi":2,"vi":0,"side":0},"partial":1},
{"id":"b52-28","bab":"الجزء 5","sec":"تعلم أول غناء من مجنون","page":"ج5 ص217","text":"أخبرني محمد بن مزيد عن حماد بن إسحاق عن أبيه قال أول من تعلمت منه الغناء مجنون كان إذا صيح به يا مضر يهيج ويرجم فبلغني أنه يغني أصواتا فيجيدها أخذها عن قدماء أهل الحجاز فكنت أدخله إلي فأطعمه وأسقيه وأخدعه حتى آخذ عنه وكان حاذقا فأول صوت أخذته عنه\n(أرسلي بالسلام يا سلم إني ... منذ علقتكم غني فقير)\n(فالغنى إن ملكت أمرك والفقر ... بأني أزور من لا يزور)\n(ويح نفسي تسلو النفوس ونفسي ... في هوى الريم ذكرها ما يحور)\n(من لنفس تتوق أنت هواها ... وفؤاد يكاد فيك يطير)\nم مكثت زمانا آخذ عنه وكان إذا عاد إليه عقله من أحذق الناس وأقومهم على ما يؤديه ثم غاب عني فما أعرف خبره وهذا الشعر للوليد بن يزيد والغناء ليونس خفيف رمل مطلق في مجرى البنصر عن إسحاق وذكر غيره أنه لعمر الوادي وفيه لوجه القرعة ثاني ثقيل بالوسطى عن حبش أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه عن جده قال خرجت مع الرشيد إلى الشأم لما غزا فدعاني يوما فدخلت إليه إلى مجلس لم أر أحسن منه مفروش بأنواع الرخام فأكل وأمرني فأكلت معه وجعلت أتولى خدمته إلى العصر ثم دعا بالنبيذ فشرب وسقاني معه ثم خلع علي خلعة وشي من ثيابه وأمر لي بألف دينار ثم قال انظر\nيا إبراهيم كم من يد أوليتك إياها اليوم نادمتني مفردا وآكلتني وخلعت عليك ثيابي من بدني ووصلتك وأجلستك في إيوان مسلمة بن عبد الملك تشرب معي فقلت يا سيدي ما ذهب علي شيء من تفضلك وإن نعمك عندي لأكثر من أن تحصى وقبلت رجله والأرض بين يديه","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":15,"spl":"تعلم أول غناء من مجنون — إبراهيم الموصلي أول من غنى الرشيد بعد توليه الخلافة"},
{"id":"b52-29","bab":"الجزء 5","sec":"إبراهيم الموصلي أول من غنى الرشيد بعد توليه الخلافة","page":"ج5 ص218","text":"أخبرني الحسن بن علي حدثنا أحمد بن زهير قال قال دعبل بن علي\nلما ولي الرشيد الخلافة وجلس للشرب بعد فراغه من إحكام الأمور ودخل عليه المغنون كان أول من غناه إبراهيم الموصلي بشعره فيه وهو\nصوت\n(إذا ظلم البلاد تجللتنا ... فهارون الإمام لها ضياء)\n(بهارون استقام العدل فينا ... وغاض الجور وانفسح الرجاء)\n(رأيت الناس قد سكنوا إليه ... كما سكنت إلى الحرم الظباء)\n(تبعت من الرسول سبيل حق ... فشأنك في الأمور به اقتداء)\nقال له الخادم من خلف الستارة أحسنت يا إبراهيم في شعرك\nوغنائك وأمر له بعشرين ألف درهم لحن إبراهيم في هذا الصوت ثقيل أول بالسبابة والوسطى عن أحمد بن المكي أخبرني الحسن بن علي قال حدثني يزيد بن محمد المهلبي قال حدثني أبي قال كنت أنا وأبو سعيد النهدي وهاشم بن سليمان المغني يوما مجتمعين في بستان لنا ونحن نشرب وهاشم يغنينا فلما توسطنا أمرنا إذا نحن برجل قد دخل علينا البستان جميل الهيئة حسن الزي فلما بصرنا به من بعيد وثب هاشم يعدو حتى لقيه فقبل يده وعانقه ولم يعرفه أحد منا فجاء وسلم سلام الصديق على صديقه ثم قال خذوا في شأنكم فإني اجتزت بكم فسمعت غناء أبي القاسم فاستخفني وأطربني فدخلت إليكم واثقا بأنه لا يعاشر إلا فتى ظريفا يستحسن هذا الفعل ويسره ولي في هذا إمام وهو عبد الله بن جعفر بن أبي طالب عليه السلام فإنه سمع غناء عند قوم فدخل بغير إذن ثم قال إنما أدخلني عليكم مغنيكم لما غنى\n(قل لكرام ببابنا يلجوا ... ما في التصابي على الفتى حرج)\nوأنا أعلم أن نفوسكم متعلقة بمعرفتي فمن عرفني فقد اكتفى ومن جهلني فأنا إبراهيم الموصلي فقمنا فقبلنا رأسه وسررنا به أتم سرور وانعقدت بيننا وبينه يومئذ مودة ثم غاب عنا غيبة طويلة وإذا هاشم قد أنفذ إلينا منه رقعة فيها\n(أهاشم هل لي من سبيل إلى التي ... تفرق هم النفس في كل مذهب)\n(معتقة صرفا كأن شعاعها ... تضرم نار أو توقد كوكب)\n(ألا رب يوم قد لهوت وليلة ... بها والفتى النهدي وابن المهلب)\n(ندير مداما بيننا بتحية ... وتفدية بالنفس والأم والأب)\nخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه قال\nكان لي وأنا صبي عقعق قد ربيته وكان يتكلم بكل شيء سمعه فسرق خاتم ياقوت كان لأبي قد وضعه على تكأته ودخل الخلاء ثم خرج ولم يجده فطلبه وضرب غلامه الذي كان واقفا فلم يقف له على خبر فبينا أنا ذات يوم في دارنا إذا أبصرت العقعق قد نبش ترابا فأخرج الخاتم منه ولعب به طويلا ثم رده فيه ودفنه فأخذته وجئت به إلى أبي فسر بذلك وقال يهجو العقعق\n(إذا بارك الله في طائر ... فلا بارك الله في العقعق)\n(طويل الذنابى قصير الجناح ... متى ما يجد غفلة يسرق)\n(يقلب عينين في رأسه ... كأنهما قطرتا زئبق)","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":15,"spl":"تعلم أول غناء من مجنون — إبراهيم الموصلي أول من غنى الرشيد بعد توليه الخلافة"},
{"id":"b52-30","bab":"الجزء 5","sec":"الموصلي وابن جامع عند الرشيد","page":"ج5 ص220","text":"أخبرني الحسن بن علي قال حدثنا عبد الله بن أبي سعد قال حدثني أحمد بن المكي وذاكرت أبا أحمد بن جعفر جحظة بهذا الخبر فقال حدثني به محمد بن أحمد بن يحيى المكي المرتجل عن أبيه عن جده ووجدت هذا الخبر في بعض الكتب عن علي بن محمد بن نصر عن جده حمدون بن إسماعيل فجمعت الروايات كلها أن الرشيد قال يوما لجعفر بن يحيى قد طال سماعنا هذه العصابة على اختلاط الأمر فيها فهلم أقاسمك إياها وأخايرك فاقتسما المغنين على أن جعلا بإزاء كل رجل نظيره وكان ابن جامع في حيز الرشيد وإبراهيم في حيز جعفر بن يحيى وحضر الندماء لمحنة المغنين وأمر الرشيد ابن\nجامع فغنى صوتا أحسن فيه كل الإحسان وطرب الرشيد غاية الطرب فلما قطعه قال الرشيد لإبراهيم هات يا إبراهيم هذا الصوت فغنه فقال لا والله يا أمير المؤمنين ما أعرفه وظهر الانكسار فيه فقال الرشيد لجعفر هذا واحد ثم قال لإسماعيل بن جامع غن يا إسماعيل فغنى صوتا ثانيا أحسن من الأول وأرضى في كل حال فلما استوفاه قال الرشيد لإبراهيم هاته يا إبراهيم قال ولا أعرف هذا فقال هذان اثنان غن يا إسماعيل فغنى ثالث يتقدم الصوتين الأولين ويفضلهما فلما أتى على آخره قال هاته يا إبراهيم قال ولا أعرف هذا أيضا فقال له جعفر أخزيتنا أخزاك الله قال وأتم ابن جامع يومه والرشيد مسرور به وأجازه بجوائز كثيرة وخلع عليه خلعا فاخرة ولم يزل إبراهيم منخذلا منكسرا حتى انصرف قال فمضى إلى منزله فلم يستقر فيه حتى بعث إلى محمد المعروف بالزف وكان محمد من المغنين المحسنين وكان أسرع من عرف في أيامه في أخذ صوت يريد أخذه وكان الرشيد قد وجد عليه في بعض ما يجده الملوك على أمثاله فألزمه بيته وتناساه فقال إبراهيم للزف إني اخترتك على من هو أحب إلي منك لأمر لا يصلح له غيرك فانظر كيف تكون قال أبلغ في ذلك محبتك إن شاء الله تعالى فأدى إليه الخبر وقال أريد أن تمضي الساعة إلى ابن جامع فتعلمه أنك صرت إليه مهنئا بما تهيأ له علي وتنقصني وتثلبني وتشتمني وتحتال في أن تسمع منه الأصوات وتأخذها منه ولك ما تحبه من جهتي من عرض من الأعراض مع رضا الخليفة إن شاء الله قال فمضى من عنده واستأذن على ابن جامع فأذن له فدخل وسلم عليه وقال جئتك مهنئا بما بلغني من خبرك والحمد لله الذي أخزى ابن الجرمقانية على يدك وكشف الفضل في\nمحلك من صناعتك قال وهل بلغك خبرنا قال هو أشهر من أن يخفى على مثلي قال ويحك إنه يقصر عن العيان قال أيها الأستاذ سرني بأن أسمعه من فيك حتى أرويه عنك وأسقط بيني ويبنك الأسانيد قال أقم عندي حتى أفعل قال السمع والطاعة فدعا له ابن جامع بالطعام فأكلا ودعا بالشراب ثم ابتدأ حدثه بالخبر حتى انتهى إلى خبر الصوت الأول فقال له الزف وما هو أيها الأستاذ فغناه ابن جامع أياه فجعل محمد يصفق وينعر ويشرب وابن جامع مجتهد في شأنه حتى أخذه عنه ثم سأله عن الصوت الثاني فغناه إياه وفعل مثل فعله في الصوت الأول ثم كذلك في الصوت الثالث فلما أخذ الأصوات الثلاثة كلها وأحكمها قال له يا أستاذ قد بلغت ما أحب فتأذن لي في الانصراف قال إذا شئت فانصرف محمد من وجهه إلى إبراهيم فلما طلع من باب داره قال له ما وراءك قال كل ما تحب ادع لي بعود فدعا له به فضرب وغناه الأصوات قال إبراهيم وأبيك هي بصورها وأعيانها رددها علي الآن فلم يزل يرددها حتى صحت لإبراهيم وانصرف الزف إلى منزله وغدا إبراهيم إلى الرشيد فلما دعا بالمغنين دخل فيهم فلما بصر به قال له أو قد حضرت أما كان ينبغي لك أن تجلس في منزلك شهرا بسبب ما لقيت من ابن جامع قال ولم ذلك يا أمير المؤمنين جعلني الله فداءك والله لئن أذنت لي أن أقول لأقولن قال وما عساك أن تقول قل فقال إنه ليس ينبغي لي ولا لغيري أن يراك نشيطا لشيء فيعارضك ولا أن تكون متعصبا لحيز وجنبة فيغالبك وإلا فما في الأرض صوت لا أعرفه قال دع ذا عنك قد أقررت أمس بالجهالة بما سمعت من صاحبنا فإن كنت أمسكت عنه بالأمس على معرفة كما تقول فهاته اليوم فليس ها هنا عصبية ولا تمييز فاندفع فأمر الأصوات كلها وابن جامع مصغ","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":16,"spl":"الموصلي وابن جامع عند الرشيد"},
{"id":"b52-31","bab":"الجزء 5","sec":"الموصلي وابن جامع عند الرشيد","page":"ج5 ص220","text":"يسمع منه حتى أتى على آخرها فاندفع ابن جامع فحلف بالأيمان المحرجة أنه ما عرفها قط ولا سمعها ولا هي إلا من صنعته ولم تخرج إلى أحد غيره فقال له ويحك فما أحدثت بعدي قال ما أحدثت حدثا فقال يا إبراهيم بحياتي اصدقني فقال وحياتك لأصدقنك رميته بحجره فبعثت له بمحمد الزف وضمنت له ضمانات أولها رضاك عنه فمضى فاحتال لي عليه حتى أخذها عنه ونقلها إلي وقد سقط الآن اللوم عني بإقراره لأنه ليس علي أن أعرف ما صنعه هو ولم يخرجه إلى الناس وهذا باب من الغيب وإنما يلزمني أن يعرف هو شيئا من غناء الأوائل وأجهله أنا وإلا فلو لزمني أن أروي صنعته للزمه أن يروي صنعتي ولزم كل واحد منا لسائر طبقته ونظرائه مثل ذلك فمن قصر عنه كان مذموما ساقطا فقال له الرشيد صدقت يا إبراهيم ونضحت عن نفسك وقمت بحجتك ثم أقبل على ابن جامع فقال له يا إسماعيل أتيت أتيت دهيت دهيت أبطل عليك الموصلي ما فعلته به أمس وانتصف اليوم منك ثم دعا بالزف فرضي عنه","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":17,"spl":"الموصلي وابن جامع عند الرشيد — الأصوات التي غنى بها ابن جامع"},
{"id":"b52-32","bab":"الجزء 5","sec":"الأصوات التي غنى بها ابن جامع","page":"ج5 ص223","text":"قال علي بن محمد سألت خالي أبا عبد الله بن حمدون وقد تجارينا هذا الخبر هل تعرف أصوات ابن جامع هذه فأخبرني أنه سمع إسحاق يحكي هذه القصة وذكر أن الصوت الأول منها صوت\n(بكيت نعم بكيت وكل إلف ... إذا بانت قرينته بكاها)\n(وما فرقت لبنى عن تقال ... ولكن شقوة بلغت مداها)\nالشعر لقيس بن ذريح والغناء لابن جامع ثاني ثقيل بالوسطى وفيه ليحيى المكي ثاني ثقيل آخر بالخنصر والبنصر من كتابه وفيه لإبراهيم ثقيل أول عن الهشامي قال والثاني منها صوت\n(عفت دار سلمى بمفضى الرغام ... رياح تعاقبها كل عام)\n(خلاف الحلول بتلك الطلول ... وسحب الذيول بذاك المقام)\n(وأنس الديار وقرب الجوار ... وطيب المزار ورد السلام)\n(ودهر غرير وعيش السرور ... ونأي الغيور وحسن الكلام)\nلشعر لحماد الراوية والغناء لابن جامع ثقيل أول بالبنصر ذكر ذلك الحزنبل عن عمرو بن أبي عمرو قال ابن حمدون وهذا الصوت عجيب الصنعة كثير النغم محكم العمل من صدور أغاني ابن جامع ومتقدم صنعته وكان المعتصم معجبا به وكثيرا ما كان يسكت المغنين إذا غني بحضرته فلا يسمع سائر يومه غيره قال والثالث منها صوت\n(نزف البكاء دموع عينك فاستعر ... عينا لغيرك دمعها مدرار)\n(من ذا يعيرك عينه تبكي بها ... أرأيت عينا للبكاء تعار)\nلشعر للعباس بن الأحنف والغناء لابن جامع ثقيل أول بالوسطى وقال ابن حمدون وعارضه إبراهيم بعد ذلك في هذا الشعر فصنع فيه لحنا من الرمل بالبنصر في مجراها فلم يلحقه ولا قاربه قال وقد صنع أيضا في هذا الشعر لحن خفيف فاسد الصنعة محدث ليس ينبغي أن يذكر هاهنا حدثني محمد بن يحيى الصولي قال حدثني أبو عبد الله الحزنبل قال حدثني أحمد بن إبراهيم بن إسماعيل عن أبيه قال أنشد بشار قول العباس بن الأحنف\n(نزف البكاء دموع عينك فاستعر ... عينا لغيرك دمعها مدرار)\nقال بشار لحق والله هذا الفتى بالمحسنين وما زال يدخل نفسه معنا ونحن نخرجه حتى قال هذا الشعر حدثني محمد بن يحيى قال حدثني ميمون بن هارون عن إسحاق قال أنشد الرشيد قول العباس\n(من ذا يعيرك عينه تبكي بها ... أرأيت عينا للبكاء تعار)\nقال يعيره من لا حاطه الله ولا حفظه\nومما يغنى فيه من قصيدة العباس بن الأحنف الرائية التي هذا الصوت الأخير منها قوله صوت\n(الحب أول ما يكون لجاجة ... تأتي به وتسوقه الأقدار)\n(حتى إذا سلك الفتى لجج الهوى ... جاءت أمور لا تطاق كبار)\nناه ابن جامع ثاني ثقيل بالبنصر وفيه لشاطرة امرأة منصور زلزل ثقيل أول بالوسطى عن الهشامي وذكر ابن المكي المرتجل أن هذه الأصوات الثلاثة المسروقة من ابن جامع\n(يا قبر بين بيوت آل محرق ... )\nو\n(عفا طرف القرية فالكثيب ... )\nأسقط منها قوله\n(نزف البكاء دموع عينك فاستعر ... )\nو\n(بكيت نعم بكيت وكل إلف ... )","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":17,"spl":"الموصلي وابن جامع عند الرشيد — الأصوات التي غنى بها ابن جامع","partial":1},
{"id":"b52-33","bab":"الجزء 5","sec":"نسبة هذين الصوتين","page":"ج5 ص227","text":"صوت\n(يا قبر بين بيوت آل محرق ... جادت عليك رواعد وبروق)\n(أما البكاء فقل عنك كثيره ... ولئن بكيت فبالبكاء حقيق)\nالشعر لرجل من بني أسد يرثي خالد بن نضلة ورجلا آخر من بني أسد كانا نديمين للمنذر بن ماء السماء فقتلهما في سخطه عليهما وخبر ذلك مشهور في أخبار ابن جامع والغناء لابن جامع وله فيه لحنان ثقيل أول بالوسطى ورمل بالبنصر وقيل إن الرمل لابن سريج وذكر حبش أن لمحمد صاحب البرام فيه لحنا من الثقيل الثاني بالوسطى ومنها صوت\n(عفا رسم القرية فالكثيب ... إلى ملحاء ليس بها عريب)\n(تأبد رسمها وجرى عليها ... سفي الريح والترب الغريب)\n(فإنك واطراحك وصل سعدى ... لأخرى في مودتها نكوب)\n(كثاقبة لحلي مستعار ... بأذنيها فشانهما الثقوب)\n(فردت حلي جارتها إليها ... وقد بقيت بأذنيها ندوب)\nلشعر لابن هرمة والغناء لابن جامع ثاني ثقيل بإطلاق الوتر في مجرى الوسطى عن إسحاق وفيه للغريض ثاني ثقيل آخر بالبنصر عن عمرو وقال عمرو فيه لحن للهذلي ولم يجنسه أخبرني محمد بن خلف وكيع قال حدثني هارون بن محمد بن عبد الملك الزيات قال حدثني عيسى بن أيوب القرشي قال حدثني غيث بن عبد الكريم عن فليح بن إسماعيل عن إسماعيل بن جعفر الفقيه مولى حرب عن أبيه قال مررت بابن هرمة وهو جالس على دكان في بني زريق فقلت له يا أبا إسحاق ما يجلسك ها هنا قال بيت كنت قلته ثم انقطع علي الروي فيه وتعذر علي ما أشتهيه فأبغضته وتركته قلت ما هو قال\n(فإنك واطراحك وصل سعدى ... لأخرى في مودتها نكوب)\nال قلته ثم انقطع بي فيه فمرت بي جويرية صفراء مليحة كنت أستحسنها أبدا وأكلمها إذا مرت بي فمرت اليوم فرأيتها وقد ورم وجهها وتغير خلقها عما أعرف فسألتها عن خبرها فقالت كان في بني فلان عرس أردت حضوره فاستعار لي أهلي حليا وثقبوا أذني لألبسه فورم وجهي وأذناي كما ترى فردوه ولم أشهد العرس قال ابن هرمة فاطرد لي الشعر فقلت\n(كثاقبة لحلي مستعار ... بأذنيها فشانهما الثقوب)\n(فردت حلي جارتها إليها ... وقد بقيت بأذنيها ندوب)","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":18,"spl":"نسبة هذين الصوتين — إبراهيم بن المهدي يسرق شعره ويغني به الرشيد"},
{"id":"b52-34","bab":"الجزء 5","sec":"إبراهيم بن المهدي يسرق شعره ويغني به الرشيد","page":"ج5 ص229","text":"أخبرني الحسين بن القاسم قال حدثني العباس بن الفضل قال حدثني أبي قال قال الرشيد لإبراهيم بن المهدي وإبراهيم الموصلي وابن جامع وابن أبي الكنات باكروني غدا وليكن كل واحد قد قال شعرا إن كان يقدر أن يقوله وغنى فيه لحنا وإن لم يكن شاعرا غنى في شعر غيره قال إبراهيم ابن المهدي فقمت في السحر وجهدت أن أقدر على شيء أصنعه فلم يتفق لي فلما خفت طلوع الفجر دعوت بغلماني وقلت لهم إني أريد أن أمضي إلى موضع ولا يشعر بي أحد حتى أصير إليه وكانوا يبيتون على باب داري فقمت فركبت وقصدت دار إبراهيم الموصلي وكان قد حدثني أنه إذا أراد الصنعة لم ينم حتى يدبر ما يحتاج إليه وإذا قام لحاجته في السحر اعتمد على خشبة له في المستراح فلم يزل يقرع عليها حتى يفرغ من الصوت ويرسخ في قلبه فجئت حتى وقفت تحت مستراحه فإذا هو يردد هذا الصوت صوت\n(إذا سكبت في الكأس قبل مزاجها ... ترى لونها في جلدة الكأس مذهبا)\n(وإن مزجت راعت بلون تخاله ... إذا ضمنته الكأس في الكأس كوكبا)\n(أبوها نجاء المزن والكرم أمها ... فلم أر زوجا منه أشهى وأطيبا)\n(فجاءتك صفرا أشبهت غير جنسها ... وما أشبهت في اللون أما ولا أبا)\nال فما زلت واقفا أستمع منه الصوت حتى أخذته ثم غدونا إلى الرشيد فلما جلسنا للشرب خرج الخادم إلي فقال يقول لك أمير المؤمنين يابن أم غنني فاندفعت فغنيت هذا الصوت والموصلي في الموت حتى فرغت منه فشرب عليه وأمر لي بثلاثمائة ألف درهم فوثب إبراهيم الموصلي فحلف بالطلاق وحياة الرشيد أن الشعر له قاله البارحة وغنى فيه ما سبقه إليه أحد فقال إبراهيم يا سيدي فمن أين هو لي أنا لولا كذبه وبهته وإبراهيم يضطرب ويضج فلما قضيت أربا من العبث به قلت للرشيد الحق أحق أن يتبع وصدقته فقال للموصلي أما أخي فقد أخذ المال ولا سبيل إلى رده وقد أمرت لك بمائة ألف درهم عوضا مما جرى عليه فلو بدأت أنت بالصوت لكان هذا حظك فأمر له بها فحملت إليه","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":18,"spl":"نسبة هذين الصوتين — إبراهيم بن المهدي يسرق شعره ويغني به الرشيد"},
{"id":"b52-35","bab":"الجزء 5","sec":"إبراهيم الموصلي ومحمد بن يحيى","page":"ج5 ص230","text":"أخبرني الحسين بن يحيى عن حماد بن إسحاق عن مخارق قال أتى إبراهيم الموصلي محمد بن يحيى بن خالد في يوم مهرجان فسأله محمد أن يقيم عنده فقال ليس يمكنني لأن رسول أمير المؤمنين قد أتاني قال فتمر بنا إذا انصرفت ولك عندي كل ما يهدى إلي اليوم فقال نعم وترك في المجلس صديقا له يحصي ما يبعث به إليه قال فجاءت هدايا عجيبة من كل ضرب قال وأهدي إليه تمثال فيل من ذهب عيناه ياقوتتان فقال محمد للرجل لا تخبره بهذا حتى نبعث به إلى فلانة ففعل وانصرف إبراهيم إليه فقال أحضرني ما أهدي لك فأحضره ذلك كله إلا التمثال وقال\nلا بد من صدقك كان من الأمر كذا وكذا فقال لا إلا على الشريطة وكما ضمنت فجيء بالتمثال فقال إبراهيم أليس الهدية لي فأعمل فيها ما أريد قال بلى قال فرد التمثال على الجارية وجعل يفرق الهدايا على جلساء محمد شيئا شيئا وعلى جميع من حضر من إخوانه وغلمانه وعلى من في دور الحرم من جواريه حتى لم يبق منها شيء ثم أخذ من المجلس تفاحتين لما أراد الانصراف وقال هذا لي وانصرف فجعل محمد يعجب من كبر نفسه ونبله","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":19,"spl":"إبراهيم الموصلي ومحمد بن يحيى — الرشيد يزوره ليلا ليغنيه"},
{"id":"b52-36","bab":"الجزء 5","sec":"الرشيد يزوره ليلا ليغنيه","page":"ج5 ص231","text":"وقال أحمد بن المرزبان حدثني بعض كتاب السلطان أن الرشيد هب ليلة من نومه فدعا بحمار كان يركبه في القصر أسود قريب من الأرض فركبه وخرج في دراعة وشي متلثما بعمامة وشي ملتحفا بإزار وشي بين يديه أربعمائة خادم أبيض سوى الفراشين وكان مسرور الفرغاني جريئا عليه لمكانه عنده فلما خرج من باب القصر قال أين يريد أمير المؤمنين في هذه الساعة قال أردت منزل الموصلي قال مسرور فمضى ونحن معه وبين يديه حتى انتهى إلى منزل إبراهيم فخرج فتلقاه وقبل حافر حماره وقال له يا أمير المؤمنين أفي مثل هذه الساعة تظهر قال نعم شوق طرق لك بي ثم نزل فجلس في طرف الإيوان وأجلس إبراهيم فقال له إبراهيم يا سيدي أتنشط لشيء تأكله فقال نعم خاميز ظبي فأتي به كأنما كان معدا له فأصاب منه شيئا يسيرا ثم دعا بشراب حمل معه فقال الموصلي يا سيدي أؤغنيك أم تغنيك إماؤك فقال بل الجواري فخرج جواري إبراهيم فأخذن صدر الإيوان وجانبيه فقال أيضربن كلهن أم واحدة فقال بل\nتضرب اثنتان اثنتان وتغني واحدة فواحدة ففعلن ذلك حتى مر صدر الإيوان وأحد جانبيه والرشيد يسمع ولا ينشط لشيء من غنائهن إلى أن غنت صبية من حاشيته\n(يا موري الزند قد أعيت قوادحه ... إقبس إذا شئت من قلبي بمقباس)\n(ما أقبح الناس في عيني وأسمجهم ... إذا نظرت فلم أبصرك في الناس)\nال فطرب لغنائها واستعاد الصوت مرارا وشرب أرطالا ثم سأل الجارية عن صانعه فأمسكت فاستدناها فتقاعست فأمر بها فأقيمت حتى وقفت بين يديه فأخبرته بشيء أسرته إليه فدعا بحماره فركبه وانصرف ثم التفت إلى إبراهيم فقال ما ضرك ألا تكون خليفة فكادت نفسه تخرج حتى دعا به وأدناه بعد ذلك قال وكان الذي خبرته به أن الصنعة في الصوت لأخته علية بنت المهدي وكانت الجارية لها وجهت بها إلى إبراهيم يطارحها فغار الرشيد ولحن الصوت خفيف رمل أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه قال كان أبي يألف خمارة بالرقة يقال لها بشرة تنزل الهنيء والمريء\nوكانت لها بنت من أحسن الناس وجها فكان أبي يتحلاها ثم رحل الرشيد عن الرقة إلى بلاد الروم في بعض غزواته فقال أبي فيها\n(أيا بنت بشرة ما عاقني ... عن العهد بعدك من عائق)\n(نفى النوم عني سنا بارق ... وأشهقني في ذرى شاهق)\nال وفيها يقول أيضا من أبيات له وله فيها صنعة من الرمل الأول صوت\n(وزعمت أني ظالم فهجرتني ... ورميت في قلبي بسهم نافذ)\n(ونعم ظلمتك فاغفري وتجاوزي ... هذا مقام المستجير العائذ)\nكر حماد في هذا الخبر أن لحن جده من الرمل ووجدت في كتاب أحمد بن المكي أن له فيهما لحنين أحدهما ثقيل أول والآخر ثاني ثقيل","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":19,"spl":"إبراهيم الموصلي ومحمد بن يحيى — الرشيد يزوره ليلا ليغنيه"},
{"id":"b52-37","bab":"الجزء 5","sec":"الرشيد يحبس الموصلي فيغني في السجن","page":"ج5 ص233","text":"حدثني عيسى بن الحسين الوراق قال حدثني عبد الله بن أبي سعد قال حدثني محمد بن عبد الله بن مالك الخزاعي قال حبس الرشيد إبراهيم الموصلي عند أبي العباس يعني أباه عبد الله ابن مالك فسمعناه ليلة وقد صنع هذا اللحن وهو يكرره حتى يستوي له\n(يا أخلاء قد مللت مكاني ... وتذكرت ما مضى من زماني)\n(شربي الراح إذ تقوم علينا ... ذات دل كأنها غصن بان)\nال وغنى في الحبس أيضا\n(ألا طال ليلي أراعي النجوم ... أعالج في الساق كبلا ثقيلا)\nدثني عيسى قال حدثني عبد الله قال حدثني محمد بن عبد الله بن مالك قال حدثني علويه الأعسر قال دخلت على إبراهيم الموصلي في علته التي توفي فيها وهو في الأبزن وبه القولنج الذي مات فيه وهو يترنم بهذا الصوت صوت\n(تغير مني كل حسن وجدة ... وعاد على ثغري فأصبح أثرما)\n(ومحل أطرافي فزالت فصوصها ... وحنى عظامي عوجها والمقوما)\nال محمد فحدثت بهذا الحديث إسحاق الموصلي فقال كذب ابن الزانية والله ما كان يجترئ أن يدخل إلى أبي إسحاق وهو جالس للناس إلا بعد جهد فكيف يدخل إلى أبي إسحاق وهو جالس في الأبزن","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":20,"spl":"الرشيد يحبس الموصلي فيغني في السجن — نسبة هذا الصوت"},
{"id":"b52-38","bab":"الجزء 5","sec":"نسبة هذا الصوت","page":"ج5 ص234","text":"الشعر والغناء لإبراهيم وله فيه لحنان ماخوري بالوسطى عن عمرو وثاني ثقيل عن ابن المكي حدثني جحظة قال كان المقتدر يدعونا في الأحايين فكان يحضر من المغنين إبراهيم بن أبي العبيس وكنيز وإبراهيم بن قاسم وأنا ووصيف الزامر وكان أكثر ما ندعى\nله أن جواريه كن يطالبنه بإحضارنا ليأخذن منا أصواتا قد عرفنها ويسمعننا فنغني فيأخذن ما يستحسنه فإذا انصرفنا أمر لكل واحد من إبراهيم وكنيز دبة وإبراهيم بثلاثمائة دينار ولي بمائتي دينار ولوصيف بمائتي دينار ولسائر من لعله أن يحضر معنا بمائتين إلى المائة الدينار إلى الألف الدرهم فيكون إذا حضرنا من وراء ستارة وهو جالس مع الجواري فإذا أراد اقتراح شيء جاءنا الخدم فأمرونا أن نغنيه وبين يدي كل واحد منا قنينة فيها خمسة أرطال نبيذ وقدح ومغسل وكوز ماء فغنت يوما صلفة جارية زرياب بصنعة إبراهيم الموصلي\n(تغير مني كل حسن وجدة ... وعاد على ثغري فأصبح أثرما)\nشربت عليه فاستعاده المقتدر مرارا وأنا أشرب عليه فأخذ إبراهيم بن أبي العبيس بكتفي وقال يا مجنون إنما دعيت لتغني لا لتغنى وتطرب وتشرب فلعلك تسكر حسبك فأمسكت طمعا أن ترده بعد ذلك فما فعلت ولا اجتمعنا بعدها وما سمعت قبل ذلك ولا بعده أحدا غنى هذا الصوت أحسن مما غنته قال وكان المقتدر ابتاعها من زرياب أخبرني عمي قال حدثني عبد الله بن أبي سعد قال حدثني أحمد بن القاسم بن جعفر بن سليمان بن علي قال حدثني إسحاق الموصلي عن أبيه قال بينا أنا بمكة أجول في سككها إذا أنا بسوداء قائمة ساهية باكية فأنكرت حالها وأدمنت النظر إليها فبكت وقالت\n(أعمرو علام تجنبتني ... أخذت فؤادي وعذبتني)\n(فلو كنت يا عمرو خبرتني ... أخذت حذاري فما نلتني)\nقلت لها يا هذه من عمرو قالت زوجي قلت وما شأنه قالت أخبرني أنه يهواني وما زال يطلبني حتى تزوجته فلبث معي قليلا ثم مضى إلى جدة وتركني فقلت لها صفيه لي قالت أحسن من أنت رائيه سمرة وأحلاهم حلاوة وقدا قال فركبت رواحلي مع غلماني وصرت إلى جدة فوقفت في موضع المرفأ أتبصر من يحمل من السفن وأمرت من يصوت يا عمرو يا عمرو وإذا أنا به خارجا من سفينة على عنقه صن فيه طعام فعرفته بصفتها ونعتها إياه فقلت\n(أعمرو علام تجنبتني ... أخذت فؤادي وعذبتني)\nقال هيه أرأيتها وسمعت منها فقلت نعم فأطرق هنيهة يبكي ثم اندفع فغنى به أملح غناء سمعته وردده علي حتى أخذته منه وإذا هو أحسن الناس غناء فقلت له ألا ترجع إليها فقال طلب المعاش يمنعني فقلت كم يكفيك معها في كل سنة فقال ثلاثمائة درهم قال إسحاق قال لي أبي فوالله يا بني لو قال ثلاثمائة دينار لطابت نفسي بها فدعوت به فأعطيته ثلاثة آلاف درهم وقلت له هذا لعشر سنين على أن تقيم معها فلا تطلب المعاش إلا حيث هي مقيمة معك ويكون ذلك فضلا ورددته معي إليها","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":20,"spl":"الرشيد يحبس الموصلي فيغني في السجن — نسبة هذا الصوت"},
{"id":"b52-39","bab":"الجزء 5","sec":"الموصلي يغني الرشيد والرشيد يجزل صلته","page":"ج5 ص236","text":"أخبرني حبيب بن نصر المهلبي قال حدثنا علي بن محمد النوفلي قال حدثنا صالح بن علي يعني الأضجم عن إبراهيم الموصلي قال وكان\nصالح جاره قال بينا أنا عشية في منزلي إذ أتاني خادم من خدم الرشيد فاستحثني بالركوب إليه فخرجت شبيها بالراكض فلما صرت إلى الدار عدل بي عن المدخل إلى طرق لا أعرفها فانتهي بي إلى دار حديثة البناء فدخلت صحنا واسعا وكان الرشيد يشتهي الصحون الواسعة فإذا هو جالس على كرسي في وسط ذلك الصحن ليس عنده أحد إلا خادم يسقيه وإذا هو في لبسته التي كان يلبسها في الصيف غلالة رقيقة متوشح عليها بإزار رشيدي عريض العلم مضرج فلما رآني هش لي وسر وقال يا موصلي إني اشتهيت أن أجلس في هذا الصحن فلم يتفق لي إلا اليوم وأحببت ألا يكون معي ومعك أحد ثم صاح بالخدام فوافاه مائة وصيف وإذا هم بالأرقة مستترون بالأساطين حتى لا يراهم فلما ناداهم جاؤوا جميعا فقال مقطعة لإبراهيم وكان هو أول من قطع المصليات فأتيت بمقعد فألقي لي تجاه وجهه بالقرب منه ودعا بعود فقال بحياتي أطربني بما قدرت قال ففعلت واجتهدت في ذلك ونشطت ورجوت الجائزة في عشيتي فبينا أنا كذلك إذ جاءه مسرور الكبير فقام مقامه الذي كان إذا قامه علم الرشيد أنه يريد أن يساره بشيء فأومأ إليه بالدنو فدنا فألقى في أذنه كلمة خفيفة ثم تنحى فاستشاط غضبا واحمرت عيناه وانتفخت أوداجه ثم قال حتام أصبر على آل بني أبي طالب والله لأقتلنهم ولأقتلن شيعتهم ولأفعلن ولأفعلن فقلت إنا لله ليس عند هذا أحد يخرج غضبه عليه أحسبه والله سيوقع بي فاندفعت أغني صوت\n(نعم عونا على الهموم ثلاث ... مترعات من بعدهن ثلاث)\n(بعدها أربع تتمة عشر ... لا بطاء لكنهن حثاث)\n(فإذا ناولتكهن جوار ... عطرات بيض الوجوه خناث)\n(تم فيها لك السرور وما طيب ... عيشا إلا الخناث الإناث)\nال ويلك اسقني ثلاثا لا أمت هما فشرب ثلاثا متتابعة ثم قال غن فغنيت فلما قلت ثلاث\n(مترعات من بعدهن ثلاث ... )\nال هات ويلك ثلاثا ثم قال لي غن فلما غنيته قال حث علي بأربع تتمة العشر ففعل فوالله ما استوفى آخرهن حتى سكر فنهض ليدخل ثم قال قم يا موصلي فانصرف يا مسرور أقسمت عليك بحياتي وبحقي إلا سبقته إلى منزله بمائة ألف درهم لا أستأمر فيها ولا في شيء منها فخرجت والله وقد أمنت خوفي وأدركت ما أملت ووافيت منزلي وقد سبقتني المائة الألف الدرهم إليه أخبرني عمي قال حدثنا عبد الله بن أبي سعد قال حدثني يحيى بن الحسن بن عبد الخالق قال حدثني عبد الله بن العباس بن الفضل بن الربيع قال خرج رسول الرشيد ذات ليلة إلى المغنين فقال غنوا\n(يا خليلي قد مللت ثوائي ... بالمصلى وقد سئمت البقيعا)\n(بلغاني ديار هند وسعدى ... وارجعاني فقد هويت الرجوعا)\nال فغناه ابن جامع فلما فرغ منه طرب الرشيد وشرب فقال له إبراهيم الموصلي يا سيدي فاسمعه من نبيطيك فغناه فجعل ابن جامع يزحف من أول البيت إلى آخره وطرب هارون فقال ارفعوا الستارة فقال له ابن جامع مني والله أخذه يا أمير المؤمنين فأقبل على إبراهيم فقال بحياتي صدق قال صدق وحياتك يا سيدي قال وكيف أخذته وهو أبخل الناس إذا سئل شيئا قال تركته يغنيه وكان إذا سكر يسترسل فيه فيغنيه مستويا ولا يتحرز مني فأخذته على هذا منه حتى وفيت به أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه قال كان برصوما الزامر وزلزل الضارب من سواد أهل الكوفة من أهل الخشنة والبذاذة والدناءة فقدم بهما أبي معه سنة حج ووقفهما على الغناء العربي وأراهما وجوه النغم وثقفهما حتى بلغا المبلغ الذي بلغاه من خدمة الخليفة وكانا أطبع أهل دهرهما في صناعتهما فحدثني أبي قال كان لزلزل جارية قد رباها وعلمها الضرب وسألني مطارحتها فطارحتها وكانت مطبوعة حاذقة قال فكان يصونها أن يسمعها أحد فلما مات بلغني أنها تعرض في ميراثه للبيع فصرت إليها لأعترضها فغنت\n(أقفر من أوتاره العود ... فالعود للأوتار معمود)\n(وأوحش المزمار من صوته ... فما له بعدك تغريد)\n(من للمزامير وعيدانها ... وعامر اللذات مفقود)\n(الخمر تبكي في أباريقها ... والقينة الخمصانة الرود)","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":21,"spl":"الموصلي يغني الرشيد والرشيد يجزل صلته","partial":1},
{"id":"b52-40","bab":"الجزء 5","sec":"الموصلي يغني الرشيد والرشيد يجزل صلته","page":"ج5 ص236","text":"ال وهذا شعر رثاه به صديق له كان بالرقة قال فأبكت والله عيني وأوجعت قلبي فدخلت على الرشيد فحدثته بحديثها فأمر بإحضارها فحضرت فقال لها غني الصوت الذي حدثني إبراهيم عنك أنك غنيته فغنته وهي تبكي فرق الرشيد لها وتغرغرت عيناه وقال لها أتحبين أن أشتريك فقالت يا أمير المؤمنين لقد عرضت علي ما يقصر عنه الأمل ولكن ليس من الوفاء أن يملكني أحد بعد سيدي فينتفع بي فازداد رقة عليها وقال غني صوتا آخر فغنت\n(العين تظهر كتماني وتبديه ... والقلب يكتم ما ضمنته فيه)\n(فكيف ينكتم المكتوم بينهما ... والعين تظهره والقلب يخفيه)\nأمر بأن تبتاع وتعتق ولم يزل يجري عليها إلى أن ماتت","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":22,"spl":"الموصلي يغني الرشيد والرشيد يجزل صلته — قصته مع الرشيد بشأن جارية"},
{"id":"b52-41","bab":"الجزء 5","sec":"قصته مع الرشيد بشأن جارية","page":"ج5 ص240","text":"أخبرنا محمد قال حدثنا حماد عن أبيه عن جده قال قال لي الرشيد يوما يا إبراهيم بكر علي غدا حتى نصطبح فقلت له أنا والصبح كفرسي رهان فبكرت فإذا أنا به خاليا وبين يديه جارية كأنها خوط بان أو جدل عنان حلوة المنظر دمثة الشمائل وفي يدها عود فقال لها غني فغنت في شعر أبي نواس وهو\n(توهمه قلبي فأصبح خده ... وفيه مكان الوهم من نظري أثر)\n(ومر بفكري خاطرا فجرحته ... ولم أر جسما قط يجرحه الفكر)\n(وصافحه قلبي فآلم كفه ... فمن غمز قلبي في أنامله عقر)\nال إبراهيم فذهبت والله بعقلي حتى كدت أن أفتضح فقلت من هذه يا أمير المؤمنين فقال هذه التي يقول فيها الشاعر\n(لها قلبي الغداة وقلبها لي ... فنحن كذاك في جسدين روح)\nم قال لها غني فغنت صوت\n(تقول غداة البين إحدى نسائهم ... لي الكبد الحرى فسر ولك الصبر)\n(وقد خنقتها عبرة فدموعها ... على خدها بيض وفي نحرها صفر)\nالشعر لأبي الشيص والغناء لعمرو بن بانة خفيف رمل بالوسطى من كتابه وفيه لمتيم ثاني ثقيل وخفيف رمل آخر قال فشرب وسقاني ثم سقاها ثم قال غن يا إبراهيم فغنيت حسب ما في قلبي غير متحفظ من شيء\n(تشرب قلبي حبها ومشى به ... تمشي حميا الكأس في جسم شارب)\n(ودب هواها في عظامي فشفها ... كما دب في الملسوع سم العقارب)\nال ففطن بتعريضي وكانت جهالة مني قال فأمرني بالانصراف ولم يدعني شهرا ولا حضرت مجلسه فلما كان بعد شهر دس إلي خادما معه رقعة فيها مكتوب\n(قد تخوفت أن أموت من الوجد ... ولم يدر من هويت بما بي)\n(يا كتابي فاقر السلام على من ... لا أسمي وقل له يا كتابي)\n(إن كفا إليك قد بعثتني ... في شقاء مواصل وعذاب)\nأتاني الخادم بالرقعة فقلت له ما هذا قال رقعة الجارية فلانة التي غنتك بين يدي أمير المؤمنين فأحسست القصة فشتمت الخادم ووثبت عليه وضربته ضربا شفيت به نفسي وغيظي وركبت إلى الرشيد من فوري فأخبرته القصة وأعطيته الرقعة فضحك حتى كاد يستلقي ثم قال على عمد فعلت ذلك بك لأمتحن مذهبك وطريقتك ثم دعا بالخادم فلما خرج رآني فقال لي قطع الله يديك ورجليك ويحك قتلتني فقلت القتل والله كان بعض حقك لما وردت به علي ولكن رحمتك فأبقيت عليك وأخبرت أمير المؤمنين ليأتي في عقوبتك بما تستحقه فأمر لي الرشيد بصلة سنية والله يعلم أني ما فعلت الذي فعلت عفافا ولكن خوفا","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":22,"spl":"الموصلي يغني الرشيد والرشيد يجزل صلته — قصته مع الرشيد بشأن جارية"},
{"id":"b52-42","bab":"الجزء 5","sec":"الرشيد يسأله كيف يصوغ الألحان","page":"ج5 ص242","text":"أخبرني محمد بن خلف بن المرزبان قال حدثني حماد بن إسحاق قال أخبرني أبي أنه سمع الرشيد وقد سأل جدي إبراهيم كيف يصنع إذا أراد أن يصوغ الألحان فقال يا أمير المؤمنين أخرج الهم من فكري وأمثل الطرب بين عيني فتسوغ لي مسالك الألحان التي أريد فأسلكها بدليل الإيقاع فأرجع مصيبا ظافرا بما أريد فقال يحق لك يا إبراهيم أن تصيب وتظفر وإن حسن وصفك لمشاكل حسن صنعتك وغنائك أخبرني ابن المرزبان قال حدثني حماد عن أبيه عن جده قال أدركت يونس الكاتب وهو شيخ كبير فعرضت عليه غنائي فقال إن\nعشت كنت مغني دهرك قال حماد قال لي محمد بن الحسن كان لكل واحد من المغنين مذهب في الخفيف والثقيل وكان معبد ينفرد بالثقيل وابن سريج بالرمل وحكم بالهزج ولم يكن في المغنين أحد يتصرف في كل مذهب من الأغاني إلا ابن سريج وإبراهيم جدك وأبوك إسحاق حدثني عمي قال حدثني أحمد بن الطيب السرخسي قال حدثني أحمد ابن ثابت العبدي عن أبي الهذيل العلاف رأس المعتزلة عن ثمامة بن أشرس قال مررت بإبراهيم الموصلي ويزيد حوراء وهما مصطبحان وقد أخذا بينهما صوتا يغنيانه هذا بيتا وهذا بيتا وهو صوت\n(أيا جبلي نعمان بالله خليا ... سبيل الصبا يخلص إلي نسيمها)\n(فإن الصبا ريح إذا ما تنسمت ... على نفس مهموم تجلت همومها)\nقال ثمامة فوالله ما خلت أن شيئا بقي من لذات الدنيا بعد ما كانا فيه أخبرنا محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه عن جده إبراهيم قال سألت الرشيد أن يهب لي يوما في الجمعة لا يبعث فيه إلي بوجه ولا بسبب لأخلو فيه بجواري وإخواني فأذن لي في يوم السبت وقال لي هو يوم أستثقله فآله فيه بما شئت فأقمت يوم السبت بمنزلي وتقدمت في إصلاح طعامي وشرابي بما احتجت إليه وأمرت بوابي فأغلق الأبواب وتقدمت إليه ألا يأذن علي لأحد فبينا أنا في مجلسي والخدم قد حفوا بي وجواري يترددن بين يدي إذا أنا بشيخ ذي هيئة وجمال عليه خفان قصيران وقميصان ناعمان وعلى رأسه قلنسوة لاطئة وبيده عكازة مقمعة بفضة وروائح المسك تفوح منه حتى ملأ البيت والدار فداخلني بدخوله علي مع ما تقدمت فيه غيظ ما تداخلني قط مثله وهممت بطرد بوابي ومن حجبني لأجله فسلم علي أحسن سلام فرددت عليه وأمرته بالجلوس فجلس ثم أخذ بي في أحاديث الناس وأيام العرب وأحاديثها وأشعارها حتى سلى ما بي من الغضب وظننت أن غلماني تحروا مسرتي بإدخالهم مثله علي لأدبه وظرفه فقلت هل لك في الطعام فقال لا حاجة لي فيه فقلت هل لك في الشراب فقال ذلك إليك فشربت رطلا وسقيته مثله فقال لي يا أبا إسحاق هل لك أن تغني لنا شيئا من صنعتك وما قد نفقت به عند الخاص والعام فغاظني قوله ثم سهلت على نفسي أمره فأخذت العود فجسسته ثم ضربت فغنيت فقال أحسنت يا إبراهيم\nفازداد غيظي وقلت ما رضي بما فعله من دخوله علي بغير إذن واقتراحه أن أغنيه حتى سماني ولم يكنني ولم يجمل مخاطبتي ثم قال هل لك أن تزيدنا فتذممت فأخذت العود فغنيت فقال أجدت يا أبا إسحاق فأتم حتى نكافئك ونغنيك فأخذت العود وتغنيت وتحفظت وقمت بما غنيته إياه قياما تاما ما تحفظت مثله ولا قمت بغناء كما قمت به له بين يدي خليفة قط ولا غيره لقوله لي أكافئك فطرب وقال أحسنت يا سيدي ثم قال أتأذن لعبدك بالغناء فقلت شأنك واستضعفت عقله في أن يغنيني بحضرتي بعد ما سمعه مني فأخذ العود وجسه وحبسه فوالله لخلته ينطق بلسان عربي لحسن ما سمعته من صوته ثم تغنى صوت\n(ولي كبد مقروحة من يبيعني ... بها كبدا ليست بذات قروح)\n(أباها علي الناس لا يشترونها ... ومن يشتري ذا علة بصحيح)\n(أئن من الشوق الذي في جوانبي ... أنين غصيص بالشراب جريح)\nال إبراهيم فوالله لقد ظننت الحيطان والأبواب وكل ما في البيت يجيبه ويغني معه من حسن غنائه حتى خلت والله أني أسمع أعضائي وثيابي تجاوبه وبقيت مبهوتا لا أستطيع الكلام ولا الجواب ولا الحركة لما خالط قلبي ثم غنى صوت\n(ألا يا حمامات اللوى عدن عودة ... فإني إلى أصواتكن حزين)\n(فعدن فلما عدن كدن يمتنني ... وكدت بأسراري لهن أبين)\n(دعون بترداد الهدير كأنما ... سقين حميا أو بهن جنون)\n(فلم تر عيني مثلهن حمائما ... بكين ولم تدمع لهن عيون)","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":23,"spl":"الرشيد يسأله كيف يصوغ الألحان"},
{"id":"b52-43","bab":"الجزء 5","sec":"الرشيد يسأله كيف يصوغ الألحان","page":"ج5 ص242","text":"م أعرف في هذه الأبيات لحنا ينسب إلى إبراهيم والذي عرفته لمحمد بن الحارث بن بسخنر خفيف رمل فكاد والله أعلم عقلي أن يذهب طربا وارتياحا لما سمعت ثم غنى صوت\n(ألا يا صبا نجد متى هجت من نجد ... لقد زادني مسراك وجدا على وجد)\n(أأن هتفت ورقاء في رونق الضحى ... على فنن غض النبات من الرند)\n(بكيت كما يبكي الحزين صبابة ... وذبت من الحزن المبرح والجهد)\n(وقد زعموا أن المحب إذا دنا ... يمل وأن النأي يشفي من الوجد)\n(بكل تداوينا فلم يشف ما بنا ... على أن قرب الدار خير من البعد)\nم قال يا إبراهيم هذا الغناء الماخوري فخذه وانح نحوه في غنائك وعلمه جواريك فقلت أعده علي فقال لست تحتاج قد أخذته وفرغت منه ثم غاب من بين يدي فارتعت وقمت إلى السيف فجردته وعدوت نحو أبواب الحرم فوجدتها مغلقة فقلت للجواري أي شيء سمعتن عندي فقلن سمعنا أحسن غناء سمع قط فخرجت متحيرا إلى باب الدار فوجدته مغلقا فسألت البواب عن الشيخ فقال لي أي\nشيخ هو والله ما دخل إليك اليوم أحد فرجعت لأتأمل أمري فإذا هو قد هتف بي من بعض جوانب البيت لا بأس عليك يا أبا إسحاق أنا إبليس وأنا كنت جليسك ونديمك اليوم فلا ترع فركبت إلى الرشيد وقلت لا أطرفه أبدا بطرفه مثل هذه فدخلت إليه فحدثته بالحديث فقال ويحك تأمل هذه الأصوات هل أخذتها فأخذت العود أمتحنها فإذا هي راسخة في صدري كأنها لم تزل فطرب الرشيد عليها وجلس يشرب ولم يكن عزم على الشراب وأمر لي بصلة وحملان وقال الشيخ كان أعلم بما قال لك من أنك أخذتها وفرغت منها فليته أمتعنا بنفسه يوما واحدا كما أمتعك","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":24,"spl":"الرشيد يسأله كيف يصوغ الألحان — نسبة هذه الأصوات"},
{"id":"b52-44","bab":"الجزء 5","sec":"نسبة هذه الأصوات","page":"ج5 ص247","text":"أما الصوت الأول فالذي أعرفه فيه خفيف رمل لمحمد بن الحارث بن بسخنر ولم يقع إلي فيه صنعة لإبراهيم والصوت الثاني الذي أوله\n(ألا يا صبا نجد متى هجت من نجد ... )\nشعره ليزيد بن الطثرية والغناء لإبراهيم خفيف ثقيل بالبنصر عن عمرو وفيه لمحمد بن الحسن بن مصعب ثاني ثقيل بالوسطى عن الهشامي\nوعمرو وذكر إبراهيم أن فيه لحنا لدحمان ولحنا لابنه الزبير ولم يذكر في أي طريقة هما هكذا حدثنا ابن أبي الأزهر بهذا الخبر وما أدري ما أقول فيه ولعل إبراهيم صنع هذه الحكاية ليتنفق بها أو صنعت وحكيت عنه إلا أن للخبر أصلا الأشبه بالحق منه ما حدثني به أحمد بن عبد العزيز الجوهري وأحمد بن عبيد الله بن عمار قالا حدثنا عمر بن شبة قال حدثنا إسحاق بن إبراهيم الموصلي عن أبيه قال صنعت لحنا فأعجبني وجعلت أطلب شعرا فعسر ذلك علي ورأيت في المنام كأن رجلا لقيني فقال يا إبراهيم أأعياك شعر لغنائك هذا الذي تعجب به قلت نعم قال فأين أنت من قول ذي الرمة حيث قال\n(ألا يا اسلمي يا دار مي على البلى ... ولا زال منهلا بجرعائك القطر)\n(وإن لم تكوني غير شام بقفرة ... تجر بها الأذيال صيفية كدر)\nال فانتبهت وأنا فرح بالشعر فدعوت من ضرب علي وغنيته فإذا هو أوفق ما خلق الله فلما علمت ذلك وعملت هذا الغناء في شعر ذي الرمة تنبهت عليه وعلى شعره فصنعت فيه ألحانا ماخورية منها صوت\n(أمنزلتي مي سلام عليكما ... هل الأزمن اللائي مررن رواجع)\n(وهل يرجع التسليم أو يكشف العمى ... ثلاث الأثافي أو رسوم بلاقع)\nنعة إبراهيم في هذين الشعرين جميعا من الماخوري بالوسطى وهو خفيف الثقيل الثاني وأخباره كلها في هذا المعنى تأتي في أخبار ذي الرمة مشروحة","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":24,"spl":"الرشيد يسأله كيف يصوغ الألحان — نسبة هذه الأصوات","partialRef":{"sid":"b52-43","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b52-45","bab":"الجزء 5","sec":"سأل الرشيد أن يختصه بالغناء في شعر ذي الرمة","page":"ج5 ص249","text":"حدثني محمد بن مزيد قال حدثني حماد عن أبيه قال قال لي أبي قال لي جعفر بن يحيى يوما وقد علم أن الرشيد أذن لي وللمغنين في الانصراف يومئذ صر إلي حتى أهب لك شيئا حسنا فصرت إليه فقال لي أيما أحب إليك أهب لك الشيء الحسن الذي وعدتك به أم أرشدك إلى شيء تكسب به ألف ألف درهم فقلت بل يرشدني الوزير أعزه الله إلى هذا الوجه فإنه يقوم مقام إعطائه إياي هذا الحسن فقال إن أمير المؤمنين يحفظ شعر ذي الرمة حفظ الصبا ويعجبه ويؤثره فإذا سمع\nغناء أطربه أكثر مما يطربه غيره مما لا يحفظ شعره فإذا غنيته فأطربته وأمر لك بجائزة فقم على رجليك قائما وقبل الأرض بين يديه وقل له لي حاجة غير هذه الجائزة أريد أن أسألها أمير المؤمنين وهي حاجة تقوم عندي مقام كل فائدة ولا تضره ولا ترزؤه فإنه سيقول لك أي شيء حاجتك فقل قطيعة تقطعنيها سهلة عليك لا قيمة لها ولا منفعة فيها لأحد فإذا أجابك إلى ذلك فقل له تقطعني شعر ذي الرمة أغني فيه ما أختاره وتحظر على المغنين جميعا أن يداخلوني فيه فإني أحب شعره وأستحسنه فلا أحب أن ينغصه علي أحد منهم وتوثق منه في ذلك فقبلت ذلك القول منه وما انصرفت من عنده بعد ذلك إلا بجائزة وتوخيت وقت الكلام في هذا المعنى حتى وجدته فقمت فسألت كما قال لي وتبينت السرور في وجهه وقال ما سألت شططا قد أقطعتك سؤلتك فجعلوا يتضاحكون من قولي ويقولون لقد استضخمت القطيعة وهو ساكت فقلت يا أمير المؤمنين أتأذن لي في التوثق قال توثق كيف شئت فقلت بالله وبحق رسوله وبتربة أمير المؤمنين المهدي إلا جعلتني على ثقة من ذلك بأنك تحلف لي أنك لا تعطي أحدا من المغنين جائزة على شيء يغنيه في شعر ذي الرمة فإن ذلك وثيقتي فحلف مجتهدا لهم لئن غناه أحد منهم في شعر ذي الرمة لا أثابه بشيء ولا بره ولا سمع غناءه فشكرت فعله وقبلت الأرض بين يديه وانصرفنا فغنيت مائة صوت وزيادة في شعر ذي الرمة فكان إذا سمع منها صوتا طرب وزاد طربه ووصلني فأجزل ولم ينتفع به أحد منهم غيري فأخذت منه والله بها ألف ألف درهم وألف ألف درهم أخبرني جعفر بن قدامة بن زياد الكاتب قال حدثني هارون بن محمد بن عبد الملك الزيات قال حدثني أبو خالد الأسلمي قال حدثني محمد بن عمر الجرجاني قال\nقال إبراهيم الموصلي أرتج علي فلم أجد شعرا أصوغ فيه غناء أغني فيه الرشيد فدخلت إلى بعض حجر داري مغموما فأسبلت الستور علي وغلبتني عيني فتمثل لي في البيت شيخ أشوه الخلقة فقال لي يا موصلي مالي أراك مغموما قلت لم أصب شعرا أغني فيه الرشيد الليلة قال فأين أنت عن قول ذي الرمة\n(ألا يا اسلمي يا دار مي على البلى ... ولا زال منهلا بجرعائك القطر)\n(وإن لم تكوني غير شام بقفرة ... تجر بها الأذيال صيفية كدر)\n(أقامت بها حتى ذوى العود في الثرى ... وساق الثريا في ملاءته الفجر)\n(وحتى اعتلى البهمى من الصيف نافض ... كما نفضت خيل نواصيها شقر)\nال وغناني فيه بلحن وكرره حتى علقته فانتبهت وأنا أديره فناديت جارية لي وأمرتها بإحضار عود وما زلت أترنم بالصوت وهي تضرب حتى استوى لي ثم صرت إلى هارون فغنيته إياه فأسكت المغنين ثم قال أعد فأعدت فما زال ليلته يستعيدنيه فلما أصبح أمر لي بثلاثين ألف درهم وبفرش البيت الذي كنا فيه وقال عليك بشعر ذي الرمة فغن فيه فصنعت فيه غناء كثيرا فكنت أغنيه به فيعجبه ويجزل صلتي أخبرني عمي وابن المرزبان والحسن بن علي قالوا حدثنا عبد الله بن\nأبي سعد قال حدثنا محمد بن عبد الله السلمي قال حدثنا أبو غانم مولى جبلة ابن يزيد السلمي قال اجتمع إبراهيم الموصلي وزلزل وبرصوما بين يدي الرشيد فضرب زلزل وزمر برصوما وغنى إبراهيم صوت\n(صحا قلبي وراع إلي عقلي ... وأقصر باطلي ونسيت جهلي)\n(رأيت الغانيات وكن صورا ... إلي صرمنني وقطعن حبلي)\nطرب هارون حتى وثب على رجليه وصاح يا آدم لو رأيت من يحضرني من ولدك اليوم لسرك ثم جلس وقال أستغفر الله الشعر الذي غنى فيه إبراهيم لأبي العتاهية والغناء لإبراهيم خفيف ثقيل بالبنصر حدثني جحظة قال حدثني حماد بن إسحاق عن أبيه قال كان الرشيد يجد بماردة وجدا شديدا فغضبت عليه وغضب عليها وتمادى بينهما الهجر أياما فأمر جعفر بن يحيى العباس بن الأحنف فقال\n(راجع أحبتك الذين هجرتهم ... إن المتيم قلما يتجنب)\n(إن التجنب إن تطاول منكما ... دب السلوله فعز المطلب)","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":25,"spl":"سأل الرشيد أن يختصه بالغناء في شعر ذي الرمة"},
{"id":"b52-46","bab":"الجزء 5","sec":"سأل الرشيد أن يختصه بالغناء في شعر ذي الرمة","page":"ج5 ص249","text":"وأمر إبراهيم الموصلي فغنى فيه الرشيد فلما سمعه بادر إلى ماردة\nفترضاها فسألت عن السبب في ذلك فعرفته فأمرت لكل واحد من العباس وإبراهيم بعشرة آلاف درهم وسألت الرشيد أن يكافئهما عنها فأمر لهما بأربعين ألف درهم","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":26,"spl":"سأل الرشيد أن يختصه بالغناء في شعر ذي الرمة — فطنته في صناعة الموسيقى"},
{"id":"b52-47","bab":"الجزء 5","sec":"جائزة الرشيد الأولى كانت لإبراهيم الموصلي","page":"ج5 ص253","text":"أخبرني جعفر بن قدامة عن حماد عن أبيه قال أول جائزة خرجت لشاعر من الرشيد لما ولي الخلافة جائزة لإبراهيم فإنه قال يمدحه لما ولي صوت\n(ألم تر أن الشمس كانت مريضة ... فلما ولي هارون أشرق نورها)\n(فألبست الدنيا جمالا بوجهه ... فهارون واليها ويحيى وزيرها)\nغنى فيه فأمر له بمائة ألف درهم وأمر له يحيى بخمسين ألف درهم أخبرنا الحسن بن علي قال حدثنا عبد الله بن أبي سعد قال حدثني محمد بن عبد الله بن مالك قال حدثني إسحاق الموصلي أن أباه لعب يوما مع الرشيد بالنرد في الخلعة التي كانت على الرشيد والخلعة التي كانت عليه هو فتقامر للرشيد فلما قمره قام إبراهيم فنزع ثيابه ثم قال للرشيد حكم النرد الوفاء به وقد قمرت ووفيت لك فالبس ما كان علي فقال له الرشيد ويلك أنا ألبس ثيابك فقال إي والله إذا أنصفت وإذا لم تنصف قدرت وأمكنك قال ويلك أو أفتدي منك قال نعم قال وما الفداء قال قل أنت يا أمير المؤمنين فإنك\nأولى بالقول فقال أعطيك كل ما علي قال فمر به يا أمير المؤمنين وأنا أستخير الله في ذلك فدعا بغير ما عليه فلبسه ونزع ما كان عليه فدفعه إلى إبراهيم","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":26,"spl":"سأل الرشيد أن يختصه بالغناء في شعر ذي الرمة — فطنته في صناعة الموسيقى"},
{"id":"b52-48","bab":"الجزء 5","sec":"فطنته في صناعة الموسيقى","page":"ج5 ص254","text":"أخبرني إسماعيل بن يونس قال حدثني عمر بن شبة قال حدثني علي بن عبد الكريم قال زار ابن جامع إبراهيم الموصلي فأخرج إليه ثلاثين جارية فضربن جميعا طريقة واحدة وغنين فقال ابن جامع في الأوتار وتر غير مستو فقال إبراهيم يا فلانة شدي مثناك فشدته فاستوى فعجبت أولا من فطنة ابن جامع لوتر في مائة وعشرين وترا غير مستو ثم ازداد عجبي من فطنة إبراهيم له بعينه أخبرني إسماعيل بن يونس وحبيب بن نصر المهلبي قالا حدثنا عمر ابن شبة قال حدثني إسحاق بن إبراهيم قال حدثني أبي قال كنا مع الرشيد بالرقة وكان هناك خمار أقصده أشتري منه شرابا حسنا طيبا وربما شربت في حانته فأتيته يوما فبزل لي دنا في باطية له فرأيت لونه حسنا صافيا فاندفعت أغني صوت\n(اسقني صهباء صرفا ... لم تدنس بمزاج)\n(اسقني والليل داج ... قبل أصوات الدجاج)\n(يا أبا وهب خليلي ... كل هم لانفراج)\n(حين توهت بقلبي ... في أعاصير الفجاج)\nلغناء في هذه الأبيات لإبراهيم هزج بالوسطى عن عمرو وفيها لسياط ثاني ثقيل بالخنصر في مجرى البنصر عن إسحاق قال فدهش الخمار يسمع صوتي فقلت له ويحك قد فاض النبيذ من الباطية فقال دعني من النبيذ يا أبا إسحاق مالي أرى صوتك حزينا حريقا مات لك بالله إنسان فلما جئت إلى الرشيد حدثته بذلك فجعل يضحك","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":26,"spl":"سأل الرشيد أن يختصه بالغناء في شعر ذي الرمة — فطنته في صناعة الموسيقى"},
{"id":"b52-49","bab":"الجزء 5","sec":"قصته مع الرشيد والجواري","page":"ج5 ص255","text":"وذكر أحمد بن أبي طاهر أن المدائني حدث قال قال إبراهيم الموصلي قال لي الرشيد يوما يا إبراهيم إني قد جعلت غدا للحريم وجعلت ليلته للشرب مع الرجال وأنا مقتصر عليك من المغنين فلا تشتغل غدا بشيء ولا تشرب نبيذا وكن بحضرتي في وقت العشاء الآخرة فقلت السمع والطاعة لأمير المؤمنين فقال وحق أبي لئن تأخرت أو اعتللت بشيء لأضربن عنقك أفهمت فقلت نعم وخرجت فما جاءني أحد من إخواني إلا احتجبت عنه ولا قرأت رقعة لأحد حتى إذا صليت المغرب ركبت قاصدا إليه فلما قربت من فناء داره مررت بفناء قصر وإذا زنبيل كبير مستوثق منه بحبال وأربع عزى أدم وقد دلي من القصر وجارية قائمة تنتظر إنسانا قد وعد ليجلس فيه فنازعتني نفسي إلى الجلوس فيه ثم قلت هذا خطأ ولعله أن يجري سبب يعوقني عن الخليفة فيكون الهلاك فلم أزل أنازع نفسي وتنازعني حتى غلبتني فنزلت فجلست فيه ومد الزنبيل حتى صار في أعلى القصر ثم خرجت فنزلت\nفإذا جوار كأنهن المها جلوس فضحكن وطربن وقلن قد جاء والله من أردناه فلما رأينني من قريب تبادرن إلى الحجاب وقلن يا عدو الله ما أدخلك إلينا فقلت يا عدوات الله ومن الذي أردتن إدخاله ولم صار أولى بهذا مني فلم يزل هذا دأبنا وهن يضحكن وأضحك معهن ثم قالت إحداهن أما من أردناه فقد فات وما هذا إلا ظريف فهلم نعاشره عشرة جميلة فأخرج إلي طعام ودعيت إلى أكله فلم يكن في فضل إلا أني كرهت أن أنسب إلى سوء العشرة فأصبت منه إصابة معذر ثم جيء بالنبيذ فجعلنا نشرب وأخرجن إلي ثلاث جوار لهن فغنين غناء مليحا فغنت إحداهن صوتا لمعبد فقالت إحدى الثلاث من وراء الستر أحسن إبراهيم هذا له فقلت كذبت ليس هذا له هذا لمعبد فقالت يا فاسق وما يدريك الغناء ما هو ثم غنت الأخرى صوتا للغريض فقالت تلك أحسن إبراهيم هذا له أيضا فقلت كذبت يا خبيثة هذا للغريض فقالت اللهم أخزه ويلك وما يدريك ثم غنت الجارية صوتا لي فقالت تلك أحسن ابن سريج هذا له فقلت كذبت هذا لإبراهيم وأنت تنسبين غناء الناس إليه وغناءه إليهم فقالت ويحك وما يدريك فقلت أنا إبراهيم فتباشرن بذلك جميعا وطربن كلهن وظهرهن كلهن لي وقلن كتمتنا نفسك وقد سررتنا فقلت أنا الآن أستودعكن الله فقلن وما السبب فأخبرتهن بقصتي مع الرشيد فضحكن وقلن الآن والله طاب حبسك علينا وعلينا إن خرجت أسبوعا فقلت هو والله القتل قلن إلى لعنة الله فأقمت والله عندهن أسبوعا لا أزول فلما كان بعد الأسبوع ودعنني وقلن إن سلمك الله فأنت بعد ثلاث عندنا قلت نعم فأجلسنني في الزنبيل وسرحت فمضيت لوجهي حتى أتيت دار الرشيد وإذا النداء قد أشيع ببغداد في طلبي وأن من أحضرني فقد سوغ ملكي وأقطع مالي فاستأذنت فتبادر الخدم حتى أدخلوني على الرشيد فلما رآني شتمني وقال","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":27,"spl":"قصته مع الرشيد والجواري"},
{"id":"b52-50","bab":"الجزء 5","sec":"قصته مع الرشيد والجواري","page":"ج5 ص255","text":"السيف والنطع إيه يا إبراهيم تهاونت بأمري وتشاغلت بالعوام عما أمرتك به وجلست مع أشباهك من السفهاء حتى أفسدت علي لذتي فقلت يا أمير المؤمنين أنا بين يديك وما أمرت به غير فائت ولي حديث عجيب ما سمع بمثله قط وهو الذي قطعني عنك ضرورة لا اختيارا فاسمعه فإن كان عذرا فأقبله وإلا فأنت أعلم قال هاته فليس ينجيك فحدثته فوجم ساعة ثم قال إن هذا لعجب أفتحضرني معك هذا الموضع قلت نعم وأجلسك معهن إن شئت قبلي حتى تحصل عندهن وإن شئت فعلى موعد قال بل على موعد قلت أفعل فقال انظر قلت ذلك حاصل إليك متى شئت فعدل عن رأيه في وأجلسني وشرب وطرب فلما أصبحت أمرني بالانصراف وأن أجيئه من عندهن فمضيت إليهن في وقت الوعد فلما وافيت الموضع إذا الزنبيل معلق فجلست فيه ومده الجواري فصعدت فلما رأينني تباشرن وحمدن الله على سلامتي وأقمت ليلتي فلما أردت الانصراف قلت لهن إن لي أخا هو عدل نفسي عندي وقد أحب معاشرتكن ووعدته بذلك فقلن إن كنت ترضاه فمرحبا به فوعدتهن ليلة غد وانصرفت وأتيت الرشيد وأخبرته فلما كان الوقت خرج معي متخفيا حتى أتينا الموضع فصعدت وصعد بعدي ونزلنا جميعا وقد كان الله وفقني لأن قلت لهن إذا جاء صديقي فاستترن عني وعنه ولا يسمع لكن نطقة وليكن ما تخترنه من غناء أو تقلنه من قول مراسلة فلم يتعدين ذلك وأقمن على أتم ستر وخفر وشربنا شربا كثيرا وقد كان أمرني ألا أخاطبه بأمير المؤمنين فلما أخذ مني النبيذ قلت سهوا يا أمير المؤمنين فتواثبن من وراء الستارة حتى غابت عنا حركاتهن فقال لي يا إبراهيم لقد أفلت من أمر عظيم والله لو برزت إليك واحدة منهن لضربت عنقك قم بنا فانصرفنا وإذا هن له قد كان غضب\nعليهن فحبسهن في ذلك القصر ثم وجه من غد بخدم فردوهن إلى قصره ووهب لي مائة ألف درهم وكانت الهدايا والألطاف تأتيني بعد ذلك منهن أخبرني جعفر بن قدامة قال حدثنا حماد بن إسحاق عن أبيه قال حدثني أبي قال دخلت على الرشيد يوما فقال لي أنا اليوم كسلان خاثر فإن غنيتني صوتا يوقظ نشاطي أحسنت صلتك فغيته\n(ولم ير في الدنيا محبان مثلنا ... على ما نلاقي من ذوي الأعين الخزر)\n(صفيان لا نرضى الوشاة إذا وشوا ... عفيفان لا نغشى من الأمر ما يزري)\nطرب ودعا بالطعام فأكل وشرب وأمر لي بخمسين ألف درهم","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":28,"spl":"قصته مع الرشيد والجواري"},
{"id":"b52-51","bab":"الجزء 5","sec":"الموصلي يمتحن صوتا للمغنية دنانير","page":"ج5 ص258","text":"أخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة قال حدثني إسحاق قال قال لي أبي قال لي يحيى بن خالد إن ابنتك دنانير قد عملت صوتا أعجبني وأعجبت أيضا هي به فقلت لها لا تعجبي به حتى أعرضه على أبيك أبي إسحاق فقلت له والله ما في معرفة الوزير أعزه الله به ولا بغيره من الصنائع مطعن وإنه لأصح العالم تمييزا وأثقبه فطنة وما أعجبه إلا وهو صحيح حسن فقال إن كنت كما تقول أيضا فإن أهل كل صناعة يمارسونها أفهم بها ممن يعلمها عن عرض من غير ممارسة ولو كنا في هذه الصناعة متساويين لكان الاستظهار\nبرأيك أجود لأن ميلي إلى صانعة الصوت ربما حسن عندي ما ليس بالحسن وإنما يتم سروري به بعد سماعك إياه واستحسانك له على الحقيقة فمضيت فوجدت ستارة منصوبة وأمرا قد تقدم فيه قبلي فجلست فسلمت على الجارية وقلت لها تغنيني الصوت الذي ذكره لي الوزير أعزه الله فقالت إن الوزير قال لي إن استجاده فعرفيني ليتم سروري به وإلا فاطو الخبر عني لئلا تزول رتبته عندي فقلت هاتيه حتى أسمعه فغنت تقول\n(نفسي أكنت عليك مدعيا ... أم حين أزمع بينهم خنت)\n(إن كنت هائمة بذكرهم ... فعلى فراقهم ألا حمت)\nال فأحسنت والله وما قصرت فاستعدته لأطلب فيه موضعا لأصلحه فيكون لي فيه معنى فما وجدت قلت أحسنت والله يا بنية ما شئت ثم عدت إلى يحيى فحلفت له بأيمان رضيها أن كثيرا من حذاق المغنين لا يحسنون أن يصنعوا مثله ولقد استعدته لأرى فيه موضعا يكون لي فيه عمل فما وجدت فقال وصفك لها من أجله يقوم مقام تعليمك إياها فقد والله سررتني وسأسرك فلما انصرفت أتبعني بخمسين ألف درهم حدثني عمي وابن المرزبان قالا حدثنا ابن أبي سعد قال حدثني محمد بن عبد الله السلمي قال حدثني عمر بن شبة قال حدثني إسحاق ولم يقل عن أبيه قال والله إني لفي منزلي ذات يوم وأنا مفكر في الركوب مرة وفي القعود مرة إذا غلامي قد دخل ومعه خادم الرشيد يأمرني بالحضور من وقتي فركبت وصرت إليه فقال لي اجلس يا إبراهيم حتى أريك عجبا فجلست فقال علي بالأعرابية وابنتها فأخرجت إلي أعرابية ومعها بنية لها عشر أو أرجح فقال يا إبراهيم إن هذه الصبية تقول الشعر فقلت\nلأمها ما يقول أمير المؤمنين فقالت هي هذه قدامك فسلها فقلت يا حبيبة أتقولين الشعر فقالت نعم فقلت أنشديني بعض ما قلت فأنشدتني صوت\n(تقول لأتراب لها وهي تمتري ... دموعا على الخدين من شدة الوجد)\n(أكل فتاة لا محالة نازل ... بها مثل ما بي أم بليت به وحدي)\n(براني له حب تنشب في الحشى ... فلم يبق من جسمي سوى العظم والجلد)\n(وجدت الهوى حلوا لذيذا بديئه ... وآخره مر لصاحبه مردي)\nقال الشبي في خبره قال إسحاق وكان أبي حاضرا فقال والله لا تبرح يا أمير المؤمنين أو نصنع في هذه الأبيات لحنا فصغت فيها أنا وأبي وجميع من حضر وقال الآخرون قال إبراهيم فما برحت حتى صنعت فيه لحنا وتغنيت به وهي حاضرة تسمع قال ابن المرزبان في خبره ولم يذكره عمي فقالت يا أمير المؤمنين قد أحسن رواية ما قلت أفتأذن لي أن أكافئه بمدح أقوله فيه قال افعلي فقالت صوت\n(ما لإبراهيم في العلم ... بهذا الشأن ثاني)\n(إنما عمر أبي إسحاق ... زين للزمان)\n(منه يجنى ثمر اللهو ... وريحان الجنان)\n(جنة الدنيا أبو إسحاق ... في كل مكان)\nال فأمر لها الرشيد بجائزة وأمر لي بعشرة آلاف درهم فوهبت لها شطرها اللحن الذي صنعه إبراهيم في شعر الأعرابية ثقيل أول بالوسطى وفيه لعلويه ثاني ثقيل وأما الشعر الثاني فهو لابن سيابة لا يشك فيه ولإبراهيم فيه لحن من خفيف الثقيل أخبرني محمد بن مزيد عن حماد بن إسحاق عن أبيه قال كنت أخذت بالمدينة من مجنون بها هذا الصوت وغنيته الرشيد وقلت صوت\n(هما فتاتان لما تعرفا خلقي ... وبالشباب على شيبي تدلان)\n(رأيت عرسي لما ضمني كبري ... وشخت أزمعتا صرمي وهجراني)\n(كل الفعال الذي يفعلنه حسن ... يصبي فؤادي ويبدي سر أشجاني)\n(بل احذرا صولة من صول شيخكما ... مهلا على الشيخ مهلا يا فتاتان)\nطرب وأمر لي بظبية كانت ملقاة بين يديه فيها ألف دينار مسيفة وكان ابن جامع حاضرا فقال اسمع يا أمير المؤمنين غناء العقلاء ودع غناء المجانين وكان أشد خلق الله حسدا فغناه صوت\n(ولقد قالت لأتراب لها ... كالمها يلعبن في جحرتها)\n(خذن عني الظل لا يتبعني ... ومضت سعيا إلى قبتها)","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":29,"spl":"الموصلي يمتحن صوتا للمغنية دنانير"},
{"id":"b52-52","bab":"الجزء 5","sec":"الموصلي يمتحن صوتا للمغنية دنانير","page":"ج5 ص258","text":"طرب وشرب وأمر له بألف وخمسمائة دينار ثم تبعه محمد بن حمزة وجه القرعة فغنى صوت\n(يمشون فيها بكل سابغة ... أحكم فيها القتير والحلق)\n(يعرف إنصافهم إذا شهدوا ... وصبرهم حين تشخص الحدق)\nفاستحسنه وشرب عليه وأمر له بخمسمائة دينار ثم غنى علوية صوت\n(يجحدن ديني بالنهار وأقتضي ... ديني إذا وقذ النعاس الرقدا)\n(وأرى الغواني لا يواصلن امرأ ... فقد الشباب وقد يصلن الأمردا)\nدعا به الرشيد وقال له يا عاض بظر أمه أتغني في مدح المرد وذم الشيب وستارتي منصوبة وقد شبت وكأنك تعرض بي ثم دعا مسرورا فأمره أن يأخذ بيده فيضربه ثلاثين درة ويخرجه من مجلسه ففعل وما انتفعنا به بقية يومنا ولا انتفع بنفسه وجفا علويه شهرا ثم سألناه فيه فأذن له قال أبو الفرج لإبراهيم أخبار مع خنث المعروفة بذات الخال وكان يهواها جعلتها في موضع آخر من هذا الكتاب لأنها منفردة بذاتها\nمستغنية عن إدخالها في غمار أخباره وله في هذه الجارية شعر كثير فيه غناء له ولغيره وقد شرطت أن الشيء من أخبار الشعراء والمغنين إذا كانت هذه سبيله أفرده لئلا يقطع بين القرائن والنظائر مما تضاف إليه وتدخل فيه","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":30,"spl":"الموصلي يمتحن صوتا للمغنية دنانير — خبر موته"},
{"id":"b52-53","bab":"الجزء 5","sec":"خبر موته","page":"ج5 ص263","text":"أخبرني محمد بن يحيى الصولي قال حدثني الحسين بن يحيى قال سمعت إسحاق الموصلي يقول لما دخلت سنة ثمان وثمانين ومائة اشتد أمر القولنج على أبي ولزمه وكان يعتاده أحيانا فقعد عن خدمة الخليفة وعن نوبته في داره فقال في ذلك صوت\n(مل والله طبيبي ... من مقاساة الذي بي)\n(سوف أنعى عن قريب ... لعدو وحبيب)\nغني فيه لحنا من الرمل فكان آخر شعر قاله وآخر لحن صنعه أخبرني الصولي عن محمد بن موسى عن حماد بن إسحاق عن أبيه أن الرشيد ركب حمارا ودخل إلى إبراهيم يعوده وهو في الأبزن جالس فقال له كيف أنت يا إبراهيم فقال أنا والله يا سيدي كما قال الشاعر\n(سقيم مل منه أقربوه ... وأسلمه المداوي والحميم)\nفقال الرشيد إنا لله وخرج فلم يبعد حتى سمع الواعية عليه","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":30,"spl":"الموصلي يمتحن صوتا للمغنية دنانير — خبر موته"},
{"id":"b52-54","bab":"الجزء 5","sec":"المأمون يصلي عليه بعد موته","page":"ج5 ص264","text":"أخبرني إسماعيل بن يونس قال حدثني عمر بن شبة قال مات إبراهيم الموصلي سنة ثمان وثمانين ومائة ومات في ذلك اليوم الكسائي النحوي والعباس بن الأحنف الشاعر وهشيمة الخمارة فرفع ذلك إلى الرشيد فأمر المأمون أن يصلي عليهم فخرج فصفوا بين يديه فقال من هذا الأول قيل إبراهيم فقال أخروه وقدموا العباس بن الأحنف فقدم فصلى عليهم فلما فرغ وانصرف دنا منه هاشم بن عبد الله ابن مالك الخزاعي قال يا سيدي كيف آثرت العباس بالتقدمة على من حضر قال لقوله\n(وسعى بها ناس فقالوا إنها ... لهي التي تشقى بها وتكابد)\n(فجحدتهم ليكون غيرك ظنهم ... إني ليعجبني المحب الجاحد)\nم قال أتحفظها قلت نعم فقال أنشدني باقيها فأنشدته\n(لما رأيت الليل سد طريقه ... عني وعذبني الظلام الراكد)\n(والنجم في كبد السماء كأنه ... أعمى تحير ما لديه قائد)\n(ناديت من طرد الرقاد بصده ... عما أعالج وهو خلو هاجد)\n(ياذا الذي صدع الفؤاد بهجره ... أنت البلاء طريفه والتالد)\n(ألقيت بين جفون عيني حرقة ... فإلى متى أنا ساهر يا راقد)\nقال المأمون أليس من قال هذا الشعر حقيقا بالتقدمة فقلت بلى والله يا سيدي أخبرني يحيى بن علي بن يحيى قال قال حدثني حماد بن إسحاق قال حدثني أبي قال قال لي برصوما الزامر أما في حقي وخدمتي وميلي إليكم وشكري لكم ما أستوجب به أن تهب لي يوما من عمرك تفعل فيه ما أريد ولا تخالفني في شيء فقلت بلى ووعدته بيوم فأتاني فقال مر لي بخلعة ففلعت وجعلت فيها جبة وشي فلبسها ظاهرة وقال امض بنا إلى المجلس الذي كنت آتي أباك فيه فمضينا جميعا إليه وقد خلقته وطيبته فلما صار على باب المجلس رمى بنفسه إلى الأرض فتمرغ في التراب وبكى وأخرج نايه وجعل ينوح في زمره ويدور في المجلس ويقبل المواضع التي كان أبو إسحاق يجلس فيها ويبكي ويزمر حتى قضى من ذلك وطرا ثم ضرب بيده إلى ثيابه فشقها وجعلت أسكته وأبكي معه فما سكن إلا بعد حين ثم دعا بثيابه فلبسها وقال إنما سألتك أن تخلع علي لئلا يقال إن برصوما إنما خرق\nثيابه ليخلع عليه ما هو خير منها ثم قال امض بنا إلى منزلك فقد اشتفيت مما أردت فعدت إلى منزلي وأقام عندي يومه وانصرف بخلعة مجددة أخبرني إسماعيل بن يونس قال حدثني عمر بن شبة قال حدثني القاسم ابن يزيد قال لما مات إبراهيم الموصلي دخلت على إبراهيم بن المهدي وهو يشرب وجواريه يغنين فذكرنا إبراهيم الموصلي وحذقه وتقدمه فأفضنا في ذلك وإبراهيم مطرق فلما طال كلامنا وقال كل واحد منا مثل ما قاله صاحبه اندفع إبراهيم بن المهدي يغني في شعر لابن سيابة يرثي به إبراهيم ويقال إن الأبيات لأبي الأسد\n(تولى الموصلي فقد تولت ... بشاشات المزاهر والقيان)\n(وأي بشاشة بقيت فتبقى ... حياة الموصلي على الزمان)\n(ستبكيه المزاهر والملاهي ... وتسعدهن عاتقة الدنان)\n(وتبكيه الغوية إذ تولى ... ولا تبكيه تالية القران)\nال فأبكى من حضر وقلت أنا في نفسي أفتراه هو إذا مات من يبكيه المحراب أم المصحف قال وكان كالشامت بموته أخبرني يحيى بن علي قال قال أنشدني حماد قال أنشدني أبي لنفسه\nيرثي أباه وأنشدها غير يحيى وفيها زيادة على روايته\n(أقول له لما وقفت بقبره ... عليك سلام الله يا صاحب القبر)\n(أيا قبر إبراهيم حييت حفرة ... ولا زلت تسقى الغيث من سبل القطر)\n(لقد عزني وجدي عليك فلم يدع ... لقلبي نصيبا من عزاء ولا صبر)\n(وقد كنت أبكي من فراقك ليلة ... فكيف وقد صار الفراق إلى الحشر)\nخبرني أحمد بن محمد بن إسماعيل بن إبراهيم الموصلي الملقب بوسواسة قال أنشدني حماد لأبيه إسحاق يرثي أباه إبراهيم الموصلي\n(سلام على القبر الذي لا يجيبنا ... ونحن نحيي تربه ونخاطبه)\n(ستبكيه أشراف الملوك إذا رأوا ... محل التصابي قد خلا منه جانبه)\n(ويبكيه أهل الظرف طرا كما بكى ... عليه أمير المؤمنين وحاجبه)\n(ولما بدا لي اليأس منه وأنزفت ... عيون بواكيه وملت نوادبه)\n(وصار شفاء النفس من بعض ما بها ... إفاضة دمع تستهل سواكبه)\n(جعلت على عيني للصبح عبرة ... ولليل أخرى ما بدت لي كواكبه)\nال وأنشدني أيضا حماد لأبيه يرثي أباه\n(عليك سلام الله من قبر فاجع ... وجادك من نوء السماكين وابل)\n(هل انت محيي القبر أم أنت سائل ... وكيف تحيا تربة وجنادل)\n(أظل كأني لم تصبني مصيبة ... وفي الصدر من وجد عليك بلابل)","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":31,"spl":"المأمون يصلي عليه بعد موته"},
{"id":"b52-55","bab":"الجزء 5","sec":"المأمون يصلي عليه بعد موته","page":"ج5 ص264","text":"(وهون عندي فقده أن شخصه ... على كل حال بين عيني ماثل)\nخبرنا يحيى بن علي قال حدثني أبو أيوب المديني قال أنشدني إبراهيم ابن علي بن هشام لرجل يرثي إبراهيم الموصلي\n(أصبح اللهو تحت عفر التراب ... ثاويا في محلة الأحباب)\n(إذ ثوى الموصلي فانقرض اللهو ... بخير الإخوان والأصحاب)\n(بكت المسمعات حزنا عليه ... وبكاه الهوى وصفو الشراب)\n(وبكت آلة المجالس حتى ... رحم العود دمعة المضراب)","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":32,"spl":"المأمون يصلي عليه بعد موته — صوت من المائة المختارة"},
{"id":"b52-56","bab":"الجزء 5","sec":"إسحاق الموصلي يذكر أباه عند الرشيد ويبكي","page":"ج5 ص268","text":"أخبرني محمد بن مزيد قال حدثنا حماد عن أبيه قال دخلت إلى الرشيد بعقب وفاة أبي وذلك بعد شهر من يوم وفاته فلما جلست ورأيت موضعه الذي كان يجلس فيه خاليا دمعت عيني فكففتها وتصبرت ولمحني الرشيد فدعاني إليه وأدناني منه فقبلت يده ورجله والأرض بين يديه فاستعبر وكان رقيقا فوثبت قائما ثم قلت\n(في بقاء الخليفة الميمون ... خلف من مصيبة المحزون)\n(لا يضير المصاب رزء إذا ما ... كان ذا مفزع إلى هارون)\nقال لي كذاك والله هو ولن تفقد من أبيك ما دمت حيا إلا شخصه وأمر بإضافة رزقه إلى رزقي فقلت بل يأمر أمير المؤمنين به إلى ولده ففي خدمتي إياه ما يغنيني فقال اجعلوا رزق إبراهيم لولده وأضعفوا رزق إسحاق","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":32,"spl":"المأمون يصلي عليه بعد موته — صوت من المائة المختارة"}]);
window.__BOOK__['p03'].push([{"id":"b52-57","bab":"الجزء 5","sec":"صوت من المائة المختارة","page":"ج5 ص269","text":"(يا دار سعدى بالجزع من ملل ... حييت من دمنة ومن طلل)\n(إني إذا ما البخيل أمنها ... باتت ضموزا مني على وجل)\n(لا أمتع العوذ بالفصال ولا ... أبتاع إلا قريبة الأجل)\nلعوذ الإبل التي قد نتجت واحدتها عائذ يقول أنحرها وأولادها للأضياف فلا أمتعها والضموز الممسكة عن أن تجتر ضمز الجمل بجرته إذا أمسك عنها ودسع بها إذا استعملها يقول فهذه الناقة من شدة خوفها على نفسها مما رأت من نحر نظائرها قد امتنعت من جرتها فهي ضامزة الشعر لابن هرمة والغناء في اللحن المختار لمرزوق الصراف ثقيل أول بإطلاق الوتر في مجرى البنصر عن إسحاق ويقال إنه ليحيى بن واصل وذكر عمرو بن بانة أن فيه لدحمان لحنا من الثقيل الأول بالبنصر وأن فيه لابن محرز لحنا من الثقيل الثاني بالبنصر في الثالث ثم الثاني ووافقه ابن المكي قال وفيه لدحمان خفيف رمل بالوسطى في الأول والثالث وذكر الهشامي أن هذا اللحن بعينه ليونس وأن الثقيل الثاني لإبراهيم وأن لمعبد فيه لحنا من الثقيل الأول بالوسطى وأن فيه للهذلي خفيف ثقيل وأن فيه رملا ينسب إلى ابن محرز أيضا","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":32,"spl":"المأمون يصلي عليه بعد موته — صوت من المائة المختارة"},
{"id":"b52-58","bab":"الجزء 5","sec":"شيء من ذكر ابن هرمة أيضا","page":"ج5 ص270","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثنا عبد الرحمن بن عبد الله بن عبد العزيز الزهري ونوفل بن ميمون عن يحيى بن عروة بن أذينة قال خرجت في حاجة لي فلما كنت بالسيالة وقفت على منزل إبراهيم بن علي بن هرمة فصحت يا أبا إسحاق فأجابتني ابنته من هذا فقلت انظري فخرجت إلي فقلت أعلمي أبا إسحاق فقالت خرج والله آنفا قال فقلت هل من قرى فإني مقو من الزاد قالت لا والله ما صادفته حاضرا قلت فأين قول أبيك\n(لا أمتع العوذ بالفصال ولا ... أبتاع إلا قريبة الأجل)\nقالت بذاك والله أفناها أخبرني الحسين بن يحيى عن حماد عن أبيه عن أيوب بن عباية بمثل هذا الخبر سواء وزاد فيه قال فأخبرت إبراهيم بن هرمة بقولها فضمها إليه وقال بأبي أنت وأمي أنت والله ابنتي حقا الدار والمزرعة لك\nاخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني نوفل بن ميمون قال حدثني مرقع قال كنت مع ابن هرمة في سقيفة أم أذينة فجاءه راع بقطعة من غنم يشاوره فيما يبيع منها وكان قد أمره ببيع بعضها قال مرقع فقلت يا أبا إسحاق أين عزب عنك قولك\n(لا غنمي مد في الحياة لها ... إلا لدرك القرى ولا إبلي)\nقولك فيها أيضا\n(لا أمتع العوذ بالفصال ولا ... ولا أبتاع إلا قريبة الأجل)\nقال لي مالك أخزاك الله من أخذ منها شيئا فهو له فانتهبناها حتى وقف الراعي وما معه منها شيء وحدثنا بهذا الخبر أحمد بن عبيد الله بن عمار قال حدثني علي بن محمد النوفلي عن أبيه أن ابن هرمة كان اشترى غنما للربح فلقيه رجل فقال له ألست القائل\n(لا غنمي مد في الحياة لها ... إلا لدرك القرى ولا إبلي)\nال نعم قال فوالله إني لأحسبك تدفع عن هذه الغنم المكروه بنفسك وإنك لكاذب فأحفظه ذلك فصاح من أخذ منها شيئا فهو له فانتهبها الناس جميعا وكان ابن هرمة أحد البخلاء أخبرني الحرمي بن أبي العلاء قال حدثني الزبير بن بكار قال حدثني نوفل بن ميمون قال حدثني زفر بن محمد الفهري أن هذه القصيدة أول شعر قاله ابن هرمة\nأخبرنا محمد بن خلف وكيع قال حدثنا حماد بن إسحاق قال قرأت على أبي حدثنا عبد الله بن الوليد الأزدي قال حدثني جعفر بن محمد بن زيد بن علي بن الحسين قال سمع مزبد قول ابن هرمة\n(لا أمتع العوذ بالفصال ولا ... أبتاع إلا قريبة الأجل)\nال صدق ابن الخبيثة إنما كان يشتري الشاة للأضحى فيذبحها من ساعته أخبرنا وكيع قال حدثنا حماد عن أبيه عن عبد الله بن الوليد عن جعفر ابن محمد بن زيد عن أبيه قال اجتمع قوم من قريش أنا فيهم فأحببنا أن نأتي ابن هرمة فنعبث به فتزودنا زادا كثيرا ثم أتيناه لنقيم عنده فلما انتهينا إليه خرج إلينا فقال ما جاء بكم فقلنا سمعنا شعرك فدعانا إليك لما سمعناك قلت\n(إن امرأ جعل الطريق لبيته ... طنبا وأنكر حقه للئيم)\nسمعناك تقول\n(وإذا تنور طارق مستنبح ... نبحت فدلته علي كلابي)\n(وعوين يستعجلنه فلقينه ... يضربنه بشراشر الأذناب)\nسمعناك تقول\n(كم ناقة وجأت منحرها ... بمستهل الشؤبوب أو جمل)\n(لا أمتع العوذ بالفصال ولا ... أبتاع إلا قريبة الأجل)\nال فنظر إلينا طويلا ثم قال ما على وجه الأرض عصابة أضعف عقولا ولا أسخف دينا منكم فقلنا له يا عدو الله يا دعي أتيناك زائرين وتسمعنا هذا الكلام فقال أما سمعتم الله تعالى يقول للشعراء ( وأنهم يقولون ما لا يفعلون\nأفيخبركم الله أني أقول ما لا أفعل وتريدون مني أن أفعل ما أقول قال فضحكنا منه وأخرجناه معنا فأقام عندنا في نزهتنا يشركنا في زادنا حتى انصرفنا إلى المدينة أخبرنا عمي قال حدثني محمد بن سعيد الكراني عن عبد الرحمن ابن أخي الأصمعي عن عمه قال الحكم الخضري وابن ميادة ورؤبة وابن هرمة\nوطفيل الكناني ومكين العذري كانوا على ساقة الشعراء وتقدمهم ابن هرمة بقوله\n(لا أمتع العوذ بالفصال ولا ... أبتاع إلا قريبة الأجل)\nال عبد الرحمن وكان عمي معجبا بهذا البيت مستحسنا له وكان كثيرا ما يقول أما ترون كيف قال والله لو قال هذا حاتم لما زاد ولكان كثيرا ثم يقول ما يؤخره عن الفحول إلا قرب عهده انتهى أخبرني محمد بن مزيد والحسين بن يحيى ووكيع عن حماد عن أبيه قال قلت لمروان بن أبي حفصة من أشعر المحدثين من طبقتكم عندك لا أعنيك قال الذي يقول\n(لا أمتع العوذ بالفصال ولا ... أبتاع إلا قريبة الأجل)","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":33,"spl":"شيء من ذكر ابن هرمة أيضا"},
{"id":"b52-59","bab":"الجزء 5","sec":"شيء من ذكر ابن هرمة أيضا","page":"ج5 ص270","text":"خبرنا يحيى بن علي قال حدثنا أبو أيوب المديني عن أبي حذافة قال لما قال ابن هرمة\n(لا أمتع العوذ بالفصال ولا ... أبتاع إلا قريبة الأجل)\nال ابن الكوسج مولى آل حنين يجيبه\n(ما يشرب البارد القراح ولا ... يذبح من جفرة ولا حمل)\n(كأنه قردة يلاعبها ... قرد بأعلى الهضاب من ملل)\nال فقال ابن هرمة لئن لم أوت به مربوطا لأفعلن بآل حنين ولأفعلن فوهبوا لابن الكوسج مائة درهم وربطوه وأتوا به ابن هرمة فأطلقه فقال ابن الكوسج والله لئن عاد لمثلها لأعودن أخبرني الحسن بن علي الخفاف قال حدثني هارون بن محمد بن عبد الملك الزيات قال حدثني هارون بن مخارق عن أبيه قال كنا عند الرشيد في بعض أيامنا ومعنا ابن جامع فغناه ابن جامع ونحن يومئذ بالرقة\n(هاج شوقا فراقك الأحبابا ... فتناسيت أو نسيت الربابا)\n(حين صاح الغراب بالبين منهم ... فتصاممت إذ سمعت الغرابا)\n(لو علمنا أن الفراق وشيك ... ما انتهينا حتى نزور القبابا)\n(أو علمنا حين استقلت نواهم ... ما أقمنا حتى نزم الركابا)\nلغناء لابن جامع رمل بإطلاق الوتر في مجرى الوسطى عن إسحاق وله فيه أيضا ثقيل أول بالوسطى عن عمرو وذكرت دنانير عن فليح أن فيه لابن سريج وابن محرز لحنين قال فاستحسنه الرشيد وأعجب به واستعاده مرارا وشرب عليه أرطالا حتى سكر وما سمع غيره ولا أقبل على أحد وأمر لابن جامع بخمسة آلاف دينار فلما انصرفنا قال لي\nإبراهيم لا ترم منزلك حتى أصير إليك فصرت إلى منزلي فلم أغير ثيابي حتى أعلمني الغلام بموافاته فتلقيته في دهليزي فدخل وجلس وأجلسني بين يديه ثم قال لي يا مخارق أنت فسيلة مني وحسني لك وقبيحي عليك ومتى تركنا ابن جامع على ما ترى غلبنا على الرشيد وقد صنعت صوتا على طريقة صوته الذي غناه أحسن صنعة منه وأجود وأشجى وإنما يغلبني عند هذا الرجل بصوته ولا مطعن على صوتك وإذا أطربته وغلبته عليه بما تأخذه مني قام ذلك لي مقام الظفر وسيصبح أمير المؤمنين غدا فيدخل الحمام ونحضر ثم يخرج فيدعو بالطعام ويدعو بنا ويأمر ابن جامع فيرد الصوت الذي غناه ويشرب عليه رطلا ويأمر له بجائزة فإذا فعل فلا تنتظره أكثر من أن يرد ردته حتى تغني ما أعلمك إياه الساعة فإنه يقبل عليك ويصلك ولست أبالي ألا يصلني بعد أن يكون إقباله عليك فقلت السمع والطاعة فألقى علي لحنه\n(يا دار سعدى بالجزع من ملل ... )\nردده حتى أخذته وانصرف ثم بكر علي فاستعاد الصوت فرددته حتى رضيه ثم ركبنا وأنا أدرسه حتى صرنا إلى دار الرشيد فلما دخلنا فعل الرشيد جميع ما وصفه إبراهيم شيئا فشيئا وكان إبراهيم أعلم الناس به ثم أمر ابن جامع فرد الصوت ودعا برطل فشربه ولما استوفاه واستوفى ابن جامع صوته لم أدعه يتنفس حتى اندفعت فغنيت صوت إبراهيم فلم يزل يصغي إليه وهو باهت حتى استوفيته فشرب وقال أحسنت والله لمن هذا\nالصوت فقلت لإبراهيم فلم يزل يستدنيني حتى صرت قدام سريره وجعل يستعيد الصوت فأعيده ويشرب عليه رطلا فأمر لإبراهيم بجائزة سنية وأمر لي بمثلها وجعل ابن جامع يشغب ويقول يجيء بالغناء فيدسه في أستاه الصبيان إن كان محسنا فليغنه هو والرشيد يقول له دع ذا عنك فقد والله استقاد منك وزاد عليك","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":34,"spl":"شيء من ذكر ابن هرمة أيضا — صوت من المائة المختارة","partialRef":{"sid":"b52-57","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b52-60","bab":"الجزء 5","sec":"صوت من المائة المختارة","page":"ج5 ص277","text":"(تولى شبابك إلا قليلا ... وحل المشيب فصبرا جميلا)\n(كفى حزنا بفراق الصبا ... وإن أصبح الشيب منه بديلا)\nلشعر والغناء لإسحاق ولحنه المختار ثاني ثقيل بالوسطى في مجراها عن إسحاق بن عمرو","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":34,"spl":"شيء من ذكر ابن هرمة أيضا — صوت من المائة المختارة"},
{"id":"b52-61","bab":"الجزء 5","sec":"أخبار إسحاق بن إبراهيم","page":"ج5 ص278","text":"قد مضى نسبه مشروحا في نسب أبيه ويكنى أبا محمد وكان الرشيد يولع به فيكنيه أبا صفوان وهذه كنية أوقعها عليه إسحاق بن إبراهيم بن مصعب مزحا وموضعه من العلم ومكانه من الأدب ومحله من الرواية وتقدمه في الشعر ومنزلته في سائر المحاسن أشهر من أن يدل عليه فيها بوصف وأما الغناء فكان أصغر علومه وأدنى ما يوسم به وإن كان الغالب عليه وعلى ما كان يحسنه فإنه كان له في سائر أدواته نظراء وأكفاء ولم يكن له في هذا نظير فإنه لحق بمن مضى فيه وسبق من بقي ولحب للناس جميعا طريقه فأوضحها وسهل عليهم سبيله وأنارها فهو إمام أهل صناعته جميعا ورأسهم ومعلمهم يعرف ذلك منه الخاص والعام ويشهد به الموافق والمفارق على أنه كان أكره الناس للغناء وأشدهم بغضا لأن يدعى إليه أو يسمى به وكان يقول لوددت أن أضرب كلما أراد مريد مني أن أغني وكلما قال قائل إسحاق الموصلي المغني عشر مقارع لا أطيق أكثر من ذلك وأعفى من الغناء ولا ينسبني من يذكرني إليه وكان المأمون يقول لولا ما سبق على ألسنة الناس وشهر به عندهم من الغناء لوليته القضاء بحضرتي فإنه أولى به وأعف وأصدق وأكثر دينا وأمانة من هؤلاء القضاة","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":35,"spl":"أخبار إسحاق بن إبراهيم"},
{"id":"b52-62","bab":"الجزء 5","sec":"مشايخه الذين تلقى عنهم","page":"ج5 ص279","text":"وقد روى الحديث ولقي أهله مثل مالك بن أنس وسفيان بن عيينة وهشيم بن بشير وإبراهيم بن سعد وأبي معاوية الضرير وروح بن عبادة وغيرهم من شيوخ العراق والحجاز وكان مع كراهته\nالغناء أضن خلق الله وأشدهم بخلا به على كل أحد حتى على جواريه وغلمانه ومن يأخذ عنه منتسبا إليه متعصبا له فضلا عن غيرهم وهو الذي صحح أجناس الغناء وطرائقه وميزه تمييزا لم يقدر عليه أحد قبله ولا تعلق به أحد بعده ولم يكن قديما مميزا على هذا الجنس إنما كان يقال الثقيل وثقيل الثقيل والخفيف وخفيف الخفيف وهذا عمرو بن بانة وهو من تلاميذه يقول في كتابه الرمل الأول والرمل الثاني ثم لا يزيد في ذكر الأصابع على الوسطى والبنصر ولا يعرف المجاري التي ذكرها إسحاق في كتابه مثل ما ميز الأجناس فجعل الثقيل الأول أصنافا فبدأ فيه بإطلاق الوتر في مجرى البنصر ثم تلاه بما كان منه بالبنصر في مجراها ثم بما كان بالسبابة في مجرى البنصر ثم فعل هذا بما كان منه بالوسطى على هذه المرتبة ثم جعل الثقيل الأول صنفين الصنف الأول منهما هذا الذي ذكرناه والصنف الثاني القدر الأوسط من الثقيل الأول وأجراه المجرى الذي تقدم من تمييز الأصابع والمجاري وألحق جميع الطرائق والأجناس بذلك وأجراها على هذا الترتيب ثم لم يتعلق بفهم ذلك أحد بعده فضلا عن أن يصنفه في كتابه فقد ألف جماعة من المغنين كتبا منهم يحيى المكي وكان شيخ الجماعة وأستاذهم وكلهم كان يفتقر إليه ويأخذ عنه غناء الحجاز وله صنعة كثيرة حسنة متقدمة وقد كان إبراهيم الموصلي وابن جامع يضطران إلى الأخذ عنه ألف كتابا جمع فيه الغناء القديم وألحق فيه ابنه الغناء المحدث إلى آخر أيامه فأتيا فيه في أمر الأصابع بتخليط عظيم حتى جعلا أكثر ما جنساه من ذلك مختلطا فاسدا وجعلا بعضه فيما زعما تشترك الأصابع كلها فيه وهذا محال ولو اشتركت الأصابع لما احتيج إلى تمييز الأغاني وتصييرها مقسومة على صنفين الوسطى والبنصر\nوالكلام في هذا طويل ليس موضعه هاهنا وقد ذكرته في رسالة عملتها لبعض إخواني ممن سألني شرح هذا فأثبته واستقصيته استقصاء يستغني به عن غيره وهذا كله فعله إسحاق واستخرجه بتمييزه حتى أتى على كل ما رسمته الأوائل مثل إقليدس ومن قبله ومن بعده من أهل العلم بالموسيقى ووافقهم بطبعه وذهنه فيما قد أفنوا فيه الدهور من غير أن يقرأ لهم كتابا أو يعرفه فأخبرني جعفر بن قدامة قال حدثني علي بن يحيى المنجم قال كنت عند إسحاق بن إبراهيم بن مصعب فسأل إسحاق الموصلي أو سأله محمد بن الحسن بن مصعب بحضرتي فقال له يا أبا محمد أرأيت لو أن الناس جعلوا للعود وترا خامسا للنغمة الحادة التي هي العاشرة على مذهبك أين كنت تخرج منه فبقي إسحاق واجما ساعة طويلة مفكرا واحمرت أذناه وكانتا عظيمتين وكان إذا ورد عليه مثل هذا احمرتا وكثر ولوعه بهما فقال لمحمد بن الحسن الجواب في هذا لا يكون كلاما إنما يكون بالضرب فإن كنت تضرب أريتك أين تخرج فخجل وسكت عنه مغضبا لأنه كان أميرا وقابله من الجواب بما لا يحسن فحلم عنه قال علي بن يحيى فصار إلي به وقال لي يا أبا الحسن إن هذا الرجل سألني عما سمعت ولم يبلغ علمه أن يستنبط مثله بقريحته وإنما هو شيء قرأه في كتب الأوائل وقد بلغني أن التراجمة عندهم يترجمون لهم كتب الموسيقى فإذا خرج إليك منها شيء فأعطنيه فوعدته بذلك ومات قبل أن يخرج إليه شيء منها وإنما ذكرت هذا بتمام أخباره كلها ومحاسنه وفضائله لأنه من أعجب شيء يؤثر عنه أنه استخرج بطبعه علما رسمته الأوائل لا يوصل إلى معرفته إلا بعد علم كتاب إقليدس الأول في الهندسة ثم ما بعده من الكتب الموضوعة في الموسيقى ثم تعلم ذلك وتوصل إليه واستنبطه بقريحته فوافق ما رسمه أولئك ولم يشذ عنه شيء يحتاج إليه\nمنه وهو لم يقرأه ولا له مدخل إليه ولا عرفه ثم تبين بعد هذا بما أذكره من أخباره ومعجزاته في صناعته فضله على أهلها كلهم وتميزه عنهم وكونه سماء هم أرضها وبحرا هم جداوله وأم إسحاق امرأة من أهل الري يقال لها شاهك وذكر قوم أنها دوشار التي كانت تغني بالدف فهويها إبراهيم وتزوجها وهذا خطأ تلك لم تلد من إبراهيم إلا بنتا وإسحاق وسائر ولد إبراهيم من شاهك هذه","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":36,"spl":"مشايخه الذين تلقى عنهم"},
{"id":"b52-63","bab":"الجزء 5","sec":"برنامج دراسته اليومي","page":"ج5 ص282","text":"أخبرني يحيى بن علي المنجم قال أخبرني أبي عن إسحاق قال بقيت دهرا من دهري أغلس في كل يوم إلى هشيم فأسمع منه ثم أصير إلى الكسائي أو الفراء أو ابن غزالة فأقرأ عليه جزءا من القرآن ثم آتي منصور زلزل فيضاربني طرقين أو ثلاثة ثم آتي عاتكة بنت شهدة فآخذ منها صوتا أو صوتين ثم آتي الأصمعي وأبا عبيدة فأناشدهما وأحدثهما فأستفيد منهما ثم أصير إلى أبي فأعلمه ما صنعت ومن لقيت وما أخذت وأتغدى معه فإذا كان العشاء رحت إلى أمير المؤمنين الرشيد\nأخبرنا محمد بن مزيد بن أبي الأزهر قال حدثنا حماد بن إسحاق عن أبيه قال أخذ مني منصور زلزل إلى أن تعلمت مثل ضربه بالعود أكثر من مائة ألف درهم أخبرنا محمد بن العباس اليزيدي قال حدثنا أحمد بن أبي خيثمة قال كنت عند ابن عائشة فجاءه أبو محمد إسحاق بن إبراهيم الموصلي فرحب به وقال هاهنا يا أبا محمد إلى جنبي فلئن بعدت بيننا الأنساب لقد قربت بيننا الآداب أخبرني الحسن بن علي الخفاف قال حدثنا يزيد بن محمد المهلبي قال حدثنا ابن شبيب من جلساء المأمون عنه أنه قال يوما وإسحاق غائب عن مجلسه لولا ما سبق على ألسنة الناس واشتهر به عندهم من الغناء لوليته القضاء فما أعرف مثله ثقة وصدقا وعفة وفقها هذا مع تحصيل المأمون وعقله ومعرفته أخبرنا يحيى بن علي قال حدثنا الفضل بن العباس الوراق قال حدثنا المخرمي عن أبيه قال سمعت إسحاق الموصلي يقول صرت إلى سفيان بن عيينة لأسمع منه فتعذر ذلك علي وصعب مرامه فرأيته عند الفضل بن الربيع فسألته أن يعرفه موضعي من عنايته ومكاني من الأدب والطلب وأن يتقدم إليه بحديثي ففعل وأوصاه بي فقال إن أبا محمد من أهل العلم وحملته قال فقلت تفرض لي عليه ما يحدثني به فسأله في ذلك ففرض لي خمسة عشر حديثا في كل مجلس\nفصرت إليه فحدثني بما فرض لي فقلت له أعزك الله صحيح كما حدثتني به قال نعم وعقد بيده شيئا قلت أفأرويه عنك قال نعم وعقد بيده شيئا آخر ثم قال هذه خمسة وأربعون حديثا وضحك إلي وقال قد سرني ما رأيت من تقصيك في الحديث وتشددك فيه على نفسك فصر إلي متى شئت حتى أحدثك بما شئت أخبرني محمد بن يحيى الصولي قال حدثني الحسين بن يحيى أبو الجمان وعون بن محمد الكندي قالا سمعنا إسحاق الموصلي يقول جئت يوما إلى أبي معاوية الضرير ومعي مائة حديث فوجدت حاجبه يومئذ رجلا ضريرا فقال لي إن أبا معاوية قد ولاني اليوم حجبته لينفعني فقلت معي مائة حديث وقد جعلت لك مائة درهم إذا قرأتها فدخل واستأذن لي فدخلت فلما عرفني أبو معاوية دعاه فقال له أخطأت وإنما جعلت لك مثل هذا من ضعفاء أصحاب الحديث فأما أبو محمد وأمثاله فلا ثم أقبل علي يرغبني في الإحسان إليه ويذكر ضعفه وعنايته به فقلت له احتكم في أمره فقال مائة دينار فأمرت بإحضارها الغلام وقرأت عليه ما أردت وانصرفت أخبرني محمد بن يحيى الصولي قال حدثني علي بن محمد الأسدي قال حدثني أحمد بن يحيى الشيباني ثعلب قال وقف أبو عبد الله بن الأعرابي على المدائني فقال له إلى أين يا أبا عبد الله فقال أمضي إلى رجل هو كما قال الشاعر\n(نحمل أشباحنا إلى ملك ... نأخذ من ماله ومن أدبه)\nقال له ومن ذلك يا أبا عبد الله قال أبو محمد إسحاق بن إبراهيم الموصلي\nقال أبو بكر والبيت لأبي تمام الطائي وقد أخبرني بهذا الخبر عن ثعلب محمد بن القاسم الأنباري فقال فيه كان إسحاق يجري على ابن الأعرابي في كل سنة ثلاثمائة دينار وأهدى له ابن الأعرابي شيئا من كتاب النوادر كتبه له بخطه فمر ابن الأعرابي يوما على باب دار الموصلي ومعه صديق له فقال له صديقه هذه دار صديقك أبي محمد إسحاق فقال هذه دار الذي نأخذ من ماله ومن أدبه أخبرني الحسن بن علي قال حدثنا يزيد بن محمد المهلبي قال حدثنا حماد بن إسحاق عن أبيه قال رأيت في منامي كأن جريرا جالس ينشد شعره وأنا أسمع منه فلما فرغ أخذ بيده كبة شعر فألقاها في فمي فابتلعتها فأول ذلك بعض من ذكرته له أنه ورثني الشعر قال يزيد بن محمد وكذلك كان لقد مات إسحاق وهو أشعر أهل زمانه","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":37,"spl":"برنامج دراسته اليومي"},
{"id":"b52-64","bab":"الجزء 5","sec":"إسحاق يتعلم الضرب بالعود من زلزل","page":"ج5 ص285","text":"أخبرنا يحيى بن علي بن يحيى ومحمد بن مزيد قالا حدثنا حماد بن إسحاق قال قال لي أبي أعطيت منصورا زلزلا من مالي خاصة حتى تعلمت ضربه بالعود نحوا\nمن مائة ألف درهم سوى ما أخذته له من الخلفاء ومن أبي قال وكانت في زلزل قبل أن يعرف الصوت ويفهمه بلادة أول ما يسمعه حتى لو ضرب هو وغلامه على صوت لم يعرفاه قبل لكان غلامه أقوى منه فإذا تفهمه جاء فيه من الضرب بما لا يتعلق به أحد البتة أخبرني محمد بن العباس اليزيدي قال حدثني عمي الفضل عن إسحاق وأخبرني به الأخفش عن الفضل عن إسحاق وأخبرني به يحيى ابن علي بن يحيى عن أبيه عن إسحاق وأخبرني الحسن بن علي قال حدثنا يزيد بن محمد المهلبي عن إسحاق قال قال لي أبو زياد الكلابي أولم جار لي يكنى أبا سفيان وليمة ودعاني لها فانتظرت رسوله حتى تصرم يومي فلم يأت فقلت لامرأتي\n(إن أبا سفيان ليس بمولم ... فقومي فهاتي فلقة من حوارك)\nال إسحاق فقلت له أليس غير هذا فقال لا إنما أرسلته يتيما فقلت أفلا أجيزه قال شأنك فقلت له\n(فبيتك خير من بيوت كثيرة ... وقدرك خير من وليمة جارك)\nال فضحك ثم قال أحسنت بأبي أنت وأمي جئت والله به قبلا ما انتظرت به القرب وما ألوم الخليفة أن يجعلك في سماره ويتملح بك وإنك لمن طراز ما رأيت بالعراق مثله ولو كان الشباب يشترى لا ابتعته لك بإحدى عيني ويمنى يدي وعلى أن فيك بحمد الله ومنه بقية تسر الودود وترغم الحسود هذا لفظ يزيد المهلبي والأخفش وأخبرني بهذا الخبر محمد بن عبد الله بن عمار فقال حدثني عمر بن شبة قال حدثني إسحاق قال\nقال لي إما شداد بن عقبة وإما أبو مجيب قالت امرأة القتال الكلابي له هل لك في فلقة من حوار نطبخها لك فقال لا والله نحن على وليمة أبي سفيان ودعوته وكان أبو سفيان رجلا من الحي زفت إليه امرأته تلك الليلة فجعل ينظر دخانا فلا يراه فقال\n(إن أبا سفيان ليس بمولم ... فقومي فهاتي فلقة من حوارك)\nم ذكر باقي الخبر على ما تقدم من الذي قبله أخبرنا يحيى بن علي قال حدثني أبي قال حدثني إسحاق قال أنشدت أعرابيا فهما شعرا لي فقال أقفرت والله يا أبا محمد قلت وما أقفرت قال رعيت قفرة لم ترع قبلك يريد أبدعت","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":38,"spl":"إسحاق يتعلم الضرب بالعود من زلزل"},
{"id":"b52-65","bab":"الجزء 5","sec":"نباهة إسحاق في الغناء","page":"ج5 ص287","text":"أخبرني علي بن سليمان الأخفش وعمي قالا حدثنا محمد بن يزيد المبرد قال حدثني بعض أصحاب السلطان بمدينة السلام قال سمعت إسحاق الموصلي يقول\nدخلت على المأمون يوما وعقيد يغنيه ارتجالا وغيره يضرب عليه فقال يا إسحاق كيف تسمع مغنينا هذا فقلت هل سأل أمير المؤمنين عن هذا غيري قال نعم سألت عمي إبراهيم فوصفه وقرظه واستحسنه فقلت له يا أمير المؤمنين أدام الله سرورك وأطاب عيشك إن الناس قد أكثروا في أمري حتى نسبتني فرقة إلى التزيد في علمي فقال لي فلا يمنعك ذلك من قول الحق إذا لزمك فقلت لعقيد أردد هذا الصوت الذي غنيته آنفا وتحفظ فيه وضرب ضاربه عليه فقلت لإبراهيم بن المهدي كيف رأيته فقال ما رأيت شيئا يكره ولا سمعته فأقبلت على عقيد فقلت له حين استوفاه في أي طريقة هذا الصوت الذي غنيته قال في الرمل فقلت للضارب في أي طريقة ضربت أنت قال في الهزج الثقيل فقلت يا أمير المؤمنين ما عسيت أن أقول في صوت يغني مغنيه رملا ويضرب ضاربه هزجا وليس هو صحيحا في إيقاعه الذي ضرب عليه قال وتفهمه إبراهيم بن المهدي بعدي فقال صدق يا أمير المؤمنين الأمر فيه الآن بين فغاظني فقلت له بأي شيء بان الآن ما لم يكن بينا قبل أتوهم أنك استنبطت معرفة هذا وإنما قلته لما علمته من جهتي كما يقوله الغلمان العجم وسائر من حضر اتباعا لي واقتداء بقولي فقال له المأمون صدق فأمسك وجعل يتعجب من ذهاب ذلك على كل من حضر وكناني في ذلك اليوم مرتين أخبرني أحمد بن جعفر جحظة قال حدثني أبو عبد الله أحمد بن حمدون قال حدثني أبي أن الأصمعي أنشد قول إسحاق يذكر ولاءه لخزيمة بن خازم\n(إذا كانت الأحرار أصلي ومنصبي ... ودافع ضيمي خازم وابن خازم)\n(عطست بأنف شامخ وتناولت ... يداي الثريا قاعدا غير قائم)\nال فجعل الأصمعي يعجب منهما ويستحسنهما وكان بعد ذلك يذكرهما ويفضلهما قال ابن حمدون وكان السبب في تولي إسحاق خازم بن خزيمة بن حازم أن مناظرة جرت بينه وبين ابن جامع بحضرة الرشيد فتغالظا فقال له ابن جامع يا من إذا قلت له يا بن زانية لم أخف أن يكذبني أحد فمضى إلى خازم بن خزيمة فتولاه وانتمى إليه فقبل ذلك منه وقال هذين البيتين","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":39,"spl":"نباهة إسحاق في الغناء — المعتصم يمتحن إسحاق في الغناء"},
{"id":"b52-66","bab":"الجزء 5","sec":"المعتصم يمتحن إسحاق في الغناء","page":"ج5 ص289","text":"أخبرني يحيى بن علي قال حدثني أبي قال قال إسحاق كانت عندي صناجة كنت بها معجبا واشتهاها أبو إسحاق المعتصم في خلافة المأمون فبينا أنا ذات يوم في منزلي إذا ببابي يدق دقا شديدا فقلت انظروا من هذا قالوا رسول أمير المؤمنين فقلت ذهبت صناجتي تجده ذكرها له ذاكر فبعث إلي فيها فلما مضى بي الرسول انتهيت إلى الباب\nوأنا مثخن فدخلت فسلمت فرد السلام ونظر إلى تغير وجهي فقال اسكن فسكنت وسألني عن صوت وقال أتدري لمن هو فقلت أسمعه ثم أخبر أمير المؤمنين إن شاء الله بذلك فأمر جارية من وراء الستارة فغنته وضربت فإذا هي قد شبهته بالقديم فقلت زدني معها عودا آخر فإنه أثبت لي فزادني عودا آخر فقلت يا أمير المؤمنين هذا الصوت محدث لامرأة ضاربة فقال من أين قلت ذلك فقلت لما سمعته وسمعت لينه عرفت أنه من صنعة النساء ولما رأيت جودة مقاطعه علمت أن صاحبته ضاربة فقال من أين قلت ذلك فقلت لأنها قد حفظت مقاطعه وأجزاءه ثم طلبت عودا آخر ليكون أثبت لي فلم أشكك فقال صدقت الغناء لعريب نسخت من كتاب ابن أبي سعيد حدثني إسحاق بن إبراهيم الطاهري قال حدثتني مخارق مولاتنا قالت كان لمولاي الذي علمني الغناء فراش رومي وكان يغني بالرومية صوتا مليح اللحن فقال لي مولاي يا مخارق خذي هذا اللحن الرومي فانقليه إلى شعر من أصواتك العربية حتى أمتحن به إسحاق الموصلي فأعلم أين يقع من معرفته ففعلت ذلك وصار إليه إسحاق فاحتبسه مولاي فأقام وبعث إلي أن أدخلي اللحن الرومي في وسط غنائك فغنيته إياه في درج\nأصوات مرت قبله فأصغى إليه إسحاق وجعل يتفهمه ويقسمه ويتفقد أوزانه ومقاطعه ويوقع عليه بيده ثم أقبل على مولاي فقال هذا صوت رومي اللحن فمن أين وقع إليك فكان مولاي بعد ذلك يقول ما رأيت شيئا أحسن من استخراجه لحنا روميا لا يعرفه ولا العلة فيه وقد نقل إلى غناء عربي وامتزجت نغمه حتى عرفه ولم يخف عليه","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":39,"spl":"نباهة إسحاق في الغناء — المعتصم يمتحن إسحاق في الغناء"},
{"id":"b52-67","bab":"الجزء 5","sec":"إسحاق وملاحظ في مجلس الواثق","page":"ج5 ص291","text":"أخبرني عمي قال حدثني محمد بن موسى قال حدثني عبد الله بن عمرو عن محمد بن عبد الله بن مالك قال حدثني علويه الأعسر ووجدت هذا الخبر في بعض الكتب عن علي بن محمد بن نصر الشامي عن جده حمدون ابن إسماعيل قال تناظر المغنون يوما عند الواثق فذكروا الضراب وحذقهم فقدم إسحاق زلزلا على ملاحظ ولملاحظ في ذلك الرياسة على جميعهم فقال له الواثق هذا حيف وتعد منك فقال إسحاق يا أمير المؤمنين اجمع بينهما وامتحنهما فإن الأمر سينكشف لك فيهما فأمر بهما فأحضرا فقال له إسحاق إن للضراب أصواتا معروفة أفأمتحنهما بشيء منها قال أجل افعل فسمى ثلاثة أصوات كان أولها\n(علق قلبي ظبية السيب ... )\nضربا عليه فتقدم زلزل وقصر عنه ملاحظ فعجب الواثق من كشفه عما ادعاه في مجلس واحد فقال له ملاحظ فما باله يا أمير المؤمنين يحيلك على الناس ولم لا يضرب هو فقال يا أمير المؤمنين إنه لم\nيكن أحد في زماني أضرب مني إلا أنكم أعفيتموني فتفلت مني وعلى أن معي بقية لا يتعلق بها أحد من هذه الطبقة ثم قال يا ملاحظ شوش عودك وهاته ففعل ذلك ملاحظ فقال يا أمير المؤمنين هذا يخلط الأوتار تخليط متعنت فهو لا يألو ما أفسدها ثم أخذ العود فجسه ساعة حتى عرف مواقعه ثم قال يا ملاحظ غن أي صوت شئت فغنى ملاحظ صوتا وضرب عليه إسحاق بذلك العود الفاسد التسوية فلم يخرجه عن لحنه في موضع واحد حتى استوفاه عن نقرة واحدة ويده تصعد وتنحدر على الدساتين فقال له الواثق لا والله ما رأيت مثلك ولا سمعت به اطرح هذا على الجواري فقال هيهات يا أمير المؤمنين هذا لا تعرفه الجواري ولا يصلح لهن إنما بلغني أن الفهليذ ضرب يوما بين يدي كسرى فأحسن فحسده رجل من حذاق أهل صنعته فترقبه حتى قام لبعض شأنه ثم خالفه إلى عوده فشوش بعض أوتاره فرجع فضرب وهو لا يدري والملوك لا تصلح في مجالسها العيدان فلم يزل يضرب بذلك العود الفاسد إلى أن فرغ ثم قام على رجله فأخبر الملك بالقصة فامتحن العود فعرف ما فيه ثم قال زه وزه وزهان زه ووصله بالصلة التي كان يصل بها من خاطبه هذه المخاطبة فلما تواطأت الرواية بهذا أخذت نفسي ورضتها عليه وقلت لا ينبغي أن يكون الفهليذ أقوى على هذا مني فما زلت أستنبطه بضع عشرة سنة حتى لم يبق في الأرض موضع على طبقة من الطبقات إلا وأنا أعرف نغمته كيف هي والمواضع التي يخرج النغم كلها منه فيها من أعاليها إلى أسافلها وكل شيء منها يجانس شيئا غيره كما أعرف ذلك في مواضع الدساتين وهذا شيء لا تفي به الجوراي قال له الواثق صدقت ولئن مت لتموتن هذه الصناعة معك وأمر له بثلاثين ألف درهم","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":40,"spl":"إسحاق وملاحظ في مجلس الواثق — نسبه هذا الصوت","partial":1},
{"id":"b52-68","bab":"الجزء 5","sec":"نسبه هذا الصوت","page":"ج5 ص293","text":"صوت\n(علق قلبي ظبية السيب ... جهلا فقد أغري بتعذيبي)\n(نمت عليها حين مرت بنا ... مجاسد ينفحن بالطيب)\n(تصدها عنا عجوز لها ... منكرة ذات أعاجيب)\n(فكلما همت بإتيانها ... قالت توقي عدوة الذيب)\nلشعر والغناء لإبراهيم هزج ثقيل بالسبابة في مجرى البنصر حدثني علي بن هارون قال حدثني محمد بن موسى اليزيدي قال حدثتني دمن جارية إسحاق الموصلي وكانت من كبار جواريه وأحظى منه عنده ولقيتها فقلت لها أي شيء أخذت عن مولاك من الغناء فقالت لا والله ما أخذت أنا عنه ولا واحدة من جواريه صوتا قط كان أبخل بذلك وما أخذت منه قط إلا صوتا واحدا وذلك أنه انصرف من دار الخليفة وهو مثخن سكرا فدخل إلى بيت كان ينام فيه فرأى عودا معلقا فأخذه بيده وقال لخادمه يا غلام صح لي بدمن فجاءني الغلام فخرجت فلما بلغت الباب إذا هو مستلق على فراشه والعود في يده وهو يصنع هذا الصوت ويردده وقد اسحنفر في نغمه وتنوق فيها حتى استقام له وهو صوت\n(ألا ليلك لا يدهب ... ونيط الطرف بالكوكب)\n(وهذا الصبح لا يأتي ... ولا يدنو ولا يقرب)\nفلما سمعته علمت أني إن دخلت إليه أمسك فوقفت أستمعه حتى فرغ منه وأخذته عنه فلما فرغ منه وضع العود من يده وذكر أنه قد طلبني فقال يا غلام أين دمن فقلت هأنذي فقال مذ كم أنت واقفة فقلت مند ابتدأت بالصوت وقد أخذته فنظر إلي نظر مغضب أسف ثم قال غنيه فغنيته حتى استوفيته فقال لي وقد فتر وخجل قد بقيت عليك فيه بقية أنا أصلحها لك فقلت لست أحتاج إلى إصلاحك إياه وقد والله أخذته على رغمك فضحك لحن هذا الصوت من الهزج بالبنصر والشعر والغناء لإسحاق","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":40,"spl":"إسحاق وملاحظ في مجلس الواثق — نسبه هذا الصوت"},
{"id":"b52-69","bab":"الجزء 5","sec":"كان قادرا على إظهار الأخطاء في الغناء والأوتار","page":"ج5 ص294","text":"أخبرنا يحيى بن علي قال قال لي إسحاق\nكنت عند المعتصم وعنده إبراهيم بن المهدي فغنى إبراهيم صوتا لابن جامع أخل ببعضه ثم قال يا أمير المؤمنين ترك ابن جامع الناس يحجلون خلفه ولا يلحقونه\nوفي هذا الصوت خاصة فقلت والله يا أمير المؤمنين ما صدق وما هذا الصوت بتام الأجزاء فقال كذب والله يا أمير المؤمنين فقلت يا سيدي أنا أوقفه على نقصانه فمره فليعد يا أمير المؤمنين فأعاد البيت الأول فأقامه وطمع في الإصابة فقلت آفته في البيت الثاني فليردده فرده فنقص من أجزائه وقسمته فعرفته فأقر به فقلت يا أمير المؤمنين هذه صناعتي وصناعة آبائي وإبراهيم يكلمني فيها\nوأنا أسأله عن ثلاثين مسألة من باب واحد في طريق الغناء لا يعرف منها مسألة واحدة فقال أو يعفيني أمير المؤمنين من كلامه فأعفاه وقد أخبرني بهذا الخبر الحسن بن علي قال حدثنا يزيد بن محمد المهلبي عن إسحاق فذكر نحوا مما ذكره يحيى وذكر أن القصة كانت بين يدي المعتصم وزاد فيها فقال أنا أسأله عن ثلاثين مسألة وأوقفه على خطئه فيها فإن لم يقر بذلك أقر به مخارق وعلويه فقال أو يعفيني أمير المؤمنين من كلامه فإنه يعدل عندي البختج قلت يا أمير المؤمنين وما يفعل البختج قال يسلح قلت قد والله فعل ذلك كلامي به ومنه هرب فضحك وغطى فاه وقام فظن إسحاق بن إبراهيم المصعبي أني قد أغضبته فضرب بيده إلى السيف فقلت له لا تحسب أني أغضبته فما كنت لأكلم عمه بين يديه بهزء من غير إذنه فأمسك وكان لا يقدم أحد أن يكلم الخليفة بحضرته بما فيه الوهن إلا بادر إلى سيفه تعظيما للأمير وإجلالا له أخبرني يحيى بن علي قال حدثنا أحمد بن القاسم الهاشمي عن إسحاق وأخبرني الحسين بن يحيى قال حدثنا حماد بن إسحاق عن أبيه قال دعاني المأمون وعنده إبراهيم بن المهدي وفي مجلسه عشرون جارية قد أجلس عشرا عن يمينه وعشرا عن يساره ومعهن العيدان يضربن بها فلما دخلت سمعت من الناحية اليسرى خطأ فأنكرته فقال المأمون يا إسحاق أتسمع خطأ فقلت نعم والله يا أمير المؤمنين فقال لإبراهيم هل تسمع خطأ فقال لا فأعاد علي السؤال فقلت بلى والله يا أمير المؤمنين وإنه لفي الجانب الأيسر فأعاد إبراهيم سمعه إلى الناحية اليسرى ثم قال\nلا والله يا أمير المؤمنين ما في هذه الناحية خطأ فقلت يا أمير المؤمنين مر الجواري اللواتي على اليمين يمسكن فأمرهن فأمسكن فقلت لإبراهيم هل تسمع خطأ فتسمع ثم قال ما ها هنا خطأ فقلت يا أمير المؤمنين يمسكن وتضرب الثامنة فأمسكن وضربت الثامنة فعرف إبراهيم الخطأ فقال نعم يا أمير المؤمنين ها هنا خطأ فقال عند ذلك لإبراهيم يا إبراهيم لا تمار إسحاق بعدها فإن رجلا فهم الخطأ بين ثمانين وترا وعشرين حلقا لجدير ألا تماريه فقال صدقت يا أمير المؤمنين وقال الحسين بن يحيى في خبره وكان في الأوتار كلها مثنى فاسد التسوية وقال فيه فطرب أمير المؤمنين المأمون وقال لله درك يا أبا محمد فكناني يومئذ","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":41,"spl":"كان قادرا على إظهار الأخطاء في الغناء والأوتار"},
{"id":"b52-70","bab":"الجزء 5","sec":"الواثق يثني على إسحاق","page":"ج5 ص296","text":"أخبرني أحمد بن جعفر جحظة قال حدثني أحمد بن حمدون قال سمعت الواثق يقول ما غناني إسحاق قط إلا ظننت أنه قد زيد لي في ملكي ولا سمعته يغني غناء ابن سريج إلا ظننت أن ابن سريج قد نشر وإنه ليحضرني غيره إذا لم يكن حاضرا فيتقدمه عندي وفي نفسي بطيب الصوت حتى إذا اجتمعا عندي رأيت إسحاق يعلو ورأيت من ظننته يتقدمه ينقص وإن إسحاق لنعمة من نعم الملك التي لم يحظ بمثلها ولو أن العمر والشباب والنشاط مما يشترى لاشتريتهن له بشطر ملكي أخبرني جعفر بن قدامة قال حدثني علي بن يحيى المنجم قال سأل إسحاق الموصلي المأمون أن يكون دخوله إليه مع أهل العلم والأدب والرواة لا مع المغنين فإذا أراده للغناء غناه فأجابه إلى ذلك ثم سأله بعد حين أن يأذن له في الدخول مع الفقهاء فأذن له قال فحدثني\nمحمد بن الحارث بن بسخنر أنه كان هو ومخارق وعلويه جلوسا في حجرة لهم ينتظرون جلوس المأمون وخروج الناس من عنده إذ دخل يحيى بن أكثم وعليه سواده وطويلته ويده في يد إسحاق يماشيه حتى جلس معه بين يدي المأمون فكاد علويه أن يجن وقال يا قوم أسمعتم بأعجب من هذا يدخل قاضي القضاة ويده في يد مغن حتى يجلسا بين يدي الخليفة ثم مضت على ذلك مدة فسأل إسحاق المأمون أن يأذن له في لبس السواد يوم الجمعة والصلاة معه في المقصورة قال فضحك المأمون وقال ولا كل ذا يا إسحاق وقد اشتريت منك هذه المسألة بمائة ألف درهم وأمر له بها حدثني أحمد بن جعفر جحظة قال حدثني أبو عبد الله بن حمدون قال كان المغنون جميعا يحضرون مجلس الواثق وعيدانهم معهم إلا إسحاق فإنه كان يحضر بلا عود للشرب والمجالسة فإن أمره الخليفة أن يغني أحضر له عودا فإذا غنى وفرغ سل من بين يديه إلى أن يطلبه وكان الواثق كثيرا ما يكنيه رفعا له من أن يدعوه باسمه وكان إذا غنى وفرغ الواثق من شرب قدحه قطع الغناء ولم يعد منه حرفا إلا أن يكون في بعض بيت فيتمه ثم يقطع ويضع العود من يده أخبرنا يحيى بن علي بن يحيى عن أبيه في خبر ذكر إسحاق فيه\nفقال وعارض معبدا وابن سريج فانتصف منهما وكان إبراهيم بن المهدي يناظره ويجادله في الغناء وينازعه في صناعته ولم يبلغه وما رأيت بعد إسحاق مثله أخبرني عمي قال حدثني عبد الله بن أبي سعد قال حدثني محمد بن عبد الله بن مالك قال قال لي محمد بن راشد الخناق سمعت علويه يقول لإسحاق بن إبراهيم الموصلي إن إبراهيم بن المهدي يعيبك بتركك تحريك الغناء فقال له إسحاق ليتنا نفي بما علمناه فإنا لا نحتاج إلى الزيادة فيه ثم قال له فإنه يزعم أن حلاوة الغناء تحريكه وتحريكه عنده أن يكون كثير النغم وليس يفعل ذلك إنما يسقط بعض عمله لعجزه عنه فإذا فعل ذلك فهو بالإضافة إلى حاله الأولى بمنزلة الأسكدار للكتاب وهو حينئذ بأن يسمى المحذوف أشبه منه بأن يسمى المحرك فضحك علويه ثم قال فإن إبراهيم يسمي غناءكم هذا الممسك المدادي قال إسحاق هذا من لغات الحاكة لأنهم يسمون الثوب الجافي الكثير العرض والطول المدادي وعلى هذا القياس فينبغي لنا أن نسمي غناءه المحرك الضرابي وهو الخفيف السخيف من الثياب في لغة الحاكة حتى ندخل الغناء في جملة الحياكة ونخرجه عن جملة الملاهي ثم قال لعلويه بحياتي عليك إلا ما أعدت عليه ما جرى فقال له لا وحياتك لا فعلت فإنه يعلم ميلي إليكم ولكن عليك بأبي جعفر محمد بن راشد الخناق فكلمه إسحاق وأقسم عليه أن يؤيده ففعل وسار إلى إبراهيم فأخبره فجعل كلما أخبره شيئا تغيظ وشتم إسحاق بأقبح شتم ثم جاءه ابن راشد فأخبره فجعل كلما أخبره بشيء من ذلك ضحك وصفق سرورا لغيظ إبراهيم من قوله\nأخبرني حبيب بن نصر المهلبي قال حدثني علي بن محمد النوفلي قال أخبرني محمد بن راشد الخناق قال إني لفي منزلي يوما مع الظهر إذ دخل علي إسحاق بن إبراهيم الموصلي فسررت بمكانه فقال قد جاءت بي إليك حاجة قال قلت قل ما شاء الله قال دعني في بيتك ودع غلاميك عندي بديحا وسليمان وكانا خادمين مغنيين ومرهما أن يغنياني وأتني بفلان ليغنيني أيضا بحياتي عليك وانطلق إلى إبراهيم بن المهدي فإنه سيسر بمكانك فاشرب معه أقداحا ثم قل له يا سيدي أسألك عن شيء فإذا قال سل فقل له أخبرني عن قولك\n(ذهبت من الدنيا وقد ذهبت مني ... )","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":42,"spl":"الواثق يثني على إسحاق","partial":1},
{"id":"b52-71","bab":"الجزء 5","sec":"الواثق يثني على إسحاق","page":"ج5 ص296","text":"ي شيء كان معنى صنعتك فيه وأنت تعلم أنه لا يجوز في غنائك الذي صنعته فيه إلا أن تقول ذهبتو بالواو فإن قلت ذهبت ولم تمدها انقطع اللحن والشعر وإن مددتها قبح الكلام وصار على كلام النبط فقلت له يا أبا محمد كيف أخاطب إبراهيم بهذا فقال هو حاجتي إليك وقد كلفتك إياها فإن استحسنت أن تردني فأنت أعلم قال أفعل ذلك لموضعك على ما فيه علي ثم أتيت إبراهيم وجلست عنده مليا وتجارينا الحديث إلى أن خرجنا إلى ذكر الغناء فخاطبته بما قال لي إسحاق فتغير لونه وانكسر ثم قال يا محمد ليس هذا من كلامك هذا من كلام الجرمقاني ابن الزانية قل له عني أنتم تصنعون هذه للصناعة ونحن نصنعه للهو واللعب والعبث قال فخرجت إلى إسحاق فحدثته بذلك فقال الجرمقاني والله منا أشبهنا بالجرامقة لغة وهو الذي يقول ذهبتو وأقام عندي يومه فرحا بما بلغته إبراهيم عنه من توقيفه على خطئه","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":43,"spl":"الواثق يثني على إسحاق — إسحاق وصداقة محمد بن راشد"},
{"id":"b52-72","bab":"الجزء 5","sec":"إسحاق وصداقة محمد بن راشد","page":"ج5 ص300","text":"قال علي بن محمد قال لي أبي كان محمد بن راشد صديقا لإسحاق ثم فسد ما بينهما فإنه طابق إبراهيم بن المهدي عليه وبلغه عنه من توقيعه أن يذكره وكان في محمد ابن رشد رداءه ونقل لأحاديث فقال فيه إسحاق\n(وندمان صدق لا تخاف أذاته ... ولا يلفظ الأخبار لفظ ابن راشد)\n(دعاني إلى ما يشتهي فأجبته ... إجابة محمود الخلائق ماجد)\n(فلا خير في اللذات إلا بأهلها ... ولا عيش إلا بالخليل المساعد)\nال فجمع ابن راشد عدة من الشعراء وأمرهم بهجاء إسحاق فهجوه بأشعار لم تبلغ مراده فلم يظهرها وبلغ ذلك إسحاق فقال فيه\n(وأبيات شعر رائعات كأنها ... إذا أنشدت في القوم من حسنها سحر)\n(تحفز واقلولى لرد جوابها ... أبو جعفر يغلي كما غلت القدر)\n(فلم يستطعها غير أن قد أعانه ... عليها أناس كي يكون له ذكر)\n(فيا ضيعة الأشعار إذ يقرضونها ... وأضيع منها من يرى أنها شعر)\nال فعاذ محمد بن راشد بإسحاق واستكفه وصالحه فرجع إليه أخبرني عمي قال حدثني علي بن محمد بن نصر الشامي قال حدثني منصور بن محمد بن واضح أن إبراهيم بن المهدي طرح في منزل أبيه\nصوت\n(أمن آل ليلى عزفت الطلولا ... بذي حرض ماثلات مثولا)\n(بلين وتحسب آياتهن ... عن فرط حولين رقا محيلا)\nلشعر لكعب بن زهير والغناء لإسحاق وله فيه لحنان ثاني ثقيل مطلق في مجرى البنصر وماخوري بالوسطى وفيه للزبير بن دحمان خفيف ثقيل قال فجاءنا إسحاق يوما وأقام عند أبي وأخرجنا إليه جوارينا ومر الصوت الذي طرحه إبراهيم بن المهدي من غنائه فقال إسحاق من أين لك هذا قال طرحه أبو إسحاق إبراهيم بن المهدي أعزه الله تعالى فقال إسحاق وما لأبي إسحاق أعزه الله ولهذا الصوت هذا أنا صنعته وليس هو كما طرحه قال فسأله أبي أن يغنيه فغناه وردده حتى صح لمن عنده فقال لي أبي أكتب إلى أبي إسحاق أن أبا محمد أعزه الله صار إلي فاحتبسته وأنه غنى بحضرتي الصوت الذي ألقيته في منزلك الذي أسكنه فزعم أنه صنعه وأنه ليس على ما أخذه الجواري عنك فأحببت أن أعلم ما عندك جعلني الله فداك قال فكتبت الرقعة وأنفذتها إلى إبراهيم فكتب نعم جعلت فداك صدق أبو محمد أعزه الله والصوت له وهو على ما ذكره لكني لعبت في وسطه لعبا أعجبني قال فقرأ إسحاق الرقعة فغضب غضبا شديدا ثم قال لي اكتب إليه إذا أردت\nيا هذا أن تلعب فالعب في غناء نفسك لا في غناء الناس وما حاجتك إلى هذا الشعر أكثر من ذلك فاصنع أنت إن كنت تحسن وألعب في صنعتك كما تشتهي مبتدئا باللهو واللعب غير مشارك في جد الناس بلعبك ومفسد له بما لا تعلمه يا أبا إسحاق أيدك الله ليس هذا الصوت مما يتهيأ لك أن تمخرق فيه وتقول جندرته قال وكان إبراهيم يقول إنه يجندر صنعة القدماء ويحسنها","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":43,"spl":"الواثق يثني على إسحاق — إسحاق وصداقة محمد بن راشد"},
{"id":"b52-73","bab":"الجزء 5","sec":"إسحاق يناظر إبراهيم بن المهدي في الغناء","page":"ج5 ص302","text":"قال علي بن محمد حدثني جدي حمدون أن إسحاق قال لإبراهيم بن المهدي بحضرة المعتصم ما تقول فيمن يزعم أن ابن سريج وابن محرز ومعبدا ومالكا وابن عائشة لم يكونوا يحسنون تمام الصنعة ولا استيفاء الغناء ويعجزون عما به يكمل ويتم ويحسن وأنه أقدر على الصنعة منهم قال أقول إنه جاهل أحمق قال فأنت تزعم أنه قد كانت بقيت عليهم أشياء لم يهتدوا لها ولم يحسنوها فتنبهت عليها أنت وتممتها وحسنتها بجندرتك قال فضحك المعتصم وبقي إبراهيم واجما مطرقا ولم ينتفع بنفسه بقية يومه وما سمعته أنا ولا غيري بعد ذلك اليوم يتبجح بغناء يصلحه من غناء المتقدمين حتى يطنب في صنعته ويشتهى استماعه منه كما كان يدعي قديما قال وكان حمدون يقول كان إبراهيم يأكل المغنين أكلا حتى يحضر إسحاق فيداريه إبراهيم ويطلب مكافأته ولا يدع إسحاق تبكيته ومعارضته وكان إسحاق آفته كما أن لكل شيء آفة أخبرني جعفر بن قدامة قال حدثني حماد بن إسحاق عن أبيه قال\nخرجت يوما من داري وأنا مخمور أتنسم الهواء فمررت برجل ينشد رجلا معه لذي الرمة صوت\n(ألم تعلمي يا مي أني وبيننا ... مهاو لطرف العين فيهن مطرح)\n(ذكرتك أن مرت بنا أم شادن ... أمام المطايا تشرئب وتسنح)\n(من المؤلفات الرمل أدماء حرة ... شعاع الضحى في متنها يتوضح)\n(هي الشبه أعطافا وجيدا ومقلة ... ومية منها بعد أبهى وأملح)\n(كأن البرى والعاج عيجت متونه ... على عشر نهى به السيل أبطح)\n(لئن كانت الدنيا علي كما أرى ... تباريح من مي فللموت أروح)\nأعجبني فصنعت فيه لحنا غنيت به المأمون فأخذت به منه مائة ألف درهم لحن إسحاق في هذه الأبيات أول مطلق في مجرى البنصر حدثني يحيى بن محمد الطاهري قال حدثني ينشو مولى أبي أحمد بن الرشيد قال اشتراني مولاي أبو أحمد بن الرشيد واشترى رفيقي محموما فدفعنا إلى وكيل له أعجمي خراساني وقال له انحدر بهذين الغلامين إلى بغداد\nإلى إسحاق الموصلي ودفع إليه مائة ألف درهم وشهريا بسرجه ولجامه وثلاثة أدراج من فضة مملوءة طيبا وسبعة تخوت من بز خراساني وعشرة أسفاط من بز مصر وخمسة تخوت وشي كوفي وخمسة تخوت خز سوسي وثلاثين ألف درهم للنفقة وقال للرسول عرف إسحاق أن هذين الغلامين لرجل من وجوه أهل خراسان وجه بهما إليه ليتفضل ويعلمهما أصواتا اختارها وكتبها له في درج وقال له كلما علمهما صوتا ادفع إليه ألف درهم حتى يتعلما بها مائة صوت فإذا علمهما الصوتين اللذين بعد المائة فادفع إليه الشهري ثم إذا علمهما الثلاثة التي بعد الصوتين فادفع إليه بكل صوت درجا من الأدراج ثم لكل صوت بعد ذلك تختا أو سفطا حتى ينفد ما بعثت به معك ففعل وانحدرنا إلى بغداد فأتينا إسحاق وغنينا بحضرته وبلغه الوكيل الرسالة فلم يزل يلقي علينا الأصوات حتى أخذناها كما أمرنا سيدنا ثم سرنا إلى سر من رأى فدخلنا إليه وغنيناه جميع ما أخذناه فسره ذلك وقدم إسحاق سر من رأى ولقيه مولانا فدعا بنا وأوصانا بما أراد وغدا بنا إلى الواثق وقال إنكما ستريان إسحاق بين يديه فلا تسلما عليه ولا توهماه أنكما رأيتماه قط وألبسنا أقبية خراسانية ومضينا معه فلما دخلنا على الواثق قال له يا سيدي هذان غلامان اشتريا لي من خراسان يغنيان بالفارسية فقال غنيا فضربنا ضربا فارسيا وغنينا غناء فهليذيا فطرب الواثق وقال\nأحسنتما فهل تغنيان بالعربية قلنا نعم واندفعنا نغني ما أخذناه عن إسحاق وهو ينظر إلينا ونحن نتغافل عنه حتى غنينا أصواتا من غنائه فقام إسحاق ثم قال للواثق وحياتك يا سيدي وبيعتك وإلا كل ملك لي صدقة وكل مملوك لي حر إن لم يكن هذان الغلامان من تعليمي ومن قصتهما كيت وكيت فقال له أبو أحمد ما أدري ما تقول هذان اشتريتهما من رجل نخاس خراساني فقال له بلغ ولعك إلي ونخاس خراساني من أين يحسن أن يختار مثل تلك الأغاني فضحك أبو أحمد ثم قال صدق أنا احتلت عليه ولو رمت أن يعلمهما ما أخذاه منه إذا علم أنهما لي بعشرة أضعاف ما أعطيته لما فعل فقال له إسحاق قد تمت علي حيلته وقال أبو أحمد للواثق إن أردتهما فخذهما فقال لا أفجعك بهما يا عم ولكن لا تمنعني حضورهما فقال له قد بذلت لك الملك فلم تؤثره أفتراني أمنعك الخدمة فكنا نخدمه بنوبة","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":44,"spl":"إسحاق يناظر إبراهيم بن المهدي في الغناء"},
{"id":"b52-74","bab":"الجزء 5","sec":"الواثق يرفع إسحاق إلى صف الجلساء","page":"ج5 ص305","text":"حدثني جحظة قال حدثني أبو عبد الله بن حمدون قال حدثني ابن فيلا الطنبوري وكان قد دخل على الواثق وغناه قال قال الواثق في بعض العشايا لا يبرح أحد من المغنين الليلة فقد عزمت على الصبوح في غد فأمسكوا جميعا عن معارضته إلا إسحاق فإنه قال له لا وحياتك ما أبيت قال فلا والله ما كان له عند الواثق معارضة أكثر من أن قال له فبحياتي إلا بكرت يا أبا محمد قال فرأيت مخارقا وعلويه قد تقطعا غيظا وبتنا في بعض الحجر فقالا لي اجلس على باب الحجرة فإذا جاء إسحاق فعرفنا حتى ندخل بدخوله فلم نلبث أن جاء\nإسحاق مع أحمد بن أبي داود يماشيه في زيه وسواده وطويلته مثل طويلته فدخلت فأعلمتهما فقامت على علويه القيامة وقال يا هؤلاء خيناكر يدخل إلى الخليفة مع قاضي القضاة أسمعتم بأعجب من هذا البخت قط فقال له مخارق دع هذا عنك فقد والله بلغ ما أراد ولم نلبث أن خرج ابن أبي داود ودعي بنا فدخلنا فإذا إسحاق جالس في صف الندماء لا يخرج منه فإذا أمره الواثق أن يغني خرج عن صفهم قليلا وأتي بعود فغنى الصوت الذي يأمره به فإذا فرغ من القدح قطع الصوت الذي يأمره به حيث بلغ ولم يتمه ورجع إلى صف الجلساء","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":45,"spl":"الواثق يرفع إسحاق إلى صف الجلساء"},
{"id":"b52-75","bab":"الجزء 5","sec":"قصة إبراهيم بن المهدي في مجلس الرشيد","page":"ج5 ص306","text":"أخبرني محمد بن أحمد بن إسماعيل بن إبراهيم الموصلي الملقب بوسواسة قال حدثني حماد قال قال لي أبي كنت عند الرشيد يوما وعنده ندماؤه وخاصته وفيهم إبراهيم بن المهدي فقال لي الرشيد يا إسحاق تغن\n(شربت مدامة وسقيت أخرى ... وراح المنتشون وما انتشيت)\nغنيته فأقبل علي إبراهيم بن المهدي فقال لي ما أصبت يا إسحاق ولا أحسنت فقلت ليس هذا مما تحسنه ولا تعرفه وإن شئت فغنه فإن لم أجدك أنك تخطئ فيه منذ ابتدائك إلى انتهائك فدمي حلال ثم أقبلت على الرشيد فقلت يا أمير المؤمنين هذه صناعتي وصناعة أبي وهي التي قربتنا منك واستخدمتنا لك وأوطأتنا بساطك فإذا نازعناها أحد بلا علم لم نجد بدا من الإيضاح والذب فقال لا غرو ولا لوم عليك فقام الرشيد ليبول فأقبل إبراهيم بن المهدي علي وقال ويلك يا إسحاق أتجترئ علي وتقول ما قلت يابن الفاعلة لا يكني فداخلني ما لم أملك نفسي معه فقلت له أنت تشتمني وأنا لا أقدر على إجابتك وأنت ابن الخليفة وأخو الخليفة ولولا ذلك لكنت أقول لك يابن الزانية أو ترى أني كنت لا أحسن أن أقول لك يابن الزانية ولكن قولي في ذمك ينصرف جميعه إلى خالك الأعلم ولولاك لذكرت صناعته ومذهبه قال إسحاق وكان بيطارا قال ثم سكت وعلمت أن إبراهيم يشكوني وأن الرشيد سوف يسأل من حضر عما جرى فيخبرونه فتلافيت ذلك ثم قلت أنت تظن أن الخلافة تصير إليك فلا تزال تهددني بذلك وتعاديني كما تعادي سائر أولياء أخيك حسدا له ولولده على الأمر فأنت تضعف عنه وعنهم وتستخف بأوليائهم تشفيا وأرجوا ألا يخرجها الله عن يد الرشيد وولده وأن يقتلك دونها فإن صارت إليك وبالله العياذ فحرام علي العيش يومئذ والموت أطيب من الحياة معك فاصنع حينئذ ما بدا لك قال فلما خرج الرشيد وثب إبراهيم فجلس بين يديه فقال يا أمير المؤمنين شتمني وذكر أمي واستخف\nبي فغضب وقال ما تقول ويلك قلت لا أعلم فسل من حضر فأقبل على مسرور وحسين فسألهما عن القصة فجعلا يخبرانه ووجهه يتربد إلى أن انتهيا إلى ذكر الخلافة فسري عنه ورجع لونه وقال لإبراهيم ماله ذنب شتمته فعرفك أنه لا يقدر على جوابك ارجع إلى موضعك وأمسك عن هذا فلما انقضى المجلس وانصرف الناس أمر بألا أبرح وخرج كل من حضر حتى لم يبق غيري فساء ظني وأهمتني نفسي فأقبل علي وقال ويلك يا إسحاق أتراني لم أفهم قولك ومرادك قد والله زنيته ثلاث مرات أتراني لا أعرف وقائعك وأقدامك وأين ذهبت ويلك لا تعد حدثني عنك لو ضربك إبراهيم أكنت أقتص لك منه فأضربه وهو أخي يا جاهل أتراك لو أمر غلمانه فقتلوك أكنت أقتله بك فقلت يا أمير المؤمنين قد والله قتلتني بهذا الكلام ولئن بلغه ليقتلني وما أشك في أنه قد بلغه الآن فصاح بمسرور الخادم وقال علي بإبراهيم الساعة فأحضر وقال قم فانصرف وقلت لجماعة من الخدم وكلهم كان لي محبا وإلي مائلا ولي مطيعا أخبروني بما يجري فأخبروني من غد أنه لما دخل وبخه وجهله وقال له أتستخف بخادمي وصنيعتي ونديمي وابن نديمي وابن خادمي وصنيعتي وصنيعة أبي في مجلسي وتقدم علي وتستخف بمجلسي وحضرتي هاه هاه أتقدم على هذا وأمثاله وأنت مالك وللغناء وما يدريك ما هو ومن أخذك به وطارحك إياه حتى تتوهم أنك تبلغ مبلغ إسحاق الذي غذي به وعلمه وهو صناعته ثم تظن أنك تخطئه فيما لا تدريه ويدعوك إلى إقامة الحجة عليك فلا تثبت لذلك وتعتصم بشتمه أليس هذا مما يدل على السقوط وضعف العقل وسوء الأدب من دخولك فيما لا يشبهك وغلبة لذتك على مروءتك وشرفك ثم إظهارك إياه ولم تحكمه","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":46,"spl":"قصة إبراهيم بن المهدي في مجلس الرشيد"},
{"id":"b52-76","bab":"الجزء 5","sec":"قصة إبراهيم بن المهدي في مجلس الرشيد","page":"ج5 ص306","text":"وادعائك ما لا تعلمه حتى ينسبك الناس إلى الجهل المفرط ألا تعلم ويلك أن هذا سوء أدب وقلة معرفة وقلة مبالاة بالخطأ والتكذيب والرد القبيح ثم قال والله العظيم وحق رسوله وإلا فأنا نفي من المهدي لئن أصابه أحد بسوء أو سقط عليه حجر من السماء أو سقط من على دابته أو سقط عليه سقفه أو مات فجأة لأقتلنك به والله والله والله فلا تعرض له وأنت أعلم قم الآن فاخرج فخرج وقد كاد أن يموت فلما كان بعد ذلك دخلت إليه وإبراهيم عنده فأعرضت عن إبراهيم وجعل ينظر إليه مرة وإلي مرة ويضحك ثم قال له إني لأعلم محبتك في إسحاق وميلك إليه وإلى الأخذ عنه وإن هذا لا يجيئك من جهته كما تريد إلا بعد أن يرضى والرضا لا يكون بمكروه ولكن أحسن إليه وأكرمه واعرف حقه وبره وصله فإذا فعلت ذلك ثم خالفك فيما تهواه عاقبته بيد منبسطة ولسان منطلق ثم قال لي قم إلى مولاك وابن مولاك فقبل رأسه فقمت إليه وقام إلي وأصلح الرشيد بيننا","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":47,"spl":"قصة إبراهيم بن المهدي في مجلس الرشيد — نسبة الصوت المذكور في هذا الخبر"},
{"id":"b52-77","bab":"الجزء 5","sec":"نسبة الصوت المذكور في هذا الخبر","page":"ج5 ص309","text":"صوت\n(أعاذل قد نهيت فما انتهيت ... وقد طال العتاب فما ارعويت)\n(أعاذل ما كبرت وفي ملهى ... ولو أدركت غايتك انتهيت)\n(شربت مدامة وسقيت أخرى ... وراح المنتشون وما انتشيت)\n(أبيت معذبا قلقا كئيبا ... لما ألقاه من ألم وفوت)\nلغناء لابن محرز ثقيل عن ابن المكي وفيه رمل بالوسطى","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":47,"spl":"قصة إبراهيم بن المهدي في مجلس الرشيد — نسبة الصوت المذكور في هذا الخبر"},
{"id":"b52-78","bab":"الجزء 5","sec":"إسحاق مغني الرشيد ونديمه","page":"ج5 ص310","text":"أخبرني محمد بن مزيد بن أبي الأزهر قال حدثنا حماد بن إسحاق عن أبيه قال أرسل إلي الرشيد ذات ليلة فدخلت إليه فإذا هو جالس وبين يديه جارية عليها قميص مورد وسراويل موردة وقناع مورد كأنها ياقوتة على وردة فلما رآني قال لي اجلس فجلست فقال لي غن فغنيت\n(تشكى الكميت الجري لما جهدته ... وبين لو يسطيع أن يتكلما)\nقال لمن هذا اللحن فقلت لي يا أمير المؤمنين فقال هات لحن ابن سريج فغنيته إياه فطرب وشرب رطلا وسقى الجارية رطلا وسقاني رطلا ثم قال غن فغنيته صوت\n(هاج شوقي بعد ما شيب ... أصداغي بروق)\n(موهنا والبرق مما ... ذا الهوى قدما يشوق)\nقال لمن هذا الصوت فقلت لي فقال قد كنت سمعت فيه لحنا آخر فقلت نعم لحن ابن محرز قال هاته فغنيته فطرب وشرب رطلا ثم سقى الجارية رطلا وسقاني رطلا ثم قال غن فغنيته\n(أفاطم مهلا بعض هذا التدلل ... وإن كنت قد أزمعت صرمي فأجملي)\nقال لي ليس هذا اللحن أريد غن رمل ابن سريج فغنيته وشرب\nرطلا وسقى الجارية رطلا ثم قال حدثني فجعلت أحدثه بأحاديث القيان والمغنين طورا وأحاديث العرب وأيامها وأخبارها تارة وأنشده أشعار القدماء والمحدثين في خلال ذلك إذ دخل الفضل بن الربيع فحدثه حديث ثلاث جوار ملكهن ووصفهن بالحسن والإحسان والظرف والأدب فقال له يا عباسي هل تسخو نفسك بهن وهل لك من سلوة عنهن فقال له والله يا أمير المؤمنين إني لأسخو بهن وبنفسي فبها فداك الله ثم قام فوجه بهن إليه فغلبن على قلبه وهن سحر وضياء وخنث ذات الخال وفيهن يقول\n(إن سحرا وضياء وخنث ... هن سحر وضياء وخنث)\n(أخذت سحر ولا ذنب لها ... ثلثي قلبي وترباها الثلث)\nدثني الصولي قال حدثني ميمون بن هارون عن إسحاق قال أتيت عبيد الله بن محمد بن عائشة بالبصرة فلما دخلت إليه حصرت فقال لي إن الحصر رائد الحياء والحياء عقيد الإيمان فانبسط وأزل الوحشة فلئن باعدت بيننا الأحساب لقد قربت بيننا الآداب فقلت له والله لقد سررتني بخطابك وزدتني ببرك عجزا عن جوابك ولله در القطامي حيث يقول\n(أما قريش فلن تلقاهم أبدا ... وإلا وهم خير من يحفى وينتعل)\nخبرني علي بن صالح بن الهيثم قال حدثني أبو هفان قال وجه أحمد بن هشام إلى إسحاق الموصلي بزعفران رطب وكتب إليه\n(اشرب على الزعفران الرطب متكئا ... وانعم نعمت بطول اللهو والطرب)\n(فحرمة الكأس بين الناس واجبة ... كحرمة الود والأرحام والأدب)\nال فكتب إليه إسحاق\n(أذكر أبا جعفر حقا أمت به ... أني وإياك مشغوفان بالأدب)\n(وأننا قد رضعنا الكأس درتها ... والكأس حرمتها أولى من النسب)\nدثنا الصولي قال حدثني محمد بن موسى عن حماد بن إسحاق عن أبيه قال لما أراد الفضل بن يحيى الخروج إلى خراسان ودعته ثم أنشدته بعد التوديع\n(فراقك مثل فراق الحياة ... وفقدك مثل افتقاد الديم)\n(عليك السلام فكم من وفاء ... أفارق فيك وكم من كرم)\nقال فضمني إليه وأمر لي بألف دينار وقال لي يا أبا محمد لو حليت هذين البيتين بصنعة وأودعتهما من يصلح من الخارجين معنا لأهديت بذلك إلي أنسا وأذكرتني بنفسك ففعلت ذلك وطرحته على بعض المغنين فكان كتابه لا يزال يرد علي ومعه ألف دينار يصلني بذلك كلما غني بهذا الصوت قال الصولي وهو من طريقة الرمل\nأخبرني عمي قال حدثني عمر بن شبة عن إسحاق قال قال لي الأصمعي لما خرجنا مع الرشيد إلى الرقة قال لي هل حملت معك شيئا من كتبك فقلت نعم حملت منها ما خف حمله فقال كم فقلت ثمانية عشر صندوقا فقال هذا لما خففت فلو ثقلت كم كنت تحمل فقلت أضعافها فجعل يعجب","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":48,"spl":"إسحاق مغني الرشيد ونديمه"},
{"id":"b52-79","bab":"الجزء 5","sec":"شعر إسحاق في المعتصم","page":"ج5 ص313","text":"أخبرنا إسماعيل بن يونس قال حدثنا عمر بن شبة قال حدثني إسحاق قال لما ولي المعتصم دخلت إليه في جملة الجلساء والشعراء فهنأه القوم نظما ونثرا وهو ينظر إلي مستنطقا فأنشدته صوت\n(لاح بالمفرق منك القتير ... وذوى غصن الشباب النضير)\n(هزئت أسماء مني وقالت ... أنت يابن الموصلي كبير)\n(ورأت شيبا برأسي فصدت ... وابن ستين بشيب جدير)\n(لا يروعنك شيبي فإني ... مع هذا الشيب حلو مزير)\n(قد يفل السيف وهو جراز ... ويصول الليث وهو عقير)\n(يا بني العباس أنتم شفاء ... وضياء للقلوب ونور)\n(أنتم أهل الخلافة فينا ... ولكم منبرها والسرير)\n(لا يزال الملك فيكم مدى الدهر ... مقيما ما أقام ثبير)\n(وأبو إسحاق خير إمام ... ماله في العالمين نظير)\n(ما له فيما يريش ويبري ... غير توفيق الإله وزير)\n(واضح الغرة للخير فيه ... حين يبدو شاهد وبشير)\n(زانه هدي تقى وجلال ... وعفاف ووقار وخير)\n(لو تباري جوده الريح يوما ... نزعت وهي طليح حسير)\nقال فأمر لي بجائزة فضلني بها على الجماعة ثم دخلت إليه يوم مقدمه من غزاته فأنشدته قولي فيه صوت\n(لأسماء رسم عفا باللوى ... أقام رهينا لطول البلى)\n(تعاوره الدهر في صرفه ... بكر الجديدين حتى عفا)\n(إذ البين لم تخش روعاته ... ولم يصرف الحي صرف الردى)\n(وإذ ميعة اللهو يجري بنا ... وحبل الوصال متين القوى)\n(فذلك دهر مضى فابكه ... ومن ضاق ذرعا بأمر بكى)\n(وهل يشفينك من غلة ... بكاؤك في إثر ما قد مضى)\n(إلى ابن الرشيد إمام الهدى ... بعثنا المطي تجوب الفلا)\n(إلى ملك حل من هاشم ... ذؤابة مجد منيف الذرى)\n(إذا قيل أي فتى هاشم ... وسيدها كان ذاك الفتى)\n(به نعش الله آمالنا ... كما نعش الأرض صوب الحيا)\n(إذا ما نوى فعل أكرومة ... تجاوز من جوده ما نوى)\n(كساه الإله رداء الجمال ... ونور الجلال وهدي التقى)\nقال فأمر لي بجائزة وقال لست أحسب هذا لك إلا بعد أن تقرن صناعتك فيه بالأخرى يعني أن أغني فيه وفي هزئت أسماء مني فصنعت في\n(هزئت أسماء مني ... )\nحنا وفي\n(لأسماء رسم عفا باللوى ... )\nخنا آخر وغنيته بهما فأمر لي بألفي دينار","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":49,"spl":"شعر إسحاق في المعتصم","partial":1},
{"id":"b52-80","bab":"الجزء 5","sec":"نسبة هذين الصوتين","page":"ج5 ص315","text":"(هزئت أسماء مني وقالت ... أنت يابن الموصلي كبير)\nحن إسحاق في أربعة أبيات متوالية من الشعر ثقيل أول بالوسطى والآخر\n(لأسماء رسم عفا باللوى ... أقام رهينا لطول البلى)\nلغناء لإسحاق ثاني ثقيل بالوسطى أخبرني يحيى بن علي قال حدثني أبي قال حدثني أحمد بن عبيد الله ابن أبي العلاء قال غنيت يوما بين يدي الواثق لحن إسحاق في\n(هزئت أسماء مني وقالت ... أنت يا بن الموصلي كبير)\nال فنظر إلي مخارق نظر شزرا وعض شفته علي فلما خرجنا من\nبين يدي الواثق قلت يا أستاذ لم نظرت إلي ذلك النظر أأنكرت علي شيئا أم أخطأت في غنائي فقال لي ويحك أتدري أي صوت غنيت إن إسحاق جعل صيحة هذا الصوت بمنزلة طريق ضيق وعر صعب المرتقى أحد جانبي ذلك الطريق حرف الجبل وعن جانبه الآخر الوادي فإن مال مرتقيه عن محجته إلى جانب الوادي هوى وإن مال إلى الجانب الآخر نطحه حرف الجبل فتكسر صر إلي غدا حتى أصححه لك أخبرني علي بن سليمان الأخفش قال حدثنا محمد بن يزيد قال حدثت من غير وجه أن إسحاق بات ليلة عند المعتصم وهو أمير فسمع لحنا لعبد الوهاب المؤذن أذن به على باب المعتصم فأصغى إليه فأعجبه فأعاد المبيت ليلة أخرى عنده حتى استقام له اللحن فبنى عليه لحنه\n(هزئت أسماء مني وقالت ... )\nخبرني الحسن بن علي قال حدثنا يزيد بن محمد المهلبي أن إبراهيم بن المهدي فصد يوما فكتب إليه إسحاق يتعرف خبره ويدعو له بالسلامة وحسن العقبى وكتب إليه إني سأهدي إليك هدية للفصد حسنة فوجه إليه بديحا غلامه فغناه ه في\n(هزئت أسماء مني وقالت ... )\nاستحسنه إبراهيم وقال له قد قبلنا الهدية فإن كان أذن لك في طرحه على الجواري فافعل فقال له بذلك أمرني وقال لي إنك ستقول لي هذا القول فقال إن قاله لك فقل له لو لم آمرك بطرحه لم يكن هدية فضحك إبراهيم وألقاه بديح على جواريه وقد ذكر علي بن\nمحمد بن نصر هذا الخبر فذكر أنه كتب إلى أبيه بهذه الهدية وهذا خطأ لأن الشعر في تهنئة المعتصم بالخلافة وإبراهيم الموصلي مات في حياة الرشيد فكيف يهدي إليه هذا الصوت أخبرنا يحيى بن علي قال حدثني أبي قال حدثني أحمد بن أبي العلاء قال اندفع محمد بن الحارث بن بسخنر يوما يغني هذا الصوت فالتفت إلينا مخارق فقال خرج ابن الزانية","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":50,"spl":"نسبة هذين الصوتين","partialRef":{"sid":"b52-79","gi":0,"vi":1,"side":0},"partial":1},
{"id":"b52-81","bab":"الجزء 5","sec":"إسحاق يحاور علويه في مجلس الفضل بن الربيع","page":"ج5 ص317","text":"حدثني عمي قال حدثني أبو جعفر محمد بن الدهقانة النديم قال حدثني أحمد بن يحيى المكي قال دعاني الفضل بن الربيع ودعا علويه ومخارقا وذلك في أيام المأمون بعد رجوعه ورضاه عنه إلا أن حاله كانت ناقصة متضعضعة فلما اجتمعنا عنده كتب إلى إسحاق الموصلي يسأله أن يصير إليه ويعلمه الحال في اجتماعنا عنده فكتب إليهم لا تنتظروني بالأكل فقد أكلت وأنا أصير إليكم بعد ساعة فأكلنا وجلسنا نشرب حتى قرب العصر ثم وافى إسحاق فجلس وجاء غلامه بقطرميز نبيذ فوضعه ناحية وأمر صاحب الشراب بإسقائه منه وكان علويه يغني الفضل بن الربيع في لحن لسياط اقترحه الفضل عليه وأعجبه وهو\n(فإن تعجبي أو تبصري الدهر طمني ... بأحداثه طم المقصص بالجلم)\n(فقد أترك الأضياف تندى رحالهم ... وأكرمهم بالمحض والتامك السنم)\nلحنه من الثقيل الثاني فقال له إسحاق أخطأت يا أبا الحسن في أداء هذا الصوت وأنا أصلحه لك فجن علويه واغتاظ وقامت قيامته ثم أقبل على علويه فقال له يا حبيبي ما أردت الوضع منك بما قلته لك وإنما أردت تهذيبك وتقويمك لأنك منسوب الصواب والخطأ إلى أبي وإلي فإن كرهت ذلك تركتك وقلت لك أحسنت وأجملت فقال له علويه والله ما هذا أردت ولا أردت إلا ما لا تتركه أبدا من سوء عشرتك أخبرني عنك حين تجيء هذا الوقت لما دعاك الأمير وعرفك أنه قد نشط للاصطباح ما حملك على الترفع عن مباكرته وخدمته مع صنائعه عندك وما كان ينبغي أن يشغلك عنه شيء إلا الخليفة ثم تجيئه ومعك قطرميز نبيذ ترفعا عن شرابه كما ترفعت عن طعامه ومجالسته إلا كما تشتهي وحين تنشط كما تفعل الأكفاء بل تزيد على فعل الأكفاء ثم تعمد إلى صوت قد اشتهاه واقترحه وسمعه جميع من حضر فما عابه منهم أحد فتعيبه ليتم تنغيصك إياه لذته أما والله لو الفضل بن يحيى أو أخوه جعفر دعاك إلى مثل ما دعاك إليه الأمير بل بعض أتباعهم لبادرت وباكرت وما تأخرت ولا اعتذرت قال فأمسك الفضل عن الجواب إعجابا بما خاطب به علويه إسحاق فقال له إسحاق أما ما ذكرته من تأخري عنه إلى الوقت الذي حضرت فيه فهو يعلم أني لا أتأخر عنه إلا بعائق قاطع إن وثق بذلك مني وإلا ذكرت له الحجة سرا من حيث لا يكون لك ولا لغيرك فيه مدخل وأما ترفعي عنه فكيف أترفع عنه وأنا أنتسب إلى صنائعه وأستمنحه وأعيش من فضله مذ كنت وهذا تضريب لا أبالي به منك وأما حملي النبيذ معي فإن لي في النبيذ شرطا من طعمه وريحه وإن لم أجده لم أقدر على الشرب وتنغص","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":51,"spl":"إسحاق يحاور علويه في مجلس الفضل بن الربيع"},
{"id":"b52-82","bab":"الجزء 5","sec":"إسحاق يحاور علويه في مجلس الفضل بن الربيع","page":"ج5 ص317","text":"علي يومئذ وإنما حملته ليتم نشاطي وينتفع بي وأما طعني على ما اختاره فإني لم أطعن على اختياره وإنما أردت تقويمك ولست والله تراني متتبعا لك بعد هذا اليوم ولا مقوما شيئا من خطئك وأنا أغني له أعزه الله هذا الصوت فيعلم وتعلم ويعلم من حضر أنك أخطأت فيه وقصرت وأما البرامكة وملازمتي لهم فأشهر من أن أجحده وإني لحقيق فيه بالمعذرة وأحرى أن أشكرهم على صنيعهم وبأن أذيعه وأنشره وذلك والله أقل ما يستحقونه مني ثم أقبل على الفضل وقد غاظه مدحه لهم فقال اسمع مني شيئا أخبرك به مما فعلوه ليس هو بكبير في صنائعهم عندي ولا عند أبي قبلي فإن وجدت لي عذرا وإلا فلم كنت في ابتداء أمري نازلا مع أبي في داره فكان لا يزال يجري بين غلماني وغلمانه وجواري وجواريه الخصومة كما تجري بين هذه الطبقات فيشكونهم إليه فأتبين الضجر والتنكر في وجهه فاستأجرت دارا بقربه وانتقلت إليها أنا وغلماني وجواري وكانت دارا وساعة فلم أرض ما معي من الآلة لها ولا لمن يدخل إلي من أخواني أن يروا مثله عندي ففكرت في ذلك وكيف أصنع وزاد فكري حتى خطر بقلبي قبح الأحدوثة من نزول مثلي في دار بأجرة وأني لا آمن في وقت أن يستأذن علي صاحب داري وعندي من أحتشمه ولا يعلم حالي فيقال صاحب دارك أو يوجه في وقت فيطلب أجرة الدار وعندي من أحتشمه فضاق بذلك صدري ضيقا شديدا حتى جاوز الحد فأمرت غلامي بأن يسرج لي حمارا كان عندي لأمضي إلى الصحراء أتفرج فيها مما دخل على قلبي فأسرجه وركبت برداء ونعل فأفضى بي المسير وأنا مفكر لا أميز الطريق التي أسلك فيها حتى هجم بي على باب يحيى بن خالد فتواثب غلمانه إلي وقالوا أين هذا الطريق فقلت إلى الوزير فدخلوا فاستأذنوا لي وخرج الحاجب فأمرني بالدخول وبقيت خجلا قد وقعت في أمرين فاضحين إن دخلت إليه برداء ونعل وأعلمته أني قصدته في تلك الحال كان سوء أدب وإن قلت له كنت مجتازا ولم أقصدك فجعلتك\nطريقا كان قبيحا ثم عزمت فدخلت فلما رآني تبسم وقال ما هذا الزي يا أبا محمد احتبسنا لك بالبر والفصد والتفقد ثم علمنا أنك جعلتنا طريقا فقلت لا والله يا سيدي ولكني أصدقك قال هات فأخبرته القصة من أولها إلى آخرها فقال هذا حق مستو أفهذا شغل قلبك قلت أي والله وزاد فقال لا تشغل قلبك بهذا يا غلام ردوا حماره وهاتوا له خلعة فجاؤوني بخلعة تامة من ثيابه فلبستها ودعا بالطعام فأكلت ووضع النبيذ فشربت وشرب فغنيته ودعا في وسط ذلك بدواة ورقعة وكتب أربع رقاع ظننت بعضها توقيعا لي بجائزة فإذا هو قد دعا بعض وكلائه فدفع إليه الرقاع وساره بشيء فزاد طمعي في الجائزة ومضى الرجل وجلسنا نشرب وأنا أنتظر شيئا فلا أراه إلى العتمة ثم اتكأ يحيى فنام فقمت وأنا منكسر خائب فخرجت وقدم لي حماري فلما تجاوزت الدار قال لي غلامي إلى أين تمضي قلت إلى البيت قال قد والله بيعت دارك وأشهد على صاحبها وابتيع الدرب كله ووزن ثمنه والمشتري جالس على بابك ينتظرك ليعرفك وأظنه اشترى ذلك للسلطان لأني رأيت الأمر في استعجاله واستحثاثه أمرا سلطانيا فوقعت من ذلك فيما لم يكن في حسابي وجئت وأنا لا أدري ما أعمل فلما نزلت على باب داري إذ أنا بالوكيل الذي ساره يحيى قد قام إلي فقال لي ادخل أيدك الله دارك حتى أدخل إلى مخاطبتك في أمر أحتاج إليك فيه فطابت نفسي بذلك ودخلت ودخل إلي فأقرأني توقيع يحيى يطلق لأبي محمد إسحاق مائة ألف درهم يبتاع له بها داره وجميع ما يجاورها ويلاصقها والتوقيع الثاني إلى ابنه الفضل قد أمرت لأبي محمد إسحاق بمائة ألف درهم يبتاع له بها داره فأطلق إليه مثلها لينفقها على إصلاح الدار كما يريد وبنائها على ما يشتهي والتوقيع الثالث إلى جعفر قد أمرت لأبي محمد إسحاق بمائة ألف درهم يبتاع له بها منزل يسكنه وأمر له أخوك بدفع مائة ألف درهم ينفقها على بنائها ومرمتها على ما يريد فأطلق له أنت مائة ألف درهم يبتاع بها فرشا لمنزله","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":52,"spl":"إسحاق يحاور علويه في مجلس الفضل بن الربيع"},
{"id":"b52-83","bab":"الجزء 5","sec":"إسحاق يحاور علويه في مجلس الفضل بن الربيع","page":"ج5 ص317","text":"والتوقيع الرابع إلى محمد قد أمرت لأبي محمد إسحاق أنا وأخواك بثلاثمائة ألف درهم لمنزل يبتاعه ونفقة ينفقها عليه وفرش يبتذله فمر له أنت بمائة ألف درهم يصرفها في سائر نفقته وقال الوكيل قد حملت المال واشتريت كل شيء جاورك بسبعين ألف درهم وهذه كتب الابتياعات باسمي والإقرار لك وهذا المال بورك لك فيه فاقبضه فقبضته وأصبحت أحسن حالا من أبي في منزلي وفرشي وآلتي ولا والله ما هذا بأكبر شيء فعلوه لي أفألام على شكر هؤلاء فبكى الفضل بن الربيع وكل من حضر وقالوا لا والله لا تلام على شكر هؤلاء ثم قال الفضل بحياتي غن","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":53,"spl":"إسحاق يحاور علويه في مجلس الفضل بن الربيع — الصوت"},
{"id":"b52-84","bab":"الجزء 5","sec":"الصوت","page":"ج5 ص321","text":"ولا تبخل على أبي الحسن بأن تقومه له فقال أفعل وغناه فتبين علويه أنه كما قال فقام فقبل رأسه وقال أنت أستاذنا وابن أستاذنا وأولى بتقويمنا واحتمالنا من كل أحد ورده إسحاق مرات حتى استوى لعلويه\nولقد روي في هذا الخبر بعينه أن هذه القصة كانت عند علي بن هشام وقد أخبرني بهذا الخبر أحمد بن جعفر جحظة قال حدثني ميمون بن هارون وأبو عبد الله الهاشمي قالا\nدعا علي بن هشام إسحاق الموصلي وسأله أن يصطبح عنده ويبكر فأجابه فلما كان الغد وافاه ظهرا وعنده مخارق وعلويه فقال له علي بن هشام أين كنت الساعة يا أبا محمد قال عاقني أمر لم أجد من القيام به بدا فدعا له بطعام فأصاب منه ثم قعدوا على نبيذهم وتغنى علويه صوتا الشعر فيه لابن ياسين وهو\nالصوت\n(إلهي منحت الود مني بخيلة ... وأنت على تغيير ذاك قدير)\n(شفاء الهوى بث الهوى واشتكاؤه ... وإن امرأ أخفى الهوى لصبور)\nلغناء لسليمان أخي أحيحة خفيف ثقيل أول بالبنصر عن عمرو فقال له إسحاق أخطأت ويلك فوضع علويه العود وشرب رطلا وشرب علي بن هشام ثم تناول العود وغنى صوت\n(ولقد أسمو إلى غرف ... في طريق موحش جدده)\n(حوله الأحراس تحرسه ... ولديه جاثما أسده)\nالغناء لمعبد ثقيل أول بالوسطى عن عمرو فقال له إسحاق أخطأت ويلك فوضع العود من يده ثم أقبل على إسحاق فقال له دعاك الأمير أعزه الله لتبكر إليه فجئته ظهرا وغنيت صوتين يشتهيهما الأمير أعزه الله علي فخطأتني فيهما وزعمت أنك لا تغني بين يدي الأمير أعزه الله ولا تغني إلا بين يدي خليفة أو ولي عهد ولو دعاك بعض البرامكة لكنت تسرع إليه ثم تغني منذ غدوة إلى الليل فقال إسحاق إني والله ما أردت انتقاصا منك ولا أقول مثله لغيرك ولا أريد ازدراء من أحد ولكني أردت بك خاصة التقويم والتأديب فإن ساءك ذلك تركتك في خطئك ثم أقبل على علي بن هشام فقال له أعزك الله إني أحدثك عن البرامكة بما يقيم عذري فيما ذكره دخلت على يحيى بن خالد يوما ولم أكن أردت الدخول عليه وإنما ركبت متبذلا لهم أهمني وكنت نازلا مع أبي في داره فضقت صدرا بذلك وأحببت النقلة عنه ونظرت فإذا يدي تقصر عما يصلحني ثم ذكر الخبر نحوا مما قلته وزاد فيه أنه دخل إلى يحيى بن خالد وهو مصطبح فلما رآه نعر وصفق وأنه وقع له بمائتي ألف درهم\nووقع له كل من جعفر والفضل بمائة وخمسين ألفا وكل واحد من موسى ومحمد بمائة ألف مائة ألف وقال فيه فبكى علي بن هشام ومن حضر وقالوا لا يرى والله مثل هؤلاء أبدا وأخذ إسحاق العود فغنى الصوتين فأتى فيهما بالعجائب فقام علويه فقبل رأسه وقال له أنت أستاذنا وابن أستاذنا وما بنا عن تقويمك غنى ثم غنى بعد ذلك لحنه تشكى الكميت الجري ولم يزل يغني بقية يومه كلما شرب علي بن هشام ثم انصرف فأتبعه علي ابن هشام بجائزة سنية","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":53,"spl":"إسحاق يحاور علويه في مجلس الفضل بن الربيع — الصوت"},
{"id":"b52-85","bab":"الجزء 5","sec":"عبد الله بن العباس الربيعي يشهد له بتفوقه في الصنعة","page":"ج5 ص323","text":"حدثني الصولي قال حدثنا عون بن محمد قال حدثني عبد الله بن العباس الربيعي قال\nأحضرني إسحاق بن إبراهيم بن مصعب فلما جلست وأطمأننت أخرج إلي خادمه رقعة فقال اقرأ ما فيها واعمل بما رسمه الأمير أعزه الله فقرأتها فإذا فيها قوله\nصوت\n(يرتاح للدجن قلبي وهو مقتسم ... بين الهموم ارتياح الأرض للمطر)\n(إني جعلت لهذا الدجن نحلته ... ألا يزول ولي في اللهو من وطر)\nتحت هذين البيتين تقدم جعلت فداك إلى من بحضرتك من المغنين بأن يغنوا في هذين البيتين وألق جميع ما يصنعونه على فلانة فإذا أخذته فأنفذها إلي مع رسولي فقلت السمع والطاعة لأمر الأمير أعزه الله\nفهل صنع فيهما أحد قبلي فقال نعم إسحاق الموصلي فقلت والله لو كلف إبليس أن يصنع فيهما صنعة يفضل إسحاق فيها بل يساويه بل يقاربه ما قدر على ذلك ولا بلغ مبلغه فضحك حتى استلقى وقال صدقت والله وهكذا يقول من يعقل لا كما يقول هؤلاء الحمقى ولكن اصنع فيهما على كل حال كما أمر فقلت أفعل وقد برئت من العهدة فانصرفت فصنعت فيهما صنعة كانت والله عند صنعة إسحاق بمنزلة غناء القرادين حدثني جحظة قال حدثني ميمون قال حدثني إسحاق الموصلي قال قال لي المعتصم أو قال لي الواثق لقد ضحك الشيب في عارضيك فقلت نعم يا سيدي وبكيت ثم قلت أبياتا في الوقت وغنيت فيها\n(تولى شبابك إلا قليلا ... وحل المشيب فصبرا جميلا)\n(كفى حزنا بفراق الصبا ... وإن أصبح الشيب منه بديلا)\n(ولما رأى الغانيات المشيب ... أغضين دونك طرفا كليلا)\n(سأندب عهدا مضى للصبا ... وأبكي الشباب بكاء طويلا)\nبكى الواثق وحزن وقال والله لو قدرت على رد شبابك لفعلت بشطر ملكي فلم يكن لكلامه عندي جواب إلا تقبيل البساط بين يديه أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق قال حدثني حمدون ابن إسماعيل قال لما صنع أبوك لحنه في\n(قف بالديار التي عفا القدم ... وغيرتها الأرواح والديم)\nأيتهم يعني المغنين يأخذونه عنه ويجهدون فيه فتوفي والله وما أخذوا منه إلا رسمه","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":54,"spl":"عبد الله بن العباس الربيعي يشهد له بتفوقه في الصنعة — نسبة هذا الصوت"},
{"id":"b52-86","bab":"الجزء 5","sec":"نسبة هذا الصوت","page":"ج5 ص325","text":"صوت\n(قف بالديار التي عفا القدم ... وغيرتها الأرواح والديم)\n(لما وقفتا بها نسائلها ... فاضت من القوم أعين سجم)\n(ذكرا لعيش إذا ذكروا ... ما فات منه فإنه سقم)\n(وكل عيش دامت غضارته ... منقطع مرة ومنصرم)\nلشعر والغناء لإسحاق ثقيل أول بالوسطى من جميع أغانيه حدثني أبو أيوب المديني قال حدثني هارون اليتيم قال حدثني عجيف ابن عنبسة قال كنت عند أمير المؤمنين المعتصم وعنده إسحاق الموصلي فغناه\n(قل لمن صد عاتبا ... ونأى عنك جانبا)\nأمره بإعادته فأعاده ثلاثا وشرب عليه ثلاثا فقال له إبراهيم بن المهدي قد استحسنت هذا الصوت يا أمير المؤمنين أفنأخذه قال نعم خذوه فقد أعجبني فاجتمع جماعة المغنين مخارق وعلويه وعمرو ابن بانة وغيرهم فأمره المعتصم أن يلقيه عليهم حتى يأخذوه فقال عجيف فعددت خمسين مرة قد أعاده فيها عليهم وهم يظنون أنهم قد أخذوه ولم يكونوا أخذوه قال هارون فنحن في هذا الحديث إذ دخل علينا محمد ابن الحارث بن بسخنر فقال له عجيف يا أبا جعفر كنت أحدث أبا موسى بحديثنا البارحة مع إسحاق في الصوت وأني عددت خمسين مرة فقال محمد إي والله أصلحك الله ولقد عددت أنا أكثر من سبعين مرة وما في القوم أحد إلا وهو يظن أنه قد أخذه والله ما أخذه أحد منهم وأنا أولهم ما قدرت علم الله على أخذه على الصحة وأنا أسرعهم أخذا فلا\nأدري ألكثرة زوائده فيه أم لشدة صعوبته ومن يقدر أن يأخذ من ذلك الشيطان شيئا أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق قال حدثني عجيف بن عنبسة بهذا الخبر فذكر مثله سواء قال أبو أيوب وحدثني حماد عن أبيه قال كنت يوما عند المعتصم فمر شعر على هذا الوزن فقال وددت أنه على غير ما هو فقلت له أنا لك به على هذا الوزن في أحسن من هذا الشعر صوت\n(قل لمن صد عاتبا ... ونأى عنك جانبا)\n(قد بلغت الذي أردت ... وإن كنت لاعبا)\nفأعجبه وقال لي قد والله أحسنت وأمر لي بألفي دينار ووالله ما كانت قيمتهما عندي دانقين الشعر والغناء في هذين البيتين لإسحاق ثاني ثقيل بالسبابة في مجرى الوسطى","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":54,"spl":"عبد الله بن العباس الربيعي يشهد له بتفوقه في الصنعة — نسبة هذا الصوت"},
{"id":"b52-87","bab":"الجزء 5","sec":"الأمين يغضب عليه فيتشفع إليه بالفضل","page":"ج5 ص326","text":"أخبرني يحيى بن علي قال حدثني أبو أيوب المديني قال حدثني ابن المكي عن إسحاق قال غضب علي المخلوع فأقصاني وجفاني فاشتد ذلك علي قال\nوجفاني وهو يومئذ بالأنبار فحملت عليه بالفضل بن الربيع فطلب إليه فشفعه المخلوع ودعاني وهو مصطبح فلم أزل متوقفا وقد لبست قباء وخفا أحمر واعتصبت بعصابة صفراء وشددت وسطي بشقة حمراء من حرير فلما أخذوا في الأهزاج دخلت وفي يدي صفاقتان وأنا أتغنى صوت\n(اسمع لصوت طريب ... من صنعة الأنباري)\n(صوت مليح خفيف ... يطير في الأوتار)\nلشعر والغناء لإسحاق هزج بالبنصر فسر بذلك محمد وكان صوتهم في يومهم ذلك وأمر لي بثلثمائة ألف درهم وأخبرني جحظة بهذا الخبر عن محمد بن أحمد بن يحيى المكي قال حدثني أبي أن إسحاق حدثه بهذا الخبر وذكر مثل ما ذكره يحيى وزاد فيه قال وكان سبب تسمية محمد لي ب الأنباري أني دخلت عليه يوما وقد لثت عمامتي على رأسي لوثا غير مستحسن فقال لي يا إسحاق كأن عمامتك من عمائم أهل الأنبار أخبرنا محمد بن العباس اليزيدي قال حدثني عمي الفضل عن إسحاق وأخبرني علي بن سليمان الأخفش قال حدثني عمي الفضل عن إسحاق وأخبرنا يحيى بن علي بن يحيى قال حدثني أبي قال إسحاق قلت في ليلة من الليالي\nصوت\n(هل إلى نظرة إليك سبيل ... يرو منها الصدى ويشفى الغليل)\n(إن ما قل منك يكثر عندي ... وكثير ممن تحب القليل)\nال فلما أصبحت أنشدتهما الأصمعي فقال هذا الديباج الخسرواني هذا الوشي الإسكندراني لمن هذا فقلت له إنه ابن ليلته فتبينت الحسد في وجهه وقال أفسدته أفسدته أما إن التوليد فيه لبين في هذين البيتين لإسحاق خفيف ثقيل بالبنصر أخبرني جعفر بن قدامة قال حدثني علي بن يحيى قال حدثني إسحاق بهذا الخبر فذكر مثل ما ذكره من قدمت الرواية عنه وزاد فيه فقال لي علي بن يحيى بعقب هذا الخبر كان إسحاق يعجب بهذا المعنى ويكرره في شعره ويرى أنه ما سبق إليه فمن ذلك قوله صوت\n(أيها الظبي الغرير ... هل لنا منك مجير)\n(إن ما نولتني منك ... وإن قل كثير)\nحن إسحاق خفيف ثقيل بالوسطى فقلت إنك قد سبقت إلى هذا المعنى فقال ما علمت أن أحدا سبقني إليه فأنشدته لأعرابي من بني عقيل\n(قفي ودعينا يا مليح بنظرة ... فقد حان منا يا مليح رحيل)\n(أليس قليلا نظرة إن نظرتها ... إليك وكلا ليس منك قليل)\n(عقيلية أما ملاث إزارها ... فوعث وأما خصرها فضئيل)\nوت\n(أيا جنة الدنيا ويا غاية المنى ... ويا سؤل نفسي هل إليك سبيل)\n(أراجعة نفسي إلي فأغتدي ... مع الركب لم يقتل عليك قتيل)\n(فما كل يوم لي بأرضك حاجة ... ولا كل يوم لي إليك رسول)\nال فحلف أنه ما سمع بذلك قط قال علي بن يحيى وصدق ما سمع بها الغناء في الأبيات الأخيرة من أبيات العقيلي","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":55,"spl":"الأمين يغضب عليه فيتشفع إليه بالفضل — إبراهيم بن المهدي يعاتب إسحاق"},
{"id":"b52-88","bab":"الجزء 5","sec":"إبراهيم بن المهدي يعاتب إسحاق","page":"ج5 ص329","text":"حدثني الحرمي بن أبي العلاء قال حدثنا الحسين بن محمد بن أبي طالب الديناري بمكة قال حدثني إسحاق بن إبراهيم الموصلي قال عاتبني إبراهيم بن المهدي في ترك المجيء إليه فقال لي من جمع لك مع المودة الصادقة رأيا حازما فاجمع له مع المحبة الخالصة طاعة لازمة فقلت له جعلني الله فداك إذا ثبتت الأصول في القلوب نطقت الألسن بالفروع والله يعلم أن قلبي لك شاكر ولساني بالثناء عليك ناثر وما يظهر الود المستقيم إلا من القلب السليم قال فأبرئ ساحتك عندي بكثرة مجيئك إلي فقلت أجعل مجيئي إليك في الليل والنهار نوبا أتيقظ لها كتيقظي للصلوات الخمس وأكون بعد ذلك مقصرا فضحك وقال من يقدر على جواب المغنين فقلت من اتخذ الغناء لنفسه ولم يتخذه لغيره فضحك أيضا وأمر لي بخلع ودنانير وبرذون وخادم وبلغ الخبر المعتصم فضاعف لإبراهيم ما أعطاني فرحت وقد ربحت وأربحت\nحدثنا الحرمي قال حدثنا الديناري قال حدثني إسحاق قال عتب علي الفضل بن الربيع في شيء بلغه عني فكتبت إليه إن لكل ذنب عفوا وعقوبة فذنوب الخاصة عندك مستورة مغفورة فأما مثلي من العامة فذنبه لا يغفر وكسره لا يجبر فإن كنت لا بد معاقبي فإعراض لا يؤدي إلى مقت حدثني الحرمي قال حدثنا الديناري قال حدثني إسحاق قال كان يختلف إلي رجل من الأعراب وكان الفضل بن الربيع يقربه ويستظرف كلامه وكان عندي يوما وجاء رسول الفضل يطلبه فمضى إليه فقال له الفضل فيم كنتم قال كنا في قدر تفور وكأس تدور وغناء يصور وحديث لا يحور","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":55,"spl":"الأمين يغضب عليه فيتشفع إليه بالفضل — إبراهيم بن المهدي يعاتب إسحاق"},
{"id":"b52-89","bab":"الجزء 5","sec":"إسحاق يقول الشعر على ألسن الأعراب","page":"ج5 ص330","text":"حدثنا الحرمي قال حدثنا الحسين بن طالب قال كان إسحاق يقول الشعر على ألسن الأعراب وينشده للأعراب وكان يعايي بذلك أصحابه ويغرب عليهم به فمن ذلك ما أنشدنيه لأعرابي\n(لفظ الخدور عليك حورا عينا ... أنسين ما جمع الكناس قطينا)\n(فإذا بسمن فعن كمثل غمامة ... أو أقحوان الرمل بات معينا)\n(وأصح من رأت العيون محاجرا ... ولهن أمرض ما رأيت عيونا)\n(وكأنما تلك الوجوه أهلة ... أقمرن بين العشر والعشرينا)\n(وكأنهن إذا نهضن لحاجة ... ينهضن بالعقدات من يبرينا)\nقال وأنشدني أيضا مما كان ينسبه إلى الأعراب وهو له\n(ومكحولة العينين من غير ما كحل ... مهفهفة الكشحين ذات شوى خدل)\n(منعمة الأطراف مفعمة البرى ... روادفها تحكي الدهاس من الرمل)\n(صيود لألباب الرجال متى رنت ... إلى ذي نهى جلد القوى وافر العقل)\n(تخلى النهى عنه وحالفه الصبا ... وأسلمه الرأي الأصيل إلى الجهل)\n(شبيبة كثبان يروقك تحتها ... عناقيد كرم جادها غدق الوبل)\n(رمتني فحلت نائطي ولم تصب ... لها نائطي قلب ولا مقتلا نبلي)\nدثني علي بن سليمان الأخفش قال حدثنا محمد بن يزيد المبرد قال حدثت عن الأصمعي قال دخلت أنا وإسحاق الموصلي يوما على الرشيد فرأيناه لقس النفس فأنشده إسحاق يقول صوت\n(وآمرة بالبخل قلت لها اقصري ... فذلك شيء ما إليه سبيل)\n(أرى الناس خلان الكرام ولا أرى ... بخيلا له حتى الممات خليل)\n(وإني رأيت البخل يزري بأهله ... فأكرمت نفسي أن يقال بخيل)\n(ومن خير حالات الفتى لو علمته ... إذا نال خيرا أن يكون ينيل)\n(فعالي فعال المكثرين تجملا ... ومالي كما قد تعلمين قليل)\n(وكيف أخاف الفقر أو أحرم الغنى ... ورأي أمير المؤمنين جميل)\nال فقال الرشيد لا تخف إن شاء الله ثم قال لله در أبيات تأتينا بها ما أشد أصولها وأحسن فصولها وأقل فضولها وأمر له بخمسين ألف درهم فقال له إسحاق وصفك والله يا أمير المؤمنين لشعري أحسن منه فعلام آخذ الجائزة فضحك الرشيد وقال اجعلوها لهذا القول مائة ألف درهم قال الأصمعي فعلمت يومئذ أن إسحاق أحذق بصيد الدراهم مني وأخبرني بهذا الخبر جعفر بن قدامة عن حماد عن أبيه وأخبرنا به يحيى بن علي عن أبيه عن إسحاق فذكر معنى الخبر قريبا مما ذكره الأصمعي والألفاظ تختلف أخبرنا إسماعيل بن يونس قال حدثنا عمر بن شبة عن إسحاق وأخبرني به جعفر بن قدامة ووكيع عن حماد عن أبيه قال كنت عند الفضل بن الربيع يوما فدخل إليه ابن ابنه عبد الله بن العباس بن الفضل وهو طفل وكان يرق عليه لأن أباه مات في حياته فأجلسه في حجره وضمه إليه ودمعت عيناه فأنشأت أقول صوت\n(مد لك الله الحياة مدا ... حتى يكون ابنك هذا جدا)\n(مؤزرا بمجده مردى ... ثم يفدى مثل ما تفدى)\n(أشبه منك سنة وخدا ... وشيما مرضية ومجدا)\n(كأنه أنت إذا تبدى ... شمائلا محمودة وقدا)\nال فتبسم الفضل وقال أمتعني الله بك يا أبا محمد فقد عوضت من الحزن سرورا وتسليت بقولك وكذلك يكون إن شاء الله قال جعفر بن قدامة وحدثني بهذا الحديث علي بن يحيى فذكر أن إسحاق قال هذه الأبيات للفضل بن يحيى وقد دخل عليه وفي حجره ابن له غنى في هذه الأبيات أبو عيسى بن المتوكل لحنا من الرمل يقال إنه صنعه وقد ولد للمعتمد ولد ثم غنى به وأخبرني ذكاء وجه الرزة عن بدعة الكبيرة أن الرمل لعريب وأن لحن أبي عيسى خفيف رمل حدثني عمي قال حدثني الفضل بن محمد اليزيدي عن إسحاق قال أتيت الفضل بن الربيع يوما عائدا وجاءه بنو هاشم يعودونه فقلت في مجلسي ذلك\n(إذا ما أبو العباس عيد ولم يعد ... رأيت معودا أكرم الناس عائدا)\n(وجاء بنو العباس يبتدرونه ... مراضا لما يشكوه مثنى وواحدا)\n(يفدونه عند السلام وكلهم ... مجل له يدعوه عما ووالدا)\nال وكان الفضل مضطجعا فأمر خادما له فأجلسه ثم قال لي أعد يا أبا محمد فأعدت فأمرني فكتبتها وسر بها وجعل يرددها حتى حفظها","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":56,"spl":"إسحاق يقول الشعر على ألسن الأعراب"},
{"id":"b52-90","bab":"الجزء 5","sec":"إسحاق يسترضي الفضل بن الربيع بشعر","page":"ج5 ص334","text":"أخبرني يحيى بن علي بن يحيى قال أخبرني أبي قال قال إسحاق وأخبرني الحسن بن علي الخفاف قال حدثنا عبد الله بن أبي سعد قال حدثنا محمد بن عبد الله بن مالك عن إسحاق قال جاءني الزبير بن دحمان يوما مسلما فاحتبسته فقال لي أمرني الفضل بن الربيع بالمسير إليه فقلت له\n(أقم يا أبا العوام ويحك نشرب ... ونله مع اللاهين يوما ونطرب)\n(إذا ما رأيت اليوم قد جاء خيره ... فخذه بشكر واترك الفضل يغضب)\nأقام عندي وسررنا يومنا ثم صار إلى الفضل فسأله عن سبب تأخره عنه فحدثه الحديث وأنشده البيتين فغضب وحول وجهه عني وأمر عونا حاجبه بألا يدخلني إليه ولا يستأذن لي عليه ولا يوصل لي رقعة فقلت\n(حرام علي الكأس ما دمت غضبانا ... وما لم يعد عني رضاك كما كانا)\n(فأحسن فإني قد أسأت ولم تزل ... تعودني عند الإساءة إحسانا)\nال وأنشدته إياهما فضحك ورضي عني وعاد إلى ما كان عليه وقد أخبرني بهذا الخبر محمد بن مزيد والحسين بن يحيى عن حماد عن أبيه فذكر مثله وزاد فيه فقلت في عون حاجبه\n(عون يا عون ليس مثلك عون ... أنت لي عدة إذا كان كون)\n(لك عندي والله إن رضي الفضل ... غلام يرضيك أو برذون)\nال فأتى عون الفضل بالشعرين جميعا فقرأهما وضحك وقال ويحك إنما عرض لك بقوله غلام يرضيك بالسوءة قال قد وعدني ما سمعت فإن شئت أن تحرمنيه فأنت أعلم فأمره أن يرسل إلي فأتاني رسوله فصرت إليه فرضي عني\nأخبرني جحظة قال حدثني محمد بن أحمد بن يحيى المكي المرتجل قال حدثني أبي قال حدثني الزبير بن دحمان قال دخلت يوما على الفضل بن الربيع مسلما فقال لي قد عزمت غدا على الصبوح فصر إلي بكرة فكنت أنا والصبح كفرسي رهان فلما أصبحت في غد جعلت طريقي على إسحاق بن إبراهيم فدخلت إليه فلما جلست قال لي أقم اليوم عندي فعرفته خبري فقال\n(أقم يا أبا العوام ويحك نشرب ... ونله مع اللاهين يوما ونطرب)\n(إذا ما رأيت اليوم قد جاء خيره ... فخذه بشكر واترك الفضل يغضب)\nفقلت إني لا آمن غضبه وأنا بين يديك فقال لي أنت تعلم أن صبوح الفضل أبدا في وقت غبوق الناس فأقم وارفق بنفسك ثم امض إليه فأجبته إلى ذلك فلما شربنا طاب لي الموضع فأقمت حتى سكرت وذكر باقي الخبر نحوا مما ذكر إسحاق انتهى حدثني جحظة قال حدثني محمد بن المكي المرتجل قال قلت لزرزور الكبير كيف كان إسحاق ينفق على الخلفاء معكم وأنت وإبراهيم ابن المهدي ومخارق أطيب أصواتا وأحسن نغمة قال كنا والله يا بني نحضر معه فنجتهد في الغناء ونقيم الوهج فيه ويقبل علينا الخلفاء حتى نطمع فيه ونظن أنا قد غلبناه فإذا غنى عمل في غنائه أشياء من مداراته وحذقه ولطفه حتى يسقطنا كلنا ويقبل عليه الخليفة دوننا ويجيزه دوننا ويصغي إليه ونرى أنفسنا اضطرارا دونه","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":57,"spl":"إسحاق يسترضي الفضل بن الربيع بشعر"},
{"id":"b52-91","bab":"الجزء 5","sec":"إسحاق أول من أحدث التخنيث في الغناء","page":"ج5 ص336","text":"حدثنا جحظة قال حدثني محمد بن أحمد المكي قال حدثني أبي قال كان المغنون يجتمعون مع إسحاق وكلهم أحسن صوتا منه ولم يكن فيه عيب إلا صوته فيطمعون فيه فلا يزال بلطفه وحذقه ومعرفته حتى يغلبهم ويبذهم جميعا ويفضلهم ويتقدمهم قال وهو أول من أحدث التخنيث ليوافق صوته ويشاكله فجاء معه عجبا من العجب وكان في حلقة نبو عن الوتر اخبرني يحيى بن علي قال أخبرنا أبو العبيس بن حمدون أن إسحاق أول من جاء بالتخنيث في الغناء ولم يكن يعرف وإنما احتال بحذقه لمنافرة حلقه الوتر حتى صار يجيبه ببعض التخنيث فيكون أحسن له في السمع أخبرنا جحظة قال حدثني الهشامي عن أبيه قال كان المغنون إذا حضروا وليس إسحاق معهم غنوا هوينى وهم غير مفكرين فإذا حضر إسحاق لم يكن إلا الجد أخبرني الحرمي بن أبي العلاء قال حدثني إسحاق الموصلي قال قال لي أبي وقد انصرف من دار الرشيد رأيت الأمير جعفر بن يحيى يستبطئك ويقول لست أراه ولا يغشاني فقلت إني لآتيه كثيرا فأحجب عنه ويصرفني نافذ حاجبه ويقول هو على شغل قال فبلعه أبي ذلك فقال له قل له أنكه أمه إذا فعل فأقمت أياما ثم كتبت إليه\n(جعلت فداءك من كل سوء ... إلى حسن رأيك أشكو أناسا)\n(يحولون بيني وبين السلام ... فلست أسلم إلا اختلاسا)\n(وأنفذت أمرك في نافذ ... فما زاده ذاك إلا شماسا)\nوقد أخبرني الخبر محمد بن مزيد عن حماد عن أبيه فذكر مثله وقال كان خادم يحجبه يقال له نافذ فقال إذا حجبك فنكه فلما كتبت إليه بهذه الأبيات بعث فأحضرني فلما دخلت إليه أحضر نافذا وقرأ الأبيات عليه وقال لي أفعلتها يا عدو الله فغضب نافذ حتى كاد يبكي وجعل جعفر يضحك ويصفق ثم ما عاد بعد ذلك يتعرض لي حدثني الحسين بن أبي طالب قال حدثني عبيد الله بن المأمون وأخبرنا اليزيدي عن عمه عبيد الله عن أبيه قال غضب المأمون على إسحاق بن إبراهيم ثم كلم فيه فرضي عنه ودعا به فلما وقف بين يديه اعتذر وقبل الأرض بين يديه واستقاله فأجابه المأمون جوابا جميلا ثم قال له في أثناء كلامه\n(فلا أنت أعتبت من زلة ... ولا أنت بالغت في المعذره)\n(ولا أنت وليتني أمرها ... فأغفر ذنبك عن مقدره)\nكذا في الخبر وأظنه إسحاق بن إبراهيم الطاهري لا الموصلي أخبرنا الحرمي بن أبي العلاء قال حدثنا الحسين بن أبي طالب قال حدثني إسحاق قال أنشدت أبا الأشعث الأعرابي شعرا لي فقال والذي أصوم له مخافته ورجاءه إنك لمن طراز ما رأيت بالعراق شيئا منه ولو كان شباب يشترى لأشتريته لك ولو بإحدى يدي وإن في كبرك لما زان الجليس وسره أخبرنا الحرمي قال حدثنا الديناري قال حدثنا إسحاق قال قالت لي زهراء الكلابية ما فعل عبد الله بن خرداذبه فقلت مات فقالت\nغير ذميم ولا لئيم غفر الله لصداه لقد كان يحبك ويعجبه ما سرك قال فقلت لزهراء حدثيني عن قول الشاعر\n(أحبك أن أخبرت أنك فارك ... لزوجك إني مولع بالفوارك)\nما أعجبه من بغضها لزوجها فقالت عرفته أن في نفسها فضلة من جمال وشمخا بأنفها وأبهة فأعجبته","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":58,"spl":"إسحاق أول من أحدث التخنيث في الغناء"},
{"id":"b52-92","bab":"الجزء 5","sec":"إسحاق يغني المعتصم","page":"ج5 ص338","text":"...\nأخبرني علي بن سليمان الأخفش قال حدثنا محمد بن يزيد المبرد قال حدثت عن غير واحد\nأن إسحاق الموصلي دخل على المعتصم يوما من الأيام فرآه لقس النفس فقال له أما ترى يا أمير المؤمنين طيب هذا اليوم وحسنه فقال المعتصم ما يدعوني حسنه إلى شيء مما تريد ولا أنشط له فقال يا أمير المؤمنين إنه يوم أكل وشرب فاشرب حتى أنشطك قال أو تفعل قال نعم قال يا غلمان قدموا الطعام والشراب ومدوا الستارة وأحضروا الندماء والمغنين فأتي بالطعام فأكل و بالشراب فشرب وحضر الندماء والمغنون فغناه إسحاق\nصوت\n(سقيت الغيث يا قصر السلام ... فنعم محله الملك الهمام)\n(لقد نشر الإله عليك نورا ... وخصك بالسلامة والسلام)\nلشعر والغناء لإبراهيم الموصلي رمل بالسبابة في مجرى البنصر عن إسحاق وذكر حبش أن فيه للزبير بن دحمان لحنا من الرمل بالوسطى قال فطرب المعتصم وشرب شربا كثيرا ولم يبق أحد بحضرته إلا وصله وخلع عليه وحمله وفضل إسحاق في ذلك أجمع أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثنا ابن أبي سعد قال حدثنا علي بن الصباح عن إسحاق قال أول جائزة أخذتها من الرشيد ألف دينار في أول يوم دخلت إليه فغنيته\n(علق القلب بزوعا ... )\nاستحسنه واستعاده ثلاث مرات وشرب عليه ثلاثة أرطال وأمر لي بألف دينار فكان أول جائزة أجازنيها أخبرني جعفر بن قدامة قال حدثني حماد بن إسحاق قال كان أبي ذات يوم عند إسحاق بن إبراهيم بن مصعب فلما جلسوا للشراب جعل الغلمان يسقون من حضر وجاء غلام قبيح الوجه إلى أبي بقدح نبيذ فلم يأخذه ورآه إسحاق فقال له لم لا تشرب فكتب إليه أبي\n(اصبح نديمك أقداحا يسلسلها ... من الشمول وأتبعها بأقداح)\n(من كف ريم مليح الدل ريقته ... بعد الهجوع كمسك أو كتفاح)\n(لا أشرب الراح إلا من يدي رشأ ... تقبيل راحته أشهى من الراح)\nضحك وقال صدقت والله ثم دعا بوصيفة كأنها صورة تامة الحسن لطيفة الخصر في زي غلام عليها أقبية ومنطقة فقال لها تولي سقي أبي محمد فما زالت تسقيه حتى سكر ثم أمر بتوجيهها وكل ما لها في داره إليه فحملت معه","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":59,"spl":"إسحاق يغني المعتصم — إسحاق وزهراء الكلابية","partial":1},
{"id":"b52-93","bab":"الجزء 5","sec":"إسحاق وزهراء الكلابية","page":"ج5 ص340","text":"أخبرني عمي قال حدثنا عبد الله بن أبي سعد قال حدثني علي بن الصباح قال كانت امرأة من بني كلاب يقال لها زهراء تحدث إسحاق وتناشده وكانت تميل إليه وتكني عنه في عشيرتها إذا ذكرته بجمل قال فحدثني إسحاق أنها كتبت إليه وقد غابت عنه تقول\n(وجدي بجمل على أني أجمجمه ... وجد السقيم ببرء بعد إدناف)\n(أو وجد ثكلى أصاب الموت واحدها ... أو وجد مغترب من بين ألاف)\nال فأجبتها\n(أقر السلام على الزهراء إذ شحطت ... وقل لها قد أذقت القلب ما خافا)\n(أما رثيت لمن خلفت مكتئبا ... يذري مدامعه سحا وتوكافا)\n(فما وجدت على إلف أفارقه ... وجدي عليك وقد فارقت ألافا)\nأخبرني عمي قال حدثني عبد الله بن أبي سعد قال حدثني محمد بن عبد الله بن مالك قال أنشدني إسحاق لنفسه\n(سقى الله يوم الماوشان ومجلسا ... به كان أحلى عندنا من جنى النحل)\n(غداة اجتنينا اللهو غضا ولم نبل ... حجاب أبي نصر ولا غضبة الفضل)\n(غدونا صحاحا ثم رحنا كأننا ... أطاف بنا شر شديد من الخبل)\nسألته أن يكتبها ففعل فقلت له ما حديث الماوشان فضحك وقال لو لم أكتبك الأبيات لما سألت عما لا يعنيك ولم يخبرني","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":59,"spl":"إسحاق يغني المعتصم — إسحاق وزهراء الكلابية"},
{"id":"b52-94","bab":"الجزء 5","sec":"ابن الأعرابي يعجب بإسحاق وبشعره","page":"ج5 ص341","text":"أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني أحمد بن الحارث وأبو مسلم عن ابن الأعرابي أنه كان يصف إسحاق الموصلي ويقرظه ويثني عليه ويذكر أدبه وحفظه وعلمه وصدقه ويستحسن قوله صوت\n(هل إلى أن تنام عيني سبيل ... إن عهدي بالنوم عهد طويل)\nذلك فقلت هذا ومائة بعده خير منه لهم فقال اصنع في شعر الأخطل\n(أعاذلتي اليوم ويحكما مهلا ... وكفا الأذى عني ولا تكثرا العذلا)\nصنعت فيه كما أمرني فلما سمعوا بذلك وما جاء بعده أذعنوا وزال عن قلب الرشيد ما كان ظنه بي وقد ذكر غير حماد أن اللحن الذي اختبره به الرشيد قوله\n(كنت صبا وقلبي اليوم سال ... عن حبيب يسيء في كل حال)\nذكر أن الفضل بن الربيع قال الشعر في ذلك الوقت ودفعه إليه وأمره الرشيد أن يصنع فيه ففعل وأخبرني بذلك محمد بن يحيى الصولي قال حدثني الحسين بن يحيى عن حماد بن إسحاق وأخبرني محمد بن مزيد قال حدثنا حماد قال أول ما سمعه الرشيد من غناء أبي\n(ألم تسأل فتخبرك المغاني ... وكيف وهن مذحجج ثماني)\n(برئت من المنازل غير شوق ... إلى الدار التي بلوى أبان)\n(ديار للتي لجلجت فيها ... ولو أعربت لج بها لساني)\n(فكاد يظل للعينين غرب ... بربعي دمنة لا ينطقان)\nقال فحدثني أبي أن المغنين قالوا للرشيد هذا من صنعة أبيه انتحله بعد وفاته فقلت له أنا أدع لهم هذا ومائة صوت بعده ثم نظروا إلى ما جاء بعد ذلك فأذعنوا","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":60,"spl":"ابن الأعرابي يعجب بإسحاق وبشعره — نسبة ما في هذه الأخبار من الغناء"},
{"id":"b52-95","bab":"الجزء 5","sec":"نسبة ما في هذه الأخبار من الغناء","page":"ج5 ص344","text":"صوت\n(قف نحي المغانيا ... والطلول البواليا)\n(وعلى أهلها فنح ... وابك إن كنت باكيا)\nلشعر لابن ياسين والغناء لإسحاق ثقيل أول بالوسطى صوت\n(أمن آل ليلى عرفت الطلولا ... بذي حرض مائلات مثولا)\n(بلين وتحسب آياتهن ... عن فرط حولين رقا محيلا)\nلشعر لكعب بن زهير والغناء لإسحاق ثاني ثقيل بالبنصر صوت\n(أعاذلتي اليوم ويحكما مهلا ... وكفا الأذى عني ولا تكثرا العذلا)\n(دعاني تجد كفي بمالي فإنني ... سأصبح لا أسطيع جودا ولا بخلا)\n(إذا وضعوا فوق الصفيح جنادلا ... علي وخلفت المطية والرحلا)\n(فلا أنا مجتاز إذا ما نزلته ... ولا أنا لاق ما ثويت به أهلا)\nلشعر للأخطل والغناء لإسحاق ثقيل أول بالوسطى صوت\n(إني لأكني بأجبال عن اجبلها ... وباسم أودية عن اسم واديها)\n(عمدا ليحسبها الواشون غانية ... أخرى وتحسب أني لا أباليها)\n(ولا يغير ودي أن أهاجرها ... ولا فراق نوى في الدار أنويها)\n(وللقلوص ولي منها إذا بعدت ... بوارح الشوق تنضيني وأنضيها)\nلشعر لأعرابي والغناء لإسحاق هزج بالبنصر حدثني جحظة قال حدثني أبو عبد الله أحمد بن حمدون قال قال إسحاق للواثق يوما الأهزاج من أملح الغناء فقال الواثق أما إذا كانت مثل صوتك\n(إني لأكني بأجبال عن اجبلها ... وباسم أودية عن اسم واديها)\nهي كذلك","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":60,"spl":"ابن الأعرابي يعجب بإسحاق وبشعره — نسبة ما في هذه الأخبار من الغناء"},
{"id":"b52-96","bab":"الجزء 5","sec":"إسحاق يغني لطلحة بن طاهر","page":"ج5 ص345","text":"قال أحمد بن أبي طاهر حدثني أحمد بن يحيى الرازي عن محمد ابن المثنى عن الحجاج بن قتيبة بن مسلم قال قال إسحاق بعث إلي طلحة بن طاهر وقد انصرف من وقعة للشراة وقد أصابته ضربة في وجهه فقال لي الغلام أجب فقلت وما\nيعمل قال يشرب فمضيت إليه فإذا هو جالس قد عصب ضربته وتقلنس بقلنسوة فقلت له سبحان الله أيها الأمير ما حملك على لبس هذا قال التبرم بغيره ثم قال غن\n(إني لأكني بأجبال عن اجبلها ... )\nال فغنيته إياه فقال أحسنت والله أعد فأعدت وهو يشرب حتى صلى العتمة وأنا أغنيه فأقبل على خادم له بالحضرة وقال له كم عندك قال مقدار سبعين ألف درهم قال تحمل معه فلما خرجت من عنده تبعني جماعة من الغلمان يسألونني فوزعت المال بينهم فرفع الخبر إليه فأغضبه ولم يوجه إلي ثلاثا فجلست ليلا وتناولت الدواة والقرطاس فقلت\n(علمني جودك السماح فما ... أبقيت شيئا لدي من صلتك)\n(لم أبق شيئا إلا سمحت به ... كأن لي قدرة كمقدرتك)\n(تتلف في اليوم بالهبات وفي الساعة ما تجتنيه في سنتك ... )\n(فلست أدري من أين تنفق لو ... لا أن ربي يجزي على صلتك)\nلما كان في اليوم الرابع بعث إلي فصرت إليه ودخلت عليه فسلمت فرفع بصره إلي وقال اسقوه رطلا فسقيته وأمر لي بآخر وآخر فشربت ثلاثا ثم قال لي غن\n(إني لأكني بأجبال عن اجبلها ... )\nغنيته ثم أتبعته بالأبيات التي قلتها وقد كنت غنيت فيها لحنا في طريقة الصوت فقال ادن فدنوت وقال اجلس فجلست فاستعاد الصوت الذي صنعته فأعدته فلما فهمه وعرف معنى الشعر قال لخادم له أحضرني فلانا فأحضره فقال كم قبلك من مال الضياع قال ثمانمائة\nألف درهم فقال احضر بها الساعة فجيء بثمانين بدرة فقال للخادم جئني بثمانين غلاما مملوكا فأحضروا فقال احملوا هذا المال ثم قال يا أبا محمد خذ المال والمماليك حتى لا تحتاج أن تعطي لأحد منهم شيئا","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":61,"spl":"إسحاق يغني لطلحة بن طاهر","partialRef":{"sid":"b52-95","gi":3,"vi":0,"side":0},"partial":1},
{"id":"b52-97","bab":"الجزء 5","sec":"إسحاق ومحمد بن راشد","page":"ج5 ص347","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الحسين بن محمد بن طالب قال كان إسحاق بن إبراهيم الموصلي كثير الغشيان لإسحاق بن إبراهيم بن مصعب والحضور لسمره وكان إسحاق بن إبراهيم يرى ذلك له ويسني جوائزه ويواتر صلاته ويشاوره في بعض أموره ويسمع منه فأصيب إسحاق ببصره قبل موته بسنتين فترك زيارة إسحاق وغيره ممن كان يغشاهم ولزم بيته وخرج إسحاق يوما إلى بستان له بباب قطربل وخرج معه ندماؤه وفيهم موسى بن صالح بن شيخ بن عميرة ومحمد بن راشد الخناق والحراني فجرى ذكر إسحاق الموصلي فتوجع له إسحاق وذكر أنسه به وتمنى حضوره وذكره القوم فأطنبوا في نشر محاسنه وشيعوا ما ذكره به\nإسحاق بما حسن موقعه لهم عنده وذكره محمد بن راشد ذكرا لم يحمده أصحابه عليه وزجره إسحاق فأمسك عنه فلما انصرفوا من مجلسهم نمي إلى إسحاق الموصلي ما كان فيه القوم في يومهم وما جرى من ذكره فكتب إلى موسى بن صالح\n(ألا قل لموسى الخير موسى بن صالح ... ومن هو دون الخلق إلفي وخلصاني)\n(ومن لو سألت الناس عنه لأجمعوا ... على أنه أفتى معد وقحطان)\n(لعمري لئن كان الأمير تمناني ... بمجلس لذات ونزهة بستان)\n(لقد زادني ما كان منه صبابة ... وجدد لي شوقا إليه وأبكاني)\n(وما زال ممتنا علي يخصني ... بما لست أحصي من أياد وإحسان)\n(هو السيد القرم الذي ما يرى له ... من الناس إن حصلته أبدا ثاني)\n(نمته روابي مصعب وبنى له ... كريم المساعي في أرومته باني)\n(يعز علي أن تفوزوا بقربه ... ولست إليه بالقريب ولا الداني)\n(فيا ليت شعري هل أروحن مرة ... إليه فيلقاني كما كان يلقاني)\n(وهل أرين يوما غضارة ملكه ... وسلطانه لا زال في عز سلطان)\n(وهل أسمعن ذاك المزاح الذي به ... إذا جئته سليت همي وأحزاني)\n(إذا قال لي يا مرد مي خر وكرها ... علي وكناني مزاحا بصفوان)\nذا كلام بالفارسية تفسيره يا رجل اشرب النبيذ\n(فيا لك من ملهى أنيق ومجلس ... كريم ومن مزح كثير بألوان)\n(وهل يغمزن بي ذو الهنات ابن راشد ... وذاك الكريم الجد من آل حران)\n(وهل أرين موسى الكريم ابن صالح ... ينازعني صوتا إذا هو غناني)\nيريد الغناء في\n(فلم أر كالتجمير منظر ناظر ... ولا كليالي النفر أفتن ذا هوى)\n(إذا صاح بالتجمير ثم أعاده ... بتحقيق إعراب صحيح وتبيان)\n(أولئك إخواني الذين أحبهم ... وأوثرهم بالود من بين إخواني)\n(وما منهم إلا كريم مهذب ... حبيب إلى إخوانه غير خوان)\nأجابه محمد بن راشد\n(بعثت بشعر فيه أن رسالة ... أتتك لموسى عن جماعة إخوان)\n(بشوق وذكر للجميل ولم يكن ... لموسى لعمري في سلامته ثاني)\n(ولكن نطقنا بالذي أنت أهله ... وما تستحق من صديق وندمان)\n(وموسى كريم لم يحط بك خبره ... كخبر ندامى قد بلوك وإخوان)\n(ولو قد بلاك قال فيك كقول من ... فسدت عليه من خليل وخلصان)\n(ولم يعره شوق إليك ولم يجد ... لفقدك مسا عند نزهة بستان)\n(حمدت الندامى كلهم غير إنسان ... ألا إنما يجني على نفسه الجاني)\n(فلا تعتب الإخوان من بعدها فما ... تنقص إخوان المودة من شاني)\nال فأجابه إسحاق\n(عجبت لمخذول تعرض جانيا ... لليث أبي شبلين من أسد خفان)\n(أتانا بشعر قاله مثل وجهه ... تزخرف فيه واستعان بأعوان)\n(فجاء بألفاظ ضعاف سخيفة ... ومضغها تمضيغ أهوج سكران)\n(دعوا الشعر للشيخ الذي تعرفونه ... وإلا وسمتم أو رميتم بشهبان)\n(فإنكم والشعر إذ تدعونه ... كمعتسف في ظلمة الليل حيران)\n(صه لا تعودوا للجواب فإنما ... ترومون صعبا من شماريخ ثهلان)\n(أنا الأسد الورد الذي لا يفله ... تظاهر أعداء عليه وأقران)\n(ومن قد أردتم جاهدين سقاطه ... فأعياكم في كل سر وإعلان)\n(لعمري لئن قلتم بما أنا أهله ... ليستنفدن القول تعظيمكم شاني)\n(وجحدكم إياي ما تعلمونه ... وإقراركم عندي بذلك سيان)\n(ألا يزجر الجهال عنا أميرنا ... وموسى وذاك الشيخ من آل حران)\n(ولا سيما من بان للناس شره ... فما يتمارى في مذاهبه اثنان)","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":62,"spl":"إسحاق ومحمد بن راشد"},
{"id":"b52-98","bab":"الجزء 5","sec":"محمد بن عمر الجرجاني يثني عليه","page":"ج5 ص350","text":"حدثني أحمد بن عبيد الله بن عمار قال حدثني يعقوب بن إسرائيل قرقارة قال قال لي محمد بن عمر الجرجاني وقد تذاكرنا إسحاق يوما بحضرته ما\nتذكرون من إسحاق شيئا تقاربون به وصفه كان والله إسحاق غرة في زمانه وواحدا في دهره علما وفقها وأدبا ووقارا ووفاء وجودة رأي وصحة مودة كان والله يخرس الناطق إذا نطق ويحير السامع إذا تحدث لا يمل جليسه مجلسه ولا تمج الآذان حديثه ولا تنبو النفوس عن مطاولته إن حدثك ألهاك وإن ناظرك أفادك وإن غناك أطربك وما كنت ترى خصلة من الأدب ولا جنسا من العلم يتكلم فيه إسحاق فيقدم أحد على مساجلته ومباراته أخبرني الحسن بن علي قال حدثنا يزيد بن محمد المهلبي قال حدثني أحمد بن يحيى المكي قال أمر المأمون يوما بالفرش الصيفي أن يخرج فأخرج فيما أخرج منه بساط طبري أو أصبهبذاني مكتوب في حواشيه صوت\n(لج بالعين واكف ... من هوى لا يساعف)\n(كلما جف دمعه ... هيجته المعازف)\n(إنما الموت أن تفارق ... من أنت آلف)\n(لك حبان في الفؤاد ... تليد وطارف)\nال فاستحسن المأمون هذه الأبيات وبعث إلى إسحاق فأحضره وأمره إن يصنع فيها لحنا ويعجل به فصنع فيها الهزج الذي يغنى به اليوم\nقال أحمد وسمعها أبي منه فقال لو كان هذا الهزج لحكم الوادي لكان قد أحسن يريد أن حكما كان صاحب الأهزاج","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":63,"spl":"محمد بن عمر الجرجاني يثني عليه"},
{"id":"b52-99","bab":"الجزء 5","sec":"يحيى المكي يعجب به ويثني عليه","page":"ج5 ص352","text":"أخبرني الحسن قال حدثني يزيد بن محمد قال حدثني ابن المكي قال تذاكرنا يوما عند أبي صنعة إسحاق وقد كنا بالأمس عند المأمون فغناه إسحاق لحنا صنعه في شعر ابن ياسين صوت\n(الطلول الدوارس ... فارقتها الأوانس)\n(أوحشت بعد أهلها ... فهي قفر بسابس)\nالغناء لإسحاق خفيف ثقيل بالبنصر قال فقال أبي لو لم يكن من بدائع إسحاق غير هذا لكفى الطلول الدوارس كلمتان وفارقتها الأوانس كلمتان وقد غنى فيهما استهلالا وبسيطا وصاح وسجع ورجع النغمة واستوفى ذلك كله في أربع كلمات وأتى بالباقي مثله فمن شاء فليفعل مثل هذا أو ليقاربه ثم قال إسحاق والله في زماننا فوق ابن سريج والغريض ومعبد ولو عاشوا حتى يروه لعرفوا فضله واعترفوا له به وأخبرني عمي عن يزيد بن محمد المهلبي أنه كان عند الواثق فغنته شجا\nهذا الصوت فقال الواثق مثل هذا القول والمذكور أن ابن المكي قاله فلا أدري أهذا وهم من يزيد أو اتفق أن قال فيه الواثق كما قال يحيى أو اتفقت عليه قريحتاهما أخبرنا يحيى بن علي قال حدثني أبي عن إسحاق قال أرسل إلي الفضل بن الربيع يوما وإلى الزبير بن دحمان فوافق مجيئنا شغلا كان له فصرنا إلى بعض حجره فنعست فنمت فإذا زبير يحركني فانتبهت فإذا خباز في مطبخ الفضل يضرب بالشوبق يغني صوت\n(بدير القائم الأقصى ... غزال شفني أحوى)\n(برى حبي له جسمي ... وما يدري بما ألقى)\n(وأخفي حبه جهدي ... ولا والله ما يخفى)\nلشعر والغناء لإسحاق خفيف ثقيل بالبنصر قال فقال لي الزبير تضن بهذا وانظر من يبتذله فقلت لا أضن بغناء بعد هذا حدثني عمي قال حدثني أحمد بن الطيب السرخسي قال حدثنا عمر بن شبة قال حدثني أحمد بن معاوية بن بكر قال قال لي صالح بن الرشيد كنا أمس عند أمير المؤمنين المأمون وعنده جماعة من المغنين فيهم إسحاق وعلويه ومخارق وعمرو بن بانة فغنى مخارق في الثقيل الأول\nصوت\n(أعاذل لا آلوك إلا خليقتي ... فلا تجعلي فوقي لسانك مبردا)\n(ذريني أكن للمال ربا ولا يكن ... لي المال ربا تحمدي غبه غدا)\n(ذريني يكن مالي لعرضي وقاية ... يقي المال عرضي قبل أن يتبددا)\n(ألم تعلمي أني إذا الضيف نابني ... وعز القرى أقري السديف المسرهدا)\nقال له المأمون لمن هذا اللحن قال لهذا الهزبر الجالس يعني إسحاق فقال المأمون لمخارق قم فاقعد بين يدي وأعد الصوت فقام فجلس بين يديه وأعاده فأجاده وشرب المأمون عليه رطلا ثم التفت إلى إسحاق فقال له غن هذا الصوت فغناه فلم يستحسنه كما استحسنه من مخارق ثم دار الدور إلى علويه فقال له غن فغنى في الثقيل الأول أيضا صوت\n(أريت اليوم نارك لم أغمض ... بواقصة ومشربنا برود)\n(فلم أر مثل موقدها ولكن ... لأية نظرة زهر الوقود)\n(فبت بليلة لا نوم فيها ... أكابدها وأصحابي رقود)\n(كأن نجومها ربطت بصخر ... وأمراس تدور وتستزيد)\nفقال له المأمون لمن هذا الصوت فقال لهذا الجالس وأشار إلى إسحاق فقال لعلويه أعده فأعاده فشرب عليه رطلا ثم قال لإسحاق غنه فغناه فلم يطرب له طربه لعلويه فالتفت إلي إسحاق ثم قال لي أيها الأمير لولا أنه مجلس سرور وليس مجلس لجاج وجدال لأعلمته أنه طرب على خطأ وأن الذي استحسنه إنما هو تزايد منهما يفسد قسمة اللحن وتجزئته وأن الصوت ما غنيته لا ما زادا ثم أقبل عليهما فقال يا مخنثان قد علمت أنكما لم تريدا بما فعلتماه مدحي ولا رفعتي وأنا على مكافأتكما قادر فضحك المأمون وقال له ما كان ما رأيته من طربي لهما إلا استحسانا لأصواتهما لا تقديما لهما ولا جهلا بفضلك","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":64,"spl":"يحيى المكي يعجب به ويثني عليه"},
{"id":"b52-100","bab":"الجزء 5","sec":"إسحاق يغني المعتصم فيطرب ويجيزه","page":"ج5 ص355","text":"حدثني عمي قال حدثني عبد الله بن أبي سعد قال حدثني محمد بن عبد الله بن مالك الخزاعي قال حدثني إسحاق قال دخلت يوما على المعتصم وقد رجع من الصيد وبين يديه ظباء مذبحة وطير ماء وغير ذلك من الصيد وهو يشرب فأمرني بالجلوس والغناء فجلست وغنيته صوت\n(اشتهينا في ربيع مرة ... زهم الوحش على لحم الإبل)\n(فغدونا بطوال هيكل ... كعسيب النخل مياد خضل)\nالشعر يقال إنه لأعشى همدان والغناء لأحمد النصبي خفيف ثقيل بإطلاق الوتر في مجرى البنصر عن إسحاق فتبسم وقال وأين رأيت لحم الإبل فغنيته صوت\n(ليس الفتى فيهم إذا ... شرب الشراب مؤنبا)\n(لكن يروح مرنحا ... حسن الثياب مطيبا)\n(يسقونه صرفا على ... لحم الظباء مضهبا)\nقال هذا أشبه وشرب ثم غنيته بشعر وضاح اليمن قال والغناء لابن محرز ثقيل أول صوت\n(أبى القلب اليماني الذي ... تحمد أخلاقه)\n(ويرفض له اللحن ... فما تفتق أرتاقه)\n(غزال أدعج العين ... ربيب خدلج ساقه)\n(رماني فسبى قلبي ... وأرميه فأشتاقه)\nطرب وقال هذا والله أحسن صيد وألذه وشرب عليه بقية يومه\nوخلع علي وأمر لي بجائزة هكذا ذكر في هذا الخبر أن الثقيل الأول لابن محرز وقد قيل ذلك وذكر عمرو بن بانة أن الثقيل الأول بالبنصر لابن طنبورة وأن لحن ابن محرز خفيف ثقيل حدثني عمي قال حدثني فضل اليزيدي قال قال لي إسحاق يوما في عرض حديثه دخلت على المعتصم ذات يوم وعليه قميص دبيقي كأنما قد من جرم الزهرة فضحكت فقال ما أضحكك فقلت من مبالغتك في الوصف فتبسم قال الفضل وما سمعت محدثا قط ولا واصفا أبلغ منه ولا أحسن لفظا وتشبيها أخبرنا يحيى بن علي قال حدثنا أبو أيوب المديني قال حدثنا محمد بن عبد الله بن مالك قال قال لي إسحاق وددت أن كل يوم قيل لي غن أو قيل لي عند ذكري المغني ضرب رأسي خمسة عشر سوطا لا أقوى على أكثر منها ولم يقل لي ذلك أخبرنا يحيى قال حدثنا حماد قال صنع أبي لحنه في تشكى الكميت الجري على لحن أذان سمعه أخبرنا يحيى قال حدثنا حماد قال تذاكرنا يوما الهزج عند المأمون فقال عمرو بن بانة ما أقله في الغناء القديم فقال إسحاق ما أكثره فيه ثم غناهم ثلاثين هزجا في إصبع واحدة ومجرى واحد ما عرفوا جميعا منها إلا نحو سبعة أصوات حدثني يحيى قال حدثني أخي قال حدثني عافية بن شبيب قال\nقلت لزرزور ما لكم تذلون لإسحاق هذا الذل وما فيكم أحد إلا وهو أطيب صوتا منه وما في صنائعكم وصمة فقال لي لا تقل ذلك فوالله لو رأيتنا معه لرحمتنا ورأيتنا نذوب كما يذوب الرصاص في النار حدثني الصولي قال حدثني عون بن محمد قال حدثني إسحاق قال لاعبت الفضل بن الربيع بالنرد فوقع بيننا خلاف فحلف وحلفت فغضب علي وهجرني فكتبت إليه\n(يقول أناس شامتون وقد رأوا ... مقامي وإغبابي الرواح إلى الفضل)\n(لقد كان هذا خص بالفضل مرة ... فأصبح منه اليوم منصرم الحبل)\n(ولو كان لي في ذاك ذنب علمته ... لقطعت نفسي بالملامة والعذل)\nعرضت الأبيات عليه فلما قرأها ضحك وقال أشد من ذنبك أنك لا ترى لنفسك بذلك الفعل ذنبا والله لولا أني أدبتك أدب الرجل ولده وأن حسنك وقبيحك مضافان إلي لأنكرتني فأصلح الآن قلب عون وكان يحجبه فخاطبته في ذلك فكلمني بما كرهت فقلت أتدخل بيني وبين الأمير أعزه الله وكان عون يرمي بالأبنة فقلت فيه\n(وذاكر أمر ضاق ذرعا بذكره ... وناس لداء منه متسع الخرق)\nال ثم علمت أنه لا يتم لي رضا الفضل إلا بعد أن يرضى عون فقلت فيه\n(عون يا عون ليس مثلك عون ... أنت لي عدة إذ كان كون)\n(لك عندي والله إن رضي الفضل ... غلام يرضيك أو برذون)\nدخل إلى الفضل فترضاه لي فرضي ثم قال له ويلك يا عون إنه والله إنما هجاك وأنت ترى أنه قد مدحك ألا ترى إلى قوله غلام يرضيك هذا تعريض بك قال فكيف أصنع به مع محله عند الأمير","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":65,"spl":"إسحاق يغني المعتصم فيطرب ويجيزه"},
{"id":"b52-101","bab":"الجزء 5","sec":"غنى المأمون وأطربه فأجازه","page":"ج5 ص359","text":"أخبرني الصولي قال حدثني عون عن إسحاق وأخبرني بعض الخبر إسماعيل بن يونس عن عمر بن شبة عن إسحاق ولفظ الخبر وسياقته للصولي قال استدناني المأمون يوما وهو مستلق على فراش حتى صارت ركبتي على الفراش ثم قال لي يا إسحاق أشكو إليك أصحابي فعلت بفلان كذا ففعل كذا وفعلت بفلان كذا ففعل كذا حتى عدد جماعة من خواصه فقلت له أنت يا سيدي بتفضلك علي وحسن رأيك في ظننت أني ممن يشاور في مثل هذا فجاوزت بي حدي وهذا رأي يجل عني ولا يبلغه قدري فقال ولم وأنت عندي عالم عاقل ناصح فقلت هذه المنزلة عند سيدي علمتني ألا أقول إلا ما أعرف ولا أطلب إلا ما أنال فضحك وقال قد بلغني أنك في هذه الأيام صنعت لحنا في شعر الراعي ولم أسمعه منك فقلت يا سيدي ما سمعه أحد إلا جواري ولا حضرت عندك للشرب منذ صنعته فقال غنه فقلت الهيبة والصحو يمنعاني أن أؤديه كما تريد فلو آنس أمير المؤمنين عبده بشيء يطربه ويقوي به طبعه كان أجود قال صدقت ثم أمر بالغداء فتغدينا ومدت الستارة فغني من ورائها وشربنا أقداحا فقال يا إسحاق أما جاء أوان ذلك الصوت فقلت بلى يا سيدي وغنيته لحني في شعر الراعي\nصوت\n(ألم تسأل بعارمة الديارا ... عن الحي المفارق أين صارا)\n(بلى ساءلتها فأبت جوابا ... وكيف تسائل الدمن القفارا)\nحن إسحاق في هذين البيتين خفيف ثقيل بالوسطى قال فاستحسنه وما زال يشرب عليه سائر يومه وقال لي يا إسحاق لا طلب بعد وجود البغية ما أشرب بقية يومي هذا إلا على هذا الصوت ثم وصلني وخلع علي خلعة من ثيابه حدثني الصولي قال حدثني عون بن محمد قال حدثني إسحاق قال كانت أعرابية تقدم علي من البادية فأفضل عليها وكانت فصيحة فقالت لي ذات يوم والذي يعلم مغزى كل ناطق لكأنك في علمك ولدت فينا ونشأت معنا ولقد أريتني نجدا بفصاحتك وأحللتني الربيع بسماحتك فلا اطرد لي قول إلا شكرتك ولا نسمت لي ريح إلا ذكرتك حدثني الصولي قال حدثني عون بن محمد قال حدثني المغيرة بن محمد المهلبي عن إسحاق قال كان أبو المجيب الربعي فصيحا عالما فقال لي يا أبا محمد قد عزمت على التزوج فأعني وقوني قال فأعطيته دنانير وثيابا فغاب عني أياما ثم عاد فقلت يا أبا مجيب ها هنا أبيات فاسمعها فقال هاتها فقلت\n(يا ليت شعري عن أبي مجيب ... إذ بات في مجاسد وطيب)\n(معانقا للرشأ الربيب ... أأحمد المحفار في القليب)\n(أم كان رخوا ذابل القضيب ... )\nال فقال لي الأخير والله يا أبا محمد حدثني الصولي قال حدثني عون بن محمد قال حدثني إسحاق قال كانت بيني وبين الخليل بن هشام صداقة ثم استوحشنا فمررت ببابه يوما فتذممت أن أجوزه ولا أدخل إليه فدعوت بدواة وقرطاس وكتبت إليه\n(رجعنا بالصفاء إلى الخليل ... فليس إلى التهاجر من سبيل)\n(عتاب في مراجعة وصفح ... أحق بنا وأشبه بالجميل)\nال ووجهت بالرقعة وقصدت بابه فخرج إلي حتى تلقاني ورجعنا إلى ما كنا عليه حدثني الصولي قال حدثني عبد الله بن المعتز عن الهشامي قال كان أهلنا يعتبرون على إسحاق ما يقوله في نسبة الغناء وأخباره بأن يجلسوا كاتبتين فهمتين خلف الستارة فتكتبان ما يقوله وتضبطانه ثم\nيتركونه مدة حتى ينسى ما جرى ثم يعيدون تلك المسألة عليه فلا يزيد فيها ولا ينقص منها حرفا كأنه يقرأها من دفتر فعلموا حينئذ أنه لا يقول في شيء يسأل عنه إلا الحق حدثني الصولي قال حدثني أحمد بن مزيد المهلبي قال حدثني أبي عن إسحاق قال كنا عند المأمون فغناه علويه صوت\n(لعبدة دار ما تكلمنا الدار ... تلوح مغانيها كما لاح أسطار)\n(أسائل أحجارا ونؤيا مهدما ... وكيف يرد القول نؤي وأحجار)\nلشعر لبشار والغناء لإبراهيم ثاني ثقيل مطلق في مجرى الوسطى عن إسحاق قال فقال المأمون لمن هذا اللحن فقلت لعبد أمير المؤمنين أبي وقد أخطأ فيه علويه قال فغنه أنت فغنيته فاستعادنيه مرارا وشرب عليه أقداحا ثم تمثل قول جرير\n(وابن اللبون إذا ما لز في قرن ... لم يستطع صولة البزل القناعيس)\nم أمر لي بخمسين ألف درهم ووجدت هذا الخبر بخط أبي العباس ثوابة فقال فيه حدثني أحمد بن إسماعيل أبو حاتم قال حدثني عبد الله ابن العباس الربيعي قال\nإجتمعنا بين يدي المعتصم فغنى علويه\n(لعبدة دار ما تكلمنا الدار ... )","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":66,"spl":"غنى المأمون وأطربه فأجازه","partial":1},
{"id":"b52-102","bab":"الجزء 5","sec":"غنى المأمون وأطربه فأجازه","page":"ج5 ص359","text":"قال له إسحاق أخطأت فيه ليس هو هكذا فقال علويه أم من أخذناه عنه هكذا زانية فقال إسحاق شتمنا قبحه الله وسكت وبان ذلك فيه وكان علويه أخذه من إبراهيم","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":67,"spl":"غنى المأمون وأطربه فأجازه — حواره مع علويه"},
{"id":"b52-103","bab":"الجزء 5","sec":"حواره مع علويه","page":"ج5 ص363","text":"حدثني جحظة قال حدثني أبو العبيس بن حمدون عن أبيه عن جده قال كان إسحاق بعد وفاة المأمون لا يغني إلا الخليفة أو ولي عهده أو رجلا من الطاهرية مثل إسحاق بن إبراهيم وطبقته فاجتمعنا عند الواثق وهو ولي عهد المعتصم فاشتهى الواثق أن يضرب بين مخارق وعلويه وإسحاق ففعل حتى تهاتروا ثم قال لإسحاق كيف هما الآن عندك فقال أما مخارق فمناد طيب الصوت وأما علويه فهو خير حماري العبادي وهو على كل حال شييء يريد تصغيره فوثب علويه مغضبا ثم قال للواثق جواريه حرائر ونساؤه طوالق لئن لم تستحلفه بحياتك وحق أبيك أن يصدق عما أسأله عنه لأتوبن عن الغناء ما عشت فقال له الواثق لا تعربد يا علي نحن نفعل ما سألت ثم حلف إسحاق أن يصدق فحلف فقال له من أحسن الناس اليوم صنعة بعدك قال أنت قال فمن\nأضرب الناس بعد ثقيف قال أنت قال فمن أطيب الناس صوتا بعد مخارق قال أنت قال علويه لإسحاق أهذا قولك في وأنت تعلم أني مصلي كل سابق فاضل وأني ثالث ثلاثة أنت أحدهم لم يكن في الدنيا مثلهم ولا يكون فما أنت وغناؤك الذي لا يسمع انخفاضا فغضب إسحاق وانتهر الواثق علويه ثم أخذ إسحاق عودا فنقل مثناه إلى موضع ألبم وزيره إلى موضع المثلث وجعل البم والمثلث مكان الزير والمثنى وضرب وقال ليغن من شاء منكم فغنى مخارق عليه\n(تقطع من ظلامة الوصل أجمع ... أخيرا على أن لم يكن يتقطع)\nضرب عليه إسحاق فلم يبن في الأوتار خلاف ولا فقد من الإيقاع شيء ولا بان فيه اختلال فعظم عجب الواثق من فعله وقام إسحاق فرقص طربا فكان والله أحسن رقصا من كبيش وعبد السلام وكانا من أرقص الناس فقال الواثق لا يكمل أحد أبدا في صناعته كمثل كمال إسحاق حدثني الصولي قال حدثني عون بن محمد قال حدثني إسحاق قال دخلت على عبد الله بن طاهر وهو يلاعب إبراهيم بن وهب بالشطرنج فغلبه عبد الله وأومأ إلي بأن أكايده فقلت\n(قد ذهبت منك أبا إسحاق ... مثل ذهاب الشهر بالمحاق)\nقال لي عبد الله إن فضائلك يا أبا محمد لتتكاثر عندنا كما قال الشاعر في إبله\n(إذا أتاها طالب يستامها ... تكاثرت في عينه كرامها)\nأخبرني محمد بن خلف بن المرزبان قال ذكر علي بن الحسن بن عبد الأعلى عن إسحاق قال أنشدتني أم محمد الأعرابية لنفسها هذين البيتين وأنا حاج فاستحسنتهما وصنعت فيهما لحنا غنيته الواثق فاستعاده حتى أخذه وأمر لي بثلاثين ألف درهم وهما\n(عسى الله يا ظمياء أن يعكس الهوى ... فتلقين ما قد كنت منك لقيت)\n(ثراء فتحتاجي إلي فتعلمي ... بأن به أجزيك حين غنيت)","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":67,"spl":"غنى المأمون وأطربه فأجازه — حواره مع علويه"},
{"id":"b52-104","bab":"الجزء 5","sec":"براعة إسحاق تظهر في مجلس المعتصم","page":"ج5 ص365","text":"حدثني عمي قال حدثني عبد الله بن أبي سعد قال حدثني محمد بن مروان قال قال لي يحيى بن معاذ كان إسحاق الموصلي وإبراهيم بن المهدي إذا خلوا فهما أخوان وإذا التقيا عند خليفة تكاشحا أقبح تكاشح فاجتمعا يوما عند المعتصم فقال لإسحاق يا إسحاق إن إبراهيم يثلبك ويغض منك ويقول إنك تقول إن مخارقا لا يحسن شيئا ويتضاحك منك فقال إسحاق لم أقل يا أمير المؤمنين إن مخارقا لا يحسن شيئا وكيف أقول ذلك وهو تلميذ أبي وتخريجه وتخريجي ولكن قلت إن مخارقا يملك من صوته ما لا يملكه أحد فيتزايد فيه تزايدا لا يبقي عليه ويتغير في كل حال فهو أحلى الناس مسموعا وأقله نفعا لمن يأخذ عنه لقلة ثباته على شيء واحد ولكني أفعل الساعة فعلا إن زعم إبراهيم أنه يحسنه فلست أحسن شيئا وإلا فلا ينبغي له أن يدعي ما ليس يحسنه ثم أخذ عودا فشوش أوتاره ثم قال لإبراهيم غن على هذا أو يغني غيرك وتضرب عليه فقال المعتصم يا إبراهيم قد سمعت فما عندك قال ليفعله هو إن كان صادقا فقال له إسحاق غن حتى أضرب عليك فأبى فقال لزرزور غن فغنى وإسحاق يضرب عليه\nحتى فرغ من الصوت ما علم أحد أن العود مشوش ثم قال هاتوا عودا آخر فشوشه وجعل كل وتر منه في الشدة واللين على مقدار العود المشوش الأول حتى استوفى ثم قال لزرزور خذ أحدهما فأخذه ثم قال انظر إلى يدي واعمل كما أعمل واضرب ففعل وجعل إسحاق يغني ويضرب وزرزور ينظر إليه ويفعل كما يفعل فما ظن أحد أن في العودين شيئا من الفساد لصحة نغمهما جميعا إلى أن فرغ من الصوت ثم قال لإبراهيم خذ الآن أحد العودين فاضرب به مبدأ أو عمود طريقة أو كيف شئت إن كنت تحسن شيئا فلم يفعل وانكسر انكسارا شديدا فقال له المعتصم أرأيت مثل هذا قط قال لا والله ما رأيت ولا ظننت أن مثله يكون حدثني أبو عبد الله محمد بن العباس اليزيدي قال حدثني عمي الفضل قال دعاني إسحاق يوما فمضيت إليه وعنده الزبير بن دحمان وعلويه وحسين بن الضحاك فمر لنا أحسن يوم فالتفت إلي إسحاق ثم قال يومنا هذا والله يا أبا العباس كما قال الشاعر\n(أنت والله من الأيام ... لدن الطرفين)\n(كلما قلبت عيني ... ففي قرة عين)","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":68,"spl":"براعة إسحاق تظهر في مجلس المعتصم"},
{"id":"b52-105","bab":"الجزء 5","sec":"إسحاق والواثق","page":"ج5 ص366","text":"أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه قال دخلت يوما على الواثق فقال لي يا إسحاق إني أصبحت اليوم قرما إلى غنائك فغنني فغنيته\n(من الظباء ظباء همها السخب ... ترعى القلوب وفي قلبي لها عشب)\n(لا يغتربن ولا يسكن بادية ... وليس يدرين ما ضرع ولا حلب)\n(إذا يد سرقت فالقطع يلزمها ... والقطع في سرق بالعين لا يجب)\nال فشرب عليه بقية يومه وبعض ليلته وخلع علي خلعة من ثيابه أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه قال خرجت مع الواثق إلى الصالحية وهو يريد النزهة فذكرت بغداد وعيالي وأهلي وولدي بها فبكيت فقال لي بحياتي أذكرت بغداد فبكيت شوقا إليها فقلت نعم وغنيته صوت\n(وما زلت أبكي في الديار وإنما ... بكائي على الأحباب ليس على الدار)\nال فأمر لي بمائة ألف درهم وصرفني وأخبرني محمد بن مزيد بهذا الخبر عن حماد بن إسحاق عن أبيه وحدثني به علي بن هارون عن عمه عن حماد عن أبيه وخبره أتم قال ما وصلني أحد من الخلفاء قط بمثل ما وصلني به الواثق ولقد انحدرت معه إلى النجف فقلت له يا أمير المؤمنين قد قلت في النجف قصيدة فقال هاتها فأنشدته\n(يا راكب العيس لا تعجل بنا وقف ... نحي دارا لسعدى ثم ننصرف)\nتى أتيت على قولي\n(لم ينزل الناس في سهل ولا جبل ... أصفى هواء ولا أعذى من النجف)\n(حفت ببر وبحر من جوانبها ... فالبر في طرف والبحر في طرف)\n(وما يزال نسيم من يمانية ... يأتيك منها بريا روضة أنف)\nفقال صدقت يا إسحاق هي كذلك ثم أنشدته حتى أتيت على قولي في مدحه\n(لا يحسب الجود يفني ماله أبدا ... ولا يرى بذل ما يحوي من السرف)\nمضيت فيها حتى أتممتها فطرب وقال أحسنت والله يا أبا محمد وكناني يومئذ وأمر لي بمائة ألف درهم وانحدر إلى الصالحية التي يقول فيها أبو نواس\n(بالصالحية من أكناف كلواذ ... )\nذكرت الصبيان وبغداد فقلت\n(أتبكي على بغداد وهي قريبة ... فكيف إذا ما ازددت منها غدا بعدا)\n(لعمرك ما فارقت بغداد عن قلى ... لو انا وجدنا عن فراق لها بدا)\n(إذا ذكرت بغداد نفسي تقطعت ... من الشوق أو كادت تموت بها وجدا)\n(كفى حزنا أن رحت لم أستطع لها ... وداعا ولم أحدث بساكنها عهدا)\nال فقال لي يا موصلي أشتقت إلى بغداد فقلت لا والله\nيا أمير المؤمنين ولكن من أجل الصبيان وقد حضرني بيتان فقال هاتهما فأنشدته\n(حننت إلى الأصيبية الصغار ... وشاقك منهم قرب المزار)\n(وأبرح ما يكون الشوق يوما ... إذا دنت الديار من الديار)\nقال لي يا إسحاق صر إلى بغداد فأقم مع عيالك شهرا ثم صر إلينا وقد أمرت لك بمائة ألف درهم أخبرنا يحيى بن علي قال أخبرني أبي قال لما صنع الواثق لحنه في\n(أيا منشر الموتى أقدني من التي ... بها نهلت نفسي سقاما وعلت)\n(لقد بخلت حتى لو اني سألتها ... قذى العين من سافي التراب لضنت)\nعجب به إعجابا شديد فوجه بالشعر إلى إسحاق الموصلي وأمره أن يغني فيه فصنع فيه لحنه الثقيل الأول وهو من أحسن صنعة إسحاق فلما سمعه الواثق عجب منه وصغر لحنه في عينه وقال ما كان أغنانا أن نأمر إسحاق بالصنعة في هذا الشعر لأنه قد أفسد علينا لحننا قال علي بن يحيى قال إسحاق ما كان يحضر مجلس الواثق أعلم منه بهذا الشأن","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":69,"spl":"إسحاق والواثق","partial":1},
{"id":"b52-106","bab":"الجزء 5","sec":"نسبة هذين الصوتين","page":"ج5 ص369","text":"صوت\n(أيا منشر الموتى أقدني من التي ... بها نهلت نفسي سقاما وعلت)\n(لقد بخلت حتى لو اني سألتها ... قذى العين من سافي التراب لضنت)\nلشعر لأعرابي والغناء للواثق ثاني ثقيل في مجرى البنصر وفيه لمخارق رمل ولعريب رمل ومن الناس من ينسب هذا الشعر إلى كثير وهو خطأ من قائله\nأنشدني هذه الأبيات عمي قال أنشدني هارون بن علي بن يحيى وأنشدنيها علي بن هارون عن أبيه عن جده عن إسحاق أنه أنشده لأعرابي فقال صوت\n(ألا قاتل الله الحمامة غدوة ... على الغصن ماذا هيجت حين غنت)\n(تغنت بصوت أعجمي فهيجت ... من الشوق ما كانت ضلوعي أجنت)\nنى في هذين البيتين عمرو بن بانة ثاني ثقيل بالوسطى\n(فلو قطرت عين امرئ من صبابة ... دما قطرت عيني دما فألمت)\n(فما سكتت حتى أويت لصوتها ... وقلت ترى هذي الحمامة جنت)\n(ولي زفرات لو يدمن قتلنني ... بشوق إلى نأي التي قد تولت)\n(إذا قلت هذي زفرة اليوم قد مضت ... فمن لي بأخرى في غد قد أظلت)\n(فيا محيي الموتى أقدني من التي ... بها نهلت نفسي سقاما وعلت)\n(لقد بخلت حتى لو اني سألتها ... قذى العين من سافي التراب لضنت)\n(فقلت ارحلا يا صاحبي فليتني ... أرى كل نفس أعطيت ما تمنت)\n(حلفت لها بالله ما أم واحد ... إذا ذكرته آخر الليل حنت)\n(وما وجد أعرابية قذفت بها ... صروف النوى من حيث لم تك ظنت)\n(إذا ذكرت ماء العضاه وطيبه ... وبرد الحمى من بطن خبت أرنت)\n(بأكثر منى لوعة غير أنني ... أجمجم أحشائي على ما أجنت)\nأما لحن إسحاق فإنه غنى في\n(لقد بخلت حتى لو اني سألتها ... )\nأضاف إليه شيئا آخر وليس من ذلك الشعر وهو\n(فإن بخلت فالبخل منها سجية ... وإن بذلت أعطت قليلا وأكدت)\nال ولحنه ثقيل أول بالسبابة في مجرى الوسطى أخبرني الحسن بن علي ومحمد بن يحيى الصولي قال حدثنا يزيد بن محمد المهلبي وحدثني به عمي عن أبي جعفر بن دهقانة النديم عن أبيه قال كان الواثق إذا صنع صوتا قال لإسحاق هذا وقع إلينا البارحة فاسمعه فكان ربما أصلح فيه الشيء بعد الشيء فكاده مخارق عنده وقال له إنما يستجيد صنعتك إذا حضر ليقاربك ويستخرج ما عندك فإذا فارق حضرتك قال في صنعتك غير ما تسمع قال الواثق فأنا أحب أن أقف على ذلك فقال له مخارق فأنا أغنيه أيا منشر الموتى فإنه لم يعلم أنه لك ولا سمعه من أحد قال فافعل فلما دخل إسحاق غناه مخارق وتعمد لأن يفسده بجهده وفعل ذلك في مواضع خفية لم يعلمها الواثق من قسمته فلما غناه قال له الواثق كيف ترى هذا الصوت قال له فاسد غير مرضي فأمر به فسحب من المجلس حتى أخرج عنه وأمر بنفيه إلى بغداد ثم جرى ذكره يوما فقالت له فريدة يا أمير المؤمنين إنما كاده مخارف فأفسد عليه الصوت من حيث أوهمك أنه زاد فيه بحذقه نغما وجودة وإسحاق يأخذ نفسه بقول الحق من كل شيء ساءه أو سره ويفهم من غامض علل الصنعة ما لا يفهمه غيره فليحضره أمير المؤمنين ويحلفه بغليظ الأيمان أن يصدقه عما يسمع وأغنيه إياه حتى يقف على حقيقة الصوت فإن كان فاسدا فصدق عنه لم يكن عليه عتب ووافقناه عليه حتى يستوي\nفليس يجوز أن نتركه فاسدا إذا كان فيه فساد وإن كان صحيحا قال فيه ما عنده فأمر بالكتاب بحمله فحمل وأحضر فأظهر الرضا عنه ولزمه أياما ثم أحلفه ليصدقن عما يمر في مجلسه فحلف له ثم غنى الواثق أصواتا يسأله عنها أجمع فيخبر فيها بما عنده ثم غنته فريدة هذا الصوت وسأله الواثق عنه فرضيه واستجاده وقال له ليس على هذا سمعته في المرة الأولى وأبان عن المواضع الفاسدة وأخبر بإفساد مخارق إياها فسكن غضبه ووصل إسحاق وتنكر لمخارق مدة","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":70,"spl":"نسبة هذين الصوتين","partialRef":{"sid":"b52-105","gi":8,"vi":1,"side":0},"partial":1},
{"id":"b52-107","bab":"الجزء 5","sec":"إسحاق والواثق وقصة الغناء والألحان","page":"ج5 ص372","text":"أخبرنا يحيى بن علي قال حدثنا أبو أيوب المديني قال حدثنا محمد بن عبد الله بن مالك قال حدثني إسحاق الموصلي أنه دخل على إسحاق بن إبراهيم الطاهري وقد كان تكلم له في حاجة فقضيت فقال له أعطاك الله أيها الأمير ما لم تحط به أمنية ولا تبلغه رغبة قال فاشتهى هذا الكلام واستعاده مني فأعدته ثم مكثنا ما شاء الله وأرسل الواثق إلى محمد بن إبراهيم يأمره بإخراجي إليه في الصوت الذي أمرني به بأن أغني فيه وهو\n(لقد بخلت حتى لو أني سألتها ... )\nغنيته إياه فأمر لي بمائة ألف درهم فخرجت وأقمت ما شاء الله ليس أحد من مغنيهم يقدر أن يأخذ هذا الغناء مني فلما طال مقامي قلت له يا أمير المؤمنين ليس أحد من هؤلاء المغنين يقدر أن يأخذ هذا الصوت مني فقال لي ولم ويحك فقلت لأني لا أصححه ولا تسخو نفسي\nبه لهم فما فعلت الجارية التي أخذتها مني يعني شجا وهي التي كان أهداها إلى الواثق وعمل مجرد أغانيها وجنسه ونسبه إلى شعرائه ومغنيه وهو الذي في أيدي الناس إلى اليوم فقال وكيف قال لأنها تأخذه مني ويأخذونه هم منها فأمر بها فأخرجت وأخذته على المكان فأمر لي بمائة ألف درهم وأذن لي في الانصراف وكان إسحاق بن إبراهيم الطاهري حاضرا فقلت للواثق عند وداعي له أعطاك الله يا أمير المؤمنين ما لم تحط به أمنية ولم تبلغه رغبة فالتفت إلي إسحاق بن إبراهيم فقال لي أي إسحاق أتعيد الدعاء فقلت إي والله أعيده قاض أنا أو مغن وقدمت بغداد فلما وافى إسحاق جئته مسلما عليه فقال لي ويحك يا إسحاق أتدري ما قال أمير المؤمنين بعد خروجك من عنده قلت لا أيها الأمير قال قال لي ويحك كنا أغنى الناس عن أن نبعث إسحاق على لحننا حتى أفسده علينا قال علي بن يحيى فحدثني إسحاق قال استأذنت الواثق عدة دفعات في الانحدار إلى بغداد فلم يأذن لي فصنعت لحنا في\n(خليلي عوجا من صدور الرواحل ... )\nم غنيته الواثق فاستحسنه وعجب من صحة قسمته ومكث صوته أياما ثم قال لي يا إسحاق قد صنعت لحنا في صوتك في إيقاعه وطريقته وأمر من وراء الستارة فغنوه فقلت قد والله يا أمير المؤمنين بغضت إلي لحني وسمجته عندي وقد كنت استأذنته في الانحدار إلى بغداد فلم يأذن لي فلما صنع هذا اللحن وقلت له ما قلت أتبعته بأن قلت له قد والله يا أمير المؤمنين اقتصصت مني في لقد بخلت وزدت فأذن لي بعد ذلك","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":71,"spl":"إسحاق والواثق وقصة الغناء والألحان — نسبة هذا الصوت","partial":1},
{"id":"b52-108","bab":"الجزء 5","sec":"نسبة هذا الصوت","page":"ج5 ص374","text":"صوت\n(خليلي عوجا من صدور الرواحل ... بجرعاء حزوى فابكيا في المنازل)\n(لعل انحدار الدمع يعقب راحة ... من الوجد أو يشفي نجي البلابل)\nالشعر لذي الرمة والغناء لإسحاق رمل بالوسطى في البيتين وللواثق في البيت الثاني وحده رمل بالبنصر أخبرني أحمد بن عمار قال حدثني يعقوب بن نعيم قال حدثني كثير بن أبي جعفر الحزامي الكوفي عن أحمد بن جواس الحنفي عن أبي بكر بن عياش قال كنت إذا أصابتني المصيبة تصبرت وأمسكت عن البكاء فأجد ذلك يشتد علي حتى مررت ذات يوم بالكناسة فإذا أنا بأعرابي واقف على ناقة له وهو ينشد\n(خليلي عوجا من صدور الرواحل ... بجرعاء حزوى فابكيا في المنازل)\n(لعل انحدار الدمع يعقب راحة ... من الوجد أو يشفي نجي البلابل)\nسألت عنه فقيل لي هذا ذو الرمة فكنت بعد إذا أصابتني مصيبة بكيت فأجد لذلك راحة فقلت قاتل الله الأعرابي ما كان أعلمه وأفصح لهجته أخبرنا يحيى بن علي عن أبيه قال قلت لإسحاق أيما أجود لحنك في خليلي عوجا أم لحن الواثق فقال لحني أجود قسمة وأكثر عملا ولحنه أطرب لأنه جعل ردته من نفس قسمته وليس يقدر على أدائه إلا متمكن من نفسه قال علي ابن يحيى فتأملت اللحنين بعد ذلك فوجدتهما كما ذكر إسحاق قال وقال لي إسحاق ما كان بحضرة الواثق أعلم منه بالغناء أخبرني علي بن هارون قال كان عبد الله بن المعتز يحلف أن الواثق ظلم نفسه في تقديمه لحن إسحاق في لقد بخلت قال ومن الدليل على ذلك أنه قلما غني في صوت واحد بلحنين فسقط أجودهما وشهر الدون ولا يشهر من اللحنين إلا أجودهما ولحن الواثق أشهرهما وما يروي لحن إسحاق إلا العجائز ومن كثرت روايته حدثني جحظة عن ابن المكي المرتجل عن أبيه أحمد بن يحيى قال كان الواثق يعرض صنعنه على إسحاق فيصلح فيها الشيء بعد الشيء","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":71,"spl":"إسحاق والواثق وقصة الغناء والألحان — نسبة هذا الصوت"},
{"id":"b52-109","bab":"الجزء 5","sec":"آخر صوت صنعه","page":"ج5 ص375","text":"أخبرنا حسين بن يحيى عن حماد أن آخر صوت صنعه أبوه لقد بخلت ثم ما صنع شيئا حتى مات\nأخبرنا هاشم بن محمد الخزاعي قال حدثني أبو زيد عمر بن شبة قال حدثني إسحاق قال دخل أعرابي من بني سليم سر من رأى وكان يكنى أبا القنافذ فحضر باب المعتصم مع الشعراء فأذن له فلما مثل بين يديه أنشده\n(مراض العيون خماص البطون ... طوال المتون قصار الخطا)\n(عتاق النحور دقاق الثغور ... لطاف الخصور خدال الشوى)\n(عطابيل من كل رقراقة ... تلوث الإزار بدعص النقا)\n(إذا هن منيننا نائلا ... أبى البخل منهن ذاك المنى)\n(إلى النفر البيض أهل البطاح ... وأهل السماح طلبنا الندى)\n(لهم سطوات إذا هيجوا ... وحلم إذا الجهل حل الحبا)\n(يبين لك الخير في أوجه ... لهم كالمصابيح تجلوا الدجى)\n(سعى الناس كي يدركوا فضلهم ... فقصر عن سعيهم من سعى)\n(سعى للخلافة فاقتادها ... وبرز في السبق لما جرى)\nال فاستحسنها المعتصم وأمرني فغنيت فيها وأمر للأعرابي بعشرين ألف درهم ولي بثلاثين ألف درهم وما خرج الناس يومئذ إلا بهذه الأبيات حدثني عمي قال حدثني فضل اليزيدي عن إسحاق قال\nكتبت إلى علي بن هشام أطلب منه نبيذا فبعث إلي جمان بما التمست وكتب إلي قد بعثت إليك بشراب أصلب من الصخر وأعتق من الدهر وأصفى من القطر حدثني جحظة قال حدثني أبو عبد الله الهشامي عن أحمد المكي قال لما صنع إسحاق لحنه في الرمل\n(أماوي إن المال غاد ورائح ... ويبقى من المال الأحاديث والذكر)\n(وقد علم الأقوام لو أن حاتما ... يريد ثراء المال كان له وفر)\nهو رمل نادر ابتداؤه صياح ثم لا يزال ينزل على تدريج حتى يقطعه على سجحة وكان كثير الملازمة لعبد الله بن طاهر ثم تخلف عنه مدة وذلك في أيام المأمون فقال عبد الله للميس جاريته خذي لحن إسحاق في\n(أماوي إن المال غاد ورائح ... )\nفاخلعيه على\n(وهبت شمال آخر الليل قرة ... ولا ثوب إلا بردها وردائيا)\nألقيه على كل جارية تعلمينها واشهريه وألقيه على من يجيده من\nجواري زبيدة وقولي أخذته من بعض عجائز المدينة ففعلت وشاع أمره حتى غني به بين يدي المأمون فقال المأمون للجارية ممن أخذت هذا فقالت من دار عبد الله بن طاهر من لميس جاريته وأخبرتني أنها أخذته من بعض عجائز المدينة فقال المأمون لإسحاق ويلك قد صرت تسرق الغناء وتدعيه اسمع هذا الصوت فسمعه فقال هذا وحياتك لحني وقد وقع علي فيه نقب من لص حاذق وأنا أغوص عليه حتى أعرفه ثم بكر إلى عبد الله بن طاهر فقال أهذا حقي وحرمتي وخدمتي تأخذ لميس لحني في\n(أماوي إن المال غاد ورائح ... )\nتغنيه في وهبت شمال وليس بي ذلك ولكن بي أنها فضحتني عند الخليفة وادعت أنها أخذته من بعض عجائز المدينة فضحك عبد الله وقال لو كنت تكثر عندنا كما كنت تفعل لم تقدم عليك لميس ولا غيرها فاعتذر فقبل عذره وقال له أي شيء تريد قال أريد أن تكذب نفسها عند من ألقته عليها حتى يعلم الخليفة بذلك قال أفعل ومضى إسحاق إلى المأمون وأخبره القصة فاستكشفها من لميس حتى وقف عليها وجعل يعبث بإسحاق بذلك مدة","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":72,"spl":"آخر صوت صنعه","partialRef":{"sid":"b7-27","gi":7,"vi":0,"side":0},"partial":1},
{"id":"b52-110","bab":"الجزء 5","sec":"إسحاق يغني محمد الأمين","page":"ج5 ص378","text":"حدثني جحظة قال حدثني عبيد الله بن عبد الله بن طاهر قال حدثتني شهوات الصناجة التي كان إسحاق أهداها إلى الواثق أن محمدا الأمين لما غناه إسحاق لحنه الذي صنعه في شعره وهو الثقيل الأول\nصوت\n(يأيها القائم الأمين فدت ... نفسك نفسي بالمال والولد)\n(بسطت للناس إذ وليتهم ... يدا من الجود فوق كل يد)\nفأمر له بألف ألف درهم فرأيتها قد وصلت إلى داره يحملها مائة فراش حدثني جحظة ومحمد بن خلف بن المرزبان قالا حدثنا حماد بن إسحاق عن أبيه قال غنيت الواثق صوت\n(عفا طرف القرية فالكثيب ... إلى ملحاء ليس بها عريب)\n(تأبد رسمها وجرى عليها ... سوافي الريح والقرب الغريب)\nلحنه ثقيل ثان قال فقال لي يا إسحاق قد أحسن ابن هرمة في البيتين فأي شيء هو أحسن فيهما من جميعهما قال قلت قوله الترب الغريب يريد أن الريح جاءت إلى الأرض بتراب ليس منها فهو غريب جاءت به من موضع بعيد فقال صدقت وأحسنت وأمر لي بخمسين ألف درهم حدثني علي بن سليمان الأخفش قال حدثني محمد بن الحسن بن الحرون قال كنا يوما عند أحمد بن المدبر فغناه مغن كان عنده لحن إسحاق\nصوت\n(فأصبحت كالحومان ينظر حسرة ... إلى الماء عطشانا وقد منع الوردا)\nقال ابن المدبر زد فيه\n(وأمسيت كالمسلوب مهجة نفسه ... يرى الموت في صد الحبيب إذا صدا)\nحن إسحاق في هذا البيت من الثقيل الأول بإطلاق الوتر في مجرى البنصر حدثني الأخفش قال حدثني محمد بن يزيد الأزدي قال حدثني شيخ من ولد المهلب قال دخل مروان بن أبي حفصة يوما على إبراهيم الموصلي فجعلا يتحدثان إلى أن أنشد إسحاق بن إبراهيم مروان بن أبي حفصة لنفسه\n(إذا مضر الحمراء كانت أرومتي ... وقام بنصري خازم وآبن خازم)\n(عطست بأنف شامخ وتناولت ... يداي الثريا قاعدا غير قائم)\nال وجعل إبراهيم يحدث مروان وهو عنه ساه مشغول فقال له مالك لا تجيبني قال إنك والله لا تدري ما أفرغ ابنك هذا في أذني حدثني أحمد بن جعفر جحظة قال حدثني الحرمي بن أبي العلاء قال حدثني موسى بن هارون عن يعقوب بن بشر قال كنت مع إسحاق الموصلي في نزهة فمر بنا أعرابي فوجه إسحاق خلفه بغلامه زياد الذي يقول فيه\n(وقولا لساقينا زياد يرقها ... فقد هد بعض القوم سقي زياد)\nال فوافانا الأعرابي فلما شرب وسمع حنين الدواليب قال صوت\n(بكرت تحن وما به وجدي ... وأحن من وجد إلى نجد)\n(فدموعها تحيا الرياض بها ... ودموع عيني أقرحت خدي)\n(وبساكني نجد كلفت وما ... يغني لهم كلفي ولا وجدي)\n(لو قيس وجد العاشقين إلى ... وجدي لزاد عليه ما عندي)\nال فما انصرف إسحاق إلى بيته إلا محمولا سكرا وما شرب إلا على هذه الأبيات والغناء فيها لإسحاق هزج بالبنصر","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":73,"spl":"إسحاق يغني محمد الأمين"},
{"id":"b52-111","bab":"الجزء 5","sec":"إسحاق والفضل بن الربيع وقصة البساط","page":"ج5 ص381","text":"أخبرني محمد بن مزيد والحسين بن يحيى عن حماد بن إسحاق عن أبيه وأخبرني به الحسن بن علي عن عبد الله بن أبي سعد عن محمد بن عبد الله عن إسحاق قال دخلت على الفضل بن الربيع وهو على بساط سوسنجردي ستيني مذهب يلمع عليه مكتوب مما أمر بصنعته حماد عجرد فقال لي أتدري من حماد عجرد قلت لا قال حماد عجرد كان والي تلك\nالناحية أفرأيت مثله قط قلت لا فسكت ثم قلت أهكذا يفعل الناس قال أي شيء يفعلونه قلت تهبه لي قال لا أفعل قلت إذا أغضب قال ما شئت افعل فخرجت متغاضبا فلما وافيت منزلي إذا برسوله قد لحقني بالبساط فكتبت إليه بيتين لحمزة بن مضر\n(ولقد عددت فلست أحصي كل ما ... قد نلت منك من المتاع المونق)\n(بخديعتي فأراك منخدعا لها ... وفكاهتي وتغضبي وتملقي)\nال ابن أبي سعد في خبره فلما دخلت عليه ضحك وقال لي البيتان خير من البساط فالفضل الآن لك علينا أخبرني يحيى بن علي وأحمد بن جعفر جحظة عن أبي العبيس بن حمدون عن عمرو بن بانة قال رأيت إبراهيم بن المهدي يناظر إسحاق في الغناء فتكلما بما فهماه ولم أفهم منه شيئا فقلت لهما لئن كان ما أنتما فيه من الغناء فما نحن منه في قليل ولا كثير أخبرنا يحيى بن علي قال حدثني أبي قال حدثني إسحاق قال قدمت على الواثق في بعض قدماتي فقال لي أما اشتقت إلي فقلت بلى والله يا أمير المؤمنين وأنشدته\n(أشكو إلى الله بعدي عن خليفته ... وما أعالج من سقم ومن كبر)\n(لا أستطيع رحيلا إن هممت به ... يوما إليه ولا أقوى على السفر)\n(أنوي الرحيل إليه ثم يمنعني ... ما أحدث الدهر والأيام في بصري)\nال وقال وقد أشخصه إليه قصيدته الدالية صوت\n(ضنت سعاد غداة البين بالزاد ... وأخلفتك فما توفي بميعاد)\n(ما أنس لا أنس منها إذ تودعنا ... والحزن منها وإن لم تبده بادي)\nإسحاق في هذين البيتين رمل بالوسطى يقول فيها\n(لما أمرت بإشخاصي إليك هفا ... قلبي حنينا إلى أهلي وأولادي)\n(ثم اعتزمت ولم أحفل ببينهم ... وطابت النفس عن فضل وحماد)\n(كم نعمة لأبيك الخير أفردني ... بها وعم بأخرى بعد إفراد)\n(فلو شكرت أياديكم وأنعمكم ... لما أحاط بها وصفي وتعدادي)\n(لأشكرنك ما ناح الحمام وما ... حدا على الصبح في إثر الدجى حادي)\nال علي بن يحيى قال لي أحمد بن إبراهيم يا أبا الحسن لو قال الخليفة لإسحاق أحضرني فضلا وحمادا أليس كان قد افتضح من دمامة خلقهما وتخلف شاهدهما حدثني جحظة قال حدثني هبة الله بن إبراهيم بن المهدي قال كتب أبي إلى إسحاق في شيء خالفه فيه من التجزئة والقسمة إلى من أحاكمك والناس بيننا حمير","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":74,"spl":"إسحاق والفضل بن الربيع وقصة البساط"},
{"id":"b52-112","bab":"الجزء 5","sec":"إسحاق والرشيد في تل عزاز","page":"ج5 ص383","text":"أخبرني محمد بن خلف وكيع قال حدثنا سليمان بن أيوب قال حدثني محمد بن عبد الله بن مالك الخزاعي قال حدثنا إسحاق قال كنت مع الرشيد حين خرج إلى الرقة فدخل يوما إلى النساء وخرجت فمضيت إلى تل عزاز فنزلت عند خمارة هناك فسقتني شرابا لم أر مثله حسنا وطيبا وطيب رائحة في بيت مرشوش وريحان غض وبرزت\nبنت لها كأنها خوط بان أو جدل عنان لم أر أحسن منها قدا ولا أسيل خد ولا أعتق وجها ولا أبرع ظرفا ولا أفتن طرفا ولا أحسن كلاما ولا أتم تماما فأقمت عندها ثلاثا والرشيد يطلبني فلا يقدر علي ثم انصرفت فذهبت بي رسله فدخلت عليه وهو غضبان فلما رأيته خطرت في مشيتي ورقصت وكانت في فضلة من السكر وغنيت صوت\n(إن قلبي بالتل تل عزاز ... عند ظبي من الظباء الجوازي)\n(شادن يسكن الشآم وفيه ... مع دل العراق ظرف الحجاز)\n(يا لقومي لبنت قس أصابت ... منك صفو الهوى وليست تجازي)\n(حلفت بالمسيح أن تنجز الوعد ... وليست تجود بالإنجاز)\nلغناء لإسحاق خفيف رمل بالوسطى عن عمرو بن بانة قال إسحاق فسكن غضبه ثم قالي لي أين كنت فأخبرته فضحك وقال إن مثل هذا إذا اتفق لطيب أعد غناءك فأعدته فأعجب به وأمرني أن أعيده ليلة من أولها إلى آخرها وأخذها المغنون مني جميعا وشربنا إلى طلوع الفجر ثم انصرفنا فصليت الصبح ونمت فما استقررنا حتى أتى إلي رسول الرشيد فأمرني بالحضور فركبت ومضيت فلما دخلت وجدت ابن جامع قد طرح نفسه يتمرغ على دكان في الدار لغلبة السكر عليه ثم قال أتدري لم دعينا فقلت لا والله قال لكني أدري دعينا بسبب\nنصرانيتك الزانية عليك وعليها لعنة الله فضحكت فلما دخلت على الرشيد أخبرته بالقصة فضحك وقال صدق عودوا فيه فإني اشتقت إلى ما كنا فيه لما فارقتموني فعدنا فيه يومنا كله حتى انصرفنا أخبرنا الحسن بن علي قال حدثنا يزيد بن محمد المهلبي قال كان إسحاق قد أظهر التوبة وغير زيه واحتجر من حضور دار السلطان فبلغه أن المأمون وجد عليه من ذلك وتنكر فكتب إسحاق إليه وغنى فيه بعد ذلك صوت\n(يابن عم النبي سمعا وطاعه ... قد خلعنا الرداء والدراعه)\n(ورجعنا إلى الصناعة لما ... كان سخط الإمام ترك الصناعه)\nلغناء لإسحاق رمل بالبنصر عن عمرو وقد ذكر الغلابي أن هذا الشعر لأبي العتاهية قاله لما حبسه الرشيد وأمره بأن يقول الشعر وذكر حبش أن هذا اللحن لإبراهيم أخبرني يحيى بن علي قال حدثني أبي قال قال لي محمد بن الحسن بن مصعب وكان بصيرا بالغناء والنغم\nلحن إسحاق في تشكى الكميت الجري أحسن من لحن ابن سريج ولحنه في يوم تبدي لنا قتيلة أحسن من لحن معبد وذلك من أجود صنعة معبد قال فأخبرت إسحاق بقوله فقال قد والله أخذت بزمامي راحلتيهما وزعزعتهما وأنخت بهما فما بلغتهما فأخبرت بذلك محمد بن الحسن فقال هو والله يعلم أنه برز عليهما ولكنه لا يدع تعصبه للقدماء وأخبرني جحظة قال حدثني حماد بن إسحاق أن رجلا سأل أباه فقال له إن الناس قد كثروا في صوتيك تشكى الكميت الجري ويوم تبدي لنا قتيلة وقالوا إنهما أجود من لحني ابن سريج ومعبد قال أبي ويحك رميت في هذه الصوتين بمعبد وابن سريج وهما هما فقربت ووقع القياس بيني وبينهما وعلى ذلك فقد والله أخذت بزمامي راحلتيهما وانتصفت منهما","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":75,"spl":"إسحاق والرشيد في تل عزاز"},
{"id":"b52-113","bab":"الجزء 5","sec":"تحليل غنائه في بعض الكتب","page":"ج5 ص386","text":"قرأت في بعض الكتب أن محمد بن الحسن أظنه ابن مصعب ذكر إسحاق الموصلي فقال كانت صنعته محكمة الأصول ونغمته عجيبة الترتيب وقسمته معدلة الأوزان وكان يتصرف في جميع بسط الإيقاعات فأي بساط منها أراد أن يتغنى فيه صوتا قصد أقوى صوت جاء في ذلك البساط لحذاق القدماء فعارضه وقد كان يذهب مذهب الأوائل ويسلك سبيلهم ويقتحم طرقهم فيبني على الرسم فيصنعه ويحتذي على المثال فيحكيه فتأتي صنعته قوية وثيقة يجمع فيها حالتين القوة في الطبع وسهولة المسلك\nوخنثا بين كثرة النغم وترتيبها في الصياح والإسجاح فهي بصنعة الأوائل أشبه منها بصنعة المتوسطين من الطبقات فأما المتأخرون فأحسن أحوالهم أن يرووها فيردوها وكان حسن الطبع في صياحه حسن التلطف لتنزيله من الصياح إلى الإسجاح على ترتيب بنغم يشاكله حتى تعتدل وتتزن أعجاز الشعر في القسمة بصدوره وكذلك أصواته كلها وأكثرها يبتدئ الصوت فيصيح فيه وذلك مذهبه في جل غنائه حتى كان كثير من المغنين يلقبونه الملسوع لأنه يبدأ بالصياح في أحسن نغمة فتح بها أحد فاه ثم يرد نغمته فيرجحها ترجيحا وينزلها تنزيلا حتى يحطها من تلك الشدة إلى ما يوازيها من اللين ثم يعود فيفعل مثل ذلك فيخرج من شدة إلى لين ومن لين إلى شدة وهذا أشد ما يأتي في الغناء وأعز ما يعرف من الصنعة قال يحيى بن علي بن يحيى وقد ذكر إسحاق في صدر كتابه الذي ألف في أخباره وزاد في بعض ما صنعه وكان إسحاق أعلم أهل زمانه بالغناء وأنفذهم في جميع فنونه وأضربهم بالعود وبأكثر آلات الغناء وأجودهم صنعة وقد تشبه بالقديم وزاد في بعض ما صنعه عليه وعارض ابن سريج ومعبدا فانتصف منهما وكان إبراهيم بن المهدي ينازعه في هذه الصناعة ولم يبلغه فيها ولم يكن بعد إسحاق مثله أخبرنا يحيى بن علي بن يحيى قال حدثنا أبو أيوب المديني قال حدثني إبراهيم بن علي بن هشام قال إسحاق وذكر صوته صوت\n(كان افتتاح بلائي النظر ... فالحين سبب ذاك والقدر)\n(قد كان باب الصبر مفتتحا ... فاليوم أغلق بابه النظر)\nالشعر والغناء لإسحاق ثقيل أول مطلق في مجرى البنصر وفيه لأحمد بن المكي خفيف ثقيل ولعريب ثاني ثقيل جميعا عن الهشامي قال إسحاق ما شبهت صوتي هذا إلا بإنسان أخذ الكرة على الطبطابة وأهل الميدان جميعا خلفه فلما بلغ أقصى ضربها أحجزها","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":76,"spl":"تحليل غنائه في بعض الكتب — قصته مع يحيى بن معاذ والأمين"},
{"id":"b52-114","bab":"الجزء 5","sec":"قصته مع يحيى بن معاذ والأمين","page":"ج5 ص388","text":"أخبرني الحسن بن علي قال حدثنا محمد بن يزيد المهلبي قال حدثني إسحاق وأخبرنا يحيى بن علي عن أبي أيوب المديني عن ابن المكي عن إسحاق قال صنعت هذا الصوت في آخر أيام الرشيد وكان إذ ذاك يحيى بن معاذ يشرب النبيذ فلما كان في أيام محمد غنيته فاشتهاه واشتهر به وبعث إلى يحيى بن معاذ وأنا أغنيه\n(اسقني وابن نهيك ... وابن يحيى بن معاذ)\nلما حضر يحيى غنيت\n(فاسقني واسق نهيكا ... واسق يحيى بن معاذ)\nبعث إليه محمد فأحضره فقال لتشربن أو لأعاقبنك فلم يبرح حتى شرب قدحا وغلفه وأمر له بمال وسر بذلك محمد ووهب لي عليه مالا وانصرفت إلى البيت فجاءني رسول يحيى بن معاذ فصرت إليه فلم يزل يستحلفني ألا أعود في هذا الصوت قدام محمد أبدا وأمر لي من المال بشيء فلم أقبله ولم أعد فيه","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":76,"spl":"تحليل غنائه في بعض الكتب — قصته مع يحيى بن معاذ والأمين"},
{"id":"b52-115","bab":"الجزء 5","sec":"نسبة هذا الصوت","page":"ج5 ص389","text":"صوت\n(يومنا يوم رذاذ ... واصطباح والتذاذ)\n(فاسقني وابن نهيك ... وابن يحيى بن معاذ)\n(من كميت عتقت للشيخ ... كسرى بن قباذ)\n(ليس للمرء من الهم ... سواها من ملاذ)\nلشعر لعلي بن هشام والغناء لإسحاق ثقيل أول بالبنصر عن عمرو أخبرني بقوله علي بن هشام والحسن بن علي قالا حدثنا عبد الله بن أبي سعد قال حدثني أحمد بن القاسم الهاشمي قال حدثني أبو عبد الله الهلالي قال كنت عند علي بن هشام يوما إذ رشت السماء رشا وطشت فأنشأ علي يقول\n(يومنا يوم رذاذ ... واصطباح والتذاذ)\nذكر الأبيات الأربعة ثم قال لغلامه اذهب إلى أحمد بن يحيى بن معاذ وقل له يقول لك أخوك هذا يوم طيب فتعال أنت وغلاماك بنان وعثعث فجاء إلى بابه الرسول وعليه غرماء له فمنعوه الدخول عليه فقال لهم كم لكم عليه قالوا مائتا ألف درهم فرجع الغلام إلى علي بن هشام فأخبره بالخبر ومبلغ ما لهم عليه من الدين فقال له احمل إليه مائتي ألف ردهم وجئ به وبغلاميه الساعة فحملها فجاء أحمد بن يحيى ومعه\nغلاماه فقال لعلي بن هشام لم تحملت هذا لي أنا والله منتظر ما لا يجيء فأعطيهم فقال له مالي ومالك واحد فتغديت معهما حتى جاءت الحلواء فقال أكثر من الحلواء فلست تدخل معنا في ديواننا يعني الشرب فأكلت وغسلت يدي فقال لغلامه سراج احمل مع أبي عبد الله الهلالي ثلاثين ألف درهم فانصرفت وهي معي","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":77,"spl":"نسبة هذا الصوت — إسحاق يتذكر شعر الصبا ويبكي"},
{"id":"b52-116","bab":"الجزء 5","sec":"إسحاق يتذكر شعر الصبا ويبكي","page":"ج5 ص390","text":"أخبرنا يحيى بن علي قال حدثنا سليمان المدائني عن ابن المكي عن أبيه قال حدثني إسحاق قال تعشقت جارية فقلت فيها\n(هل إلى أن تنام عيني سبيل ... إن عهدي بالنوم عهد طويل)\n(غاب عني من لا أسمي فعيني ... كل يوم عليه حزنا تسيل)\nلشعر والغناء لإسحاق رمل بالبنصر عن عمرو وفيه لعريب خفيف رمل آخر وفيه لمحمد بن حمزة وجه القرعة خفيف ثقيل وقيل إنه لابن المكي وفيه رمل بالوسطى ينسب إلى علويه وإلى حسين بن محرز قال إسحاق ثم ملكتها فكنت مشغوفا بها حتى كبرت واعتلت علي عيناي فذكرت هذا الصوت وأيامه المتقدمة فما زلت أبكي وأذكر دهري الذي تولى وأخبرني بهذا الخبر الحسن بن علي عن يزيد المهلبي عن إسحاق وليس هذا على التمام أخبرني جحظة عن محمد بن أحمد بن يحيى المكي عن أبيه قال دعا المأمون بإسحاق فأحضره فأمره أن يغني في هذا الصوت فغنى\n(هل إلى أن تنام عيني سبيل ... )\nغناه وكنت حاضرا فقلت أحسن والله يا أمير المؤمنين وما عدا بلحنه معنى شعره فقال المأمون فإنا نرد الحكم إلى من هو أعلم بذلك منك فبعث إلى أبي يعني يحيى المكي فجيء به فخبره بما قلت وما قال وأمر إسحاق برد الصوت فرده فقال يحيى أحسن إسحاق في غنائه وأحسن ابني في استحسانه إلا أن هذا اللحن يحتاج أن يسمع من غير حلق إسحاق فضحك المأمون وأمر لإسحاق بمال وأمر لأبي بمثله ولي بمثله قال ولم يكن في إسحاق شيء يعاب إلا حلقه وكان يغلب الناس جميعا بطبعه وحذقه قال وأما السبب في علة عين إسحاق وضعف بصره فأخبرني به محمد بن خلف وكيع قال حدثني به أبو أيوب المديني قال حدثني محمد بن عبد الله بن مالك الخزاعي أن إبراهيم ابن أخي سلمة الوصيف نازع إسحاق في شيء بين يدي الرشيد من الغناء فرد عليه فشتمه فرد عليه إسحاق واربى في الرد فقال له إبراهيم أترد علي وأنا مولى أمير المؤمنين فقال له اسكت فإنك من موالي العيدين فقال له الرشيد وأي شيء موالي العيدين قال يا أمير المؤمنين يشترى للخلفاء كل صانع وكل ضرب في العبيد للعتق فيكون فيهم الحجام والحائك والسائس فهو أحد هؤلاء الذين ذكرت قال وخرج إبراهيم فوقف له على طريقه فلما جاز عليه منصرفا ضرب رأسه بمقرعة فيها معول فكان ذلك سبب ضعف بصر إسحاق وبلغ الرشيد الخبر فأمر بأن يحجب عنه إبراهيم وحلف ألا يدخل عليه فدس إلى الرشيد من غناه\nصوت\n(من لعبد أذله مولاه ... ماله شافع إليه سواه)\n(يشتكي ما به إليه ويخشاه ... ويرجوه مثل ما يخشاه)\nلشعر لأبي العتاهية والغناء لإبراهيم ابن أخي سلمة الوصيف خفيف رمل وفيه لعريب ثقيل أول وقيل إن لابن جامع فيه خفيف رمل آخر فلما غني الرشيد بهذه الأبيات سأل عن صاحب لحنها فعرفه فحلف ألا يرضى عنه حتى يرضى إسحاق فقال إسحاق فقال قد رضيت عنه يا سيدي رضاء حسنا وقبل الأرض بين يديه شكرا لما كان من قوله فرضي عنه وأحضر وأمره بترضي إسحاق ففعل","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":77,"spl":"نسبة هذا الصوت — إسحاق يتذكر شعر الصبا ويبكي","partialRef":{"sid":"b52-94","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b52-117","bab":"الجزء 5","sec":"إسحاق وإبراهيم ابن أخي سلمة","page":"ج5 ص392","text":"وأخبرني محمد بن مزيد قال حدثنا حماد عن أبيه قال جاء إبراهيم ابن أخي سلمة إلى الرشيد فقال له يا أمير المؤمنين إني أحب أن تشرفني بأن تكون نوبتي ونوبة إسحاق الموصلي في مكان وأن يكون دخولي إليك ودخوله في مكان فإن رأيت أن تجعل ذلك كما سألت فعلت قال قد فعلت ولم أكن حاضرا لمسألته فلما كان يوم دخولي عليه جاءني إبراهيم فدق بابي دقا عنيفا وعرفني الغلام خبره فقلت له يدخل فأبى وقال له قل له اخرج أنت فساء ظني واغتممت فخرجت إليه فقلت له ما الخبر قال إن أمير المؤمنين يأمرك بالحضور ويأمرك ألا تدخل الدار إلا معي بعد أن أوجه إليك فتركب إلي وتمضي معي فمضيت معه على رغمي وأنا منكسر وكنت بقية يومي على تلك الحال ثم ركبت إلى الفضل بن الربيع فشكوت ذلك إليه فقال ما أرى أمير المؤمنين يحلك هذا المحل قم بنا إليه فقمت معه فدخل إلى الرشيد فقال له يا أمير المؤمنين إسحاق وخدمته وحقوق أبيه عليك وعلى أمير المؤمنين المهدي\nتضع مقداره أن تجعله مضموما إلى إبراهيم ابن أخي سلمة قال لا والله ما فعلت هذا قال إنه قد جاءني يبكي ويحلف إن جرى عليه هذا تاب من الغناء وتركه جملة ثم لو قتل لم يعد إليه فقال ويحك والله ما جرى من هذا شيء إلا أن إبراهيم ابن أخي سلمة جاء فقال تشرفني أن تجعل نوبتي مع نوبة إسحاق ووصولي مع وصوله ففعلت فقل له يجيء متى شاء وينفرد عنه ولا يجيء معه ولا كرامة فأخبرني فرجعت فلما كانت نوبتي جاء إبراهيم إلي ففعل مثل فعله فقلت لغلامي اخرج إليه فقل له ولا كرامة لك يا زاني يابن الزانية لا أجيء معك ولا أدعك تجيء معي أيضا وشتمه أقبح شتم فخرج الغلام فأدى إليه الرسالة فعلم أن هذا لم يتجرأ عليه إلا بعد توثق فخجل فقال له قل له ومن أكرهك على هذا إنما أحببت أن نصطحب ونتأنس في طريقنا فإن كرهت هذا فلا تفعله وانصرف ولم يعاودني بعدها أخبرني يحيى بن علي قال حدثنا أبو أيوب المديني عن ابن المكي عن أبيه قال كان إسحاق إذا غنى هذا الصوت يأخذ بلحيته ويبكي\n(إذا المرء قاسى الدهر وابيض رأسه ... وثلم تثليم الإناء جوانبه)\n(فللموت خير من حياة خسيسة ... تباعده طورا وطورا تقاربه)\nلشعر لزبان بن سيار الفزاري حدثني بذلك الحرمي بن أبي العلاء عن الزبير بن بكار عن عمه والغناء لإسحاق رمل بالوسطى\nأخبرنا محمد بن مزيد والحسين بن يحيى عن حماد عن أبيه وأخبرنا يحيى بن علي عن أبيه عن إسحاق قال أقام المأمون بعد قدومه عشرين شهرا لا يسمع حرفا من الأغاني فكان أول من تغنى بحضرته أبو عيسى بن الرشيد ثم واظب على السماع متسترا متشبها في أول أمره بالرشيد فأقام كذلك أربع حجج ثم ظهر إلى الندماء والمغنين وكان حين أحب السماع سأل عني فجرحت بحضرته وقال الطاعن علي ما يقول أمير المؤمنين في رجل يتيه على الخلافة قال المأمون ما أبقى هذا من التيه شيئا إلا استعمله فأمسك عن ذكري وجفاني من كان يصلني لسوء رأيه الذي ظهر في فأضر ذلك بي حتى جاءني علويه يوما فقال لي أتأذن لي في ذكرك فإنا قد دعينا اليوم فقلت لا ولكن غنه بهذا الشعر فإنه سيبعثه على أن يسألك لمن هذا فإذا سألك انفتح لك ما تريد وكان الجواب أسهل عليك من الابتداء فقال هات فألقيت عليه لحني في شعري صوت\n(يا سرحة الماء قد سدت موارده ... أما إليك طريق غير مسدود)\n(لحائم حام حتى لا حيام له ... محلأ عن طريق الماء مطرود)\nالغناء لإسحاق رمل بالوسطى عنه وعن عمرو قال فمضى علويه فلما استقر به المجلس غناه بالشعر الذي أمرته فما عدا المأمون أن يسمع الغناء حتى قال ويحك يا علويه لمن هذا قال يا سيدي لعبد من عبيدك جفوته واطرحته من غير جرم فقال أإسحاق تعني قال نعم\nقال يحضر الساعة فجاءني رسوله فصرت إليه فلما دخلت عليه قال ادن فدنوت فرفع يديه مادهما فانكببت عليه واحتضنني بيديه وأظهر من بري وإكرامي ما لو أظهره صديق مؤانس لصديقه لبره","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":78,"spl":"إسحاق وإبراهيم ابن أخي سلمة"},
{"id":"b52-118","bab":"الجزء 5","sec":"إسحاق يغني المعتضد","page":"ج5 ص395","text":"أخبرني محمد بن إبراهيم الجرجاني قريض قال قال لي أحمد بن أبي العلاء غنيت المعتضد يوما وهو أمير صوت إسحاق\n(يا سرحة الماء قد سدت موارده ... أما إليك طريق غير مسدود)\nطرب واستعاده مرارا وقال هذا والله الغناء الذي يخالط الروح ويمازج اللحم والدم أخبرنا يحيى بن علي قال حدثنا أبو العبيس بن حمدون قال أخبرني أبي قال لما غنى إسحاق في شعره هذا صوت\n(لأسماء رسم عفا باللوى ... أقام رهينا لطول البلى)\n(تعاوره الدهر في صرفه ... بكر الجديدين حتى عفا)\nالشعر لإسحاق من قصيدة مدح بها الرشيد والغناء له ثاني ثقيل بالوسطى وفيه لسليم ثقيل أول من رواية الهشامي وذكر حبش أنه لإبراهيم ابن المهدي قال فكان الناس يتهادون الطرفة والباكورة وقال أبو العبيس حدثني ابن مخارق أن الواثق بعث إلى أبيه مخارق لما صنع إسحاق هذا الصوت ليلقيه عليه فصادفه عليلا ولم يكن أحد يلقن عن إسحاق طرح الغناء كما يلقنه مخارق فأعاد إليه الرسول ومعه محفة لا بد أن يجيء على كل حال فتحامل وصار إليه حتى أخذ الصوت عن إسحاق ورجع وذكر محمد بن الحسين الكاتب عن أبي حارثة الباهلي عن أخيه أبي معاوية أن إسحاق كان يتحلى بالشجاعة والفروسية ويحب أن ينسب إليهما ويركب الخيل ويتعلم بها آفة من الآفات المعترضة على العقول وكان قد شهد بعض مشاهد الحروب فأصابه سهم فنكص على عقبيه فقال أخوه طياب فيه\n(وأنت تكلفت ما لا تطيق ... وقلت أنا الفارس الموصلي)\n(فلما أصابتك نشابة ... رجعت إلى سنك الأول)\nخبرنا يحيى بن علي بن يحيى عن أبيه عن إسحاق قال قال حمزة الزيات القارئ يا موصلي إن لي فيك رأيا أفترضى\nمع فهمك وأدبك ورأيك أن يكون عوضك من الآخرة فضل مطعم على مطعم حدثني علي بن سليمان الأخفش قال أنشدني أبو سعيد السكري قال أنشدني عبد الرحمن ابن أخي الأصمعي لعمه يقول لإسحاق\n(أئن تغنيت للشرب الكرام ألا ... رد الخليط جمال الحي فانفرقوا)\n(وقيل أحسنت فاستدعاك ذاك إلى ... ما قلت ويحك لا يذهب بك الخرق)\n(وقيل أنت حسان الناس كلهم ... وابن الحسان فقد قالوا وقد صدقوا)\n(فما بهذا تقوم الناديات ولا ... يثنى عليك إذا ما ضمك الخرق)\nال يحيى بن علي إن هذه الأبيات تروى لابن المنذر العروضي وللأصمعي","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":79,"spl":"إسحاق يغني المعتضد"},
{"id":"b52-119","bab":"الجزء 5","sec":"إسحاق والأصمعي","page":"ج5 ص397","text":"قال مؤلف هذا الكتاب كان إسحاق يأخذ عن الأصمعي ويكثر الرواية عنه ثم فسد ما بينهما فهجاه إسحاق وثلبه وكشف للرشيد معايبه وأخبره بقلة شكره وبخله وضعة نفسه وأن الصنيعة لا تزكو عنده ووصف له أبا عبيدة معمر بن المثنى بالثقة والصدق والسماحة والعلم وفعل مثل ذلك للفضل\nابن الربيع واستعان به ولم يزل حتى وضع مرتبة الأصمعي وأسقطه عندهم وأنفذوا إلى أبي عبيدة من أقدمه أخبرني أبو الحسن الأسدي قال حدثنا حماد بن إسحاق عن أبيه قال أنشدت الفضل بن الربيع أبياتا كان الأصمعي أنشدنيها في صفة فرس\n(كأنه في الجل وهو سامي ... مشتمل جاء من الحمام)\n(يسور بين السرج واللجام ... سور القطامي إلى اليمام)\nال ودخل الأصمعي فسمعني أنشدها فقال هات بقيتها فقلت له ألم تقل إنه لم يبق منها شيء فقال ما بقي منها إلا عيونها ثم أنشد بعد هذه الأبيات ثلاثين بيتا منها فغاظني فعله فلما خرج عرفت الفضل بن الربيع قلة شكره لعارفه وبخله بما عنده ووصفت له فضل أبي عبيدة معمر ابن المثنى وعلمه ونزاهته وبذله لما عنده واشتماله على جميع علوم العرب ورغبته فيه حتى أنفذ إليه مالا جليلا واستقدمه فكنت سبب مجيئه به من البصرة أخبرني عمي قال حدثنا فضل اليزيدي عن إسحاق قال جاء عطاء الملك بجماعة من أهل البصرة إلى قريب أبي الأصمعي وكان نذلا من الرجال فوجده ملتفا في كسائه نائما في الشمس فركضه برجله وصاح به يا قريب قم ويلك فقال له هل لقيت أحدا من أهل\nالعلم قط أو من أهل اللغة أو من العرب أم من الفقهاء أو من المحدثين قال لا والله قال ولا سمعت شيئا ترويه لنا أو تنشدناه أو نكتبه عنك قال لا والله فقال لمن حضر هذا أبو الأصمعي فاشهدوا لي عليه وعلى ما سمعتم منه لا يقل لكم غدا أو بعده حدثني أبي أو أنشدني أبي ففضحه قال الفضل ثم مرض الأصمعي وكان الحال بينه وبين إسحاق الموصلي انفرجت فعاده أبو ربيعة وكان يرغب في الأدب ويبر أهله فقال له الأصمعي أقرضني خمسة آلاف درهم فقال أفعل فقال له أبو ربيعة فأي شيء تشتهي سوى هذا فقال أشتهي أن تهدي إلي فصا حسنا وسيفا قاطعا وبردا حسنا وسرجا محلى فقال أفعل وبعث بذلك إليه لما عاد إلى منزله وبلغ ذلك إسحاق فقال\n(أليس من العجائب أن قردا ... أصيمع باهليا يستطيل)\n(ويزعم أنه قد كان يفتي ... أبا عمرو ويسأله الخليل)\n(إذا ما قال قال أبي عجبنا ... لما يأتي به ولما يقول)\n(وما إن كان يدري ما دبير ... أبوه إن سألت وما قبيل)\n(وجلله عطاء الملك عارا ... تزول الراسيات ولا يزول)\n(نصحت أبا ربيعة فيه جهدي ... وبعض النصح أحيانا ثقيل)\n(فقل لأبي ربيعة إذ عصاني ... وجار به عن القصد السبيل)\n(لقد ضاعت برودك فاحتسبها ... وضاع الفص والسيف الصقيل)\n(وسرج كان للبرذون زينا ... له في إثره جزعا صهيل)\n(وأما الخمسة الآلاف فاعلم ... بأنك غبنها لا تستقبل)\n(وأن قضاءها فتعز عنها ... سيأتي دونه زمن طويل)\nدثني محمد بن مزيد قال حدثني حماد بن إسحاق عن أبيه قال كنت جالسا بين يدي الواثق وهو ولي عهد إذ خرجت وصيفة من القصر كأنها خوط بان أحسن من رأته عيني قط تقدم عدة وصائف بأيديهن المذاب والمناديل ونحو ذلك فنظرت إليها نظر دهش وهو يرمقني فلما تبين إلحاح نظري قال ما لك يا أبا محمد قد انقطع كلامك وبانت الحيرة فيك فتلجلجت فقال لي رمتك والله هذه الوصيفة فأصابت قلبك فقلت غير ملوم فضحك ثم قال أنشدني في هذا المعنى فأنشدته قول المرار\n(ألكني إليها عمرك الله يا فتى ... بآية ما قالت متى هو رائح)\n(وآية ما قالت لهن عشية ... وفي الستر حرات الوجوه ملائح)\n(تخيرن أرماكن فارمين رمية ... أخا أسد إذ طرحته الطوارح)\n(فلبسن مسلاس الوشاح كأنها ... مهاة لها طفل برمان راشح)\nقال له الواثق أحسنت بحياتي وظرفت اصنع فيها لحنا فإن جاء كما نريد وأطربنا فالوصيفة لك فصنعت فيه لحنا وغنيته إياه فاصطبح عليه وشرب بقية يومه وليلته حتى سكر ولم يقترح علي غيره وانصرفت بالجارية","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":80,"spl":"إسحاق والأصمعي"},
{"id":"b52-120","bab":"الجزء 5","sec":"يغني الواثق وهو خاثر النفس فيهش إليه","page":"ج5 ص401","text":"حدثني عمي قال حدثني فضل اليزيدي عن إسحاق قال دخلت على الواثق يوما وهو خاثر النفس فأخذت عودا من الخزانة ووقفت بين يديه فغنيته\n(من الظباء ظباء همها السخب ... نرعى القلوب وفي قلبي لها عشب)\n(أهوى الظباء اللواتي لا قرون لها ... وحليها الدر والياقوت والذهب)\n(لا يغتربن ولا يسكن بادية ... وليس يعرفن ما صر ولا حلب)\n(وفي الذين غدوا نفسي الفداء لهم ... شمس تبرقع أحيانا وتنتقب)\n(يا حسن ما سرقت عيني وما انتهبت ... والعين تسرق أحيانا وتنتهب)\n(إذا يد سرقت فالقطع يلزمها ... والقطع في سرق العينين لا يجب)\nقال فهش إلي ونشط ودعا بطعام خفيف وأكلنا واصطبح وأمر لي بمائة ألف درهم وأخبرني به الحسن بن علي عن ابن مهرويه عن علي بن الحسن عن إبراهيم بن محمد الكرخي عن إسحاق فذكر مثله وقال فيه فأمر لي بعشرة آلاف درهم حدثني جعفر بن قدامة قال حدثني عبيد الله بن عبد الله بن طاهر عن أخيه محمد قال كان إسحاق الموصلي يدخل في مبطنة وطيلسان مثل زي الفقهاء على المأمون فسأله أن يأذن له في دخول المقصورة يوم الجمعة بدراعة سوداء وطيلسان أسود فتبسم المأمون وقال له ولا كل هذا بمرة يا إسحاق ولكن قد اشترينا منك هذه المسألة بمائة ألف درهم حتى لا تغتم وأمر بحملها إليه فحملت حدثني جعفر بن قدامة قال حدثني عبيد الله بن عبد الله قال حدثني هارون بن محمد بن عبد الملك الزيات عن أبي خالد الأسلمي أنه ذكر إسحاق يوما وكان يفضله ويعظم شأنه ويقدمه في الشعر تقديما مفرطا فقال ما قولكم في رجل محدث تشبه بذي الرمة وقال على لسانه\nشعرا وغنى فيه ونسبه إليه فلم يشكك أحد سمعه أنه له ولا فطن لما فعل أحد إلا من حصل شعر ذي الرمة كله ورواه فسئل أبو خالد عن هذا الشعر فقال\n(ومدرجة للريح تيهاء لم تكن ... ليجشمها زميلة غير حازم)\n(يضل بها الساري وإن كان هاديا ... وتقطع أنفاس الرياح النواسم)\n(تعسفت أفري جوزها بشملة ... بعيدة ما بين القرا والمناسم)\n(كأن شرار المرو من نبذها به ... نجوم هوت أخرى الليالي العواتم)\nدثني عمي وأحمد بن عبيد الله بن عمار قال حدثنا فضل اليزيدي عن إسحاق قال غنيت المأمون يوما هذين البيتين\n(لأحسن من قرع المثاني ورجعها ... تواتر صوت الثغر يقرع بالثغر)\n(وسكر الهوى أروى لعظمي ومفصلي ... من الشرب في الكاسات من عاتق الخمر)\nقال لي المأمون ألا أخبرك بأطيب من ذلك وأحسن الفراغ والشباب والجدة حدثني الصولي قال حدثني الحسين بن يحيى قال\nكان لإسحاق غلام يقال له فتح يستقي الماء لأهل داره على بغلين من بغاله دائما فقال إسحاق قلت له يوما أي شيء خبرك يا فتح قال خبري أنه ليس في هذه الدار أحد أشقى مني ومنك قلت وكيف ذلك قال أنت تطعم أهل الدار الخبز وأنا أسقيهم الماء فاستظرفت قوله وضحكت منه ثم قلت له فأي شيء تحب قال تعتقني وتهب لي البغلين أستقي عليهما فقلت له قد فعلت أخبرني أبو الحسن أحمد بن محمد الأسدي قال حدثنا حماد بن إسحاق قال كان لأبي البصير الشاعر قيان وكان يتكلم في الغناء بغير علم ولا صواب فيضحك منه فقال أبي فيه\n(سكت عن الغناء فما أماري ... بصيرا لا ولا غير البصير)\n(مخافة أن أجنن فيه نفسي ... كما قد جن فيه أبو البصير)","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":81,"spl":"يغني الواثق وهو خاثر النفس فيهش إليه"},
{"id":"b52-121","bab":"الجزء 5","sec":"الرشيد ينهاه عن الغناء","page":"ج5 ص404","text":"أخبرني الحسين بن يحيى المرداسي قال حدثنا حماد بن إسحاق عن أبيه قال نهاني الرشيد أن أغني أحدا غيره ثم استوهبني جعفر بن يحيى وسأله أن يأذن لي في أن أغنيه ففعل واتفقنا يوما عند جعفر بن يحيى وعنده أخوه الفضل والرشيد يومئذ بعقب علة قد عوفي منها وليس يشرب فقال لي الفضل انصرف إلي الليلة حتى أهب لك مائة ألف درهم فقلت له إن الرشيد قد نهاني ألا أغني إلا له أو لأخيك وليس يخفى عليه خبري وأنا متهم عنده بالميل إليكم ولست أتعرض له ولا أعرضك ولم أجبه فلما نكبهم الرشيد قال إيه يا إسحاق تركتني بالرقة وجلست ببغداد تغني للفضل بن يحيى فحلفت بحياته أني ما جالسته قط إلا على المذاكرة\nوالحديث وأنه ما سمعني قط أغني إلا عند أخيه جعفر وحلفت بتربة المهدي أن يسأل عن هذا جميع من في الدار من نسائه فسأل عنه فحدثنه بمثل ما ذكرته له وعرف خبر المائة الألف الدرهم التي بذلها لي فرددتها عليه فلما دخلت عليه ضحك إلي ثم قال قد سألت عن أمرك فعرفت منه مثل ما عرفتني وقد أمرت لك بمائة ألف درهم عوضا مما بذله لك الفضل حدثني الصولي قال حدثني ميمون بن هارون عن إسحاق أنه كان يقول الإسناد قيد الحديث فتحدث مرة بحديث لا إسناد له فسئل عن إسناده فقال هذا من المرسلات عرفا حدثني الصولي قال حدثني ميمون بن هارون عن أبيه وحدثني عمي عبد الله بن أبي سعد قال حدثني محمد بن عبد الله بن مالك عن إسحاق قال أنشدت الفضل بن يحيى قول أبي الحجناء نصيب مولى المهدي فيهم صوت\n(عند الملوك مضرة ومنافع ... وأرى البرامك لا تضر وتنفع)\n(إن كان شر كان غيرهم له ... أو كان خير فهو فيهم أجمع)\n(إن العروق إذا استسر بها الثرى ... أشر النبات بها وطاب المزرع)\n(فإذا جهلت من امرئ أعراقه ... وقديمه فانظر إل ما يصنع)\nال فقال كأنا والله لم نسمع هذا الشعر قط قد كنا وصلناه بثلاثين ألف درهم وإذا نجدد له الساعة صلة له ولك معه لحفظك الأبيات فوصلنا بثلاثين ألف درهم","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":82,"spl":"الرشيد ينهاه عن الغناء — المأمون يعتب عليه فيسترضيه بشعر"},
{"id":"b52-122","bab":"الجزء 5","sec":"المأمون يعتب عليه فيسترضيه بشعر","page":"ج5 ص405","text":"وأخبرني الصولي قال حدثني الحسن بن يحيى الكاتب أبو الجماز قال عتب المأمون على إسحاق في شيء فكتب إليه رقعة وأوصلها إليه من يده ففتحها المأمون فإذا فيها قوله\n(لا شيء أعظم من جرمي سوى أملي ... لحسن عفوك عن ذنبي وعن زللي)\n(فإن يكن ذا وذا في القدر قد عظما ... فأنت أعظم من جرمي ومن أملي)\nضحك ثم قال يا إسحاق عذرك أعلى قدرا من جرمك وما جال بفكري ولا أخطرته بعد انقضائه على ذكري","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":82,"spl":"الرشيد ينهاه عن الغناء — المأمون يعتب عليه فيسترضيه بشعر"},
{"id":"b52-123","bab":"الجزء 5","sec":"إسحاق وابن بانة في مجلس الواثق","page":"ج5 ص406","text":"حدثني عمي قال حدثني يزيد بن محمد المهلبي قال خرجنا مع الواثق إلى القاطول للصيد ومعنا جماعة الجلساء والمغنين وفيهم عمرو بن بانة وعلويه ومخارق وعقيد وقدم إسحاق في ذلك الوقت فأخرجه معه فتصيد على القاطول ثم عاد فأكل وشرب أقداحا ثم أمر بالبكور إلى الصبوح فباكرنا واصطبحنا فغنى عمرو بن بانة لحن إبراهيم الموصلي صوت\n(بلوت أمور الناس طرا فأصبحت ... مذممة عندي براء من الحمد)\n(وأصبح عندي من وثقت بغيبه ... بغيض الأيادي كل إحسانه نكد)\nولحنه خفيف رمل بالوسطى فغناه على ما أخذه من إبراهيم بن المهدي وقد غيره فقال الواثق لإسحاق أتعرف هذا اللحن فقال نعم هذا لحن أبي ولكنه مما زعم إبراهيم بن المهدي أنه جندره وأصلحه فأفسده ودمر عليه فقال له غنه أنت فغناه فأتى به على حقيقته واستحسنه الواثق جدا فغم ذلك عمرو بن بانة فقال لإسحاق أفأنت مثل إبراهيم بن المهدي حتى تقول هذا فيه قال لا والله ما أنا مثله أما على الحقيقة فأنا عبده وعبد أبيه وليس هذا مما نحن فيه وأما الغناء فما دخولك أنت بيننا فيه ما أحسنت قط أن تأخذ فضلا عن أن تغني ولا قمت بأداء غناء فضلا عن أن تميز بين المحسنين وإلا فغن أي صوت شئت مما أخذته عنه وعن غيره كائنا من كان فإن لم أوضح لك ولمن حضر أنه لا يسلم لك صوت من نقصان أجزاء وفساد صنعة فدمي به رهن فأساء عمرو الجواب وأغلظ في القول فأمضه الواثق وشتمه وأمر بإقامته عن مجلسه فأقيم فلما كان من الغد دخل إسحاق على الواثق فأنشده\n(ومجلس باكرته بكورا ... والطير ما فارقت الوكورا)\n(والصبح لم يستنطق العصفورا ... على غدير لم يكن دعثورا)\n(لم تر عيني مثله غديرا ... يجري حباب مائة مسجورا)\n(على حصى تحسبه كافورا ... تسمع للماء به خريرا)\n(ينسج أعلى متنه سطورا ... نسيم ريح قد ونت فتورا)\n(حتى تخال متنه حصيرا ... والشرب قد حفوا به حضورا)\n(وأمروا الساقي أن يديرا ... كأسهم الأصغر والكبيرا)\n(وأعملوا البم معا والزيرا ... وجاوبت عيدانهم زميرا)\n(وقربوا المغني النحريرا ... مقدما في حذقه مشهورا)\n(فهم يطيرون به سرورا ... ولا ترى في شربهم تقصيرا)\n(ولا لصفو عيشهم تكديرا ... ولا لخلق منهم نظيرا)\n(إلا رجيلا منهم سكيرا ... معربدا موضحا شريرا)\n(مدعيا للعلم مستعيرا ... يروم سعيا كاذبا مغرورا)\n(وأن يكون عالما بصيرا ... مفضلا بعلمه مذكورا)\n(غمزته ولم يكن صبورا ... فعاذ مني هاربا مذعورا)\n(بمعسر تحسبهم حميرا ... أشد منهم حمقا كثيرا)\n(لا ينطقون الدهر إلا زورا ... حتى إذا كسرته تكسيرا)\n(كالليث لما ضغم الخنزيرا ... ولى انهزاما خاسئا مدحورا)\n(معترفا بذله مقهورا ... وكنت قدما ضيغما هصورا)\n(معتليا لقرنه عقورا ... وما أخاف الزمن العثورا)\n(إذ كنت بالواثق مستجيرا ... قد عز من كان له نصيرا)\n(إمام عدل دبر الأمورا ... برأيه ولم يرد مشيرا)\n(ترى من الحق عليه نورا ... تقبل المهدي والمنصورا)\n(وجده الأدنى تقى وخيرا ... ورثه المعتصم التدبيرا)\n(فأصبح الملك به منيرا ... وأصبح العدل به منشورا)\n(قد أمن الناس به المحظورا ... إذا علا المنبر والسريرا)\n(رأيت بدرا طالعا منيرا ... بحرا ترى الغني والفقيرا)\n(يرجون منه نائلا غزيرا ... والله لا زلت له شكورا)\n(لا جاحد النعمى ولا كفورا ... وكنت بالشكر له جديرا)\nحدثني الصولي قال حدثني ميمون بن هارون قال سمعت إسحاق يقول أنشدني الأصمعي قول الأعشى\n(إن تركبوا فركوب الخيل عادتنا ... أو تنزلون فإنا معشر نزل)\nم قلت له أي شيء تحفظ في هذا المعنى وكان مع بخله بالعلم لا يبخل بمثل هذا فأنشدني لربيعة بن مقروم الضبي\n(ولقد شهدت الخيل يوم طرادها ... بسليم أوظفة القوائم هيكل)\n(فدعوا نزال فكنت أول نازل ... وعلام أركبه إذا لم أنزل)\nدثني عمي قال حدثنا عبد الله بن أبي سعد قال حدثني محمد ابن محمد بن مروان قال حدثني عبد الله بن العباس بن الفضل بن الربيع قال اجتمعنا يوما إما قال في منزلي أو في منزل محمد بن الحارث بن بسخنر ودخلنا ودخل إلينا إسحاق الموصلي وعندنا ملاحظ تغنينا وقد قامت الصلاة فدخل إسحاق وهي غائبة فقال فيم كنتم ومن عندكم فأخبرناه","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":83,"spl":"إسحاق وابن بانة في مجلس الواثق"},
{"id":"b52-124","bab":"الجزء 5","sec":"إسحاق وابن بانة في مجلس الواثق","page":"ج5 ص406","text":"بخبرها فقال لا تعرفوها من أنا فيخرجها التصنع لي والتحفظ مني عن طبعها ولكن دعوها وهواها حتى ننتفع بها وخرجت وهي لا تعرفه وجلست كما كانت أولا وابتدأت وغنت والصنعة لفليح بن أبي العوراء ولحنه رمل هكذا أخبرنا إسحاق أن الغناء لفليح صوت\n(إني تعلقت ظبيا شادنا خرقا ... علقته شقوة مني وما علقا)\nال فطرب إسحاق وشرب حتى والى بين خمسة أقداح من نبيذ شديد كان بين يديه وهو يستعيدها فأخذ إسحاق دواة وكتب\n(سأشرب ما دامت تغني ملاحظ ... وإن كان لي في الشيب عن ذاك واعظ)\n(ملاحظ غنينا بعيشك وليكن ... عليك لما استحفظته منك حافظ)\n(فأقسم ما غنى عناءك محسن ... مجيد ولم يلفظ كلفظك لافظ)\n(وفي بعض هذا القول مني مساءة ... وغيظ شديد للمغنين غائظ)","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":84,"spl":"إسحاق وابن بانة في مجلس الواثق — نسبة هذا الصوت"},
{"id":"b52-125","bab":"الجزء 5","sec":"إسحاق يحدث الرشيد عن البرامكة فيزجره","page":"ج5 ص410","text":"أخبرني الحسن بن علي قال حدثنا يزيد بن محمد المهلبي قال حدثني إسحاق قال قال لي الرشيد يوما بأي شيء يتحدث الناس قلت يتحدثون بأنك تقبض على البرامكة وتولي الفضل بن الربيع الوزارة فغضب وصاح بي وما أنت وذاك ويلك فأمسكت فلما كان بعد أيام دعا بنا فكان أول شيء غنيته صوت\n(إذا نحن صدقناك ... فضر عندك الصدق)\n(طلبنا النفع الباطل ... إذ لم ينفع الحق)\n(فلو قدم صبا في ... هواه الصبر والرفق)\n(لقدمت على الناس ... ولكن الهوى رزق)\nي هذه الأبيات خفيف رمل بالوسطى ينسب إلى إسحاق وإلى ابن جامع والصحيح أنه لإسحاق وقيل إن الشعر لأبي العتاهية قال فضحك الرشيد وقال لي يا إسحاق قد صرت حقودا أخبرني الحسن قال حدثنا يزيد بن محمد قال حدثني حماد بن إسحاق عن أبيه قال دخلت على المعتصم يوما بسر من رأى فإذا الواثق بين يديه وعنده علويه ومخارق فغناه مخارق صوتا فلم ينشط له ثم غناه علويه فأطربه فلما رأيت طربه لغناء علويه دون غناء مخارق اندفعت فغنيته لحني صوت\n(تجنبت ليلى أن يلج بك الهوى ... وهيهات كان الحب قبل التجنب)\nأمر لي بألف دينار ولعلويه بخمسمائة دينار ولم يأمر لمخارق بشيء","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":84,"spl":"إسحاق وابن بانة في مجلس الواثق — نسبة هذا الصوت"},
{"id":"b52-126","bab":"الجزء 5","sec":"نسبة هذا الصوت","page":"ج5 ص411","text":"صوت\n(تجنبت ليلى أن يلج بك الهوى ... وهيهات كان الحب قبل التجنب)\n(إلا إنما غادرت يا أم مالك ... صدى أينما تذهب به الريح يذهب)\nلشعر للمجنون والغناء لإسحاق ثقيل أول بإطلاق الوتر في مجرى البنصر عن إسحاق وغنى ابن جامع في هذين البيتين وبيتين آخرين أضافهما إليهما ليسا من هذا الشعر هزجا بالبنصر والبيتان المضافان\n(برى اللحم عن أحناء عظمي ومنكبي ... هوى لسليمى في الفؤاد المعذب)\n(وإني سعيد أن رأت لك مرة ... من الدهر عيني منزلا في بني أبي)\nأخبرنا الحسن بن علي قال حدثنا يزيد بن محمد المهلبي قال غنى علويه بين يدي الواثق يوما صوت\n(خليل لي سأهجره ... لذنب لست أذكره)\n(ولكني سأرعاه ... وأكتمه وأستره)\n(وأظهر أنني راض ... وأسكت لا أخبره)\n(لكي لا يعلم الواشي ... بما عندي فأكسره)\nلشعر والغناء لإسحاق هزج بالوسطى قال فطرب الواثق طربا شديدا واستحسن اللحن وأمر لعلويه بألف دينار ثم قال أهذا اللحن لك قال لا يا أمير المؤمنين هو لهذا الهزبر يعني إسحاق قال وكان إسحاق حاضرا فضحك الواثق وقال قد ظلمناه إذا وأمر لإسحاق بثلاثين ألف درهم أخبرنا علي بن عبد العزيز الكاتب عن عبيد الله بن عبد الله بن خرداذبه عن أبيه قال كان إسحاق عند الفتح بن الحجاج الكرخي وعلويه حاضر فغناه علويه حاضر صوت\n(علقتك ناشئا حتى ... رأيت الرأس مبيضا)\n(على يسر وإعسار ... وفيض نوالكم فيضا)\n(ألا أحبب بأرض كنت ... تحتلينها أرضا)\n(وأهلك حبذا ما هم ... وإن أبدوا لي البغضا)\nالشعر لابن أذينة والغناء لابن سريج ثقيل أول بالسبابة في مجرى البنصر عن إسحاق وفيه لإسحاق هزج خفيف مطلق في مجرى البنصر عن إسحاق أيضا وفيه للأبجر ثقيل أول ولإبراهيم الموصلي رمل جميع ذلك عن الهشامي قال فغناه إياه في الثقيل ثم غناه هزجا فقال له الفتح لمن الثقيل فقال لابن سريج قال فلمن الهزج قال لهذا الهزبر يعني إسحاق فقال له الفتح ويلك يا إسحاق أتعارض ثقيل ابن سريج بهزجك قال فقبض إسحاق على لحيته ثم قال على ذلك فوالله ما فاتني إلا بتحريكه الذقن","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":84,"spl":"إسحاق وابن بانة في مجلس الواثق — نسبة هذا الصوت"},
{"id":"b52-127","bab":"الجزء 5","sec":"المعتصم يخطئ في شعر فيصوبه له","page":"ج5 ص413","text":"أخبرني الحسن قال حدثني يزيد بن محمد قال حدثني إسحاق قال دخلت يوما على المعتصم وعنده إسحاق بن إبراهيم بن مصعب واستدناني فدنوت منه واستدناني فتوقفت خوفا من أن أكون موازيا في\nالمجلس لإسحاق بن إبراهيم ففطن المعتصم فقال إن إسحاق لكريم وإنك لم تستنزل ما عند الكريم بمثل إكرامه ثم تحدثنا وأفضت بنا المذاكرة إلى قول أبي خراش الهذلي\n(حمدت إلهي بعد عروة إذ نجا ... خراش وبعض الشر أهون من بعض)\nأنشدها المعتصم إلى آخرها وأنشد فيها\n(ولم أدر من ألقى عليه رداءه ... سوى أنه قد حط عن ماجد محض)\nالرواية قد بزعن ماجد محض فغلطت وأسأت الأدب فقلت يا أمير المؤمنين هذه رواية الكتاب وما أخذ عن المعلم والصحيح بز عن ماجد محض فقال لي نعم صدقت وغمزني بعينه يحذرني من إسحاق وفطنت لغلطي فأمسكت وعلمت أنه قد أشفق علي من بادرة تبدر من إسحاق لأنه كان لا يحتمل مثل هذا في الخلفاء من أحد حتى يعظم عقوبته ويطيل حبسه كائنا من كان فنبهني رحمه الله على ذلك حتى أمسكت وتنبهت أخبرنا يحيى بن علي بن يحيى قال قال عبيد الله بن معاوية قال عمرو ابن بانة كنا عند المأمون فقال ما أقل الهزج في الغناء القديم وقال\nإسحاق ما أكثره ثم غناه نحو ثلاثين صوتا في الهزج القديم فقلت لأصحابي هذا الذي تزعمون أنه قليل الرواية أخبرنا يحيى قال حدثنا أبي عن إسحاق قال قال لي العباس بن جرير قاتلك الله مذكر فطنة ومؤنث طبيعة ما أمكرك حدثنا يحيى بن علي قال حدثني أبي عن إسحاق قال وأخبرني الحسن بن علي قال حدثنا يزيد بن محمد عن إسحاق قال أنشدت بعض الأعراب شعرا لي أقول فيه\n(أجرت سوابق دمعك المهراق ... لما جرى لك سانح بفراق)\n(إن الظعائن يوم ناصفة اللوى ... هاجت عليك صبابة المشتاق)\n(لم أنس إذ ألمحننا في رقبة ... منهن بيض ترائب وتراق)\n(وأشرن إذ ودعننا بأنامل ... حمر كهداب الدمقس رقاق)\n(ورمتك هند يوم ذاك فأقصدت ... بأغر عذب بارد براق)\n(وتنفست لما رأتك صبابة ... نفسا تصعد في حشى خفاق)\n(ولقد حذرت فما نجوت مسلما ... حتى صرعت مصارع العشاق)\n(إن الخلافة أثبتت أوتادها ... لما تحملها أبو إسحاق)\n(ملك أعز يلوح فوق جبينه ... نور الخلافة ساطع الإشراق)\n(كسي الجلال مع الجمال وزانه ... هدي التقى ومكارم الأخلاق)\n(صحت عروقك في الجياد وإنما ... يجري الجراد بصحة الأعراق)\n(ذخر الملوك فكان أكثر ذخرهم ... للملك ما جمعوا من الأوراق)\n(وذخرت أبناء الحروب كأنهم ... أسد العرين على متون عتاق)\n(كم من كريمة معشر قد أنكحت ... بسيوفهم قسرا بغير صداق)\n(وعزيزة في أهلها وقطينها ... قد فارقت بعلا بغير طلاق)\nقال فقال لي أفليت والله يا أبا محمد فقلت له وما أفليت قال رعيت فلاة لم يرعها أحد غيرك","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":85,"spl":"المعتصم يخطئ في شعر فيصوبه له"},
{"id":"b52-128","bab":"الجزء 5","sec":"إذا حضر إسحاق أصبح المغنون أقل من التراب","page":"ج5 ص416","text":"أخبرنا يحيى بن علي قال حدثني أخي أحمد بن علي عن عافية بن شبيب قال قلت لزرزور بن سعيد حدثني عن إسحاق كيف كان يصنع إذا حضر معكم عند الخليفة وهو منقطع ذاهب وحلوقكم ليس مثلها في الدنيا فقال كان والله لا يزال بحذقه ورفقه وتأنيه ولطفه حتى نصير معه أقل من التراب أخبرنا يحيى قال حدثني أبي قال حدثنا إسحاق قال دخلت على الفضل بن الربيع فقال لي يا إسحاق كثر والله شيبك فقلت أنا وذاك أصلحك الله كما قال أخو ثقيف\n(الشيب إن يظهر فإن وراءه ... عمرا يكون خلاله متنفس)\n(لم ينتقص مني المشيب قلامة ... ولنحن حين بدا ألب وأكيس)\nال هات يا غلام دواة وقرطاسا أكتبهما لي لأتسلى بهما أخبرنا يحيى قال حدثني أبي قال حدثني إسحاق وأخبرني الحسين بن يحيى عن حماد عن أبيه وأخبرني الحسن بن علي عن يزيد بن محمد بن عبد الملك عن إسحاق قال قال الفضل بن يحيى لأبي مالي لا أرى إسحاق عرفني ما خبره فقال خير ورأى في كلامه شيئا يشكك فقال أعليل هو فقال لا ولكنه جاءك مرات فحجبه نافذ الخادم ولحقته جفوة فقال له فإن حجبه بعدها فلينكه فجاءني أبي فقال لي القه فقد سأل عنك وخبرني بما جرى وجئت فحجبت أيضا وخرج الفضل ليركب فوثبت إليه برقعة وقد كتبت فيها\n(جعلت فداءك من كل سوء ... إلى حسن رأيك أشكو أناسا)\n(يحولون بيني وبين السلام ... فما إن أسلم إلا اختلاسا)\n(وأنفذت أمرك في نافذ ... فما زاده ذاك إلا شماسا)\nلما قرأها ضحك حتى غلب ثم قال أو قد فعلتها يا فاسق فقلت لا والله يا سيدي وإنما مزحت فخجل نافذ خجلا شديدا ولم يعد بعد ذلك لمساءتي أخبرنا يحيى بن علي قال حدثنا أبو أيوب المديني عن محمد بن عبد الله بن مالك قال حدثني إسحاق قال\nذكر المعتصم يوما بعض أصحابه وقد غاب عنه فقال تعالوا حتى نقول ما يصنع في هذا الوقت فقال قوم يلعب بالنرد وقال قوم يغني فبلغتني النوبة فقال قل يا إسحاق قلت إذا أقول وأصيب قال أتعلم الغيب قلت لا ولكني أفهم ما يصنع وأقدر على معرفته قال فإن لم تصب قلت فإن أصبت قال لك حكمك وإن لم تصب قلت لك دمي قال وجب قلت وجب قال فقل قلت يتنفس قال فإن كان ميتا قلت تحفظ الساعة التي تكلمت فيها فإن كان مات فيها أو قبلها فقد قمرتني فقال قد انصفت قلت فالحكم قال احتكم ما شئت قلت ما حكمي إلا رضاك يا أمير المؤمنين قال فإن رضاي لك و قد أمرت لك بمائة ألف درهم أترى مزيدا فقلت ما أولاك بذلك يا أمير المؤمنين قال فإنها مائتا ألف درهم أترى مزيدا قلت ما أحوجني إلى ذلك يا أمير المؤمنين قال فإنها ثلثمائة ألف أترى مزيدا قلت ما أولاك بذلك يا أمير المؤمنين قال يا صفيق الوجه ما نزيدك على هذا شيئا","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":86,"spl":"إذا حضر إسحاق أصبح المغنون أقل من التراب — إسحاق يمدح سفينة محمد المخلوع"},
{"id":"b52-129","bab":"الجزء 5","sec":"إسحاق يمدح سفينة محمد المخلوع","page":"ج5 ص418","text":"أخبرنا يحيى قال حدثني أبو أيوب قال حدثني محمد بن عبد الله بن مالك قال حدثني إسحاق قال عمل محمد المخلوع سفينة فأعجب بها وركب فيها يريد الأنبار فلما أمعن وأنا مقبل على بعض أبواب السفينة صاحوا إسحاق إسحاق\nفوثبت فدنوت منه فقال لي كيف ترى سفينتي فقلت حسنة يا أمير المؤمنين عمرها الله ببقائك فقام يريد الخلاء وقال لي قل فيها أبياتا فقلت وخرج فقمت في الأبيات فاشتهاها جدا وقال لي أحسنت يا إسحاق وحياتك لأهبن لك عشرة آلاف دينار قلت متى يا أمير المؤمنين إذا وسع الله عليك فضحك ودعا بها على المكان ولم يذكر يحيى في خبره الأبيات أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه قال غنيت الواثق في شعر قلته وأنا عنده بسر من رأى وقد طال مقامي واشتقت إلى أهلي وهو صوت\n(يا حبذا ريح الجنوب إذا بدت ... في الصبح وهي ضعيفة الأنفاس)\n(قد حملت برد الندى وتحملت ... عبقا من الجثجاث والبسباس)\nشرب عليه واستحسنه وقال لي يا أبا محمد لو قلت مكان يا حبذا ريح الجنوب يا حبذا ريح الشمال ألم يكن أرق وأعذى وأصح للأجساد وأقل وخامة وأطيب للأنفس فقلت ما ذهب علي ما قاله أمير المؤمنين ولكن التفسير فيما بعد فقال قل فقلت\n(ماذا تهيج من الصبابة والهوى ... للصب بعد ذهوله والياس)\nقال الواثق إنما استطبت ما تجيء به الجنوب من نسيم أهل بغداد لا الجنوب وإليهم اشتقت لا إليها فقلت أجل يا أمير المؤمنين وقمت\nفقبلت يده فضحك وقال قد أذنت لك بعد ثلاثة أيام فامض راشدا وأمر لي بمائة ألف درهم لحن إسحاق هذا من الثقيل الأول","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":86,"spl":"إذا حضر إسحاق أصبح المغنون أقل من التراب — إسحاق يمدح سفينة محمد المخلوع"},
{"id":"b52-130","bab":"الجزء 5","sec":"جعفر بن يحيى البرمكي وعبد الملك بن صالح الهاشمي","page":"ج5 ص420","text":"أخبرني يحيى بن علي قال حدثني أبي عن إسحاق قال\nلم أر قط مثل جعفر بن يحيى كانت له فتوة وظرف وأدب وحسن غناء وضرب بالطبل وكان يأخذ بأجزل حظ من كل فن من الأدب والفتوة\nفحضرت باب أمير المؤمنين الرشيد فقيل لي إنه نائم فانصرفت فلقيني جعفر بن يحيى فقال لي ما الخبر فقلت أمير المؤمنين نائم فقال قف مكانك ومضى إلى دار أمير المؤمنين فخرج إليه الحاجب فأعلمه أنه نائم فخرج إلي وقال لي قد نام أمير المؤمنين فسر بنا إلى المنزل حتى نخلو جميعا بقية يومنا وتغنيني وأغنيك ونأخذ في شأننا من وقتنا هذا قلت نعم فصرنا إلى منزله فطرحنا ثيابنا ودعا بالطعام فطعمنا وأمر بإخراج الجواري وقال لتبرزن فليس عندنا من تحتشمن منه\nفلما وضع الشراب دعا بقميص حرير فلبسه ودعا بخلوق فتخلق به ثم دعا لي بمثل ذلك وجعل يغنيني وأغنيه ثم دعا بالحاجب فتقدم إليه وأمره بألا يأذن لأحد من الناس كلهم وإن جاء رسول أمير المؤمنين أعلمه أنه مشغول واحتاط في ذلك وتقدم فيه إلى جميع الحجاب والخدم ثم قال إن جاء عبد الملك فأذنوا له يعني رجلا كان يأنس به ويمازحه ويحضر خلواته ثم أخذنا في شأننا فوالله إني لعلى حالة سارة عجيبة إذ رفع الستر وإذا عبد الملك بن صالح الهاشمي قد أقبل وغلط الحاجب ولم يفرق بينه وبين الذي يأنس به جعفر بن يحيى\nوكان عبد الملك بن صالح الهاشمي من جلالة القدر والتقشف وفي الامتناع من منادمة أمير المؤمنين على أمر جليل وكان\nأمير المؤمنين قد اجتهد به أن يشرب معه أو عنده قدحا فلم يفعل ذلك رفعا لنفسه فلما رأيناه مقبلا أقبل كل واحد منا ينظر إلى صاحبه وكاد جعفر أن ينشق غيظا وفهم الرجل حالنا فأقبل نحونا حتى إذا صار إلى الرواق الذي نحن فيه نزع قلنسيته فرمى بها مع طيلسانه جانبا ثم قال أطعمونا شيئا فدعا له جعفر بالطعام وهو منتفخ غضبا وغيظا فطعم ثم دعا برطل فشربه ثم أقبل إلى المجلس الذي نحن فيه فأخذ بعضادتي الباب ثم قال اشركونا فيما أنتم فيه فقال له جعفر ادخل ثم دعا بقميص حرير وخلوق فلبس وتخلق ثم دعا برطل ورطل حتى شرب عدة أرطال ثم اندفع ليغنينا فكان والله أحسننا جميعا غناء فلما طابت نفس جعفر وسري عنه ما كان به التفت إليه فقال له ارفع حوائجك فقال ليس هذا موضع حوائج فقال لتفعلن ولم يزل يلح عليه حتى قال له أمير المؤمنين علي واجد فأحب أن تترضاه قال فإن أمير المؤمنين قد رضي عنك فهات حوائجك فقال هذه كانت حاجتي قال ارفع حوائجك كما أقول لك قال علي دين فادح قال هذه أربعة آلاف ألف درهم فإن أحببت أن تقبضها فاقبضها من منزلي الساعة فإنه لم يمنعني من إعطائك إياها إلا أن قدرك يجل على أن يصلك مثلي ولكني ضامن لها حتى تحمل من مال أمير المؤمنين غدا فسل أيضا قال ابني تكلم أمير المؤمنين حتى ينوه باسمه قال قد ولاه أمير المؤمنين مصر وزوجه ابنته العالية ومهرها ألفي ألف درهم قال إسحاق فقلت في نفسي قد سكر الرجل أعني جعفرا فلما أصبحت لم تكن لي همة إلا حضور دار الرشيد وإذا جعفر ابن يحيى قد بكر ووجدت في الدار جلبة وإذا أبو يوسف القاضي ونظراؤه قد دعي بهم ثم دعي بعبد الملك بن صالح وابنه فأدخلا على الرشيد\nفقال الرشيد لعبد الملك إن أمير المؤمنين كان واجدا عليك وقد رضي عنك وأمر لك بأربعة آلاف ألف درهم فاقبضها من جعفر بن يحيى الساعة ثم دعا بابنه فقال اشهدوا أني قد زوجته العالية بنت أمير المؤمنين وأمهرتها عنه ألفي ألف درهم من مالي ووليته مصر قال فلما خرج جعفر ابن يحيى سألته عن الخبر فقال بكرت على أمير المؤمنين فحكيت له ما كان منا وما كنا فيه حرفا حرفا ووصفت له دخول عبد الملك وما صنع فعجب لذلك وسر به ثم قلت له قد ضمنت له عنك يا أمير المؤمنين ضمانا فقال ما هو فأعلمته قال أوف له بضمانك وأمر بإحضاره فكان ما رأيت أخبرني عمي قال حدثني فضل اليزيدي عن إسحاق قال لما صنعت لحني في\n(هل إلى نظرة إليك سبيل ... )","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":87,"spl":"جعفر بن يحيى البرمكي وعبد الملك بن صالح الهاشمي","partialRef":{"sid":"b52-87","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b52-131","bab":"الجزء 5","sec":"جعفر بن يحيى البرمكي وعبد الملك بن صالح الهاشمي","page":"ج5 ص420","text":"لقيته على علويه وجاءني رسول أبي بطبق فاكهة باكورة فبعثت إليه برك الله يا أبة ووصلك الساعة أبعث إليك بأحسن من هذه الباكورة فقال إني أظنه قد أتى بآبدة فلم يلبث أن دخل عليه علويه فغناه الصوت فعجب منه وأعجب به وقال قد أخبرتكم أنه قد أتى بآبدة ثم قال لولده أنتم تلومونني على تفضيل إسحاق ومحبتي له والله لو كان ابن غيري لأحببته لفضله فكيف وهو ابني وستعلمون أنكم لا تعيشون إلا به وقد ذكر أبو حاتم الباهلي عن أخيه أبي معاوية بن سعيد بن سلم أن هذه القصة كانت لما صنع إسحاق لحنه في\n(غيضن من عبراتهن وقلن لي ... )\nوقد ذكرت ذلك مع أخبار هذا الصوت في موضعه","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":88,"spl":"جعفر بن يحيى البرمكي وعبد الملك بن صالح الهاشمي — رأي إسحاق في إبراهيم بن المهدي","partialRef":{"sid":"b3-6","gi":0,"vi":1,"side":0},"partial":1},
{"id":"b52-132","bab":"الجزء 5","sec":"رأي إسحاق في إبراهيم بن المهدي","page":"ج5 ص423","text":"حدثني جعفر بن قدامة قال حدثني علي بن يحيى قال سألت إسحاق عن إبراهيم بن المهدي فقال دعني منه فليست له رواية ولا دراية ولا حكاية أخبرني الحسن بن علي الخفاف قال حدثني فضل اليزيدي عن إسحاق قال كانت هشيمة الخمارة جارتي وكانت تخصني بأطيب الشراب وجيده فماتت فقلت أرثيها\n(أضحت هشيمة في القبور مقيمة ... وخلت منازلها من الفتيان)\n(كانت إذا هجر المحب حبيبه ... دبت له في السر والإعلان)\n(حتى يلين لما تريد قياده ... ويصير سيئه إلى الإحسان)\nخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه قال سألني إدريس بن أبي حفصة حاجة فقضيتها له وزدت فيما سأل فقال لي\n(إذا الرجال جهلوا المكارما ... كان بها ابن الموصلي عالما)\n(أبقاك ذو العرش بقاء دائما ... فقد جعلت للكرام خاتما)\n(إسحاق لو كنت لقيت حاتما ... كان نداه لنداك خادما)\nال حماد وقال لي أبي كان إدريس سخيا من بين آل أبي حفصة فنزل به ضيف فتنمرت امرأته عليه فقال لها\n(من شر أيامك اللاتي خلقت لها ... إذا فقدت ندى صوتي وزواري)\nأخبرني محمد بن مزيد قال حدثنا حماد عن أبيه قال كان علي بن هشام قد دعاني ودعا عبد الله بن محمد بن أبي عيينة فتأخرت عنه حتى اصطبحنا شديدا وتشاغلت عنه برجل من الأعراب كان يجيئني فأكتب عنه وكان فصيحا وكان عند علي بن هشام بعض ما يعاديني فسألوا ابن أبي عيينة أن يعاتبني بشعر ينسبني فيه إلى الخلف فكتب إلي\n(يا مليا بالوعد والخلف والمطل بطيئا عن دعوة الأصحاب ... )\n(لهجا بالأعراب إن لدينا ... بعض ما تشتهي من الأعراب)\n(قد عرفنا الذي شغلت به عنا ... وإن كان غير ما في الكتاب)\nال فكتبت إلى الذي حمل ابن أبي عيينة على هذه الأبيات قال حماد وأظنه إبراهيم بن المهدي\n(قد فهمت الكتاب أصلحك الله وعندي عليه رد الجواب ... )\n(ولعمري ما تنصفون ولا كان ... الذي جاء منكم في حسابي)\n(لست آتيك فاعملن ولا لي ... فيك حظ من بعد هذا الكتاب)\nال حماد قال أبي وكتبت إلى علي بن هشام وقد اعتللت أياما فلم يأتني رسوله\n(أنا عليل منذ فارقتني ... وأنت عمن غاب لا تسأل)\n(ما هكذا كنت ولا هكذا ... فيما مضى كنت بنا تفعل)\nفلما وصلت إليه رقعتي ركب إلي وجاءني عائدا أخبرني محمد بن مزيد قال حدثنا حماد قال\nلما خرج أبي إلى البصرة خرجته الأولى وعاد أنشدني في ذلك لنفسه صوت\n(ما كنت أعرف ما في البين من حزن ... حتى تنادوا بأن قد جيء بالسفن)\n(قامت تودعني والعين تغلبها ... فجمجمت بعض ما قالت ولم تبن)\n(مالت علي تفديني وترشفني ... كما يميل نسيم الريح بالغصن)\n(وأعرضت ثم قالت وهي باكية ... يا ليت معرفتي إياك لم تكن)\n(لما افترقنا على كره لفرقتها ... أيقنت أني رهين الهم والحزن)\nخبرني محمد بن مزيد قال حدثني حماد بن إسحاق عن أبيه قال أنشدني شداد بن عقبة لجميل\n(قفي تسل عنك النفس بالخطة التي ... تطيلين تخويفي بها ووعيدي)\n(فقد طالما من غير شكوى قبيحة ... رضينا بحكم منك غير سديد)\nال فأنشدت الزبير بن بكار هذين البيتين فقال لو لم أنصرف من العراق إلا بهما لرأيتهما غنما وأنشدني شداد لجميل أيضا\n(بثين سليني بعض مالي فإنما ... يبين عند المال كل بخيل)\n(فإني وتكراري الزيارة نحوكم ... لبين يدي هجر بثين طويل)\nال أبي فقلت لشداد فهلا أزيدك فيهما فقال بلى فقلت\n(فيا ليت شعري هل تقولين بعدنا ... إذا نحن أزمعنا غدا لرحيل)\n(ألا ليت أياما مضين رواجع ... وليت النوى قد ساعدت بجميل)\nقال شداد أحسنت والله وإن هذا الشعر لضائع فقلت وكيف ذلك قال نفيته على نفسك بتسميتك جميلا فيه ولم يلحق بجميل فضاع بينكما جميعا","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":88,"spl":"جعفر بن يحيى البرمكي وعبد الملك بن صالح الهاشمي — رأي إسحاق في إبراهيم بن المهدي","partial":1},
{"id":"b52-133","bab":"الجزء 5","sec":"إسحاق بن إبراهيم وإسحاق المصعبي","page":"ج5 ص426","text":"حدثني جحظة قال حدثني علي بن يحيى المنجم قال حدثني إسحاق الموصلي قال دعاني إسحاق بن إبراهيم المصعبي وكان عبد الله بن طاهر عنده يومئذ فوجه إلي فخضرت وحضر علويه ومخارق وغيرهما من المغنين فبينا هم على شرابهم وهم أسر ما كانوا إذ وافاه رسول أمير المؤمنين فقال أجب فقال السمع والطاعة ودعا بثيابه فلبسها ثم التفت إلى محمد بن راشد الخناق فقال لله قد بلغني أنك أحفظ الناس لما يدور في المجالس فاحفظ لي كل صوت يمر وما يشربه كل إنسان حتى إذا عدت أعدت علي الأصوات وشربت ما فاتني فقال نعم أصلح الله الأمير ومضى إلى المأمون فأمره بالشخوص إلى بابك من غد وتقدم إليه فيما يحتاج إليه ورجع من عنده فلما دخل ووضع ثيابه قال يا محمد ما صنعت فيما تقدمت به إليك قال قد أحكمته أعزك الله ثم أخبره بما شرب القوم وما استحسنوه من الغناء بعده فأمر أن يجمع له أكثر ما شربه واحد منهم في فدح وأن يعاد عليه صوت صوت مما حفظه له حتى يستوفى ما فاته القوم\nبه ففعل ذلك وشرب حتى استوفى النبيذ والأصوات ثم قال لي يا أبا محمد إني قد علمته في منصرفي من عند أمير المؤمنين أبياتا فاسمعها فقلت هاتها أعز الله الأمير فأنشدني صوت\n(ألا من لقلب مسلم للنوائب ... أحاطت به الأحزان من كل جانب)\n(تبين يوم البين أن اعتزامه ... على الصبر من بعض الظنون الكواذب)\nوت\n(حرام على رامي فؤادي بسهمه ... دم صبه بين الحشى والترائب)\n(أراق دما لولا الهوى ما أراقه ... فهل بدمي من ثائر أو مطالب)\nال فقلت له ما سمعت أحسن من هذا الشعر قط فقال لي فاصنع فيه فصنعت فيه لحنا وأحضرني وصيفة له فألقيته عليها حتى أخذته وقال إنما أردت أن أتسلى به في طريقي وتذكرني به الجارية أمرك إذا غنته فكان كلما ذكر أتاني بره إلى أن قدم عدة دفعات لم أجد لإسحاق صنعة في هذا الشعر والذي وجدت فيه لعبد الله بن طاهر خفيف رمل ذكره ابنه عبيد الله عنه ولمخارق لحن من الرمل ولعمرو بن بانة هزج بالوسطى ولمخارق والطاهرية خفيف ثقيل حدثني جحظة قال حدثني أبو عبد الله محمد بن حمدون قال سأل المتوكل عن إسحاق الموصلي فعرف أنه قد كف وأنه في منزله ببغداد فكتب في إحضاره فلما دخل عليه رفعه حتى أجلسه قدام السرير وأعطاه مخدة وقال له بلغني أن المعتصم دفع إليك مخدة في أول يوم جلست بين يديه وهو خليفة وقال إنه لا يستجلب ما عند حر بمثل\nالكرامة ثم سأله هل أكل فقال نعم فأمر أن يسقى فلما شرب أقداحا قال هاتوا لأبي محمد عودا فجيء به فاندفع يغني بصوت الشعر فيه والغناء له صوت\n(ما علة الشيخ عيناه بأربعة ... تغرورقان بدمع ثم تنسكب)\nال أبو عبد الله فوالله ما بقي غلام من الغلمان الوقوف على الحير إلا وجدته يرقص طربا وهو لا يعلم بما يفعل فأمر له بمائة ألف درهم ثم قال لي المتوكل يابن حمدون أتحسن أن تغنيني هذا الصوت فقلت نعم قال غنه فترنمت به فقال إسحاق من هذا الذي يحكيني فقال هذا ابن صديقك حمدون فقال وددت أنه يحسن أن يحكيني فقلت له أنت عرضتني له يا أمير المؤمنين ثم انحدر المتوكل إلى رقة بوصرا وكان يستطيبها لكثرة تغريد الأطيار بها فغنى إسحاق صوت\n(أأن هتفت ورقاء في رونق الضحى ... على غصن غض الشباب من الرند)\n(بكيت كما يبكي الحزين صبابة ... وشوقا وتابعت الحنين إلى نجد)\nضحك المتوكل وقال له يا إسحاق هذه أخت فعلتك بالواثق لما\nغنيته بالصالحية\n(طربت إلى الأصيبية الصغار ... وذكرني الهوى قرب المزار)\nكم أعطاك لما أذن لك في الانصراف قال مائة ألف درهم فأمر له بمائة ألف درهم وأذن له بالانصراف إلى بغداد وكان هذا آخر عهدنا به لأن إسحاق توفي بعد ذلك بشهرين حدثني جحظة قال حدثني حماد بن إسحاق عن أبيه قال دخلت على الواثق أستأذنه في الانحدار إلى بغداد فوجدته مصطبحا فقال بحياتي غن صوت\n(ألا إن أهل الدار قد ودعوا الدارا ... وإن كان أهل الدار في الحي أجوارا)\n(وقد تركوا قلبي حزينا متيما ... بذكرهم لو يستطيع لقد طارا)\nتطيرت من اقتراحه له وغنيته إياه فشرب عليه مرارا وأمر لي بثلاثين ألف درهم وأذن لي فانصرفت ثم كان آخر عهدي به الشعر لمطيع بن\nإياس والغناء لإبراهيم الموصلي ثقيل أول بالوسطى عن عمرو حدثني الحسن بن علي قال حدثنا عبد الله بن أبي سعد قال حدثنا عبد الله بن الفرج قال حدثنا أحمد بن معاوية قال كنت في بيتي وعلويه يغنيني صوت","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":89,"spl":"إسحاق بن إبراهيم وإسحاق المصعبي"},
{"id":"b52-134","bab":"الجزء 5","sec":"إسحاق بن إبراهيم وإسحاق المصعبي","page":"ج5 ص426","text":"(أعرضن من شمط في الرأس لاح به ... فهن عنه إذا أبصرنه حيد)\n(قد كن يعهدن مني منظرا حسنا ... وجمة حسرت عنها العناقيد)\nوردت علي رقعة من إسحاق الموصلي يستسقيني نبيذا فبعثت إليه بدن مع غلام لي فلما توسط الغلام به الجسر زحم فكسر فرجع الغلام إلى إسحاق فأخبره الخبر وسأله مسألتي التجافي عنه فكتب إلي\n(يا أحمد بن معاويه ... إني رميت بداهيه)\n(أشكو إليك فأشكني ... كسر الغلام الخابيه)\n(يا ليتها سلمت وكان ... فداءها ابن الزانيه)\nبعثت إليه بأربعة أدنان وأعتقت الغلام بشفاعته في أمره","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":90,"spl":"إسحاق بن إبراهيم وإسحاق المصعبي — عجز المغنين عن أخذ صوته"},
{"id":"b52-135","bab":"الجزء 5","sec":"عجز المغنين عن أخذ صوته","page":"ج5 ص430","text":"أخبرني جعفر بن قدامة ومحمد بن مزيد قالا حدثنا حماد بن إسحاق\nالموصلي قال قال لي حمدون بن إسماعيل رحمه الله لما صنع أبوك رحمه الله هذا الصوت صوت\n(قف بالديار التي عفا القدم ... وغيرتها الأرواح والديم)\n(لما وقفنا بها نسائلها ... فاضت من القوم أعين سجم)\n(ذكرا لعيش مضى إذا ذكرت ... ما فات منه فذكره سقم)\n(وكل عيش دامت غضارته ... منقطع مرة ومنصرم)\nلحنه ثقيل أول أعجب به المعتصم والواثق جميعا فقال له المعتصم بحياتي اردده على مخارق وعلويه والجماعة ليأخذوه عنك وانصحهم فيه فإنهم إن أحسنوا فيه نسب إليك إحسانهم وإن أساؤوا بان فضلك عليهم فرده عليهم أكثر من مائتي مرة وكانوا يقصدون إلى منزله ويرده عليهم ومات وما أخذوا منه علم الله إلا رسمه الشعر والغناء لإسحاق ولحنه ثقيل أول","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":90,"spl":"إسحاق بن إبراهيم وإسحاق المصعبي — عجز المغنين عن أخذ صوته"},
{"id":"b52-136","bab":"الجزء 5","sec":"الرشيد وإسحاق في الرقة ودير القائم","page":"ج5 ص431","text":"أخبرني محمد بن مزيد قال حدثنا حماد عن أبيه قال خرجنا مع الرشيد يريد الرقة فلما صرنا بالموضع الذي يقال له القائم نزلنا وخرج يتصيد وخرجنا معه فأبعد في طلب الصيد ولاح\nلي دير فقصدته وقد تعبت فأشرفت على صاحبه فقال هل لك في النزول بنا اليوم فقلت أي والله وإني إلى ذلك لمحتاج فنزل ففتح لي الباب وجلس يحدثني وكان شيخا كبيرا وقد أدرك دولة بني أمية فجعل يحدثني عمن نزل به من القوم ومواليهم وجيوشهم وعرض علي الطعام فأجبته فقدم إلي طعاما من طعام الديارات نظيفا طيبا فأكلت منه وأتاني بشراب وريحان طري فشربت منه ووكل بي جارية تخدمني راهبة لم أر أحسن وجها منها ولم أشكل فشربت حتى سكرت ونمت وانتبهت عشاء فقلت في ذلك صوت\n(بدير القائم الأقصى ... غزال شادن أحوى)\n(برى حبي له جسمي ... ولا يعلم ما ألقى)\n(وأكتم حبه جهدي ... ولا والله ما يخفى)\nركبت فلحقت بالمعسكر والرشيد قد جلس للشرب وطلبني فلم أوجد وأخبرت بذلك فغنيت في الأبيات ودخلت إليه فقال لي أين كنت ويحك فأخبرته بالخبر وغنيته الصوت فطرب وشرب عليه حتى سكر وأخر الرحيل في غد ومضينا إلى الدير ونزله فرأى الشيخ واستنطقه ورأى الجارية التي كانت تخدمني بالأمس فدعا بطعام خفيف فأصاب منه ودعا بالشراب وأمر الجارية التي كانت بالأمس تخدمني أن\nتتولى خدمته وسقيه ففعلت وشرب حتى طابت نفسه ثم أمر للدير بألف دينار وأمر باحتمال خراجه له سبع سنين فرحلنا قال حماد فحدثني أبي قال فلما صرنا بتل عزاز من دابق خرجت أنا وأصحاب لي نتنزه في قرية من قراها فأقمنا بها أياما وطلبني الرشيد فلم يجدني فلما رجعت أتيت الفضل بن الربيع فقال لي أين كنت طلبك أمير المؤمنين فأخبرته بنزهتنا فغضب وخفت من الرشيد أكثر مما لقيت من الفضل فقلت صوت\n(إن قلبي بالتل تل عزاز ... عند ظبي من الظباء الجوازي)\n(شادن يسكن الشآم وفيه ... مع ظرف العراق شكل الحجاز)\n(يا لقومي لبنت قس أصابت ... منك صفو الهوى وليست تجازي)\n(حلفت بالمسيح أن تنجز الوعد ... وليست تهم بالإنجاز)\nغنيت فيه ثم دخلت على الرشيد وهو مغضب فقال أين كنت طلبتك فلم أجدك فاعتذرت إليه وأنشدته هذا الشعر وغنيته إياه فتبسم وقال عذر وأبيك وأي عذر وما زال يشرب عليه ويستعيدنيه ليلته جمعاء حتى انصرفنا مع طلوع الفجر فلما وصلت إلى رحلي إذا برسول أمير المؤمنين قد أتانا يدعونا فوافيت فدخلت وإذا ابن جامع\nيتمرغ على دكان في الدار وهو سكران يتململ فقال لي يابن الموصلي أتدري ما جاء بنا فقلت لا والله ما أدري فقال لكني والله أدري دراية صحيحة جاءت بنا نصرانيتك الزانية عليك وعليها لعنة الله وخرج الآذن فأذن لنا فدخلنا فلما رأيت الرشيد تبسمت فقال لي ما يضحكك فأخبرته بقول ابن جامع فقال صدق ما هو إلا أن فقدتكم فاشتقت إلى ما كنا فيه فعودوا بنا فعدنا فيه حتى انقضى مجلسنا وانصرفنا لحن إسحاق\n(بدير القائم الأقصى ... )\nفيف ثقيل بالوسطى وفيه للقاسم بن زرزور ثقيل أول ولحنه في\n(إن قلبي بالتل تل عزاز ... )\nفيف رمل أخبرني محمد بن مزيد قال حدثني حماد عن أبيه قال دخلت على الرشيد يوما في عمامة قد كورتها على رأسي فقال ما هذه العمامة كأنك من الأنبار فلما كان من غد دعا بنا إليه فأمهلت حتى دخل المغنون جميعا قبلي ثم دخلت عليه في آخرهم وقد شددت وسطي بمشدة حرير أحمر ولبست لباسا مشتهرا وأخذت بيدي صفاقتين وأقبلت أخطر وأضرب بالصفاقتين و أغني\n(اسمع لصوت مليح ... من صنعه الأنباري)\n(صوت خفيف ظريف ... يطير في الأوتار)\nبسط يده إلي حتى كاد يقوم وجعل يقول أحسنت وحياتي\nأحسنت أحسنت حتى جلست ثم شرب عليه بقية يومه وما استعاد غيره وأمر لي بعشرين ألف درهم لحن إسحاق في هذا الشعر هزج أخبرني محمد بن مزيد قال حدثنا حماد قال حدثني أحمد بن يحيى المكي قال كنت عند الفضل بن الربيع فغنى بعض من كان عنده صوت\n(كل شيء منك في عيني حسن ... ونصيبي منك هم وحزن)\n(لا تظني أنه غيرني ... قدم العهد ولا طول الزمن)","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":91,"spl":"الرشيد وإسحاق في الرقة ودير القائم","partialRef":{"sid":"b52-112","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b52-137","bab":"الجزء 5","sec":"الرشيد وإسحاق في الرقة ودير القائم","page":"ج5 ص431","text":"قال لي أتدري لمن هذا فقلت لبعض الطنبوريين فقال لا ولكنه لذلك الشيطان إسحاق لحن إسحاق في هذين البيتين رمل بالوسطى من مجموع أغانيه أخبرني محمد بن مزيد قال حدثنا حماد عن أبيه قال لما خرجنا مع الرشيد إلى طوس كنت معه أسايره فاستسقيت ماء من منزل نزلناه يقال له سحنة فخرجت إلينا جارية كأنها ضبية فسقتني ماء فقلت هذا الشعر صوت\n(غزال يرتعي جنبات واد ... بسحنة قد تمكن في فؤادي)\n(سقاني شربة كانت شفاء ... لعلة حائم حران صادي)\nوغنيته الرشيد فقال لي أتحب أن أوزجكها فقلت نعم والله يا سيدي قال فاخطبها والمهر علي وما يصلحها فخطبتها فأبى أهلها أن يخرجوها من بلدهم لحن إسحاق في هذين البيتين ثقيل أول وفيه لعلويه خفيف رمل أخبرني جعفر بن قدامة قال حدثني حماد بن إسحاق قال قال لي أبي ما اغتممت بشيء قط مثل ما اغتممت بصوت مليح صنعته في هذا الشعر صوت\n(كان لي قلب أعيش به ... فاكتوى بالنار فاحترقا)\n(أنا لم أرزق محبتها ... إنما للعبد ما رزقا)\n(من يكن ما ذاق طعم ردى ... ذاقه لا شك إن عشقا)\nإني صنعت فيه لحنا وجعلت أردده في جناح لي سحرا فأظن أن إنسانا من العامة مر بي فسمعه فأخذه فبكرت من غد إلى المعتصم لأغنيه فإذا أنا بسواط يسوط الناطف وهو يغني اللحن بعينه إلا أنه غناء فاسد فعجبت وقلت ترى من أين لهذا السواط هذا الصوت ولعلي إذ غنيته أن يكون قد مر بي هذا فسمعني أغنيه وبقيت متحيرا ثم قلت يا فتى ممن سمعت هذا الصوت فلم يجبني والتفت إلى شريكه وقال هذا يسألني ممن سمعته هذا غنائي والله لو سمعه إسحاق الموصلي لخرئ في سراويله فبادرت والله هاربا خوف أن يمر بي إنسان فيسمع ما جرى علي فأفتضح وما علم الله أني نطقت بذلك الصوت بعدها\nحدثني جعفر بن قدامة قال حدثني حماد بن إسحاق قال كتب إبراهيم بن المهدي إلى أبي أي شيء تصحيف لا يريح مثل الأسنة فكتب إليه أبي تصحيفه لا يرث جميل إلا بثينة فكتب إليه وي منك أخبرنا جعفر قال حدثنا حماد عن أبيه قال دخلت يوما على جعفر بن يحيى فرأى شفتي تتحركان بشيء كنت أعمله فقال أتدعو أم تصنع ماذا فقلت بل أمدح قال قل فقلت صوت\n(وكنت إذا إذن عليك جرى لنا ... تجلى لنا وجه أغر وسيم)\n(علانية محمودة وسريرة ... وفعل يسر المعتفين كريم)\nاحتبسني وأمر لي بمال جليل وكسوة وقال زد البيتين حسنا بأن تصنع فيهما لحنا فصنعت لحنا من الثقيل الثاني فلم يزل يشرب عليهما حتى سكر","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":92,"spl":"الرشيد وإسحاق في الرقة ودير القائم"},
{"id":"b52-138","bab":"الجزء 5","sec":"طفيلي مقترح","page":"ج5 ص437","text":"أخبرنا محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه أنه حدثه قال غدوت يوما وأنا ضجر من ملازمة دار الخلافة والخدمة فيها فخرجت وركبت بكرة وعزمت على أن أطوف الصحراء وأتفرج فقلت لغلماني إن جاء رسول الخليفة أو غيره فعرفوه أني بكرت في بعض مهماتي وأنكم لا\nتعرفون أين توجهت ومضيت وطفت ما بدا لي ثم عدت وقد حمي النهار فوقفت في الشارع المعروف بالمخرم في فناء ثخين الظل وجناح رحب على الطريق لأستريح فلم ألبث أن جاء خادم يقود حمارا فارها عليه جارية راكبة تحتها منديل دبيقي وعليها من اللباس الفاخر ما لا غاية بعده ورأيت لها قواما حسنا وطرفا فاترا وشمائل حسنة فخرصت عليها أنها مغنية فدخلت الدار التي كنت واقفا عليها ثم لم ألبث أن جاء رجلان شابان جميلان فاستأذنا فأذن لهما فنزلا ونزلت معهما ودخلت فظنا أن صاحب الدار دعاني وظن صاحب الدار أني معهما فجلسنا وأتي بالطعام فأكلنا وبالشراب فوضع وخرجت الجارية وفي يدها عود فغنت وشربنا وقمت قومة وسأل صاحب المنزل الرجلين عني فأخبراه أنهما لا يعرفاني فقال هذا طفيلي ولكنه ظريف فأجملوا عشرته وجئت فجلست وغنت الجارية في لحن لي\n(ذكرتك أن مرت بنا أم شادن ... أمام المطايا تشرئب وتسنح)\n(من المؤلفات الرمل أدماء حرة ... شعاع الضحى في متنها يتوضح)\nأدته أداء صالحا وشربت ثم غنت أصواتا شتى وغنت في أضعافها من صنعتي\n(الطلول الدوارس ... فارقتها الأوانس)\n(أوحشت بعد أهلها ... فهي قفر بسابس)\nكان أمرها فيه أصلح منه في الأول ثم غنت أصواتا من القديم والحديث وغنت في أثنائها من صنعتي\n(قل لمن صد عاتبا ... ونأى عنك جانبا)\n(قد بلغت الذي أردت ... وإن كنت لاعبا)\nكان أصلح ما غنته فاستعدته منها لأصححه لها فأقبل علي رجل من الرجلين وقال ما رأيت طفيليا أصفق وجها منك لم ترض بالتطفيل حتى اقترحت وهذا غاية المثل طفيلي مقترح فأطرقت ولم أجبه وجعل صاحبه يكفه عني فلا يكف ثم قاموا للصلاة وتأخرت قليلا فأخذت عود الجارية ثم شددت طبقته وأصلحته إصلاحا محكما وعدت إلى موضعي فصليت وعادوا ثم أخذ ذلك الرجل في عربدته علي وأنا صامت ثم أخذت الجارية العود فجسته وأنكرت حاله وقالت من مس عودي قالوا ما مسه أحد قالت بلى والله لقد مسه حاذق متقدم وشد طبقته وأصلحه إصلاح متمكن من صناعته فقلت لها أنا أصلحته قالت فبالله خذه وأضرب به فأخذته وضربت به مبدأ صحيحا ظريفا عجيبا صعبا فيه نقرات محركة فما بقي أحد منهم إلا وثب على قدميه وجلس بين يدي ثم قالوا بالله يا سيدنا أتغني فقلت نعم وأعرفكم\nنفسي أنا إسحاق بن إبراهيم الموصلي ووالله إني لأتيه على الخليفة إذا طلبني وأنتم تسمعونني ما أكره منذ اليوم لأني تملحت معكم فوالله لا نطقت بحرف ولا جلست معكم حتى تخرجوا هذا المعربد المقيت الغث فقال له صاحبه من هذا حذرت عليك فأخذ يعتذر فقلت والله لا نطقت بحرف ولا جلست معكم حتى يخرج فأخذوا بيده فأخرجوه وعادوا فبدأت وغنيت الأصوات التي غنتها الجارية من صنعتي فقال لي الرجل هل لك في خصلة قلت ما هي قال تقيم عندي شهرا والجارية والحمار لك مع ما عليها من حلي قلت أفعل فأقمت عنده ثلاثين يوما لا يدري أحد أين أنا والمأمون يطلبني في كل موضع فلا يعرف لي خبرا فلما كان بعد ثلاثين يوما أسلم إلي الجارية والحمار والخادم فجئت بذلك إلى منزلي وركبت إلى المأمون من وقتي فلما رآني قال إسحاق ويحك أين تكون فأخبرته بخبري فقال علي بالرجل الساعة فدللتهم على بيته فأحضر فسأله المأمون عن القصة فأخبره فقال له أنت رجل ذو مروءة وسبيلك أن تعاون عليها وأمر له بمائة ألف درهم وقال لا تعاشرن ذلك المعربد النذل البتة وأمر لي بخمسين ألف درهم وقال أحضرني الجارية فأحضرتها فغنته فقال لي قد جعلت لها نوبة في كل يوم ثلاثاء تغنيني وراء الستارة مع الجواري وأمر لها بخمسين ألف درهم فربحت والله بتلك الركبة وأربحت","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":93,"spl":"طفيلي مقترح"},
{"id":"b52-139","bab":"الجزء 5","sec":"نسبة ما في هذا الخبر من الأغاني","page":"ج5 ص440","text":"صوت\n(ذكرتك أن مرت بنا أم شادن ... أمام المطايا تشرئب وتسنح)\n(من المؤلفات الرمل أدماء حرة ... شعاع الضحى في متنها يتوضح)\nلشعر لذي الرمة والغناء لإسحاق ثقيل أول بالسبابة والوسطى عن ابن المكي ومن أغاني إسحاق\nصوت\n(قل لمن صد عاتبا ... ونأى عنك جانبا)\n(قد بلعت الذي أردت ... وإن كنت لاعبا)\nلشعر والغناء لإسحاق وقد تقدم خبره قبل هذه الأخبار صوت\n(الطلول الدوارس ... فارقتها الأوانس)\n(أوحشت بعد أهلها ... فهي قفر بسابس)\nلشعر لابن ياسين شاعر مجهول قليل الشعر كان صديقا لإسحاق والغناء لإسحاق خفيف ثقيل وهذا الصوت من أوابد إسحاق وبدائعه أخبرني عمي قال حدثني يزيد بن محمد المهلبي قال كنت عند الواثق فغنته شجى التي وهبها له إسحاق هذا الصوت فقال لمخارق وعلويه والله لو عاش معبد ما شق غبار إسحاق في هذا الصوت فقالا له إنه لحسن يا أمير المؤمنين فغضب وقال ليس عندكما فيه إلا هذا ثم أقبل على أحمد بن المكي فقال دعني من هذين الأحمقين أول بيت في هذا الصوت أربع كلمات الطلول كلمة والدوارس كلمة وفارقتها كلمة والأوانس كلمة فانظر هل ترك إسحاق شيئا من الصنعة يتصرف فيه المغني لم يدخله في هذه الكلمات الأربع بدأ بها نشيدا وتلاه بالبسيط وجعل فيه صياحا وإسجاحا وترجيحا للنغم واختلاسا فيها وعمل هذا كله في أربع كلمات فهل سمعت أحدا تقدم أو تأخر فعل مثل هذا أو قدر عليه فقال صدق أمير المؤمنين قد لحق من قبله وسبق من بعده","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":94,"spl":"نسبة ما في هذا الخبر من الأغاني — نسبة هذا الصوت"},
{"id":"b52-140","bab":"الجزء 5","sec":"الواثق وإسحاق في دير مريم","page":"ج5 ص441","text":"أخبرني جعفر بن قدامة قال حدثني ميمون بن هارون قال حدثني إسحاق قال لما خرجت مع الواثق إلى النجف درنا بالحيرة ومررنا بدياراتها فرأيت دير مريم بالحيرة فأعجبني موقعه وحسن بنائه فقلت\n(نعم المحل لمن يسعى للذته ... دير لمريم فوق الظهر معمور)\n(ظل ظليل وماء غير ذي أسن ... وقاصرات كأمثال الدمى حور)\nقال الواثق لا نصطبح والله غدا إلا فيه وأمر بأن يعد فيه ما يصلح من الليل وباكرناه فاصطبحنا فيه على هذا الصوت وأمر بمال ففرق على أهل ذلك الدير وأمر لي بجائزة لحن إسحاق في هذين البيتين ثاني ثقيل بالبنصر","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":94,"spl":"نسبة ما في هذا الخبر من الأغاني — نسبة هذا الصوت"},
{"id":"b52-141","bab":"الجزء 5","sec":"إسحاق وعبد الله بن طاهر","page":"ج5 ص442","text":"أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه قال أخرج إلي عبد الله بن طاهر يوما بيتي شعر في رقعة وقال هذان\nالبيتان وجدتهما على بساط طبري أصبهبذي أهدي إلي من طبرستان فأحب أن تغنيني فيهما فقرأتهما فإذا هما\n(لج بالعين واكف ... من هوى لا يساعف)\n(كلما كف غربها ... هيجته المعازف)\nال فغنيت فيهما وغدوت بهما إليه فأعجب بالصوت ووصلني بصلة سنية وكان يشتهيه ويقترحه وطرحته على جميع جواريه وشاع خبر إعجابه به فبينا المعتصم يوما جالس يعرض عليه فرش الربيع إذ مر بساط ديباج في نهاية الحسن عليه هذان البيتان ومعهما\n(إنما الموت أن تفارق ... من أنت آلف)\n(لك حبان في الفؤاد ... تليد وطارف)\nأمر بالبساط فحمل إلى عبد الله بن طاهر وقال للرسول قل له إني قد عرفت شغفك بالغناء في هذا الشعر فلما وقع هذا البساط أحببت أن أتم سرورك به فشكر عبد الله ما تأذى إليه من هذه الرسالة وأعظم مقداره وقال لي والله يا أبا محمد لسروري بتمام الشعر أشد من سروري بكل شيء فألحقهما في الغناء بالبيتين الأولين فألحقتهما","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":94,"spl":"نسبة ما في هذا الخبر من الأغاني — نسبة هذا الصوت"},
{"id":"b52-142","bab":"الجزء 5","sec":"نسبة هذا الصوت","page":"ج5 ص443","text":"صوت\n(لج بالعين واكف ... من هوى لا يساعف)\n(كلما كف غربها ... هيجته المعازف)\n(إنما الموت أن تفارق ... من أنت آلف)\n(لك حبان في الفؤاد ... تليد وطارف)\nلم أعرف من خبر شاعره غير ما ذكرته في هذا الخبر والغناء لإسحاق هزج بالوسطى أخبرنا يحيى بن علي بن يحيى قال حدثنا أبو أيوب المديني عن ابن المكي عن أبيه قال قلت لإسحاق يوما يا أبا محمد كم تكون صنعتك فقال ما بلغت مائتين قط","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":94,"spl":"نسبة ما في هذا الخبر من الأغاني — نسبة هذا الصوت"},
{"id":"b52-143","bab":"الجزء 5","sec":"مرض إسحاق ووفاته","page":"ج5 ص444","text":"أخبرنا يحيى بن علي قال حدثنا حماد بن إسحاق قال قال لي وكيل بن الحروني قلت لأبيك إسحاق يا أبا محمد كم يكون غناؤك قال نحوا من أربعمائة صوت قال وقال له رجل بحضرتي ما لك لا تكثر الصنعة كما يكثر الناس قال لأني إنما أنقر في صخرة ولإسحاق أخبار كثيرة قليلة الفائدة كثيرة الحشو طرحتها لذلك وله أخبار أخر حسن ذكرها في مواضع تليق بها فأخرتها واحتبستها عليها وفيما ذكرته ها هنا منها مقنع\nوتوفي إسحاق ببغداد في أول خلافة المتوكل فأخبرني الصولي قال ذكر إبراهيم بن محمد الشاهيني أن إسحاق كان يسأل الله ألا يبتليه بالقولنج لما رأى من صعوبته على أبيه فرأى في منامه كأن قائلا يقول له قد أجيبت دعوتك ولست تموت بالقولنج ولكنك تموت بضده فأصابه ذرب في شهر رمضان سنة خمس وثلاثين ومائتين فكان يتصدق في كل يوم أمكنه أن يصومه بمائة درهم ثم ضعف عن الصوم فلم يطقه ومات في شهر رمضان أخبرنا الحسن بن علي قال حدثني يزيد بن محمد المهلبي قال نعي إسحاق إلى المتوكل في وسط خلافته فغمه وحزن عليه وقال ذهب صدر عظيم من جمال الملك وبهائه وزينته ثم نعي إليه بعده أحمد ابن عيسى بن زيد بن علي بن الحسين بن علي بن أبي طالب صلوات الله عليه فقال تكافأت الحالتان وقام الفتح بوفاة أحمد وما كنت آمن وثبته علي مقام الفجيعة بإسحاق فالحمد لله على ذلك","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":95,"spl":"مرض إسحاق ووفاته"},
{"id":"b52-144","bab":"الجزء 5","sec":"ما رثاه به الشعراء","page":"ج5 ص445","text":"أحمد بن جعفر جحظة قال حدثني رجل من الكتاب من أهل\nحذف\nقطربل قال حدثني أبي عن أبيه قال رأيت فيما يرى النائم قائلا يقول لي\n(مات الحسان ابن الحسان ... ومات إحسان الزمان)\nأصبحت من غد فركبت في بعض حوائجي فتلقاني خبر وفاة إسحاق الموصلي وقال إدريس بن أبي حفصة يرثي إسحاق بن إبراهيم الموصلي\n(سقى الله يابن الموصلي بوابل ... من الغيث قبرا أنت فيه مقيم)\n(ذهبت فأوحشت الكرام فمايني ... بعبرته يبكي عليك كريم)\n(إلى الله أشكو فقد إسحاق إنني ... وإن كنت شيخا بالعراق يتيم)\nقال محمد بن عمرو الجرجاني يرثيه\n(على الجدث الشرقي عوجا فسلما ... ببغداد لما ضن عنه عوائده)\n(وقولا له لو كان للموت فدية ... فداك من الموت الطريف وتالده)\n(أاسحاق لا تبعد وإن كان قد رمى ... بك الموت وردا ليس يصدر وارده)\n(إذا هزل اخضرت فنون حديثه ... ورقت حواشيه وطابت مشاهده)\n(وإن جد كان القول جدا وأقسمت ... مخارجه ألا تلين معاقده)\n(فبك على ابن الموصلي بعبرة ... كما ارفض من نظم الجمان فرائده)\nقال مصعب بن عبد الله الزبيري يرثيه نسخت ذلك من كتاب جعفر بن قدامة وذكر أن حماد بن إسحاق أنشده إياها ونسخته أيضا\nمن كتاب الحرمي بن أبي العلاء يذكر فيه عن الزبير عن عمه مصعب أنه انشده لنفسه يرثي إسحاق\n(أتدري لمن تبكي العيون الذوارف ... وينهل منها واكف ثم واكف)\n(نعم لامرئ لم يبق في الناس مثله ... مفيد لعلم أو صديق ملاطف)\n(تجهز إسحاق إلى الله غاديا ... فلله ما ضمت عليه اللفائف)\n(وما حمل النعش المزجى عشية ... إلى القبر إلا دامع العين لاهف)\n(صدورهم مرضى عليه عميدة ... لها أزمة من ذكره وزفازف)\n(ترى كل محزون تفيض جفونه ... دموعا على الخدين والوجه شاسف)\n(جزيت جزاء المحسنين مضاعفا ... كما كان جدواك الندى المتضاعف)\n(فكم لك فينا من خلائق جزلة ... سبقت بها منها حديث وسالف)\n(هي الشهد أو أحلى إلينا حلاوة ... من الشهد لم يمزج به الماء غارف)\n(ذهبت وخليت الصديق بعولة ... به أسف من حزنه مترادف)\n(إذا خطرات الذكر عاودن قلبه ... تتابع منهن الشؤون النوازف)\n(حبيب إلى الإخوان يرزون ماله ... وآت لما يأتي امرؤ الصدق عارف)\n(هو المن والسلوى لمن يستفيده ... وسم على من يشرب السم زاعف)\n(بكت داره من بعده وتنكرت ... معالم من آفاقها ومعارف)\n(فما الدار بالدار التي كنت أعتري ... وإني بها لولا افتقاديك عارف)\n(هي الدار إلا أنها قد تخشعت ... وأظلم منها جانب فهو كاسف)\n(وبان الجمال والفعال كلاهما ... من الدار واستنت عليها العواصف)\n(خلت داره من بعده فكأنما ... بعاقبة لم يغن في الدار طارف)\n(وقد كان فيها للصديق معرس ... وملتمس إن طاف بالدار طائف)\n(كرامة إخوان الصفاء وزلفة ... لمن جاء تزجيه إليه الرواجف)\n(صحابته الغر الكرام ولم يكن ... ليصحبه السود اللئام المقارف)\n(يؤول إليه كل أبلج شامخ ... ملوك وأبناء الملوك الغطارف)\n(فلقيت في يمنى يديك صحيفة ... إذا نشرت يوم الحساب الصحائف)\n(يسر الذي فيها إذا ما بدا له ... ويفتر منها ضاحكا وهو واقف)\n(بما كان ميمونا على كل صاحب ... يعين على ما نابه ويكانف)\n(سريع إلى إخوانه برضائه ... وعن كل ما ساء الأخلاء صارف)\n(أرى الناس كالنسناس لم يبق منهم ... خلافك إلا حشوة وزعانف)\nخبرنا يحيى بن علي قال أنشدني أبو أيوب لأحمد بن إبراهيم يرثي إسحاق في قصيدة له\n(لقد طاب الحمام غداة ألوى ... بنفس أبي محمد الحمام)\n(فلو قبل الفداء إذا فدته ... ملوك كان يألفها كرام)\n(فلا تبعد فكل فتى سيثوي ... عليه الترب يحثى والرجام)\nقال وقال أيضا يرثيه\n(لله أي فتى إلى دار البلى ... حمل الرجال ضحى على الأعواد)\n(كم من كريم ما تجف دموعه ... من حاضر يبكي عليه وباد)\n(أمسى يؤبنه ويعرف فضله ... من كان يثلبه من الحساد)\n(فسقتك يابن الموصلي روائح ... تروي صداك بصوبها وغواد)\nقد بقيت من أخبار إسحاق بقايا مثل أخباره مع بني هاشم وأخباره مع إبراهيم بن المهدي وغيرها فإنها كثيرة ولها مواضع ذكرت فيها وحسن ذكرها هنالك فأخرتها لذلك عن أخباره التي ذكرت هاهنا حسبما شرطنا في أول الكتاب ومما في المائة المختارة من صنعة إسحاق بن إبراهيم صوت\n(ألا قاتل الله اللوى من محلة ... وقاتل دنيانا بها كيف ذلت)\n(غنينا زمانا باللوى ثم أصبحت ... عراص اللوى من أهلها قد تخلت)","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":96,"spl":"ما رثاه به الشعراء"},
{"id":"b52-145","bab":"الجزء 5","sec":"ما رثاه به الشعراء","page":"ج5 ص445","text":"روضه من الطويل الشعر للصمة القشيري والغناء لإسحاق ولحنه المختار ثقيل أول بالوسطى في مجراها انتهى الجزء الخامس من كتاب الأغاني ويليه الجزء السادس وأوله أخبار الصمة القشيري ونسبه","topic":"نسب إبراهيم الموصلي وأخباره","topicNo":52,"sp":97,"spl":"ما رثاه به الشعراء"},
{"id":"b53-1","bab":"الجزء 5","sec":"أخبار الصمة القشيري ونسبه","page":"ج5 ص449","text":"هو الصمة بن عبد الله بن الطفيل بن قرة بن هبيرة بن عامر بن سلمة الخير بن قشير بن كعب بن ربيعة بن عامر بن صعصعة بن معاوية بن بكر بن هوازن بن منصور بن عكرمة بن خصفة بن قيس بن عيلان بن مضر بن نزار شاعر إسلامي بدوي مقل من شعراء الدولة الأموية ولجده قرة بن هبيرة صحبة بالنبي وهو أحد وفود العرب الوافدين عليه أخبرني بخبره عبيد الله بن محمد الرازي وعمي قالا حدثنا أحمد بن الحارث الخراز عن المدائني عن أبي بكر الهذلي وابن دأب وغيرهما من الوراة قالوا وفد قرة بن هبيرة بن عامر بن سلمة الخير بن قشير بن كعب بن ربيعة إلى النبي فأسلم وقال له يا رسول الله إنا كنا نعبد الآلهة لا تنفعنا ولا تضرنا فقال له رسول الله ( نعم ذا عقلا","topic":"أخبار الصمة القشيري ونسبه","topicNo":53,"sp":0,"spl":"أخبار الصمة القشيري ونسبه"},
{"id":"b53-2","bab":"الجزء 6","sec":"رواية زواجه","page":"ج6 ص5","text":"وقال ابن دأب وكان من خبر الصمة أنه هوي امرأة من قومه ثم من بنات\nعمه دنية يقال لها العامرية بنت غطيف بن حبيب بن قرة بن هبيرة فخطبها إلى أبيها فأبى أن يزوجه إياها وخطبها عامر بن بشر بن أبي براء بن مالك بن ملاعب الأسنة بن جعفر بن كلاب فزوجه إياها وكان عامر قصيرا قبيحا فقال الصمة ابن عبدالله في ذلك\n(فإن تنكحوها عامرا لاطلاعكم ... إليه يدهدهكم برجليه عامر)\nبهه بالجعل الذي يدهده البعرة برجليه قال فلما بنى بها زوجها وجد الصمة بها وجدا شديدا وحزن عليها فزوجه أهله امرأة منهم يقال لها جبرة بنت وحشي بن الطفيل بن قرة بن هبيرة فأقام عليها مقاما يسيرا ثم رحل إلى الشأم غضبا على قومه وخلف امرأته فيهم وقال لها\n(كلي التمر حتى تهرم النخل واضفري ... خطامك ما تدرين ما اليوم من أمس)\nقال فيها أيضا\n(لعمري لئن كنتم على النأي والقلى ... بكم مثل ما بي إنكم لصديق)\n(إذا زفرات الحب صعدن في الحشى ... رددن ولم تنهج لهن طريق)\nقال فيها أيضا\n(إذا ما أتتنا الريح من نحو أرضكم ... أتتنا برياكم فطاب هبوبها)\n(أأتتنا بريح المسك خالط عنبرا ... وريح الخزامى باكرتها جنوبها)\nقال فيها أيضا\n(هل تجزيني العامرية موقفي ... على نسوة بين الحمى وغضى الجمر)\n(مررن بأسباب الصبا فذكرنها ... فأومأت إذ ما من جواب ولا نكر)\nوقال ابن دأب وأخبرني جماعة من بني قشير أن الصمة خرج في غزي من المسلمين إلى بلد الديلم فمات بطبرستان قال ابن دأب وأنشدني جماعة من بني قشير للصمة صوت\n(ألا تسألان الله أن يسقى الحمى ... بلى فسقى الله الحمى والمطاليا)\n(وأسأل من لاقيت هل مطر الحمى ... فهل يسألن عني الحمى كيف حاليا)\nلغناء في هذين البيتين لإسحاق ولحنه من الثقيل الأول بالوسطى وهو\nمن مختار الأغاني ونادرها أخبرني محمد بن خلف وكيع وعمي قالا حدثنا هارون بن محمد بن عبد الملك الزيات قال قال عبد الله بن محمد بن إسماعيل الجعفري حدثنا عبد الله بن إسحاق الجعفري عن عبد العزيز بن أبي ثابت قال حدثني رجل من أهل طبرستان كبير السن قال بينا أنا يوما أمشي في ضيعة لي فيها ألوان من الفاكهة والزعفران وغير ذلك من الأشجار إذ أنا بإنسان في البستان مطروح عليه أهدام خلقان فدنوت منه فإذا هو يتحرك ولا يتكلم فأصغيت إليه فإذا هو يقول بصوت خفي\n(تعز بصبر لا وجدك لا ترى ... بشام الحمى أخرى الليالي الغوابر)\n(كأن فؤادي من تذكره الحمى ... وأهل الحمى يهفو به ريش طائر)\nال فما زال يردد هذين البيتين حتى فاضت نفسه فسألت عنه فقيل لي هذا الصمة بن عبد الله القشيري أخبرني عمي قال حدثنا الخراز أحمد بن الحارث قال كان ابن الأعرابي يستحسن قول الصمة\nصوت\n(أما وجلال الله لو تذكرينني ... كذكريك ما كفكفت للعين مدمعا)\n(فقالت بلى والله ذكرا لو أنه ... يصب على صم الصفا لتصدعا)\nنى في هذين البيتين عبيد الله بن أبي غسان ثاني ثقيل بالوسطى وفيهما لعريب خفيف رمل\n(ولما رأيت البشر قد حال بيننا ... وجالت بنات الشوق في الصدر نزعا)\n(تلفت نحو الحي حتى وجدتني ... وجعت من الإصغاء ليتا وأخدعا)\nخبرني أبو الطيب بن الوشاء قال قال لي إبراهيم بن محمد بن سليمان الأزدي لو حلف حالف أن أحسن أبيات قيلت في الجاهلية والإسلام في الغزل قول الصمة القشيري ما حنث\n(حننت إلى ريا ونفسك باعدت ... مزارك من ريا وشعباكما معا)\n(فما حسن أن تأتي الأمر طائعا ... وتجزع أن داعي الصبابة أسمعا)\n(بكت عيني اليمنى فلما زجرتها ... عن الجهل بعد الحلم أسبلتا معا)\nوت\n(وأذكر أيام الحمى ثم أنثني ... على كبدي من خشية أن تصدعا)\n(فليست عشيات الحمى برواجع ... عليك ولكن خل عينيك تدمعا)\nغنت في هذين البيتين قرشية الزرقاء لحنا من الثقيل الأول عن الهشامي وهذه الأبيات التي أولها حننت إلى ريا تروى لقيس بن ذريح في أخباره وشعره بأسانيد قد ذكرت في مواضعها ويروى بعضها للمجنون في أخباره بأسانيد قد ذكرت أيضا في أخباره والصحيح في البيتين الأولين أنهما لقيس بن ذريح وروايتهما له أثبت وقد تواترت الروايات بأنهما له من عدة طرق والأخر مشكوك فيها أهي للمجنون أم للصمة أنشدنا محمد بن الحسن بن دريد عن أبي حاتم للصمة القشيرعمي عن الكراني عن أبي حاتم وأنشدنيهما الحسن بن علي عن ابن مهرويه عن أبي حاتم","topic":"أخبار الصمة القشيري ونسبه","topicNo":53,"sp":1,"spl":"رواية زواجه"},
{"id":"b53-3","bab":"الجزء 6","sec":"رواية زواجه","page":"ج6 ص5","text":"(إذا نأت لم تفارقني علاقتها ... وإن دنت فصدود العاتب الزاري)\n(فحال عيني من يوميك واحدة ... تبكي لفرط صدود أو نوى دار)","topic":"أخبار الصمة القشيري ونسبه","topicNo":53,"sp":2,"spl":"رواية زواجه — من المائة المختارة من رواية يحيى بن علي"},
{"id":"b53-4","bab":"الجزء 6","sec":"شعره في محبوبته","page":"ج6 ص10","text":"أخبرني حبيب بن نصر المهلبي قال حدثنا عبيد الله بن إسحاق بن سلام قال حدثني أبي عن شعيب بن صخر عن بعض بني عقيل قال مررت بالصمة بن عبد الله القشيري يوما وهو جالس وحده يبكي ويخاطب نفسه ويقول لا والله ما صدقتك فيما قالت فقلت من تعني ويحك\nأجننت قال أعني التي أقول فيها\n(أما وجلال الله لو تذكرينني ... كذكريك ما كفكفت للعين مدمعا)\n(فقالت بلى والله ذكرا لو أنه ... يصب على صم الصفا لتصدعا)\nسلي نفسي عنها وأخبرها أنها لو ذكرتني كما قالت لكانت في مثل حالي أخبرني عمي قال حدثنا عبد الله بن أبي سعد قال حدثني مسعود بن عيسى ابن إسماعيل العبدي عن موسى بن عبد الله التيمي قال خطب الصمة القشيري بنت عمه وكان لها محبا فاشتط عليه عمه في المهر فسأل أباه أن يعاونه وكان كثير المال فلم يعنه بشيء فسأل عشيرته فأعطوه فأتى بالإبل عمه فقال لا أقبل هذه في مهر ابنتي فاسأل أباك أن يبدلها لك فسأل أباه فأبى عليه فلما رأى ذلك من فعلهما قطع عقلها وخلاها فعاد كل بعير منها إلى ألافه وتحمل الصمة راحلا فقالت بنت عمه حين رأته يتحمل تالله ما رأيت كاليوم رجلا باعته عشيرته بأبعرة ومضى من وجهه حتى لحق بالثغر فقال وقد طال مقامه واشتاقها وندم على فعله\n(أتبكي على ريا ونفسك باعدت ... مزارك من ريا وشعباكما معا)\n(فما حسن أن تأتي الأمر طائعا ... وتجزع أن داعي الصبابة أسمعا)\nقد أخبرني بهذا الخبر جعفر بن قدامة قال حدثني حماد بن إسحاق عن أبيه عن الهيثم بن عدي أن الصمة خطب ابنة عمه هذه إلى أبيها فقال له لا أزوجكها إلا على كذا وكذا من الإبل فذهب إلى أبيه فأعلمه بذلك وشكا إليه ما\nيجد بها فساق الإبل عنه إلى أخيه فلما جاء بها عدها عمه فوجدها تنقص بعيرا فقال لا آخذها إلا كاملة فغضب أبوه وحلف لا يزيده على ما جاء به شيئا ورجع إلى الصمة فقال له ما وراءك فأخبره فقال تالله ما رأيت قط ألأم منكما جميعا وإني لألأم منكما إن أقمت بينكما ثم ركب ناقته ورحل إلى ثغر من الثغور فأقام به حتى مات وقال في ذلك\n(أمن ذكر دار بالرقاشين أصبحت ... بها عاصفات الصيف بدءا ورجعا)\n(حننت إلى ريا ونفسك باعدت ... مزارك من ريا وشعباكما معا)\n(فما حسن أن تأتي الأمر طائعا ... وتجزع أن داعي الصبابة أسمعا)\n(كأنك لم تشهد وداع مفارق ... ولم تر شعبى صاحبين تقطعا)\n(بكت عيني اليسرى فلما زجرتها ... عن الجهل بعد الحلم أسبلتا معا)\n(تحمل أهلي من قنين وغادروا ... به أهل ليلى حين جيد وأمرعا)\n(ألا يا خليلى اللذين تواصيا ... بلومي إلا أن أطيع وأسمعا)\n(قفا إنه لا بد من رجع نظرة ... يمانية شتى بها القوم أو معا)\n(لمغتصب قد عزه القوم أمره ... حياء يكف الدمع أن يتطلعا)\n(تبرض عينيه الصبابة كلما ... دنا الليل أو أوفى من الأرض ميفعا)\n(فليست عشيات الحمى برواجع ... إليك ولكن خل عينيك تدمعا)\nصوت","topic":"أخبار الصمة القشيري ونسبه","topicNo":53,"sp":2,"spl":"رواية زواجه — من المائة المختارة من رواية يحيى بن علي"},
{"id":"b53-5","bab":"الجزء 6","sec":"من المائة المختارة من رواية يحيى بن علي","page":"ج6 ص13","text":"(قل لأسماء أنجزي الميعادا ... وانظري أن تزودي منك زادا)\n(إن تكوني حللت ربعا من الشأم ... وجاورت حميرا أو مرادا)\n(أو تناءت بك النوى فلقد قدت ... فؤادي لحينه فانقادا)\n(ذاك أني علقت منك جوى الحب ... وليدا فزدت سنا فزادا)\nلشعر لداود بن سلم والغناء لدحمان ولحنه المختار من الثقيل الأول بالوسطى وقد كنا وجدنا هذا الشعر في رواية علي بن يحيى عن إسحاق منسوبا إلى المرقشين المرقش وطلبناه في أشعار المرقشين جميعا فلم نجده وكنا نظنه من شاذ\nالروايات حتى وقع إلينا في شعر داود بن سلم وفي خبر أنا ذاكره في أخبار داود وإنما نذكر ما وقع إلينا عن رواته فما وقع من غلط فوجدناه أو وقفنا على صحته أثبتناه وأبطلنا ما فرط منا غيره وما لم يجر هذا المجرى فلا ينبغي لقارىء هذا الكتاب أن يلزمنا لوم خطأ لم نتعمده ولا اخترعناه وإنما حكيناه عن رواته واجتهدنا في الإصابة وإن عرف صوابا مخالفا لما ذكرناه وأصلحه فإن ذلك لا يضره ولا يخلو به من فضل وذكر جميل إن شاء الله","topic":"أخبار الصمة القشيري ونسبه","topicNo":53,"sp":2,"spl":"رواية زواجه — من المائة المختارة من رواية يحيى بن علي"},
{"id":"b54-1","bab":"الجزء 6","sec":"أخبار داود بن سلم ونسبه","page":"ج6 ص15","text":"داود بن سلم مولى بني تيم بن مرة بن كعب بن لؤي ثم يقول بعض الرواة إنه مولى آل أبي بكر ويقول بعضهم إنه مولى آل طلحة وهو مخضرم من شعراء الدولتين الأموية والعباسية من ساكني المدينة يقال له داود الآدم وداود الأرمك وكان من أقبح الناس وجها وكان سعد بن إبراهيم بن عبد الرحمن بن عوف يستثقله فرآه ذات يوم يخطر خطرة منكرة فدعا به وكان يتولى المدينة فضربه ضربا مبرحا وأظهر أنه إنما فعل ذلك به من أجل الخطرة التي تخايل فيها في مشيته فقال بعض الشعراء في ذلك وأظنه ابن رهيمة\n(ضرب العادل سعد ... ابن سلم في السماجه)\n(فقضى الله لسعد ... من أمير كل حاجه)\nخبرني محمد بن سليمان الطوسي قال حدثنا الزبير بن بكار قال سألت محمد بن موسى بن طلحة عن داود بن سلم هل هو مولاهم\nفقال كذلك يقول الناس هو مولانا أبوه رجل من النبط وأمه بنت حوط مولى عمر بن عبيد الله بن معمر فانتسب إلى ولاء أمه وفي ذلك يقول ويمدح ابن معمر\n(وإذا دعا الجاني النصير لنصره ... وارتني الغرر النصيرة معمر)\n(متخازرين كأن أسد خفية ... بمقامها مستبسلات تزأر)\n(متجاسرين بحمل كل ملمة ... متجبرين على الذي يتجبر)\n(عسل الرضا فإذا أردت خصامهم ... خلط السمام بفيك صاب ممقر)\n(لا يطبعون ولا ترى أخلاقهم ... إلا تطيب كما يطيب العنبر)\n(رفعوا بناي بعتق حوط دنية ... جدي وفضلهم الذي لا ينكر)","topic":"أخبار داود بن سلم ونسبه","topicNo":54,"sp":0,"spl":"أخبار داود بن سلم ونسبه — نسبة ما في هذا الخبر من الشعر الذي فيه غناء"},
{"id":"b54-2","bab":"الجزء 6","sec":"بعض من أوصافه","page":"ج6 ص16","text":"أخبرني أحمد بن عبد العزيز الجوهري وحبيب بن نصر المهلبي قالا حدثنا عمر بن شبة قال حدثني إسحاق الموصلي قال\nكان داود بن سلم مولى بني تيم بن مرة وكان يقال له الآدم لشدة سواده وكان من أبخل الناس فطرقه قوم وهو بالعقيق فصاحوا به العشاء والقرى يا بن سلم فقال لهم لا عشاء لكم عندي ولا قرى قالوا فأين قولك في قصيدتك إذ تقول فيها\n(يا دار هند ألا حييت من دار ... لم أقض منك لباناتي وأوطاري)\n(عودت فيها إذا ما الضيف نبهني ... عقر العشار على يسري وإعساري)\nال لستم من أولئك الذين عنيت قال ودخل على السري بن عبد الله الهاشمي وقد أصيب بابن له فوقف بين يديه ثم أنشده\n(يا من على الأرض من عجم ومن عرب ... استرجعوا خاست الدنيا بعباس)\n(فجعت من سبعة قد كنت آملهم ... من ضنء والدهم بالسيد الراس)\nال وداود بن سلم الذي يقول\n(قل لأسماء أنجزي الميعادا ... وانظري أن تزودي منك زادا)\n(إن تكوني حللت ربعا من الشأم ... وجاورت حميرا أو مرادا)\n(أو تناءت بك النوى فلقد قدت ... فؤادي لحينه فانقادا)\n(ذاك أني علقت منك جوى الحب ... وليدا فزدت سنا فزادا)\nال أبو زيد أنشدنيها أبو غسان محمد بن يحيى وإبراهيم بن المنذر لداود ابن سلم","topic":"أخبار داود بن سلم ونسبه","topicNo":54,"sp":0,"spl":"أخبار داود بن سلم ونسبه — نسبة ما في هذا الخبر من الشعر الذي فيه غناء"},
{"id":"b54-3","bab":"الجزء 6","sec":"نسبة ما في هذا الخبر من الشعر الذي فيه غناء","page":"ج6 ص17","text":"صوت\n(يا دار هند ألا حييت من دار ... لم أقض منك لباناتي واوطاري)\nتم وينسب","topic":"أخبار داود بن سلم ونسبه","topicNo":54,"sp":0,"spl":"أخبار داود بن سلم ونسبه — نسبة ما في هذا الخبر من الشعر الذي فيه غناء"},
{"id":"b54-4","bab":"الجزء 6","sec":"المادح المزجور","page":"ج6 ص18","text":"أخبرنا الطوسي قال حدثنا الزبير قال أخبرني مصعب بن عثمان قال دعا الحسن بن زيد إسحاق بن إبراهيم بن طلحة بن عمر بن عبيد الله بن معمر التيمي أيام كان بالمدينة إلى ولاية القضاء فأبى عليه فحبسه فدعا مسرقين يسرقون له مغسلا في السجن وجاء بنو طلحة فانسجنوا معه وبلغ ذلك الحسن بن زيد فأرسل إليه فأتي به فقال إنك تلاججت علي وقد حلفت ألا أرسلك حتى تعمل لي فأبرر يميني ففعل فأرسل الحسن معه جندا حتى جلس في المسجد مجلس القضاء والجند على رأسه فجاءه داود بن سلم فوقف عليه فقال\n(طلبوا الفقه والمروءة والحلم ... وفيك اجتمعن يا إسحاق)\nقال ادفعوه فدفعوه فنحي عنه فجلس ساعة ثم قام من مجلسه فأعفاه الحسن بن زيد من القضاء فلما سار إلى منزله أرسل إلى داود بن سلم بخمسين دينارا وقال للرسول قل له يقول لك مولاك ما حملك على أن تمدحني بشيء أكرهه استعن بهذه على أمرك\nأخبرني الحرمي بن أبي العلاء قال حدثنا الزبير ابن بكار قال حدثني محرز بن سعيد قال بينما سعد بن إبراهيم في مسجد النبي يقضي بين الناس إذ دخل عليه زيد بن إسماعيل بن عبد الله بن جعفر ومعه داود بن سلم مولى التيميين وعليهما ثياب ملونة يجرانها فأومأ أن يؤتى بهما فاشار إليه زيد أن اجلس فجلس بالقرب منه وأومأ إلى الآخر أن يجلس حيث يجلس مثله ثم قال لعون من أعوانه ادع لي نوح بن إبراهيم بن محمد بن طلحة بن عبيد الله فدعي له فجاء أحسن الناس سمتا وتشميرا ونقاء ثياب فأشار إلى فجلس ثم أقبل على زيد فقال له يابن أخي تشبه بشيخك هذا وسمته وتشميره ونقاء ثوبه ولا تعد إلى هذا اللبس قم فانصرف ثم أقبل على ابن سلم وكان قبيحا فقال له هذا ابن جعفر أحتمل هذا له وأنت لأي شيء أحتمل هذا لك أللؤم أصلك أم لسماجة وجهك جرد يا غلام فجرد فضربه أسواطا فقال ابن رهيمة\n(جلد العادل سعد ... إبن سلم في السماجه)\n(فقضى الله لسعد ... من أمير كل حاجه)\nخبرني الحرمي قال حدثنا الزبير بن بكار قال حدثني يعقوب بن حميد بن كاسب قال حدثني عبد الملك بن عبد العزيز بن الماجشون عن يوسف بن الماجشون قال\nقال لي أبي وقد عزل سعد بن إبراهيم عن القضاء يا بني تعجل بنا عسى أن نروح مع سعد بن إبراهيم فإن القاضي إذا عزل لم يزل الناس ينالون منه فخرجنا حتى جئنا دار سعد بن إبراهيم فإذا صوت عال فقال لي أي شيء هذا أرى أنه قد أعجل علي ودخلنا فإذا داود بن سلم يقول له أطال الله بقاءك يا أبا إسحاق وفعل بك وقد كان سعد جلد داود بن سلم أربعين سوطا فأقبل علي سعد وعلى أبي فقال لم تر مثل أربعين سوطا في ظهر لئيم قال وفيه يقول الشاعر\n(ضرب العادل سعد ... إبن سلم في السماجه)\n(فقضى الله لسعد ... من أمير كل حاجه)","topic":"أخبار داود بن سلم ونسبه","topicNo":54,"sp":1,"spl":"المادح المزجور — الحسن بن زيد يغضب منه"},
{"id":"b54-5","bab":"الجزء 6","sec":"الحسن بن زيد يغضب منه","page":"ج6 ص20","text":"أخبرني محمد بن خلف وكيع قال قال الزبير بن بكار قال حدثني أبو يحيى الزهري واسمه هارون بن عبد الله قال حدثني عبد الملك بن عبد العزيز عن أبيه قال كان الحسن بن زيد قد عود داود بن سلم مولى بني تيم إذا جاءته غلة من الخانقين أن يصله فلما مدح داود بن سلم جعفر بن سليمان وكان بينه وبين الحسن بن زيد تباعد شديد أغضب ذلك الحسن فقدم من حج أو عمرة ودخل عليه داود مسلما فقال له الحسن أنت القائل في جعفر\n(وكنا حديثا قبل تأمير جعفر ... وكان المنى في جعفر أن يؤمرا)\n(حوى المنبرين الطاهرين كليهما ... إذا ما خطا عن منبر أم منبرا)\n(كأن بني حواء صفوا أمامه ... فخبر من أنسابهم فتخيرا)\nفقال داود نعم جعلني الله فداءكم فكنتم خيرة اختياره وأنا الذي أقول\n(لعمري لئن عاقبت أوجدت منعما ... بعفو عن الجاني وإن كان معذرا)\n(لأنت بما قدمت أولى بمدحة ... وأكرم فرعا إن فخرت وعنصرا)\n(هو الغرة الزهراء من فرع هاشم ... ويدعو عليا ذا المعالي وجعفرا)\n(وزيد الندى والسبط سبط محمد ... وعمك بالطف الزكي المطهرا)\n(وما نال من ذا جعفر غير مجلس ... إذا ما نفاه العزل عنه تأخرا)\n(بحقكم نالوا ذراها فأصبحوا ... يرون به عزا عليكم ومفخرا)\nال فعاد الحسن بن زيد له إلى ما كان عليه ولم يزل يصله ويحسن إليه حتى مات قال أبو يحيى يعني بقوله وإن كان معذرا أن جعفرا أعطاه بأبياته الثلاثة ألف دينار فذكر أن له عذرا في مدحه إياه بجزالة إعطائه","topic":"أخبار داود بن سلم ونسبه","topicNo":54,"sp":1,"spl":"المادح المزجور — الحسن بن زيد يغضب منه"},
{"id":"b54-6","bab":"الجزء 6","sec":"أبو السائب المخزومي يعجب بشعره","page":"ج6 ص21","text":"أخبرني الحسين بن يحيى عن حماد بن إسحاق عن أبيه عن الواقدي عن ابن أبي الزناد قال كنت ليلة عند الحسن بن زيد ببطحاء ابن أزهر على ستة أميال من المدينة حيال ذي الحليفة نصف الليل جلوسا في القمر وأبو السائب المخزومي معنا وكان ذا فضل وكان مشغوفا بالسماع والغزل وبين أيدينا طبق\nعليه فريك فنحن نصيب منه والحسن يومئذ عامل المنصور على المدينة فأنشد الحسن قول داود بن سلم وجعل يمد به صوته ويطربه صوت\n(فعرسنا ببطن عريتنات ... ليجمعنا وفاطمة المسير)\n(أتنسى إذ تعرض وهو باد ... مقلدها كما برق الصبير)\n(ومن يطع الهوى يعرف هواه ... وقد ينبيك بالأمر الخبير)\n(على أني زفرت غداة هرشى ... فكاد يريبهم مني الزفير)\nالغناء للغريض ثاني ثقيل بالسبابة في مجرى البنصر عن إسحاق وفيه للهذلي ثاني ثقيل بالوسطى عن عمرو بن بانة وأظنه هذا اللحن قال فأخذ أبو السائب الطبق فوحش به إلى السماء فوقع الفريك على رأس الحسن بن زيد فقال له مالك ويحك أجننت فقال له أبو السائب أسألك بالله وبقرابتك من رسول الله إلا ما أعدت إنشاد هذا الصوت ومددته كما فعلت قال فما ملك الحسن نفسه ضحكا ورد الحسن الأبيات لإستحلافه إياه قال ابن أبي الزناد فلما خرج أبو السائب قال لي يا بن أبي الزناد أما سمعت مده\n(ومن يطع الهوا يعرف هواه ... )\nقلت نعم قال لو علمت أنه يقبل لدفعته إليه بهذه الثلاثة الأبيات أخبرني بخبره عبيد الله بن محمد الرازي وعمي قالا حدثنا أحمد بن الحارث الخراز عن المدائني عن أبي بكر الهذلي أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثتني ظبية مولاة فاطمة بنت عمر بن مصعب قالت أرسلتني مولاتي فاطمة في حاجة فمررت برحبة القضاء فإذا بضبيعة العبسي خليفة جعفر بن سليمان يقضي بين الناس فأرسل إلي فدعاني وقد كنت رطلت شعري وربطت في أطرافه من ألوان العهن فقال ما هذا فقلت شيء أتملح به فقال يا حرسي قنعها بالسوط قالت فتناولت السوط بيدي وقلت قاتلك الله ما أبين الفرق بينك وبين سعد بن إبراهيم سعد يجلد الناس\nفي السماجة وأنت تجلدهم في الملاحة وقد قال الشاعر\n(جلد العادل سعد ... إبن سلم في السماجه)\n(فقضى الله لسعد ... من أمير كل حاجه)\nالت فضحك حتى ضرب بيديه ورجليه وقال خل عنها قالت فكان يسوم بي وكانت مولاتي تقول لا أبيعها إلا أن تهوى ذلك وأقول لا أريد بأهلي بدلا إلى أن مررت يوما بالرحبة وهو في منظرة دار مروان ينظر فأرسل إلي فدعاني فوجدته من وراء كلة وأنا لا أشعر به وحازم وجرير جالسان فقال لي حازم الأمير يريدك فقلت لا أريد بأهلي بدلا وكشفت الكلة عن جعفر بن سليمان فارتعت لذلك فقلت آه فقال مالك فقلت\n(سمعت بذكر الناس هندا فلم أزل ... أخا سقم حتى نظرت إلى هند)\nال فأبصرت ماذا ويحك فقلت\n(فأبصرت هندا حرة غير أنها ... تصدى لقتل المسلمين على عمد)\nالت فضحك حتى استلقى وأرسل إلى مولاتي ليبتاعني فقالت لا والله لا أبيعها حتى تستبيعني فقلت والله لا أستبيعك أبدا","topic":"أخبار داود بن سلم ونسبه","topicNo":54,"sp":2,"spl":"أبو السائب المخزومي يعجب بشعره","partial":1},
{"id":"b54-7","bab":"الجزء 6","sec":"يذكر قثم بن عباس بجارية كان يهواها","page":"ج6 ص24","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثنا يونس بن عبد الله عن داود بن سلم قال كنت يوما جالسا مع قثم بن العباس قبل أن يملكوا بفنائه فمرت بنا\nجارية فأعجب بها قثم وتمناها فلما يمكنه ثمنها فلما ولي قثم اليمامة اشترى الجارية إنسان يقال له صالح قال داود بن سلم فكتبت إلى قثم\n(يا صاحب العيس ثم راكبها ... أبلغ إذا ما لقيته قثما)\n(أن الغزال الذي أجاز بنا ... معارضا إذ توسط الحرما)\n(حوله صالح فصار مع الإنس ... وخلى الوحوش والسلما)\nال فأرسل قثم في طلب الجارية ليشتريها فوجدها قد ماتت أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثنا عبد الله بن محمد بن موسى بن طلحة قال حدثني زهير بن حسن مولى آل الربيع بن يونس أن داود بن سلم خرج إلى حرب بن خالد بن يزيد بن معاوية فلما نزل به حط غلمانه متاع داود وحلوا عن راحلته فلما دخل عليه أنشأ يقول\n(ولما دفعت لأبوابهم ... ولاقيت حربا لقيت النجاحا)\n(وجدناه يحمده المجتدون ... ويأبى على العسر إلا سماحا)\n(ويغشون حتى يرى كلبهم ... يهاب الهرير وينسى النباحا)\nال فأجازه بجائزة عظيمة ثم استأذنه في الخروج فأذن له وأعطاه ألف دينار فلم يعنه أحد من غلمانه ولم يقوموا إليه فظن أن حربا ساخط عليه فرجع إليه فأخبره بما رأى من غلمانه فقال له سلهم لم فعلوا بك ذلك قال فسألهم فقالوا إننا ننزل من جاءنا ولا نرحل من خرج عنا قال فسمع الغاضري حديثه فأتاه فحدثه فقال أنا يهودي إن لم يكن الذي قال الغلمان أحسن من شعرك","topic":"أخبار داود بن سلم ونسبه","topicNo":54,"sp":3,"spl":"يذكر قثم بن عباس بجارية كان يهواها — من شعره في الغزل"},
{"id":"b54-8","bab":"الجزء 6","sec":"من شعره في الغزل","page":"ج6 ص26","text":"وذكر محمد بن داود بن الجراح أن عمر بن شبة أنشده ابن عائشة لداود بن سلم فقال أحسن والله داود حيث يقول\n(لججت من حبي في تقريبه ... وعميت عيناي عن عيوبه)\n(كذاك صرف الدهر في تقليبه ... لا يلبث الحبيب عن حبيبه)\n(أو يغفر الأعظم من ذنوبه ... )\nال وأنشدني أحمد بن يحيى عن عبد الله بن شبيب لداود بن سلم قال\n(وما ذر قرن الشمس إلا ذكرتها ... وأذكرها في وقت كل غروب)\n(وأذكرها ما بين ذاك وهذه ... وبالليل أحلامي وعند هبوبي)\n(وقد شفني شوقي وأبعدني الهوى ... وأعيا الذي بي طب كل طبيب)\n(وأعجب أني لا أموت صبابة ... وما كمد من عاشق بعجيب)\n(وكل محب قد سلا غير أنني ... غريب الهوى يا ويح كل غريب)\n(وكم لام فيها من أخ ذي نصيحة ... فقلت له أقصر فغير مصيب)\n(أتأمر إنسانا بفرقة قلبه ... أتصلح أجسام بغير قلوب)\nخبرني إسماعيل بن يونس الشيعي قال حدثنا عمر بن شبة قال حدثني أبو غسان قال كان داود بن سلم منقطعا إلى قثم بن العباس وفيه يقول\n(عتقت من حلي ومن رحلتي ... ياناق إن أدنيتني من قثم)\n(إنك إن أدنيت منه غدا ... حالفني اليسر ومات العدم)\n(في وجهه بدر وفي كفه ... بحر وفي العرنين منه شمم)\n(أصم عن قيل الخنا سمعه ... وما عن الخير به من صمم)\n(لم يدر ما لا وبلى قد درى ... فعافها واعتاض منها نعم)\nال أبو إسحاق إسماعيل بن يونس قال أبو زيد عمر بن شبة قال لي إسحاق لنظم العمياء في هذه الأبيات صنعة عجيبة وكانت تجيدها ما شاءت إذا غنتها","topic":"أخبار داود بن سلم ونسبه","topicNo":54,"sp":3,"spl":"يذكر قثم بن عباس بجارية كان يهواها — من شعره في الغزل","partial":1},
{"id":"b55-1","bab":"الجزء 6","sec":"أخبار دحمان ونسبه","page":"ج6 ص28","text":"دحمان لقب لقب به واسمه عبد الرحمن بن عمرو مولى بني ليث بن بكر بن عبد مناة بن كنانة ويكنى أبا عمرو ويقال له دحمان الأشقر قال إسحاق كان دحمان مع شهرته بالغناء رجلا صالحا كثير الصلاة معدل الشهادة مدمنا للحج وكان كثيرا ما يقول ما رأيت باطلا أشبه بحق من الغناء قال إسحاق وحدثني الزبيري أن دحمان شهد عند عبد العزيز بن المطلب بن عبد الله بن حنطب المخزومي وهو يلي القضاء لرجل من أهل المدينة على رجل من أهل العراق بشهادة فأجازها وعدله فقال له العراقي إنه دحمان قال أعرفه ولو لم أعرفه لسألت عنه قال إنه يغني ويعلم الجواري الغناء قال غفر الله لنا ولك وأينا لا يتغنى اخرج إلى الرجل عن حقه وفي دحمان يقول أعشى بني سليم\n(إذا ما هزج الوادي ... أو ثقل دحمان)\n(سمعت الشدو من هذا ... ومن هذا بميزان)\n(فهذا سيد الإنس ... وهذا سيد الجان)\nوفيه يقول أيضا\n(كانوا فحولا فصاروا عند خلبتهم ... لما انبرى لهم دحمان خصيانا)\n(فأبلغوه عن الأعشى مقالته ... أعشى سليم أبي عمرو سليمانا)\n(قولوا يقول أبو عمرو لصحبته ... ياليت دحمان قبل الموت غنانا)\nخبرني رضوان بن أحمد الصيدلاني قال حدثنا يوسف بن إبراهيم عن إبراهيم بن المهدي أنه حدثه عن ابن جامع وزبير بن دحمان جميعا أن دحمان كان معدلا مقبول الشهادة عند القضاة بالمدينة وكان أبو سعيد مولى فائد أيضا ممن تقبل شهادته وكان دحمان من رواة معبد وغلمانه المتقدمين قال وكان معبد في أول أمره مقبول الشهادة فلما حضر الوليد بن يزيد وعاشره على تلك الهنات وغنى له سقطت عدالته لا لأن شيئا بان عليه من دخول في محظور ولكن لأنه اجتمع مع الوليد على ما كان يستعمله أخبرنا يحيى بن علي بن يحيى قال حدثنا أبو أيوب المديني قال قال إسحاق كان دحمان يكنى أبا عمرو مولى بني ليث واسمه عبد الرحمن وكان يخضب رأسه ولحيته بالحناء وهو من غلمان معبد قال إسحاق وكان أبي لا يضعه بحيث يضعه الناس ويقول لو كان عبدا ما اشتريته على الغناء بأربعمائة درهم وأشبه الناس به في الغناء ابنه عبد الله وكان يفضل الزبير ابنه تفضيلا شديدا على عبد الله أخيه وعلى دحمان أبيه","topic":"أخبار دحمان ونسبه","topicNo":55,"sp":0,"spl":"أخبار دحمان ونسبه — نسبة هذا الصوت"},
{"id":"b55-2","bab":"الجزء 6","sec":"دحمان يحظى عند المهدي","page":"ج6 ص30","text":"أخبرني يحيى عن أبي أيوب عن أحمد بن المكي عن عبد الله بن دحمان قال رجع أبي من عند المهدي وفي حاصله مائة ألف دينار أخبرنا إسماعيل بن يونس وحبيب بن نصر المهلبي قالا حدثنا عمر بن شبة قال بلغني أن المهدي أعطى دحمان في ليلة واحدة خمسين ألف دينار وذلك أنه غنى في شعر الأحوص\n(قطوف المشي إذ تمشي ... ترى في مشيها خرقا)\nأعجبه وطرب واستخفه السرور حتى قال لدحمان سلني ما شئت فقل ضيعتان بالمدينة يقال لهما ريان وغالب فأقطعه إياهما فلما خرج التوقيع بذلك إلى أبي عبيد الله وعمر بن بزيع راجعا المهدي فيه وقالا إن هاتين ضيعتان لم يملكهما قط إلا خليفة وقد استقطعهما ولاة العهود في أيام بني أمية فلم\nيقطعوهما فقال والله لا أرجع فيهما إلا بعد أن يرضى فصولح عنهما على خمسين ألف دينار","topic":"أخبار دحمان ونسبه","topicNo":55,"sp":0,"spl":"أخبار دحمان ونسبه — نسبة هذا الصوت"},
{"id":"b55-3","bab":"الجزء 6","sec":"نسبة هذا الصوت","page":"ج6 ص31","text":"سرى ذا الهم بل طرقا ... فبت مسهدا قلقا كذاك الحب مما يحدث ... التسهيد والأرقا قطوف المشي إذ تمشي ... ترى في مشيها خرقا وتثقلها عجيزتها ... إذا ولت لتنطلقا\nالشعر للأحوص والغناء لدحمان ثقيل أول بالوسطى عن عمرو وذكر الهشامي أنه لإبن سريج أخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة عن إسحاق قال مر دحمان المغني وعليه رداء جيد عدني فقال له من حضر بكم اشتريت هذا يا أبا عمرو قال ب\n(ما ضر جيراننا إذ انتجعوا ... )\nسبة هذا الصوت صوت\n(ما ضر جيراننا إذ انتجعوا ... لو أنهم قبل بينهم ربعوا)\n(أحموا على عاشق زيارته ... فهو بهجران بينهم قطع)\n(وهو كأن الهيام خالطه ... وما به غير حبها ذرع)\n(كأن لبنى صبير غادية ... أو دمية زينت بها البيع)\n(الله بيني وبين قيمها ... يفر عني بها وأتبع)","topic":"أخبار دحمان ونسبه","topicNo":55,"sp":0,"spl":"أخبار دحمان ونسبه — نسبة هذا الصوت","partialRef":{"sid":"b45-6","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b55-4","bab":"الجزء 6","sec":"الوليد يكرم دحمان","page":"ج6 ص32","text":"أخبرني وكيع عن أبي أيوب المديني إجازة عن أبي محمد العامري الأويسي قال كان دحمان جمالا يكري إلى المواضع ويتجر وكانت له مروءة فبينا هو ذات يوم قد أكرى جماله وأخذ ماله إذ سمع رنة فقام واتبع الصوت فإذا جارية قد خرجت تبكي فقال لها أمملوكة أنت قالت نعم فقال لمن فقالت لإمرأة من قريش وسمتها له فقال أتبيعك قالت نعم ودخلت إلى مولاتها فقالت هذا إنسان يشتريني فقالت ائذني له فدخل فسامها حتى استقر أمر الثمن بينهما على مائتي دينار فنقدها إياها وانصرف بالجارية قال دحمان فأقامت عندي مدة اطرح عليها ويطرح عليها معبد والأبجر ونظراؤهما من المغنين ثم خرجت بها بعد ذلك إلى الشأم وقد حذقت وكنت لا أزال إذا نزلنا أنزل الأكرياء ناحية وأنزل معتزلا بها ناحية في محمل وأطرح على المحمل من أعبية الجمالين وأجلس أنا وهي تحت ظلها فأخرج شيئا فنأكله ونضع ركوة فيها لنا شراب فنشرب ونتغنى حتى نرحل ولم نزل كذلك حتى قربنا من الشأم فبينا أنا ذات يوم نازل وأنا ألقي عليها لحني\nصوت\n(لو رد ذو شفق حمام منية ... لرددت عن عبد العزيز حماما)\n(صلى عليك الله من مستودع ... جاورت بوما في القبور وهاما)\nلشعر لكثير يرثي عبد العزيز بن مروان وزعم بعض الرواة أن هذا الشعر ليس لكثير وأنه لعبد الصمد بن علي الهشامي يرثي إبنا له والغناء لدحمان ولحنه من الثقيل الأول بالخنصر في مجرى البنصر قال فرددته عليها حتى أخذته واندفعت تغنيه فإذا أنا براكب قد طلع فسلم علينا فرددنا عليه السلام فقال أتأذنون لي أن أنزل تحت ظلكم هذا ساعة قلنا نعم فنزل وعرضت عليه طعامنا وشرابنا فأجاب فقدمنا إليه السفرة فأكل وشرب معنا واستعاد الصوت مرارا ثم قال للجارية أتغنين لدحمان شيئا قالت نعم قال فغنته أصواتا من صنعتي وغمزتها ألا تعرفه أني دحمان فطرب وامتلأ سرورا وشرب أقداحا والجارية تغنيه حتى قرب وقت الرحيل فأقبل علي وقال أتبيعني هذه الجارية فقلت نعم قال بكم قلت كالعابث بعشرة آلاف دينار قال قد أخذتها بها فهلم دواة وقرطاسا فجئته بذلك فكتب إدفع إلى حامل كتابي هذا حين تقرؤه عشرة آلاف دينار واستوص به خيرا وأعلمني بمكانه وختم الكتاب ودفعه إلي ثم قال أتدفع إلي الجارية أم تمضي بها معك حتى تقبض\nمالك فقلت بل أدفعها إليك فحملها وقال إذا جئت البخراء فسل عن فلان وادفع كتابي هذا إليه واقبض منه مالك ثم انصرف بالجارية قال ومضيت فلما وردت البخراء سألت عن اسم الرجل فدللت عليه فإذا داره دار ملك فدخلت عليه ودفعت إليه الكتاب فقبله ووضعه على عينيه ودعا بعشرة آلاف دينار فدفعها إلي وقال هذا كتاب أمير المؤمنين وقال لي اجلس حتى أعلم أمير المؤمنين بك فقلت له حيث كنت فأنا عبدك وبين يديك وقد كان أمر لي بأنزال وكان بخيلا فاغتنمت ذلك فارتحلت وقد كنت أصبت بجملين وكانت عدة أجمالي خمسة عشر فصارت ثلاثة عشر قال وسأل عني الوليد فلم يدر القهرمان أين يطلبني فقال له الوليد عدة جماله خمسة عشر جملا فاردده إلي فلم أوجد لأنه لم يكن في الرفقة من معه خمسة عشر جملا ولم يعرف اسمي فيسأل عني قال وأقامت الجارية عنده شهرا لا يسأل عنها ثم دعاها بعد أن استبرئت وأصلح من شأنها فظل معها يومه حتى إذا كان في آخر نهاره قال لها غنيني لدحمان فغنت وقال لها زيديني فزادت ثم أقبلت عليه فقالت يا أمير المؤمنين أو ما سمعت غناء دحمان منه قال لا قالت بلى والله قال أقول لك لا فتقولين بلى والله فقالت بلى والله لقد سمعته قال وما ذاك ويحك قالت إن الرجل الذي اشتريتني منه هو دحمان قال أو ذلك هو قالت نعم هو هو قال فكيف لم أعلم قالت غمزني بألا أعلمك فأمر فكتب إلى عامل المدينة بأن يحمل إليه دحمان فحمل فلم يزل عنده أثيرا أخبرني محمد بن مزيد بن أبي الأزهر قال حدثنا حماد بن إسحاق عن أبيه","topic":"أخبار دحمان ونسبه","topicNo":55,"sp":1,"spl":"الوليد يكرم دحمان"},
{"id":"b55-5","bab":"الجزء 6","sec":"الوليد يكرم دحمان","page":"ج6 ص32","text":"قال حدثنا ابن جامع قال تذاكروا يوما كبر الأيور بحضرة بعض أمراء المدينة فأطالوا القول ثم قال بعضهم إنما يكون كبر أير الرجل على قدر حر أمه فالتفت الأمير إلى دحمان فقال يا دحمان كيف أيرك فقال له أيها الأمير أنت لم ترد أن تعرف كبر أيري وإنما أردت أن تعرف مقدار حر أمي وكان دحمان طيبا ظريفا أخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة قال حدثني إسحاق قال أول ما عرف من ظرف دحمان أن رجلا مر به يوما فقال له أير حماري في حر أمك يا دحيم فلم يفهم ما قاله وفهمه رجل كان حاضرا معه فضحك فقال مم ضحكت فلم يخبره فقال له أقسمت عليك إلا أخبرتني قال إنه شتمك فلا أحب استقبالك بما قاله لك فقال والله لتخبرني كائنا ما كان فقال له قال كذا وكذا من حماري في حر أمك فضحك ثم قال أعجب والله وأغلظ علي من شتمه كنايتك عن أير حماره وتصريحك بحر أمي لا تكني","topic":"أخبار دحمان ونسبه","topicNo":55,"sp":2,"spl":"الوليد يكرم دحمان — نسبة هذا الصوت"},
{"id":"b55-6","bab":"الجزء 6","sec":"جعفر بن سليمان والمغنون","page":"ج6 ص35","text":"أخبرني محمد بن خلف وكيع قال حدثني أبو خالد يزيد بن محمد المهلبي قال حدثني إسحاق الموصلي قال حدثنا عبد الله بن الربيع المديني قال حدثني الربعي المغني قال قال لنا جعفر بن سليمان وهو أمير المدينة اغدوا على قصري بالعقيق غدا وكنت أنا ودحمان وعطرد فغدوت للموعد فبدأت بمنزل دحمان وهو في جهينة\nفإذا هو وعطرد قد اجتمعا على قدر يطبخانها وإذا السماء تبغش فأذكرتهما الموعد فقالا أما ترى يومنا هذا ما أطيبه اجلس حتى نأكل من هذه القدر ونصيب شيئا ونستمتع من هذا اليوم فقال ما كنت لأفعل مع ما تقدم الأمير به إلي فقالا لي كأنا بالأمير قد انحل عزمه وأخذك المطر إلى أن تبلغ ثم ترجع إلينا مبتلا فتقرع الباب وتعود إلى ما سألناك حينئذ قال فلم ألتفت إلى قولهما ومضيت وإذا جعفر مشرف من قصره والمضارب تضرب والقدور تنصب فلما كنت بحيث يسمع تغنيت\n(واستصحب الأصحاب حتى إذا ونوا ... وملوا من الإدلاج جئتكم وحدي)\nال وما ذاك فأخبرته فقال يا غلام هات مائتي دينار أو أربعمائة دينار الشك من إسحاق الموصلي فانثرها في حجر الربعي اذهب الآن فلا تحل لها عقدة حتى تريهما إياها فقلت وما في يدي من ذلك يأتيانك غدا فتلحقهما بي قال ما كنت لأفعل قلت فلا أمضي حتى تحلف لي أنك لا تفعل فحلف فمضيت إليهما فقرعت الباب فصاحا وقالا ألم نقل لك إن هذه تكون حالك فقلت كلا فأريتهما الدنانير فقالا إن الأمير لحي كريم ونأتيه غدا فنعتذر إليه فيدعوه كرمه إلى أن يلحقنا بك فقلت كذبتكما أنفسكما والله إني قد أحكمت الأمر ووكدت عليه الإيمان ألا يفعل فقالا لا وصلتك رحم أخبرني الحسين بن يحيى عن حماد عن أبيه عن منصور بن أبي مزاحم قال أخبرني عبد العزيز بن الماجشون قال صلينا يوما الصبح بالمدينة فقال قوم قد سال العقيق فخرجنا من المسجد مبادرين إلى العقيق فانتهينا إلى العرصة فإذا من وراء الوادي قبالتنا\nدحمان المغني وابن جندب مع طلوع الشمس قد تماسكا بينهما صوتا وهو\n(اسكن البدو ما سكنت ببدو ... فإذا ما حضرت طال الحضور)\nوإذا أطيب صوت في الدنيا قال وكان أخي يكره السماع فلما سمعه طرب طربا شديدا وتحرك وكان لغناء دحمان أشد استحسانا وحركة وارتياحا فقال لي يا أخي تسمع إلى غناء دحمان والله لكأنه يسكب على الماء زيتا","topic":"أخبار دحمان ونسبه","topicNo":55,"sp":2,"spl":"الوليد يكرم دحمان — نسبة هذا الصوت"},
{"id":"b55-7","bab":"الجزء 6","sec":"نسبة هذا الصوت","page":"ج6 ص37","text":"صوت أوحش الجنبذان فالدير منها ... فقراها فالمنزل المحظور أسكن البدو ما أقمت ببدو ... فإذا ما حضرت طاب الحضور أي عيش ألذه لست فيه ... أو ترى نعمة به وسرور\nالشعر لحسان بن ثابت والغناء لإبن مسجح رمل مطلق في مجرى البنصر عن إسحاق","topic":"أخبار دحمان ونسبه","topicNo":55,"sp":2,"spl":"الوليد يكرم دحمان — نسبة هذا الصوت"},
{"id":"b55-8","bab":"الجزء 6","sec":"دحمان والفضل بن يحيى","page":"ج6 ص38","text":"أخبرنا محمد بن خلف بن المرزبان قال حدثني أحمد بن عبد الرحمن عن أبي عثمان البصري قال قال دحمان دخلت على الفضل بن يحيى ذات يوم فلما جلسنا قام وأومأ إلي فقمت فأخذ بيدي ومضى بي إلى منظرة له على الطريق ودعا بالطعام فأكلنا ثم صرنا إلى الشراب فبينا نحن كذلك إذ مرت بنا جارية سوداء حجازية تغني\n(اهجريني أو صليني ... كيفما شئت فكوني)\n(أنت والله تحبيني ... وإن لم تخبريني)\nطرب وقال أحسنت ادخلي فدخلت فأمر بطعام فقدم إليها فأكلت وسقاها أقداحا وسألها عن مواليها فأخبرته فبعث فاشتراها فوجدها من أحسن الناس غناء وأطيبهم صوتا وأملحهم طبعا فغلبتني عليه مدة وتناساني فكتبت إليه\n(أخرجت السوداء ما كان في ... قلبك لي من شدة الحب)\n(فإن يدم ذا منك لا دام لي ... مت من الإعراض والكرب)\nال فلما قرأ الرقعة ضحك وبعث فدعاني ووصلني وعاد إلى ما كان عليه من الأنس قال مؤلف هذا الكتاب هكذا أخبرنا ابن المرزبان بهذا الخبر وأظنه غلطا لأن دحمان لم يدرك خلافة الرشيد وإنما أدركها ابناه زبير وعبد الله\nفإما أن يكون الخبر لأحدهما أو يكون لدحمان مع غير الفضل بن يحيى","topic":"أخبار دحمان ونسبه","topicNo":55,"sp":3,"spl":"دحمان والفضل بن يحيى — من المائة المختارة"},
{"id":"b55-9","bab":"الجزء 6","sec":"ومما في المائة المختارة من صنعة دحمان","page":"ج6 ص38","text":"صوت","topic":"أخبار دحمان ونسبه","topicNo":55,"sp":3,"spl":"دحمان والفضل بن يحيى — من المائة المختارة"},
{"id":"b55-10","bab":"الجزء 6","sec":"من المائة المختارة من رواية علي بن يحيى","page":"ج6 ص38","text":"(وإني لآتي البيت ما إن أحبه ... وأكثر هجر البيت وهو حبيب)\n(وأغضي على أشياء منكم تسوءني ... وأدعى إلى ما سركم فأجيب)\n(وأحبس عنك النفس والنفس صبة ... بقربك والممشى إليك قريب)\nلشعر للأحوص والغناء لدحمان ثقيل أول وقد تقدمت أخبار الأحوص ودحمان فيما مضى من الكتاب صوت","topic":"أخبار دحمان ونسبه","topicNo":55,"sp":3,"spl":"دحمان والفضل بن يحيى — من المائة المختارة"},
{"id":"b55-11","bab":"الجزء 6","sec":"من المائة المختارة","page":"ج6 ص39","text":"(حييا خولة مني بالسلام ... درة البحر ومصباح الظلام)\n(لا يكن وعدك برقا خلبا ... كاذبا يلمع في عرض الغمام)\n(واذكري الوعد الذي واعدتنا ... ليلة النصف من الشهر الحرام)\nلشعر لأعشى همدان والغناء لأحمد النصبي ولحنه المختار من القدر الأوسط من الثقيل الأول بإطلاق الوتر في مجرى البنصر وعروضه من الرمل والخلب من البرق الذي لا غيث معه ولا ينتفع بسحابه وتضرب المثل به العرب لمن أخلف وعده قال الشاعر\n(لا يكن وعدك برقا خلبا ... إن خير البرق ما الغيث معه)\nوعرض السحابة الناحية منها","topic":"أخبار دحمان ونسبه","topicNo":55,"sp":3,"spl":"دحمان والفضل بن يحيى — من المائة المختارة"},
{"id":"b56-1","bab":"الجزء 6","sec":"أخبار أعشى همدان ونسبه","page":"ج6 ص41","text":"اسمه عبد الرحمن بن عبد الله بن الحارث بن نظام بن جشم بن عمرو بن الحارث بن مالك بن عبد الحر بن جشم بن حاشد بن جشم بن خيران بن نوف بن همدان بن مالك بن زيد بن نزار بن أوسلة بن ربيعة بن الخيار بن مالك بن زيد بن كهلان بن سبأ بن يشجب بن يعرب بن قحطان ويكنى أبا المصبح شاعر فصيح كوفي من شعراء الدولة الأموية وكان زوج أخت الشعبي الفقيه والشعبي زوج أخته وكان أحد الفقهاء القراء ثم ترك ذلك وقال الشعر وآخى أحمد النصبي بالعشيرية والبلدية فكان إذا قال شعرا غنى فيه أحمد وخرج مع ابن الأشعث فأتي الحجاج أسيرا في الأسرى فقتله صبرا\nأخبرني بما أذكره من جملة أخباره الحسن بن علي الخفاف قال حدثنا الحسن بن عليل العنزي عن محمد بن معاوية الأسدي أنه أخذ أخباره هذه عن ابن كناسة عن الهيثم بن عدي عن حماد الراوية وعن غيرهم من رواة الكوفيين قال حدثنا عمر بن شبة وأبو هفان جميعا عن إسحاق الموصلي عن الهيثم بن عدي عن عبد الله بن عياش الهمداني قال الغنزي وأخذت بعضها من رواية مسعود بن بشر عن الأصمعي وما كان من غير رواية هؤلاء ذكرته مفردا أخبرني المهلبي أبو أحمد حبيب بن نصر وعلي بن صالح قالا حدثنا عمر بن شبة وأبو هفان جميعا عن إسحاق الموصلي عن الهيثم بن عدي عن عبد الله بن عياش الهمداني قال كان الشعبي عامر بن شراحيل زوج أخت أعشى همدان وكان أعشى همدان زوج أخت الشعبي فأتاه أعشى همدان يوما وكان أحد القراء للقرآن فقال له إني رأيت كأني أدخلت بيتا فيه حنطة وشعير وقيل لي خذ أيهما شئت\nفأخذت الشعير فقال إن صدقت رؤياك تركت القرآن وقراءته وقلت الشعر فكان كما قال","topic":"أخبار أعشى همدان ونسبه","topicNo":56,"sp":0,"spl":"أخبار أعشى همدان ونسبه"},
{"id":"b56-2","bab":"الجزء 6","sec":"ابنة الأمير تهرب معه","page":"ج6 ص43","text":"أخبرني الحسن بن علي قال حدثنا الحسن بن عليل العنزي عن محمد بن معاوية الأسدي عن ابن كناسة قال العنزي وحدثني مسعود بن بشر عن أبي عبيدة والأصمعي قالا وافق روايتهم الهيثم بن عدي عن حماد الراوية قال كان أعشى همدان أبو المصبح ممن أغزاه الحجاج بلد الديلم ونواحي دستبى فأسر فلم يزل أسيرا في أيدي الديلم مدة ثم إن بنتا للعلج الذي أسره هويته وصارت إليه ليلا فمكنته من نفسها فأصبح وقد واقعها ثماني مرات فقالت له الديلمية يا معشر المسلمين أهكذا تفعلون بنسائكم فقال لها هكذا نفعل كلنا فقالت له بهذا العمل نصرتم أفرأيت إن خلصتك أتصطفيني لنفسك فقال لها نعم وعاهدها فلما كان الليل حلت قيوده وأخذت به طرقا تعرفها حتى خلصته وهربت معه فقال شاعر من أسرى المسلمين\n(فمن كان يفديه من الأسر ماله ... فهمدان تفديها الغداة أيورها)\nقال الأعشى يذكر ما لحقه من أسر الديلم\nصوت\n(لمن الظعائن سيرهن ترجف ... عوم السفين إذا تقاعس مجذف)\n(مرت بذي خشب كأن حمولها ... نخل بيثرب طلعه متضعف)\nنى في هذين البيتين أحمد النصبي ولحنه خفيف ثقيل مطلق في مجرى البنصر عن عمرو وابن المكي وفيهما لمحمد الزف خفيف رمل بالوسطى عن عمرو\n(عولين ديباجا وفاخر سندس ... وبخز أكسية العراق تحفف)\n(وغدت بهم يوم الفراق عرامس ... فتل المرافق بالهوادج دلف)\n(بان الخليط وفاتني برحيله ... خود إذا ذكرت لقلبك يشغف)\n(تجلو بمسواك الأراك منظما ... عذبا إذا ضحكت تهلل ينظف)\n(وكأن ريقتها على علل الكرى ... عسل مصفى في القلال وقرقف)\n(وكأنما نظرت بعيني ظبية ... تحنو على خشف لها وتعطف)\n(وإذا تنوء إلى القيام تدافعت ... مثل النزيف ينوء ثمت يضعف)\n(ثقلت روادفها ومال بخصرها ... كفل كما مال النقا المتقصف)\n(ولها ذراعا بكر رحبية ... ولها بنان بالخضاب مطرف)\n(وعوارض مصقولة وترائب ... بيض وبطن كالسبيكة مخطف)\n(ولها بهاء في النساء وبهجة ... وبها تحل الشمس حين تشرف)\n(تلك التي كانت هواي وحاجتي ... لو أن دارا بالأحبة تسعف)\n(وإذا تصبك من الحوادث نكبة ... فاصبر فكل مصيبة ستكشف)\n(ولئن بكيت من الفراق صبابة ... إن الكبير إذا بكى ليعنف)\n(عجبا من الأيام كيف تصرفت ... والدار تدنو مرة وتقذف)\n(أصحبت رهنا للعداة مكبلا ... أمسي وأصبح في الأداهم أرسف)\n(بين القليسم فالقيول فحامن ... فاللهزمين ومضجعي متكنف)\nذه أسماء مواضع من بلد الديلم تكنفته الهموم بها\n(فحبال ويمة ما تزال منيفة ... يا ليت أن جبال ويمة تنسف)\nيمة وشلبة ناحيتان من نواحي الري\n(ولقد أراني قبل ذلك ناعما ... جدلان آبى أن أضام وآنف)\n(واستنكرت ساقي الوثاق وساعدي ... وأنا أمرؤ بادي الأشاجع أعجف)\n(ولقد تضرسني الحروب وإنني ... الفي بكل مخافة أتعسف)\n(أتسربل الليل البهيم وأستري ... في الخبت إذ لا يسترون وأوجف)\n(ما إن أزال مقنعا أو حاسرا ... سلف الكتيبة والكتيبة وقف)\n(فأصابني قوم فكنت أصيبهم ... فالآن أصبر للزمان وأعرف)\n(إني لطلاب الترات مطلب ... وبكل أسباب المنية أشرف)\n(باق على الحدثان غير مكذب ... لا كاسف بالي ولا متأسف)\n(إن نلت لم أفرح بشيء نلته ... وإذا سبقت به فلا أتلهف)\n(إني لأحمي في المضيق فوارسي ... وأكر خلف المستضاف وأعطف)\n(وأشد إذ يكبو الجبان وأصطلي ... حر الأسنة والأسنة ترعف)\nوت\n(فلئن أصابتني الحرب فربما ... أدعى إذا منع الرداف فأردف)\n(ولربما يروى بكفي لهذم ... ماض ومطرد الكعوب مثقف)\n(وأغير غارات وأشهد مشهدا ... قلب الجبان به يطير ويرجف)\n(وأرى مغانم لو أشاء حويتها ... فيصدني عنها غنى وتعفف)\nنى في هذه الأبيات دحمان ولحنه ثقيل أول بالبنصر عن الهشامي قال الهشامس فيها لمالك خفيف ثقيل أول بالوسطى ووافقه في هذا ابن المكي قالوا جميعا","topic":"أخبار أعشى همدان ونسبه","topicNo":56,"sp":1,"spl":"ابنة الأمير تهرب معه"},
{"id":"b56-3","bab":"الجزء 6","sec":"خروجه مع جيش الحجاج إلى مكران","page":"ج6 ص47","text":"ثم ضرب البعث على جيش أهل الكوفة إلى مكران فأخرجه الحجاج معهم فخرج إليها وطال مقامه بها ومرض فاجتواها وقال في ذلك وأنشدني بعض هذه القصيدة اليزيدي عن سليمان بن أبي شيخ\n(طلبت الصبا إذ علا المكبر ... وشاب القذال وما تقصر)\n(وبان الشباب ولذاته ... ومثلك في الجهل لا يعذر)\n(وقال العواذل هل ينتهي ... فيقدعه الشيب أو يقصر)\n(وفي أربعين توفيتها ... وعشر مضت لي مستبصر)\n(وموعظة لامرئ حازم ... إذا كان يسمع أو يبصر)\n(فلا تأسفن على ما مضى ... ولا يحزننك ما يدبر)\n(فإن الحوادث تبلي الفتى ... وإن الزمان به يعثر)\n(فيوما يساء بما نابه ... ويوما يسر فيستبشر)\n(ومن كل ذلك يلقى الفتى ... ويمنى له منه ما يقدر)\n(كأني لم أرتحل جسرة ... ولم أجفها بعدما تضمر)\n(فأجشمها كل ديمومة ... ويعرفها البلد المقفر)\n(ولم أشهد البأس يوم الوغى ... علي المفاضة والمغفر)\n(ولم أخرق الصف حتى تميل ... دارعة القوم والحسر)\n(وتحتي جرداء خيفانة ... من الخيل أو سابح مجفر)\n(أطاعن بالرمح حتى اللبان ... يجري به العلق الأحمر)\n(وما كنت في الحرب إذ شمرت ... كمن لا يذيب ولا يخثر)\n(ولكنني كنت ذا مرة ... عطوفا إذا هتف المحجر)\n(أجيب الصريخ إذا ما دعا ... وعند الهياج أنا المسعر)\n(فإن أمس قد لاح في المشيب ... أم البنين فقد أذكر)\n(رخاء من العيش كنا به ... إذ الدهر خال لنا مصحر)\n(وإذ أنا في عنفوان الشباب ... يعجبني اللهو والسمر)\n(أصيد الحسان ويصطدنني ... وتعجبني الكاعب المعصر)\n(وبيضاء مثل مهاة الكثيب ... لا عيب فيها لمن ينظر)\n(كأن مقلدها إذ بدا ... به الدر والشذر والجوهر)\n(مقلد أدماء نجدية ... يعن لها شادن أحور)\n(كأن جنى النحل والزنجبيل ... والفارسية إذ تعصر)\n(يصب على برد أنيابها ... مخالطه المسك والعنبر)\n(إذا انصرفت وتلوت بها ... رقاق المجاسد والمئزر)\n(وغص السوار وجال الوشاح ... على عكن خصرها مضمر)\n(وضاق عن الساق خلخالها ... فكاد مخدمها يندر)\n(فتور القيام رخيم الكلام ... يفزعها الصوت إذ تزجر)\n(وتنمى إلى حسب شامخ ... فليست تكذب إذ تفخر)\n(فتلك التي شفني حبها ... وحملني فوق ما أقدر)\n(فلا تعذلاني في حبها ... فإني بمعذرة أجدر)\nمن ها هنا رواية اليزيدي\n(وقولا لذي طرب عاشق ... أشط المزار بمن تذكر)\n(بكوفية أصلها بالفرات ... تبدو هنالك أو تحضر)\n(وأنت تسير إلى مكران ... فقد شحط الورد والمصدر)\n(ولم تك من حاجتي مكران ... ولا الغزو فيها ولا المتجر)\n(وخبرت عنها ولم آتها ... فما زلت من ذكرها أذعر)\n(بأن الكثير بها جائع ... وأن القليل بها مقتر)\n(وأن لحي الناس من حرها ... تطول فتجلم أو تضفر)\n(ويزعم من جاءها قبلنا ... بأنا سنسهم أو ننحر)\n(أعوذ بربي من المخزيات ... فيما أسر وما أجهر)\n(وحدثت أن ما لنا رجعة ... سنين ومن بعدها أشهر)\n(إلى ذاك ما شاب أبناؤنا ... وباد الإخلاء والمعشر)\n(وما كان بي من نشاط لها ... وإني لذو عدة موسر)\n(ولكن بعثت لها كارها ... وقيل انطلق كالذي يؤمر)\n(فكان النجاء ولم ألتفت ... إليهم وشرهم منكر)\n(هو السيف جرد من غمده ... فليس عن السيف مستأخر)\n(وكم من أخ لي مستأنس ... يظل به الدمع يستحسر)\n(يودعني وانتحت عبرة ... له كالجداول أو أغزر)\n(فلست بلاقيه من بعدها ... يد الدهر ما هبت الصرصر)\n(وقد قيل إنكم عابرون ... نجرا لها لم يكن يعبر)\n(إلى السند والهند في أرضهم ... هم الجن لكنهم أنكر)\n(وما رام غزوا لها قبلنا ... أكابر عاد ولا حمير)\n(ولا رام سابور غزوا لها ... ولا الشيخ كسرى ولا قيصر)\n(ومن دونها معبر واسع ... وأجر عظيم لمن يؤجر)","topic":"أخبار أعشى همدان ونسبه","topicNo":56,"sp":2,"spl":"خروجه مع جيش الحجاج إلى مكران"},
{"id":"b56-4","bab":"الجزء 6","sec":"قصته مع جارية خالد الرياحي","page":"ج6 ص50","text":"وذكر محمد بن صالح بن النطاح أن هشام بن محمد الكلبي حدث عن أبيه أن أعشى همدان كان مع خالد بن عتاب بن ورقاء الرياحي بالري\nودستبي وكان الأعشى شاعر أهل اليمن بالكوفة وفارسهم فلما قدم خالد من مغزاه خرج جواريه يتلقينه وفيهن أم ولد له كانت رفيعة القدر عنده فجعل الناس يمرون عليها إلى أن جاز بها الأعشى وهو على فرسه يميل يمينا ويسارا من النعاس فقالت أم خالد بن عتاب لجواريها إن امرأة خالد لتفاخرني بأبيها وعمها وأخيها وهل يزيدون على أن يكونوا مثل هذا الشيخ المرتعش وسمعها الأعشى فقال من هذه فقال له بعض الناس هذه جارية خالد فضحك وقال لها إليك عني يا لكعاء ثم أنشأ يقول\n(وما يدريك ما فرس جرور ... وما يدريك ما حمل السلاح)\n(وما يدريك ما شيخ كبير ... عداه الدهر عن سنن المراح)\n(فأقسم لو ركبت الورد يوما ... وليلته إلى وضح الصباح)\n(إذا لنظرت منك إلى مكان ... كسحق البرد أو أثر الجراح)\nال فأصبحت الجارية فدخلت إلى خالد فشكت إليه الأعشى فقالت والله ما تكرم ولقد اجترئ عليك فقال لها وما ذاك فأخبرته أنها مرت برجل في وجه الصبح ووصفته له وأنه سبها فقال ذلك أعشى همدان فأي شيء قال لك فأنشدته الأبيات فبعث إلى الأعشى فلما دخل عليه قال له ما تقول هذه زعمت أنك هجوتها فقال أساءت سمعا إنما قلت\n(مررت بنسوة متعطرات ... كضوء الصبح أو بيض الأداحي)\n(على شقر البغال فصدن قلبي ... بحسن الدل والحدق الملاح)\n(فقلت من الظباء فقلن سرب ... بدا لك من ظباء بني رياح)\nفقالت لا والله ما هكذا قال وأعادت الأبيات فقال له خالد أما إنها لولا أنها قد ولدت مني لوهتبها لك ولكني أفتدي جنايتها بمثل ثمنها فدفعه إليه وقال له أقسمت عليك يا أبا المصبح ألا تعيد في هذا المعنى شيئا بعد ما فرط منك وذكر هذا الخبر العنزي في روايته التي قدمت ذكرها ولم يأت به على هذا الشرح وقال هو وابن النطاح جميعا وكان خالد يقول للأعشى في بعض ما يمنيه إياه ويعده به إن وليت عملا كان لك ما دون الناس جميعا فمتى استعملت فخذ خاتمي واقض في أمور الناس كيف شئت قال فاستعمل خالد على أصبهان وصار معه الأعشى فلما وصل إلى عمله جفاه وتناساه ففارقه الأعشى ورجع إلى الكوفة وقال فيه\n(تمنيني إمارتها تميم ... وما أمي بأم بني تميم)\n(وكان أبو سليمان أخا لي ... ولكن الشراك من الأديم)\n(أتينا أصبهان فهزلتنا ... وكنا قبل ذلك في نعيم)\n(أتذكرنا ومرة إذ غزونا ... وأنت على بغيلك ذي الوشوم)\n(ويركب رأسه في كل وحل ... ويعثر في الطريق المستقيم)\n(وليس عليك إلا طيلسان ... نصيبى وإلا سحق نيم)\n(فقد أصبحت في خز وقز ... تبختر ما ترى لك من حميم)\n(وتحسب أن تلقاها زمانا ... كذبت ورب مكة والحطيم)\nذه رواية ابن النطاح وزاد العنزي في روايته\n(وكانت أصبهان كخير أرض ... لمغترب وصعلوك عديم)\n(ولكنا أتيناها وفيها ... ذوو الأضغان والحقد القديم)\n(فأنكرت الوجوه وأنكرتني ... وجوه ما تخبر عن كريم)\n(وكان سفاهة مني وجهلا ... مسيري لا أسير إلى حميم)\n(فلو كان ابن عتاب كريما ... سما لرواية الأمر الجسيم)\n(وكيف رجاء من غلبت عليه ... تنائي الدار كالرحم العقيم)\nال ابن النطاح فبعث إليه خالد من مرة هذا الذي أدعيت أني وأنت غزونا معه على بغل ذي وشوم ومتى كان ذلك ومتى رأيت علي الطيلسان والنيم اللذين وصفتهما فأرسل إليه هذا كلام أردت وصفك بظاهره فأما تفسيره فإن مرة مرارة ثمرة ما غرست عندي من القبيح والبغل المركب الذي ارتكبته مني لا يزال يعثر بك في كل وعث وجدد ووعر وسهل وأما الطيلسان فما ألبسك إياه من العار والذم وإن شئت راجعت الجميل فراجعته لك فقال لا بل أراجع الجميل وتراجعه فوصله بمال عظيم وترضاه وهكذا روى من قدمت ذكره أخبرني هاشم بن محمد الخزاعي قال حدثنا الرياشي قال حدثنا الأصمعي قال لما ولي خالد بن عتاب بن ورقاء أصبهان خرج إليه أعشى همدان وكان صديقه وجاره بالكوفة فلم يجد عنده ما يحب وأعطى خالد الناس عطايا فجعله في أقلها وفضل عليه آل عطارد فبلغه عنه أنه ذمه فحبسه مدة ثم أطلقه فقال يهجوه\n(وما كنت ممن ألجأته خصاصة ... إليك ولا ممن تغر المواعد)\n(ولكنها الأطماع وهي مذلة ... دنت بي وأنت النازح المتباعد)\n(أتحبسني في غير شيء وتارة ... تلاحظني شزرا وأنفك عاقد)","topic":"أخبار أعشى همدان ونسبه","topicNo":56,"sp":3,"spl":"قصته مع جارية خالد الرياحي"},
{"id":"b56-5","bab":"الجزء 6","sec":"قصته مع جارية خالد الرياحي","page":"ج6 ص50","text":"(فإنك لا كابني فزارة فاعلمن ... خلقت ولم يشبههما لك والد)\n(ولا مدرك ما قد خلا من نداهما ... أبوك ولا حوضيهما أنت وارد)\n(وإنك لو ساميت آل عطارد ... لبذتك أعناق لهم وسواعد)\n(ومأثرة عادية لن تنالها ... وبيت رفيع لم تخنه القواعد)\n(وهل أنت إلا ثعلب في ديارهم ... تشل فتعسا أو يقودك قائد)\n(أرى خالدا يختال مشيا كأنه ... من الكبرياء نهشل أو عطارد)\n(وما كان يربوع شبيها لدارم ... وما عدلت شمس النهار الفراقد)\nالوا ولما خرج ابن الأشعث على الحجاج بن يوسف حشد معه أهل الكوفة فلم يبق من وجوههم وقرائهم أحد له بناهة إلا خرج معه لثقل وطأة الحجاج عليهم فكان عامر الشعبي وأعشى همدان ممن خرج معه وخرج أحد النصبي أبو أسامة الهمداني المغني مع الأعشى لألفته إياه وجعل الأعشى يقول الشعر في ابن الأشعث يمدحه ولا يزال يحرض أهل الكوفة بأشعاره على القتال وكان مما قاله في ابن الأشعث يمدحه\n(يأبى الإله وعزة ابن محمد ... وجدود ملك قبل آل ثمود)\n(أن تأنسوا بمذممين عروقهم ... في الناس إن نسبوا عروق عبيد)\n(كم من أب لك كان يعقد تاجه ... بجبين أبلج مقول صنديد)\n(وإذا سألت المجد أين محله ... فالمجد بين محمد وسعيد)\n(بين الأشج وبين قيس باذخ ... بخ بخ لوالده وللمولود)\n(ما قصرت بك أن تنال مدى العلا ... أخلاق مكرمة وإرث جدود)\n(قرم إذا سامى القروم ترى له ... أعراق مجد طارف وتليد)\n(وإذا دعا لعظيمة حشدت له ... همدان تحت لوائه المعقود)\n(يمشون في حلق الحديد كأنهم ... أسد الإباء سمعن زأر أسود)\n(وإذا دعوت بآل كندة أجفلوا ... بكهول صدق سيد ومسود)\n(وشباب مأسدة كأن سيوفهم ... في كل ملحمة بروق رعود)\n(ما إن ترى قيسا يقارب قيسكم ... في المكرمات ولا ترى كسعيد)","topic":"أخبار أعشى همدان ونسبه","topicNo":56,"sp":4,"spl":"قصته مع جارية خالد الرياحي"},
{"id":"b56-6","bab":"الجزء 6","sec":"شعره عندما رده ابن الأشعث","page":"ج6 ص55","text":"وقال حماد الراوية في خبره كانت لأعشى همدان مع ابن الأشعث مواقف محمودة وبلاء حسن وآثار مشهورة وكان الأعشى من أخواله لأن أم عبد الرحمن بن محمد بن الأشعث أم عمرو بنت سعيد بن قيس الهمداني قال فلما صار ابن الأشعث إلى سجستان جبى مالا كثيرا فسأله أعشى همدان أن يعطيه منه زيادة على عطائه فمنعه فقال الأعشى في ذلك\n(هل تعرف الدار عفا رسمها ... بالحضر فالروضة من آمد)\n(دار لخود طفلة رودة ... بانت فأمسى حبها عامدي)\n(بيضاء مثل الشمس رقراقة ... تبسم عن ذي أشر بارد)\n(لم يخط قلبي سهمها إذ رمت ... يا عجبا من سهمها القاصد)\n(يأيها القرم الهجان الذي ... يبطش بطش الأسد اللابد)\n(والفاعل الفعل الشريف الذي ... ينمى إلى الغائب والشاهد)\n(كم قد أسدي لك من مدحة ... تروى مع الصادر والوارد)\n(وكم أجبنا لك من دعوة ... فاعرف فما العارف كالجاحد)\n(نحن حميناك وما تحتمي ... في الروع من مثنى ولا واحد)\n(يوم انتصرنا لك من عابد ... ويوم أنجيناك من خالد)\n(ووقعة الري التي نلتها ... بجحفل من جمعنا عاقد)\n(وكم لقينا لك من واتر ... بصرف نابي حنق حارد)\n(ثم وطئناه بأقدامنا ... وكان مثل الحية الراصد)\n(إلى بلاء حسن قد مضى ... وأنت في ذلك كالزاهد)\n(فاذكر أيادينا وآلاءنا ... بعودة من حلمك الراشد)\n(ويوم الأهواز فلا تنسه ... ليس النثا والقول بالبائد)\n(إنا لنرجوك كمال نرتجي ... صوب الغمام المبرق الراعد)\n(فانفخ بكفيك وما ضمتا ... وافعل فعال السيد الماجد)\n(ما لك لا تعطي وأنت امرؤ ... مثر من الطارف والتالد)\n(تجبي سجستان وما حولها ... متكئا في عيشك الراغد)\n(لا ترهب الدهر وأيامه ... وتجرد الأرض مع الجارد)\n(إن يك مكروه تهجنا له ... وأنت في المعروف كالراقد)\n(ثم ترى أنا سنرضى بذا ... كلا ورب الراكع الساجد)\n(وحرمة البيت وأستاره ... ومن به من ناسك عابد)\n(تلك لكم أمنية باطل ... وغفوة من حلم الراقد)\n(ما أنا إن هاجك من بعدها ... هيج بآتيك ولا كابد)\n(ولا إذا ناطوك في حلقة ... بحامل عنك ولا فاقد)\n(فأعط ما أعطيته طيبا ... لا خير في المنكود والناكد)\n(نحن ولدناك فلا تجفنا ... والله قد وصاك بالوالد)\n(إن تك من كندة في بيتها ... فإن أخوالك من حاشد)\n(شم العرانين وأهل الندى ... ومنتهى الضيفان والرائد)\n(كم فيهم من فارس معلم ... وسائس للجيش أو قائد)\n(وراكب للهول يجتابه ... مثل شهاب القبس الواقد)\n(أو ملأ يشفى بأحلامهم ... من سفه الجاهل والمارد)\n(لم يجعل الله بأحسابنا ... نقصا وما الناقص كالزائد)\n(ورب خال لك في قومه ... فرع طويل الباع والساعد)\n(يحتضر البأس وما يبتغي ... سوى إسار البطل الناجد)\n(والطعن بالراية مستمكنا ... في الصف ذي العادية الناهد)\n(فارتح لأخوالك واذكرهم ... وأرحمهم للسلف العائد)\n(فإن أخوالك لم يبرحوا ... يربون بالرفد على الرافد)\n(لم يبخلوا يوما ولم يجبنوا ... في السلف الغازي ولا القاعد)\n(ورب خال لك في قومه ... حمال أثقال لها واجد)\n(معترف للرزء في ماله ... والحق للسائل والعامد)","topic":"أخبار أعشى همدان ونسبه","topicNo":56,"sp":5,"spl":"شعره عندما رده ابن الأشعث — مدحه النعمان بن بشير"},
{"id":"b56-7","bab":"الجزء 6","sec":"مدحه النعمان بن بشير","page":"ج6 ص58","text":"أخبرني محمد بن الحسن بن دريد الأزدي قال حدثني عمي عن العباس بن هشام عن أبيه وأخبرني الحسين بن يحيى عن حماد عن أبيه عن ابن الكلبي وأخبرني عمي عن الكراني عن العمري عن الهيثم بن عدي وذكره العنزي عن أصحابه قالوا جميعا خرج أعشى همدان إلى الشأم في ولاية مروان بن الحكم فلم ينل فيها حظا فجاء إلى النعمان بن بشير وهو عامل على حمص فشكا إليه حاله فكلم\nله النعمان بن بشير اليمانية وقال لهم هذا شاعر اليمن ولسانها واستماحهم له فقالوا نعم يعطيه كل رجل منا دينارين من عطائه فقال لا بل أعطوه دينارا دينارا واجعلوا ذلك معجلا فقالوا أعطه إياه من بيت المال واحتسبها على كل رجل من عطائه ففعل النعمان وكانوا عشرين ألفا فأعطاه عشرين ألف دينار وأرتجعها منهم عند العطاء فقال الأعشى يمدح النعمان\n(ولم أر للحاجات عند التماسها ... كنعمان نعمان الندى ابن بشير)\n(إذا قال أوفى ما يقول ولم يكن ... كمدل إلى الأقوام حبل غرور)\n(متى أكفر النعمان لم ألف شاكرا ... وما خير من لا يقتدي بشكور)\n(فلولا أخو الأنصار كنت كنازل ... ثوى ما ثوى لم ينقلب بنقير)","topic":"أخبار أعشى همدان ونسبه","topicNo":56,"sp":5,"spl":"شعره عندما رده ابن الأشعث — مدحه النعمان بن بشير"},
{"id":"b56-8","bab":"الجزء 6","sec":"شعره في حرب نصيبين","page":"ج6 ص59","text":"وقال الهيثم بن عدي في خبره حاصر المهلب بن أبي صفرة نصيبين وفيها أبو قارب يزيد بن أبي صخر ومعه الخشبية فقال المهلب يأيها الناس لا يهولنكم هؤلاء القوم فإنما هم العبيد بأيديها العصي فحمل عليهم المهلب وأصحابه فلقوهم بالعصي فهزموهم حتى أزالوهم عن موقفهم فدس المهلب رجلا من عبد القيس إلى يزيد بن أبي صخر ليغتاله وجعل له ذلك جعلا سنيا قال الهيثم بلغني أنه أعطاه مائتي ألف درهم قبل أن يمضي ووعده بمثلها\nإذا عاد فاندس له العبدي فاغتاله فقتله وقتل بعده فقال أعشى همدان في ذلك\n(يسمون أصحاب العصي وما أرى ... مع القوم إلا المشرفية من عصا)\n(ألا أيها الليث الذي جاء حاذرا ... وألقى بنا جرمى الخيام وعرصا)\n(أتحسب غزو الشأم يوما وحربه ... كبيض ينظمن الجمان المفصصا)\n(وسيرك بالأهواز إذ أنت آمن ... وشربك ألبان الخلايا المقرصا)\n(فأقسمت لا تجبي لك الدهر درهما ... نصيبون حتى تبتلى وتمحصا)\n(ولا أنت من أثوابها الخضر لابس ... ولكن خشبانا شدادا ومشقصا)\n(فكم رد من ذي حاجة لا ينالها ... جديع العتيك رده الله أبرصا)\n(وشيد بنيانا وظاهر كسوة ... وطال جديع بعد ما كان أوقصا)\nتصغير جدع جديع بالدال غير معجمة والأبيات التي كانت فيها الغناء المذكور معه خبر الأعشى في هذا الكتاب يقولها في زوجة له من همدان يقال لها جزلة هكذا رواه الكوفيون وهو الصحيح وذكر الأصمعي أنها خولة هكذا رواه في شعر الأعشى فذكر العنزي في أخبار الأعشى المتقدم إسنادها أنها كانت عند الأعشى امرأة من قومه يقال لها أم الجلال فطالت مدتها معه وأبغضها ثم خطب إمرأة من قومه يقال لها جزلة وقال الأصمعي خولة فقالت له لا حتى تطلق أم الجلال فطلقها وقال في ذلك\n(تقادم ودك أم الجلال ... فطاشت نبالك عند النضال)\n(وطال لزومك لي حقبة ... فرثت قوى الحبل بعد الوصال)\n(وكان الفؤاد بها معجبا ... فقد أصبح اليوم عن ذاك سالي)\n(صحا لا مسيئا ولا ظالما ... ولكن سلا سلوة في جمال)\n(ورضت خلائقنا كلها ... ورضنا خلائقكم كل حال)\n(فأعييتنا في الذي بيننا ... تسومينني كل أمر عضال)\n(وقد تأمرين بقطع الصديق ... وكان الصديق لنا غير فالي)\n(وإتيان ما قد تجنبته ... وليدا ولمت عليه رجالي)\n(أفاليوم أركبه بعد ما ... علا الشيب مني صميم القذال)\n(لعمر أبيك لقد خلتني ... ضعيف القوى أو شديد المحال)\n(هلمي اسألي نائلا فانظري ... أأحرمك الخير عند السؤال)\n(ألم تعلمي أنني معرق ... نماني إلى المجد عمي وخالي)\n(وأني إذا ساءني منزل ... عزمت فأوشكت منه ارتحالي)\n(فبعض العتاب فلا تهلكي ... فلا لك في ذاك خير ولا لي)\n(فلما بدا لي منها البذاء ... صبحتها بثلاث عجال)\n(ثلاثا خرجن جميعا بها ... فخلينها ذات بيت ومال)\n(إلى أهلها غير مخلوعة ... وما مسها عندنا من نكال)\n(فأمست تحن حنين اللقاح ... من جزع إثر من لا يبالي)\n(فحني حنينك واستيقني ... بأنا أطرحناك ذات الشمال)\n(وأن لا رجوع فلا تكذبين ... ما حنت النيب إثر الفصال)\n(ولا تحسبيني بأني ندمت ... كلا وخالقنا ذي الجلال)\nقالت له أم الجلال بئس والله بعل الحرة وقرين الزوجة المسلمة أنت ويحك أعددت طول الصحبة والحرمة ذنبا تسبني وتهجوني بها ثم دعت عليه أن يبغضه الله إلى زوجته التي اختارها وفارقته فلما انتقلت إلى أهلها وصارت جزلة إليه ودخل بها لم يحظ عندها ففركته وتنكرت له واشتد شغفه بها ثم خرج مع ابن الأشعث فقال فيها\n(حييا جزلة مني بالسلام ... درة البحر ومصباح الظلام)\n(لا تصدى بعد ود ثابت ... واسمعي يا أم عيسى من كلامي)\n(إن تدومي لي فوصلي دائم ... أو تهمي لي بهجر أو صرام)\n(أو تكوني مثل برق خلب ... خادع يلمع في عرض الغمام)\n(أو كتخييل سراب معرض ... بفلاة أو طروق في المنام)\n(فاعلمي إن كنت لما تعلمي ... ومتى ما تفعلي ذاك تلامي)\n(بعد ما كان الذي كان فلا ... تتبعي الإحسان إلا بالتمام)\n(لا تناسي كل ما أعطيتني ... من عهود ومواثيق عظام)\n(واذكري الوعد الذي واعدتني ... ليلة النصف من الشهر الحرام)\n(فلئن بدلت أو خست بنا ... وتجرأت على أم صمام)\nم صمام الغدر والحنث\n(لا تبالين إذا من بعدها ... أبدا ترك صلاة أو صيام)\n(راجعي الوصل وردي نظرة ... لا تلجي في طماح وأثام)\n(وإذا أنكرت مني شيمة ... ولقد ينكر ما ليس بذام)","topic":"أخبار أعشى همدان ونسبه","topicNo":56,"sp":6,"spl":"شعره في حرب نصيبين"},
{"id":"b56-9","bab":"الجزء 6","sec":"شعره في حرب نصيبين","page":"ج6 ص59","text":"(فاذكريها لي أزل عنها ولا ... تسفحي عينيك بالدمع السجام)\n(وأرى حبلك رثا خلقا ... وحبالي جددا غير رمام)\n(عجبت جزلة مني أن رأت ... لمتي حفت بشيب كالثغام)\n(ورأت جسمي علاه كبرة ... وصروف الدهر قد أبلت عظامي)\n(وصليت الحرب حتى تركت ... جسدي نضوا كأشلاء اللجام)\n(وهي بيضاء على منكبها ... قطط جعد وميال سخام)\n(وإذا تضحك تبدي حببا ... كرضاب المسك في الراح المدام)\n(كملت ما بين قرن فإلى ... موضع الخلخال منها والخدام)\n(فاراها اليوم لي قد أحدثت ... خلقا ليس على العهد القدام)\nخبرني عمي قال حدثنا محمد بن سعيد الكراني قال حدثنا العمري عن الهيثم بن عدي عن مجالد عن الشعبي أنه أتى البصرة أيام ابن الزبير فجلس في المسجد إلى قوم من تميم فيهم الأحنف بن قيس فتذاكروا أهل الكوفة وأهل البصرة وفاخروا بينهم إلى أن قال\nقائل من أهل البصرة وهل أهل الكوفة إلا خولنا استنقذناهم من عبيدهم يعني الخوارج قال الشعبي فهجس في صدري أن تمثلت قول أعشى همدان\n(أفخرتم أن قتلتم أعبدا ... وهزمتم مرة آل عزل)\n(نحن سقناهم إليكم عنوة ... وجمعنا أمركم بعد فشل)\n(فإذا فاخرتمونا فاذكروا ... ما فعلنا بكم يوم الجمل)\n(بين شيخ خاضب عثنونه ... وفتى أبيض وضاح رفل)\n(جاءنا يرفل في سابغة ... فذبحناه ضحى ذبح الحمل)\n(وعفونا فنسيتم عفونا ... وكفرتم نعمة الله الأجل)\nال فضحك الأحنف ثم قال يأهل البصرة قد فخر عليكم الشعبي وصدق وانتصف فأحسنوا مجالسته","topic":"أخبار أعشى همدان ونسبه","topicNo":56,"sp":7,"spl":"شعره في حرب نصيبين"},
{"id":"b56-10","bab":"الجزء 6","sec":"شعره في هزيمة الزبير الخثعمي","page":"ج6 ص64","text":"أخبرني محمد بن عمران الصيرفي قال حدثنا العنزي قال حدثنا الرياشي عن أبي محلم عن الخليل بن عبد الحميد عن أبيه قال\nبعث بشر بن مروان الزبير بن خزيمة الخثعمي إلى الري فلقيه الخوارج بجلولاء فقتلوا جيشه وهزموه وأبادوا عسكره وكان معه أعشي همدان فقال في ذلك\n(أمرت خثعم على غير خير ... ثم أوصاهم الأمير بسير)\n(أين ما كنتم تعيفون للناس ... وما تزجرون من كل طير)\n(ضلت الطير عنكم بجلولاء ... وغرتكم أماني الزبير)\n(قدر ما أتيح لي من فلسطين ... على فالج ثقال وعير)\n(خثعمي مغصص جرجماني ... محل غزا مع ابن نمير)\nأخبرني محمد بن الحسن بن دريد قال حدثنا أبو حاتم قال سألت الأصمعي عن أعشى همدان فقال هو من الفحول وهو إسلامي كثير الشعر ثم قال لي العجب من ابن دأب حين يزعم أن أعشى همدان قال\n(من دعا لي غزيلي ... أربح الله تجارته)\nم قال سبحان الله أمثل هذا يجوز على الأعشى أن يجزم اسم الله عز و جل ويرفع تجارته وهو نصب ثم قال لي خلف الأحمر والله لقد طمع ابن دأب في الخلافة حين ظن أن هذا يقبل منه وأن له من المحل مثل أن يجوز مثل هذا قال ثم قال ومع ذلك أيضا إن قوله\n(من دعا لي غزيلي ... )\nا يجوز إنما هو من دعا لغزيلي ومن دعا لبعير ضال أخبرني عيسى بن الحسين الوراق ومحمد بن مزيد بن أبي الأزهر قالا حدثنا حماد بن إسحاق عن أبيه عن الهيثم بن عدي قال أملق أعشى همدان فأتى خالد بن عتاب بن ورقاء فأنشده\n(رأيت ثناء الناس بالقول طيبا ... عليك وقالوا ماجد وابن ماجد)\n(بني الحارث السامين للمجد إنكم ... بنيتم بناء ذكره غير بائد)\n(هنيئا لما أعطاكم الله واعلموا ... بأني سأطري خالدا في القصائد)\n(فإن يك عتاب مضى لسبيله ... فما مات من يبقى له مثل خالد)\nأمر له بخمسة آلاف درهم أخبرني هاشم بن محمد الخزاعي قال حدثنا أبو غسان قال قال عمر بن عبد العزيز يوما لسابق البربري ودخل عليه أنشدني يا سابق شيئا من شعرك تذكرني به فقال أو خيرا من شعري فقال هات قال قال أعشى همدان\n(وبينما المرء ناعما جذلا ... في أهله معجبا بالعيش ذا أنق)\n(غرا أتيح له من حينه عرض ... فما تلبث حتى مات كالصعق)\n(ثمت أضحى ضحى من غب ثالثة ... مقنعا غير ذي روح ولا رمق)\n(يبكى عليه وأدنوه لمظلمة ... تعلى جوانبها بالترب والفلق)\n(فما تزود مما كان يجمعه ... إلا حنوطا وما واراه من خرق)\n(وغير نفحة أعواد تشب له ... وقل ذلك من زاد لمطلق)\nال فبكى عمر حتى أخضل لحيته أخبرني الحرمي بن أبي العلاء قال حدثنا الحسين بن محمد بن أبي طالب الديناري قال حدثني إسحاق بن إبراهيم الموصلي عن الهيثم بن عدي عن حماد الراوية قال سأل أعشى همدان شجرة بن سليمان العبسي حاجة فرده عنها فقال يهجوه\n(لقد كنت خياطا فأصبحت فارسا ... تعد إذا عد الفوارس من مضر)\n(فإن كنت قد أنكرت هذا فقل كذا ... وبين لي الجرح الذي كان قد دثر)\n(وإصبعك الوسطى عليه شهيدة ... وما ذاك إلا وخزها الثوب بالإبر)\nال وكان يقال إن شجرة كان خياطا وقد كان ولى للحجاج بعض أعمال السواد فلما قدم على الحجاج قال له يا شجرة أرني إصبعك أنظر إليها قال أصلح الله الأمير وما تصنع بها قال أنظر إلى صفة الأعشى فخجل شجرة فقال الحجاج لحاجبه مر المعطي أن يعطي الأعشى من عطاء شجرة كذا\nوكذا يا شجرة إذا أتاك امرؤ ذو حسب ولسان فاشتر عرضك منه","topic":"أخبار أعشى همدان ونسبه","topicNo":56,"sp":8,"spl":"شعره في هزيمة الزبير الخثعمي","partial":1},
{"id":"b56-11","bab":"الجزء 6","sec":"الحجاج يأسره ويقتله","page":"ج6 ص68","text":"أخبرني علي بن سليمان الأخفش قال حدثنا محمد بن يزيد الأزدي قال حدثنا أحمد بن عمرو الحنفي عن جماعة قال المبرد أحسب أن أحدهم مؤرج بن عمرو السدوسي قالوا لما أتي الحجاج بن يوسف الثقفي بأعشى همدان أسيرا قال الحمد لله الذي أمكن منك ألست القائل\n(لما سفونا للكفور الفتان ... بالسيد الغطريف عبد الرحمن)\n(سار يجمع كالقطا من قحطان ... ومن معد قد أتى ابن عدنان)\n(أأمكن ربي من ثقيف همدان ... يوما إلى الليل يسلي ما كان)\n(إن ثقيفا منهم الكذابان ... كذابها الماضي وكذاب ثان)\nولست القائل\n(يابن الأشج قريع كندة ... لا أبالي فيك عتبا)\n(أنت الرئيس ابن الرئيس ... وأنت أعلى الناس كعبا)\n(نبئت حجاج بن يوسف ... خر من زلق فتبا)\n(فانهض فديت لعله ... يجلو بك الرحمن كربا)\n(وابعث عطية في الخيول ... يكبهن عليه كبا)\nلا يا عدو الله بل عبد الرحمن بن الأشعث هو الذي خر من زلق فتب وحار وانكب وما لقي ما أحب ورفع بها صوته واربد وجهه واهتز منكباه فلم يبق أحد في المجلس إلا أهمته نفسه وارتعدت فرائصه فقال له الأعشى بل أنا القائل أيها الأمير\n(أبى الله إلا أن يتم نوره ... ويطفىء نار الفاسقين فتخمدا)\n(وينزل ذلا بالعراق وأهله ... كما نقضوا العهد الوثيق المؤكدا)\n(وما لبث الحجاج أن سل سيفه ... علينا فولى جمعنا وتبددا)\n(وما زاحف الحجاج إلا رأيته ... حساما ملقى للحروب معودا)\n(فكيف رأيت الله فرق جمعهم ... ومزقهم عرض البلاد وشردا)\n(بما نكثوا من بيعة بعد بيعة ... إذا ضمنوها اليوم خاسوا بها غدا)\n(وما أحدثوا من بدعة وعظيمة ... من القوم لم تصعد إلى الله مصعدا)\n(ولما دلفنا لإبن يوسف ضلة ... وأبرق منا العارضان وأرعدا)\n(قطعنا إليه الخندقين وإنما ... )\n(قطعنا وأفضينا إلى الموت مرصدا ... )\n... ( فصادمنا الحجاج دون صفوفنا ... كفاحا ولم يضرب لذلك موعدا\n(بجند أمير المؤمنين وخيله ... وسلطانه أمسى معانا مؤيدا)\n(ليهنىء أمير المؤمنين ظهوره ... على أمة كانوا بغاة وحسدا)\n(وجدنا بني مروان خير أئمة ... وأعظم هذا الخلق حلما وسؤددا)\n(وخير قريش في قريش أرومة ... وأكرمهم إلا النبي محمدا)\n(إذا ما تدبرنا عواقب أمرنا ... وجدنا أمير المؤمنين المسددا)\n(سيغلب قوما غالبوا الله جهرة ... وإن كايدوه كان أقوى وأكيدا)\n(كذاك يضل الله من كان قلبه ... ضعيفا ومن والى النفاق وألحدا)\n(فقد تركوا الأموال والأهل خلفهم ... وبيضا عليهن الجلابين خردا)\n(ينادينهم مستعبرات إليهم ... ويذرين دمعا في الخدود وإثمدا)\n(وإلا تناولهن منك برحمة ... يكن سببا والبعولة أعبدا)\n(تعطف أمير المؤمنين عليهم ... فقد تركوا أمر السفاهة والردى)\n(لعلهم أن يحدثوا العام توبة ... وتعرف نصحا منهم وتوددا)\n(لقد شمت يابن الأشعث العام مصرنا ... فظلوا وما لاقوا من الطير أسعدا)\n(كما شاءم الله النجير وأهله ... بجدك من قد كان أشقى وأنكدا)\nقال من حضر من أهل الشام قد أحسن أيها الأمير فخل سبيله فقال أتظنون أنه أراد المدح لا والله لكنه قال هذا أسفا لغلبتكم إياه وأراد به أن يحرض أصحابه ثم أقبل عليه فقال له أظننت يا عدو الله أنك تخدعني بهذا الشعر وتنفلت من يدي حتى تنجو ألست القائل ويحك\n(وإذا سألت المجد أين محله ... فالمجد بين محمد وسعيد)\n(بين الأغر وبين قيس باذخ ... بخ بخ لوالده وللمولود)\nالله لا تبخبخ بعدها أبدا أو لست القائل\n(وأصابني قوم وكنت أصيبهم ... فاليوم أصبر للزمان وأعرف)\nذبت والله ما كنت صبورا ولا عروفا ثم قلت بعده\n(وإذا تصبك من الحوادث نكبة ... فاصبر فكل غيابة ستكشف)","topic":"أخبار أعشى همدان ونسبه","topicNo":56,"sp":9,"spl":"الحجاج يأسره ويقتله","partial":1},
{"id":"b56-12","bab":"الجزء 6","sec":"الحجاج يأسره ويقتله","page":"ج6 ص68","text":"ما والله لتكونن نكبة لا تنكشف غيابتها عنك أبدا يا حرسي اضرب عنقه فضرب عنقه وذكر مؤرج السدوسي أن الأعشى كان شديد التحريض على الحجاج في تلك الحروب فجال أهل العراق جولة ثم عادوا فنزل عن سرجه ونزعه عن فرسه ونزع درعه فوضعها فوق السرج ثم جلس عليها فأحدث والناس يرونه ثم أقبل عليهم فقال لهم لعلكم أنكرتم ما صنعت قالوا أو ليس هذا موضع نكير قال لا كلكم قد سلح في سرجه ودرعه خوفا وفرقا ولكنكم سترتموه وأظهرته فحمي القوم وقاتلوا أشد قتال يومهم إلى الليل وشاعت فيهم الجراح والقتلى وانهزم أهل الشأم يومئذ ثم عاودوهم من غد وقد نكأتهم الحرب وجاء مدد من أهل الشأم فباكروهم القتال وهم مستريحون فكانت الهزيمة وقتل ابن الأشعث وقد حكيت هذه الحكاية عن أبي كلدة اليشكري أنه فعلها في هذه الوقعة وذكر ذلك أبو عمرو الشيباني في أخبار أبي كلدة وقد ذكر ما حكاه مع أخباره في موضعه من هذا الكتاب","topic":"أخبار أعشى همدان ونسبه","topicNo":56,"sp":10,"spl":"الحجاج يأسره ويقتله"}]);
window.__BOOK__['p03'].push([{"id":"b57-1","bab":"الجزء 6","sec":"أخبار أحمد النصبي ونسبه","page":"ج6 ص72","text":"النصبي هو صاحب الأنصاب وأول من غنى بها وعنه أخذ النصب في الغناء هو أحمد بن أسامة الهمداني من رهط الأعشى الأدنين ولم أجد نسبه متصلا فأذكره وكان يغني بالطنبور في الإسلام وكان فيما يقال ينادم عبيد الله بن زياد سرا ويغينه وله صنعة كثيرة حسنة لم يلحقها أحد من الطنبوريين ولا كثير ممن يغني بالعود وذكره جحظة في كتاب الطنبوريين فأتى من ذكره بشيء ليس من جنس أخباره ولا زمانه وثلبه فيما ذكره وكان مذهبه عفا الله عنا وعنه في هذا الكتاب أن يثلب جميع من ذكره من أهل صناعته بأقبح ما قدر عليه وكان يجب عليه ضد هذا لأن من انتسب إلى صناعنه ثم ذكر متقدمي أهلها كان الأجمل به أن يذكر محاسن أخبارهم وظريف قصصهم ومليح ما عرفه منهم لا أن يثلبهم بما لا يعلم وما يعلم فكان فيما قرأت عليه من هذا الكتاب أخبار أحمد النصبي وبه صدر كتابه فقال أحمد النصبي أول من غنى الأنصاب على الطنبور وأظهرها وسيرها ولم يخدم خليفة ولا كان له شعر ولا أدب وحدثني جماعة من الكوفيين أنه لم يكن بالكوفة أبخل منه مع يساره وأنه كان يقرض الناس بالربا وأنه اغتص في دعوة دعي إليها بفالوذجة حارة فبلعها فجمعت أحشاءه فمات وهذا كله باطل أما الغناء فله منه صنعة في الثقيل الأول\nوخفيف الثقيل والثقيل الثاني ليس لكثير أحد مثلها ومنها الصوت الذي تقدم ذكره وهو قوله\n(حييا خولة مني بالسلام ... )\nمنها\n(سلبت الجواري حليهن فلم تدع ... سوارا ولا طوقا على النحر مذهبا)\nهو من الثقيل الثاني والشعر للعديل بن الفرخ وقد ذكرت ذلك في أخباره ومنها\n(يأيها القلب المطيع الهوى ... أنى اعتراك الطرب النازح)\nهو أيضا من الثقيل الثاني وأصوات كثيرة نادرة تدل على تقدمه وأما ما وصفه من بخله وقرضه للناس بالربا وموته من فالوذجة حارة أكلها فلا أدري من من الكوفيين حدثه بهذا الحديث ليس يخلو من أن يكون كاذبا أو نحل هو هذه الحكاية ووضعها هنا لأن أحمد النصبي خرج مع أعشى همدان وكان قرابته وإلفه في عسكر ابن الأشعث فقتل فيمن قتل روى ذلك الثقات من أهل الكوفة والعلم بأخبار الناس وذلك يذكر في جملة أخباره أخبرنا محمد بن مزيد بن أبي الأزهر والحسين بن يحيى قالا حدثنا حماد بن إسحاق عن أبيه وذكره العنزي في أخبار أعشى همدان المذكورو عنه عن رجاله\nالمسمين قال كان أحمد النصبي مواخيا لأعشى همدان مواصلا له فأكثر غنائه في أشعاره مثل صنعته في شعره\n(حييا خولة مني بالسلام ... )\nو\n(لمن الظعائن سيرهن ترجف ... )\nو\n(يأيها القلب المطيع الهوى ... )\nهذه الأصوات قلائد صنعته وغرر أغانيه قال وكان سبب قوله الشعر في سليم ابن صالح بن سعد بن جابر العنبري وكان منزل سليم ساباط المدائن أن أعشى همدان وأحمد النصبي خرجا في بعض مغازيهما فنزلا على سليم فأحسن قراهما وأمر لدوابهما بعلوفة وقضيم وأقسم عليهما أن ينتقلا إلى منزله ففعلا فعرض عليهما الشراب فأنعما به وطلباه فوضعه بين أيديهما وجلسا يشربان فقال أحمد النصبي للأعشى قل في هذا الرجل الكريم شعرا تمدحه به حتى أغني فيه فقال الأعشى يمدحه\n(يأيها القلب المطيع الهوى ... أنى اعتراك الطرب النازح)\n(تذكر جملا فإذا ما نأت ... طار شعاعا قلبك الطامح)\n(هلا تناهيت وكنت امرأ ... يزجرك المرشد والناصح)\n(ما لك لا تترك جهل الصبا ... وقد علاك الشمط الواضح)\n(فصار من ينهاك عن حبها ... لم تر إلا أنه كاشح)\n(يا جمل ما حبي لكم زائل ... عني ولا عن كبدي نازح)\n(حملت ودا لكم خالصا ... جدا إذا ما هزل المازح)\n(ثم لقد طال طلابيكم ... أسعى وخير العمل الناجح)\n(إني توسمت امرأ ماجدا ... يصدق في مدحته المادح)\n(ذؤابة العنبر فاخترته ... والمرء قد ينعشه الصالح)\n(أبلج بهلولا وظني به ... أن ثنائي عنده رابح)\n(سليم ما أنت بنكس ولا ... ذمك لي غاد ولا رائح)\n(أعطيت ودي وثنائي معا ... وخلة ميزانها راجح)\n(أرعاك بالغيب وأهوى لك الرشد ... وجيبي فاعلمن ناصح)\n(إني لمن سالمت سلم ومن ... عاديت أمسي وله ناطح)\n(في الرأس منه وعلى أنفه ... من نقماتي ميسم لائح)\n(نعم فتى الحي إذا ليلة ... لم يور فيها زنده القادح)\n(وراح بالشول إلى أهلها ... مغبرة أذقانها كالح)\n(وهبت الريح شآمية ... فانجحر القابس والنابح)\n(قد علم الحي إذا أمحلوا ... أنك رفاد لهم مانح)","topic":"أخبار أحمد النصبي ونسبه","topicNo":57,"sp":0,"spl":"أخبار أحمد النصبي ونسبه","partialRef":{"sid":"b56-2","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b57-2","bab":"الجزء 6","sec":"أخبار أحمد النصبي ونسبه","page":"ج6 ص72","text":"(في الليلة القالي قراها التي ... لا عابق فيها ولا صابح)\n(فالضيف معروف له حقه ... له على أبوابكم فاتح)\n(والخيل قد تعلم يوم الوغى ... أنك من جمرتها ناضح)\nال فغنى أحمد النصبي في بعض هذه الأبيات وجارية لسليم في السطح فسمعت الغناء فنزلت إلى مولاها وقالت إني سمعت من أضيافك شعرا ما سمعت أحسن منه فخرج معها مولاها فاستمع حتى فهم ثم نزل فدخل عليهما فقال لأحمد لمن هذا الشعر والغناء ومن أنتما فقال الشعر لهذا وهو أبو المصبح أعشى همدان والغناء لي وأنا أحمد النصبي الهمداني فانكب على رأس أعشى همدان فقبله وقال كتمتماني أنفسكما وكدتما أن تفارقاني ولم أعرفكما ولم أعلم خبركما واحتبسهما شهرا ثم حملهما على فرسين وقال خلفا عندي ما كان من دوابكما وارجعا من مغزاكما إلي فمضيا إلى مغزاهما فأقاما حينا ثم انصرفا فلما شارفا منزله قال أحمد للأعشى إني أرى عجبا قال وما هو قال أرى فوق قصر سليم ثعلبا قال لئن كنت صادقا فما بقي في القرية أحد فدخلا القرية فوجدا سليما وجميع أهل القرية قد أصابهم الطاعون فمات أكثرهم وانتقل باقيهم هكذا ذكر إسحاق وذكر غيره أن الحجاج طالب سليما بمال عظيم فلم يخرج منه حتى باع كل ما يملكه وخربت قريته وتفرق أهلها ثم باعه الحجاج عبدا فاشتراه بعض أشراف أهل الكوفة إما أسماء بن خارجة وإما بعض نظرائه فأعتقه","topic":"أخبار أحمد النصبي ونسبه","topicNo":57,"sp":1,"spl":"أخبار أحمد النصبي ونسبه — من المائة المختارة"},
{"id":"b57-3","bab":"الجزء 6","sec":"نسبة هذاالصوت الذي قال الأعشى شعره وصنع أحمد النصبي لحنه في سليم","page":"ج6 ص76","text":"صوت\n(يأيها القلب المطيع الهوى ... أنى اعتراك الطرب النازح)\n(تذكر جملا فإذا ما نأت ... طار شعاعا قلبك الطامح)\n(أعطيت ودي وثنائي معا ... وخلة ميزانها راجح)\n(إني تخيرت امرأ ماجدا ... يصدق مدحته المادح)\n(سليم ما أنت بنكس ولا ... ذمك لي غاد ولا رائح)\n(نعم فتى الحي إذا ليلة ... لم يور فيها زنده القادح)\n(وراح بالشول إلى أهلها ... مغبرة أذقانها كالح)\n(وهبت الريح شآمية ... فانجحر القابس والنابح)\nلشعر لأعشى همدان والغناء لأحمد النصبي ولحنه ثاني ثقيل بالسبابة في مجرى الوسطى عن إسحاق وذكر يونس أن فيه لمالك لحنا ولسنان الكاتب لحنا آخر صوت","topic":"أخبار أحمد النصبي ونسبه","topicNo":57,"sp":1,"spl":"أخبار أحمد النصبي ونسبه — من المائة المختارة"},
{"id":"b57-4","bab":"الجزء 6","sec":"من المائة المختارة","page":"ج6 ص77","text":"(تنكر من سعدى وأقفر من هند ... مقامهما بين الرغامين فالفرد)\n(محل لسعدى طالما سكنت به ... فأوحش ممن كان يسكنه بعدي)\nالشعر لحماد الراوية والغناء لعبادل ولحنه المختار من الثقيل الأول بإطلاق الوتر في مجرى البنصر عن إسحاق وفيه خفيف ثقيل أول بالوسطى ذكر الهشامي أنه للهذلي وذكر عمرو بن بانة أنه لعبادل بن عطية","topic":"أخبار أحمد النصبي ونسبه","topicNo":57,"sp":1,"spl":"أخبار أحمد النصبي ونسبه — من المائة المختارة"},
{"id":"b58-1","bab":"الجزء 6","sec":"أخبار حماد الراوية ونسبه","page":"ج6 ص79","text":"هو حماد بن ميسرة فيما ذكره الهيثم بن عدي وكان صاحبه وراويته وأعلم الناس به وزعم أنه مولى بني شيبان وذكر المدائني والقحذمي أنه حماد بن سابور وكان من أعلم الناس بأيام العرب وأخبارها وأشعارها وأنسابها ولغاتها وكانت ملوك بني أمية تقدمه وتؤثره وتستزيره فيفد عليهم وينادمهم ويسألونه عن أيام العرب وعلومها ويجزلون صلته حدثنا محمد بن العباس اليزيدي وعمي وإسماعيل العتكي قالوا حدثنا الرياشي قال قال الأصمعي كان حماد أعلم الناس إذا نصح قال وقلت لحماد ممن أنتم قال كان أبي من سبي سلمان بن ربيعة فطرحتنا سلمان لبني شيبان فولاؤنا لهم قال وكان أبوه يسمى ميسرة ويكنى أبا ليلى قال العتكي في خبره قال الرياشي وكذلك ذكر الهيثم بن عدي في أمر حماد أخبرني عمي قال حدثني الكراني قال حدثنا العمري عن العتبي والهيثم بن عدي ولقيط قالوا قال الوليد بن يزيد لحماد الراوية بم استحققت هذا اللقب فقيل لك\nالراوية فقال بأني أروي لكل شاعر تعرفه يا أمير المؤمنين أو سمعت به ثم أروي لأكثر منهم ممن تعرف أنك لم تعرفه ولم تسمع به ثم لا أنشد شعرا قديما ولا محدثا إلا ميزت القديم منه من المحدث فقال إن هذا لعلم وأبيك كثير فكم مقدار ما تحفظ من الشعر قال كثيرا ولكني أنشدك على كل حرف من حروف المعجم مائة قصيدة كبيرة سوى المقطعات من شعر الجاهلية دون شعر الإسلام قال سأمتحنك في هذا وأمره بالإنشاد فأنشد الوليد حتى ضجر ثم وكل به من استحلفه أن يصدقه عنه ويستوفي عليه فأنشده ألفين وتسعمائة قصيدة للجاهليين وأخبر الوليد بذلك فأمر له بمائة ألف درهم","topic":"أخبار حماد الراوية ونسبه","topicNo":58,"sp":0,"spl":"أخبار حماد الراوية ونسبه — حماد ومروان بن أبي حفصة"},
{"id":"b58-2","bab":"الجزء 6","sec":"حماد ومروان بن أبي حفصة","page":"ج6 ص80","text":"أخبرني يحيى بن علي المنجم قال حدثني أبي قال حدثني إسحاق الموصلي عن مروان بن أبي حفصة وأخبرني محمد بن خلف بن المرزبان قال حدثني أبو بكر العامري عن الأثرم عن مروان بن أبي حفصة قال دخلت أنا وطريح بن إسماعيل الثقفي والحسين بن مطير الأسدي في\nجماعة من الشعراء على الوليد بن يزيد وهو في فرش قد غاب فيها وإذا رجل عنده كلما أنشد شاعر شعرا وقف الوليد بن يزيد على بيت بيت من شعره وقال هذا أخذه من موضع كذا وكذا وهذا المعنى نقله من موضع كذا وكذا من شعر فلان حتى أتى على أكثر الشعر فقلت من هذا فقالوا حماد الراوية فلما وقفت بين يدي الوليد أنشده قلت ما كلام هذا في مجلس أمير المؤمنين وهو لحنة لحانة فأقبل الشيخ علي وقال يابن أخي إني رجل أكلم العامة فأتكلم بكلامها فهل تروي من أشعار العرب شيئا فذهب عني الشعر كله إلا شعر ابن مقبل فقلت له نعم شعر ابن مقبل قال أنشد فأنشدته قوله\n(سل الدار من جنبي حبر فواهب ... إذا ما رأى هضب القليب المضيح)\nم جزت فقال لي قف فوقفت فقال لي ماذا يقول فلم أدر ما يقول فقال لي حماد يابن أخي أنا أعلم الناس بكلام العرب يقال تراءى الموضعان إذا تقابلا حدثني عمي قال حدثني الكراني عن العمري عن الهيثم بن عدي قال قلت لحماد الراوية يوما ألق علي ما شئت من الشعر أفسره لك فضحك\nوقال لي ما معنى قول ابن مزاحم الثمالي\n(تخوف السير منها تامكا قردا ... كما تخوف عود النبعة السفن)\nلم أدر ما أقول فقال تخوف تنقص قال الله عز و جل ( أو يأخذهم على تخوف\nأي على تنقص قال الهيثم ما رأيت رجلا أعلم بكلام العرب من حماد حدثني محمد بن خلف وكيع قال حدثني الكراني محمد بن سعد عن النضر بن عمرو عن الوليد بن هشام عن أبيه قال أنشدني الفرزدق وحماد الراوية حاضر\n(وكنت كذئب السوء لما رأى دما ... بصاحبه يوما أحال على الدم)\nقال له حماد أنت تقوله قال نعم قال ليس الأمر كذلك هذا لرجل من أهل اليمن قال ومن يعلم هذا غيرك أفأردت أن أتركه وقد نحلنيه الناس ورووه لي لأنك تعلمه وحدك ويجهله الناس جميعا غيرك حدثني محمد بن العباس اليزيدي قال حدثني الفضل قال حدثني ابن النطاح قال حدثني أبو عمرو الشيباني قال ما سألت أبا عمرو بن العلاء قط عن حماد الراوية إلا قدمه على نفسه ولا سألت حمادا عن أبي عمرو إلا قدمه على نفسه\nحدثنا إبراهيم بن أيوب عن عبد الله بن مسلم وذكر عبد الله بن مسلم عن الثقفي عن إبراهيم بن عمر والعامري قالا كان بالكوفة ثلاثة نفر يقال لهم الحمادون حماد عجرد وجماد بن الزبرقان وحماد الراوية يتنادمون على الشراب ويتناشدون الأشعار ويتعاشرون معاشرة جميلة وكانوا كأنهم نفس واحدة وكانوا يرمون بالزندقة جميعا","topic":"أخبار حماد الراوية ونسبه","topicNo":58,"sp":0,"spl":"أخبار حماد الراوية ونسبه — حماد ومروان بن أبي حفصة"},
{"id":"b58-3","bab":"الجزء 6","sec":"حماد البخيل","page":"ج6 ص83","text":"أخبري الحسن بن يحيى المرداسي قال حدثنا حماد بن إسحاق عن أبيه قال دخل مطيع بن إياس ويحيى بن زياد على حماد الراوية فإذا سراجه على ثلاث قصبات قد جمع أعلاهن وأسفلهن بطين فقال له يحيى بن زياد يا حماد إنك لمسرف مبتذل لحر المتاع فقال له مطيع ألا تبيع هذه المنارة وتشتري أقل ثمنا منها وتنفق علينا وعلى نفسك الباقي وتتسع به فقال له يحيى ما أحسن ظنك به ومن أين له مثل هذه إنما هي وديعة أو عارية فقال له مطيع أما إنه لعظيم الأمانة عند الناس قال له يحيى وعلى عظيم أمانته فما أجهل من يخرج مثل هذه من داره ويأمن عليها غيره قال مطيع ما أظنها عارية ولا وديعة ولكني أظنها مرهونة عنده على مال وإلا فمن يخرج هذه من بيته فقال لهما حماد قوما عني يا بني الزانيتين واخرجا من منزلي فشر منكما من يدخلكما بيته","topic":"أخبار حماد الراوية ونسبه","topicNo":58,"sp":1,"spl":"حماد البخيل"},
{"id":"b58-4","bab":"الجزء 6","sec":"انقطع ليزيد فجفاه هشام","page":"ج6 ص84","text":"حدثني الحسن بن علي قال حدثنا أحمد بن عبيد أبو عصيدة قال حدثني محمد بن عبد الرحمن العبدي عن حميد بن محمد الكوفي عن إبراهيم بن عبد الرحمن القرشي عن محمد بن أنس وأخبرني الحسن بن يحيى عن حماد عن أبيه عن الهيثم بن عدي عن حماد الراوية وخبر حماد بن إسحاق أتم واللفظ له قال حماد الراوية كان انقطاعي إلى يزيد بن عبد الملك فكان هشام يجفوني لذلك دون سائر أهله من بني أمية في أيام يزيد فلما مات يزيد وأفضت الخلافة إلى هشام خفته فمكثت في بيتي سنة لا أخرج إلا لمن أثق به من إخواني سرا فلما لم أسمع أحد يذكرني سنة أمنت فخرجت فصليت الجمعة ثم جلست عند باب الفيل فإذا للشرطين قد وقفا علي فقالا لي يا حماد أجب الأمير يوسف بن عمر فقلت في نفسي من هذا كنت أحذر ثم قلت للشريطيين هل لكما أن تدعاني آتي أهلي فأودعهم وداع من لا ينصرف إليهم أبدا ثم أصير معكما إليه فقالا ما إلى ذلك من سبيل فاستسلمت في أيديهما وصرت إلى يوسف بن عمر وهو في الإيوان الأحمر فسلمت عليه فرد علي السلام ورمى إلي كتابا فيه بسم الله الرحمن الرحمن الرحيم من عبد الله هشام أمير المؤمنين إلى يوسف بن عمر أما بعد فإذا قرأت كتابي هذا فابعث إلى حماد الراوية من يأتيك به غير مروع ولا متعتع وادفع إليه خمسمائة دينار وجملا مهريا يسير عليه اثنتي عشرة ليلة إلى دمشق\nدمشق فأخذت الخمسمائة الدينار ونظرت فإذا جمل مرحول فوضعت رجلي في الغرز وسرت اثنتي عشرة ليلة حتى وافيت باب هشام فاستأذنت فأذن لي فدخلت عليه في دار قوراء مفروشة بالزحام وهو في مجلس مفروش بالرخام وبين كل رخامتين قضيب ذهب وحيطانه كذلك وهشام جالس على طنفسة حمراء وعليه ثياب خز حمر وقد تضمخ بالمسك والعنبر وبين يديه مسك مفتوت في أواني ذهب يقلبه بيده فتفوح روائحه فسلمت فرد علي واستدناني فدنوت حتى قبلت رجله وإذا جاريتان لم أر قبلهما مثلهما في أذني كل واحدة منهما حلقتان من ذهب فيهما لؤلؤلتان تتوقدان فقال لي كيف أنت يا حماد وكيف حالك فقلت بخير يا أمير المؤمنين قال أتدري فيم بعث إليك قلت لا قا لبعثت إليك لبيت خطر ببالي لم أدر من قاله فقلت وما هو فقال\n(فدعوا بالصبوح يوما فجاءت ... قينة في يمينها إبريق)\nلت هذا يقوله عدي بن زيد في قصيدة له قال فأنشدنيها فأنشدته\n(بكر العاذلون في وضح الصبح ... يقولون لي ألا تستفيق)\n(ويلومون فيك يابنة عبد الله ... والقلب عندكم موهوق)\n(لست أدري إذ أكثروا العذل عندي ... أعدو يلومني أو صديق)\n(زانها حسنها وفرع عميم ... وأثيث صلت الجبين أنيق)\n(وثنايا مفلجات عذاب ... لا قصار ترى ولا هن روق)\n(فدعوا بالصبوح يوما فجاءت ... قينة في يمينها إبريق)\n(قدمته على عقار كعين الديك ... صفى سلافها الراووق)\n(مرة قبل مزجها فإذا ما ... مزجت لذ طعمها من يذوق)\n(وطفت فوقها فقاقيع كالدر ... صغار يثيرها التصفيق)\n(ثم كان المزاج ماء سماء ... غير ما آجن ولا مطروق)\nال فطرب ثم قال أحسنت والله يا حماد يا جارية أسقيه فسقتني شربة ذهبت بثلث عقلي وقال أعد فأعدت فاستخفه الطرب حتى نزل عن فرشه ثم قال للجارية الأخرى اسقيه فسقتني شربة ذهبت بثلث عقلي فقلت إن سقتني الثالثة افتضحت فقال سل حوائجك فقلت كائنة ما كانت قال نعم قلت إحدى الجاريتين فقال لي هما جميعا لك بما عليهما وما لهما ثم قال للأولى اسقيه فسقتني شربة سقطت معها فلم اعقل حتى أصحبت فإذا بالجاريتين عند رأسي وإذا عدة من الخدم مع كل واحد منهم بدرة فقال لي أحدهم أمير المؤمنين يقرأ عليك السلام ويقول لك خذ هذه فانتفع بها فأخذتها\nوالجاريتين وانصرفت هذا لفظ حماد عن أبيه ولم يقل أحمد بن عبيد في خبره أنه سقاه شيئا ولكنه ذكر أنه طرب لإنشاده ووهب له الجاريتين لما طلب إحداهما وأنزله في دار ثم نقله من غد إلى منزل أعده له فانتقل إليه فوجد فيه الجاريتين وما لهما وكل ما يحتاج إليه وأنه أقام عنده مدة فوصل إليه مائة ألف درهم وهذا هو الصحيح لأن هشاما لم يكن يشرب ولا يسقى أحد بحضرته مسكرا وكان ينكر ذلك ويعيبه ويعاقب عليه في أبيات عدي المذكورة في هذا الخبر غناء نسبته صوت\n(بكر العاذلون في وضح الصبح ... يقولون ما له لا يفيق)\n(ويلومون فيك يابنة عبد الله ... والقلب عندكم موهوق)\n(ثم نادوا إلى الصبوح فقامت ... قينة في يمينها إبريق)","topic":"أخبار حماد الراوية ونسبه","topicNo":58,"sp":2,"spl":"انقطع ليزيد فجفاه هشام"},
{"id":"b58-5","bab":"الجزء 6","sec":"انقطع ليزيد فجفاه هشام","page":"ج6 ص84","text":"(قدمته على عقار كعين الديك ... صفى سلافها الراووق)\nي البيتين الأولين لحن من الثقيل الأول مختلف في صانعه نسبه يحيى بن المكي إلى معبد ونسبه الهشامي إلى حنين وفي الثالث وهو ثم نادوا والرابع لعبد الله بن العباس الربيعي رمل وفيهما خفيف رمل ينسب إلى مالك وخفيف ثقيل ذكر حبش أنه لحنين","topic":"أخبار حماد الراوية ونسبه","topicNo":58,"sp":3,"spl":"انقطع ليزيد فجفاه هشام — أجازه يوسف بن عمر بأمر الوليد"},
{"id":"b58-6","bab":"الجزء 6","sec":"أجازه يوسف بن عمر بأمر الوليد","page":"ج6 ص88","text":"أخبرني محمد بن مزيد والحسين بن يحيى قالا حدثنا حماد بن إسحاق عن أبيه عن الأصمعي قال قال حماد الراوية كتب الوليد بن يزيد وهو خليفة إلى يوسف بن عمر أحمل إلي حمادا الراوية على ما أحب من دواب البريد وأعطه عشرة آلاف درهم معونة له فلما أتاه الكتاب وأنا عنده نبذه إلي فقلت السمع والطاعة فقال يا دكين بن شجرة أعطه عشرة آلاف درهم فأخذتها فلما كان اليوم الذي اردت الخروج فيه أتيت يوسف مودعا فقال يا حماد أنا بالموضع الذي قد عرفت من أمير المؤمنين ولست مستغنيا عن ثنائك فقلت أصلح الله الأمير إن العوان لا تعلم الخمرة خرجت حتى أتيت الوليد بن يزيد وهو بالبخراء فاستأذنت فأذن لي فإذا هو على سرير ممهد وعليه ثوبان إزار ورداء يقيئان الزعفران قيئا وإذا عنده معبد ومالك وأبو كامل مولاه فتركني حتى سكن جأشي ثم قال أنشدني\n(أمن المنون وريبها تتوجع ... )\nأنشدته إياها حتى أتيت على آخرها فقال لساقيه اسقه يا سبرة أكؤسا فسقاني\nثلاث كؤس خدرت ما بين الذؤابة والنعل ثم قال يا معبد غنني\n(ألا هل جاءك الأظعان ... إذ جاوزن مطلحا)\nغناه ثم قال غنني\n(أتنسى إذ تودعنا سليمى ... بفرع بشامة سقي البشام)\nغنى ثم قال غنني\n(جلا أمية عنا كل مظلمة ... سهل الحجاب وأوفى بالذي وعدا)\nغناه ثم قال اسقني يا غلام شاب بزب فرعون فأتاه بقدح معوج فيه طول فسقاه به عشرين قدحا ثم أتاه الحاجب فقال أصلح الله أمير المؤمنين الرجل الذي طلبت بالباب فقال أدخله فدخل غلام شاب لم أر أحسن منه وجها في رجله فدع فقال يا سبرة اسقه كأسا فسقاه ثم قال له غنني\n(وهي إذ ذاك عليها مئزر ... ولها بيت جوار من لعب)\nغناه فنبذ إليه أحد ثوبيه ثم قال غنني\n(طرق الخيال فمرحبا ... الفا برؤية زينبا)\nغضب معبد وقال يا أمير المؤمنين إنا مقبلون إليك بأقدارنا وأسناننا وإنك تتركنا بمزجر الكلب وأقبلت على هذا الصبي فقال والله يا أبا عباد ما جهلت\nقدرك ولا سنك ولكن هذا الغلام طرحني على مثل الطياجن من حرارة غنائه فسألت عن الغلام فإذا هو ابن عائشة","topic":"أخبار حماد الراوية ونسبه","topicNo":58,"sp":3,"spl":"انقطع ليزيد فجفاه هشام — أجازه يوسف بن عمر بأمر الوليد","partialRef":{"sid":"b10-5","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b58-7","bab":"الجزء 6","sec":"طلبه المنصور فجاءه وأنشده شعرا","page":"ج6 ص90","text":"حدثني الحسن بن محمد المادراني الكاتب قال حدثني الرياشي عن العتبي وأخبرني به هاشم بن محمد عن الرياشي وليس خبره بتمام هذا قال طلب المنصور حمادا الراوية فطلب ببغداد فلم يوجد وسئل عنه إخوانه فعرفوا من سألهم عنه أنه بالبصرة فوجهوا إليه برسول يشخصه قال الرسول فوجدته في حانة وهو عريان يشرب نبيذا من إجانة وعلى سوأته رأس دستجة فقلت أجب أمير المؤمنين فما رأيت رسالة أرفع ولا حالة أوضع من تلك فأجاب فأشخصته إليه فلما مثل بين يديه قال له أنشدني شعر هفان بن همام بن نضلة يرثي أباه فأنشده\n(خليلي عوجا إنها حاجة لنا ... على قبر همام سقته الرواعد)\n(على قبر من يرجى نداه ويبتغى ... جداه إذا لم يحمد الأرض رائد)\n(كريم الثنا حلو الشمائل بينه ... وبين المزجى نفنف متباعد)\n(إذا نازع القوم الأحاديث لم يكن ... عييا ولا ثقلا على من يقاعد)\n(صبور على العلات يصبح بطنه ... خميصا وآتيه على الزاد حامد)\n(وضعنا الفتى كل الفتى في حفيرة ... بحرين قد راحت عليه العوائد)\n(صريعا كنصل السيف تضرب جلوه ... ترائبهن المعولات الفواقد)\nال فبكى أبو جعفر حتى أخضل لحيته ثم قال هكذا كان أخي أبو العباس رضي الله عنه أخبرني الحسين بن يحيى المرداسي قال حدثنا حماد بن إسحاق عن أبيه قال كان جعفر بن أبي جعفر المنصور المعروف بابن الكردية يستخف مطيع بن إياس ويحبه وكان منقطعا إليه وله معه منزلة حسنة فذكر له حمادا الراوية وكان صديقه وكان مطرحا مجفوا في أيامهم فقال ائتنا به لنراه فأتى مطيع حمادا فأخبره بذلك وأمره بالمسير معه إليه فقال له حماد دعني فإن دولتي كانت مع بني أمية ومالي عند هؤلاء خير فأبى مطيع إلا الذهاب إليه فاستعار حماد سوادا وسيفا ثم أتاه ثم مضى به مطيع إلى جعفر فلما دخل عليه سلم عليه سلاما حسنا وأثنى عليه وذكر فضله فرد عليه وأمره بالجلوس فجلس فقال جعفر انشدني فقال لمن أيها الأمير ألشاعر بعينه أم لمن حضر قال بل أنشدني لجرير قال حماد فسلخ والله شعر جرير كله من قلبي إلا قوله\n(بان الخليط برامتين فودعوا ... أو كلما اعتزموا لبين تجزع)\nفاندفعت فأنشدته إياه حتى انتهيت إلى قوله\n(وتقول بوزع قد دببت على العصا ... هلا هزئت بغيرنا يا بوزع)\nال حماد فقال لي جعفر أعد هذا البيت فأعدته فقال بوزع أي شيء هو فقلت اسم امرأة فقال أمرأة اسمها بوزع هو بريء من الله ورسوله ونفي من العباس بن عبد المطلب إن كانت بوزع إلا غولا من الغيلان تركتني والله يا هذا لا أنام الليلة من فزع بوزع يا غلمان قفاه فصفعت والله حتى لم أدر أين أنا ثم قال جروا برجله فجروا برجلي حتى أخرجت من بين يديه مسحوبا فتخرق السواد وانكسر جفن السيف ولقيت شرا عظيما مما جرى علي وكان أغلظ من ذلك كله واشد بلاء إغرامي ثمن السواد وجفن السيف فلما انصرفت أتاني مطيع يتوجع لي فقلت له ألم أخبرك أني لا أصيب منهم خيرا وأن حظي قد مضى مع بني أمية حدثني جعفر بن قدامة قال حدثني أحمد بن أبي طاهر قال بلغني أن رجلا تحدث في مجلس حماد الراوية فقال بلغني أن المأبون له رحم كرحم المرأة قال وكان الرجل يرمى بهذا الداء فقال حماد لغلامه اكتب هذا الخبر عن الشيخ فإن خير العلم ما حمل عن أهله قال وكتب حماد الراوية إلى بعض الأشراف الرؤساء قال\n(إن لي حاجة فرأيك فيها ... لك نفسي فدى من الأوصاب)\n(وهي ليست مما يبلغها غيري ... ولا يستطيعها في كتاب)\n(غير أني أقولها حين ألقاك ... رويدا أسرها في حجاب)\nكتب إليه الرجل اكتب إلي بحاجتك ولا تشهرني بشعرك فكتب إليه حماد\n(إنني عاشق لجبتك الدكناء ... عشقا قد حال دون الشراب)\n(فاكسنيها فدتك نفسي وأهلي ... أتباهى بها على الأصحاب)\n(ولك الله والأمانة أن أجعلها ... عمرها أمير ثيابي)\nبعث إليه بها وقد رويت هذه القصة لمطيع بن إياس","topic":"أخبار حماد الراوية ونسبه","topicNo":58,"sp":4,"spl":"طلبه المنصور فجاءه وأنشده شعرا"},
{"id":"b58-8","bab":"الجزء 6","sec":"حماد والخزيمي وبعض الغلمان","page":"ج6 ص93","text":"أخبرني الحسين بن يحيى عن حماد بن إسحاق عن أبيه قال حدثني أبو يعقوب الخزيمي قال كنت في مجلس فيه حماد عجرد وحماد الراوية ومعنا غلام أمرد فنظر إليه حماد الراوية نظرا شديدا وقال لي يا أبا يعقوب قد عزمت الليلة على أن أدب على هذا الغلام فقلت شأنك به ثم نمنا فلم أشعر بشىء إلا وحماد ينيكني وإذا أنا قد غلطت ونمت في موضع الغلام فكرهت أن أتكلم فينتبه الناس فأفتضح وأبطل عليه ما أراد فأخذت بيده فوضعتها على عيني العوراء ليعرفني فقال قد عرفت الآن فيكون ماذا وفديناه بذبح عظيم قال وما برح علم الله وأنا أعالجه جهدي فلا ينفعني حتى أنزل قال إسحاق وأهدى حماد إلى صديق له غلاما وكتب إليه قد بعثت إليك غلاما تتعلم عليه كظم الغيظ قال\nواستهدى من صديق له نبيذا فأهدى إليه دسيتجة نبيذ فكتب إليه لو عرفت في العدد أقل من واحد وفي الألوان شرا من السواد لأهديته إلي قال وسمع مغنية تغني\n(عاد قلبي من الطويلة عاد ... )\nقال وثمود فإن الله عز و جل لم يفرق بينهما والشعر\n(عاد قلبي من الطويلة عيد ... )\nخبرني أبو الحسن الأسدي قال حدثنا الرياشي قال حدثني أبو عثمان اللاحقي وأخبرني به محمد بن مزيد عن حماد عن أبيه عن محمد بن سلام عن بشر بن المفضل بن لاحق قال جاء رجل إلى حماد الراوية فأنشده شعرا وقال أنا قلته فقال له أنت لا تقول مثل هذا هذا ليس لك وإن كنت صادقا فاهجني فذهب ثم عاد إليه فقال له قد قلت فيك\n(سيعلم حماد إذا ما هجوته ... أأنتحل الأشعار أم أنا شاعر)\n(ألم تر حمادا تقدم بطنه ... وأخر عنه ما تجن المآزر)\n(فليس براء خصيتيه ولو جثا ... لركبته ما دام للزيت عاصر)\n(فيا ليته أمسى قعيدة بيته ... له بعل صدق كومه متواتر)\n(فحماد نعم العرس للمرء يبتغي النكاح ... وبئس المرء فيمن يفاخر)\nفقال حماد حسبنا عافاك الله هذا المقدار وحسبك قد علمنا أنك شاعر وأنك قائل الشعر الأول وأجود منه وأحب أن تكتم هذا العشر ولا تذيعه فتفضحني فقال له قد كنت غنيا عن هذا وانصرف الرجل وجعل حماد يقول أسمعتم أعجب مما جررت على نفسي من البلاء حدثني الأسدي أبو الحسن قال حدثنا الرياشي قال حدثنا أبو عبد الله الفهمي قال عاب حماد الراوية شعرا لأبي الغول فقال يهجوه\n(نعم الفتى لو كان يعرف ربه ... ويقيم وقت صلاته حماد)\n(هدلت مشافره الدنان فأنفه ... مثل القدوم يسنها الحداد)\n(وابيض من شرب المدامة وجهه ... فبياضه يوم الحساب سواد)\n(لا يعجبنك بزه وثيابه ... إن اليهود ترى لها أجلاد)\n(حماد يا ضبعا تجر جعارها ... أخنى لها بالقريتين جراد)\n(سبعا يلاعبها ابنها وبناتها ... ولها من الخرق الكبار وساد)\nال معنى قوله\n(أخنى لها القريتين جراد ... )\nهو مثل قول العرب للضبع خامري أم عامر أبشري بجراد عظال وكمر رجل فإن الضبع تجيء إلى القتيل وقد استلقى على قفاه وانتفخ غرموله فكان\nكالمنعظ فتحتك به وتحيض من الشهوة فيثب عليها الذئب حينئذ فتلد منه السمع وهو دابة لا يولد له مثل البغل وفي مثل هذا المعنى يقول الشنفري الأزدي\n(تضحك الضبع لقتلى هذيل ... وترى الذئب لها يستهل)\nضحك تحيض وقال ابن النطاح كان حماد الراوية في أول أمره يتشطر ويصحب الصعاليك واللصوص فنقب ليلة على رجل فأخذ ماله وكان فيه جزء من شعر الأنصار فقرأه حماد\nفاستحلاه وتحفظه ثم طلب الأدب والشعر وأيام الناس ولغات العرب بعد ذلك وترك ما كان عليه فبلغ في العلم ما بلغ حدثنا محمد بن العباس اليزيدي قال حدثني عمي الفضل عن أبيه عن جده عن حماد الراوية قال دخلت على المهدي فقال أنشدني أحسن أبيات قيلت في السكر ولك عشرة آلاف درهم وخلعتان من كسوة الشتاء والصيف فأنشدته قول الأخطل\n(ترى الزجاج ولم يطمث يطيف به ... كأنه من دم الأجواف مختضب)\n(حتى إذا افتض ماء المزن عذرتها ... راح الزجاج وفي ألوانه صهب)\n(تنزو إذا شجها بالماء مازجها ... نزو الجنادب في رمضاء تلتهب)\n(راحوا وهم يحسبون الأرض في فلك ... إن صرعوا وقت الراحات والركب)\nقال لي أحسنت وأمر لي بما شرطه ووعدني به فأخذته","topic":"أخبار حماد الراوية ونسبه","topicNo":58,"sp":5,"spl":"حماد والخزيمي وبعض الغلمان","partial":1},
{"id":"b58-9","bab":"الجزء 6","sec":"مدح بلال بن أبي بردة","page":"ج6 ص97","text":"حدثني اليزيدي قال حدثني عمي عبيد الله قال حدثني سليمان بن أبي شيخ قال حدثني صالح بن سليمان قال قدم حماد الراوية على بلال بن أبي بردة البصرة وعند بلال ذو الرمة\nفأنشده حماد شعرا مدحه به فقال بلال لذي الرمة كيف ترى هذا الشعر قال جيدا وليس له قال فمن يقوله قال لا أدري لا أنه لم يقله فلما قضى بلال حوائج حماد وأجازه قال له إن لي إليك حاجة قال هي مقضية قال أنت قلت ذلك الشعر قال لا قال فمن يقوله قال بعض شعراء الجاهلية وهو شعر قديم وما يرويه غيري قال فمن أين علم ذو الرمة أنه ليس من قولك قال عرف كلام أهل الجاهلية من كلام أهل الإسلام قال صالح وأنشد حماد الراوية بلال بن أبي بردة ذات يوم قصيده قالها ونحلها الحطيئة يمدح أبا موسى الأشعري يقول فيها\n(جمعت من عامر فيها ومن جشم ... ومن تميم ومن حاء ومن حام)\n(مستحقبات رواياها جحافلها ... يسمو بها أشعري طرفه سامي)\nفقال له بلال قد علمت أن هذا شيء قلته أنت ونسبته إلى الحطيئة وإلا فهل كان يجوز أن يمدح الحطيئة أبا موسى بشيء لا أعرفه أنا ولا أرويه ولكن دعها تذهب في الناس وسيرها حتى تشتهر ووصله","topic":"أخبار حماد الراوية ونسبه","topicNo":58,"sp":6,"spl":"مدح بلال بن أبي بردة"},
{"id":"b58-10","bab":"الجزء 6","sec":"رأي المفضل الضبي بحماد","page":"ج6 ص98","text":"أخبرني محمد بن خلف وكيع قال سمعت أحمد بن الحارث الخراز يقول سمعت ابن الأعرابي يقول سمعت المفضل الضبي يقول\nقد سلط على الشعر من حماد الراوية ما أفسده فلا يصلح أبدا فقيل له وكيف ذلك أيخطىء في روايته أم يلحن قال ليته كان كذلك فإن أهل العلم يردون من أخطأ إلى الصواب لا ولكنه رجل عالم بلغات العرب وأشعارها ومذاهب الشعراء ومعانيهم فلا يزال يقول الشعر يشبه به مذهب رجل ويدخله في شعره ويحمل ذلك عنه في الآفاق فتختلط أشعار القدماء ولا يتميز الصحيح منها إلا عند عالم ناقد وأين ذلك أخبرني رضوان بن أحمد الصيدلاني قال حدثنا يوسف بن إبراهيم قال حدثني أبو إسحاق إبراهيم بن المهدي قال حدثني السعيدي الراوية وأبو إياد المؤدب وكان مؤدبي ثم أدب المعتصم بعد ذلك وقد تعالت سنه وحدثني بنحو من ذلك عبد الله بن مالك وسعيد بن سلم وحدثني به ابن غزالة أيضا واتفقوا عليه أنهم كانوا في دار أمير المؤمنين المهدي بعيساباذ وقد اجتمع فيها عدة من الرواة والعلماء بأيام العرب وآدابها وأشعارها ولغاتها إذ خرج بعض أصحاب الحاجب فدعا المفضل الضبي الراوية فدخل فمكث مليا ثم خرج إلينا ومعه حماد والمفضل جميعا وقد بان في وجه حماد الإنكسار والغم وفي وجه المفضل\nالسرور والنشاط ثم خرج حسين الخادم معهما فقال يا معشر من حضر من أهل العلم إن أمير المؤمنين يعلمكم أنه قد وصل حمادا الشاعر بعشرين ألف درهم لجودة شعره وأبطل روايته لزيادته في أشعار الناس ما ليس منها ووصل المفضل بخمسين ألفا لصدقه وصحة روايته فمن أراد أن يسمع شعرا جيدا محدثا فليسمع من حماد ومن أراد رواية صحيحة فليأخذها عن المفضل فسألنا عن السبب فأخبرنا أن المهدي قال للمفضل لما دعا به وحده إني رأيت زهير بن أبي سلمى افتتح قصيدته بأن قال\n(دع ذا وعد القول في هرم ... )\nلم يتقدم له قبل ذلك قول فما الذي أمر نفسه بتركه فقال له المفضل ما سمعت يا أمير المؤمنين في هذا شيئا إلا أني توهمته كان يفكر في قول يقوله أو يروي في أن يقول شعرا فعدل عنه إلى مدح هرم وقال دع ذا أو كان مفكرا في شيء من شأنه فتركه وقال دع ذا أي دع ما أنت فيه من الفكر وعد القول في هرم فأمسك عنه ثم دعا بحماد فسأله عن مثل ما سأل عنه المفضل فقال ليس هكذا قال زهير يا أمير المؤمنين قال فكيف قال فأنشده\n(لمن الديار بقنة الحجر ... أقوين مذحجج ومذ دهر)\n(قفر بمندفع النحائت من ... ضفوى أولات الضال والسدر)\n(دع ذا وعد القول في هرم ... خير الكهول وسيد الحضر)\nقال فأطرق المهدي ساعة ثم أقبل على حماد فقال له قد بلغ أمير المؤمنين عنك خبر لا بد من استحلافك عليه ثم أستحلفه بأيمان البيعة وكل يمين محرجة\nليصدقنه عن كل ما يسأله عنه فحلف له بما توثق منه قال له اصدقني عن حال هذه الأبيات ومن أضافها إلى زهير فأقر له حينئذ أنه قائلها فأمر فيه وفي المفضل بما أمر به من شهرة أمرهما وكشفه أخبرني الحسين بن القاسم الكوكبي قال حدثنا أحمد بن عبيد قال حدثنا الأصمعي قال قال حماد الراوية أرسل إلي أمير الكوفة فقال لي قد أتاني كتاب أمير المؤمنين الوليد بن يزيد يأمرني بحملك فجملت فقدمت عليه وهو في الصيد فلما رجع أذن لي فدخلت علي وهو في بيت منجد بالأرمني أرضه وحيطانه فقال لي أنت حماد الراوية فقلت له إن الناس ليقولون ذلك قال فما بلغ من روايتك قلت أروي سبعمائة قصيدة أول كل واحدة منها بانت سعاد فقال إنها لرواية ثم دعا بشراب فأتته جارية بكأس وإبريق فصبت في الكأس ثم مزجته حتى رأيت له حبابا فقال أنشدني في مثل هذه فقلت يا أمير المؤمنين هي كما قال عدي بن زيد\n(بكر العاذلون في وضح الصبح ... يقولون لي ألا تستفيق)\n(ثم ثاروا إلى الصبوح فقامت ... قينة في يمينها إبريق)\n(قدمته على سلاف كريح المسك ... صفى سلافها الراووق)\n(فترى فوقها فقاقيع كالياقوت ... يجري خلالها التصفيق)\nال فشربها ولم يزل يستعيدني الأبيات ويشرب عليها حتى سكر ثم قام فتناول مرفقة من تلك المرافق فجعلها على رأسه ونادى من يشتري لحوم البقر ثم قال لي يا حماد دونك ما في البيت فهو لك فكان أول مال تأثلته حدثني هاشم بن محمد الخزاعي قال حدثنا دماذ عن أبي عبيدة قال","topic":"أخبار حماد الراوية ونسبه","topicNo":58,"sp":7,"spl":"رأي المفضل الضبي بحماد","partial":1},
{"id":"b58-11","bab":"الجزء 6","sec":"رأي المفضل الضبي بحماد","page":"ج6 ص98","text":"قال خلف كنت آخذ من حماد الراوية الصحيح من أشعار العرب وأعطيه المنحول فيقبل ذلك مني ويدخله في أشعارها وكان فيه حمق أخبرني محمد بن خلف بن المرزبان قال حدثنا أحمد بن الهيثم بن فراس قال حدثني العمري عن الهيثم بن عدي قال حدثني المسور الغنزي وكان من رواة العرب وكان أسن من سماك بن حرب عن حماد قال دخلت على زياد فقال لي أنشدني فقلت من شعر من أيها الأمير قال من شعر الأعشى فأنشدته\n(بكرت سمية غدوة أجمالها ... )\nقال فما أتمتت القصيدة حتى تبينت الغضب في وجهه وقال الحاجب للناس ارتفعوا فقاموا ثم لم أعد والله إليه قال حماد فكنت بعد ذلك إذا استنشدني خليفة أو أمير تنبهت قبل أن أنشده لئلا يكون في القصيدة اسم أم له أو ابنة أو أخت أو زوجة","topic":"أخبار حماد الراوية ونسبه","topicNo":58,"sp":8,"spl":"رأي المفضل الضبي بحماد — الوليد يسأله سبب تسميته بالراوية","partial":1},
{"id":"b58-12","bab":"الجزء 6","sec":"الوليد يسأله سبب تسميته بالراوية","page":"ج6 ص102","text":"أخبرني محمد بن خلف بن المرزبان قال حدثنا أحمد بن الحارث الخراز عن المدائني قال قال الوليد بن يزيد لحماد الراوية لم سميت الراوية وما بلغ من حفظك حتى استحققت هذا الإسم فقال له يا أمير المؤمنين إن كلام العرب يجري على ثمانية وعشرين حرفا أنا أنشدك على كل حرف منها مائة قصيدة فقال إن هذا لحفظ هات فاندفع ينشد حتى مل الوليد ثم استخلف على الإستماع منه خليفة حتى وفاه ما قال فأحسن الوليد صلته وصرفه أخبرني الحرمي بن أبي العلاء قال حدثني الحسين بن محمد بن أبي طالب الديناري قال حدثني إسحاق الموصلي قال\nقال حماد الراوية أرسل الوليد بن يزيد إلي بمائتي دينار وأمر يوسف بن عمر بحملي إليه على البريد قال فقلت لا يسألني إلا عن طرفيه قريش وثقيف فنظرت في كتابي قريش وثقيف فلما قدمت عليه سألني عن أشعار بلي فأنشدته منها ما استحسنه ثم قال أنشدني في الشراب وعنده وجوه من أهل الشام فأنشدته\n(إصبح القوم قهوة ... في أباريق تحتذى)\n(من كميت مدامة ... حبذا تلك حبذا)\n(يترك الأذن شربها ... أرجوانا بها خذا)\nقال أعدها فأعدتها فقال لخدمه خذوا آذان القوم فأتينا بالشراب فسقينا حتى ما درينا متى نقلنا قال ثم حملنا وطرحنا في دار الضيفان فما أيقظنا إلا حر الشمس وجعل شيخ من أهل الشأم يشتمني ويقول فعل الله بك وفعل أنت الذي صنعت بنا هذا أخبرني هاشم بن محمد الخزاعي قال حدثنا أبو غسان دماذ قال حدثني أبو عبيدة قال حدثني يحيى بن صبيرة بن الطرماح بن حكيم عن أبيه عن جده الطرماح قال أنشدت حمادا الراوية في مسجد الكوفة وكان أذكى الناس وأحفظهم قولي\n(بان الخليط بسحرة فتبددوا ... )\nوهي ستون بيتا فسكت ساعة ولا أدري ما يريد ثم أقبل علي فقال أهذه لك\nقلت نعم قال ليس الأمر كما تقول ثم ردها علي كلها وزيادة عشرين بيتا زادها فيها في وقته فقلت له ويحك إن هذا الشعر قلته منذ أيام ما اطلع عليه أحد قال قد والله قلت أنا هذا الشعر منذ عشرين سنة وإلا فعلي وعلي فقلت لله علي حجة حافيا راجلا إن جالستك بعد هذا أبدا فأخذ قبضة من حصى المسجد وقال لله علي بكل حصاة من هذا الحصى مائة حجة إن كنت أبالي فقلت أنت رجل ماجن والكلام معك ضائع ثم انصرفت قال دماذ وكان أبو عبيدة والأصمعي ينشدان بيتي الطرماح في هذه القصيدة وهما\n(مجتاب حلة برجد لسراته ... قددا وأخلف ما سراه البرجد)\n(يبدو وتضمره البلاد كأنه ... سيف على شرف يسل ويغمد)\nكانا يقولان هذا أشعر الناس في هذين البيتين","topic":"أخبار حماد الراوية ونسبه","topicNo":58,"sp":8,"spl":"رأي المفضل الضبي بحماد — الوليد يسأله سبب تسميته بالراوية","partial":1},
{"id":"b59-1","bab":"الجزء 6","sec":"أخبار عبادل ونسبه","page":"ج6 ص105","text":"عبادل بن عطية مولى قريش مكي مغن محسن متقدم من الطبقة الثانية التي منها يونس الكاتب وسياط ودحمان وكان حسن الوجه نظيف الثياب ظريفا ولم يفارق الحجاز ولا وفد إلى ملوك بني أمية كما وفد غيره من طبقته ومن هو فوقها ويقال إنه كان مقبول الشهادة أخبرني الحسن بن علي قال حدثني هارون بن محمد بن عبد الملك قال حدثنا حماد عن ابن أبي جناح قال كان عبادل بن عطية سريا نبيلا نظيفا ساكن الطرف حسن العشرة وكان يعاشر مشيخة قريش وجلة أحداثها فإذا أرادوا الغناء منه غنى فأحسن وأطرب وكانت له صنعة كثيرة منها\n(نقول يا عمتا كفي جوانبه ... ويلي بليت وأبلى جيدي الشعر)\nمنها\n(أمن حذر البين ما ترقد ... ودمعك يجري فيما يجمد)\nمنها\n(إني أستحيتك أن أفوه بحاجتي ... فإذا قرأت صحيفتي فتفهم)\nمنها\n(قولا لنائل ما تقضين في رجل ... يهوى هواك وما جنبته اجتنبا)\nومنها\n(علام ترين اليوم قتلى لديكم ... حلالا بلا ذنب وقتلي محرم)\nقال وكانوا يقولون له ألا تكثر الصنعة فيقول بأبي أنتم إنما أنحته من صخر ومن أكثر أرذل","topic":"أخبار عبادل ونسبه","topicNo":59,"sp":0,"spl":"أخبار عبادل ونسبه — نسبة هذه الأصوات"},
{"id":"b59-2","bab":"الجزء 6","sec":"نسبة هذه الأصوات","page":"ج6 ص106","text":"صوت\n(أمن حذر البين ما ترقد ... ودمعك يجري فما يجمد)\n(دعاني إلى الحين فاقتادني ... فؤاد إلى شقوتي يعمد)\n(فلو أن قلبي صحا وارعوى ... لكان له عنكم مقعد)\n(يبيد الزمان وحبي لكم ... يزيد خبالا وما ينفد)\nلغناء لعبادل ثقيل أول بالسبابة والوسطى عن ابن المكي وفيه لإبراهيم خفيف ثقيل ومنها صوت\n(إني أستحيتك أن أفوه بحاجتي ... فإذا قرأت صحيفتي فتفهم)\n(وعليك عهد الله إن أنبأته ... أهل السيالة إن فعلت وإن لم)\nكذا قال ابن هرمة والمغنون يغنونه\n(وعليك عهد الله إن أخبرته ... أحدا وإن أظهرته بتكلم)\nلشعر لأبن هرمة والغناء لعبادل","topic":"أخبار عبادل ونسبه","topicNo":59,"sp":0,"spl":"أخبار عبادل ونسبه — نسبة هذه الأصوات"},
{"id":"b59-3","bab":"الجزء 6","sec":"الوشاية به","page":"ج6 ص107","text":"أخبرني عمي قال حدثني هارون بن محمد بن عبد الملك قال حدثني عبد الله بن محمد بن إسماعيل الجعفري عن أبيه أن حسن بن حسن بن علي كان صاحب شراب وفيه يقول ابن هرمة\n(إني استحيتك أن أفوه بحاجتي ... فإذا قرأت صحيفتي فتفهم)\n(وعليك عهد الله إن أنبأته ... أحدا ولا أظهرته بتكلم)\nال عبد الله بن محمد الجعفري وكان ابن هرمة كما حدثني أبي يشرب هو وأصحاب له بشرف السيالة عند سمرة بالشرف يقال لها سمرة جرانة فنفد شرابهم فكتب إلى حسن بن حسن بن علي يطلب منه نبيذا وكتب إليه بهذين البيتين فلما قرأ حسن رقعته قال وأنا علي عهد الله إن لم أخبر به عامل السيالة أمني يطلب الدعي الفاعل نبيذا وكتب إلى عامل السيالة أن يجيء إليه فجاء لوقته فقال له إن ابن هرمة وأصحابه السفهاء يشربون عند سمرة جرانة فاخرج فخدهم فخرج إليه العامل بأهل السيالة وأنذر بهم ابن هرمة فسبقهم هربا وتعلق هو وأصحابه بالجبل ففاتوهم وقال في حسن\n(كتبت إليك أستهدي نبيذا ... وأدلي بالجوار وبالحقوق)\n(فخبرت الأمير بذاك غدرا ... وكنت أخا مفاضحة وموق)\nومنها صوت\n(علام ترين اليوم قتلي لديكم ... حلالا بلا ذنب وقتلي محرم)\n(لك النفس ما عاشت وقاء من الردى ... ونحن لكم فيما تجنب أظلم)\nأما صنعته في\n(قولا لنائل ما تقضين في رجل ... )\nفإن الشعر لمسعدة بن البختري ابن أخي المهلب بن أبي صفرة والغناء لعبادل وقد ذكرت ذلك في موضع من هذا الكتاب مفرد لأن نائلة التي عنيت بهذا الشعر هي بنت الميلاء ولها أخبار ذكرت في موضع منفرد صلحت له ومنها صوت\n(تقول يا عمتا كفي جوانبه ... ويلي بليت وأبلى جيدي الشعر)\n(مثل الأساود قد أعيا مواشطه ... تضل فيه مداريها وتنكسر)\n(فإن نشرت على عمد ذوائبها ... أبصرت منه فتيت المسك ينتشر)\nلشعر لعمر بن أبي ربيعة والغناء لعبادل ثقيل أول بالسبابة في مجرى البنصر عن إسحاق وفيه خفيف ثقيل أول بالسبابة في مجرى البنصر عن إسحاق وفيه خفيف ثقيل ينسب إلى دحمان وإلى الغريض وإلى عبادل أيضا\nصوت من المائة المختارة\n(ليست نعم منك للعافين مسجلة ... من التخلق لكن شيمة خلق)\n(يكاد بابك من علم بصاحبه ... من دون بوابه للناس يندلق)\nإسحاق في هذين البيتين لحن من الثقيل الأول بالبنصر عن عمرو وذكر يحيى ابن علي بن يحيى عن أبيه عن إسحاق أن الشعر لطريح وذكر يعقوب بن السكيت أنه لإبن هرمة والغناء في اللحن المختار لشهية مولاة العبلات خفيف رمل بالبنصر في مجراها فمن روى هذه الأبيات لإبن هرمة ذكر أنها من قصيدة له يمدح بها عبد الواحد بن سلمان بن عبد الملك ومن ذكر أنها لطريح ذكر أنها من قصيدة له يمدح بها الوليد بن يزيد والصحيح من القولين أن البيت الأول من البيتين لطريح والثاني لإبن هرمة فبيت طريح من قصيدته التي مدح بها الوليد بن يزيد وهي طويلة يقول في تشبيهها\n(تقول والعيس قد شدت بأرحلها ... ألحق أنك منا اليوم منطلق)\n(قلت نعم فاكظمي قالت وما جلدي ... ولا أظن اجتماعا حين نفترق)\n(فقلت إن أحيى لا أطول بعادكم ... وكيف والقلب رهن عندكم غلق)\n(فارقتها لا فؤادي من تذكرها ... سالي الهموم ولا حبلي لها خلق)\n(فاضت على إثرهم عيناك دمعهما ... كما تتابع يجري اللؤلؤ النسق)\nصوت\n(فاستبق عينك لا يودي البكاء بها ... واكفف بوادر دمع منك تستبق)\n(ليس الشؤون وإن جادت بباقية ... ولا الجفون على هذا ولا الحدق)\nإسحاق في هذين البيتين لحن من الثقيل الأول بالبنصر عن عمرو يقول فيها في مدح الوليد\n(وما نعم منك للعافين مسجلة ... من التخلق لكن شيمة خلق)\n(ساهمت فيها وفي لا فاختصصت بها ... وطار قوم بلا والذم فانطلقوا)\n(قوم هم شرف الدنيا وسوددها ... صفو على الناس لم يخلط بهم رنق)\n(إن حاربوا وضعوا أو سالموا رفعوا ... أو عاقدوا ضمنوا أو حدثوا صدقوا)\nأما قصيدة إبراهيم بن هرمة التي فيها هذا الشعر فنذكر خبرها ثم نذكر موضع الغناء وما قبله وما بعده منها ومن أبي أحمد رحمه الله سمعنا ذلك أجمع ولكنه حكى عن إسحاق في الأصوات المختارة ما قاله إسحاق ولعله لم يتفقد ذلك أو لعل أحد الشاعرين أغار على هذا البيت فانتحله وسرقه من قائله","topic":"أخبار عبادل ونسبه","topicNo":59,"sp":1,"spl":"الوشاية به","partialRef":{"sid":"b59-1","gi":3,"vi":0,"side":0},"partial":1},
{"id":"b59-4","bab":"الجزء 6","sec":"مدح وتعريض","page":"ج6 ص110","text":"أخبرني يحيى بن علي قال أخبرنا حماد بن إسحاق عن أبيه عن رجل من أهل البصرة وحدثني به وكيع قال حدثنا هارون بن محمد بن عبد الملك عن حماد عن أبيه عن رجل من أهل البصرة وخبره أتم قال قال العباس بن الوليد بن عبد الملك وكان بخيلا لا يحب أن يعطي أحدا\nشيئا ما بال الشعراء تمدح أهل بيتي أجمع ولا تمدحني فبلغ ذلك ابن هرمة وكان قد مدحه فلم يثبه فقال يعرض به ويمدح عبد الواحد بن سليمان\n(ومعجب بمديح الشعر يمنعه ... من المديح ثواب المدح والشفق)\n(يا آبي المدح من قول يحبره ... ذو نيقة في حواشي شعره أنق)\n(إنك والمدح كالعذراء يعجبها ... مس الرجال ويثنى قلبها الفرق)\n(لكن بمدين من مفضى سويمرة ... من لا يذم ولا يشنا له خلق)\n(أهل المدائح تأتيه فتمدحه ... والمادحون إذا قالوا له صدقوا)\nعني عبد الواحد بن سليمان\n(لا يستقر ولا تخفى علامته ... إذا القنا شال في أطرافها الحرق)\n(في يوم لا مال عند المرء ينفعه ... إلا السنان وإلا الرمح والدرق)\n(يطعن بالرمح أحيانا ويضربهم ... بالسيف ثم يدانيهم فيعتنق)\nهذا البيت سرقه ابن هرمة من زهير ومن مهلهل جميعا فإنهما سبقا إليه قال مهلهل وهو أقدمهما\n(أنبضوا معجس القسي وأبرقنا ... كما توعد الفحول الفحولا)\nعني أنهم لما أخذوا القسي ليرموهم من بعيد انتضوا سيوفهم ليخالطوهم ويكافحوهم بها وقال زهير وهو أشرح من الأول\n(يطعنهم ما ارتموا حتى إذا اطعنوا ... ضارب حتى إذا ما ضاربوا اعتنقا)\nفما ترك في المعنى فضلا لغيره","topic":"أخبار عبادل ونسبه","topicNo":59,"sp":2,"spl":"مدح وتعريض"},
{"id":"b59-5","bab":"الجزء 6","sec":"رجع إلى شعر ابن هرمة","page":"ج6 ص112","text":"(يكاد بابك من وجود ومن كرم ... من دون بوابه للناس يندلق)\nيروى إذا أطاف به الجادون والعافون أيضا ويروى ينبلق\n(إني لأطوي رجالا أن أزورهم ... وفيهم عكر الأنعام والورق)\n(طي الثياب التي لو كشفت وجدت ... فيها المعاوز في التفتيش والخرق)\n(وأترك الثوب يوما وهو ذو سعة ... وألبس الثوب وهو الضيق الخلق)\n(إكرام نفسي وأني لا يوافقني ... ولو ظمئت فحمت المشرب الرنق)\nقال هارون بن الزيات في خبره فلما قال ابن هرمة هذه القصيدة أنشدها عبد الواحد بن سليمان وهو إذ ذاك أمير الحجاز فأمر له بثلثمائة دينار وخلعة موشية\nمن ثيابه وحمله على فرس وأعطاه ثلاثين لقحة ومائة شاة وسأله عما يكفيه في كل سنة ويكفي عياله من البر والتمر فأخبره به فأمر له بذلك أجمع لسنة وقال له هذا لك علي ما دمت ودمت في الدنيا واقتطعه لنفسه وأنس به وقال له لست بمحوجك إلى غيري أبدا فلما عزل عبد الواحد بن سليمان عن المدينة تصدى للوالي مكانه وامتدحه ولم يلبث أن ولي عبد الواحد بعد ذلك وبلغه الخبر فأمر أن يحجب عنه ابن هرمة وطرده وجفاه حتى تحمل عليه بعبد الله بن الحسن بن الحسن فاستوهبه منه فعاد له إلى ما أحبه أخبرني هاشم بن محمد الخزاعي قال حدثنا الراياشي وأخبرني به علي بن سليمان الأخفش عن أحمد بن يحيى ثعلب عن الرياشي وخبره أتم قال الرياشي حدثني أبو سلمة الغفاري قال قال ابن ربيح راوية ابن هرمة قال حدثني ابن هرمة قال أول من رفعني في الشعر عبد الواحد بن سليمان بن عبد الملك فأخذ علي ألا أمدح أحدا غيره وكان واليا على المدينة وكان لا يدع بري وصلتي والقيام بمؤونتي فلم ينشب أن عزل وولي غيره مكانه وكان الوالي من بني الحارث بن كعب فدعتني نفسي إلى مدحه طمعا أن يهب لي كما كان عبد الواحد يهب لي فمدحته فلم يصنع بي ما ظننت ثم قدم عبد الواحد المدينة فأخبر أني مدحت الذي عزل به فأمر بي فحجبت عنه ورمت الدخول عليه فمنعت فلم أدع بالمدينة وجها ولا رجلا له نباهة وقدر من قريش إلا سألته أن يشفع لي في أن يعيدني إلى منزلتي عنده فيأبى ذلك فلا يفعله فلما أعوزتني الحيل أتيت عبد الله بن الحسن بن الحسن بن علي بن أبي طالب صلوات الله عليه وعليهم فقلت يابن رسول الله إن هذا الرجل قد كان يكرمني وأخذ علي\nألا أمدح غيره فأعطيته بذلك عهدا ثم دعاني الشره والكد إلى أن مدحت الوالي بعده وقصصت عليه قصتي وسألته أن يشفع لي فركب معي فأخبرني الواقف على رأس عبد الواحد أن عبد الله بن حسن لما دخل إليه قام عبد الواحد فعانقه وأجلسه إلى جنبه ثم قال أحاجة غدت بك أصلحك الله قال نعم قال كل حاجة لك مقضية إلا ابن هرمة فقال له إن رأيت ألا تستثني في حاجتي فافعل قال قد فعلت قال فحاجتي ابن هرمة قال قد رضيت عنه وأعدته إلى منزلته قال فتأذن له أن ينشدك قال تعفيني من هذه قال أسألك أن تفعل قال ائتوا به فدخلت عليه وأنشدته قولي فيه\n(وجدنا غالبا كانت جناحا ... وكان أبوك قادمة الجناح)\nال فغضب عبد الله بن الحسن حتى انقطع رزه ثم وثب مغضبا وتجوزت في الإنشاد ثم لحقته فقلت له جزاك الله يابن رسول الله فقال ولكن لا جزاك الله خيرا يا ماص بظر أمه وتقول لإبن مروان\n(وكان أبوك قادمة الجناح ... )\nحضرتي وأنا ابن رسول الله وابن علي بن أبي طالب عليه السلام فقلت جعلني الله فداك إني قلت قولا أخدعه به طلبا لدنياه ووالله ما قست بكم أحد قط أفلم تسمعني قد قلت فيها\n(وبعض القول يذهب بالرياح ... )\nضحك عبد الله وقال قاتلك الله ما أظرفك","topic":"أخبار عبادل ونسبه","topicNo":59,"sp":3,"spl":"رجع إلى شعر ابن هرمة","partial":1},
{"id":"b59-6","bab":"الجزء 6","sec":"حائية ابن هرمة","page":"ج6 ص114","text":"وهذه القصيدة الحائية التي مدح بها عبد الواحد من فاخر الشعر ونادر الكلام\nومن جيد شعر ابن هرمة خاصة وأولها\n(صرمت حبائلا من حب سلمى ... لهند ما عمدت لمستراح)\n(فإنك إن تقم لا تلق هندا ... وإن ترحل فقلبك غير صاحي)\n(يظل نهاره يهذي بهند ... ويأرق ليله حتى الصباح)\n(أعبد الواحد المحمود إني ... أغص حذار سخطك بالقراح)\n(فشلت راحتاي وجال مهري ... فألقاني بمشتجر الرماح)\n(وأقعدني الزمان فبت صفرا ... من المال المعزب والمراح)\n(إذا فخمت غيرك في ثنائي ... ونصحي في المغيبة وامتداحي)\n(كأن قصائدي لك فاصطنعني ... كرائم قد عضلن عن النكاح)\n(فإن أك قد هفوت إلى أمير ... فعن غير التطوع والسماح)\n(ولكن سقطة عيبت علينا ... وبعض القول يذهب في الرياح)\n(لعمرك إنيي وبني عدي ... ومن يهوى رشادي أو صلاحي)\n(إذا لم ترض عني أو تصلني ... لفي حين أعالجه متاح)\n(وإنك إن حططت إليك رحلي ... بغربي الشراة لذوا ارتياح)\n(هششت لحاجة ووعدت أخرى ... ولم تبخل بناجزة السراح)\n(وجدنا غالبا خلقت جناحا ... وكان أبوك قادمة الجناح)\n(إذا جعل البخيل البخل ترسا ... وكان سلاحه دون السلاح)\n(فإن سلاحك حتى ... تفوز بعرض ذي شيم صحاح)\nأخبرني أحمد بن عبيد الله بن عمار قال حدثنا يعقوب بن إسرائيل قال حدثني إبراهيم بن إسحاق العمري قال حدثني عبد الله بن إبراهيم الجمحي قال قلت لإبن هرمة أتمدح عبد الواحد بن سليمان بعشر ما مدحت به غيره فتقول فيه هذا البيت\n(وجدنا غالبا كانت جناحا ... وكان أبوك قادمة الجناح)\nم تقول فيها\n(أعبد الواحد الميمون إني ... أغص حذار سخطك بالقراح)\nبأي شيء استوجب ذلك منك فقال إني أخبرك بالقصة لتعذرني أصابتني أزمة بالمدينة فاسنهضتني بنت عمي للخروج فقلت لها ويحك إنه ليس عندي ما يقل جناحي فقالت أنا أنهضك بما أمكنني وكانت عندي ناب لي فنهضت عليها نهجد النوام ونؤذي السمار وليس من منزل أنزله إلا قال الناس ابن هرمة حتى دفعت إلى دمشق فأويت إلى مسجد عبد الواحد في جوف الليل فجلست فيه أنتظره إلى أن نظرت الفجر بزوغ الفجر فإذا الباب ينفلق عن رجل كأنه البدر فدنا فأذن ثم صلى ركعتين وتأملته فإذا هو عبد الواحد فقمت فدنوت منه وسلمت عليه فقال لي أبو إسحاق أهلا ومرحبا فقلت لبيك بأبي أنت وأمي وحياك الله بالسلام وقربك من رضوانه فقال أما آن لك أن تزورنا فقد طال العهد واشتد الشوق فما رواءك قلت لا تسلني بأبي أنت وأمي فإن الدهر قد أخنى علي فما وجدت مستغاثا غيرك فقال لا ترع فقد وردت على ما تحب إن\nشاء الله فوالله لإني لأخاطبه فإذا بثلاثة فتية قد خرجوا كأنهم الأشطان فسلموا عليه فاستدنى الأكبر منهم فهمس إليه بشىء دوني ودون أخويه فمضى إلى البيت ثم رجع فجلس إليه فكلمه بشىء دوني ثم ولى فلم يلبث أن خرج ومعه عبد ضابط يحمل عبئا من الثياب حتى ضرب به بين يدي ثم همس إليه ثانية فعاد وإذا به قد رجع ومعه مثل ذلك فضرب به بين يدي فقال لي عبد الواحد ادن يا أبا إسحاق فإني أعلم أنك لم تصر إلينا حتى تفاقم صدعك فخذ هذا وارجع إلى عيالك فوالله ماسللنا لك هذا إلا من أشداق عيالنا ودفع إلي ألف دينار وقال لي قم فارحل فأغث من وراءك فقمت إلى الباب فلما نظرت إلى ناقتي ضقت فقال لي تعال ما أرى هذه مبلغتك يا غلام قدم له جملي فلانا فوالله لقد كنت بالجمل أشد سرورا مني بكل ما نلته فهل تلومني أن أغص حذار سخط هذا بالقراح والله ما أنشدته ليلتئذ بيتا واحدا","topic":"أخبار عبادل ونسبه","topicNo":59,"sp":4,"spl":"حائية ابن هرمة"},
{"id":"b59-7","bab":"الجزء 6","sec":"شعره في مدح المنصور","page":"ج6 ص117","text":"أخبرني محمد بن خلف وكيع قال حدثني هارون بن محمد بن عبد الملك الزيات قال حدثني محمد بن عمر الجرجاني قال حدثني عثمان بن حفص الثقفي قال حدثني محمد بن جعفر بن محمد بن علي بن الحسين صلى الله عليه قال دخلت مع أبي علي على المنصور بالمدينة وهو جالس في دار مروان فلما أجتمع الناس قام ابن هرمة فقال يا أمير المؤمنين جعلني الله فداءك شاعرك\nوصنيعتك إن رأيت أن تأذن لي في الإنشاد قال هات فأنشده قوله\n(سرى ثوبه عنك الصبا المتخايل ... )\nتى انتهى إلى قوله\n(له لحظات عن خفافي سريره ... إذا كرها فيها عقاب ونائل)\n(فأم الذي آمنت آمنة الردى ... وأم الذي خوفت بالثكل ثاكل)\nقال له المنصور أما لقد رأيتك في هذه الدار قائما بين يدي عبد الواحد بن سليمان تنشده قولك فيه\n(وجدنا غالبا كانت جناحا ... وكان أبوك قادمة الجناح)\nال فقطع بإبن هرمة حتى ما قدر على الإعتذار فقال له المنصور أنت رجل شاعر طالب خير وكل ذلك يقول الشاعر وقد أمر لك أمير المؤمنين بثلثمائة دينار فقام إليه الحسن بن زيد فقال يا أمير المؤمنين إن ابن هرمة رجل منفاق متلاف لا يليق شيئا فإن رأى أمير المؤمنين أن يأمر له بها يجرى عليه منها ما يكفيه ويكفي عياله ويكتب بذلك إلى أصحاب الجاري أن يرجيها عليهم فعل فقال افعلوا ذلك به قال وإنما فعل به الحسن بن زيد هذا لأنه كان مغضبا عليه لقوله يمدح عبد الله بن حسن\n(ما غيرت وجهه أم مهجنة ... إذا القتام تغشى أوجه الهجن)\nدثني يحيى بن علي بن يحيى وأخبرنا ابن أبي الأزهر وجحظة قالا حدثنا حماد بن إسحاق عن أبيه قال يحيى بن علي في خبره عن الفضل بن يحيى ولم يقله الآخران\nدخل ابن هرمة على المنصور وقال يا أمير المؤمنين إني قد مدحتك مديحا لم يمدح أحد أحدا بمثله قال وما عسى أن تقول في بعد قول كعب الأشقري في المهلب\n(براك الله حين براك بحرا ... وفجر منك أنهارا غزارا)\nقال له قد قلت أحسن من هذا قال هات فأنشده قوله\n(له لحظات عن حفافي سريره ... إذا كرها فيها عقاب ونائل)\nال فأمر له بأربعة آلاف درهم فقال له المهدي يا أمير المؤمنين قد تكلف في سفره إليك نحوها فقال له المنصور يا بني إني قد وهبت له ما هو أعظم من ذلك وهبت له نفسه أليس هو القائل لعبد الواحد بن سليمان\n(إذا قيل من خير من يرتجى ... لمعتر فهر ومحتاجها)\n(ومن يعجل الخيل يوم الوغى ... بإلجامها قبل إسراجها)\n(أشارت نساء بني غالب ... إليك به قبل ازواجها)\nهذه القصيدة من فاخر شعر ابن هرمة وأولها\n(أجارتنا روحي نعمة ... على هائم النفس مهتاجها)\n(ولا خير في ود مستكره ... ولا حاجة دون إنضاجها)\nقول فيها يمدح عبد الواحد بن سليمان\n(كأن قتودي على خاضب ... زفوف العشيات هداجها)\n(إلى ملك لا إلى سوقة ... كسته الملوك ذرا تاجها)\n(تحل الوفود بأبوابه ... فتلقى الغنى قبل إرتاجها)\n(بقراع أبواب دور الملوك ... عند التحية ولاجها)\n(إلى دار ذي حسب ماجد ... حمول المغارم فراجها)\n(ركود الجفان غداة الصبا ... ويوم الشمال وإرهاجها)\n(وقفت بمدحيه عند الجمار ... أنشده بين حجاجها)\nخبرني محمد بن جعفر النحوي صهر المبرد قال حدثني أبو إسحاق طلحة ابن عبد الله الطلحي قال حدثني محمد بن سليمان بن المنصور قال وجه المنصور رسولا قاصدا إلى ابن هرمة ودفع إليه ألف دينار وخلعة ووصفه له وقال امض إليه فإنك تراه جالسا في موضع كذا في المسجد فانتسب له إلى بني أمية أو مواليهم وسله أن ينشدك قصيدته الحائية التي يقول فيها يمدح عبد الواحد بن سليمان\n(وجدنا غالبا كانت جناحا ... وكان أبوك قادمة الجناح)\nفإذا أنشدكها فأخرجه من المسجد واضرب عنقه وجئني برأسه وإن أنشدك قصيدته اللامية التي يمدحني بها فادفع إليه الألف الدينار والخلعة وما أراه ينشدك غيرها ولا يعترف بالحائية قال فأتاه الرسول فوجده كما قال المنصور فجلس إليه واستنشده قصيدته في عبد الواحد فقال ما قلت هذه القصيدة قط ولا أعرفها وإنما نحلها إياي من يعاديني ولكن إن شئت أنشدتك أحسن منها قال قد شئت فهات فأنشده\n(سرى ثوبه عنك الصبا المتخايل ... )","topic":"أخبار عبادل ونسبه","topicNo":59,"sp":5,"spl":"شعره في مدح المنصور","partial":1},
{"id":"b59-8","bab":"الجزء 6","sec":"شعره في مدح المنصور","page":"ج6 ص117","text":"تى أتى على آخرها ثم قال هات ما أمرك أمير المؤمنين بدفعه إلي فقال أي شيء تقول يا هذا وأي شيء دفع إلي فقال دع ذا عنك فوالله ما بعثك إلا أمير المؤمنين ومعك مال وكسوة لي وأمرك أن تسألني عن هذه القصيدة فإن أنشدتك إياها ضربت عنقي وحملت رأسي إليه وإن أنشدتك هذه اللامية دفعت إلي ما حملك إياه فضحك الرسول ثم قال صدقت لعمري ودفع إليه الألف الدينار والخلعة فما سمعنا بشيء أعجب من حديثهما أخبرني محمد بن مزيد قال حدثنا الزبير بن بكار قال حدثنا عمي عن جدي قال لما انشد ابن هرمة المنصور قصيدته اللامية التي مدحه بها أمر له بألف درهم فكلمه فيه المهدي واستقلها فقال يا بني لو رايت هذا بحيث رأيته وهو واقف بين يدي عبد الواحد بن سليمان ينشده\n(وجدنا غالبا كانت جناحا ... وكان أبوك قادمة الجناح)\nلاستكثرت له ما استقللته ولرأيت أن حياته بعد ذلك القول ربح كثير والله إني يا بني ما هممت له منذ يومئذ بخير فذكرت قوله إلا زال ما عرض بقلبي إلى ضده حتى أهم بقتله ثم أعفو عنه فأمسك المهدي","topic":"أخبار عبادل ونسبه","topicNo":59,"sp":6,"spl":"شعره في مدح المنصور — ما يغنى من شعره"},
{"id":"b59-9","bab":"الجزء 6","sec":"ما يغنى من شعره","page":"ج6 ص122","text":"ومما يغنى فيه من مدائح ابن هرمة في عبد الواحد بن سليمان قوله من قصيدة أنا ذاكرها بعد فراغي من ذكر الأبيات على أن المغنين قد خلطوا مع أبياته أبياتا لغيره صوت\n(ولما أن دنا منا ارتحال ... وقرب ناجيات السير كوم)\n(تحاسر واضحات اللون زهر ... على ديباج أوجهها النعيم)\n(أتين مودعات والمطايا ... لدى أكوارها حوض هجوم)\n(فكم من حرة بين المنقى ... إلى أحد إلى ما حاز ريم)\nيروى\n(فكم بين الأقارع فالمنقى ... )\nوهو أجود\n(إلى الجماء من خد أسيل ... نقي اللون لي به كلوم)\n(كأني من تذكر ما ألاقي ... إذا ما أظلم الليل البهيم)\n(سليم مل منه أقربوه ... وأسلمه المداوي والحميم)\nكر الزبير بن بكار أن هذا الشعر كله لأبي المنهال نفيلة الأشجعي قال وسمعت بعض أصحابنا يقول إنه لمعمر بن العنبر الهذلي والصحيح من القول أن بعض هذه الأبيات لإبن هرمة من قصيدة له يمدح بها عبد الواحد بن سليمان مخفوضة الميم ولما غني فيها وفي أبيات نفيلة وخلط فيه ما أوجب خفض القافية غير إلى ما أوجب رفعها فأما ما لإبن هرمة فيها فهو من قصيدته التي أولها\n(أجارتنا بذي نفر أقيمي ... فما أبكى على الدهر الذميم)\n(أقيمي وجه عامك ثم سيري ... بلا واهي الجوار ولا مليم)\n(فكم بين الأقارع فالمنقى ... إلى أحد إلى أكناف ريم)\n(إلى الجماء من خد أسيل ... نقي اللون ليس بذي كلوم)\n(ومن عين مكحلة الأماقي ... بلا كحل ومن كشح هضيم)\n(أرقت وغاب عني من يلوم ... ولكن لم أنم أنا للهموم)\n(أرقت وشفني وجع بقلبي ... لزينب أو أميمة أو رعوم)\n(أقاسي ليلة كالحول حتى ... تبدى الصبح منقطع البريم)\n(كأن الصبح أبلق في حجول ... يشب ويتقي ضرب الشكيم)\n(رأيت الشيب قد نزلت علينا ... روائعه بحجة مستقيم)\n(إذا ناكرته ناكرت منه ... خصومة لا ألد ولا ظلوم)\n(وودعني الشباب فصرت منه ... كراض بالصغير من العظيم)\n(فدع مالا يرد عليك شيئا ... من الجارات أو دمن الرسوم)\n(وقل قولا تطبق مفصليه ... بمدحه صاحب الرأي الصروم)\n(لعبد الواحد الفلج المعلى ... على خلق النفورة والخصوم)\n(دعته المكرمات فناولته ... خطام المجد في سن الفطيم)\nهي طويلة فمن الأبيات التي فيها الغناء أربعة أبيات لإبن هرمة قد مضت في هذه القصيدة وإنما غيرت حتى صارت مرفوعة فاتفقت الأبيات وغنى فيها وأما أبيات نفيلة فما بقي من الصوت المذكور بعد أبيات ابن هرمة له ويتلو ذلك من أبيات نفيلة قوله\n(يضيء دجى الظلام إذا تبدى ... كضوء الفجر منظره وسيم)\n(وقائلة ومثنية علينا ... تقول وما لها فينا حميم)\n(وأخرى لبها معنا ولكن ... تصبر وهي واجمة كظوم)\n(تعد لنا الليالي تحتصيها ... متى هو حائن منه قدوم)\n(متى تر غفلة الواشين عنها ... تجد بدموعها العين السجوم)\nالغناء في هذه الأبيات المذكورة المختلط فيها شعر ابن هرمة ونفيلة لمعبد ولحنه من الثقيل الأول بالوسطى عن عمرو ويونس وفيها لحن من الثقيل الثاني ينسب إلى الوابصي وفيها خفيف ثقيل ينسب إلى معبد وإلى ابن سريح","topic":"أخبار عبادل ونسبه","topicNo":59,"sp":6,"spl":"شعره في مدح المنصور — ما يغنى من شعره","partial":1},
{"id":"b59-10","bab":"الجزء 6","sec":"الوابصي وأخباره","page":"ج6 ص125","text":"وهذا الوابصي هو الصلت بن العاصي بن وابصة بن خالد بن المغيرة بن عبد الله ابن عمرو بن مخزوم كان تنصر ولحق ببلاد الروم لأن عمر بن عبد العزيز فيما ذكر حده في الخمر وهو أمير الحجاز فغضب فلحق ببلاد الروم وتنصر هناك ومات هنالك نصرانيا فأخبرنا محمد بن العباس اليزيدي قال حدثنا أحمد بن زهير قال حدثنا الزبير بن بكار قال حدثني عبد الله بن عبد العزيز قال أخبرني ابن العلاء أظنه أبا عمرو أو أخاه عن جويرية بن أسماء عن إسماعيل بن أبي حكيم وأخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثنا سعيد بن عامر عن جويرية بن أسماء بن أبي حكيم وقد جمعت الروايتين قال اليزيدي في خبره إن إسماعيل حدث أن عمر بن عبد العزيز بعث في الفداء وقال عمر بن شبة إن إسماعيل حدث قال كنت عند عمر بن عبد العزيز فأتاه البريد الذي جاء من القسطنطينية فحدثه قال بينا أنا أجول في القسطنطينية إذ سمعت رجلا يغني بلسان فصيح وصوت شج\n(فكم من حرة بين المنقى ... إلى أحد إلى جنبات ريم)\nسمعت غناء لم أسمع قط أحسن منه فلما سمعت الغناء وحسنه لم أدر أهو كذلك حسن أم لغربته وغربة العربية في ذلك الموضع فدنوت من الصوت فلما قربت منه إذا هو في غرفة فنزلت عن بغلتي فأوثقتها ثم صعدت إليه فقمت على باب الغرفة فغذا رجل مستلق على قفاه يغني هذين البيتين لا يزيد عليهما وهو واضع إحدى رجليه على الأخرى فإذا فرغ بكى فيبكي ما شاء الله ثم يعيد الغناء ففعل ذلك مرارا فقلت السلام عليكم فوثب ورد السلام فقلت أبشر فقد فك الله أسرك أنا بريد أمير المؤمنين عمر بن عبد العزيز إلى هذا الطاغية في فداء الأساري ثم سالته من أنت فقال أنا الوابصي أخذت فعذبت حتى دخلت في دينهم فقلت له أنت والله أحب من أفتديه إلى أمير المؤمنين وإلي إن لم تكن دخلت في الكفر فقال قد والله دخلت فيه فقلت أنشدك الله إلا أسلمت فقال أأسلم وهذان ابناي وقد تزوجت امرأة منهم وهذان ابناها وإذا دخلت المدينة قيل لي يا نصراني وقيل مثيل ذلك لولدي وأمهما لا والله لا أفعل فقلت له قد كنت قارئا للقرآن فما بقي معك منه قال لا شيء إلا هذه الآية ( ربما يود الذين كفروا لو كانوا مسلمين\nقال فعاودته وقلت له إنك لا تغير بهذا فقال وكيف بعبادة الصليب وشرب الخمر وأكل لحم الخنزير فقلت سبحان الله أما تقرأ ( إلا من أكره وقلبه مطمئن بالإيمان\nفجعل يعيد علي قوله فكيف بما فعلت ولم يجبني إلى الرجوع قال فرفع عمر يده وقال اللهم لا تمتني حتى تمكنني منه قال فوالله ما زلت راجيا لإجابة دعوة عمر فيه قال جويرية في حديثه وقد رأيت أخا الوابصي بالمدينة وقال يعقوب بن السكيت في هذا الخبر أخبرني ابن الأزرق عن رجل من أهل البصرة أنسيت اسمه قال\nنزلنا في ظل حصن من الحصون التي للروم فإذا أنا بقائل يقول من فوق الحصن\n(فكم بين الأقارع فالمنقى ... إلى أحد إلى ميقات ريم)\n(إلى الزوراء من ثغر تقي ... عوارضه ومن دل رخيم)\n(ومن عين مكحلة الأماقي ... بلا كحل ومن كشح هضيم)\nهو ينشد بلسان فصيح ويبكي فناديته أيها المنشد فأشرف فتى كأحسن الناس فقلت من الرجل وما قصتك فقال أنا رجل من الغزاة من العرب نزلت مكانك هذا فأشرفت علي جارية كأحسن الناس فعشقتها فكلمتها فقالت إن دخلت في ديني لم أخالفك فغلب علي الشيطان فدخلت في دينها فأنا كما ترى فقلت أكنت تقرأ القرآن فقال إي والله لقد حفظته قلت فما تحفظ منه اليوم قال لا شيء إلا قوله عز و جل ( ربما يود الذين كفروا لو كانوا مسلمين\nقلت فهل لك أن نعطيهم فداءك وتخرج قال ففكر ساعة ثم قال انطلق صحبك الله","topic":"أخبار عبادل ونسبه","topicNo":59,"sp":7,"spl":"الوابصي وأخباره — من المائة المختارة"},
{"id":"b59-11","bab":"الجزء 6","sec":"ومما في الأخبار من شعر ابن هرمة","page":"ج6 ص126","text":"صوت","topic":"أخبار عبادل ونسبه","topicNo":59,"sp":7,"spl":"الوابصي وأخباره — من المائة المختارة"},
{"id":"b59-12","bab":"الجزء 6","sec":"من المائة المختارة","page":"ج6 ص127","text":"(في حاضر لجب بالليل سامره ... في الصواهل والرايات والعكر)\n(وخرد كالمها حور مدامعها ... كأنها بين كثبان النقا البقر)\nلشعر لإبن هرمة والغناء في اللحن المختار لحنين ولحنه من الثقيل الأول بالخنصر في مجرى البنصر عن إسحاق قال إسحاق وفيه لأبي همهمة لحن من الثقيل الأول أيضا وأبو همهمة هذا مغن أسود من أهل المدينة ليس بمشهور ولا ممن نادم الخلفاء ولا وجدت له خبرا فأذكره صوت","topic":"أخبار عبادل ونسبه","topicNo":59,"sp":7,"spl":"الوابصي وأخباره — من المائة المختارة"},
{"id":"b59-13","bab":"الجزء 6","sec":"من المائة المختارة","page":"ج6 ص127","text":"(بزينب ألمم قبل أن يرحل الركب ... وقل إن تملينا فما ملك القلب)\n(وقل في تجنيها لك الذنب إنما ... عتابك من عاتبت فيما له عتب)\nلشعر لنصيب والغناء في اللحن المختار لكردم بن معبد ولحنه المختار من القدر الأوسط من الثقيل الأول بالخنصر في مجرى البنصر عن إسحاق وفيه لمعبد لحن آخر من خفيف الثقيل عن يونس والهشامي ودنانير وفيه لإبراهيم لحن آخر من الثقيل الأول ذكره الهشامي","topic":"أخبار عبادل ونسبه","topicNo":59,"sp":8,"spl":"من المائة المختارة — بعض أخبار لنصيب"},
{"id":"b59-14","bab":"الجزء 6","sec":"بعض أخبار لنصيب","page":"ج6 ص128","text":"وقد تقدم من أخبار نصيب ما فيه كفاية وإنما تأخر منها ما له موضع يصلح إفراده فيه مثل أخبار هذا الصوت\nأخبرني محمد بن العباس اليزيدي قال حدثنا عمي الفضل عن إسحاق بن إبراهيم الموصلي عن أبي كناسة قال قال نصيب ما توهمت أني أحسن أن أقول الشعر حتى قلت\n(بزينب ألمم قبل أن يرحل الركب ... )\nخبرنا الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثنا إبراهيم المنذر الحزامي عن محمد بن معن الغفاري قال أخبرني ابن الربيح قال مر بنا جميل ونحن بضرية فاجتمعنا إليه فسمعته يقول لأن أكون سبقت الأسود إلى قوله\n(بزينب ألمم قبل أن يرحل الركب ... )\nحب إلي من كذا وكذا لشيء قاله عظيم أخبرني الحرمي قال حدثني الزبير قال حدثني سعيد بن عمرو عن حبيب بن شوذب الأسدي قال مر بنا جرير بن الخطفي ونحن بضرية فاجتمعنا إليه فسمعته يقول لأن أكون سبقت العبد إلى هذا البيت أحب إلي من كذا وكذا يعني قوله\n(بزينب ألمم قبل أن يرحل الركب ... )\nخبرنا محمد بن العباس اليزيدي قال حدثني عمي الفضل عن إسحاق الموصلي عن ابن كناسة قال\nاجتمع الكميت بن زيد ونصيب في الحمام فقال له الكميت أنشدني قولك\n(بزينب ألمم قبل أن يرحل الركب ... )\nقال والله ما أحفظها فقال الكميت ينشده وهو يبكي أخبرني أحمد بن عبد العزيز الجوهري وحبيب بن نصر المهلبي قالا حدثنا عمر بن شبة قال ذكر ابن أبي الحويرث عن مولاة لهم وأخبرني الحسين بن يحيى عن حماد عن أبيه عن عثمان بن حفص عن مولاة لهم قالت إنا لبمنى إذ نظرت إلى أبنية مضروبة وأثاث وأمتعة فلم أدر لمن هي حتى أنيخ بعير فنزل عنه أسود وسوداء فألقيا أنفسهما على بعض المتاع ومر راكب يتغنى غناء الركبان\n(بزينب المم قبل أن يرحل الركب ... )\nرأيت السوداء تخبط الأسود وتقول له شهرتني وأذعت في الناس ذكري فإذا هو نصيب وزوجته قال إسحاق في خبره وكان الذي اجتاز بهم وتغنى ابن سريج أخبرني الحسين بن يحيى عن حماد عن أبيه عن محمد بن كناسة عن أبيه قال قال نصيب والله إني لأسير على راحلتي إذ أدركت نسوة ذوات جمال يتناشدن قولي\n(بزينب ألمم قبل أن يرحل الركب ... )\nوإذا معهن ابن سريج فقلن له يا أبا يحيى غننا في هذا الشعر فغناهن فأحسن فقلن وددنا والله يا أبا يحيى أن نصيبا معنا فيتم سرورنا فحركت\nبعيري لأتعرف بهن وأنشدهن فالتفت إحداهن إلي فقالت حين رأتني والله لقد زعموا أن نصيبا يشبه هذا الأسود لا جرم فقلت والله لا أتعرف بهن سائر اليوم ومضيت وتركتهن قال وكان الذي تغنى به ابن سريج من شعري\n(بزينب ألمم قبل أن يرحل الركب ... وقل إن تملينا فما ملك القلب)\n(وقل إن تنل بالحب منك مودة ... فما مثل ما لقيت من حبكم حب)\n(وقل في تجنيها لك الذنب إنما ... عتابك من عاتبت فيما له عتب)\n(فمن شاء رام الوصل أو قال ظالما ... لذي وده ذنب وليس له ذنب)\nخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني إبراهيم بن عبد الله السعدي عن جدته جمال بنت عون عن جدها قال قلت للنصيب أنشدني يا أبا محجن من شعرك شيئا فقال أيه تريد قلت ما شئت قال لا أنشدك أو تقترح ما تريد فقلت قولك\n(بزينب ألمم قبل أن يرحل الركب ... )\nال فتبسم وقال هذا شعر قلته وأنا غلام ثم أنشدني القصيدة قال الزبير وهي أجود ما قال","topic":"أخبار عبادل ونسبه","topicNo":59,"sp":8,"spl":"من المائة المختارة — بعض أخبار لنصيب","partialRef":{"sid":"b59-13","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b59-15","bab":"الجزء 6","sec":"توبة نصيب عن التشهير بالنساء","page":"ج6 ص131","text":"أخبرني أحمد بن عبد العزيز الجوهري وحبيب بن نصر المهلبي قالا حدثنا عمر بن شبة قال حدثنا المدائني عن أبي بكر الهذلي قال حدثني أيوب بن شاس\nونسخت هذا الخبر من كتاب أحمد بن الحارث الخراز عن المدائني عن أبي بكر الهذلي عن أيوب بن شاس وروايته أتم من رواية عمر بن شبة قال أيوب حدثني عبد الله بن سعيد أن النصيب دخل على عمر بن عبد العزيز لما ولي الخلافة فقال له هيه يا أسود\n(بزينب ألمم قبل أن يرحل الركب ... وقل إن تملينا فما ملك القلب)\nأأنت الذي تشهر بالنساء وتقول فيهن فقال يا أمير المؤمنين إني قد تركت ذلك وتبت من قول الشعر وكان قد نسك فأثنى عليه القوم وقالوا فيه قولا جميلا فقال له أما إذ أثنى عليك القوم فسل حاجتك فقال يا أمير المؤمنين لي بنيات سويداوات أرغب بهن عن السودان ويرغب عنهن البيضان فإن رأيت أن تفرض لهن فافعل ففعل أخبرني الحسن بن علي قال حدثنا عبد الله بن شبيب عن محمد بن المؤمل بن طالوت عن أبيه عن عثمان بن الضحاك الحزامي قال خرجت على بعير لي أريد الحج فنزلت في فناء خيمة بالأبواء فإذا جارية قد خرجت من الخيمة ففتحت الباب بيديها فآستلهاني حسنها فتمثلت قول نصيب\n(بزينب ألمم قبل أن يرحل الركب ... وقل إن تملينا فما ملك القلب)\nفقالت الجارية أتعرف قائل هذا الشعر قلت نعم ذاك نصيب قالت أفتعرف زينب هذه قلت لا قالت فأنا والله زينبه وهو اليوم الذي وعدني فيه الزيارة ولعلك لا ترحل حتى تراه فوقفت ساعة فإذا أنا براكب قد طلع فجاء حتى أناخ قريبا منها ثم نزل فسلم عليها وسلمت عليه فقلت عاشقان التقيا ولا بد أن يكون لهما حاجة فقمت إلى راحلتي فشددت عليها فقال على رسلك أنا معك فلبث ساعة ثم رحل ورحلت معه فقال لي كأنك قلت في نفسك كذا وكذا قلت قد كان ذاك فقال لا ورب الكعبة البنية المستورة ما جلست معها مجلسا قط هو أقرب من هذا حدثني الحسن بن علي قال حدثنا هارون بن محمد بن عبد الملك قال حدثني حماد بن إسحاق قال قال لي أبو ربيعة لو لم تكن هذه القصيدة\n(بزينب المم قبل أن يرحل الركب ... )\nلنصيب شعر من كانت تشبه فقلت شعر إمرئ القيس لأنها جزلة الكلام جيدة قال سبحان الله قلت ما شأنك فقال سألت أباك عن هذا فقال لي مثل ما قلت فعجبت من اتفاقكما قال هارون وحدثني حماد عن أبيه عن عثمان بن حفص الثقفي عن رجل سماه قال أتاني منقذ الهلالي ليلة وضرب علي الباب فقلت من هذا فقال منقذ الهلالي فخرجت فزعا فقلت فيم السرى أي ما جاء بك تسري إلي ليلا في هذه الساعة قال خير أتاني أهلي بدجاجة مشوية بين رغيفين فتغذيت بها معهم ثم أتيت بقنينة نبيذ قد ألتقى طرفاها فشربت وذكرت قول نصيب\n(بزينب ألمم قبل أن يرحل الركب ... )\nأنشدتها فأطربتني وفكرت في إنسان يفهم حسن ذلك ويعرف فضله فلم أجد\nغيرك فأتيتك فقلت ما جاء بك إلا هذا قال لا وأنصرف قال حماد معنى قوله التقى طرفاها أي قد صفت وراقت فأسفلها وأعلاها سواء في الصفاء ومما يغني فيه من قصيدة نصيب البائية المذكورة قوله صوت خليلي من كعب ألما هديتما ... بزينب لا يفقدكما أبدا كعب من اليوم زوراها فإن ركابنا ... غداة غد عنها وعن أهلها نكب\nلغناء لمالك خفيف ثقيل أول بالوسطى عن عمرو بن بانة صوت","topic":"أخبار عبادل ونسبه","topicNo":59,"sp":9,"spl":"توبة نصيب عن التشهير بالنساء — من المائة المختارة على رواية حجظة عن أصحابه","partialRef":{"sid":"b59-13","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b59-16","bab":"الجزء 6","sec":"من المائة المختارة على رواية حجظة عن أصحابه","page":"ج6 ص134","text":"(والنشر مسك والوجوه دنانير ... وأطراف الأكف عنم)\n(والدار وحش والرسوم كما ... رقش في ظهر الأديم قلم)\n(لست كأقوام خلائقهم ... نث أحاديث وهتك حرم)\nنث الحديث إشاعته والعنم شجر أحمر وقيل بل هو دود أحمر\nكالأساريع يكون في البقل في أيام الربيع والأديم الجلد وجلد كل شيء أديمه ورقش زين الشعر لمرقش الأكبر والغناء لإبن عائشة هزج بالبنصر في مجراها","topic":"أخبار عبادل ونسبه","topicNo":59,"sp":9,"spl":"توبة نصيب عن التشهير بالنساء — من المائة المختارة على رواية حجظة عن أصحابه"},
{"id":"b60-1","bab":"الجزء 6","sec":"أخبار المرقش الأكبر ونسبه","page":"ج6 ص136","text":"المرقش لقب غلب عليه بقوله\n(الدر وحش والرسوم كما ... رقش في ظهر الأديم قلم)\nهو أحد من قال شعرا فلقب به واسمه فيما ذكر أبو عمرو الشيباني عمرو وقال غيره عوف بن سعد بن مالك بن ضبيعة بن قيس بن ثعلبة الحصن بن عكابة بن صعب بن علي بن بكر بن وائل وهو أحد المتيمين كان يهوى ابنة عمه أسماء بنت عوف بن مالك بن ضبيعة كان المرقش الأصغر ابن أخي المرقش الأكبر واسمه فيما ذكر أبو عمرو ربيعة بن سفيان بن سعد بن مالك وقال غيره هو عمرو بن حرملة بن سعد بن مالك وهو أيضا أحد المتيمين كان يهوى فاطمة بنت المنذر الملك ويتشبب بها وكان للمرقشين جميعا وقع في بكر بن وائل وحروبها مع بني تغلب وباس وشجاعة ونجدة وتقدم في المشاهد ونكاية في العدو وحسن أثر وكان عوف بن مالك بن شبيعة عم المقرش الأكبر من فرسان بكر بن وائل وهو القائل يوم فضة يا لبكر بن وائل أفي كل يوم فرار\nومحلوفي لا يمر بي رجل من بكر بن وائل منهزما إلا ضربته بسيفي وبرك يقاتل فسمي البرك يومئذ وكان أخوه عمرو بن مالك أيضا من فرسان بكر وهو الذي أسر مهلهلا التقيا في خيلين من غير مزاحفة في بعض الغارات بين بكر وتغلب في موضع يقال له نقا الرمل فانهزمت خيل مهلهل وأدركه عمرو بن مالك فأسره فانطلق به إلى قومه وهم في نواحي هجر فأحسن إساره ومر عليه تاجر يبيع الخمر قدم بها من هجر وكان صديقا لمهلهل يشتري منه الخمر فأهدى إليه وهو أسير زق خمر فاجتمع إليه بنو مالك فنحروا عنده بكرا وشربوا عند مهلهل في بيته وقد أفرد له عمرو بيتا يكون فيه فلما أخذ فيهم الشراب تغنى مهلهل فيما كان يقوله من الشعر وينوح به على كليب فسمع ذلك عمرو بن مالك فقال إنه لريان والله لا يشرب ماء حتى يرد ربيب يعني جملا كان لعمرو بن مالك وكان يتناول الدهاس من أجواف هجر فيرعى فيها غبا بعد عشر في حمارة القيظ فطلبت ركبان بني مالك ربيبا وهم حراص على ألا يقتل مهلهل فلم يقدروا على البعير حتى مات مهلهل عطشا ونحر عمرو بن مالك يومئذ نابا فأسرج جلدها على مهلهل وأخرج رأسه وكانت بنت خال مهلهل امرأته بنت المحلل أحد بني تغلب قد أرادت أن تأتيه وهو أسير فقال يذكرها\n(ظبية ما ابنة المحلل شنباء ... لعوب لذيذة في العناق)\nفلما بلغها ما هو فيه لم تأته حتى مات فكان هبنقه القيسي أحد بني قيس بن ثعلبة واسمه يزيد بن ثروان يقول وكان محمقا وهو الذي تضرب به العرب المثل في الحمق لا يكون لي جمل أبدا إلا سميته ربيبا يعني أن ربيبا كان مباركا لقتله مهلهلا ذكر ذلك أجمع ابن الكلبي وغيره من الرواة والقصيدة الميمية التي فيها الغناء المذكورة بذكر أخبار المرقش يقولها في مرثية ابن عم له وفيها يقول\n(بل هل شجتك الظعن باكرة ... كأنها النخيل من ملهم)","topic":"أخبار المرقش الأكبر ونسبه","topicNo":60,"sp":0,"spl":"أخبار المرقش الأكبر ونسبه"},
{"id":"b60-2","bab":"الجزء 6","sec":"عشق المرقش الأكبر","page":"ج6 ص138","text":"قال أبو عمرو ووافقه المفضل الضبي وكان من خبر المرقش الأكبر أنه عشق ابنة عمه أسماء بنت عوف بن مالك وهو البرك عشقها وهو غلام فخطبها إلى أبيها فقال لا أزوجك حتى تعرف بالبأس وهذا قبل أن تخرج ربيعة من أرض اليمن وكان يعده فيها المواعيد ثم انطلق مرقش إلى ملك من الملوك فكان عنده زمانا ومدحه فأجازه وأصاب عوفا زمان شديد فأتاه رجل من مراد أحد بني غطيف فأرغبه في المال فزوجه أسماء على مائة من الإبل ثم تنحى عن بني سعد ابن مالك ورجع مرقش فقال اخوته لا تخبروه إلا أنها ماتت فذبحوا كبشا وأكلوا لحمه ودفنوا عظامه ولفوها في ملحفة ثم قبروها فلما قدم مرقش عليهم أخبروه أنها ماتت وأتوا به موضع القبر فنظر إليه وصار بعد ذلك يعتاده ويزوره فبينا هو ذات يوم مضطجع وقد تغطى بثوبه وابنا أخيه يلعبان بكعبين لهما إذ اختصما في كعب فقال أحدهما هذا كعبي أعطانيه أبي من الكبش الذي دفنوه\nوقالوا إذا جاء مرقش أخبرناه أنه قبر أسماء فكشف مرقش عن رأسه ودعا الغلام وكان قد ضنى ضنا شديدا فسأله عن الحديث فأخبره به وبتزويج المرادي أسماء فدعا مرقش وليدة له ولها زوج من غفيلة كان عسيفا لمرقش فأمرها بأن تدعو له زوجها فدعته وكانت له رواحل فأمره بإحضارها ليطلب المرادي عليها فأحضره إياها فركبها ومضى في طلبه فمرض في الطريق حتى ما يحمل إلا معروضا وإنهما نزلا كهفا بأسفل نجران وهي أرض مراد ومع الغفلي امرأته وليدة مرقش فسمع مرقش زوج الوليدة يقول لها اتركيه فقد هلك سقما وهلكنا معه ضرا وجوعا فجعلت الوليدة تبكي من ذلك فقال لها زوجها أطيعيني وإلا فإني تاركك وذاهب قال وكان مرقش يكتب وكان أبوه دفعه وأخاه حرملة وكانا أحب ولده إليه إلى نصراني من أهل الحيرة فعلمهما الخط فلما سمع مرقش قول الغفلي للوليدة كتب مرقش على مؤخرة الرحل هذه الأبيات\n(يا صاحبي تلبثا لا تعجلا ... إن الرواح رهين ألا تفعلا)\n(فلعل لبثكما يفرط سيئا ... أو يسبق الإسراع سيبا مقبلا)\n(يا راكبا إما عرضت فبلغن ... أنس بن سعد إن لقيت وحرملا)\n(لله دركما ودر أبيكما ... إن أفلت العبدان حتى يقتلا)\n(من مبلغ الأقوام أن مرقشا ... أضحى على الأصحاب عبئا مثقلا)\n(وكأنما ترد السباع بشلوه ... إذ غاب جمع بني ضبيعة منهلا)\nقال فانطلق الغفلي وامرأته حتى رجعا إلى أهلهما فقالا مات المرقش ونظر حرملة إلى الرحل وجعل يقلبه فقرأ الأبيات فدعاهما وخوفهما وأمرهما بأن يصدقاه ففعلا فقتلهما وقد كانا وصفا له الموضع فركب في طلب المرقش حتى أتى المكان فسال عن خبره فعرف أن مرقشا كان في الكهف ولم يزل فيه حتى إذا هو بغنم تنزو على الغار الذي هو فيه وأقبل راعيها إليها فلما بصر به قال له من أنت وما شأنك فقال له مرقش أنا رجل من مراد وقال للراعي من أنت قال راعي فلان وإذا هو راعي زوج أسماء فقال له مرقش أتستطيع أن تكلم أسماء امرأة صاحبك قال لا ولا أدنو منها ولكن تأتيني جاريتها كل ليلة فأحلب لها عنزا فتأتيها بلبنها فقال له خذ خاتمي هذا فإذا حلبت فألقه في اللبن فإنها ستعرفه وإنك مصيب به خيرا لم يصبه راع قط إن أنت فعلت ذلك فأخذ الراعي الخاتم ولما راحت الجارية بالقدح وحلب لها العنز طرح الخاتم فيه فانطلقت الجارية به وتركته بين يديها فلما سكنت الرغوة أخذته فشربته وكذلك كانت تصنع فقرع الخاتم ثنيتها فأخذته واستضاءت بالنار فعرفته فقالت للجارية ما هذا الخاتم قالت ما لي به علم فأرسلتها إلى مولاها وهو في شرف بنجران فأقبل فزعا فقال لها لم دعوتني قالت ادع عبدك راعي غنمك فدعاه فقالت سله أين وجد هذا الخاتم قال وجدته مع رجل في كهف خبان قال ويقال كهف جبار فقال اطرحه في اللبن الذي تشربه أسماء فإنك مصيب به خيرا وما أخبرني من هو ولقد تركته بآخر رمق فقال لها زوجها وما هذا الخاتم قالت خاتم\nمرقش فأعجل الساعة في طلبه فركب فرسه وحملها على فرس آخر وسارا حتى طرقاه من ليلتهما فاحتملاه إلى أهلهما فمات عند أسماء وقال قبل أن يموت\n(سرى ليلا خيال من سليمى ... فأرقني وأصحابي هجود)\n(فبت أديرأمري كل حال ... وأذكر أهلها وهم بعيد)\n(على أن قد سما طرفي لنار ... يشب لها بذي الأرطى وقود)\n(حواليها مها بيض التراقي ... وآرام وغزلان رقود)\n(نواعم لا تعالج بؤس عيش ... أوانس لا تروح ولا ترود)","topic":"أخبار المرقش الأكبر ونسبه","topicNo":60,"sp":1,"spl":"عشق المرقش الأكبر"},
{"id":"b60-3","bab":"الجزء 6","sec":"عشق المرقش الأكبر","page":"ج6 ص138","text":"(يرحن معا بطاء المشي بدا ... عليهن المجاسد والبرود)\n(سكن ببلدة وسكنت أخرى ... وقطعت المواثق والعهود)\n(فما بالي أفي ويخان عهدي ... وما بالي أصاد ولا أصيد)\n(ورب أسيلة الخدين بكر ... منعمة لها فرع وجيد)\n(وذو أشر شتيت النبت عذب ... نقي اللون براق برود)\n(لهوت بها زمانا في شبابي ... وزارتها النجائب والقصيد)\n(أناس كلما أخلقت وصلا ... عناني منهم وصل جديد)\nثم مات عند أسماء فدفن في أرض مراد وقال غير أبي عمرو والمفضل أتى رجل من مراد يقال له قرن الغزال وكان موسرا فخطب أسماء وخطبها المرقش وكان مملقا فزوجها أبوها من المرادي سرا فظهر على ذلك مرقش فقال لئن ظفرت به لأقتلنه فلما أراد أن يهتديها خاف أهلها عليها وعلى بعلها من مرقش فتربصوا بها حتى عزب مرقش في إبله وبنى المرادي بأسماء واحتملها إلى بلده فلما رجع مرقش إلى الحي رأى غلاما يتعرق عظما فقال له يا غلام ما حدث بعدي في الحي وأوجس في صدره خيفة لما كان فقال الغلام اهتدى المرادي امرأته أسماء بنت عوف فرجع المرقش إلى حية فلبس لأمته وركب فرسه الأغر واتبع آثار القوم يريد قتل المرادي فلما طلع لهم قالوا للمرادي هذا مرقش وإن لقيك فنفسك دون نفسه وقالوا لأسماء إنه سيمر عليك فأطلعي راسك إليه واسفري فإنه لا يرميك ولا يضرك ويلهو بحديثك عن طلب بعلك حتى يلحقه إخوته فيردوه وقالوا للمرادي تقدم فتقدم وجاءهم مرقش فلما حاذاهم أطلعت أسماء من خدرها ونادته فغض من فرسه وسار بقربها حتى أدركه أخواه أنس وحرملة فعذلاه ورداه عن القوم ومضى بها المرادي فألحقها بحية وضني مرقش لفراق أسماء فقال في ذلك\n(أمن آل أسماء الرسوم الدوارس ... تخطط فيها الطير قفر بسابس)\nهي قصيدة طويلة وقال في أسماء ايضا\n(أغالبك القلب اللجوج صبابة ... وشوقا إلى أسماء أم أنت غالبه)\n(يهيم ولا يعيا بأسماء قلبه ... كذاك الهوى إمراره وعواقبه)\n(أيلحى امرؤ في حب أسماء قد نأى ... بغمز من الواشين وازور جانبه)\n(وأسماء هم النفس إن كنت عالما ... وبادي أحاديث الفؤاد وغائبه)\n(إذا ذكرتها النفس ظلت كأنني ... يزعزعني قفقاف ورد وصالبه)\nوقال أبو عمرو وقع المجالد بن ريان ببني تغلب بجمران فنكى فيهم وأصاب مالا وأسرى وكان معه المرقش الأكبر فقال المرقش في ذلك\n(أتتني لسان بني عامر ... فجلى أحاديثها عن بصر)\n(بأن بني الوخم ساروا معا ... بجيش كضوء نجوم السحر)\n(بكل خبوب السرى نهدة ... وكل كميت طوال أغر)\n(فما شعر الحي حتى رأوا ... بريق القوانس فوق الغرر)\n(فأقبلنهم ثم أدربرنهم ... وأصدرنهم قبل حين الصدر)\n(فيا رب شلة تخطرفنه ... كريم لدى مزحف أو مكر)\n(وكائن بجمران من مزعف ... ومن رجل وجهه قد عفر)","topic":"أخبار المرقش الأكبر ونسبه","topicNo":60,"sp":2,"spl":"عشق المرقش الأكبر"},
{"id":"b60-4","bab":"الجزء 6","sec":"وأما المرقش الأصغر","page":"ج6 ص145","text":"فهو على ما ذكر أبو عمرو ربيعة بن سفيان بن سعد بن مالك بن ضبيعة والمرقش الأكبر عم الأصغر والأصغر عم طرفة بن العبد قال أبو عمرو والمرقش الأصغر أشعر المرقشين وأطولهما عمرا وهو الذي عشق فاطمة بنت المنذر وكانت لها وليدة يقال لها بنت عجلان وكان لها قصر بكاظمة وعليه حرس وكان الحرس يجرون كل ليلة حوله الثياب فلا يطؤه أحد إلا بنت عجلان وكان لبنت عجلان في كل ليلة رجل من أهل الماء يبيت عندها فقال عمرو بن جناب بن مالك لمرقش إن بنت عجلان تأخذ كل عشية رجلا ممن يعجبها فيبيت معها وكان مرقش ترعية لا يفارق إبله فأقام بالماء وترك إبله ظمأى وكان من أجمل الناس وجها وأحسنهم شعرا وكانت فاطمة بنت المنذر تقعد فوق القصر فتنظر إلى الناس فجاء مرقش فبات عند ابنة عجلان حتى إذا كان من الغد تجردت عند مولاتها فقالت لها ما هذا بفخذيك وإذا نكت كأنها التين وكآثار السياط من شدة حفزه إياها عند الجماع قالت اثار رجل بات معي الليلة وقد كانت فاطمة قالت لها لقد رأيت رجلا جميلا راح نحونا بالعشية لم أره قبل ذلك قالت فإنه فتى قعد عن إبله وكان يرعاها وهو الفتى الجميل الذي\nرأيته وهو الذي بات معي فأثر في هذه الآثار قالت لها فاطمة فإذا كان غد وأتاك فقدمي له مجمرا ومريه أن يجلس عليه وأعطيه سواكا فإن استاك به أو رده فلا خير فيه وإن قعد على المجمر أو رده فلا خير فيه فأتته بالمجمر فقالت له اقعد عليه فأبى وقال أدنيه مني فدخن لحيته وجمته وأبى أن يقعد عليه وأخذ السواك فقطع رأسه واستاك به فأتت ابنة عجلان فاطمة فأخبرتها بما صنع فازدادت به عجبا وقالت أئتيني به فتعلقت به كما كانت تتعلق فمضى معها وانصرف أصحابه فقال القوم حين انصرفوا لشد ما علقت بنت عجلان المرقش وكان الحرس ينثرون التراب حول قبة فاطمة بنت المنذر ويجرون عليه ثوبا حين تمسي ويحرسونها فلا يدخل عليه إلا ابنة عجلان فإذا كان الغد بعث الملك بالقافة فينظرون أثر من دخل إليها ويعودون فيقولون له لم نر إلا أثر بنت عجلان فلما كانت تلك الليلة حملت بنت عجلان مرقشا على ظهرها وحزمته إلى بطنها بثوب وأدخلته إليها فبات معها فلما أصبح بعث الملك القافة فنظروا وعادوا إليه فقالوا نظرنا أثر بنت عجلان وهي مثقلة فلبث بذلك حينا يدخل إليها فكان عمرو بن جناب بن عوف بن مالك يرى ما يفعل ولا يعرف مذهبه فقال له ألم تكن عاهدتني عهدا لا تكتمني شيئا ولا أكتمك ولا نتكاذب فأخبره مرقش الخبر فقال له لا أرضى عنك ولا أكلمك أبدا أو تدخلني عليها وحلف على ذلك فانطلق المرقش إلى المكان الذي كان يواعد فيه بنت عجلان فأجلسه فيه وانصرف وأخبره كيف يصنع وكانا متشابهين غير أن عمرو بن جناب كان أشعر فأتته بنت عجلان فاحتملته وأدخلته إليها وصنع ما أمره به مرقش فلما أراد مباشرتها وجدت شعر فخذيه فاستنكرته وإذا هو يرعد فدفعته بقدمها في صدره وقالت قبح الله سرا عند المعيدي ودعت بنت عجلان فذهبت به وانطلق\nإلى موضع صاحبه فلما رآه قد أسرع الكرة ولم يلبث إلا قليلا علم أنه قد افتضح فعض على إصبعه فقطعها ثم انطلق إلى أهله وترك المال الذي كان فيه يعني الإبل التي كان مقيما فيها حياء مما صنع وقال مرقش في ذلك\n(ألا يا اسلمى لا صرم لي اليوم فاطما ... ولا أبدا ما دام وصلك دائما)\n(رمتك ابنة البكري عن فرع ضالة ... وهن بنا خوص يخلن نعائما)\n(تراءت لنا يوم الرحيل بوارد ... وعذب الثنايا لم يكن متراكما)\n(سقاه حباب المزن في متكلل ... من الشمس رواه ربابا سواجما)\n(أرتك بذات الضال منها معاصما ... وخدا أسيلا كالوذيلة ناعما)\n(صحا قلبه عنها على أن ذكرة ... إذا خطرت دارت به الأرض قائما)\n(تبصر خليلي هل ترى من ظعائن ... خرجن سراعا واقتعدن المفائما)\n(تحملن من جو الوريعة بعد ما ... تعالى النهار وانتجعن الصرائما)\n(تحلين ياقوتا وشذرا وصيغة ... وجزعا ظفاريا ودرا توائما)\n(سلكن القرى والجزع تحدى جمالها ... ووركن قوا واجتزعن المخارما)\n(ألا حبذا وجه تريك بياضه ... ومنسدلات كالمثاني فواحما)\n(وإني لأستحيي فطيمة جائعا ... خميصا وأستحيي فطيمة طاعما)\n(وإني لأستحييك والخرق بيننا ... مخافة أن تلقى أخا لي صارما)\n(وإني وإن كلت قلوصي لراجم ... بها وبنفسي يا فطيم المراجما)\n(ألا يا اسلمى بالكوكب الطلق فاطما ... وإن لم يكن صرف النوى متلائما)","topic":"أخبار المرقش الأكبر ونسبه","topicNo":60,"sp":3,"spl":"وأما المرقش الأصغر"},
{"id":"b60-5","bab":"الجزء 6","sec":"وأما المرقش الأصغر","page":"ج6 ص145","text":"(ألا يا اسلمى ثم اعلمي أن حاجتي ... إليك فردي من نوالك فاطما)\n(أفاطم لو أن انساء ببلدة ... وأنت بأخرى لابتغيتك هائما)\n(متى ما يشأ ذو الود يصرم خليله ... ويغضب عليه لا محالة ظالما)\n(وآلى جناب حلفة فأطعته ... فنفسك ول اللوم إن كنت نادما)\n(فمن يلق خيرا يحمد الناس أمره ... ومن يغو لا يعدم على الغي لائما)\n(ألم تر أن المرء يجذم كفه ... ويجشم من لوم الصديق المجاشما)\n(أمن حلم أصبحت تنكت واجما ... وقد تعتري الأحلام من كان نائما)\nصوت","topic":"أخبار المرقش الأكبر ونسبه","topicNo":60,"sp":4,"spl":"وأما المرقش الأصغر — من المائة المختارة"},
{"id":"b60-6","bab":"الجزء 6","sec":"من المائة المختارة","page":"ج6 ص148","text":"(إذا قلت تسلو النفس أو تنتهي المنى ... أبى القلب إلا حب أم حكيم)\n(منعمة صفراء حلو دلالها ... أبيت بها بعد الهدوء أهيم)\n(قطوف الخطا محطوطة المتن زانها ... مع الحسن خلق في الجمال عميم)\nالشعر مختلف في قائله فمن الرواة من يرويه لصالح بن عبد الله العبشمي ومنهم من يرويه لقطري بن الفجاءة المازني ومنهم من يرويه لعبيدة بن هلال اليشكري والغناء لسياط وله فيه لحنان أحدهما وهو المختار ثقيل أول بالوسطى والآخر خفيف ثقيل بالسبابة في مجرى البنصر عن إسحاق ولبعض الشراة قصيدة في هذا الوزن وعلى هذه القافية وفيها ذكر لأم حكيم هذه أيضا تنسب إلى هؤلاء الشعراء الثلاثة ويختلف في قائلها كالإختلاف في قائل هذه وفيها أيضا غناء وهو في هذه الأبيات منها\n(لعمرك إني في الحياة لزاهد ... وفي العيش ما لم ألق أم حكيم)\n(ولو شهدتني يوم دولاب أبصرت ... طعان فتى في الحرب غير ذميم)\nذكر المبرد أن الشعر لقطري بن الفجاءة وذكر الهيثم بن عدي أنه لعمرو القنا وذكر وهب بن جرير أنه لحبيب بن سهم التميمي وذكر أبو مخنف أنه لعبيدة بن هلال اليشكري وذكر خالد بن خداش أنه لعمرو القنا أيضا والغناء لمعبد ثاني ثقيل بالسبابة في مجرى الوسطى عن إسحاق ويونس","topic":"أخبار المرقش الأكبر ونسبه","topicNo":60,"sp":4,"spl":"وأما المرقش الأصغر — من المائة المختارة"},
{"id":"b60-7","bab":"الجزء 6","sec":"خبر الوقعة التي قيل فيها هذان الشعران وهي وقعة دولاب وشيء من أخبار","page":"ج6 ص151","text":"هؤلاء الشراة وأنسابهم وخبر أم حكيم هذه هذان الشعران قيلا في وقعة دولاب وهي قرية من عمل الأهواز بينها وبين الأهواز نحو من أربعة فراسخ كانت بها حرب بين الأزارقة وبين مسلم بن عبيس بن كريز خليفة عبد الله بن الحارث بن نوفل بن عبد المطلب وذلك في أيام ابن الزبير أخبرني بخبر هذه الحرب أحمد بن عبد العزيز الجوهري عن عمر بن شبة عن المدائني وأخبرني بها عبيد الله بن محمد الرازي عن الخراز عن المدائني وأخبرني الحسن بن علي عن أحمد بن زهير بن حرب عن خالد بن خداش أن نافع بن الأزرق لما تفرقت آراء الخوارج ومذاهبهم في أصول مقالتهم أقام بسوق الأهواز وأعمالها لا يعترض الناس وقد كان متشككا في ذلك فقالت له امرأته إن كنت قد كفرت بعد إيمانك وشككت فيه فدع نحلتك ودعوتك وإن كنت قد خرجت من الكفر إلى الإيمان فاقتل الكفار حيث لقيتهم وأثخن في النساء والصبيان كما قال نوح لا تذر على الارض من الكافرين ديارا فقبل قولها واستعرض الناس وبسط سيفه فقتل الرجال والنساء والولدان وجعل يقول إن هؤلاء إذا كبروا كانوا مثل آبائهم وإذا وطىء بلدا فعل مثل هذا به\nإلى أن يجيبه أهله جميعا ويدخلوا ملته فيرفع السيف ويضع الحباية فيجبى الخراج فعظم أمره واشتدت شوكته وفشا عماله في السواد فارتاع لذلك أهل البصرة ومشوا إلى الأحنف بن قيس فشكوا إليه أمرهم وقالوا له ليس بيننا وبين القوم إلا ليلتان وسيرتهم كما ترى فقال لهم الأحنف إن سيرتهم في مصركم إن ظفروا به مثل سيرتهم في سوادكم فخذوا في جهاد عدوكم وحرضهم الأحنف فاجتمع إليه عشرة آلاف رجل في السلاح فأتاه عبد الله بن الحارث بن نوفل وسأله أن يؤمر عليهم أميرا فاختار لهم مسلم بن عبيس بن كريز بن ربيعة وكان فارسا شجاعا دينا فأمره عليهم وشيعه فلما نفذ من جسر البصرة أقبل على الناس وقال إني ما خرجت لإمتيار ذهب ولا فضة وإني لأحارب قوما إن ظفرت بهم فما رواءهم إلا سيوفهم ورماحهم فمن كان من شأنه الجهاد فلينهض ومن أحب الحياة فليرجع فرجع نفر يسير ومضى الباقون معه فلما صاروا بدولاب خرج إليهم نافع بن الأزرق فاقتتلوا قتالا شديدا حتى تكسرت الرماح وعقرت الخيل وكثرت الجراح والقتلى وتضاربوا بالسيوف والعمد فقتل في المعركة ابن عبيس وهو على أهل البصرة وذلك في جمادى الآخرة سنة خمس وستين وقتل نافع بن الأزرق يومئذ أيضا فعجب الناس من ذلك وأن الفريقين تصابروا حتى قتل منهم خلق كثير وقتل رئيسا العسكرين والشراة يومئذ ستمائة رجل فكانت الحدة يومئذ وباس الشراة واقعا ببني تميم وبني سدوس وأتى ابن عبيس وهو يجود بنفسه فاستخلف على الناس الربيع بن عمرو الغداني وكان يقال له الأجذم كانت يده أصيبت بكابل مع عبد الرحمن بن سمرة واستخلف نافع بن الأزرق عبيد\nالله بن بشير بن الماحوز أحد بني سليط بن يربوع فكان رئيسا المسلمين والخوراج جميعا من بني يربوع رئيس المسلمين من بني غدانة بن يربوع ورئيس الشراة من بني سليط بن يربوع فاتصلت الحرب بينهم عشرين يوما قال المدائني في خبره وادعى قتل نافع بن الأزرق رجل من باهلة يقال له سلامة وتحدث بعد ذلك قال كنت لما قتلته على برذون لورد فإذا أنا برجل ينادي وأنا واقف في خمس بني تميم فإذا به يعرض علي المبارزة فتغافلت عنه وجعل يطلبني وأنا أنتقل من خمس إلى خمس وليس يزايلني فصرت إلى رحلي ثم رجعت فدعاني إلى المبارزة فلما أكثر خرجت إليه فاختلفنا ضربتين فضربته فصرعته ونزلت فأخذت رأسه وسلبته فإذا امرأة قد رأتني حين قتلت نافعا فخرجت لتثأر به قالوا فلما قتل نافع وابن عبيس وولي الجيش إلى ربيع بن عمرو لم يزل يقاتل الشراة نيفا وعشرين يوما ثم أصبح ذات يوم فقال لأصحابه إني مقتول لا محالة قالوا وكيف ذلك قال إني رايت البارحة كأن يدي التي أصيبت بكابل انحطت من السماء فاستشلتني فلما كان الغد قاتل إلى الليل ثم غاداهم فقتل يومئذ قال استشلاه أخذه إليه يقال أستشلاه واشتلاه قال فلما قتل الربيع تدافع أهل البصرة الراية حتى خافوا العطب إذ لم يكن لهم رئيس","topic":"أخبار المرقش الأكبر ونسبه","topicNo":60,"sp":5,"spl":"خبر الوقعة التي قيل فيها هذان الشعران وهي وقعة دولاب وشيء من أخبار"},
{"id":"b60-8","bab":"الجزء 6","sec":"خبر الوقعة التي قيل فيها هذان الشعران وهي وقعة دولاب وشيء من أخبار","page":"ج6 ص151","text":"ثم أجمعوا على الحجاج بن باب الحميري وقد اقتتل الناس يومئذ وقبله بيومين قتالا شديدا لم يقتتلوا مثله تطاعنوا بالرماح حتى تقصفت ثم تضاربوا بالسيوف والعمد حتى لم يبق لأحد منهم قوة وحتى كان الرجل منهم يضرب الرجل فلا يغني شيئا من الإعياء وحتى كانوا يترامون بالحجارة ويتكادمون بالأفواه فلما تدافع القوم الراية وأبوها واتفقوا على الحجاج بن باب امتنع من أخذها فقال له كريب بن عبد الرحمن خذها فإنها مكرمة فقال إنها لراية مشؤومة ما أخذها أحد إلا قتل فقال له كريب يا أعور تقارعت العرب على أمرها ثم صيروها إليك فتأبى خوف القتل خذ اللواء ويحك فإن حضر أجلك قتلت إن كانت معك أو لم تكن فأخذ اللواء وناهضهم فاقتتلوا حتى انتقضت الصفوف وصاروا كراديس والخوارج أقوى عدة بالدروع والجواشن وجعل الحجاج يغمض عينيه ويحمل حتى يغيب في الشراة ويطعن فيهم ويقتل حتى يظن أنه قد قتل ثم يرفع راسه وسيفه يقطر دما ويفتح عينيه فيرى الناس كراديس يقاتل كل قوم في ناحية ثم التقى الحجاج بن باب وعمران بن الحارث الراسبي فاختلفا ضربتين كل واحد منهما قتل صاحبه وجال الناس بينهما جولة ثم تحاجزوا وأصبح أهل البصرة وقد هرب عامتهم وولوا حارثة بن بدر الغداني أمرهم ليس بهم طرق ولا بالخوارج فقالت امرأة من الشراة وهي أم عمران قاتل الحجاج بن باب وقتيله ترثي ابنها عمران\n(ألله أيد عمرانا وطهره ... وكان عمران يدعو الله في السحر)\n(يدعوه سرا وإعلانا ليرزقه ... شهادة بيدي ملحادة غدر)\n(ولى صحابته عن حر ملحمة ... وشد عمران كالضرغامة الذكر)\nال فلما عقدوا لحارثة بن بدر الرياسة وسلموا إليه الراية نادى فيهم بأن يثبتوا فإذا فتح الله عليهم فللعرب زيادة فريضتين وللموالي زيادة فريضة فندب الناس فآلتقوا وليس بأحد منهم طرق وقد فشت فيهم الجراحات فلهم أنين وما تطأ الخيل إلا على القتلى فبينما هم كذلك إذ أقبل من اليمامة جمع من الشراة يقول المكثر إنهم مائتان والمقلل إنهم أربعون فاجتموا وهم يريحون مع أصحابهم واجتمعوا كبكبة واحدة فحملوا على المسلمين فلما رآهم حارثة بن بدر نكص برايته فانهزم وقال\n(كرنبوا ودولبوا ... وحيث شئتم فاذهبوا)\nوقال\n(أير الحمار فريضة لعبيدكم ... والخصيتان فريضة الأعراب)\nتتابع الناس على أثره منهزمين وتبعتهم الخوارج فألقوا أنفسهم في دجيل فغرق منهم خلق كثير وسلمت بقيتهم وكان ممن غرق دغفل بن حنظلة أحد بني عمرو بن شيبان ولحقت قطعة من الشراة خيل عبد القيس فأكبوا عليهم فعطفت عليهم خيل من بني تميم فعاونوهم وقاتلوا الشراة حتى كشفوهم وانصرفوا إلى أصحابهم وعبرت بقية الناس فصار حارثة ومن معه بنهر تيري والشراة بالأهواز فأقاموا ثلاثة أيام وكان على الأزد يومئذ قبيصة بن أبي صفرة أخو المهلب وهو جد هزارمرد قال وغرق يومئذ من الأزد عدد كثير فقال شاعر الأزراقة\n(يرى من جاء ينظر من دجيل ... شيوخ الأزد طافية لحاها)\nقال شاعر آخر منهم\n(شمت ابن بدر والحوادث جمة ... والظالمون بنافع بن الأزرق)\n(والموت حتم لا محالة واقع ... من لا يصبحه نهارا يطرق)\n(فلئن أمير المؤمنين أصابه ... ريب المنون فمن تصبه يغلق)\nال قطري بن الفجاءة فيما ذكر المبرد وقال المدائني في خبره إن صالح بن عبد الله العبشمي قائل ذلك وقال خالد بن خداش بل قائلها عمرو القنا قال وهب بن جرير عن أبيه فيما حدثني به أحمد بن الجعد الوشاء عن أحمد بن أبي خيثمة عن أبيه عن وهب بن جرير عن أبيه إن حبيب بن سهم قائلها\n(لعمرك إني في الحياة لزاهد ... وفي العيش ما لم ألق أم حكيم)\n(من الخفرات البيض لم أر مثلها ... شفاء لذي بي ولا لسقيم)\n(لعمرك إني يوم ألطم وجهها ... على نائبات الدهر غير حليم)\n(ولو شهدتني يوم دولاب أبصرت ... طعان فتى في الحرب غير لئيم)\n(غداة طفت علماء بكر بن وائل ... وألافها من حمير وسليم)\n(ومال الحجازيون نحو بلادهم ... وعجنا صدور الخيل نحو تميم)\n(وكان لعبد القيس أول جدها ... وولت شيوخ الأزذ فهي تعوم)\n(فلم أر يوما كان أكثر مقعصا ... يمج دما من فائظ وكليم)\n(وضاربة خدا كريما على فتى ... أغر نجيب الأمهات كريم)\n(أصيب بدولاب ولم تك موطنا ... له أرض دولاب ودير حميم)\n(فلو شهدتنا يوم ذاك وخيلنا ... تبيح من الكفار كل حريم)\n(رأت فتية باعوا الإلة نفوسهم ... بجنات عدن عنده ونعيم)","topic":"أخبار المرقش الأكبر ونسبه","topicNo":60,"sp":6,"spl":"خبر الوقعة التي قيل فيها هذان الشعران وهي وقعة دولاب وشيء من أخبار"},
{"id":"b60-9","bab":"الجزء 6","sec":"خبر الوقعة التي قيل فيها هذان الشعران وهي وقعة دولاب وشيء من أخبار","page":"ج6 ص151","text":"حدثني حبيب بن نصر المهلبي قال حدثنا عمر بن شبة قال حدثنا خلاد الأرقط قال كان الشراة والمسلمون يتواقفون ويتساءلون بينهم عن أمر الدين وغير ذلك على أمان وسكون فلا يهيج بعضهم بعضا فتوافق يوما عبيدة بن هلال اليشكري وأبو حزابة التميمي وهما في الحرب فقال عبيدة يا أبا حزابة إني سائلك عن أشياء افتصدقني في الجواب عنها قال نعم إن تضمنت لي مثل ذلك قال قد فعلت قال سل عما بدا لك قال ما تقول في أئمتكم قال يبيحون الدم الحرام والمال الحرام والفرج الحرام قال ويحك فكيف فعلهم في المال قال يجبونه من غير حلة وينفقونه في غير حقه قال فكيف فعلهم في اليتيم قال يظلمونه ماله ويمنعونه حقه وينيكون أمه قال ويلك يا أبا حزابة أفمثل هؤلاء تتبع قال قد أجبت فاسمع سؤالي ودع عنك عتابي على رأيي قال قل قال أي الخمر أطيب أخمر السهل أم خمر الجبل قال ويلك أتسأل مثلي عن هذا قال قد أوجبت على نفسك أن تجيب قال أما إذ أبيت فإن خمر الجبل أقوى وأسكر وخمر السهل أحسن وأسلس قال أبو حزابة فأي الزواني أفره أزواني رامهرمز أم زواني أرجان قال ويلك إن مثلي لا يسأل عن مثل هذا\nقال لا بد من الجواب أو تغدر فقال أما إذ أبيت فزواني رامهرمز أرق أبشارا وزواني أرجان أحسن أبدانا قال فأي الرجلين أشعر أجرير أم الفرزدق قال عليك وعليهما لعنة الله أيهما الذي يقول\n(وطوى الطراد مع القياد بطونها ... طي التجار بحضرموت برودا)\nال جرير قال فهو أشعرهما قال وكان الناس قد تجاذبوا في أمر جرير والفرزدق حتى تواثبوا وصاروا إلى المهلب محكمين له في ذلك فقال أردتم أن أحكم بين هذين الكلبين المتهارشين فيمتضغاني ما كنت لأحكم بينهما ولكني أدلكم على من يحكم بينهما ثم يهون عليه سبابهما عليكم بالشراة فسيلوهم إذا توافقتم فلما تواقفوا سأل أبو حزابة عبيدة بن هلال عن ذلك فأجابه بهذا الجواب أخبرني أحمد بن جعفر جحظة قال حدثني ميمون بن هارون قال حدثت أن امرأة من الخوارج كانت مع قطري بن الفجاءة يقال لها أم حكيم وكان من أشجع الناس وأجملهم وجها وأحسنهم بدينهم تمسكا وخطبها جماعة منهم فردتهم ولم تجب إلى ذلك فأخبرني من شهدها أنها كانت تحمل على الناس وترتجز\n(أحمل رأسا قد سئمت حمله ... وقد مللت دهنه وغسله)\n(ألا فتى يحمل عني ثقله ... )\nال وهم يفدونها بالآباء والأمهات فما رأيت قبلها ولا بعدها مثلها أخبرني محمد بن خلف وكيع قال حدثنا أحمد بن الهيثم بن فراس قال حدثنا\nالعمري عن الهيثم بن عدي قال كان عبيدة بن هلال إذا تكاف الناس ناداهم ليخرج إلي بعضكم فيخرج إليه فتيان من العسكر فيقول لهم أيما أحب إليكم أقرأ عليكم القرآن أو أنشدكم الشعر فيقولون له أما القرآن فقد عرفناه مثل معرفتك فأنشدنا فيقول لهم يا فسقة والله قد علمت أنكم تختارون الشعر على القرآن ثم لا يزال ينشدهم ويستنشدهم حتى يملوا ثم يفترقون","topic":"أخبار المرقش الأكبر ونسبه","topicNo":60,"sp":7,"spl":"خبر الوقعة التي قيل فيها هذان الشعران وهي وقعة دولاب وشيء من أخبار","partial":1},
{"id":"b61-1","bab":"الجزء 6","sec":"أخبار سياط ونسبه","page":"ج6 ص161","text":"سياط لقب غلب عليه واسمه عبد الله بن وهب ويكنى أبا وهب مكي مولى خزاغة وكان مقدما في الغناء رواية وصنعة ومقدما في الضرب معدودا في الضراب وهو أستاذ ابن جامع وإبراهيم الموصلي وعنه أخذا ونقلا ونقل نظراؤهما الغناء القديم وأخذه هو عن يونس الكاتب وكان سياط زوج أم ابن جامع وفيه يقول بعض الشعراء\n(ما سمعت الغناء إلا شجاني ... من سياط وزاد في وسواسي)\n(غنني يا سياط قد ذهب الليل ... غناء يطير منه نعاسي)\n(ما أبالي إذا سمعت غناء ... لسياط ما فاتني للرؤاسي)\nوالرؤاسي الذي عناه هو عباس بن منقار وهو من بني رؤاس وفيه يقول محمد بن أبان الضبي\n(إذا واخيت عباسا ... فكن منه على وجل)\n(فتى لا يقبل العذر ... ولا يرغب في الوصل)\n(وما إن يتغنى من ... يواخيه من النبل)\nال حماد بن إسحاق لقب سياط هذا اللقب لأنه كان كثيرا ما يتغنى\n(كأن مزاحف الحيات فيه ... قبيل الصبح آثار السياط)\nأخبرني محمد بن خلف قال حدثني هارون بن مخارق عن أبيه وأخبرني به عبد الله بن عباس بن الفضل بن الربيع عن وسواسة الموصلي ولم أسمع أنا هذا الخبر من وسواسة عن حماد عن أبيه قالا غنى إبراهيم الموصلي يوما صوتا لسياط فقال له ابنه إسحاق لمن هذا الغناء يا أبت قال لمن لو عاش ما وجد أبوك شيئا يأكله لسياط قال وقال المهدي يوما وهو يشرب لسلام الأبرش جئني بسياط وعقاب وحبال فارتاع كل من حضر وظن جميعهم أنه يريد الإيقاع بهم أو ببعضهم فجاءه بسياط المغني وعقاب المدني وكان الذي يوقع عليه وحبال الزامر فجعل الجلساء يشتمونهم والمهدي يضحك","topic":"أخبار سياط ونسبه","topicNo":61,"sp":0,"spl":"أخبار سياط ونسبه"},
{"id":"b61-2","bab":"الجزء 6","sec":"سياط وأبو ريحانة المدني","page":"ج6 ص162","text":"أخبرني محمد بن خلف قال حدثني أبو أيوب المدني قال حدثني حماد ابن إسحاق عن أبيه قال مر سياط على أبي ريحانة المدني في يوم بارد وهو جالس في الشمس وعليه ثوب رقيق رث فوثب إليه أبو ريحانة وقال بابي أنت يا أبا وهب غنني صوتك في شعر ابن جندب\n(فؤادي رهين في هواك ومهجتي ... تذوب وأجفاني عليك همول)\nفغناه إياه فشق قميصه ورجع إلى موضعه من الشمس وقد ازداد بردا وجهدا فقال له رجل ما أغنى عنك ما غناك من شق قميصك فقال له يا ابن أخي إن الشعر الحسن من المغني الحسن ذي الصوت المطرب أدفأ للمقرور من حمام محمى فقال له رجل أنت عندي من الذين قال الله جل وعز ( فما ربحت تجارتهم وما كانوا مهتدين\nفقال بل أنا من الذين قال تبارك وتعالى ( الذين يستمعون القول فيتبعون أحسنه\nوقد أخبرني بهذا الخبر علي بن عبد العزيز عن ابن خرداذبه فذكر قريبا من هذا ولفظ أبي أيوب وخبره أتم وأخبرني إسماعيل بن يونس الشيعي المعروف بإبن أبي اليسع قال حدثنا عمر بن شبة أن سياطا مر بأبي ريحانة المدني فقال له بحق القبر ومن فيه غنني بلحنك في شعر ابن جندب\n(لكل حمام أنت باك إذا بكى ... ودمعك منهل وقلبك يخفقق)\n(مخافة بعد بعد قرب وهجرة ... تكون ولما تأت والقلب مشفق)\n(ولي مهجة ترفض من خوف عتبها ... وقلب بنار الحب يصلى ويحرق)\n(أظل خليعا بين أهلي ميتما ... وقلبي لما يرجوه منها معلق)\nغناه إياه فلما استوفاه ضرب بيده على قميصه فشقه حتى خرج منه وغشي عليه فقال له رجل لما أفاق يا أبا ريحانة ما أغنى عنك الغناء ثم ذكر باقي الخبر أخبرني إسماعيل قال حدثني عمر بن شبة قال مرت جارية بأبي ريحانة يوما على ظهرها قربة وهي تغني وتقول\n(وأبكي فلا ليلى بكت من صبابة ... إلي ولا ليلى لذي الود تبذل)\n(وأخنع بالعتبى إذا كنت مذنبا ... وإن أذنبت كنت الذي أتنصل)\nقام إليها فقال يا سيدتي أعيدي فقالت مولاتي تنتظرني والقربة على ظهري فقال أنا أحملها عنك فدفعتها إليه فحملها وغنته الصوت فطرب فرمى بالقربة فشقها فقالت له الجارية أمن حقي أن أغنيك وتشق قربتي فقال لها لا عليك تعالي معي إلى السوق فجاءت معه فباع ملحفته واشترى لها بثمنها قربة جديدة فقال له رجل يا أبا ريحانة أنت والله كما قال الله عز و جل ( فما ربحت تجارتهم وما كانوا مهتدين\nفقال بل أنا كما قال الله يستمعون القول فيتبعون أحسنه\nخبرني الحسين بن القاسم الكوكبي قال حدثني أبو العيناء قال قال إسحاق الموصلي بلغني أن أبا ريحانة المدني كان جالسا في يوم شديد البرد وعليه قميص خلق رقيق فمر به سياط المغني فوثب إليه وأخذ بلجامه وقال له يا سيدي بحق القبر ومن فيه غنني صوت ابن جندب فغناه\n(فؤادي رهين في هواك ومهجتي ... تذوب وأجفاني عليك همول)\nشق قميصه حتى خرج منه وبقي عاريا وغشي عليه واجتمع الناس حوله وسياط واقف متعجب مما فعل ثم أفاق وقام إليه فرحمه سياط وقال له مالك يا مشؤوم أي شيء تريد قال غنني بالله عليك\n(ودع أمامة حان منك رحيل ... إن الوداع لمن تحب قليل)\n(مثل القضيب تمايلت أعطافه ... )\n(فالريح تجذب متنه فيميل ... )\n(إن كان شأنكم الدلال فإنه ... حسن دلالك يا أميم جميل)\nفغناه إياه فلطم وجهه ثم خرج الدم من أنفه ووقع صريعا ومضى سياط وحمل الناس أبا ريحانة إلى الشمس فلما أفاق قيل له ويحك خرقت قميصك وليس لك غيره فقال دعوني فإن الغناء الحسن من المغني المطرب أدفأ للمقرور من حمام المهدي إذا أوقد سبعة أيام قال ووجه له سياط بقميص وجبة وسراويل وعمامة","topic":"أخبار سياط ونسبه","topicNo":61,"sp":1,"spl":"سياط وأبو ريحانة المدني","partial":1},
{"id":"b61-3","bab":"الجزء 6","sec":"سياط يوصي بالمحافظة على غنائه","page":"ج6 ص165","text":"أخبرني يحيى بن علي بن يحيى قال حدثني أبو أيوب المدني قال حدثني محمد بن عبد الله الخزاعي وحماد بن إسحاق جميعا عن إسحاق قال كان سياط أستاذ أبي وأستاذ ابن جامع ومن كان في ذلك العصر فاعتل علة فجاءه أبي وابن جامع يعودانه فقال له أبي أعزز علي بعلتك أبا وهب ولو كانت مما يفتدى لفديتك منها قال كيف كنت لكم قلنا نعم الأستاذ والسيد قال قد غنيت لنفسي ستين صوتا فأحب ألا تغيروها ولا تنتحلوها فقال له أبي أفعل ذلك يا أبا وهب ولكن أي ذلك كرهت أن يكون في غنائك فضل فأقصر عنه فيعرف فضلك علي فيه أو أن يكون فيه نقص فأحسنه فينسب إحساني إليك ويأخذه الناس عني لك قال لقد استعفيت من غير مكروه قال الخزاعي في خبره ثم قال لي إسحاق كان سياط خزاعيا وكان له زامر يقال له حبال وضارب يقال له عقاب قال حماد قال أبي أدركت أربعة كانوا أحسن الناس غناء سياط أحدهم قال وكان موته في أول أيام موسى الهادي\nأخبرني يحيى قال حدثنا أبو أيوب عن مصعب قال دخل ابن جامع على سياط وقد نزل به الموت فقال له ألك حاجة فقال نعم لا تزد في غنائي شيئا ولا تنقص منه دعه رأسا برأس فإنما هو ثمانية عشر صوتا أخبرنا محمد بن مزيد قال حدثنا حماد قال حدثني محمد بن حديد أخو النضر بن حديد أن إخوانا لسياط دعوه فأقام عندهم وبات فأصبحوا فوجدوه ميتا في منزلهم فجاؤوا إلى أمه وقالوا يا هذه إنا دعونا إبنك لنكرمه ونسر به ويأنس بقربه فمات فجأة وها نحن بين يديك فاحتكمي ما شئت ونشدناك الله ألا تعرضينا للسلطان أو تدعي فيه علينا ما لم نفعله فقلت ما كنت لأفعل وقد صدقتم وهكذا مات أبوه فجأة قال فجاءت معنا فحملته إلى منزلها فأصلحت أمره ودفنته وقد ذكرت هذه القصة بعينها في وفاة نبيه المغني وخبره في ذلك يذكر مع أخباره إن شاء الله تعالى أخبرنا يحيى بن علي وعيسى بن الحسين الزيات واللفظ له قالا حدثنا أبو أيوب قال حدثنا أحمد بن المكي قال غنيت إبراهيم بن المهدي لسياط\n(ضاف قلبي الهوى فأكثر سهوي ... )\nفاستحسنه جدا وقال لي ممن أخذته قلت من جارية أبيك قرشية الزباء فقال أشعرت أنه كان لأبي ثلاث جوار محسنات كلهن تسمى قرشية منهن قرشية الزباء وقرشية السوداء وقرشية البيضاء وكانت الزباء أحسنهن غناء يعني التي\nأخذت منها هذا الصوت قال وكنت أسمعها كثيرا تقول قد سمعت المغنين وأخذت عنهم وتقفدت أغانيهم فما رأيت فيهم مثل سياط قط هذه الحكاية من رواية عيسى بن الحسين خاصة","topic":"أخبار سياط ونسبه","topicNo":61,"sp":2,"spl":"سياط يوصي بالمحافظة على غنائه — من المائة المختارة","partial":1},
{"id":"b61-4","bab":"الجزء 6","sec":"نسبة هذا الصوت","page":"ج6 ص166","text":"صوت\n(ضاف قلبي الهوى فأكثر سهوي ... وجوي الحب مفظع غير خلو)\n(لو علا بعض ما علاني ثبيرا ... ظل ضعفا ثبير من ذاك يهوي)\n(من يكن من هوى الغواني خليا ... يا ثقاتي فإنني غير خلو)\nلغناء لسياط ثاني ثقيل بالوسطى في مجراها عن إسحاق صوت","topic":"أخبار سياط ونسبه","topicNo":61,"sp":2,"spl":"سياط يوصي بالمحافظة على غنائه — من المائة المختارة"},
{"id":"b61-5","bab":"الجزء 6","sec":"من المائة المختارة","page":"ج6 ص167","text":"(يا أم عمرو لقد طالبت ودكم ... جهدي وأعذرت فيه كل إعذار)\n(حتى سقمت وقد أصبحت سالمة ... مما أعالج من هم وتذكار)\nم يسم قائل هذا الشعر والغناء للرطاب والرطاب مدني قليل الصنعة ليس بمشهور وقيل له الرطاب لأنه كان يبيع الرطب بالمدينة ولحنه المختار هزج بالوسطى\nصوت من المائة المختارة\n(تصدع الأنس الجميع ... أمسى فقلبي به صدوع)\n(في إثرهم وجفون عيني ... مخضلة كلها دموع)\nم يسم لنا قائل هذا الشعر ولا عرفناه والغناء لدكين بن يزيد الكوفي ولحنه المختار من خفيف الثقيل بالوسطى وهكذا ذكر إسحاق في الألحان المختارة للواثق وذكر هذا الصوت في مجرد شجا فنسبه إلى دكين وجنسه في الثقيل الأول بإطلاق الوتر في مجرى الوسطى وذكر أيضا فيه لحنا من القدر الأوسط من الثقيل الأول بالخصر في مجرى البنصر فزعم أنه ينسب إلى معبد وإلى الغريض وفيه بيتان آخران وهما\n(فالقلب إن سيم عنك صبرا ... كلف ما ليس يستطيع)\n(عاص لمن لام في هواكم ... وهو لكم سامع مطيع)\nصوت","topic":"أخبار سياط ونسبه","topicNo":61,"sp":2,"spl":"سياط يوصي بالمحافظة على غنائه — من المائة المختارة"},
{"id":"b61-6","bab":"الجزء 6","sec":"من المائة المختارة","page":"ج6 ص168","text":"(يأيها الرجل الذي ... قد زان منطقه البيان)\n(لا تعتبن على الزمان ... فليس يعتبك الزمان)\nلشعر لعبد الله بن هارون العروضي والغناء لنبيه المغني ولحنه المختار ثقيل أول بالبنصر فأما عبد الله بن هارون فما أعلم أنه وقع إلي له خبر إلا ما شهر من حاله في نفسه وهو عبد الله بن هارون بن السميد مولى قريش من أهل البصرة وأخذ العروض من الخليل بن أحمد فكان مقدما فيه وانقطع إلى آل سليمان بن علي وأدب أولادهم وكان يمدحهم كثيرا فأكثر شعره فيهم وهو مقل جدا وكان يقول أوزانا من العروض غريبة في شعره ثم أخذ ذلك عنه ونحا نحوه فيه رزين العروضي فأتى فيه ببدائع جمة وجعل أكثر شعره من هذا الجنس فأما عبد الله ابن هارون فما عرفت له خبرا ولا وقع إلي من أمره شيء غير ما ذكرته","topic":"أخبار سياط ونسبه","topicNo":61,"sp":3,"spl":"من المائة المختارة"},
{"id":"b62-1","bab":"الجزء 6","sec":"ذكر نبيه وأخباره","page":"ج6 ص170","text":"زعم ابن خرداذبه أنه من بني تميم صليبة وأن أصله من الكوفة وأنه كان في أول أمره شاعرا لا يغني ويقول شعرا صالحا فهوي قينة ببغداد فتعلم الغناء من أجلها وجعله سببا للدخول عليها ولم يزل يتزيد حتى جاد غناؤه وصنع فأحسن واشتهر ودون غناؤه وعد في المحسنين فمما قاله في هذه الجارية وغنى فيه قوله صوت\n(يا رب إني ما جفوت وقد جفت ... فاليك أشكو ذاك يا رباه)\n(مولاة سوس ما ترق لعبدها ... نعم الغلام وبئست المولاه)\n(يا رب إن كانت حياتي هكذا ... ضررا علي فما أريد حياه)\nلغناء لنبيه ثاني ثقيل مطلق في مجرى الوسطى ومن الناس من ينسب الشعر والغناء إلى علية بنت المهدي أخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة قال قلت لمخارق وقد غنى هذا الصوت يوما\n(متى تجمع القلب الذكي وصارما ... وأنفا حميا تجتنبك المظالم)\nسألته لمن هو فقال هذا لنبيه التميمي وكان له أخوان يقال لهما منبه ونبهان وكان ينزل شهارسوج الهيثم في درب الريحان قال أبو زيد وسمعت مخارقا يحدث إسحاق بن إبراهيم قال سمعت أباك إبراهيم بن ميمون يقول وقد ذكر نبيها إن عاش هذا الغلام ذهب خبرنا قال وكنت قد غنيته صوتا أخذته عنه وهو\n(شكوت إلى قلبي الفراق فقال لي ... من الآن فاياس لا أغرك بالصبر)\n(إذا صد من أهوى وأسلمني العزا ... ففرقة من أهوى أحر من الجمر)\nخبرنا الحسن بن علي قال حدثنا محمد بن القاسم بن مهروية قال حدثني ابن أبي سعد عن محمد بن عبد الله بن مالك قال حدثني علي بن المفضل قال إصطبحنا يوما أنا ونبيه عند عبيد الله بن أبي غسان فغنانا نبيه لحنه\n(يأيها الرجل الذي ... قد زان منطقه البيان)\nما سمعت أحسن منه وكان صوتنا عليه بقية يومنا ثم أردنا الإنصراف فسألنا عبيد الله أن نبيت عنده ونصطبح من غد فأجبناه وقال لنبيه أي شيء تشتهي أن يصلح لك قال تشتري لي غزالا فتطعمني كبده كبابا وتجعل سائر ما آكله من لحمه كما تحب فقال أفعل فلما أصبحنا جاءه بغزال فأصلحه كما أحب فلما\nاستوفى أكله استلقى لينام فحركناه فإذا هو ميت فجزعنا من ذلك وبعث عبيد الله إلى أمه فجاءت فأخبرها بخبره فلما رأته استرجعت ثم قالت لا بأس عليكم هو رابع أربعة ولدتهم كانت هذه ميتتهم جميعا وميتة أبيهم من قبلهم فسكنا إلى ذلك وغسل في دار عبيد الله وأصلح شأنه وصلي عليه ومضينا به إلى مقابرهم فدفن هناك صوت","topic":"ذكر نبيه وأخباره","topicNo":62,"sp":0,"spl":"ذكر نبيه وأخباره — أخبار سليم"},
{"id":"b62-2","bab":"الجزء 6","sec":"من المائة المختارة","page":"ج6 ص172","text":"(وقفت على ربع لسعدى وعبرتي ... ترقرق في العينين ثم تسيل)\n(أسائل ربعا قد تعفت رسومه ... عليه لأصناف الرياح ذيول)\nم يسم لنا قائل هذا الشعر والغناء لسليم هزج خفيف بالسبابة في مجرى البنصر عن إسحاق","topic":"ذكر نبيه وأخباره","topicNo":62,"sp":0,"spl":"ذكر نبيه وأخباره — أخبار سليم"},
{"id":"b62-3","bab":"الجزء 6","sec":"أخبار سليم","page":"ج6 ص173","text":"هو سليم بن سلام الكوفي ويكنى أبا عبد الله وكان حسن الوجه حسن الصوت وقد انقطع وهو أمرد إلى إبراهيم الموصلي فمال إليه وتعشقه فعلمه وناصحه فبرع وكثرت روايته وصنع فأجاد وكان إسحاق يهجوه ويطعن عليه واتفق له اتفاق سيء كان يخدم الرشيد فيتفق مع ابن جامع وإبراهيم وإبنه إسحاق وفليح بن العوراء وحكم الوادي فيكون بالإضافة إليهم كالساقط وكان من أبخل الناس فلما مات خلف جملة عظيمة وافرة من المال فقبضها السلطان عنه أخبرنا يحيى بن علي بن يحيى عن أبيه أن إسحاق قال في سليم\n(سليم بن سلام على برد خلقه ... أحر غناء من حسين بن محرز)\nوأخبرنا إسماعيل بن يونس قال حدثنا عمر بن شبة عن إسحاق وأخبرنا\nيحيى بن علي عن أبيه عن إسحاق أن الرشيد قال لبرصوما الزامر وكانت فيه لكنة ما تقول في ابن جامع قال زق من أسل يريد من عسل قال فإبراهيم قال بستان فيه فاكهة وريحان وشوك قال فيزيد حوراء قال ما أبيد أسنانه يريد ما أبيض قال فحسين بن محرز قال ما أحسن خظامه يريد ما أحسن خضابه قال فسليم بن سلام قال ما أنظف ثيابه قال إسماعيل بن يونس في خبره عن عمر بن شبة عن إسحاق وغنى سليم يوما وبرصوما يزمر عليه بين يدي الرشيد فقصر سليم في موضع صيحة فأخرج برصوما الناي من فيه ثم صاح به وقال له يا أبا عبد الله صيهة أشد من هذا جهة أشد من هذا فضحك الرشيد حتى استلقى قال وما أذكر أني ضحكت قط أكثر من ذلك اليوم","topic":"ذكر نبيه وأخباره","topicNo":62,"sp":0,"spl":"ذكر نبيه وأخباره — أخبار سليم"},
{"id":"b62-4","bab":"الجزء 6","sec":"غنى الرشيد فوصله","page":"ج6 ص174","text":"أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه قال قال محمد بن الحسن بن مصعب إنما أخر سليما عن أصحابه في الصنعة ولعه بالأهزاج فإن ثلثي صنعته هزج وله من ذلك ما ليس لأحد منهم قال ثم قال محمد غني سليم يوما بين\nيدي الرشيد ثلاثة أصوات من الهزج ولاء أولها\n(مت على من غبت عنه أسفا ... )\nالثاني\n(أسرفت في الإعراض والهجر ... )\nالثالث\n(أصبح قلبي به ندوب ... )\nأطربه وأمر له بثلاثين ألف درهم وقال له لو كنت الحكم الوادي ما زدت على هذا الإحسان في أهزاجك يعني أن الحكم كان منفردا بالهزج","topic":"ذكر نبيه وأخباره","topicNo":62,"sp":1,"spl":"غنى الرشيد فوصله — نسبة هذه الأصوات","partial":1},
{"id":"b62-5","bab":"الجزء 6","sec":"نسبة هذه الأصوات","page":"ج6 ص175","text":"صوت\n(مت على من غبت عنه أسفا ... لست منه بمصيب خلفا)\n(لن ترى قرة عين أبدا ... أو ترى نحوهم منصرفا)\n(قلت لما شفني وجدي بهم ... حسبي الله لما بي وكفى)\n(بين الدمع لمن أبصرني ... ما تضمنت إذا ما ذرفا)\nالشعر للعباس بن الأحنف والغناء لسليم وله فيه لحنان أحدهما في الأول والثاني هزج بالوسطى والآخر في الثالث والرابع خفيف رمل بالبنصر مطلق\nوفيهما لإبراهيم خفيف ثقيل بالوسطى عن عمرو ومنها صوت\n(أسرفت في الإعراض والهجر ... وجزت حد التيه والكبر)\n(الهجر والإعراض من ذي الهوى ... سلم ذي الغدر إلى الغدر)\n(مالي وللهجران حسبي الذي ... مر على رأسي من الهجر)\n(ودون ما جربت فيما مضى ... ما عرف الخير من الشر)\nلغناء لسيلم هزج بالبنصر ومنها صوت\n(أصبح قلبي به ندوب ... أندبه الشادن الربيب)\n(تماديا منه في التصابي ... وقد علا رأسي المشيب)\n(أظنني ذائقا حمامي ... وأن إلمامه قريب)\n(إذا فؤاد شجاه حب ... فقلما ينفع الطبيب)\nلشعر لأبي نواس والغناء لسليم وله فيه لحنان خفيف رمل بالبنصر عن إسحاق وهزج بالوسطى عن الهشامي وزعمت بذل أن الهزج لها أخبرني عمي قال حدثنا أحمد بن أبي طاهر قال حدثني هارون بن مخارق عن أبيه قال كان سليم بن سلام كوفيا وكان أبوه من أصحاب أبي مسلم صاحب الدولة ودعاته وثقاته فكان يكاتب أهل العراق على يده وكان سليم حسن الصوت\nجهيره وكان بخيلا قال أحمد بن أبي طاهر وحدثني أبو الحواجب الأنصاري واسمه محمد قال قال لي سليم يوما امض إلى موسى بن إسحاق الأزرق فادعه ووافياني مع الظهر فجئناه مع الظهر فأخرج إلينا ثلاثين جارية محسنة ونبيذا ولم يطعمنا شيئا ولم نكن أكلنا شيئا فغمز موسى غلامه فذهب فاشترى لنا خبزا وبيضا فأدخله إلى الكنيف وجلسنا نأكل فدخل علينا فلما رآنا نأكل غضب وخاصمنا وقال أهكذا يفعل الناس تأكلون ولا تطعمونني وجلس معنا في الكنيف يأكل كما يأكل واحد منا حتى فني الخبز والبيض أخبرني الحسن بن علي قال حدثني الفضل بن محمد اليزيدي قال حدثني أبي قال كان سليم بن سلام صديقي وكان كثيرا ما يغشاني فجاءني يوما وأعلمني الغلام بمجيئه فأمرت بإدخاله فدخل وقال قد جئتك في حاجة فقلت مقضية فقال إن المهرجان بعد غد وقد أمرنا بحضور مجلس الخليفة وأريد أن أغنيه لحنا أصنعه في شعر لم يعرفه هو ولا من بحضرته فقل أبياتا أغني فيها ملاحا فقلت على أن تقيم عندي وتصنع بحضرتي اللحن قال أفعل فردوا دابته وأقام عندي وقلت صوت\n(أتيتك عائذا بك منك ... لما ضاقت الحيل)\n(وصيرني هواك وبي ... لحيني يضرب المثل)\n(فإن سلمت لكم نفسي ... فما لاقيته جلل)\n(وإن قتل الهوى رجلا ... فإني ذلك الرجل)\nفغنى فيه وشربنا يومئذ عليه وغنانا عدة أصوات من غنائه فما رأيته مذ عرفته كان أنشط منه يومئذ أخبرني أحمد بن عبيد الله بن عمار قل حدثني محمد بن داود بن الجراح قال حدثني عبد الله بن محمد اليزيدي قال حدثني أخي محمد قال سمعت أبي يقول ما سرقت من الشعر قط إلا معنيين قال مسلم بن الوليد\n(ذاك ظبي تحير الحسن في الأركان ... منه وجال كل مكان)\n(عرضت دونه الحجال فما يلقاك ... إلا في النوم أو في الأماني)\nاستعرت معناه فقلت صوت\n(يا بعيد الدار موصولا ... بقلبي ولساني)\n(ربما باعدك الدهر ... فأذنتك الأماني)\nلغناء في هذين البيتين لسليم هزج بالبنصر عن الهشامي قال وقال مسلم أيضا\n(متى ما تسمعي بقتيل أرض ... فإني ذلك الرجل القتيل)\nويروى أصيب فإنني ذاك القتيل فقلت\n(أتيتك عائذا بك منك ... لما ضاقت الحيل)\n(وصيرني هواك وبي ... لحيني يضرب المثل)\n(فإن سلمت لكم نفسي ... فما لاقيته جلل)\n(وإن قتل الهوى رجلا ... فإني ذلك الرجل)","topic":"ذكر نبيه وأخباره","topicNo":62,"sp":1,"spl":"غنى الرشيد فوصله — نسبة هذه الأصوات"},
{"id":"b62-6","bab":"الجزء 6","sec":"غنى ابن المهدي فأمر له بجائزة","page":"ج6 ص178","text":"وجدت في كتاب علي بن محمد بن نصر عن جده حمدون بن إسماعيل ولم أسمعه من أحد أن إبراهيم المهدي سأل جماعة من إخوانه أن يصطبحوا عنده قال حمدون وكنت فيهم وكان فيمن دعا مخارق فسار إليه وهو سكران لا فضل فيه لطعام ولا لشراب فاغتم لذلك إبراهيم وعاتبه على ما صنع فقال لا والله أيها الأمير ما كان آفتي إلا سليم بن سلام فإنه مر بي فدخل علي فغناني صوتا له صنعه قريبا فشربت عليه إلى السحر حتى لم يبق في فضل وأخذته فقال له إبراهيم فغنناه إملالا فغناه صوت\n(إذا كنت ندماني فباكر مدامة ... معتقة زفت إلى غير خاطب)\n(إذا عتقت في دنها العام أقبلت ... تردي رداء الحسن في عين شارب)\nلغناء لسليم خفيف ثقيل مطلق في مجرى البنصر قال فبعث إبراهيم إلى سليم فأحضره فغناه إياه وطرحه على جواريه وأمر له بجائزة وشربنا عليه بقية يومنا حتى صرنا في حالة مخارق وصار في مثل أحوالنا صوت","topic":"ذكر نبيه وأخباره","topicNo":62,"sp":2,"spl":"غنى ابن المهدي فأمر له بجائزة — من المائة المختارة"},
{"id":"b62-7","bab":"الجزء 6","sec":"من المائة المختارة","page":"ج6 ص179","text":"(عتق الفؤاد من الصبا ... ومن السفاهة والعلاق)\n(وحططت رحلي عن قلوص ... الحب في قلص عتاق)\n(ورفعت فضل إزاري ... المجرور عن قدمي وساقي)\n(وكففت غرب النفس حتى ... ما تتوق إلى متاق)\nم يقع إلينا قائل هذا الشعر والغناء لإبن عباد الكاتب ولحنه المختار من القدر الأوسط من الثقيل الأول بإطلاق الوتر في مجرى البنصر عن إسحاق وفيه لإبراهيم خفيف ثقيل وقيل إنه لغيره بل قيل إنه لعمرو","topic":"ذكر نبيه وأخباره","topicNo":62,"sp":2,"spl":"غنى ابن المهدي فأمر له بجائزة — من المائة المختارة"},
{"id":"b62-8","bab":"الجزء 6","sec":"أخبار ابن عباد","page":"ج6 ص181","text":"هو محمد بن عباد مولى بني مخزوم وقيل إنه مولى بني جمح ويكنى أبا جعفر مكي من كبراء المغنين من الطبقة الثانية منهم وقد ذكره يونس الكاتب فيمن أخذ عنه الغناء متقن الصنعة كثيرها وكان أبوه من كتاب الديوان بمكة فلذلك قيل ابن عباد الكاتب أخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة عن إسحاق وأخبرني الحسين بن يحيى عن حماد عن أبيه عن عثمان بن حفص الثقفي عن أبي خالد الكناني عن ابن عباد الكاتب قال والله إني لأمشي بأعلى مكة في الشعب إذا أنا بمالك على حمار له ومعه فتيان من أهل المدينة فظننت أنهم قالوا له هذا ابن عباد فمال إلي فملت إليه فقال لي أنت ابن عباد قلت نعم قال مل معي ها هنا ففعلت فأدخلني شعب ابن عامر ثم أدخلني دهليز ابن عامر وقال غنني فقلت أغنيك هكذا وأنت مالك وقد كان يبلغني أنه يثلب أهل مكة ويتعصب عليهم فقال بالله إلا غنيتني صوتا من صنعتك فاندفعت فغنيته صوت\n(ألا يا صاحبي قفا قليلا ... على ربع تقادم بالمنيف)\n(فأمست دراهم شحطت وبانت ... وأضحى القلب يخفق ذا وجيف)\nما غنيته إياه إلا على احتشام فلما فرغت نظر إلي وقال لي قد والله أحسنت ولكن حلقك كأنه حلق زانية فقلت أما إذ أفلت منك بهذا فقد أفلت وهذا اللحن من صدور غناء ابن عباد ولحنه من الثقيل الثاني بإطلاق الوتر في مجرى الوسطى أخبرني يحيى بن علي بن يحيى وعيسى بن الحسين قالا حدثنا أبو أيوب المديني قال حدثني جماعة من أهل العلم أن ابن عباد الكاتب توفي ببغداد في الدولة العباسية ودفن بباب حرب وقال أبو أيوب أظنه فيمن قدم من مغني الحجاز على المهدي صوت","topic":"ذكر نبيه وأخباره","topicNo":62,"sp":2,"spl":"غنى ابن المهدي فأمر له بجائزة — من المائة المختارة"},
{"id":"b62-9","bab":"الجزء 6","sec":"من المائة المختارة","page":"ج6 ص182","text":"(يا طللا غيره بعدي ... صوب ربيع صادق الرعد)\n(أراك بعد الأنس ذا وحشة ... لست كما كنت على العهد)\n(مالي أبكي طللا كلما ... ساءلته عي عن الرد)\n(كان به ذو غنج أهيف ... أحور مطبوع على الصد)\nم يسم أبو أحمد قائل هذا الشعر والغناء ليحيى المكي ولحنه المختار من الهزج بالوسطى","topic":"ذكر نبيه وأخباره","topicNo":62,"sp":2,"spl":"غنى ابن المهدي فأمر له بجائزة — من المائة المختارة"},
{"id":"b63-1","bab":"الجزء 6","sec":"أخبار يحيى المكي ونسبه","page":"ج6 ص183","text":"هو يحيى بن مرزوق مولى بني أمية وكان يكتم ذلك لخدمته الخلفاء من بني العباس خوفا من أن يجتنبوه ويحتشموه فإذا سئل عن ولائه انتمى إلى قريش ولم يذكر البطن الذي ولاؤه لهم واستعفى من سأله عن ذلك ويكنى يحيى أبا عثمان وذكر ابن خرداذبه أنه مولى خزاعة وليس قوله مما يحصل لأنه لا يعتمد فيه على رواية ولا دراية أخبرني عبد الله بن الربيع أبو بكر الربيعي صديقنا رحمه الله قال حدثني وسواسة بن الموصلي وقد لقيت وسواسة هذا وهو أحمد بن إسماعيل بن إبراهيم وكان معلما ولم أسمع هذا منه فكتبته وأشياء أخر عن أبي بكر رحمه الله قال حدثني حماد بن إسحاق قال قال لي أبي سألت يحيى المكي عن ولائه فانتمى إلى قريش فاستزدته في الشرح فسألني أن أعفيه أخبرني عيسى بن الحسين الوراق ويحيى بن علي بن يحيى قالا حدثنا أبو أيوب المديني قال كان يحيى المكي يكنى أبا عثمان وهو مولى بني أمية وكان يكتم ذلك ويقول أنا مولى قريش ولما قال أعشى بني سليم يمدح دحمان\n(كانوا فحولا فصاروا عند حلبتهم ... لما انبرى لهم دحمان خصيانا)\n(فأبلغوه عن الأعشى مقالته ... أعشى سليم أبي عمرو سليمانا)\n(قولوا يقول أبو عمرو لصحبته ... ياليت دحمان قبل الموت غنانا)\nال أبان بن عبد الحميد اللاحقي ويقال إن ابنه حمدان بن أبان قالها والأشبه عندي أنها لأبان وما أظن ابنه أدرك يحيى\n(يا من يفضل دحمانا ويمدحه ... على المغنين طرا قلت بهتانا)\n(لو كنت جالست يحيى أو سمعت به ... لم تمتدح أبدا ما عشت إنسانا)\n(ولم تقل سفها في منية عرضت ... ياليت دحمان قبل الموت غنانا)\n(لقد عجبت لدحمان ومادحه ... لا كان مادح دحمان ولا كانا)\n(ما كان كابن صغير العين إذ جريا ... بل قام في غاية المجرى وما دانى)\n(بذ الجياد أبو بكر وصيرها ... من بعد ما قرحت جذعا وثنيانا)\nيعني بأبي بكر ابن صغير العين وهو من مغني مكة وله أخبار تذكر في موضعها إن شاء الله تعالى","topic":"أخبار يحيى المكي ونسبه","topicNo":63,"sp":0,"spl":"أخبار يحيى المكي ونسبه — منزلته في الغناء"},
{"id":"b63-2","bab":"الجزء 6","sec":"منزلته في الغناء","page":"ج6 ص184","text":"وعمر يحيى المكي مائة وعشرين سنة وأصاب بالغناء ما لم يصبه أحد من نظرائه ومات وهو صحيح السمع والبصر والعقل وكان قدم مع الحجازيين الذين قدموا على المهدي في أول خلافته فخرج أكثرهم وبقي يحيى بالعراق هو وولده يخدمون الخلفاء إلى أن انقرضوا وكان آخرهم محمد بن أحمد بن يحيى المكي وكان يغني مرتجلا ويحضر مجلس المعتمد مع المغنين فيوقع بقضيب على دواة ولقيه جماعة من أصحابنا وأخذ عنه جماعة ممن أدركنا من عجائز المغنيات منهم قمرية العمرية وكانت أم ولد عمرو بن بانة وممن أدركه من أصحابنا جحظة\nوكتبنا عنه عن ابن المكي هذا حكايات حسنة من أخبار أهله وكان ابن جامع وإبراهيم الموصلي وفليح يفزعون إليه في الغناء القديم ويأخذونه عنه ويعايي بعضهم بعضا بما يأخذه منه ويغرب به على أصحابه فإذا خرجت لهم الجوائز أخذوا منها ووفروا نصيبه وله صنعة عجيبة نادرة متقدمة وله كتاب في الأغاني ونسبها وأخبارها وأجناسها كبير جليل مشهور إلا أنه كان كالمطرح عند الرواة لكثرة تخليطه في رواياته والعمل على كتاب ابنه أحمد فإنه صحح كثيرا مما أفسده أبوه وأزال ما عرفه من تخاليط أبيه وحقق ما نسبه من الأغاني إلى صانعه وهو يشتمل على نحو ثلاثة آلاف صوت","topic":"أخبار يحيى المكي ونسبه","topicNo":63,"sp":0,"spl":"أخبار يحيى المكي ونسبه — منزلته في الغناء"},
{"id":"b63-3","bab":"الجزء 6","sec":"ألف كتابا في الأغاني وأهداه لعبد الله بن طاهر","page":"ج6 ص185","text":"أخبرني عبد الله بن الربيع قال حدثني وسواسة بن الموصلي قال حدثني محمد بن أحمد بن يحيى المكي قال عمل جدي كتابا في الأغاني وأهداه إلى عبد الله بن طاهر وهو يومئذ شاب حديث السن فاستحسنه وسر به ثم عرضه على إسحاق فعرفه عوارا كثيرا في نسبه لأن جدي كان لا يصحح لأحد نسبة صوت البتة وينسب صنعته إلى المتقدمين وينحل بعضهم صنعة بعض ضنا بذلك على غيره فسقط من عين عبد الله وبقي في خزانته ثم وقع إلى محمد بن عبد الله فدعا أبي وكان إليه محسنا وعليه مفضلا فعرضه عليه فقال له إن في هذه النسب تخليطا كثيرا خلطها أبي لضنه بهذه الشأن على الناس ولكني أعمل لك كتابا أصحح هذا وغيره فيه\nفعمل له كتابا فيه اثنا عشر ألف صوت وأهداه إليه فوصله محمد بثلاثين ألف درهم وصحح له الكتاب الأول أيضا فهو في أيدي الناس\nقال وسواسة وحدثني حماد أن أباه إسحاق كان يقدم يحيى المكي تقديما كثيرا ويفضله ويناضل أباه وابن جامع فيه ويقول ليس يخلو يحيى فيما يرويه من الغناء الذي لا يعرفه أحد منكم من\nأحد أمرين إما أن يكون محقا فيه كما يقول فقد علم ما جهلتم أو يكون من صنعته وقد نحله المتقدمون كما تقولن فهو أفضل له وأوضح لتقدمه عليكم قال وكان أبي يقول لولا ما أفسد به يحيى المكي نفسه من تخليطه في رواية الغناء على المتقدمين وإضافته إليهم ما ليس لهم وقلة ثباته على ما يحكيه من ذلك لما تقدمه أحد وقال محمد بن الحسن الكاتب كان يحيى يخلط في نسب الغناء تخليطا كثيرا ولا يزال يصنع الصوت بعد الصوت يتشبه فيه بالغريض مرة وبمعبد أخرى وبإبن سريج وابن محرز ويجتهد في إحكامه وإتقانه حتى يشتبه على سامعه فإذا حضر مجالس الخلفاء غناه على ما أحدث فيه من ذلك فيأتي بأحسن صنعة وأتقنها وليس أحد يعرفها فيسأل عن ذلك فيقول أخذته عن فلان وأخذه فلان عن يونس أو عن نظرائه من رواة الأوائل فلا يشك في قوله ولا يثبت لمباراته أحد ولا يقوم لمعارضته ولا يفي بها حتى نشأ إسحاق فضبط الغناء وأخذه من مظانه ودونه وكشف عوار يحيى في منحولاته وبينها للناس","topic":"أخبار يحيى المكي ونسبه","topicNo":63,"sp":1,"spl":"ألف كتابا في الأغاني وأهداه لعبد الله بن طاهر — إسحاق يظهر غلطه"},
{"id":"b63-4","bab":"الجزء 6","sec":"إسحاق يظهر غلطه","page":"ج6 ص186","text":"أخبرني عمي قال سمعت عبيد الله بن عبد الله بن طاهر يذكر عن أحمد ابن سعيد المالكي وكان مغنيا منقطعا إلى طاهر وولده وكان من القواد قال حضرت يحيى المكي يوما وقد غنى صوتا فسئل عنه فقال هذا لمالك ولم يحفظ أحمد بن سعيد الصوت ثم غنى لحنا لمالك فسئل عن صانعه فقال هذا لي فقال له إسحاق قلت ماذا فديتك وتضاحك به فسئل عن\nصانعه فأخبر به ثم غنى الصوت فخجل يحيى حتى أمسك عنه ثم غنى بعد ساعة في الثقيل الأول واللحن صوت\n(إن الخليط أجد فاحتملا ... واراد غيظك بالذي فعلا)\n(فظللت تأمل قرب أوبتهم ... والنفس مما تأمل الأملا)\nسئل عنه فنسبه إلى الغريض فقال له إسحاق يا أبا عثمان ليس هذا من نمط الغريض ولا طريقته في الغناء ولو شئت لأخذت ما لك وتركت للغريض ما له ولم تتعب فاستحيا يحيى ولم ينتفع بنفسه بقية يومه فلما انصرف بعث إلى إسحاق بألطاف كثيرة وبرواسع وكتب إليه يعاتبه ويستكف شره ويقول له لست من أقرانك فتضادني ولا أنا ممن يتصدى لمباغضتك ومباراتك فتكايدني ولأنت إلى أن أفيدك وأعطيك ما تعلم أنك لا تجده عند غيري فتسمو به على أكفائك أحوج منك إلى أن تباغضني فأعطي غيرك سلاحا إذا حمله عليك لم تقم له وأنت أولى وما تختار فعرف إسحاق صدق يحيى فكتب إليه يعتذر ورد الألطاف التي حملها إليه وحلف لا يعارضه بعدها وشرط عليه الوفاء بما وعده به من الفوائد فوفى له بها وأخذ منه كل ما أراد من غناء المتقدمين وكان إذا حز به مر في شيء منها فزع إليه فأفاده وعاونه ونصحه وما عاود إسحاق معارضته بعد ذلك وحذره يحيى فكان إذا سئل بحضرته عن شيء صدق فيه وإذا غاب إسحاق خلط فيما يسأل عنه قال وكان يحيى إذا صار إليه إسحاق يطلب منه شيئا أعطاه إياه وأفاده وناصحه ويقول لإبنه أحمد تعال حتى تأخذ مع أبي محمد ما الله يعلم أني كنت أبخل به عليك فضلا عن غيرك فيأخذه أحمد عن أبيه مع\nإسحاق قال وكان إسحاق بعد ذلك يتعصب ليحيى تعصبا شديدا ويصفه ويقدمه ويعترف برياسته وكذلك كان في وصف أحمد ابنه وتقريظه","topic":"أخبار يحيى المكي ونسبه","topicNo":63,"sp":1,"spl":"ألف كتابا في الأغاني وأهداه لعبد الله بن طاهر — إسحاق يظهر غلطه"},
{"id":"b63-5","bab":"الجزء 6","sec":"عدد أصواته التي صنعها","page":"ج6 ص188","text":"قال أحمد بن سعيد والإختلاف الواقع في كتب الأغاني إلى الآن من بقايا تخليط يحيى قال أحمد بن سعيد وكانت صنعة يحيى ثلاثة آلاف صوت منها زهاء ألف صوت لم يقاربه فيها أحد والباقي متوسط وذكر بعض أصحاب أحمد بن يحيى المكي عنه أنه سئل عن صنعة أبيه فقال الذي صح عندي منها ألف وثلثمائة صوت منها مائة وسبعون صوتا غلب فيها على الناس جميعا من تقدم منهم ومن تأخر فلم يقم له فيها أحد وقال حماد بن إسحاق قال لي أبي كان يحيى المكي يسأل عن الصوت وهو يعلم لمن هو فينسبه إلى غير صانعه فيحمل ذلك عنه كذلك ثم يسأله آخرون فينسبه غير تلك النسبة حتى طال ذلك وكثر منه وقل تحفظه فظهر عواره ولولا ذلك لما قاومه أحد وقال أحمد بن سعيد المالكي في خبره قال إسحاق يوما للرشيد قبل أن تصلح الحال بينه وبين يحيى المكي أتحب يا أمير المؤمنين أن أظهر لك كذب يحيى فيما ينسبه من الغناء قال نعم قال أعطني أي شعر شئت حتى أصنع فيه واسألني بحضرة يحيى عن نسبته فإني سأنسبه إلى رجل لا أصل له واسأل يحيى عنه إذا غنيته فإنه لا يمتنع من أن يدعي معرفته فأعطاه شعرا فصنع فيه لحنا وغناه الرشيد ثم قال له يسألني أمير المؤمنين عن نسبته بين يديه فلما حضر يحيى غناه إسحاق فسأله الرشيد\nلمن هذا اللحن فقال له إسحاق لغناديس المديني فأقبل الرشيد على يحيى فقال له أكنت لقيت غناديس المديني قال نعم لقيته وأخذت عنه صوتين ثم غنى صوتا وقال هذا أحدهما فلما خرج حلف إسحاق بالطلاق ثلاثا وعتق جواريه أن الله ما خلق أحدا اسمه غناديس ولا سمع في المغنين ولاغيرهم وأنه وضع ذلك الإسم في وقته ذلك لينكشف أمره حدثني أحمد بن جعفر جحظة قال حدثني محمد بن أحمد بن يحيى المكي المرتجل قال غني جدي يوما بين يدي الرشيد صوت\n(هل هيجتك مغاني الحي والدور ... فاشتقت إن الغريب الدار معذور)\n(وهل يحل بنا إذ عيشنا أنق ... بيض أوانس أمثال الدمى حور)\nالصنعة له خفيف ثقيل فسار إليه إسحاق وسأله أن يعيده إياه فقال نعم حبا وكرامة لك يابن أخي ولو غيرك يروم ذلك لبعد عليه وأعاده حتى أخذه إسحاق فلما انصرف بعث إلى جدي بتخت ثياب وخاتم ياقوت نفيس حدثني جحظة قال حدثني القاسم بن زرزور عن أبيه عن مولاه علي بن المارقي قال قال لي إبراهيم بن المهدي ويلك يا مارقي إن يحيى المكي غنى البارحة\nبحضرة أمير المؤمنين صوتا فيه ذكر زينب وقد كان النبيذ أخذ مني فأنسيت شعره واستعدته إياه فلم يعده فاحتل لي عليه حتى تأخذه لي منه ولك علي سبق فقال لي المارقي وأنا يومئذ غلامه اذهب إليه فقل له إني أسأله أن يكون اليوم عندي فمضيت إليه فجئته به فلما تغدوا وضع النبيذ فقال له المارقي إني كنت سمعتك تغني صوتا فيه زينب وأنا أحب أن آخذه منك وكان يحيى يوفي هذا الشأن حقه من الأستقصاء فلا يخرج عنه إلا بحذر ولا يدع الطلب والمسألة ولا يلقي صوتا إلا بعوض قال لي جحظة في هذا الفصل هذا فديتك فعل يحيى مع ما أفاده من المال ومع كرم من عاشره وخدمه من الخلفاء مثل الرشيد والبرامكة وسائر الناس لا يلام ولا يعاب ونحن مع هؤلاء السفل إن جئناهم نكارمهم تغافلوا عنا وإن أعطونا التزر اليسير منوا به علينا وعابونا فمن يلومني أن أشتمهم فقلت ما عليك لوم قال فقال له يحيى وأي شيء العوض إذا ألقيت عليك هذا الصوت قال ما تريد قال هذه الزربية الأرمينية كم تقعد عليها أما آن لك أن تملها قال بلى وهي لك قال وهذه الظباء الحرمية وأنا مكي لا أنت وأنا أولى بها قال هي لك وأمر بحملها معه فلما حصلت له قال المارقي يا غلام هات العود قال يحيى والميزان والدراهم وكان لا يغني أو يأخذ خمسين درهما فأعطاه إياه فألقى عليه قوله\n(بزينب ألمم قبل أن يرحل الركب ... وقل إن تملينا فما ملك القلب)\nلحنه لكردم ثقيل أول فلم يشك المارقي أنه قد أخذ الصوت الذي طلبه إبراهيم وأدرك حاجته فبكر إلى إبراهيم وقد أخذ الصوت فقال له قد جئتك","topic":"أخبار يحيى المكي ونسبه","topicNo":63,"sp":2,"spl":"عدد أصواته التي صنعها"},
{"id":"b63-6","bab":"الجزء 6","sec":"عدد أصواته التي صنعها","page":"ج6 ص188","text":"بالحاجة فدعا بالعود فغناه إياه فقال له لا والله ما هو هذا وقد خدعك فعاود الإحتيال عليه فبعثني إليه وبعث معي خمسين درهما فلما دخل إليه وأكلا وشربا قال له يحيى قد واليت بين دعواتك لي ولم تكن برا ولا وصولا فما هذا قالا شيء والله إلا محبتي للأخذ عنك والإقتباس منك فقال سرك الله فمه قال تذكرت الصوت الذي سألتك إياه فإذا ليس هو الذي ألقيت علي قال فتريد ماذا قال تذكر الصوت قال أفعل ثم اندفع فغناه\n(ألمم بزينب إن البين قد أفدا ... قل الثواء لئن كان الرحيل غدا)\nالغناء لمعبد ثقيل أول فقال له نعم فديتك يا أبا عثمان هذا هو ألقه علي قال العوض قال ما شئت قال هذا المطرف الأسود قال هو لك فأخذه وألقى عليه هذا الصوت حتى استوى له وبكر إلى إبراهيم فقال له ما وراءك قال قد فضيت الحاجة فدعا له بعود فغناه فقال خدعك والله ليس هذا هو فعاود الإحتيال عليه وكل ما تعطيه إياه ففي ذمتي فلما كان اليوم الثالث بعث بي إليه فدعوته وفعلنا مثل فعلنا بالأمس فقال له يحيى فمالك أيضا قال له يا أبا عثمان ليس هذا الصوت هو الذي أردت فقال له لست أعلم ما في نفسك فأذكره وإنما علي أن أذكر ما فيه زينب من الغناء كما التمست حتى لا يبقى عندي زينب البتة إلا أحضرتها فقال هات على اسم الله فقال اذكر العوض قلت ما شئت قال هذه الدراعة الوشي التي عليك قال فخذها والخمسين الدرهم فأحضرها فألقى عليه والغناء لمعبد ثقيل أول\n(لزينب طيف تعتريني طوارقه ... هدوءا إذا النجم ارجحنت لواحقه)\nفأخذه منه ومضى إلى إبراهيم فصادفه يشرب مع الحرم فقال له حاجبه هو متشاغل فقال قل له قد جئتك بحاجتك فدخل فأعلمه فقال يدخل فيغنيه في الدار وهو قائم فإن كان هو وإلا فليخرج ففعل فقال لا والله ما هو هذا ولقد خدعك فعاود الإحتيال عليه ففعل مثل ذلك بيحيى فقال له يحيى وهو يضحك أما ظفرت بزينبك بعد فقال لا والله يا أبا عثمان وما أشك في أنك تعتمدني بالمنع مما أريده وقد أخذت كل شيء عندي معابثة فضحك يحيى وقال قد استحييت منك الآن وأنا ناصحك على شريطة قال نعم لك الشريطة قال لا تلمني في أن أعابثك لأنك أخذت في معابثتي والمطلوب إليه أقدر من الطالب فلا تعاود أن تحتال علي فإنك تظفر مني بما تريد إنما دسك إبراهيم بن المهدي علي لتأخذ مني صوتا غنيته فسألني إعادته فمنعته بخلا عليه لأنه لا يلحقني منه خير ولا بركة ويريد أن يأخذ غنائي باطلا وطمع بموضعك أن تأخذ الصوت بلا ثمن ولا حمد ولا والله إلا بأوفر ثمن وبعد اعترافك وإلا فلا تطمع في الصوت فقال له أما إذ فطنت فالأمر والله على ما قلت فتغنيه الآن بعينه على شرط أنه إن كان هو هو وإلا فعليك إعادته ولو غنيتني كل شيء تعرفه لم أحتسب لك إلا به قال اشتره فتساوما طويلا وماكسه حتى بلغ الصوت ألف درهم فدفعها إليه وألقى عليه صوت\n(طرقتك زينب والمزار بعيد ... بمنى ونحن معرسون هجود)\n(فكأنما طرقت بريا روضة ... أنف تسحسح مزنها وتجود)\nحنه خفيف ثقيل قال وهو صوت كثير العمل حلو النغم محكم الصنعة صحيح القسمة حسن المقاطع فأخذه وبكر إلى إبراهيم بن المهدي فقال له قد أفقرني هذا الصوت وأعراني وأبلاني بوجه يحيى المكي وشحه وطلبه وشرهه وحدثه بالقصة فضحك إبراهيم وغناه إياه فقال هذا وأبيك هو بعينه فألقاه عليه حتى أخذه وأخلف عليه كل شيء أخذه يحيى منه وزاده خمسة آلاف درهم وحمله على برذون أشهب فاره بسرجه ولجامه فقال له يا سيدي فغلامك زرزور المسكين قد تردد عليه حتى ظلع هب له شيئا فأمر له بألف درهم","topic":"أخبار يحيى المكي ونسبه","topicNo":63,"sp":3,"spl":"عدد أصواته التي صنعها"},
{"id":"b63-7","bab":"الجزء 6","sec":"غناؤه للأمين وللرشيد","page":"ج6 ص193","text":"حدثني جحظة قال حدثني هبة الله بن إبراهيم بن المهدي قال حدثني ريق وشارية جميعا قالتا كان مولانا تعنيان أبي في مجلس محمد الأمين يوما والمغنون حضور\nفغنى يحيى المكي واللحن له خفيف ثقيل صوت\n(خليل لي أهيم به ... فما كافا ولا شكرا)\n(بلى يدعى له باسمي ... إذا ما ريع أو عثرا)\nاسترده سيدنا وأحب أن يأخذه فجعل يحيى يفسده وفطن الأمين بذلك فأمر له بعشرين ألف درهم وأمره برده وترك التخليط فدعا له وقبل الأرض بين يديه ورد الصوت وجوده ثم استعاده فقال له يحيى ليست تطيب لك نفسي به إلا بعوض من مالك ولا أنصحك والله فيه فهذا مال مولاي أخذته فلم تأخذ أنت غنائي فضحك الأمين وحكم على إبراهيم بعشرة آلاف درهم فأحضرها فقبل يحيى يده وأعاد الصوت وجوده فنظر إلى مخارق وعلويه يتطلعان لأخذه فقطع الصوت ثم أقبل عليهما وقال قطعة من خصية الشيخ تغطي أستاه عدة صبيان والله لا أعدته بحضرتكما ثم أقبل على مولانا تعنيان إبراهيم بن المهدي فقال يا سيدي إني أصير إليك حتى تأخذه عني متمكنا ولا يشركك فيه أحد فصار إليه فأعاده حتى أخذه عنه وأخذناه معه أخبرنا يحيى بن علي بن يحيى قال حدثنا أبو أيوب المديني قال حدثني أحمد بن يحيى المكي عن أبيه قال\nأرسل إلي هارون الرشيد فدخلت إليه وهو جالس على كرسي بتل دارا فقال يا يحيى غنني\n(متى تلتقي الألاف والعيس كلما ... تصعدن من واد هبطن إلى واد)\nلم أزل أغنيه إياه ويتناول قدحا إلى أن أمسى فعددت عشر مرات استعاد فيها الصوت وشرب عشرة أقداح ثم أمر لي بعشرة آلاف درهم وأمرني بالإنصراف وقال محمد بن أحمد بن يحيى المكي في خبره حدثني أبي أحمد بن يحيى قال قال لي إسحاق يا أبا جعفر لأبيك مائة وسعبون صوتا من أخذها عنه بمائة وسبعين ألف درهم فهو الرابح فقلت لأبي أي شيء تعرف منها فقال لحنه في شعر الأخطل صوت\n(خف القطين فراحوا منك وابتكروا ... وأزعجتهم نوى في صرفها غير)\n(كأنني شارب يوم استبد بهم ... من قهوة عتقتها حمص أو جدر)\nحن يحيى المكي في هذين البيتين ثقيل أول هكذا في الخبر ولإبراهيم فيهما ثقيل أول آخر ولابن سريج رمل قال ومنهما صوت\n(بان الخليط فما أؤمله ... وعفا من الروحاء منزله)\n(ما ظبية أدماء عاطلة ... تحنو على طفل تطفله)\nحن يحيى في هذا الشعر ثاني ثقيل بالبنصر قال أحمد قال لي إسحاق وددت أن هذا الصوت لي أو لأبي وأني مغرم عشرة آلاف درهم ثم قال هل سمعتم بأحسن من قوله على طفل تطفله قال ومنها صوت\n(وكف كعواذ النقا لا يضيرها ... إذا برزت ألا يكون خضاب)\n(أنامل فتخ لا ترى بأصولها ... ضمورا ولم تظهر لهن كعاب)\nلحنه من الثقيل الثاني قال ومنها صوت\n(صادتك هند وتلك عادتها ... فالقلب مما يشفه كمد)\n(كم تشتكي الشوق من صبابتها ... ولا تبالي هند بما تجد)\nلحنه من خفيف الثقيل قال ومنها صوت\n(أعسيت من سلمى هواك ... اليوم محتلا جديدا)\n(ومرابط الخيل الجياد ... ومنزلا خلقا همودا)\nلحنه خفيف ثقيل أيضا قال ومنها صوت\n(ألا مرحبا بخيال ألم ... وإن هاج للقلب طول الألم)\n(خيال لأسماء يعتادني ... إذا الليل مد رواق الظلم)\nلحنه ثقيل أول قال ومنها صوت\n(كم ليلة ظلماء فيك سريتها ... أتعبت فيها صحبتي وركابي)\n(لا يبصر الكلب السروق خباءها ... ومواضع الأوتاد والأطناب)\nحنه ثاني ثقيل بالوسطى وفيه خفيف ثقيل بالوسطى للغريض قال ابن المكي غنى أبي الرشيد ليلة هذا الصوت فأطربه ثم قال له ثم يا يحيى فخذ ما في ذلك البيت فظنه فرشا أو ثيابا فإذا فيه أكياس فيها عين وورق فحملت بين يديه فكانت خمسين ألف درهم مع قيمة العين قال ومنها صوت\n(إني امرؤ مالي يقي عرضي ... ويبيت جاري آمنا جهلي)\n(وأرى الذمامة للرفيق إذا ... ألقى رحالته إلى رحلي)\nلحنه خفيف ثقيل قال ابن المكي غنى ابن جامع الرشيد يوما البيت الأول من هذين البيتين ولم يزد عليه شيئا فأعجب به الرشيد واسترده مرارا وأسكت لإبن جامع المغنين جميعا وجعل يسمعه ويشرب عليه ثم أمر له بعشرة آلاف","topic":"أخبار يحيى المكي ونسبه","topicNo":63,"sp":4,"spl":"غناؤه للأمين وللرشيد"},
{"id":"b63-8","bab":"الجزء 6","sec":"غناؤه للأمين وللرشيد","page":"ج6 ص193","text":"درهم وعشرة خواتيم وعشر خلع وانصرف فمضى إبراهيم من وجهه إلى يحيى المكي فأستأذن عليه فأذن له فأخبره بالذي كان من أمر ابن جامع واستغاث به فقال له يحيى أفزاد على البيت الأول شيئا قال لا قال أفرأيت إن زدتك بيتا ثانيا لم يعرفه إسماعيل أو عرفه ثم أنسيه وطرحته عليك حتى تأخذه ما تجعل لي قال النصف مما يصل إلي بهذا السبب قال والله فأخذ بذلك عليه عهدا وشرطا واستحلفه عليه أيمانا مؤكدة ثم زاده البيت الثاني وألقاه عليه حتى أخذه وانصرف فلما حضر المغنون من غد ودعي به كان أول صوت غناه إبراهيم هذا الصوت وجاء بالبيت الثاني وتحفظ فيه فأصاب وأحسن كل الإحسان وشرب عليه الرشيد واستعاده حتى سكر وأمر لإبراهيم بعشرة آلاف درهم وعشرة خواتيم وعشر خلع فحمل ذلك كله وانصرف من وجهه ذلك إلى يحيى فقاسمه ومضى إلى منزله وانصرف ابن جامع إليه من دار الرشيد وكان يحيى في بقايا علة فاحتجب عنه فدفع ابن جامع في صدر بوابه ودخل إليه فقال له إيه يا يحيى كيف صنعت ألقيت الصوت على الجرمقاني لا دفع الله صرعتك ولا وهب لك العافية وتشاتما ساعة ثم خرج ابن جامع من عنده وهو مدوخ","topic":"أخبار يحيى المكي ونسبه","topicNo":63,"sp":5,"spl":"غناؤه للأمين وللرشيد — من المائة المختارة"},
{"id":"b63-9","bab":"الجزء 6","sec":"إسحاق الموصلي يمدحه في جمع المغنين","page":"ج6 ص199","text":"حدثني عمي قال حدثني هارون بن محمد بن عبد الملك قال حدثني محمد بن أحمد بن يحيى المكي عن أبيه قال قال لي إسحاق كنت أنا وأبوك وابن جامع وفليح بن أبي العوراء وزبير بن دحمان يوما عند الفضل بن الربيع فانبرى زبير بن دحمان لأبيك يعني يحيى فجعلا يغنيان\nويباري كل واحد منهما صاحبه وذلك يعجب الفضل وكان يتعصب لأبيك ويعجب به فلما طال الأمر بينهما قال له الزبير أنت تنتحل غناء الناس وتدعيه وتنحلهم ما ليس لهم فأقبل الفضل علي وقال احكم أيها الحاكم بينهما فلم يخف عليك ما هما فيه فقلت لئن كان ما يرويه يحيى ويغنيه شيئا لغيره فلقد روى ما لم يرووه وما لم نروه وعلم ما جهلناه وجهلوه ولئن كان من صنعته إنه لأحسن الناس صنعة وما أعرف أحدا أروى منه ولا أصح أداء للغناء كان ما يغنيه له أو لغيره فسر بذلك الفضل وأعجبه وما زال أبوك يشكره لي صوت","topic":"أخبار يحيى المكي ونسبه","topicNo":63,"sp":5,"spl":"غناؤه للأمين وللرشيد — من المائة المختارة"},
{"id":"b63-10","bab":"الجزء 6","sec":"من المائة المختارة","page":"ج6 ص200","text":"(أهاجتك الظعائن يوم بانوا ... بذي الزي الجميل من الأثاث)\n(ظعائن أسلكت نقب المنقى ... تحث إذا ونت أي احتثاث)\nلشعر للنميري والغناء للغريض ولحنه المختار ثقيل أول بإطلاق الوتر في مجرى البنصر","topic":"أخبار يحيى المكي ونسبه","topicNo":63,"sp":5,"spl":"غناؤه للأمين وللرشيد — من المائة المختارة"},
{"id":"b64-1","bab":"الجزء 6","sec":"أخبار النميري ونسبه","page":"ج6 ص201","text":"هو محمد بن عبد الله بن نمير بن خرشة بن ربيعة بن حبيب بن الحارث بن مالك بن حطيط بن جشم بن قسي وقسي هو ثقيف شاعر غزل مولد ومنشؤه بالطائف من شعراء الدولة الأموية وكان يهوى زينب بنت يوسف بن الحكم أخت الحجاج بن يوسف وله فيها أشعار يتشبب بها حدثني محمد بن خلف بن المرزبان قال حدثنا أحمد بن الهيثم قال حدثنا العمري عن لقيط بن بكير المحاربي وأخبرني أحمد بن عبيد الله بن عمار وأحمد بن عبد العزيز الجوهري وحبيب بن نصر المهلبي قالوا حدثنا عمر بن شبة أن النميري كان يهوى زينب بنت يوسف أخت الحجاج بن يوسف بن الحكم لأبيه وأمه وأمهما الفارعة بنت همام بن عروة بن مسعود الثقفي وكانت عند المغيرة بن شعبة فرآها بكرة وهي تتخلل فقال لها والله لئن كان من\nغداء لقد جشعت ولئن كان من عشاء لقد أنتنت وطلقها فقالت أبعدك الله فبئس بعل المرأة الحرة أنت والله ما هو إلا من شظية من سواكي استمسكت بين سنين من أسناني قال حبيب بن نصر خاصة في خبره قال عمر بن شبة حدثنا بذلك أبو عاصم النبيل أخبرني حبيب بن نصر قال حدثنا عمر بن شبة عن يعقوب بن داود الثقفي وحدثنا به ابن عمار والجوهري عن عمر بن شبة ولم يذكرا فيه يعقوب بن داود قالوا جميعا قال مسلم بن جندب الهذلي وكان قاضي الجماعة بالمدينة إني لمع محمد بن عبد الله بن نمير بنعمان وغلام يسير خلفه يشتمه أقبح الشتيمة فقلت من هذا فقال هذا الحجاج بن يوسف فإني ذكرت أخته في شعري فأحفظه ذلك قال عمر بن شبة في خبره وولدت الفارعة أم الحجاج من المغيرة بن شعبة بنتا فماتت فنازع الحجاج عروة بن المغيرة إلى ابن زياد في ميراثها فأغلظ الحجاج لعروة فأمر به ابن زياد فضرب أسواطا على رأسه وقال لأبي عبد الله تقول هذه المقالة وكان الحجاج حاقدا على آل زياد ينفيهم من آل أبي سفيان ويقول آل أبي سفيان سته حمش وآل زياد رسح حدل\nوكان يوسف بن الحكم اعتل علة فطالت عليه فنذرت زينب إن عوفي أن تمشي إلى البيت فعوفي فخرجت في نسوة فقطعن بطن وج وهو ثلثمائة ذراع في يوم جعلته مرحلة لثقل بدنها ولم تقطع ما بين مكة والطائف إلا في شهر فبينا هي تسير إذ لقيها إبراهيم بن عبد الله النميري أخو محمد بن عبد الله منصرفا من العمرة فلما قدم الطائف أتى محمدا يسلم عليه فقال له ألك علم بزينب قال نعم لقيتها بالهماء في بطن نعمان فقال ما أحسبك إلا وقد قلت شيئا قال نعم قلت بيتا واحدا وتناسيته كراهة أن ينشب بيننا وبين إخواننا شر فقال محمد هذه القصيدة وهي أول ما قاله صوت","topic":"أخبار النميري ونسبه","topicNo":64,"sp":0,"spl":"أخبار النميري ونسبه"},
{"id":"b64-2","bab":"الجزء 6","sec":"شعره في زينب","page":"ج6 ص203","text":"(تضوع مسكا بطن نعمان إذ مشت ... به زينب في نسوة عطرات)\n(فأصبح ما بين الهماء فحزوة ... إلى الماء ماء الجزع ذي العشرات)\n(له أرج من مجمر الهند ساطع ... تطلع رياه من الكفرات)\n(تهادين ما بين المحصب من منى ... وأقبلن لا شعثا ولا غبرات)\n(أعان الذي فوق السموات عرشه ... مواشي بالبطحاء مؤتجرات)\n(مررن بفخ ثم رحن عشية ... يلبين للرحمن معتمرات)\n(يخبئن أطراف البنان من التقى ... ويقتلن بالألحاظ مقتدرات)\n(تقسمن لبي يوم نعمان إنني ... رأيت فؤادي عارم النظرات)\n(جلون وجوها لم تلحها سمائم ... حرور ولم يشفعن بالسبرات)\n(فقلت يعافير الظباء تناولت ... نياع غصون المرد مهتصرات)\n(ولما رأت ركب النميري راعها ... وكن من أن يلقينه حذرات)\n(فأدنين حتى جاوز الركب دونها ... حجابا من القسي والحبرات)\n(فكدت اشتياقا نحوها وصبابة ... تقطع نفسي إثرها حسرات)\n(فراجعت نفسي والحفيظة بعدما ... بللت رداء العصب بالعبرات)\nنى ابن سريج في الأول وبعده مررن بفخ وبعده يخمرن أطراف البنان ولحنه ثاني ثقيل بالخنصر في مجرى البنصر عن إسحاق قال أبو زيد فبلغت هذه القصيدة عبد الملك بن مروان فكتب إلى الحجاج قد بلغني قول الخبيث في زينب فاله عنه وأعرض عن ذكره فإنك إن أدنيته أو عاتبته أطمعته وإن عاقبته صدقته أخبرني حبيب بن نصر المهلبي قال حدثنا عمر بن شبة قال حدثنا أبو سلمة الغفاري قال هرب النميري من الحجاج إلى عبد الملك واستجار به فقال له عبد الملك أنشدني ما قلت في زينب فأنشده فلما انتهى إلى قوله\n(ولما رأت ركب النميري أعرضت ... وكن من أن يلقينه حذرات)\nال له عبد الملك وما كان ركبك يا نميري قال أربعة أحمرة لي كنت أجلب عليها القطران وثلاثة أحمرة صحبتي تحمل البعر فضحك عبد الملك حتى\nاستغرب ضحكا ثم قال لقد عظمت أمرك وأمر ركبك وكتب له إلى الحجاج أن لا سبيل له عليه فلما أتاه بالكتاب وضعه ولم يقرأه ثم أقبل على يزيد بن أبي مسلم فقال له أنا بريء من بيعة أمير المؤمنين لئن لم ينشدني ما قال في زينب لآتين على نفسه ولئن أنشدني لأعفون عنه وهو إذا أنشدني آمن فقال له يزيد ويلك أنشده فأنشده قوله\n(تضوع مسكا بطن نعمان إذ مشت ... به زينب في نسوة خفرات)\nقال كذبت والله ما كانت تتعطر إذا خرجت من منزلها ثم أنشده حتى بلغ إلى قوله\n(ولما رأت ركب النميري راعها ... وكن من أن يلقينه حذرات)\nال له حق لها أن ترتاع لأنها من نسوة خفرات صالحات ثم أنشده حتى بلغ إلى قوله\n(مررن بفخ رائحات عشية ... يلبين للرحمن معتمرات)\nقال صدقت لقد كانت حجاجة صوامة ما علمتها ثم أنشده حتى بلغ إلى قوله\n(يخمرن أطراف البنان من التقى ... ويخرجن جنح الليل معتجرات)\nقال له صدقت هكذا كانت تفعل وهكذا المرأة الحرة المسلمة ثم قاله له ويحك إني أرى ارتياعك ارتياع مريب وقولك قول بريء وقد أمنتك ولم يعرض له قال أبو زيد وقيل إنه طالب عريفه به وأقسم لئن لم يجئه به ليضربن عنقه فجاءه به بعد هرب طويل منه فخاطبه بهذه المخاطبة\nقال أبو زيد وقال النميري في زينب أيضا صوت\n(طربت وشاقتك المنازل من جفن ... ألا ربما يعتادك الشوق بالحزن)\n(نظرت إلى أظعان زينب باللوى ... فأعولتها لو كان إعوالها يغني)\n(فوالله لا أنساك زينب مادعت ... مطوقة ورقاء شجوا على غصن)\n(فإن احتمال الحي يوم تحملوا ... عناك وهل يعنيك إلا الذي يعني)\n(ومرسلة في السر أن قد فضحتني ... وصرحت بإسمي في النسيب فماتكني)\n(وأشمت بي أهلي وجل عشيرتي ... ليهنئك ما تهواه إن كان ذا يهني)\n(وقد لامني فيها ابن عمي ناصحا ... فقلت له خذ لي فؤادي أو دعني)\nنى ابن سريج في الأول والثاني والخامس والسادس من هذه الأبيات لحنا من الرمل بالخنصر في مجرى البنصر عن إسحاق قال أبو زيد فيقال إنه بلغ زينب بنت يوسف قوله هذا فبكت فقالت لها خادمتها ما يبكيك فقالت أخشى أن يسمع بقوله هذا جاهل بي لا يعرفني ولا يعلم مذهبي فيراه حقا قال وقال النميري فيها أيضا\n(أهاجتك الظعائن يوم بانوا ... بذي الزي الجميل من الأثاث)\n(ظعائن أسلكت نقب المنقى ... تحث إذا ونت أي احتثاث)\n(تؤمل أن تلاقي أهل بصرى ... فيالك من لقاء مستراث)\n(كأن على الحدائج يوم بانوا ... نعاجا ترتعي بقل البراث)\n(يهيجني الحمام إذا تداعى ... كما سجع النوائح بالمراثي)","topic":"أخبار النميري ونسبه","topicNo":64,"sp":1,"spl":"شعره في زينب"},
{"id":"b64-3","bab":"الجزء 6","sec":"شعره في زينب","page":"ج6 ص203","text":"(كأن عيونهن من التبكي ... فصوص الجزع أو ينع الكباث)\n(ألاق أنت في الحجج البواقي ... كما لاقيت في الحجج الثلاث)\nخبرني الحسين بن يحيى عن حماد بن إسحاق قال قرأت على أبي حدثنا عثمان بن حفص وغيره أن يوسف بن الحكم قام إلى عبد الملك بن مروان لما بعث بالحجاج لحرب ابن الزبير وقال له يا أمير المؤمنين إن غلاما منا قال في ابنتي زينب ما لا يزال الرجل يقول مثله في بنت عمه وإن هذا يعني ابنه الحجاج لم يزل يتتوق إليه ويهم به وأنت الآن تبعثه إلى ما هناك وما آمنه عليه فدعا بالحجاج فقال له إن محمدا النميري جاري ولا سلطان لك عليه فلا تعرض له قال إسحاق فحدثني يعقوب بن داود الثقفي قال قال لي مسلم بن جندب الهذلي\nكنت مع النميري وقد قتل الحجاج عبد الله بن الزبير وجلس يدعو الناس للبيعة فتأخر النميري حتى كان في آخرهم فدعا به ثم قال له إن مكانك لم يخف علي ادن فبايع ثم قال له أنشدني ما قلت في زينب قال ما قلت إلا خيرا قال لتنشدني فأنشده قوله\n(تضوع مسكا بطن نعمان إذ مشت ... به زينت في نسوة عطرات)\n(أعان الذي فوق السموات عرشه ... مواشي بالبطحاء مؤتجرات)\n(يخمرن أطراف الأكف من التقى ... ويخرجن جنح الليل معتجرات)\nما ذكرت أيها الأمير إلا كرما وخيرا وطيبا قال فأنشد كلمتك كلها فأنت آمن فأنشده حتى بلغ إلى قوله\n(ولما رأت ركب النميري راعها ... وكن من أن يلقينه حذرات)\nفقال له وما كان ركبك قال والله ما كان إلا أربعة أحمرة تحمل القطران فضحك الحجاج وأمره بالإنصراف ولم يعرض له","topic":"أخبار النميري ونسبه","topicNo":64,"sp":2,"spl":"شعره في زينب — هربه من الحجاج"},
{"id":"b64-4","bab":"الجزء 6","sec":"هربه من الحجاج","page":"ج6 ص209","text":"أخبرني عمي قال حدثنا الكراني عن الخليل بن أسد عن العمري عن عطاء عن عاصم بن الحدثان قال كان ابن نمير الثقفي يشبب بزينب بنت يوسف بن الحكم فكان الحجاج يتهدده ويقول لولا أن يقول قائل صدق لقطعت لسانه فهرب إلى اليمن ثم ركب بحر عدن وقال في هربه\n(أتتني عن الحجاج والبحر بيننا ... عقارب تسري والعيون هواجع)\n(فضقت بها ذرعا وأجهشت خيفة ... ولم آمن الحجاج والأمر فاظع)\n(وحل بي الخطب الذي جاءني به ... سميع فليست تستقر الأضالع)\n(فبت أدير الأمر والرأي ليلتي ... وقد أخضلت خدي الدموع التوابع)\n(ولم أر خيرا لي من الصبر إنه ... أعف وخير إذ عرتني الفواجع)\n(وما أمنت نفسي الذي خفت شره ... ولا طاب لي مما خشيت المضاجع)\n(إلى أن بدا لي رأس إسبيل طالعا ... وإسبيل حصن لم تنله الأصابع)\n(فلي عن ثقيف إن هممت بنجوة ... مهامه تهوي بينهن الهجارع)\n(وفي الأرض ذات العرض عنك ابن يوسف ... إذا شئت منأى لا أبا لك واسع)\n(فإن نلتني حجاج فاشتف جاهدا ... فإن الذي لا يحفظ الله ضائع)\nطلبه الحجاج فلم يقدر عليه وطال على النميري مقامه هاربا واشتاق إلى وطنه فجاء حتى وقف على رأس الحجاج فقال له إيه يا نميري أنت القائل\n(فإن نلتني حجاج فاشتف جاهدا ... )\nقال بل أنا الذي أقول\n(أخاف من الحجاج ما لست حائفا ... من الأسد العرباض لم يثنه ذعر)\n(أخاف يديه أن تنالا مقاتلي ... بأبيض عضب ليس من دونه ستر)\nأنا الذي أقول\n(فهأنذا طوفت شرقا ومغربا ... وأبت وقد دوخت كل مكان)\n(فلو كانت العنقاء منك تطير بي ... لخلتك إلا أن تصد تراني)\nقال فتبسم الحجاج وأمنه وقال له لا تعاود ما تعلم وخلى سبيله","topic":"أخبار النميري ونسبه","topicNo":64,"sp":2,"spl":"شعره في زينب — هربه من الحجاج","partial":1},
{"id":"b64-5","bab":"الجزء 6","sec":"زواج زينب أخت الحجاج رجع الخبر إلى رواية حماد بن إسحاق","page":"ج6 ص211","text":"قال حماد فحدثني أبي قال ذكر المدائني وغيره أن الحجاج عرض على زينب أن يزوجها محمد بن القاسم بن محمد بن الحكم بن أبي عقيل وهو ابن سبع عشرة سنة وهو يومئذ أشرف ثقفي في زمانه\nأو الحكم بن أيوب بن أبي الحكم بن عقيل وهو شيخ كبير فاختارت الحكم فزوجها إياه فأخرجها إلى الشام وكان محمد بن رياط كريها وهو يومئذ يكري فلما ولي الحجاج العراق استعمل الحكم بن أيوب على البصرة فكلمته زينب في محمد بن رياط فولاه شرطته بالبصرة فكتب إليه الحجاج إنك وليت أعرابيا جافيا شرطتك وقد أجزنا ذلك لكلام من سألك فيه قال ثم أنكر الحكم بعض تعجرفه فعزله ثم استعمل الحجاج الحكم بن سعد العذري على البصرة وعزل الحكم بن أيوب عنها واستقدمه لبعض الأمر ثم رده بعد ذلك إلى البصرة وجهزه من ماله فلما قدم البصرة هيأت له زينب طعاما وخرجت متنزهة إلى بعض البساتين ومعها نسوة فقيل لها إن فيهن امرأة لم ير أحسن ساقا منها فقالت لها زينب أريني ساقك فقالت لا إلا بخلوة فقالت ذاك لك فكشفته لها فأعطتها ثلاثين دينارا وقالت اتخذي منها خلخالا قال وكان الحجاج وجه بزينب مع حرمه إلى الشام لما خرج ابن الأشعث خوفا عليهن فلما قتل ابن الأشعث كتب إلى عبد الملك بن مروان بالفتح وكتب مع الرسول كتابا إلى زينب يخبرها الخبر فأعطاها الكتاب وهي راكبة على بغلة في هودج فنشرته تقرؤه وسمعت البغلة قعقعة الكتاب فنفرت وسقطت زينب عنها فاندق عضداها وتهرا جوفها فماتت وعاد إليه الرسول الذي نفذ بالفتح بوفاة زينب فقال النميري يرثيها صوت\n(لزينب طيف تعتريني طوارقه ... هدوءا إذا النجم ارجحنت لواحقه)\n(سيبكيك مرنان العشي يجيبه ... لطيف بنان الكف درم مرافقه)\n(إذا ما بساط اللهو مد وألقيت ... للذاته أنماطه ونمارقه)\nناه معبد ولحنه ثقيل أول بالخنصر في مجرى البنصر عن إسحاق وما بقي من شعره من الأغاني في نسيب النميري لم نذكر طريقته وصانعه لنذكر أخباره معه صوت\n(تضوع مسكا بطن نعمان أن مشت ... به زينب في نسوة خفرات)\n(مررن بفخ رائحات عشية ... يلبين للرحمن معتمرات)\nلغناء لإبن سريج ثاني ثقيل بالخنصر في مجرى البنصر عن إسحاق أخبرني الحسين بن يحيى ومحمد بن مزيد قالا حدثنا حماد بن إسحاق عن أبيه عن المدائني عن عبد الله بن مسلم الفهري قال خرج عبد الله بن جعفر متنزها فصادف ابن سريج وعزة الميلاء متنزهين\nفأناخ ابن جعفر راحلته وقال لعزة غنيني فغنته ثم قال لإبن سريج غنني يا أبا يحيى فغناه لحنه في شعر النميري\n(تضوع مسكا بطن نعمان أن مشت ... )\nأمر براحلته فنحرت وشق حلته فألقى نصفها على عزة والنصف الآخر على ابن سريج فباع ابن سريج النصف الذي صار إليه بمائة وخمسين دينارا وكانت عزة إذا جلست في يوم زينة أو مباهاة ألقت النصف الآخر عليها تتجمل به أخبرني محمد بن خلف وكيع قال حدثني عبد الله بن أبي سعد قال حدثني الحسن بن علي بن منصور قال أخبرني أبو عتاب عن إبراهيم بن محمد بن العباس المطلبي أن سعيد بن المسيب مر في بعض أزقة مكة فسمع الأخضر الحربي يتغنى في دار العاص بن وائل\n(تضوع مسكا بطن نعمان إذ مشت ... به زينب في نسوة خفرات)\nفضرب برجله وقال هذا والله مما يلذ استماعه ثم قال\n(وليست كأخرى أوسعت جيب درعها ... وأبدت بنان الكف للجمرات)\n(وعلت بنان المسك وحفا مرجلا ... على مثل بدر لاح في الظلمات)\n(وقامت تراءى يوم جمع فأفتنت ... برؤيتها من راح من عرفات)\nال فكانوا يرون أن هذا الشعر لسعيد بن المسيب","topic":"أخبار النميري ونسبه","topicNo":64,"sp":3,"spl":"زواج زينب أخت الحجاج رجع الخبر إلى رواية حماد بن إسحاق","partialRef":{"sid":"b52-6","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b64-6","bab":"الجزء 6","sec":"عائشة بنت طلحة تستنشده شعره في زينب","page":"ج6 ص215","text":"أخبرني عمي قال حدثني الكراني قال حدثني عبد الرحمن بن عبد الله أخي الأصمعي عن عبد الله بن عمران الهروي وأخبرني محمد بن يحيى الصولي قال حدثني المغيرة بن محمد المهلبي قال حدثني محمد بن عبد الوهاب عن عبد الرحمن بن عبد الله عن عبد الله بن عمران الهروي قال لما تأيمت عائشة بنت طلحة كانت تقيم بمكة سنة وبالمدينة سنة\nوتخرج إلى مال لها عظيم بالطائف وقصر كان لها هناك فتتنزه فيه وتجلس بالعشيات فيتناضل بين يديها الرماة فمر بها النميري الشاعر فسألت عنه فنسب لها فقالت ائتوني به فأتوها به فقالت له أنشدني مما قلت في زينب فامتنع عليها وقال تلك ابنة عمي وقد صارت عظاما بالية قالت أقسمت عليك بالله إلا فعلت فأنشدها قوله\n(تضوع مسكا بطن نعمان أن مشت ... )\nلأبيات فقالت والله ما قلت إلا جميلا ولا ذكرت إلا كرما وطيبا ولا وصفت إلا دينا وتقى أعطوه ألف درهم فلما كانت الجمعة الأخرى تعرض لها فقالت علي به فأحضر فقالت له أنشدني من شعرك في زينب فقال لها أو أنشدك من شعر الحارث بن خالد فيك فوثب مواليها إليه فقالت دعوه فإنه أراد أن يستقيد لبنت عمه هات مما قال الحارث في فأنشدها\n(ظعن الأمير بأحسن الخلق ... وغدوا بلبك مطلع الشرق)\nفقالت والله ما ذكر إلا جميلا ذكر أني إذا صبحت زوجا بوجهي غدا بكواكب الطلق وأني غدوت مع أمير تزوجني إلى الشرق وأني أحسن الخلق في البيت ذي الحسب الرفيع أعطوه ألف درهم واكسوه حلتين ولا تعد لإتياننا بعد هذا يا نميري أخبرني إسماعيل بن يونس الشيعي قال حدثنا عمر بن شبة عن إسحاق وأخبرني الحسين بن يحيى عن حماد عن أبيه\nأن الرشيد غضب على إبراهيم أبيه بالرقة فحبسه مدة ثم اصطبح يوما فبينا هو على حاله إذ تذكره فقال لو كان الموصلي حاضرا لانتظم أمرنا وتم سرورنا قالوا يا أمير المؤمنين فجىء به فما له كبير ذنب فبعث فجيء به فلما دخل أطرق الرشيد فلم ينظر إليه وأومأ إليه من حضر بأن يغني فاندفع فغنى\n(تضوع مسكا بطن نعمان أن مشت ... به زينب في نسوة خفرات)\nما تمالك الرشيد أن حرك رأسه مرارا واهتز طربا ثم نظر إليه وقال أحسنت والله يا إبراهيم حلوا قيوده وغطوه بالخلع ففعل ذلك فقال يا سيدي رضاك أولا قال لو لم أرض ما فعلت هذا وأمر له بثلاثين ألف درهم ومما قاله النميري في زينب وغني فيه صوت\n(تشتو بمكة نعمة ... ومصيفها بالطائف)\n(أحبب بتلك مواقفا ... وبزينب من واقف)\n(وعزيزة لم يغدها ... بؤس وجفوة حائف)\n(غراء يحكيها الغزال ... بمقلة وسوالف)\nلغناء ليحيى المكي خفيف رمل عن الهشامي وذكر عمرو بن بانة أنه لإبن سريج وأنه بالبنصر ورغم الهشامي أن فيه لإبن المكي أيضا لحنا من الثقيل الأول ومن الغناء في أشعاره في زينب\nصوت\n(ألا من لقلب معنى غزل ... يحب المحلة أخت المحل)\n(تراءت لنا يوم فرع الاراك ... بين العشاء وبين الأصل)\n(كأن القرنفل والزنجبيل ... وريح الخزامى وذوب العسل)\n(يعل به برد أنيابها ... إذا ما صفا الكوكب المعتدل)\nلغناء لمعبد ثقيل أول بالسبابة في مجرى البنصر عن إسحاق وذكر يونس لمالك فيه لحنا في\n(كأن القرنقل والزنجبيل ... )\nوالبيت الذي بعده وبيتين آخرين وهما\n(وقالت لجارتها هل رأيت ... إذ أعرض الركب فعل الرجل)\n(وأن تبسمه ضاحكا ... أجد اشتياقا لقلب غزل)\nذكر حماد عن أبيه أن فيها للهذلي لحنا ولم يذكر طريقته المحل الذي عناه النميري ها هنا الحجاج بن يوسف سمي بذلك لإحلاله الكعبة وكان أهل الحجاز يسمونه بذلك ويسمي أهل الشأم عبد الله بن الزبير المحل لأنه أحل الكعبة زعموا أنه بمقامه فيها وكان أصحابه أحرقوها بنار إستضاؤوا بها فأخبرني الحسين بن يحيى المرداسي قال قال حماد بن إسحاق قرأت على أبي وبلغني أن إسماعيل بن علي بن عبد الله بن عباس تزوج أسماء بنت يعقوب امرأة من ولد عبد الله بن الزبير فزفت إليه من المدينة وهو بفارس فمرت\nبالأهواز على السيد الحميري فسأله عنها فنسبت له فقال فيها قوله\n(مرت تزف على بغلة ... وفوق رحالتها قبه)\n(زبيرية من بنات الذي ... أحل الحرام من الكعبة)\n(تزف إلى ملك ماجد ... فلا اجتمعا وبها الوجبه)\nقد قيل بأن الأبيات اللامية التي أولها\n(ألا من لقلب معنى غزل ... )\nلخالد بن يزيد بن معاوية في زوجته رملة بنت الزبير وقيل إنها لأبي شجرة السلمي","topic":"أخبار النميري ونسبه","topicNo":64,"sp":4,"spl":"عائشة بنت طلحة تستنشده شعره في زينب","partialRef":{"sid":"b52-6","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b64-7","bab":"الجزء 6","sec":"عائشة بنت طلحة تستنشده شعره في زينب","page":"ج6 ص215","text":"حدثني الحسين بن الطيب البلخي لالشاعر قال حدثنا قتيبة بن سعيد قال حدثنا أبو بكر بن شعيب بن الحبحاب المعولي قال كنت عند ابن سيرين فجاءه إنسان يسأله عن شيء من الشعر قبل صلاة العصر فأنشده ابن سيرين\n(كأن المدامة والزنجبيل ... وريح الخزامى وذوب العسل)\n(يعل به برد أنيابها ... إذا النجم وسط السماء اعتدا)\nقال الله أكبر ودخل في الصلاة صوت","topic":"أخبار النميري ونسبه","topicNo":64,"sp":5,"spl":"عائشة بنت طلحة تستنشده شعره في زينب — من المائة المختارة"},
{"id":"b64-8","bab":"الجزء 6","sec":"من المائة المختارة","page":"ج6 ص220","text":"(يا قلب ويحك لا يذهب بك الخرق ... إن الألى كنت تهواهم قد انطلقوا)\nيروى يذهب بك الحرق\n(ما بالهم لم يبالوا إذ هجرتهم ... وأنت من هجرتهم قد كدت تحترق)\nلشعر لوضاح اليمن والغناء لصباح الخياط ولحنه المختار ثقيل أول بالوسطى في مجراها وفي أبيات من هذه القصيدة ألحان عدة فجماعة من المغنين قد خلطوا معها غيرها من شعر الحارث بن خالد ومن شعر ابن هرمة فأخرت ذكرها\nإلى أن تنقضي أخبار وضاح ثم أذكرها بعد ذلك إن شاء الله تعالى","topic":"أخبار النميري ونسبه","topicNo":64,"sp":5,"spl":"عائشة بنت طلحة تستنشده شعره في زينب — من المائة المختارة"},
{"id":"b65-1","bab":"الجزء 6","sec":"أخبار وضاح اليمن ونسبه","page":"ج6 ص222","text":"وضاح لقب غلب عليه لجماله وبهائه واسمه عبد الرحمن بن إسماعيل بن عبد كلال بن داذ بن أبي جمد ثم يختلف في تحقيق نسبه فيقول قوم إنه من أولاد الفرس الذين قدموا اليمن مع وهرز لنصرة سيف بن ذي يزن على الحبشة ويزعم آخرون أنه من آل خولان بن عمرو بن قيس بن معاوية بن جشم بن عبد شمس بن وائل بن الغوث بن قطن بن عريب بن زهير بن أيمن بن الهميسع بن العرنجج وهو حمير بن سبأ بن يشجب بن يعرب وهو المرعف بن قحطان فممن ذكر أنه من حمير خالد بن كلثوم قال كان وضاح اليمن من أجمل العرب وكان أبوه إسماعيل بن داذ بن ابي جمد من آل خولان بن عمرو بن معاوية الحميري فمات أبوه وهو طفل فانتقلت أمه إلى أهلها وانقضت عدتها فتزوجت رجلا من أهلها من أولاد الفرس وشب وضاح في حجر زوج أمه فجاء عمه وجدته أم أبيه ومعهم جماعة من أهل بيته من حمير ثم من آل ذي قيفان ثم من آل ذي جدن يطلبونه فادعى زوج أمه أنه ولده فحاكموه فيه وأقاموا البينة أنه ولد على\nفراش إسماعيل بن عبد كلال أبيه فحكم به الحاكم لهم وقد كان اجتمع الحميريون والأبناء في أمره وحضر معهم فلما حكم به الحاكم للحميريين مسح يده على رأسه وأعجبه جماله وقال له إذهب فأنت وضاح اليمن لا من أتباع ذي يزن يعني الفرس الذين قدم بهم ابن ذي يزن لنصرته فعلقت به هذه الكلمة منذ يومئذ فلقب وضاح اليمن قال خالد وكانت أم داذ بن أبي جمد جدة وضاح كندية فذلك حيث يقول في بنات عمه\n(إن قلبي معلق بنساء ... واضحات الخدود لسن بهجن)\n(من بنات الكريم داذ وفي كندة ... ينسبن من أباة اللعن)\nقال أيضا يفتخر بجده أبي جمد\n(بنى لي إسماعيل مجدا مؤثلا ... وعبد كلال بعده وأبو جمد)\nخبرني محمد بن الحسن بن دريد قال حدثني عمي عن العباس بن هشام عن أبيه قال\nكان وضاح اليمن والمقنع الكندي وأبو زبيد الطائي يردون مواسم العرب مقنعين يسترون وجوههم خوفا من العين وحذرا على أنفسهم من النساء لجمالهم قال خالد بن كلثوم فحدثت بهذا الحديث مرة وأبو عبيدة معمر بن المثنى حاضر ذلك وكان يزعم أن وضاحا من الأبناء فقال أبو عبيدة داذ اسم فارسي فقلت له عبد كلال اسم يمان وأبو جمد كنية يمانية والعجم لا تكتني وفي اليمن جماعة قد تسموا بأبرهة وهو اسم حبشي فينبغي أن تنسبهم إلى الحبشة وأي شيء يكون إذا سمي عربي بإسم فارسي وليس كل من كني أبا بكر هو الصديق ولا من سمي عمرا هو الفاروق وإنما الأسماء علامات ودلالات لا توجب نسبا ولا تدفعه قال فوجم أبو عبيدة وأفحم فما أجاب وممن زعم أنه من أبناء الفرس ابن الكلبي ومحمد بن زياد الكلابي وقال خالد بن كلثوم إن أم إسماعيل أبي الوضاح بنت ذي جدن وأم أبيه بنت فرعان ذي الدروع الكندي من بني الحارث بن عمرو","topic":"أخبار وضاح اليمن ونسبه","topicNo":65,"sp":0,"spl":"أخبار وضاح اليمن ونسبه"},
{"id":"b65-2","bab":"الجزء 6","sec":"شعره في حبيبته روضة","page":"ج6 ص224","text":"وكان وضاح يهوى امرأة من أهل اليمن يقال لها روضة أخبرني محمد بن خلف بن المرزبان قال\nذكر هشام بن الكلبي أنها روضة بنت عمرو من ولد فرعان ذي الدروع الكندي أخبرني محمد بن خلف وكيع قال حدثني محمد بن سعيد الكراني قال حدثنا العمري عن الهيثم بن عدي عن عبد الله بن عياش أن وضاحا هوي امرأة من بنات الفرس يقال لها روضة فذهبت به كل مذهب وخطبها فامتنع قومها من تزويجه إياها وعاتبه أهله وعشيرته فقال في ذلك صوت\n(يأيها القلب بعض ما تجد ... قد يعشق المرء ثم يتئد)\n(قد يكتم المرء حبه حقبا ... وهو عميد وقلبه كمد)\n(ماذا تريدين من فتى غزل ... قد شفه السقم فيك والسهد)\n(يهددوني كيما أخافهم ... هيهات أني يهدد الأسد)\nلغناء لإبن محرز خفيف رمل بالوسطى عن عمرو وفيها لحن لإبن عباد من كتاب إبراهيم غير مجنس أخبرني محمد بن خلف بن المرزبان قال حدثني سالم بن زيد قال أخبرني التوزي قال حدثنا الأصمعي عن الخليل بن أحمد قال كان وضاح يهوى امرأة من كندة يقال لها روضة فلما اشتهر أمره معها خطبها فلم يزوجها وزوجت غيره فمكثت مدة طويلة ثم أتاه رجل من بلدها فأسر إليه شيئا فبكى فقال له أصحابه مالك تبكي وما خبرك فقال أخبرني هذا أن روضة قد جذمت وأنه رآها قد ألقيت مع المجذومين ولم نجد لهما\nخبرا يرويه أهل العلم إلا لمعا يسيرة وأشياء تدل على ذلك من شعره فأما خبر متصل فلم أجده إلا في كتاب مصنوع غث الحديث والشعر لا يذكر مثله وأصابها الجذام بعد ذلك فانقطع ما بينهما ثم شبب بأم البنين بنت عبد العزيز بن مروان زوجة الوليد بن عبد الملك فقتله الوليد لذلك وأخبارهما تذكر في موضعها بعقب هذه الحكاية أخبرني الحسن بن علي الخفاف قال حدثنا أحمد بن زهير بن حرب قال حدثنا مصعب بن عبد الله قال كان وضاح اليمن يهوى امرأة يقال لها روضة ويشبب بها في شعره وهي امرأة من أهل اليمن وفيها يقول صوت\n(يا روضة الوضاح قد ... عنيت وضاح اليمن)\n(فاسقي خليلك من شراب ... لم يكدره الدرن)\n(الريح ريح سفرجل ... والطعم طعم سلاف دن)\n(إني تهيجني إليك ... حمامتان على فنن)\nال مصعب فحدثني بعض أهل العلم ممن كان يعرف خبر وضاح مع روضة من أهل اليمن أن وضاحا كان في سفر مع أصحابه فبينا هو يسير إذ استوقفهم وعدل عنهم ساعة ثم عاد إليهم وهو يبكي فسألوه عن حاله فقال عدلت إلى روضة وكانت قد جذمت فجعلت مع المجذومين وأخرجت من بلدها فأصلحت من شأنها وأعطيتها صدرا من نفقتي وجعل يبكي غما بها الغناء في الأبيات المذكورة في هذا الخبر ينسب مع تمام الأبيات فإن في جميعها غناء\nومما قاله وضاح في روضة المذكورة وفيه غناء وأنشدنا حرمي عن الزبير عن عمه صوت\n(أيا روضة الوضاح يا خير روضة ... لأهلك لو جادوا علينا بمنزل)\n(رهينك وضاح ذهبت بعقله ... فإن شئت فاحييه وإن شئت فاقتلي)\n(وتوقد حينا باليلنجوج نارها ... وتوقد أحيانا بمسك ومندل)\nالأبيات الأول النونية فيها زيادة على ما رواه مصعب وفي سائرها غناء وتمامها بعد قوله\n(إني تهيجني إليك ... حمامتان على فنن)\n(الزوج يدعو إلفه ... فتطاعما حب السكن)\n(لا خير في نث الحديث ... ولا الجليس إذا فطن)\n(فاعصي الوشاة فإنما ... قول الوشاة هو الغبن)\n(إن الوشاة إذا أتوك ... تنصحوا ونهوك عن)\n(دست حبيبة موهنا ... إني وعيشك يا سكن)\n(أبلغت عنك تبدلا ... وأتى بذلك مؤتمن)\n(وظننت أنك قد فعلت ... فكدت من حزن أجن)\n(ذرفت دموعي ثم قلت ... بمن يبادلني بمن)\n(أسكت فلست مصدقا ... ما كان يفعل ذا أظن)\n(إني وجدك لو رأيت ... خليلنا ذاك الحسن)\n(يجفوه ثم يحبنا ... والله مت من الحزن)\n(أخبره إما جئته ... أن الفؤاد به يجن)\n(أبغضت فيه أحبتي ... وقليت أهلي والوطن)\n(أتركتني حتى إذا ... علقت أبيض كالشطن)\n(أنشأت تطلب وصلنا ... في الصيف ضيعت اللبن)\nكذا قال وغيره يرويه في الصيف ضيحت اللبن أي مذقته قال\n(لو قيل يا وضاح قم ... فاختر لنفسك أو تمن)\n(لم أعد روضة والذي ... ساق الحجيج له البدن)\nالغناء في الأول من القصيدة وهو يا روضة الوضاح ينسب إن شاء الله وله في روضة هذه أشعار كثيرة في أكثرها صنعة وبعضها لم يقع إلي أنه صنع فيه فمن قوله فيها صوت\n(يا روض جيرانكم الباكر ... فالقلب لا لاه ولا صابر)\n(قالت ألا لا تلجن دارنا ... إن أبانا رجل غائر)\n(قلت فإني طالب غرة ... منه وسيفي صارم باتر)","topic":"أخبار وضاح اليمن ونسبه","topicNo":65,"sp":1,"spl":"شعره في حبيبته روضة"},
{"id":"b65-3","bab":"الجزء 6","sec":"شعره في حبيبته روضة","page":"ج6 ص224","text":"(قالت فإن القصر من دوننا ... قلت فإني فوقه ظاهر)\n(قالت فإن البحر من دوننا ... قلت فإني سابح ماهر)\n(قالت فحولي إخوة سبعة ... قلت فإني غالب قاهر)\n(قالت فليث رابض بيننا ... قلت فإني أسد عاقر)\n(قالت فإن الله من فوقنا ... قلت فربي راحم غافر)\n(قالت لقد أعييتنا حجة ... فأت إذا ما هجع السامر)\n(فاسقط علينا كسقوط الندى ... ليلة لا ناه ولا زاجز)\nلغناء في هذه الأبيات هزج يمني وذكر يحيى المكي أنه له وقال في روضة وهو بالشام\n(أبت بالشام نفسي أن تطيبا ... تذكرت المنازل والحبيبا)\n(تذكرت المنازل من شعوب ... وحيا أصبحوا قطعوا شعوبا)\n(سبوا قلبي فحل بحيث حلوا ... ويعظم إن دعوا ألا يجيبا)\n(ألاى ليت الرياح لنا رسول ... إليكم إن شمالا أو جنوبا)\n(فتأتيكم بما قلنا سريعا ... ويبلغنا الذي قلتم قريبا)\n(ألا يا روض قد عذبت قلبي ... فأصبح من تذكركم كئيبا)\n(ورققني هواك وكنت جلدا ... وأبدى في مفارقي المشيبا)\n(أما ينسيك روضة شحط دار ... ولا قرب إذا كانت قريبا)\nمما قال فيها أيضا\n(طرب الفؤاد لطيف روضة غاشي ... والقوم بين أباطح وعشاش)\n(أنى اهتديت ودون أرضك سبسب ... قفر وحزن في دجى ورشاش)\n(قالت تكاليف المحب كلفتها ... إن المحب إذا أخيف لماشي)\n(أدعوك روضة رحب واسمك غيره ... شفقا وأخشى أن يشي بك واشي)\n(قالت فزرنا قلت كيف أزوركم ... وأنا امرؤ لخروج سرك خاشي)\n(قالت فكن لعمومتي سلما معا ... والطف لإخوتي الذين تماشي)\n(فتزورنا معهم زيارة آمن ... والسر يا وضاح ليس بفاشي)\n(ولقيتها تمشي بأبطح مرة ... بخلاخل وبحلة أكباش)\n(فظللت معمودا وبت مسهدا ... ودموع عيني في الرداء غواشي)\n(يا روض حبك سل جسمي وانتحى ... في العظم حتى قد بلغت مشاشي)\nمما قال فيها أيضا\n(طرق الخيال فمرحبا سهلا ... بخيال من أهدى لنا الوصلا)\n(وسرى إلي ودون منزله ... خمس دوائم تعمل الإبلا)\n(يا حبذا من زار معتسفا ... حزن البلاد إلي والسهلا)\n(حتى ألم بنا فبت به ... أغنى الخلائق كلهم شملا)\n(يا حبذا هي حسبك قدك في ... والله ما أبقيت لي عقلا)\n(والله ما لي عنك منصرف ... إلا إليك فأجملي الفعلا)","topic":"أخبار وضاح اليمن ونسبه","topicNo":65,"sp":2,"spl":"شعره في حبيبته روضة"},
{"id":"b65-4","bab":"الجزء 6","sec":"رأته أم البنين فهويته","page":"ج6 ص231","text":"أخبرني محمد بن خلف بن المرزبان قال حدثنا القاسم بن الحسن المروزي قال حدثنا العمري عن لقيط والهيثم بن عدي أن أم البنين بنت عبد العزيز بن مروان استأذنت الوليد بن عبد الملك في الحج فأذن لها وهو يومئذ خليفة وهي زوجته فقدمت مكة ومعها من الجواري ما لم ير مثله حسنا وكتب الوليد يتوعد الشعراء جميعا إن ذكرها أحد منهم أو ذكر أحدا ممن تبعها وقدمت فتراءت للناس وتصدى لها أهل الغزل والشعر ووقعت عينها على وضاح اليمن فهويته\nفحدثنا الحرمي بن أبي العلاء قال حدثنا الزبير ابن بكار قال حدثني إبراهيم بن محمد بن عبد العزيز الزهري عن محمد بن جعفر مولى أبي هريرة عن أبيه عن بديح قال قدمت أم البنين بنت عبد العزيز بن مروان وهي عند الوليد بن عبد الملك حاجة والوليد يومئذ خليفة فبعثت إلى كثير وإلى وضاح اليمن أن انسبا بي فأما وضاح اليمن فإنه ذكرها وصرح بالنسيب بها فوجد الوليد عليه السبيل فقتله وأما كثير فعدل عن ذكرها ونسب بجاريتها غاضرة فقال صوت\n(شجا أظعان غاضرة الغوادي ... بغير مشورة عرضا فؤادي)\n(أغاضر لو شهدت غداة بنتم ... حنو العائدات على وسادي)\n(أويت لعاشق لم تشكميه ... بواقدة تلذع كالزناد)\nلغناء في هذه الأبيات لإبن محرز ثقيل أول بالوسطى عن الهشامي وحبش قال بديح فكنت لما حجت أم البنين لا تشاء أن ترى وجها حسنا إلا رأيته معها فقلت لعبيد الله بن قيس الرقيات بمن تشبب من هذا القطين فقال لي\n(وما تصنع بالسر ... إذا لم تك مجنونا)\n(إذا عالجت ثقل الحب ... عالجت ألأمرينا)\n(وقد بحت بأمر كان ... في قلبي مكنونا)\n(وقد هجت بما حاولت ... أمرا كان مدفونا)\nال ثم خلا بي فقال لي اكتم علي فإنك موضع للأمانة وأنشدني صوت\n(أصحوت عن أم البنين ... وذكرها وعنائها)\n(وهجرتها هجر امرئ ... لم يقل صفو صفائها)\n(قرشية كالشمس أشرق ... نورها ببهائها)\n(زادت على البيض الحسان ... بحسنها ونقائها)\n(لما اسبكرت للشباب ... وقنعت بردائها)\n(لم تلتفت للداتها ... ومضت على غلوائها)\n(لولا هوى أم البنين ... وحاجتي للقائها)\n(قد قربت لي بغلة ... محبوسة لنجائها)\nال بديح فلما قتل الوليد وضاح اليمن حجت بعد ذلك أم البنين محتجبة لا تكلم أحدا وشخصت كذلك فلقيني ابن قيس الرقيات فقال يا بديح صوت\n(بان الحبيب الذي به تثق ... وإشتد دون الحبيبة القلق)\n(يا من لصفراء في مفاصلها ... لين وفي بعض بطشها خرق)\nهي قصيدة قد ذكرت مع أخبار ابن قيس الرقيات الغناء في الأبيات الأول التي أولها\n(أصحوت عن أم البنين ... )\nنسب في موضع آخر إن شاء الله أخبرني الحرمي قال حدثنا الزبير قال حدثني عمر بن أبي بكر المؤملي عن عبد الله بن أبي عبيدة قال حدثني كثير قال حججت مع أم البنين بنت عبد العزيز بن مروان وهي زوجة الوليد بن عبد الملك فأرسلت إلي وإلى وضاح اليمن أن انسبا بي فهبت ذلك ونسبت بجاريتها غاضرة فقلت\n(شجا أظعان غاضرة الغوادي ... بغير مشورة عرضا فؤادي)\n(أغاضر لو شهدت غداة بنتم ... حنو العائدات على وسادي)\n(أويت لعاشق لم تشكميه ... بواقدة تلذع كالزناد)\nأما وضاح فنسب بها فبلغ ذلك الوليد فطلبه فقتله أخبرني عمي قال حدثني محمد بن سعد الكراني قال حدثني أبو عمر العمري عن العتبي قال مدح وضاح اليمن الوليد بن عبد الملك وهو يومئذ خليفة ووعدته أم\nالبنين بنت عبد العزيز بن مروان أن ترفده عنده وتقوي أمره فقدم عليه وضاح وأنشده قوله فيه صوت\n(صبا قلبي ومال إليك ميلا ... وأرقني خيالك يا أثيلا)\n(يمانية تلم بنا فتبدي ... دقيق محاسن وتكن غيلا)\n(دعينا ما أممت بنات نعش ... من الطيف الذي ينتاب ليلا)\n(ولكن إن أردت فصبحينا ... إذا أمت ركائبنا سهيلا)\n(فإنك لو رأيت الخيل تعدو ... سراعا يتخذن النقع ذيلا)\n(إذا لرأيت فوق الخيل أسدا ... تفيد مغانما وتفيت نيلا)\n(إذا سار الوليد بنا وسرنا ... خيل نلف بهن خيلا)\n(وندخل بالسرور ديار قوم ... ونعقب آخرين أذى وويلا)\nأحسن الوليد رفده وأجزل صلته ومدحه بعدة قصائد ثم نمي إليه أنه شبب بأم البنين فجفاه وأمر بأن يحجب عنه ودبر في قتله ومدحه وضاح بقوله أيضا\n(ما بال عينك لا تنام كأنما ... طلب الطبيب بها قذى فأضله)\n(بل ما لقلبك لا يزال كأنه ... نشوان أنهله النديم وعله)\n(ما كنت أحسب أن أبيت ببلدة ... وأخي بأخرى لا أحل محله)","topic":"أخبار وضاح اليمن ونسبه","topicNo":65,"sp":3,"spl":"رأته أم البنين فهويته","partial":1},
{"id":"b65-5","bab":"الجزء 6","sec":"رأته أم البنين فهويته","page":"ج6 ص231","text":"(كنا لعمرك ناعمين بغبطة ... مع ما نحب مبيته ومظله)\n(فأرى الذي كنا وكان بغرة ... نلهوا بغرته ونهوى دله)\n(كالطيف وافق ذا هوى فلها به ... حتى إذا ذهب الرقاد أضله)\n(قل للذي شعف البلاء فؤاده ... لا تهلكن أخا فرب أخ له)\n(والق ابن مروان الذي قد هزه ... عرق المكارم والندى فأقله)\n(واشك الذي لاقيته من دونه ... وانشر إليه داء قلبك كله)\n(فعلى ابن مروان السلام من امرئ ... أمسى يذوق من الرقاد أقله)\n(شوقا إليك فما تنالك حاله ... وإذا يحل الباب لم يؤذن له)\n(فإليك أعملت المطايا ضمرا ... وقطعت أرواح الشتاء وظله)\n(ولياليا لو أن حاضر بثها ... طرف القضيب أصابه لأشله)\nلم يزل مجفوا حتى وجد الوليد له غرة فبعث إليه من اختلسه ليلا فجاءه به فقتله ودفنه في داره فلم يوقف له على خبر","topic":"أخبار وضاح اليمن ونسبه","topicNo":65,"sp":4,"spl":"رأته أم البنين فهويته"},
{"id":"b65-6","bab":"الجزء 6","sec":"الوليد يدفنه حيا","page":"ج6 ص236","text":"وقال خالد بن كلثوم في خبره كان وضاح قد شبب بأم البنين بنت عبد العزيز بن مروان إمرأة الوليد بن عبد الملك وهي أم ابنة عبد العزيز بن الوليد والشرف فيهم فبلغ الوليد تشببه بها فأمر بطلبه فأبى به فأمر بقتله فقال له ابنه عبد العزيز لا تفعل يا أمير المؤمنين فتحقق قوله ولكن افعل به كما فعل معاوية بأبي دهبل فإنه لما شبب بإبنته\nشكاه يزيد وسأله أن يقتله فقال إذاتحقق قوله ولكن تبره وتحسن إليه فيستحي ويكف ويكذب نفسه فلم يقبل منه وجعله في صندوق ودفنه حيا فوقع بين رجل من زنادقة الشعوبية وبين رجل من ولد الوليد فخار خرجا فيه إلى أن أغلظا المسابة وذلك في دولة بني العباس فوضع الشعوبي عليهم كتابا زعم فيه أن أم البنين عشقت وضاحا فكانت تدخله صندوقا عندها فوقف على ذلك خادم الوليد فأنهاه إليه وأراه الصندوق فدفنه هكذا ذكر خالد بن كلثوم والزبير بن بكار جميعا وأخبرني علي بن سليمان الأخفش في كتاب المغتالين قال حدثنا أبو سعيد السكري قال حدثنا محمد بن حبيب عن ابن الكلبي قال عشقت أم البنين وضاحا فكانت ترسل إليه فيدخل إليها ويقيم عندها فإذا خافت وارته في صندوق وأقفلت عليه فأهدي للوليد جوهر له قيمة فأعجبه واستحسنه فدعا خادما له فبعث به معه إلى أم البنين وقال قل لها إن هذا الجوهر أعجبني فآثرتك به فدخل الخادم عليها مفاجأة ووضاح عندها فأدخلته الصندوق وهو يرى فأدى إليها رسالة الوليد ودفع إليها الجوهر ثم قال يا مولاتي هبيني منه حجرا فقالت لا يابن اللخناء ولا كرامة فرجع إلى الوليد فأخبره فقال كذبت يابن اللخناء وأمر به فوجئت عنقه ثم لبس نعليه ودخل على أم البنين وهي جالسة في ذلك البيت تمتشط وقد وصف له الخادم الصندوق الذي أدخلته فيه فجلس عليه ثم قال لها يا أم البنين ما أحب إليك هذا البيت\nمن بين بيوتك فلم تختارينه فقالت أجلس فيه وأختاره لأنه يجمع حوائجي كلها فأتناولها منه كما أريد من قرب فقال لها هبي لي صندوقا من هذه الصناديق قالت كلها لك يا أمير المؤمنين قال ما أريدها كلها وإنما أريد واحدا منها فقالت له خذ أيها شئت قال هذا الذي جلست عليه قالت خذ غيره فإن لي في أشياء أحتاج إليها قال ما أريد غيره قالت خذه يا أمير المؤمنين فدعا بالخدم وأمرهم بحمله فحمله حتى انتهى به إلى مجلسه فوضعه فيه ثم دعا عبيدا له فأمرهم فحفروا بئرا في المجلس عميقة فنحى البساط وحفرت إلى الماء ثم دعا بالصندوق فقال يا هذا إنه بلغنا شيء إن كان حقا فقد كفناك ودفناك ودفنا ذكرك وقطعنا أثرك إلى آخر الدهر وإن كان باطلا فإنا دفنا الخشب وما أهون ذلك ثم قذف به في البئر وعليه عليه التراب وسويت الأرض ورد البساط إلى حاله وجلس الوليد عليه ثم ما رئي بعد ذلك اليوم لوضاح أثر في الدنيا إلى هذا اليوم قال ما رأت أم البنين لذلك أثرا في وجه الوليد حتى فرق الموت بينهما أخبرني الحسن بن علي قال حدثنا أحمد بن زهير قال حدثني مصعب بن عبد الله قال مرضت أم البنين ووضاح مقيم بدمشق وكان نازلا عليها فقال في علتها صوت\n(حتام نكتم حزننا حتاما ... وعلام نستبقي الدموع علاما)\n(إن الذي بي قد تفاقم واعتلى ... ونما وزاد وأورث الأسقاما)\n(قد أصبحت أم البنين مريضة ... نخشى ونشفق أن يكون حماما)\n(يا رب أمتعني بطول بقائها ... واجبر بها الأرمال والأيتاما)\n(واجبر بها الرجل الغريب بأرضها ... قد فارق الأخوال والأعماما)\n(كم راغبين وراهبين وبؤس ... عصموا بقرب جنابها إعصاما)\n(بجناب ظاهرة الثنا محمودة ... لا يستطاع كلامها إعظاما)\nلغناء في الأول والثاني والثالث والرابع والخامس لحكم الوادي خفيف رمل بالوسطى عن الهشامي وعبد الله بن موسى ومما وجد في روايتي هارون بن الزيات وابن المكي في الرابع ثم الخامس ثم الأول والثاني لعمر الوادي خفيف رمل من رواية الهشامي أخبرني الحسن بن علي قال حدثنا أحمد بن زهير قال حدثنا مصعب قال بلغ الوليد بن عبد الملك تشبب وضاح بأم البنين فهم بقتله فسأله عبد العزيز ابنه فيه وقال له إن قتلته فضحتني وحققت قوله وتوهم الناس أن بينه وبين أمي ريبة فأمسك عنه على غيظ وحنق حتى بلغ الوليد أنه قد تعدى أم البنين إلى أخته فاطمة بنت عبد الملك وكانت زوجة عمر بن عبد العزيز رضي الله تعالى عنه وقال فيها\n(بنت الخليفة والخليفة جدها ... أخت الخليفة والخليفة بعلها)","topic":"أخبار وضاح اليمن ونسبه","topicNo":65,"sp":5,"spl":"الوليد يدفنه حيا"},
{"id":"b65-7","bab":"الجزء 6","sec":"الوليد يدفنه حيا","page":"ج6 ص236","text":"(فرحت قوابلها بها وتباشرت ... وكذاك كانوا في المسرة أهلها)\nأحنق واشتد غيظه وقال أما لهذا الكلب مزدجر عن ذكر نسائنا وأخواتنا ولا\nله عنا مذهب ثم دعا به فأحضر وأمر ببئر فحفرت ودفنه فيها حيا أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال أخبرني عبد الملك بن عبد العزيز عن يوسف بن الماجشون قال أنشدت محمد بن المنكدر قول وضاح\n(فما نولت حتى تضرعت عندها ... وأعلمتها ما رخص الله في اللمم)\nال فضحك وقال إن كان وضاح إلا مفتيا لنفسه وتمام هذه الأبيات\n(ترجل وضاح وأسبل بعدما ... تكهل حينا في الكهول وما احتلم)\n(وعلق بيضاء العوارض طفلة ... مخضبة الأطراف طيبة النسم)\n(إذا قلت يوما نوليني تبسمت ... وقالت معاذ الله من فعل ما حرم)\n(فما نولت حتى تضرعت عندها ... وأعلمتها ما رخص الله في اللمم)","topic":"أخبار وضاح اليمن ونسبه","topicNo":65,"sp":6,"spl":"الوليد يدفنه حيا — وضاح يرثي أباه وأخاه"},
{"id":"b65-8","bab":"الجزء 6","sec":"وضاح يرثي أباه وأخاه","page":"ج6 ص240","text":"أخبرني عمي قال حدثنا الكراني قال حدثنا العمري عن العتبي في خبره الأول المذكور من أخبار وضاح مع أم البنين قال\nكان وضاح مقيما عند أم البنين فورد عليه نعي أخيه وأبيه فقال يرثيهما\n(أراعك طائر بعد الخفوق ... بفاجعة مشنعة الطروق)\n(نعم ولها على رجل عميد ... أظل كأنني شرق بريقي)\n(كأني إذ علمت بها هدوا ... هوت بي عاصف من رأس نيق)\n(أعل بزفرة من بعد أخرى ... لها في القلب حر كالحريق)\n(وتردف عبرة تهتان أخرى ... كفائض غرب نضاح فتيق)\n(كأني إذا أكفكف دمع عيني ... وأنهاها أقول لها هريقي)\n(ألا تلك الحوادث غبت عنها ... بأرض الشام كالفرد الغريق)\n(فما أنفك أنظر في كتاب ... تداري النفس عنه هوى زهوق)\n(يخبر عن وفاة أخ كريم ... بعيد الغور نفاع طليق)\n(وقرم يعرض الخصمان عنه ... كما حاد البكار عن الفنيق)\n(كريم يملأ الشيزى ويقري ... إذا ما قل إيماض البروق)\n(وأعظم ما رميت به فجوعا ... كتاب جاء من فخ عميق)\n(يخبر عن وفاة أخ فصبرا ... تنجز وعد منان صدوق)\n(سأصبر للقضاء فكل حي ... سيلقى سكرة الموت المذوق)\n(فما الدنيا بقائمة وفيها ... من الأحياء ذو عين رموق)\n(وللأحياء أيام تقضى ... يلف ختامها سوقا بسوق)\n(فأغناهم كأعدمهم إذا ما ... تقضت مدة العيش الرقيق)\n(كذلك يبعثون وهم فرادى ... ليوم فيه توفية الحقوق)\n(أبعد همام قومك ذي الأيادي ... أبى الوضاح رتاق الفتوق)\n(وبعد عبيدة المحمود فيهم ... وبعد سماعة العود العتيق)\n(وبعد ابن المفضل وابن كاف ... هما أخواك في الزمن الأنيق)\n(تؤمل أن تعيش قرير عين ... وأين أمام طلاب لحوق)\n(ودنياك التي أمسيت فيها ... مزايلة الشقيق عن الشقيق)\nمما قاله في مرثية أهله وذكر الموت وغنى فيه وإنما نذكر منها ما فيه غناء لأنها طويلة صوت\n(مالك وضاح دائم الغزل ... ألست تخشى تقارب الأجل)\n(صل لذي العرش واتخذ قدما ... تنجيك يوم العثار والزلل)\n(يا موت ما إن تزال معترضا ... لآمل دون منتهى الأمل)\n(لو كان من فر منك منفلتا ... إذا لأسرعت رحلة الجمل)\n(لكن كفيك نال طولهما ... ما كل عنه نجائب الإبل)\n(تنال كفاك كل مسهلة ... وحوت بحر ومعقل الوعل)\n(لولا حذاري من الحتوف فقد ... أصبحت من خوفها على وجل)\n(لكنت للقلب في الهوى تبعا ... إن هواه ربائب الحجل)\n(حرمية تسكن الحجاز لها ... شيخ غيور يعتل بالعلل)\n(علق قلبي ربيب بيت ملوك ... ذات قرطين وعثة الكفل)\n(تفتر عن منطق تضن به ... يجري رضابا كذائب العسل)","topic":"أخبار وضاح اليمن ونسبه","topicNo":65,"sp":6,"spl":"الوليد يدفنه حيا — وضاح يرثي أباه وأخاه"},
{"id":"b65-9","bab":"الجزء 6","sec":"وضاح يشبب بحبابة وبروضة","page":"ج6 ص243","text":"أخبرني الحسن بن علي قال حدثنا هارون بن محمد بن عبد الملك قال حدثني سليمان بن أبي أيوب عن مصعب قال قال وضاح اليمن في حبابة جارية يزيد بن عبد الملك وشاهدها بالحجاز قبل أن يشتريها يزيد وتصير إليه وسمع غناءها فأعجب بها إعجابا شديدا صوت\n(يا من لقلب لا يطيع ... الزاجرين ولا يفيق)\n(تسلو قلوب ذوي الهوى ... وهو المكلف والمشوق)\n(تبلت حبابة قلبه ... بالدل والشكل الأنيق)\n(وبعين أحور يرتعي ... سقط الكثيب من العقيق)\n(مكحولة بالسحر تنشي ... نشوة الخمر العتيق)\n(هيفاء إن هي أقبلت ... لاحت كطالعة الشروق)\n(والردف مثل نقا تلبد ... فهو زحلوق زلوق)\n(في درة الأصداف معتنقا ... بها ردع الخلوق)\n(داوي هواي وأطفئي ... ما في الفؤاد من الحريق)\n(وترفقي أملي فقد ... كلفتني مالا أطيق)\n(في القلب منك جوى المحب ... وراحة الصب الشفيق)\n(هذا يقود برمتي ... قودا إليك وذا يسوق)\n(يا نفس قد كلفتني ... تعب الهوى منها فذوق)\n(إن كنت تائقة ... لحر)\nمما قاله في روضة وفيه عناء قوله صوت\n(يا لقومي لكثرة العذال ... ولطيف سرى مليح الدلال)\n(زائر في قصور صنعاء يسري ... كل أرض مخوفة وجبال)\nالغناء لإبن عباد عن الهشامي رمل وهذه الأبيات من قصيدة له في روضة طويلة جيدة يقول فيها\n(يقطع الحزن والمهامه والبيد ... ومن دونه ثمان ليالي)\n(عاتب في المنام أحبب بعتباه ... إلينا وقوله من مقال)\n(قلت أهلا ومرحبا عدد القطر ... وسهلا بطيف هذا الخيال)\n(حبذا من إذا خلونا نجيا ... قال أهلي لك الفداء ومالي)\n(وهي الهم والمنى وهوى النفس ... إذا اعتل ذو هوى باعتلال)\n(قست ما كان قبلنا من هوى الناس ... فما قست حبها بمثال)\n(لم أجد حبها يشاكله الحب ... ولا وجدنا كوجد الرجال)\n(كل حب إذا استطال سيبلى ... وهوى روضة المنى غير بالي)\n(لم يزده تقادم العهد إلا ... جدة عندنا وحسن احتلال)\n(أيها العاذلون كيف عتابي ... بعد ما شاب مفرقي وقذالي)\n(كيف عذلي على التي هي مني ... بمكان اليمين أخت الشمال)\n(والذي أحرموا له وأحلوا ... بمنى صبح عاشرات الليالي)\n(ما ملكت الهوى ولا النفس مني ... منذ علقتها فكيف احتالي)\n(إن نأت كان نأيها الموت صرفا ... أو دنت لي فثم يبدو خبالي)\n(يابنة المالكي يا بهجة النفس ... أفي حبكم يحل أقتتالي)\n(أي ذنب علي إن قلت إني ... لأحب الحجاز حب الزلال)\n(لأحب الحجاز من حب من فيه ... وأهوى حلاله من حلال)\nصوت ومما فيه غناء من شعر وضاح\n(أيها الناعب ماذا تقول ... فكلانا سائل ومسول)\n(لا كساك الله ما عشت ريشا ... وبخوف بت ثم تقيل)\n(ثم لا أنفقت في العش فرخا ... أبدا إلا عليك دليل)\n(حين تنبي أن هندا قريب ... يبلغ الحاجات منها الرسول)\n(ونأت هند فخبرت عنها ... أن عهد الود سوف يزول)\nمنها صوت\n(حتي التي أقصى فؤادك حلت ... علمت بأنك عاشق فأدلت)\n(وإذا رأتك تقلقت أحشاؤها ... شوقا إليك فأكثرت وأقلت)\n(وإذا دخلت فأغلقت أبوابها ... عزم الغيور حجابها فاعتلت)\n(وإذا خرجت بكت عليك صبابة ... حتى تبل دموعها ما بلت)\n(إن كنت يا وضاح زرت فمرحبا ... رحبت عليك بلادنا وأظلت)\nلغناء لإبن سريج رمل بالوسطى عن عمرو وفيها ليحيى المكي ثاني ثقيل\nبالوسطى من كتابه ولإبنه أحمد فيها هزج وذكر حبش أن ليحيى فيها أيضا خفيف ثقيل ومنها صوت\n(أتعرف أطلالا بميسرة اللوى ... إلى أرعب قد حالفتك به الصبا)\n(فأهلا وسهلا بالتي حل حبها ... فؤادي وحلت دار شحط من النوى)\nلغناء فيه هزج يمني بالبنصر عن ابن المكي وهذه أبيات يقولها لأخيه سماعة وقد عتب عليه في بعض الأمور وفيها يقول\n(أبادر درنوك الأمير وقربه ... لأذكر في أهل الكرامة والنهى)\n(وأتبع القصاص كل عشية ... رجاء ثواب الله في عدد الخطا)\n(وأمست بقصر يضرب الماء سوره ... وأصبحت في صنعاء ألتمس الندى)\n(فمن مبلغ عنى سماعة ناهيا ... فإن شئت فاقطعنا كما يقطع السلى)\n(وإن شئت وصل الرحم في غير حيلة ... فعلنا وقلنا للذي تشتهي بلى)\n(وإن شئت صرما للتفرق والنوى ... فبعدا أدام الله تفرقة النوى)\nومنها صوت\n(طرق الخيال فمرحبا ألفا ... بالشاغفات قلوبنا شغفا)\n(ولقد يقول لي الطبيب وما ... نبأته من شأننا حرفا)\n(إني لأحسب أن داءك ذا ... من ذي دمالج يخضب الكفا)\n(إني أنا الوضاح إن تصلي ... أحسن بك التشبيب والوصفا)","topic":"أخبار وضاح اليمن ونسبه","topicNo":65,"sp":7,"spl":"وضاح يشبب بحبابة وبروضة"},
{"id":"b65-10","bab":"الجزء 6","sec":"وضاح يشبب بحبابة وبروضة","page":"ج6 ص243","text":"(شطت فشف القلب ذكركها ... ودنت فما بذلت لنا عرفا)\nومنها صوت ويروى لبشار\n(يا مرحبا ألفا وألفا ... بالكاسرات إلي طرفا)\n(رجح الروادف كالظبا ... تعرضت حوا ووطفا)\n(أنكرن مركبي الحما ... روكن لا ينكرن طرفا)\n(وسألنني أين الشباب ... فقلت بان وكان حلفا)\n(أفنى شبابي فانقضى ... حلف النساء تبعن حلفا)\n(أعطيتهن مودتي ... فجزينني كذبا وخلفا)\n(وقصائد مثل الرقى ... أرسلتهن فكن شغفا)\n(أوجعن كل مغازل ... وعصفن بالغيران عصفا)\n(من كل لذات الفتى ... قد نلت مائلة وعرفا)\n(صعدت الأوانس كالدمى ... وسقيتهن الخمر صرفا)\nومنها وهذه القصيدة تجمع نسيبه بمن ذكر وفخره بأبيه وجده أبي جمد صوت\n(أغني على بيضاء تنكل عن برد ... وتمشي على هون كمشيه ذي الحرد)\n(وتلبس من بز العراق مناصفا ... وأبراد عصب من مهلهلة الجبد)\n(إذا قلت يوما نوليني تبسمت ... وقالت لعمر الله لو أنه اقتصد)\n(سموت إليها بعد ما نام بعلها ... وقد وسدته الكف في ليلة الصرد)\n(أشارت بطرف العين أهلا ومرحبا ... ستعطى الذي تهوى على رغم من حسد)\n(ألست ترى من حولنا من عدونا ... وكل غلام شامخ الأنف قد مرد)\n(فقلت لها إني امرؤ فاعلمنه ... إذا ما أخذت السيف لم أحفل العدد)\n(بنى لي إسماعيل مجدا مؤثلا ... وعبد كلال قبله وأبو جمد)\nطيف علينا قهوة في زجاجة ... تريك جبان القوم أمضى من الأسد\nمنها صوت\n(يأيها القلب بعض ما تجد ... قد يعشق القلب ثم يتئد)\n(قد يكتم المرء حبه حقبا ... وهو عميد وقلبه كمد)\n(ماذا تراعون من فتى غزل ... قد تيمته خمصانة رؤد)\n(يهددوني كما أخافهم ... هيهات أنى يهدد الأسد)\nومنها صوت\n(صدع البين والتفرق قلبي ... وتولت أم البنين بلبي)\n(ثوت النفس في الحمول لديها ... وتولى بالجسم مني صحبي)\n(ولقد قلت والمدامع تجري ... بدموع كأنها فيض غرب)\n(جزعا للفراق يوم تولت ... حسبي الله ذو المعارج حسبي)\nمنها\nصوت\n(يابنة الواحد جودي فما ... إن تصرميني فبما أو لما)\n(جودي علينا اليوم أو بيني ... فيم قتلت الرجل المسلما)\n(إني وأيدي قلص ضمر ... وكل خرق ورد الموسما)\n(ما علق القلب كتعليقها ... واضعة كفا علت معصما)\n(ربة محراب إذا جئتها ... لم ألقها أو أرتقي سلما)\n(إخوتها أربعة كلهم ... ينفون عنها الفارس المعلما)\n(كيف أرجيها ومن دونها ... بواب سوء يعجل المشتما)\n(أسود هتاك لأعراض من ... مر على الأبواب أو سلما)\n(لا منة أعلم كانت لها ... عندي ولا تطلب فينا دما)\n(بل هي لما أن رأت عاشقا ... صبا رمته اليوم فيمن رمى)\n(لما ارتمينا ورأت أنها ... قد أثبتت في قلبه أسهما)\n(أعجبها ذاك فأبدت له ... سنتها البيضاء والمعصما)\n(قامت تراءى لي على قصرها ... بين جوار خرد كالدمى)\n(وتعقد المرط على جسرة ... مثل كثيب الرمل أو أعظما)\nومنها صوت\n(دعاك من شوقك الدواعي ... وأنت وضاح ذو اتباع)\n(دعتك ميالة لعوب ... أسيلة الخد باللماع)\n(دلالك الحلو والمشهي ... وليس سريك بالمضاع)\n(لا أمنع النفس عن هواها ... وكل شيء إلى انقطاع)\nمنها صوت\n(ألا يالقومي أطلقوا غل مرتهن ... ومنوا على مستشعر الهم والحزن)\n(تذكر سلمى وهي نازحة فحن ... وهل تنفع الذكرى إذا اغترب الوطن)\n(ألم ترها صفراء رؤدا شبابها ... أسيلة مجرى الدمع كالشادن الأغن)\n(وأبصرت سلمى بين بردي مراجل ... وأبراد عصب من مهلهلة اليمن)\n(فقلت لها لا ترتقي السطح إنني ... أخاف عليكم كل ذي لمة حسن)\nالغناء لإبن سريج وله في هذا الشعر لحنان ثقيل أول بالبنصر عن عمرو ورمل بالسبابة في مجرى البنصر عن إسحاق وأول الرمل قوله\n(ألا يا لقومي أطلقوا غل مرتهن ... )\nوأول الثقيل الأول تذكر سلمى وفي هذه الأبيات هزج يمني بالبنصر ومنها صوت\n(أغدوت أم في الرائحين تروح ... أم أنت من ذكر الحسان صحيح)\n(إذا قالت الحسناء ما لصديقنا ... رث الثياب وإنه لمليح)\n(لا تسألن عن الثياب فإنني ... يوم اللقاء على الكماة مشيح)\n(أرمي وأطعن ثم أتبع ضربة ... تدع النساء على الرجال تنوح)\nوت","topic":"أخبار وضاح اليمن ونسبه","topicNo":65,"sp":8,"spl":"وضاح يشبب بحبابة وبروضة","partial":1},
{"id":"b65-11","bab":"الجزء 6","sec":"من المائة المختارة","page":"ج6 ص253","text":"(يا صاح إني قد حججت ... وزرت بيت المقدس)\n(وأتيت لدا عامدا ... في عيد مريا سرجس)\n(فرأيت فيه نسوة ... مثل الظباء الكنس)\nلشعر والغناء للمعلى بن طريف مولى المهدي ولحنه المختار خفيف رمل بالبنصر وكان المعلى بن طريف وأخوه ليث مملوكين مولدين من مولدي الكوفة لرجل من أهلها فاشتراهما علي بن سليمان وأهداهما إلى المنصور فوهبهما\nالمنصور للمهدي فأعتقهما ونهر المعلى وربض المعلى ببغداد منسوب إلى المعلى هكذا ذكر ذلك ابن خرداذبه وكان ضاربا محسنا طيب الصوت حسن الأداء صالح الصنعة أخذ الغناء عن إبراهيم وابن جامع وحكم الوادي وولي أخوه ليث السند وولي هو الطراز والبريد بخراسان وقاتل يوسف البرم فهزمه ثم ولي الأهواز بعد ذلك فقال فيه بعض الشعراء يمدحه ويمدح أخاه الليث ويهجو علي بن صالح صاحب المصلى\n(يا علي بن صالح ذا المصلى ... أنت تفدي ليثا وتفدي المعلى)\n(سد ليث ثغرا ووليت فاختنت ... فبئس المولي وبئس المولى)\nعلي بن سليمان هذا الذي أهدى المعلى وأخاه إلى المهدي هو الذي يقول فيه أبو دلامة زند بن الجون الأسدي وكان خرج مع المهدي إلى الصيد فرمى المهدي وعلي بن سليمان ظبيا سنح لهما وقد أرسلت عليه الكلاب بسهمين فأصاب المهدي الظبي وأصاب علي بن سليمان الكلب فقتلاهما فقال أبو دلامة\n(قد رمى المهدي ظبا ... شك بالسهم فؤاده)\n(وعلي بن سليمان ... رمى كلبا فصاده)\n(فهنيئا لهما كل ... إمرىء يأكل زاده)\nدثنا بذلك الحسن بن علي عن أحمد بن زهير عن مصعب وعن أحمد بن سعيد\nعن الزبير بن بكار عن عمه صوت","topic":"أخبار وضاح اليمن ونسبه","topicNo":65,"sp":9,"spl":"من المائة المختارة — أخبار بشار وعبدة خاصة إذ كانت أخباره سوى هذه تقدمت"},
{"id":"b65-12","bab":"الجزء 6","sec":"من المائة المختارة","page":"ج6 ص255","text":"(ألا طرد الهوى عني رقادي ... فحسبي ما لقيت من السهاد)\n(لعبدة إن عبدة تيمتني ... وحلت من فؤادي في السواد)\nلشعر لبشار والغناء المختار في هذين البيتين هزج خفيف بالبنصر ذكر يحيى بن علي أنه يمني وذكر الهشامي أنه لسليم","topic":"أخبار وضاح اليمن ونسبه","topicNo":65,"sp":9,"spl":"من المائة المختارة — أخبار بشار وعبدة خاصة إذ كانت أخباره سوى هذه تقدمت"},
{"id":"b65-13","bab":"الجزء 6","sec":"أخبار بشار وعبدة خاصة إذ كانت أخباره سوى هذه تقدمت","page":"ج6 ص256","text":"حدثني محمد بن خلف وكيع قال حدثنا أبو أيوب المديني عمن حدثه عن الأصمعي هكذا قال وأخبرني به عمي عن عبد الله بن أبي سعد عن علي بن مسرور عن الأصمعي قال كان لبشار مجلس يجلس فيه يقال له البردان فبينا هو في مجلسه ذات يوم وكان النساء يحضرنه إذ سمع كلام امرأة يقال لها عبدة في المجلس فدعا غلامه فقال إني قد علقت امرأة فإذا تكلمت فانظر من هي واعرفها فإذا انقضى المجلس وانصرف أهله فاتبعها وكلمها وأعلمها أني لها محب وأنشدها هذه الأبيات وعرفها أني قلتها فيها صوت قالوا بمن لا ترى تهذي فقلت لهم ... الأذن كالعين توفي القلب ما كانا ما كنت أول مشغوف بجارية ... يلقى بلقيانها روحا وريحانا\nويروى هل من دواء لمشغوف بجارية\n(يا قوم أذني لبعض الحي عاشقة ... والأذن تعشق قبل العين أحيانا)\nنى إبراهيم في هذه الأبيات ثاني ثقيل بإطلاق الوتر في مجرى البنصر عن إسحاق وفيها لسياط ثقيل أول بالوسطى عن عمرو وفيها لإسحاق هزج من جامع أغانيه قال فأبلغها الغلام الأبيات فهشت لها وكانت تزوره مع نسوة يصحبنها فيأكلن عنده ويشربن وينصرفن بعد أن يحدثها وينشدها ولا تطمعه في نفسها قال وقال فيها\n(قالت عقيل بن كعب إذ تعلقها ... قلبي فأضحى به من حبها أثر)\n(أنى ولم ترها تهذي فقلت لهم ... إن الفؤاد يرى ما لا يرى البصر)\n(أصبحت كالحائم الحران مجتنبا ... لم يقض وردا ولا يرجى له صدر)\nقال وقال فيها أيضا وهو من جيد ما قال فيها\n(يزهدني في حب عبدة معشر ... قلوبهم فيها مخالفة قلبي)\n(فقلت دعوا قلبي وما اختار وارتضى ... فبالقلب لا بالعين يبصر ذو الحب)\n(فما تبصر العينان في موضع الهوى ... ولا تسمع الأذنان إلا من القلب)\n(وما الحسن إلا كل حسن دعا الصبا ... وألف بين العشق والعاشق الصب)\nال وقال فيها\n(يا قلب مالي أراك لا تقر ... إياك أعني وعندك الخبر)\n(أضعت بين الألى مضوا حرقا ... أم ضاع ما استودعوك إذ بكروا)\n(فقال بعض الحديث يشغفني ... والقلب راء ما لا يرى البصر)","topic":"أخبار وضاح اليمن ونسبه","topicNo":65,"sp":9,"spl":"من المائة المختارة — أخبار بشار وعبدة خاصة إذ كانت أخباره سوى هذه تقدمت"},
{"id":"b65-14","bab":"الجزء 6","sec":"هجوه الحسن البصري","page":"ج6 ص258","text":"وأخبرني بهذا الخبر أبو الحسن أحمد بن محمد الأسدي قال حدثنا الحسن بن عليل العنزي قال حدثنا خالد بن يزيد بن وهب عن جرير عن أبيه بمثل هذه القصة وزاد فيها أن عبدة جاءت إليه في نسوة خمس قد مات لإحداهن قريب فسألنه أن يقول شعرا ينحن عليه به فوافينه وقد احتجم وكان له مجلسان مجلس يجلس فيه غدوة يسميه البردان ومجلس فيه عشية يسميه الرقيق وهو جالس في البردان وقد قال لغلامه أمسك علي بابي واطبخ لي وهيء طعامي وطيبه وصف نبيذي قال فإنه لكذلك إذا قرع الباب عليه قرعا عنيفا فقال ويحك يا غلام انظر من يدق الباب دق الشرط فنظر الغلام وجاءه فقال خمس نسوة بالباب يسألنك أن تقول شعرا ينحن فيه فقال أدخلهن فلما دخلن نظرن إلى النبيذ مصفى في قنانيه في جانب بيته فقالت إحداهن خمر وقالت الأخرى زبيب وقالت الأخرى معسل فقال لست بقائل لكن حرفا أو تطعمن من طعامي وتشربن من شرابي فتماسكن ساعة وقالت إحداهن فما عليكن من ذلك هذا أعمى كلن من طعامه واشربن من شرابه وخذن شعره ففعلن وبلغ ذلك الحسن البصري فعابه وهتف به فبلغ ذلك بشارا وكان الحسن يلقب القس فقال فيه بشار\n(لما طلعن من الرقيق ... علي بالبردان خمسا)\n(وكأنهن أهلة ... تحت الثياب زففن شمسا)\n(باكرن طيب لطيمة ... وعمس في الجادي عمسا)\n(فسألنني من في البيوت ... فقلت ما يحوين إنسا)\n(ليت العيون الناظرات ... طمسن عنا اليوم طمسا)\n(فأصبن من طرف الحديث ... لذاذة وخرجن ملسا)\n(لولا تعرضهن لي ... يا قس كنت كأنت قسا)\nأخبرني الأسدي ويحيى بن علي بن يحيى ومحمد بن عمران الصيرفي قالوا حدثنا العنزي قال حدثنا علي بن محمد عن جعفر بن محمد النوفلي قال أتيت بشارا ذات يوم فقال لي ما شعرت منذ أيام إلا بقارع يقرع بابي مع الصبح فقلت يا جارية انظري من هذا فقالت مالك بن دينار فقلت مالي ولمالك بن دينار ما هو من أشكالي إئذني له فدخل فقال لي يا أبا معاذ أتشتم أعراض الناس وتشبب بنسائهم فلم يكن عندي إلا دفعه عن نفسي بأن قلت لا أعاود فخرج من عندي وقلت في إثره\n(غدا مالك بملاماته ... علي وما بات من باليه)\n(فقلت دع اللوم في حبها ... فقبلك أعييت عذاليه)\n(وإني لأكتمهم سرها ... غداة تقول لها الجالية)\n(أعبدة مالك مسلوبة ... وكنت مقرطقة حاليه)\n(فقالت على رقبة إنني ... رهنت المرعث خلخاليه)\n(بمجلس يوم سأوفي به ... وإن أنكر الناس أحواليه)\nخبرني وكيع قال حدثني عمرو بن محمد بن عبد الملك قال حدثني\nالحسن بن جهور قال حدثني هشام بن الأحنف راوية بشار قال إني لعند بشار ذات يوم إذ أتته امرأة فقالت يا أبا معاذ عبدة تقرئك السلام وتقول لك قد اشتد شوقنا إليك ولم نرك منذ أيام فقال عن غير مقلية والله كان ذاك ثم قال لراويته يا هشام خذ الرقعة واكتب فيها ما أقول لك ثم ادفعه للرسول قال هشام فأملى علي\n(عبد إني إليك بالأشواق ... لتلاق وكيف لي بالتلاقي)\n(أنا والله أشتهي سحر عينيك ... وأخشى مصارع العشاق)\n(وأهاب الحرسي محتسب الجند ... يلف البريء بالفساق)\nمما يغني فيه من شعر بشار في عبدة قوله صوت\n(لعبدة دار تكلمنا الدار ... تلوح مغانيها كما لاح أسطار)\n(أسائل أحجارا ونؤيا مهدما ... وكيف يجيب القول نؤي وأحجار)\n(وما كلمتني دارها إذ سألتها ... وفي كبدي كالنفط شبت به النار)\n(وعند مغاني دارها لو تكلمت ... لمكتئب بادي الصبابة أخبار)\nلغناء لإبراهيم ثاني ثقيل مطلق في مجرى البنصر عن إسحاق وفيه لإبن جامع ثقيل أول عن الهشامي ومن هذه القصيدة صوت\n(تحمل جيراني فعيني لبينهم ... تفيض بتهتان إذا لاحت الدار)\n(بكيت على من كنت أحظى بقربه ... وحق الذي حاذرت بالأمس إذ ساروا)\nلغناء ليحيى المكي ثقيل أول بالبنصر ومن الأغاني في شعره في عبدة صوت\n(مسني من صدود عبدة ضر ... فبنات الفؤاد ما تستقر)\n(ذاك شيء في القلب من حب عبدة ... باد وباطن يستسر)\nالغناء لإبراهيم ثاني ثقيل مطلق في مجرى الوسطى عن إسحاق وفيه لإسحاق رمل بالبنصر عن عمرو وفيه لحكم ثقيل أول بالوسطى من جامع غنائه في كتاب إبراهيم وفيه لفريدة خفيف ثقيل عن إسحاق وفيه ليحيى المكي ثقيل أول من كتابه وفيه لحسين بن محرز رمل عن الهشامي ومنها صوت\n(يا عبد إني قد ظلمت وإنني ... مبد مقالة راغب أو راهب)\n(وأتوب مما تكرهين لتقبلي ... والله يقبل حسن فعل التائب)","topic":"أخبار وضاح اليمن ونسبه","topicNo":65,"sp":10,"spl":"هجوه الحسن البصري"},
{"id":"b65-15","bab":"الجزء 6","sec":"هجوه الحسن البصري","page":"ج6 ص258","text":"لغناء لحكم خفيف ثقيل عن إسحاق وفيه ليحيى المكي ثقيل أول من كتابه وفيه لحسين بن محرز رمل عن الهشامي ومنها صوت\n(يا عبد حبك شفني شفا ... والحب داء يورث الحتفا)\n(والحب يخفيه المحب لكي ... لا يستراب به وما يخفى)\nلغناء لسياط خفيف رمل مطلق في مجرى البنصر عن إسحاق ومنها صوت\n(يا عبد بالله فرجي كربي ... فقد براني وشفني نصبي)\n(وضقت ذرعا بما كلفت به ... من حبكم والمحب في تعب)\n(ففرجي كربة شجيت بها ... وحر حزن في الصدر كاللهب)\n(ولا تظني ما أشتكي لعبا ... هيهات قد جل ذا عن اللعب)\nناه سياط ثقيلا أول بالبنصر عن عمرو ومنها صوت\n(يا عبد زوريني تكن منة ... لله عندي يوم ألقاك)\n(والله ثم الله فاستيقني ... إني لأرجوك وأخشاك)\n(يا عبد إني هالك مدنف ... إن لم أذق برد ثناياك)\n(فلا تردي عاشقا مدنفا ... يرضى بهذا القدر من ذاك)\nلغناء لحكم هزج خفيف بالسبابة في مجرى البنصر عن إسحاق ومنها صوت\n(يا عبد قد طال المطال فانعمي ... واشفي فؤاد فتى بهيم متيم)\nالغناء ليزيد حوراء غير مجنس عن إبراهيم ومنها صوت\n(يا عبد هل للقاء من سبب ... أو لا فأدعو بالويل والحرب)\nلغناء ليزيد حوراء غير مجنس ومنها صوت\n(يا عبد هل لي منكم من عائد ... أم هل لديك صلاح قلب فاسد)\nلغناء لإبن عباد عن إبراهيم غير مجنس ومنها صوت\n(يا عبد حيي عن قريب ... وتأملي عين الرقيب)\n(وارعي ودادي غائبا ... فلقد رعيتك في المغيب)\n(أشكو إليك وإنما ... يشكو المحب إلى الحبيب)\n(غرضي إليك من الهوى ... غرض المريض إلى الطبيب)\nلغناء لحكم مطلق في مجرى البنصر ومنها\nصوت\n(يا عبد بالله ارحمي عبدك ... وعلليه بمنى وعدك)\n(يصبح مكروبا ويمسي به ... وليس يدري ما له عندك)\n(ماذا تقولين لرب العلا ... إذا تخليت به وحدك)\nلغناء لإبراهيم ثاني ثقيل بالبنصر عن عمرو وفيه لإسحاق هزج من جامع أغانيه وفيه ليزيد حوراء لحن ذكره إبراهيم ولم يجنسه وذكر حبش أن الثقيل الثاني لسياط ومنها صوت\n(يا عبد جلي كروبي ... وأسعفي وأثيبي)\n(فقد تطاول همي ... وزفرتي ونحيبي)\nلغناء لإبن سكرة عن إبراهيم ولم يجنسه ومنها صوت\n(يا عبد أنت ذخيرتي ... نفسي فدتك وجيرتي)\n(الله يعلم فيكم ... يا عبد حسن سريرتي)\n(نفسي لنفسك خلة ... وكذاك أنت أميرتي)\nلغناء لحكم الوادي خفيف ثقيل بالوسطى عن عمرو ومنها\nصوت\n(يا عبد حبي لك مستور ... وكل حب غيره زور)\n(إن كان هجري سركم فاهجروا ... إني بما سرك مسرور)\nلغناء لحكم هزج بالوسطى عن ابن المكي ومنها صوت\n(لم يطل ليلي ولكن لم أنم ... ونفى عني الكرى طيف ألم)\n(وإذا قلت لها جودي لنا ... خرجت بالصمت عن لا ونعم)\n(رفهي يا عبد عني واعلمي ... أنني يا عبد من لحم ودم)\n(إن في بردي جسما ناحلا ... لو توكأت عليه لانهدم)\n(ختم الحب لها في عنقي ... موضع الخاتم من أهل الذمم)\nلغناء لحكم هزج بالسبابة والوسطى عن ابن المكي وذكره إسحاق في هذه الطريقة فلم ينسبه إلى أحد وفيه لعثعث الأسود خفيف رمل في الأول والخامس وكان بشار ينكر هذا البيت الأخير وهو\n(ختم الحب لها في عنقي ... )\nخبرني عمي قال حدثنا الكراني قال حدثني أبو حاتم السجستاني قال حدثني من أنشد بشارا قوله\n(لم يطل ليلي ولكن لم أنم ... )\nحتى بلغ إلى قوله\n(ختم الحب لها في عنقي ... موضع الخاتم من أهل الذمم)\nقال بشار عمن أخذت هذا قلت عن راويتك فلان فقال قبحه الله والله ما قلت هذا البيت قط أما ترى إلى أثره فيه ما أقبحه وأشد تميزه عني فقال له بعض من حضر نعم هو ألحقه بالأبيات ومنها صوت\n(عبد إني قد اعترفت بذنبي ... فاغفري واعركي خطاي بجنب)\n(عبد لا صبر لي ولست فمهلا ... قائلا قد عتبت في غير عتب)\n(ولقد قلت حين أنصبني الحب ... فأبلى جسمي وعذب قلبي)\n(رب لا صبر لي على الهجر حسبي ... أقلني حسبي لك الحمد حسبي)\nلغناء لسياط خفيف رمل بالوسطى عن عمرو وفيه لسليم هزج من كتاب ابن المكي ومنها صوت\n(عبد منى وأنعمي ... قد ملكتم قياديه)\n(شاب رأسي ولم تشب ... أبلائي لداتيه)\nالغناء لسياط خفيف رمل بالوسطى عن عمرو وفيه لعريب هزج ومنها صوت\n(عبد يا همتي عليك السلام ... فيم يجفى حبيبك المستهام)\n(نزل الحب منزلا في فؤادي ... وله فيه مجلس ومقام)\nالغناء لأبي زكار خفيف رمل بالوسطى عن عمرو وفيه لعريب هزج ومنها صوت\n(عبد ياقرة عيني ... أنصفي روحي فداك)","topic":"أخبار وضاح اليمن ونسبه","topicNo":65,"sp":11,"spl":"هجوه الحسن البصري","partialRef":{"sid":"b25-11","gi":0,"vi":4,"side":0},"partial":1},
{"id":"b65-16","bab":"الجزء 6","sec":"هجوه الحسن البصري","page":"ج6 ص258","text":"(عاشق ليس له ذكر ... ولا هم سواك)\nلغناء لعريب هزج وفيه لحن ليزيد حوراء غير مجنس ومنها صوت\n(يا عبد يا جافية قاطعه ... أما رحمت المقلة الدامعه)\n(يا عبد خافي الله في عاشق ... يهواك حتى تقع الواقعة)\nالغناء لأبي زكار هزج بالبنصر عن عمرو صوت","topic":"أخبار وضاح اليمن ونسبه","topicNo":65,"sp":12,"spl":"هجوه الحسن البصري — من المائة المختارة"},
{"id":"b65-17","bab":"الجزء 6","sec":"من المائة المختارة","page":"ج6 ص267","text":"(أرسلت أم جعفر لا تزور ... ليت شعري بالغيب من ذا دهاها)\n(أأتاها محرش بنميم ... كاذب ما أراد إلا رداها)\nعروضه من الخفيف الشعر للأحوص والغناء لأم جعفر المدنية مولاة عبد الله بن جعفر بن أبي طالب ولحنه من الثقيل الأول في مجرى البنصر عن إسحاق وذكر عمرو بن بانة أن فيه لحنا من الثقيل الأول بالبنصر فلا أعلم أهذا يعني أم غيره وفيه لإبن سريج ثاني ثقيل بالبنصر في مجراها عن يحيى المكي وإسحاق وفيه لإبراهيم خفيف ثقيل بالوسطى عن عمرو والهشامي","topic":"أخبار وضاح اليمن ونسبه","topicNo":65,"sp":12,"spl":"هجوه الحسن البصري — من المائة المختارة"},
{"id":"b65-18","bab":"الجزء 6","sec":"أخبار الأحوص مع أم جعفر","page":"ج6 ص269","text":"وقد ذكرت أخبار الأحوص متقدما إلا أخباره مع أم جعفر التي قال فيها هذا الشعر فإنها أخرت إلى هذا الموضع وأم جعفر هذه امرأة من الأنصار من بني خطمة وهي أم جعفر بنت عبد الله بن عرفطة بن قتادة بن معد بن غياث بن رزاح بن عامر بن عبد الله بن خطمة بن جشم بن مالك بن الأوس وله فيها أشعار كثيرة أخبرني أحمد بن عبد العزيز الجوهري وحبيب بن نصر المهلبي قالا حدثنا عمر بن شبة قال حدثني يعقوب بن القاسم ومحمد بن يحيى الطلحي عن عبد العزيز بن أبي ثابت وأخبرني عمي قال حدثني محمد بن داود بن الجراح قال حدثني أحمد بن زهير عن مصعب وأخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثنا عبد الرحمن بن عبد الله عن المحرز بن جعفر الدوسي قالوا جميعا لما أكثر الأحوص التشبيب بأم جعفر وشاع ذكره فيها توعده أخوها أيمن وهدده فلم ينته فاستعدى عليه والي المدينة وقال الزبير في خبره فاستعدى عليه عمر بن عبد العزيز فربطهما في حبل ودفع إليهما سوطين وقال لهما تجالدا فتجالدا فغلب أخوها وقال غير الزبير في خبره وسلح الأحوص في ثيابه وهرب\nوتبعه أخوها حتى فاته الأحوص هربا وقد كان الأحوص قال فيها\n(لقد منعت معروفها أم جعفر ... وإني إلى معروفها لفقير)\n(وقد أنكرت بعد اعتراف زيارتي ... وقد وغرت فيها علي صدور)\n(أدور ولولا أن أرى أم جعفر ... بأبياتكم ما درت حيث أدور)\n(أزور البيوت اللاصقات ببيتها ... وقلبي إلى البيت الذي لا أزور)\n(وما كنت زوارا ولكن ذا الهوى ... إذا لم يزر لا بد أن سيزور)\n(أزور على أن لست أنفك كلما ... أتيت عدوا بالبنان يشير)\nقال السائب بن عمرو أحد بني عمرو بن عوف يعارض الأحوص في هذه الأبيات ويعيره بفراره\n(لقد منع المعروف من أم جعفر ... أخو ثقة عند الجلاد صبور)\n(علاك بمتن السوط حتى اتقيته ... بأصفر من ماء الصفاق يفور)\nقال الأحوص\n(إذا أنا لم أغفر لأيمن ذنبه ... فمن ذا الذي يعفو له ذنبه بعدي)\n(أريد انتقام الذنب ثم تردني ... يد لأدانيه مباركة عندي)\nوقال الزبير في خبره خاصة وإنما أعطاهما عمر بن عبد العزيز السوطين وأمرهما\nأن يتضاربا بهما اقتداء بعثمان بن عفان فإنه كان لما تهاجى سالم بن دارة ومرة ابن واقع الغطفاني الفزاري لزهما عثمان بحبل وأعطاهما سوطين فتجالدا بهما وقال عمر بن شبة في خبره وقال الأحوص فيها أيضا وقد أنشدني علي بن سليمان الأخفش هذه الأبيات وزاد فيها على رواية عمر بن شبة بيتين فأضفتهما إليها\n(وإني ليدعوني هوى أم جعفر ... وجاراتها من ساعة فأجيب)\n(وإني لآتي البيت ما إن أحبه ... وأكثر هجر البيت وهو حبيب)\n(وأغضي على أشياء منكم تسوؤني ... وأدعى إلى ما سركم فأجيب)\n(هبيني أمرأ إما بريئا ظلمته ... وإما مسيئا مذنبا فيتوب)\n(فلا تتركي نفسي شعاعا فإنها ... من الحزن قد كادت عليك تذوب)\n(لك الله إني واصل ما وصلتني ... ومثن بما أوليتني ومثيب)\n(وأخذ ما أعطيت عفوا وإنني ... لأزور عما تكرهين هيوب)\nكذا ذكره الأخفش في هذه الأبيات الأخيرة وهي مروية للمجنون في عدة\nروايات وهي بشعره أشبه وفي هذه الأشعار التي مضت أغان نسبتها صوت\n(أدور ولولا أن أرى أم جعفر ... بأبياتكم ما درت حيث أدور)\n(أدور على أن لست أنفك كلما ... أتيت عدوا بالبنان يشير)\nلغناء لمعبد وله فيه لحنان ثقيل أول بالسبابة في مجرى البنصر عن عمرو ولإسحاق فيهما وفي قوله\n(أزور البيوت اللاصقات ببتها ... )\nبعده\n(أدور ولولا أن أرى أم جعفر ... )\nحن من الرمل وفي البيتين اللذين فيهما غناء معبد للغريض ثقيل أول عن الهشامي ولإبراهيم خفيف ثقيل وفيه لحن لشاريه عن ابن المعتز ولم يذكر طريقته\n(إذا أنا لم أغفر لأيمن ذنبه ... فمن ذا الذي يعفو له ذنبه بعدي)\n(أريد مكافأة له وتصدني ... يد لأدانيه مباركة عندي)\nالغناء لمعبد ثاني ثقيل بالوسطى عن يحيى المكي وذكر غيره أنه منحول يحيى إلى معبد وفيه ثقيل أول ينسب إلى عريب ورونق ومنها وهو\nصوت","topic":"أخبار وضاح اليمن ونسبه","topicNo":65,"sp":13,"spl":"أخبار الأحوص مع أم جعفر","partialRef":{"sid":"b38-13","gi":2,"vi":0,"side":0},"partial":1},
{"id":"b65-19","bab":"الجزء 6","sec":"من المائة المختارة","page":"ج6 ص273","text":"(وإني لآتي البيت ما إن أحبه ... وأكثر هجر البيت وهو حبيب)\n(وأغضي على أشياء منكم تسوؤني ... وأدعى إلى ما سركم فأجيب)\n(وما زلت من ذكراك حتى كأنني ... أميم بأفياء الديار سليب)\n(أبثك ما ألقى وفي النفس حاجة ... لها بين جلدي والعظام دبيب)\n(لك الله إني واصل ما وصلتني ... ومثن بما أوليتني ومثيب)\n(وآخذ ما أعطيت عفوا وإنني ... لأزور عما تكرهين هيوب)\n(فلا تتركي نفسي شعاعا فإنها ... من الحزن قد كادت عليك تذوب)\nلشعر للأحوص ومن الناس من ينسب البيت الخامس وما بعده إلى المجنون والغناء في اللحن المختار لدحمان وهو ثقيل أول مطلق في مجرى البنصر وذكر الهشامي أن في الأبيات الأربعة لإبن سريج لحنا من الثقيل الأول فلا أعلم ألحن دحمان عنى أم ثقيلا آخر وفي\n(لك الله إني واصل ما وصلتني ... ومثن بما أوليتني ومثيب)\nإسحاق ثاني ثقيل بالوسطى عن عمرو وفيها لإبراهيم خفيف رمل بالوسطى أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير قال حدثني محمد بن حسن قال الزبير وحدثني عبد الرحمن بن عبد الله الزهري عن محرز\nأن أم جعفر لما أكثر الأحوص في ذكرها جاءت منتقبة فوقفت عليه في مجلس قومه ولا يعرفها وكانت امرأة عفيفة فقالت له اقض ثمن الغنم التي ابتعتها مني فقال ما ابتعت منك شيئا فأظهرت كتابا قد وضعته عليه وبكت وشكت حاجة وضرا وفاقة وقالت يا قوم كلموه فلامه قومه وقالوا اقض المرأة حقها فجعل يحلف أنه ما رآها قط ولا يعرفها فكشفت وجهها وقالت ويحك أما تعرفني فجعل يحلف مجتهدا أنه ما يعرفها ولا رآها قط حتى إذا استفاض قولها وقوله واجتمع الناس وكثروا وسمعوا ما دار وكثر لغطهم وأقوالهم قامت ثم قالت أيها الناس اسكتوا ثم أقبلت عليه وقالت يا عدو الله صدقت والله مالي عليك حق ولا تعرفني وقد حلفت على ذلك وأنت صادق وأنا أم جعفر وأنت تقول قلت لأم جعفر وقالت لي أم جعفر في شعرك فخجل الأحوص وانكسر عن ذلك وبرئت عندهم","topic":"أخبار وضاح اليمن ونسبه","topicNo":65,"sp":14,"spl":"من المائة المختارة — من المائة المختارة"},
{"id":"b65-20","bab":"الجزء 6","sec":"أبو السائب المخزومي يطرب لشعره","page":"ج6 ص274","text":"أخبرني الحرمي قال حدثنا الزبير وأخبرني به محمد بن العباس اليزيدي قال حدثنا ثعلب قال حدثنا الزبير عن عبد الملك بن عبد العزيز قال أنشدت أبا السائب المخزومي قول الأحوص\n(لقد منعت معروفها أم جعفر ... وإني إلى معروفها لفقير)\nلما انتهيت إلى قوله\n(أزور على أن لست أنفك كلما ... أتيت عدوا بالبنان يشير)\nأعجبه ذلك وطرب وقال أتدري يابن أخي كيف كانوا يقولون اساعة دخل الساعة خرج الساعة مر الساعة رجع وجعل يومئ بإبهاميه إلى وراء منكبيه وبسبابته إلى حيال وجهه ويقلبها يحكي ذهابه ورجوعه صوت","topic":"أخبار وضاح اليمن ونسبه","topicNo":65,"sp":14,"spl":"من المائة المختارة — من المائة المختارة"},
{"id":"b65-21","bab":"الجزء 6","sec":"من المائة المختارة","page":"ج6 ص275","text":"(صاح قد لمت ظالما ... فانظر أن كنت لائما)\n(هل ترى مثل ظبية ... قلدوها التمائما)\nلشعر لعمر بن أبي ربيعة والغناء في اللحن المختار لمالك خفيف ثقيل بإطلاق الوتر في مجرى البنصر عن إسحاق وأخبرني ذكاء وجه الرزة أن فيه لعريب رملا بالبنصر وهو الذي فيه سجحة وفيه لإبن المكي خفيف ثقيل آخر بالوسطى وزعم الهشامي أن فيه خفيف رمل بالوسطى لإبن سريج وقد سمعها ممن يغينه وذكر حبش أن فيه رملا آخر للغريض ولعاتكة بنت شهدة فيه خفيف ثقيل وهو من جيد صنعتها وذكر جحظة عن أصحابه أن لحنها الرمل هو اللحن المختار وأن إسحاق كان يقدمها ويستجيدها ويزعم أنه أخذه عنها وقال ابن المعتز حدثني أبو عبد الله الهشامي أن عريب صنعت فيه لحنها الرمل بعد أن أفضت الخلافة إلى المعتصم فأعجبه وأمرها أن تطرحه على جواريه ولم أسمع بشرا قط غناه أحسن من خشف الواضحية وكل أخبار هؤلاء المغنين قد ذكرت أولها موضع تذكر فيه إلا عاتكة بنت شهدة فإن أخبارها تذكر ها هنا لأنه ليس لها شيء أعرفه من الصنعة فأذكره غير هذا وقد ذكر جحظة عن أصحابه أن لحنها هو المختار فوجب أن نذكر أخبارها معه أسوة غيرها","topic":"أخبار وضاح اليمن ونسبه","topicNo":65,"sp":14,"spl":"من المائة المختارة — من المائة المختارة"},
{"id":"b65-22","bab":"الجزء 6","sec":"عاتكة بنت شهدة وشيء من أخبارها","page":"ج6 ص276","text":"كانت عاتكة بنت شهدة مدنية وأمها شهدة جارية الوليد بن يزيد وهو الصحيح وكانت شهدة مغنية أيضا حدثني محمد بن يحيى الصولي قال حدثنا العلاء قال حدثني علي بن محمد النوفلي قال حدثني عبد الله بن العباس الربيعي عن بعض المغنين قال كنا ليلة عند الرشيد ومعنا ابن جامع والموصلي وغيرهما وعنده في تلك الليلة محمد بن داود بن إسماعيل بن علي فتغنى المغنون ثم اندفع محمد بن داود فغناه بين أضعافهم صوت\n(أم الوليد سلبتني حلمي ... وقتلتني فتخوفي إثمي)\n(بالله يا أم الوليد أما ... تخشين في عواقب الظلم)\n(وتركتني أبغي الطبيب وما ... لطبيبنا بالداء من علم)\n(خافي إلهك في ابن عمك قد ... زودته سقما على سقم)\nال فاستحسن الرشيد الصوت واستحسنه جميع من حضره وطربوا له فقال له الرشيد ياحبيبي لمن هذا الصوت فقال يا أمير المؤمنين سل هؤلاء المغنين لمن هو فقالوا والله ما ندري وإنه لغريب فقال بحياتي لمن هو فقال وحياتك ما أدري إلا أني أخذته من شهدة جارية الوليد أم عاتكة بنت شهدة هذا الشعر المذكور لإبن قيس الرقيات والغناء لإبن محرز وله فيه لحنان أحدهما ثقيل أول بالخنصر في مجرى الوسطى عن إسحاق والآخر خفيف ثقيل بالبنصر عن عمرو وفيه لسليم خفيف رمل بالبنصر ولحسين بن محرز ثقيل أول عن الهشامي وحبش\nأخبرني محمد بن مزيد عن حماد بن إسحاق عن أبيه أنه ذكر عاتكة بنت شهدة يوما فقال كانت أضرب من رأيت بالعود ولقد مكثت سبع سنين أختلف إليها في كل يوم فتضار بني ضربا أو ضربين ووصل إليها مني ومن أبي أكثر من ثلاثين ألف درهم بسببي دراهم وهدايا أخبرني يحيى بن علي بن يحيى عن أبيه عن إسحاق قال كانت عاتكة بنت شهدة أحسن خلق الله غناء وأرواهم وماتت بالبصرة وأمها شهدة نائحة من أهل مكة وكان ابن جامع يلوذ منها بكثرة الترجيع فكان إذا أخذ يتزايد في غنائه قالت له إلى أين يا أبا القاسم ما هذا الترجيع الذي لا معنى له عد بنا إلى معظم الغناء ودع من جنونك فأضجرته يوما بين يدي الرشيد فقال لها إني أشتهي علم الله أن تحتك شعرتي بشعرتك فقالت أخسأ قطع الله ظهرك ولم تعد لأذاه بعدها أخبرني حبيب بن نصر المهلبي قال حدثنا الزبير بن بكار قال قال لي علي ابن جعفر بن محمد دخلت على جواري المرواني المغنيات بمكة وعاتكة بنت شهدة تطارحهن لحنها\n(يا صاحبي دعا الملامة واعلما ... أن الهوى يدع الكرام عبيدا)\nجعلت واحدة منهن تقول يدع الرجال عبيدا فصاحت بها عاتكة بنت شهدة ويلك بندار الزيات العاض بظر أمه رجل أفمن الكرام هو قال فكنت إذا مر بي بندار أو رأيته غلبني الضحك فأستحي منه وأخذ بيده وأجعل ذلك بشاشة حتى أورث هذا بيني وبينه مقاربة فكان يقول أبو الحسن علي بن جعفر صديق لي\nوكان مخارق مملوكا لعاتكة وهي علمته الغناء ووضعت يده على العود ثم باعته فانتقل من ملك رجل إلى ملك آخر حتى صار إلى الرشيد وقد ذكر ذلك في أخباره صوت","topic":"أخبار وضاح اليمن ونسبه","topicNo":65,"sp":15,"spl":"عاتكة بنت شهدة وشيء من أخبارها — من المائة المختارة"},
{"id":"b65-23","bab":"الجزء 6","sec":"من المائة المختارة","page":"ج6 ص278","text":"(ولو أن ما عند ابن بجرة عندها ... من الخمر لم تبلل لهاتي بناطل)\n(لعمري لأنت البيت أكرم أهله ... وأقعد في أفيائه بالأصائل)\nعروضه من الطويل الشعر لأبي ذؤيب الهذلي والغناء لحكم الوادي ولحنه المختار من الثقيل الأول بالبنصر في مجراها ابن بجرة هذا فيما ذكره الأصمعي رجل كان يبيع الخمر بالطائف وزعم أن الناطل كوز تكال به الخمر وقال ابن الأعرابي ليس هذا بشيء وزعم أن الناطل الشيء يقال ما في الإناء ناطل أي شيء وقال أبو عمرو الشيباني سمعت الأعراب يقولون الناطل الجرعة من الماء واللبن والنبيذ انتهى","topic":"أخبار وضاح اليمن ونسبه","topicNo":65,"sp":15,"spl":"عاتكة بنت شهدة وشيء من أخبارها — من المائة المختارة"},
{"id":"b66-1","bab":"الجزء 6","sec":"ذكر أبي ذؤيب وخبره ونسبه","page":"ج6 ص279","text":"هو خويلد بن خالد بن محرث بن زبيد بن مخزوم بن صاهلة بن كاهل بن الحارث نميم بن سعد بن هذيل بن مدركة بن الياس بن مضر بن نزار وهو أحد المخضرمين ممن أدرك الجاهلية والإسلام وأسلم فحسن إسلامه ومات في غزاة إفريقية أخبرني أبو خليفة قال حدثنا محمد بن سلام قال كان أبو ذؤيب شاعرا فحلا لا غميزة فيه ولا وهن وقال ابن سلام قال أبو عمرو بن العلاء سئل حسان بن ثابت من أشعر الناس قال أحيا أم رجلا قالوا حيا قال أشعر الناس حيا هذيل وأشعر هذيل غير مدافع أبو ذؤيب قال ابن سلام ليس هذا من قول أبي عمرو ونحن نقوله أخبرني أبو خليفة قال حدثنا محمد بن سلام قال أخبرني محمد بن معاذ العمري قال في التوراة أبو ذؤيب مؤلف زورا وكان اسم الشاعر بالسريانية مؤلف\nزورا فأخبرت بذلك بعض أصحاب العربية وهو كثير بن إسحاق فعجب منه وقال قد بلغني ذاك وكان فصيحا كثير الغريب متمكنا في الشعر قال أبو زيد عمر بن شبة تقدم أبو ذؤيب جميع شعراء هذيل بقصيدته العينية التي يرثي فيها بنيه يعني قوله\n(أمن المنون وريبة تتوجع ... والدهر ليس بمعتب من يجزع)\nوهذه يقولها في بنين له خمسة أصيبوا في عام واحد بالطاعون ورثاهم فيها وسنذكر جميع ما يغنى فيه منها على أثر أخباره هذه أخبرني الحسين بن يحيى عن حماد بن إسحاق عن أبيه عن مصعب الزبيري وأخبرني حرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عمي قال كان أبو ذؤيب الهذلي خرج في جند عبد الله بن سعد بن أبي سرج أحد\nبني عامر بن لؤي إلى أفريقية سنة ست وعشرين غازيا إفرنجة في زمن عثمان فلما فتح عبد الله بن سعد إفريقية وما والاها بعث عبد الله بن الزبير وكان في جنده بشيرا إلى عثمان بن عفان وبعث معه نفرا فيهم أبو ذؤيب ففي عبد الله يقول أبو ذؤيب\n(فصاحب صدق كسيد الضرا ... ينهض في الغزو نهضا نجيحا)\nي قصيدة له فلما قدموا مصر مات أبو ذؤيب بها وقدم ابن الزبير على عثمان وهو يومئذ في قول ابن الزبير ابن ست وعشرين سنة وفي قول الواقدي ابن أربع وعشرين سنة وبشر عبد الله عند مقدمه بخبيب بن عبد الله بن الزبير وبأخيه عروة بن الزبير وكانا ولدا في ذلك العام وخبيب أكبرهما قال مصعب فسمعت أبي والزبير بن خبيب بن ثابت بن عبد الله بن الزبير يقولان قال عبد الله بن الزبير أحاط بنا جرجير صاحب إفريقية وهو ملك إفرنجة في عشرين ألفا ومائة ألف ونحن في عشرين ألفا فضاق بالمسلمين أمرهم واختلفوا في الرأي فدخل عبد الله بن سعد فسطاطه يخلو ويفكر قال عبد الله بن الزبير فرأيت عورة من جرجير والناس على مصافهم رأيته على برذون أشهب خلف أصحابه منقطعا منهم معه جاريتان له تظلانه من الشمس بريش الطواويس فجئت فسطاط عبد الله فطلبت الإذن عليه من حاجبه فقال إنه في شأنكم وإنه قد أمرني أن أمسك\nالناس عنه قال فدرت فأتيت مؤخر فسطاطه فرفعته ودخلت عليه فإذا هو مستلق على فراشه ففزع وقال ما الذي أدخلك علي يابن الزبير فقلت إيه وإيه كل أزب نفور إني رأيت عورة من عدونا فرجوت الفرصة فيه وخشيت فواتها فاخرج فاندب الناس إلي قال وما هي فأخبرته فقال عورة لعمري ثم خرج فرأى ما رأيت فقال أيها الناس انتدبوا مع ابن الزبير إلى عدوكم فاخترت ثلاثين فارسا وقلت إني حامل فاضربوا عن ظهري فإني سأكفيكم من ألقى إن شاء الله تعالى فحملت في الوجه الذي هو فيه وحملوا فذبوا عني حتى خرقتهم إلى أرض خالية وتبينته فصمدت صمدة فوالله ما حسب إلا إني رسول ولا ظن أكثر أصحابه إلا ذاك حتى رأى ما بي من أثر السلاح فثنى برذونه هاربا فأدركته فطعنته فسقط ورميت بنفسي عليه واتقت جاريتاه عنه السيف فقطعت يد إحداهما وأجهزت عليه ثم رفعت رأسه في رمحي وجال أصحابه وحمل المسلمون في ناحيتي وكبروا فقتلوهم كيف شاؤوا وكانت الهزيمة فقال لي عبد الله بن سعد ما أحد أحق بالبشارة منك فبعثني إلى عثمان وقدم مروان بعدي على عثمان حين اطمأنوا وباعوا المغنم وقسموه وكان مروان قد صفق على\nالخمس بخمسمائة ألف فوضعها عنه عثمان فكان ذلك مما تكلم فيه بسببه فقال عبد الرحمن بن حنبل بن مليل وكان هو وأخوه كلدة أخوي صفوان بن أمية بن خلف لأمه وهي صفية بنت معمر بن حبيب بن وهب بن حذافة بن جمح وكان أبوهما ممن سقط من اليمن إلى مكة\n(أحلف بالله جهد اليمين ... ما ترك الله أمرا سدى)","topic":"ذكر أبي ذؤيب وخبره ونسبه","topicNo":66,"sp":0,"spl":"ذكر أبي ذؤيب وخبره ونسبه"},
{"id":"b66-2","bab":"الجزء 6","sec":"ذكر أبي ذؤيب وخبره ونسبه","page":"ج6 ص279","text":"(ولكن خلقت لنا فتنة ... لكي نبتلى فيك أو تبتلى)\n(دعوت الطريد فأدنيته ... خلافا لسنة من قد مضى)\n(وأعطيت مروان خمس العباد ... ظلما لهم وحميت الحمى)\n(ومالا أتاك به الأشعري ... من الفيء أعطيته من دنا)\n(وإن الأمينين قد بينا ... منار الطريق عليه الهدى)\n(فما أخذا درهما غيلة ... ولا قسما درهما في هوى)\nال والمال الذي ذكر أن الأشعري جاء به مال كان أبو موسى قدم به على عثمان من العراق فأعطى عبد الله بن أسيد بن أبي العيص منه مائة ألف درهم وقيل ثلثمائة ألف درهم فأنكر الناس ذلك","topic":"ذكر أبي ذؤيب وخبره ونسبه","topicNo":66,"sp":1,"spl":"ذكر أبي ذؤيب وخبره ونسبه — ذكره ابن بجرة"},
{"id":"b66-3","bab":"الجزء 6","sec":"ذكره ابن بجرة","page":"ج6 ص284","text":"أخبرني أحمد بن عبيد الله قال حدثنا عمر بن شبة عن محمد بن يحيى عن عبد العزيز أظنه ابن الدراوردي قال ابن بجرة الذي ذكره أبو ذؤيب رجل من بني عبيد بن عويج بن عدي بن كعب من قريش ولم يسكنوا مكة ولا المدينة قط وبالمدينة منهم امرأة ولهم موال أشهر منهم يقال لهم بنو سجفان وكان ابن بجرة هذا خمارا وهذا الصوت الذي ذكرناه من لحن حكم الوادي المختار من قصيدة لأبي ذؤيب طويلة فمما يغنى فيه منها صوت\n(أساءلت رسم الدار أم لم تسائل ... عن الحي أم عن عهده بالأوائل)\n(عفا غير رسم الدار ما إن تبينه ... وعفر ظباء قد ثوت في المنازل)\n(فلو أن ما عند ابن بجرة عندها ... من الخمر لم تبلل لهاتي بناطل)\n(فتلك التي لا يذهب الدهر حبها ... ولا ذكرها ما أرزمت أم حائل)\nغناه الغريض ثقيلا أول بالوسطى ويقال إن لمعبد فيه أيضا لحنا\nقوله أساءلت يخاطب نفسه ويروي عن السكن أو عن أهله والسكن الذي كانوا فيه وقال الأصمعي السكن سكن الدار والسكن المنزل أيضا ويروى عفا غير نؤي الدار والنؤي حاجز يجعل حول بيوت الأعراب لئلا يصل المطر إليها ويروى وهو الصحيح\n(وأقطاع طفي قد عفت في المعاقل ... )\nالطفي خوص المنقل والمعاقل حيث نزلوا فامتنعوا واحدها معقل وواحد الطفي طفية وأرزمت حنت والحائل الأنثى والسقب الذكر ومنها صوت\n(وإن حديثا منك لو تبذلينه ... جنى النحل في ألبان عوذ مطافل)\n(مطافل أبكار حديث نتاجها ... تشاب بماء مثل ماء المفاصل)\nغناه ابن سريج رملا بالوسطى جنى النحل العسل والعوذ جمع عائذ الناقة حين تضع فهي عائذ فإذا تبعها ولدها قيل لها مطفل والمفاصل منفصل السهل من الجبل حيث يكون الرضراض والماء الذي يستنقع فيها أطيب المياه وتشاب تخلط وأخبرني محمد بن العباس اليزيدي قال حدثنا الرياشي قال حدثنا الأصمعي\nأن أبا ذؤيب إنما عنى بقوله مطافل أبكار أن لبن الأبكار أطيب الألبان وهو لبنها لأول بطن وضعت قال وكذلك العسل فإن أطيبه ما كان من بكر النحل قال وحدثني كردين قال كتب الحجاج إلى عامله على فارس ابعث إلي بعسل من عسل خلار من النحل الأبكار من الدستفشار الذي لم تمسه النار","topic":"ذكر أبي ذؤيب وخبره ونسبه","topicNo":66,"sp":1,"spl":"ذكر أبي ذؤيب وخبره ونسبه — ذكره ابن بجرة","partial":1},
{"id":"b66-4","bab":"الجزء 6","sec":"بعض من قصيدته العينية الشهيرة","page":"ج6 ص286","text":"فأما قصيدته العينية التي فضل بها فمما يغنى به منها صوت\n(أمن المنون وريبها تتوجع ... والدهر ليس بمعتب من يجزع)\n(قالت أمامة ما لجسمك شاحبا ... منذ ابتذلت ومثل مالك ينفع)\n(أم ما لجنبك لا يلائم مضجعا ... إلا أقض عليك ذاك المضجع)\n(فأجبتها أن ما لجسمي أنه ... أودى بني من البلاد فودعوا)\nروضه من الكامل غناه ابن محرز ولحنه من القدر الأوسط من الثقيل الأول بالبنصر في مجراها قال الأصمعي سميت المنون منونا لأنها تذهب بمنة كل شيء وهي قوته وروى الأصمعي وريبه فذكر المنون والشاحب المغير المهزول يقال شحب يشحب ابتذلت امتهنت نفسك وكرهت الدعة والزينة ولزمت العمل والسفر ومثل مالك يغنيك عن هذا فاشتر لنفسك من يكفيك ذلك ويقوم لك به ويلائم يوافق أقض عليك أي خشن فلم تستطع أن تضطجع عليه والقضض الرمل والحصى قال الراجز\n(إن أحيحا مات من غير مرض ... ووجد في مرمضه حيث ارتمض)\n(عساقل وجبأ فيها قضض ... )\nودعوا ذهبوا استعمل ذلك في الذهاب لأن من عادة المفارق أن يودع أخبرني أحمد بن عبيد الله بن عمار قال حدثني أحمد بن عمر النحوي قال حدثني أبي عن الهيثم بن عدي عن ابن عياش قال لما مات جعفر بن المنصور الأكبر مشى المنصور في جنازته من المدينة إلى مقابر قريش ومشى الناس أجمعون معه حتى دفنه ثم انصرف إلى قصره ثم أقبل على الربيع فقال يا ربيع أنظر من في أهلي ينشدني\n(أمن المنون وريبها تتوجع ... )\nتى أتسلى عن مصيبتي قال الربيع فخرجت إلى بني هاشم وهم بأجمعهم حضور فسألتهم عنها فلم يكن فيهم أحد يحفظها فرجعت فأخبرته فقال والله لمصيبتي بأهل بيتي ألا يكون فيهم أحد يحفظ هذا لقلة رغبتهم في الأدب أعظم وأشد علي من مصيبتي بابني ثم قال أنظر هل في القواد والعوام من الجند من يعرفها فإني أحب أن أسمعها من إنسان ينشدها فخرجت فاعترضت الناس فلم أجد أحدا ينشدها ألا شيخا كبيرا مؤدبا قد انصرف من موضع تأديبه فسألته\nهل تحفظ شيئا من شعره فقال نعم شعر أبي ذؤيب فقلت أنشدني فابتدأ هذه القصيدة العينية فقلت له أنت بغيتي ثم أوصلته إلى المنصور فاستنشده إياها فلما قال\n(والدهر ليس بمعتب من يجزع ... )\nال صدق والله فأنشدني هذا البيت مائة مرة ليتردد هذا المصراع علي فأنشده ثم مر فيها فلما انتهى إلى قوله\n(والدهر لا يبقى على حدثانه ... جون السراة له جدائد أربع)\nال سلا أبو ذؤيب عند هذا القول ثم أمر الشيخ بالإنصراف فاتبعته فقلت له أأمر لك أمير المؤمنين بشيء فأراني صرة في يده فيها مائة درهم","topic":"ذكر أبي ذؤيب وخبره ونسبه","topicNo":66,"sp":2,"spl":"بعض من قصيدته العينية الشهيرة","partialRef":{"sid":"b66-1","gi":0,"vi":0,"side":1},"partial":1},
{"id":"b66-5","bab":"الجزء 6","sec":"الخيانة مشتركة","page":"ج6 ص288","text":"حدثنا محمد بن العباس اليزيدي قال حدثنا الرياشي قال حدثنا الأصمعي قال كان أبو ذؤيب الهذلي يهوى امرأة يقال لها أم عمرو وكان يرسل إليها خالد بن زهير فخانه فيها وكذلك كان أبو ذؤيب فعل برجل يقال له عويم بن مالك بن عويمر وكان رسوله إليها فلما علم أبو ذؤيب بما فعل خالد صرمها فأرسلت تترضاه فلم يفعل وقال فيها\n(تريدين كيما تجمعيني وخالدا ... وهل يجمع السيفان ويحك في غمد)\n(أخالد ما راعيت مني قرابة ... فتحفظني بالغيب أو بعض ما تبدي)\n(دعاك إليها مقلتاها وجيدها ... فملت كما مال المحب على عمد)\n(وكنت كرقراق السراب إذا بدا ... لقوم وقد بات المطي بهم يخدي)\n(فآليت لا أنفك أحدو قصيدة ... تكون وإياها بها مثلا بعدي)\nناه ابن سريج خفيف رمل بالبنصر الغيب السر والرقراق الجاري ويروي أحذو قصيدة فمن قال أحذو بالذال المعجمة أراد أصنع ومن قال أحدو أراد أغني وقال أبو ذؤيب في ذلك\n(وما حمل البختي عام غياره ... عليه الوسوق برها وشعيرها)\n(أتى قرية كانت كثيرا طعامها ... كرفغ التراب كل شيء يميرها)\nلرفع من التراب الكثير اللين\n(فقيل تحمل فوق طوقك إنها ... مطبعة من يأتها لا يضيرها)\n(بأعظم مما كنت حملت خالدا ... وبعض أمانات الرجال غرورها)\n(ولو أنني حملته البزل ما مشت ... به البزل حتى تتلئب صدورها)\nتلئب تستقيم وتنتصب وتمتد وتتابع\n(خليلي الذي دلى لغي خليلتي ... جهارا فكل قد أصاب عرورها)\nقال عرة بكذا أي أصابه به\n(فشأنكها إني أمين وإنني ... إذا ما تحالى مثلها لا أطورها)\nتحالى من الحلاوة أطورها أقربها\n(أحاذر يوما أن تبين قرينتي ... ويسلمها أحرازها ونصيرها)\nلأحراز الحصون قرينتي نفسي\n(وما أنفس الفتيان إلا قرائن ... تبين ويبقى هامها وقبورها)\n(فنفسك فاحفظها ولا تفش للعدا ... من السر ما يطوى عليه ضميرها)\n(وما يحفظ المكتوم من سر أهله ... إذا عقد الأسرار ضاع كبيرها)\n(من القوم إلا ذو عفاف يعينه ... على ذاك منه صدق نفس وخيرها)\n(رعى خالد سرى ليالي نفسه ... توالى على قصد السبيل أمورها)\n(فلما تراماه الشباب وغيه ... وفي النفس منه فتنة وفجورها)\n(لوى رأسه عني ومال بوده ... أغانيج خود كان فينا يزورها)\n(تعلقه منها دلال ومقلة ... تظل لأصحاب الشقاء تديرها)\n(فإن حراما أن أخون أمانة ... وآمن نفسا ليس عندي ضميرها)\nأجابه خالد بن زهير\n(لا يبعدن الله لبك إذ غزا ... وسافر والأحلام جم عثورها)\nزا وسافر لبك ذهب عنك والعثور من العثار وهو الخطأ\n(وكنت إماما للعشيرة تنتهي ... إليك إذا ضاقت بأمر صدورها)\n(لعلك إما أم عمرو تبدلت ... سواك خليلا شاتمي تستخيرها)\nلإستخارة الإستعطاف\n(فإن التي فينا زعمت ومثلها ... لفيك ولكني أراك تجورها)\nجورها تعرض عنها\n(ألم تنتقذها من عويم بن مالك ... وأنت صفي نفسه وسجيرها)\n(فلا تجزعن من سنة أنت سرتها ... فأول راض سنة من يسيرها)\nويروى قد أسرتها أي جعلتها سائرة ومن رواه هكذا روى يسيرها لأن مستقبل أفعل أسارها يسيرها ويسيرها مستقبل سار السيرة يسيرها\n(فإن كنت تشكو من خليل مخانة ... فتلك الجوازي عقبها ونصورها)\nقبها يريد عاقبتها ونصورها أي تنصر عليك الواحد نصر\n(وإن كنت تبغي للظلامة مركبا ... ذلولا فإني ليس عندي بعيرها)\n(نشأت عسيرا لا تلين عريكتي ... ولم يعل يوما فوق ظهري كورها)\n(متى ما تشأ أحملك والرأس مائل ... على صعبة حرف وشيك طمورها)\n(فلا تك كالثور الذي دفنت له ... حديدة حتف ثم أمسى يثيرها)\n(يطيل ثواء عندها ليردها ... وهيهات منه دارها وقصورها)\n(وقاسمها بالله جهدا لأنتم ... الذ من السلوى إذا ما نشورها)\nشورها نجتنيها السلوى ها هنا العسل\n(فلم يغن عنه خدعه يوم أزمعت ... صريمتها والنفس مر ضميرها)\n(ولم يلف جلدا حازما ذا عزيمة ... وذا قوة ينفي بها من يزورها)\n(فأقصر ولم تأخذك مني سحابة ... ينفر شاء المقلعين خريرها)\nلمقلعين الذين أصابهم القلع وهو السحاب\n(ولا تسبقن الناس مني بخمطة ... من السم مذرور عليها ذرورها)","topic":"ذكر أبي ذؤيب وخبره ونسبه","topicNo":66,"sp":3,"spl":"الخيانة مشتركة"},
{"id":"b66-6","bab":"الجزء 6","sec":"الخيانة مشتركة","page":"ج6 ص288","text":"أخبرني محمد بن الحسن بن دريد قال حدثنا السكن بن سعيد قال حدثنا العباس بن هشام قال حدثني أبو عمرو عبد الله بن الحارث الهذلي من أهل المدينة قال خرج أبو ذؤيب مع ابنه وابن أخ له يقال له ابو عبيد حتى قدموا على عمر بن الخطاب رضي الله عنه فقال له أي العمل افضل يا أمير المؤمنين قال الإيمان بالله ورسوله قال قد فعلت فأيه أفضل بعده الجهاد في سبيل الله قال ذلك كان علي وإني لا أرجو جنة ولا أخاف نارا ثم خرج فغزا أرض الروم مع المسلمين فلما قفلوا أخذه الموت فاراد ابنه وابن أخيه أن يتخلفا عليه جميعا فمنعهما صاحب الساقة وقال ليتخلف عليه أحدكما وليعلم أنه مقتول فقال لهما أبو ذؤيب اقترعا فطارت القرعة لأبي عبيد فتخلف عليه ومضى ابنه مع\nالناس فكان أبو عبيد يحدث قال قال لي أبو ذؤيب يا أبا عبيد احفر ذلك الجرف برمحك ثم اعضد من الشجر بسيفك ثم اجررني إلى هذا النهر فإنك لا تفرغ حتى أفرغ فآغسلني وكفني ثم اجعلني في حفيري وإنثل علي الجرف برمحك وألق علي الغصون والشجر ثم اتبع الناس فإن لهم رهجة تراها في الأفق إذا مشيت كأنها جهامة قال فما أخطأ مما قال شيئا ولولا نعته لم أهتد لأثر الجيش وقال وهو يجود بنفسه\n(أبا عبيد رفع الكتاب ... واقترب الموعد والحساب)\n(وعند رحلي جمل نجاب ... أحمر في حاركه انصباب)\nم مضيت حتى لحقت الناس فكان يقال إن أهل الإسلام ابعدوا الأثر في بلد الروم فما كان وراء قبر أبي ذؤيب قبر يعرف لأحد من المسلمين","topic":"ذكر أبي ذؤيب وخبره ونسبه","topicNo":66,"sp":4,"spl":"الخيانة مشتركة"},
{"id":"b67-1","bab":"الجزء 6","sec":"ذكر حكم الوادي وخبره ونسبه","page":"ج6 ص294","text":"هو الحكم بن ميمون مولى الوليد بن عبد الملك وكان أبوه حلاقا يحلق رأس الوليد فاشتراه فأعتقه وكان حكم طويلا أحول يكري الجمال ينقل عليها الزيت من الشام إلى المدينة ويكنى أبا يحيى وقال مصعب بن عبد الله بن الزبير هو حكم بن يحيى بن ميمون وكان أصله من الفرس وكان جمالا ينقل الزيت من وادي القرى إلى المدينة وذكر حماد بن إسحاق عن أبيه أنه كان شيخا طويلا أحول أجنأ يخضب بالحناء وكان جمالا يحمل الزيت من جدة إلى المدينة وكان واحد دهره في الحذق وكان ينقر بالدف ويغني مرتجلا وعمر عمرا طويلا وغني الوليد بن عبد الملك وغنى الرشيد ومات في الشطر من خلافته وذكر أنه أخذ الغناء من عمر الوادي قال وكان بوادي القرى جماعة من المغنين فيهم عمر بن زاذان وقال ابن داود بن زاذان وهو الذي كان يسميه الوليد جامع لذتي وحكم بن يحيى وسليمان وخليد بن عتيك وقيل ابن عبيد ويعقوب\nالوادي وكل هؤلاء كان يصنع فيحسن أخبرني يحيى بن علي قال حدثني حماد قال قال لي أبي أحذق من رأيت من المغنين أربعة جدك وحكم وفليح بن العوراء وسياط قلت وما بلغ من حذقهم قال كانوا يصنعون فيحسنون ويؤدون غناء غيرهم فيحسنون قال إسحاق وقال لي أبي ما في هؤلاء الذين تراهم من المغنين أطبع من حكم وابن جامع وفليح أدرى منهما بما خرج من رأسه وذكر هارون بن محمد بن عبد الملك الزيات أن أحمد بن المكي حدثه عن أبيه قال حدثني حكم الوادي وأخبرني به محمد بن يحيى الصولي قال حدثنا الغلابي عن حماد بن إسحاق عن أحمد بن المكي عن أبيه عن حكم الوادي قال أدخلني عمر الوادي على الوليد بن يزيد وهو على حمار وعليه جبة وشي ورداء وشي وخف وشي وفي يده عقد جوهر وفي كمه شيء لا أدري ما هو فقال من غناني ما أشتهي فله ما في كمي وما علي وما تحتي فغنوه كلهم فلم يطرب فقال لي غن يا غلام فغنيت صوت\n(إكليلها ألوان ... ووجهها فتان)\n(وخالها فريد ... ليبس له جيران)\n(إذا مشت تثنت ... كأنها ثعبان)\nلشعر لمطيع بن إياس والغناء لحكم الوادي هزج بالوسطى وفيه لإبراهيم رمل خفيف بالوسطى فطرب وأخرج ما كان في كمه وإذا كيس فيه ألف\nدينار فرمى به إلي مع عقد الجوهر فلما دخل بعث إلي بالحمار وجميع ما كان عليه وهذا الخبر يذكر من عدة وجوه في أخبار مطيع بن إياس وفي حكم الوادي يقول رجل من قريش صوت\n(أبو يحيى أخو الغزل المغني ... بصير بالثقال وبالخفاف)\n(على العيدان يحسن ما يغني ... ويحسن ما يقول على الدفاف)\nناه حكم الوادي هزجا بالبنصر قال هارون بن عبد الملك قال أبو يحيى العبادي قال حدثني أحمد البارد قال دخلت على حكم يوما فقال لي يا قصافي إن رجلا من قريش قال في هذا الشعر\n(أبو يحيى أخو الغزل المغني ... )\nقد غنيت فيه فخذ العود حتى تسمعه مني فأخذت العود فضربت عليه وغنانيه فكنت أول من أخذ من حكم الوادي هذا الصوت قال أبو يحيى وقال إسحاق سمعت حكما الوادي يغني صوتا فاعجبني فسألته لمن هو فقال ولمن يكون هذا إلا لي وقال مصعب حدثني شيخ أنه سمع حكما الوادي يغني فقال له أحسنت فألقى الدف وقال للرجل قبحك الله تراني مع المغنين منذ ستين سنة وتقول لي أحسنت وقال لي هارون حدثني مدرك بن يزيد قال قال لي فليح بعث إلي يحيى بن خالد وإلى حكم الوادي وابن جامع معنا فأتيناه\nفقلت لحكم الوادي أو قال لي إن ابن جامع معنا فعاوني عليه لنكسره فلما صرنا إلى الغناء غنى حكم فصحت وقلت هكذا والله يكون الغناء ثم غنيت ففعل بي حكم مثل ذلك وغنى ابن جامع فما كنا معه في شيء فلما كان العشي أرسل إلى جاريته دنانير إن أصحابك عندنا فهل لك أن تخرجي إلينا فخرجت وخرج معها وصائف لها فأقبل عليها يقول لها من حيث يظن أنا لا نسمع ليس في القوم أنزه نفسا من فليح ثم أشار إلى غلام له إن ائت كل إنسان بألفي درهم فجاء بها فدفع إلى ابن جامع ألفين فأخذها فطرحها في كمه ولحكم مثل ذلك فطرحها في كمه ودفع إلي الفين فقلت لدنانير قد بلغ مني النبيذ فاحتبسيها لي عندك فأخذت الدراهم مني وبعثت بها إلي من الغد وقد زادت عليها مثلها وأرسلت إلي قد بعثت إليك بوديعتك وبشيء أحببت أن تفرقه على أخواتي تعني جواري","topic":"ذكر حكم الوادي وخبره ونسبه","topicNo":67,"sp":0,"spl":"ذكر حكم الوادي وخبره ونسبه","partial":1},
{"id":"b67-2","bab":"الجزء 6","sec":"شهرته في الهزج","page":"ج6 ص297","text":"قال هارون بن محمد قال حماد بن إسحاق قال أبي أربعة بلغوا في أربعة أجناس من الغناء مبلغا قصر عنه غيرهم معبد في الثقيل وابن سريج في الرمل وحكم في الهزج وإبراهيم في الماخوري قال هارون وحدثني أبي قال حدثني هبة الله بن إبراهيم بن المهدي عن أبيه قال\nزاد حكم الوادي الرشيد فبره ووصله بثلثمائة ألف درهم وسأله عمن يختار أن يكتب له بها إليه فقال اكتب لي بها إلى إبراهيم بن المهدي وكان عاملا له بالشام قال إبراهيم فقدم علي حكم بكتاب الرشيد فدفعت إليه ما كتب به ووصلته بمثل ما وصله إلا أني نقصته ألفا من الثلثمائة وقلت له لا أصلك بمثل صلة أمير المؤمنين فأقام عندي ثلاثين يوما أخذت منه فيها ثلثمائة صوت كل صوت منها أحب إلي من الثلثمائة الألف التي وهبتها له وأخبرني علي بن عبد العزيز عن عبيد الله بن خرداذبة قال قال مصعب بن عبد الله بينا حكم الوادي بالمدينة إذ سمع قوما يقولون لو ذهبنا إلى جارية ابن شقران فإنها حسنة الغناء فمضوا إليها وتبعهم حكم وعليه فروة فدخلوا ودخل معهم وصاحب المنزل يظن أنه معهم وهم يظنون أنه من قبل صاحب المنزل ولا يعرفونه فغنت الجارية أصواتا ثم غنت صوتا ثم صوتا فقال حكم الوادي أحسنت والله وصاح فقال له رب البيت يا ماص كذا وكذا من أمه وما يدريك ما الغناء فوثب عليه يتعتعه وأراد ضربه فقال له حكم يا عبدالله دخلت بسلام وأخرج كما دخلت وقام ليخرج فقال له رب البيت لا أو أضربك فقال حكم على رسلك أنا أعلم بالغناء منك ومنها وقال شدي موضع كذا وأصلحي موضع كذا وإندفع يغني فقالت الجارية إنه والله أبو يحيى فقال رب المنزل جعلت فداك المعذرة إلى الله وإليك لم أعرفك فقام حكم ليخرج فأبى الرجل فقال والله لأخرجن فسأعود إليها لكرامتها لا لكرامتك وذكر أحمد بن المكي عن أبيه أن حكما لم يشهر بالغناء ويذهب له\nالصوت به حتى صار الأمر إلى بني العباس فانقطع إلى محمد بن أبي العباس أمير المؤمنين وذلك في خلافة المنصور فأعجب به واختاره على المغنين وأعجبته أهزاجه وكان يقال إنه من أهزج الناس ويقال إنه غنى الأهزاج في آخر عمره وإن ابنه لامه على ذلك وقال له أبعد الكبر تغني غناء المخنثين فقال له اسكت فإنك جاهل غنيت الثقيل ستين سنة فلم أنل إلا القوت وغنيت الأهزاج منذ سنيات فأكسبتك ما لم تر مثله قط قال هارون بن محمد وقال يحيى بن خالد ما رأينا فيمن يأتينا من المغنين أحدا أجود أداء من حكم وليس أحد يسمع غناء ثم يغنيه بعد ذلك إلا وهو يغيره ويزيد فيه وينقص إلا حكما فقيل لحكم ذلك فقال إني لست أشرب وغيري يشرب فإذا شرب تغير غناؤه أخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة قال كان خبر حكم الوادي يتناهى إلى المنصور ويبلغه ما يصله به بنو سليمان بن علي فيعجب لذلك ويستسرفه ويقول هل هو إلا أن حسن شعرا بصوته وطرب مستمعيه فماذا يكون وعلام يعطونه هذه العطايا المسرفة إلى أن جلس يوما في مستشرف له وقد كان حكم دخل إلى رجل من قواده أراه قال علي بن يقطين أو أبوه وهو يراه ثم خرج عشيا وقد حمله على بغلة له يعرفها المنصور وخلع عليه ثيابا يعرفها له فلما رآه المنصور قال من هذا فقيل حكم الوادي فحرك رأسه عليا ثم قال الآن علمت أن هذا يستحق ما يعطاه قيل وكيف ذلك يا\nأمير المؤمنين وأنت تنكر ما يبلغك منه قال لأن فلانا لا يعطي شيئا من ماله باطلا ولا يضعه إلا في حقه","topic":"ذكر حكم الوادي وخبره ونسبه","topicNo":67,"sp":1,"spl":"شهرته في الهزج"},
{"id":"b67-3","bab":"الجزء 6","sec":"المهدي يجيزه والهادي يعطيه","page":"ج6 ص300","text":"أخبرني الحسن بن علي قال حدثنا ابن أبي سعد قال حدثنا قعنب بن المحرز الباهلي عن الأصمعي قال رأيت حكما الوادي حين مضى المهدي إلى بيت المقدس وقد عارضه في الطريق وأخرج دفه ونقر فيه وله شعيرات على راسه وقال أنا والله يا أمير المؤمنين القائل\n(ومتى تخرج العروس ... فقد طال حبسها)\nتسرع إليه الحرس فقال دعوه وسأل عنه فأخبر أنه حكم الوادي فوصله وأحسن إليه لحن حكم في هذا الشعر المذكور هزج بالبنصر وفيه ألحان لغيره وقد ذكرت في أخبار الوليد بن يزيد أخبرني الحسن قال حدثنا ابن مهرويه قال حدثنا علي بن محمد النوفلي عن صالح الأضجم عن حكم الوادي قال كان الهادي يشتهي من الغناء ما توسط وقل ترجيعه ولم يبلغ أن يستخف جدا فأخرج ليلة ثلاث بدر وقال من أطربني فهي له فغناه ابن جامع وإبراهيم الموصلي والزبير بن دحمان فلم يصنعوا شيئا وعرفت ما أراد فغنيته لإبن سريج\nصوت\n(غراء كالليلة المباركة القمراء ... تهدي أوائل الظلم)\n(أكني بغير اسمها وقد علم ... الله خفيات كل مكتتم)\n(كأن فاها إذا تنسم عن ... طيب مشم وحسن مبتسم)\n(يسن بالضرو من براقش أو ... هيلان أو يانع من العتم)\nلشعر في هذا الغناء للنابغة الجعدي والصنعة لإبن سريج رمل بالبنصر فوثب عن فراشه طربا وقال أحسنت أحسنت والله اسقوني فسقي ووثقت بأن البدر لي فقمت فجلست عليها فأحسن ابن جامع المحضر وقال أحسن والله كما قال أمير المؤمنين وإنه لمحسن مجمل فلما سكن أمر الفراشين بحملها معي فقلت لإبن جامع مثلك يفعل ما فعلت في شرفك ونسبك فإن رأيت أن تشرفني بقبول إحداها فعلت فقال لا والله لا فعلت والله لوددت أن الله زادك وأسأل الله أن يهنيك ما رزقك ولحقني الموصلي فقال آخذ يا حكم من\nهذا فقلت لا والله ولا درهما واحدا لأنك لم تحسن المحضر","topic":"ذكر حكم الوادي وخبره ونسبه","topicNo":67,"sp":2,"spl":"المهدي يجيزه والهادي يعطيه — من المائة المختارة"},
{"id":"b67-4","bab":"الجزء 6","sec":"موته وشعر الدارمي فيه","page":"ج6 ص301","text":"ومات حكم الوادي من قرحة أصابته في صدره فقال الدارمي فيه قبل وفاته صوت\n(إن أبا يحيى اشتكى علة ... أصبح منها بين عواد)\n(فقلت والقلب به موجع ... يا رب عاف الحكم الوادي)\n(فرب بيض قادة سادة ... كأنصل سلت من اغماد)\n(نادمهم في مجلس لاهيا ... فأصمت المنشد والشادي)\nنى فيه حكم الوادي هزجا بالبنصر صوت","topic":"ذكر حكم الوادي وخبره ونسبه","topicNo":67,"sp":2,"spl":"المهدي يجيزه والهادي يعطيه — من المائة المختارة"},
{"id":"b67-5","bab":"الجزء 6","sec":"من المائة المختارة","page":"ج6 ص302","text":"(أمعارف الدمن القفار توهم ... ولقد مضى حول لهن مجرم)\n(ولقد وقفت على الديار لعلها ... بجواب رجع تحية تتكلم)\n(عن علم ما فعل الخليط فما درت ... أنى توجه بالخليط الموسم)\n(ولقد عهدت بها سعاد وإنها ... بالله جاهدة اليمين لتقسم)\n(إني لأوجه من تكلم عندها ... بألية ومخالف من يزعم)\n(فلها لدينا بالذي بذلت لنا ... ود يطول له العناء ويعظم)\nروضه من الكامل الشعر لنصيب من قصيدة يمدح بها عبد الملك بن\nمروان والغناء لإبن جامع له فيه لحنان ذكرهما إسحاق أحدهما ثاني ثقيل بإطلاق الوتر في مجرى الوسطى ولإبراهيم في البيتين الأولين ثقيل أول مطلق في مجرى الوسطى ولإسحاق وسياط فيهما ثقيل بالبنصر عن عمرو","topic":"ذكر حكم الوادي وخبره ونسبه","topicNo":67,"sp":2,"spl":"المهدي يجيزه والهادي يعطيه — من المائة المختارة"},
{"id":"b68-1","bab":"الجزء 6","sec":"ذكر ابن جامع وخبره ونسبه","page":"ج6 ص304","text":"هو إسماعيل بن جامع بن إسماعيل بن عبد الله بن المطلب بن أبي وداعة بن ضبيرة بن سعيد بن سعد بن سهم بن عمرو بن هصيص بن كعب بن لؤي بن غالب أخبرني الطوسي عن الزبير بن بكار عن عمه مصعب وأخبرنا محمد بن جرير الطبري قال حدثنا محمد بن حميد عن سلمة عن ابن إسحاق قالا جميعا مات ضبيرة السهمي وله مائة سنة ولم يظهر في رأسه ولا لحيته شيب فقال بعض شعراء قريش يرثيه\n(حجاج بيت الله إن ... ضبيرة السهمي ماتا)\n(سبقت منيته المشيب ... وكان ميتته افتلاتا)\n(فتزودوا لا تهلكوا ... من دون أهلكم خفاتا)\nال وأسر أبو وداعة كافرا يوم بدر ففداه ابنه المطلب وكان المطلب رجل صدق\nوقد روى عن النبي الحديث ويكنى ابن جامع أبا القاسم وأمه امرأة من بني سهم وتزوجت بعد أبيه رجلا من أهل اليمن فذكر هارون بن محمد بن عبد الملك الزيات عن حماد عن أبيه عن بعض أصحابه عن عون حاجب معن بن زائدة قال رايت أم ابن جامع وابن جامع معها عند معن بن زائدة وهو ضعيف يتبعها ويطأ ذيلها وكانت من قريش ومعن يومئذ على اليمن فقالت أصلح الله الأمير إن عمي زوجني زوجا ليس بكفء ففرق بيني وبينه قال من هو قالت ابن ذي مناجب قال علي به قال فدخل أقبح من خلق الله وأشوهه خلقا قال من هذه منك قال امرأتي قال خل سبيلها ففعل فأطرق معن ساعة ثم رفع رأسه فقال\n(لعمري لقد أصبحت غير محبب ... ولا حسن في عينها ذا مناجب)\n(فما لمتها لما تبينت وجهه ... وعينا له حوصاء من تحت حاجب)\n(وأنفا كأنف البكر يقطر دائبا ... على لحية عصلاء شابت وشارب)\n(أتيت بهامثل المهاة تسوقها ... فياحسن مجلوب ويا قبح جالب)\nأمر لها بمائتي دينار وقال لها تجهزي بها إلى بلادك\nأخبرني يحيى بن علي بن يحيى قال أخبرني حماد عن أبيه أن الرشيد سأل ابن جامع يوما عن نسله وقال له أي بني الإنس ولدك يا إسماعيل قال لا أدري ولكن سل ابن أخي يعني إسحاق وكان يماظ إبراهيم الموصلي ويميل إلى ابنه إسحاق قال إسحاق ثم التفت إلي ابن جامع فقال أخبره يابن أخي بنسب عمك فقال له الرشيد قبحك الله شيخا من قريش تجهل نسبك حتى يخبرك به غيرك وهو رجل من العجم","topic":"ذكر ابن جامع وخبره ونسبه","topicNo":68,"sp":0,"spl":"ذكر ابن جامع وخبره ونسبه"},
{"id":"b68-2","bab":"الجزء 6","sec":"بعض من ورعه وتقواه","page":"ج6 ص306","text":"قال هارون حدثني عبد الله بن عمرو قال حدثني أبو هشام محمد بن عبد الملك المخزومي قال أخبرني محمد بن عبد الله بن أبي فروة بن أبي قراد المخزومي قال كان ابن جامع من أحفظ خلق الله لكتاب الله وأعلمه بما يحتاج إليه كان يخرج من منزله مع الفجر يوم الجمعة فيصلي الصبح ثم يصف قديمه حتى تطلع الشمس ولا يصلي الناس الجمعة حتى يختم القرآن ثم ينصرف إلى منزله قال هارون وحدثني علي بن محمد النوفلي قال حدثني صالح بن علي بن عطية وغيره من رجال أهل العسكر قالوا قدم ابن جامع قدمة له من مكة على الرشيد وكان ابن جامع حسن السمت كثير الصلاة قد أخذ السجود جبهته وكان يعتم بعمامة سوداء على قلنسوة طويلة ويلبس لباس الفقهاء ويركب حمارا مريسيا في زي أهل الحجاز فبينا\nهو واقف على باب يحيى بن خالد يلتمس الإذن عليه فوقف على ما كان يقف الناس عليه في القديم حتى يأذن لهم أو يصرفهم أقبل أبو يوسف القاضي بأصحابه أهل القلانس فلما هجم على الباب نظر إلى رجل يقف إلى جانبه ويحادثه فوقعت عينه على ابن جامع فرأى سمته وحلاوة هيئته فجاء فوقف إلى جانبه ثم قال له أمتع الله بك توسمت فيك الحجازية والقرشية قال أصبت قال فمن أي قريش أنت قال من بني سهم قال فأي الحرمين منزلك قال مكة قال ومن لقيت من فقهائهم قال سل عمن شئت ففاتحه الفقه والحديث فوجد عنده ما أحب فأعجب به ونظر الناس إليهما فقالوا هذا القاضي قد اقبل على المغني وأبو يوسف لا يعلم أنه ابن جامع فقال أصحابه لو أخبرناه عنه ثم قالوا لا لعله لا يعود إلى مواقفته بعد اليوم فلم نغمه فلما كان الإذن الثاني ليحيى غدا عليه الناس وغدا عليه أبو يوسف فنظر يطلب ابن جامع فرآه فذهب فوقف إلى جانبه فحادثه طويلا كما فعل في المرة الأولى فلما انصرف قال له بعض أصحابه أيها القاضي أتعرف هذا الذي تواقف وتحادث قال نعم رجل من قريش من أهل مكة من الفقهاء قالوا هذا ابن جامع المغني قال إنا لله قالوا إن الناس قد شهروك بمواقفته وأنكروا ذلك من فعلك فلما كان الإذن الثالث جاء أبو يوسف ونظر إليه فتنكبه وعرف ابن جامع أنه قد أنذر به فجاء فوقف فسلم عليه فرد السلام عليه أبو يوسف بغير ذلك الوجه الذي كان يلقاه به ثم أنحرف عنه فدنا منه ابن جامع وعرف الناس القصة وكان ابن جامع جهيرا فرفع صوته ثم قال يا أبا يوسف مالك تنحرف عني أي شيء أنكرت قالوا لك إني ابن جامع المغني فكرهت مواقفتي لك أسألك عن مسألة ثم اصنع ما شئت ومال الناس فأقبلوا نحوهما يستمعون فقال يا أبا يوسف لو أن أعرابيا جلفا وقف بين يديك فأنشدك بجفاء وغلظة من لسانه وقال\n(يا دار مية بالعلياء فالسند ... أقوت وطال عليها سالف الأبد)\nكنت ترى بذلك بأسا قالا لا قد روي عن النبي في الشعر قول وروي في الحديث قال ابن جامع فإن قلت أنا هكذا ثم اندفع يتغنى فيه حتى أتى عليه ثم قال يا أبا يوسف رأيتني زدت فيه أو نقصت منه قال عافاك الله أعفنا من ذلك قال يا أبا يوسف أنت صاحب فتيا ما زدته على أن حسنته بألفاظي فحسن في السماع ووصل إلى القلب ثم تنحى عنه ابن جامع قال وحدثني عبد الله بن شبيب قال حدثني إبراهيم بن المنذر عن سفيان ابن عيينة ومر به ابن جامع يسحب الخز فقال لبعض أصحابه بلغني أن هذا القرشي أصاب مالا من بعض الخلفاء فبأي شيء أصابه قالوا بالغناء قال فمن منكم يذكر بعض ذلك فأنشد بعض أصحابه ما يغني فيه\n(وأصحب بالليل أهل الطواف ... وأرفع من مئزري المسبل)\nال أحسن هيه قال\n(وأسجد بالليل حتى الصباح ... واتلو من المحكم المنزل)\nقال أحسن هيه قال\n(عسى فارج الكرب عن يوسف ... يسخر لي ربة المحمل)\nال أما هذا فدعه","topic":"ذكر ابن جامع وخبره ونسبه","topicNo":68,"sp":1,"spl":"بعض من ورعه وتقواه"},
{"id":"b68-3","bab":"الجزء 6","sec":"طريقته في الغناء","page":"ج6 ص308","text":"وحدثني محمد بن الحسن العتابي قال حدثني جعفر بن محمد الكاتب قال\nحدثني طيب بن عبد الرحمن قال كان ابن جامع يعد صيحة الصوت قبل أن يصنع عمود اللحن وحدث محمد بن الحسن قال حدثني أبو حارثة بن عبد الرحمن بن سعيد بن سلم عن أخيه أبي معاوية بن عبد الرحمن قال قال لي ابن جامع لولا أن القمار وحب الكلاب قد شغلاني لتركت المغنين لا يأكلون الخبز أخبرني علي بن عبد العزيز عن ابن خرداذبه قال أهدى رجل إلى ابن جامع كلبا فقال ما اسمه فقال لا أدري فدعا بدفتر فيه أسماء الكلاب فجعل يدعوه بكل اسم فيه حتى أجابه الكلب قال هارون بن محمد حدثني علي بن محمد النوفلي قال حدثني محمد بن أحمد المكي قال حدثتني حولاء مولاة ابن جامع قالت انتبه مولاي يوما من قائلته فقال علي بهشام يعني ابنه ادعوه لي عجلوه فجاء مسرعا فقال أي بني خذ العود فإن رجلا من الجن ألقى علي في قائلتي صوتا فأخاف أن أنساه فأخذ هشام العود وتغنى ابن جامع عليه رملا لم أسمع له رملا أحسن منه وهو صوت\n(أمست رسوم الديار غيرها ... هوج الرياح الزعازع العصف)\n(وكل حنانة لها زجل ... مثل حنين الروائم الشغف)\nأخذه عنه هشام فكان بعد ذلك يتغناه وينسبه إلى الجن وفي هذا الصوت\nللهذلي لحن من الثقيل الثاني بالخنصر في مجرى الوسطى وفيه للغريض ثاني ثقيل بالوسطى على مذهب إسحاق من رواية عمرو وقيل إن هذا اللحن لعبادل وفيه لإبن جامع الرمل المذكور قال هارون وحدثني أحمد بن بشر بن عبد الوهاب قال حدثني محمد بن موسى بن فليح الخزاعي قال حدثنا أبو محمد عبد الله بن محمد المكي قال قال لي ابن جامع أخذت من هارون ببيتن غنيته بهما عشرة آلاف دينار صوت\n(لا بد للعاشق من وقفة ... تكون بين الوصل والصرم)\n(يعتب أحيانا وفي عتبة ... إظهار ما يخفي من السقم)\n(إشفاقه داع إلى ظنه ... وظنه داع إلى الظلم)\n(حتى إذا ما مضه هجره ... راجع من يهوى على رغم)\nكذا رويته الشعر للعباس بن الأحنف والغناء لإبن جامع ثاني ثقيل بالوسطى وذكر ابن بانة أن هذا اللحن لسيلم وفيه لإبراهيم ثقيل أول بالوسطى قال ثم قال لي ابن جامع فمتى تصيب أنت بالمروءة شيئا وقال هارون حدثني أحمد بن زهير قال حدثني مصعب بن عبد الله قال خرج ابن أبي عمرو الغفاري وعبد الرحمن بن أبي قباحة وغيرهما من القرشيين عمارا يريدون مكة فلما كانوا بفخ نزلوا على البئر التي هناك\nليغتسلوا فيها قال فبينما نحن نغتسل إذ سمعنا صوت غناء فقلنا لو ذهبنا إلى هؤلاء فسمعنا غناءهم فأتيناهم فإذا ابن جامع وأصحاب له يغنون وعندهم فضيخ لهم يشربون منه فقالوا تقدموا يا فتيان فتقدم ابن أبي عمرو فجلس مع القوم وكان رأسهم فجلسنا نشرب وطرب ابن أبي قباحة فغنى فقال ابن جامع وابأبي وأمي ابن أبي قباحة وإلا فهو ابن الفاعلة فقام ابن أبي عمرو فأخرج من وسطه هميانا فيه ثلثمائة درهم فنثرها على ابن أبي قباحة فقال ابن جامع امضوا بنا إلى المنزل فمضنيا فأقمنا عنده شهرا ما نبرح ونحن على إحرامنا ذلك قال هارون بن محمد بن عبد الملك حدثني علي بن سليمان عن محمد بن أحمد النوفلي عن جارية ابن جامع الحولاء قال وكانت تتبناني فتغنت يوما وطربت وقالت يا بني ألا أغنيك هزجا لسيدي في عشيقة له سوداء قلت بلى فتغنت هزجا ما سمعت أحسن منه وهو صوت\n(اشبهك المسك وأشبهته ... قائمة في لونه قاعده)\n(لا شك إذ لونكما واحد ... أنكما من طينة واحده)\nقد روي هذا الشعر لأبي حفص الشطرنجي يقوله في دنانير مولاة البرامكة ونسب هذا الهزج إلى إبراهيم وابن جامع وغيرهما\nقال عبد الله بن عمرو حدثنا أحمد بن عمر بن إسماعيل الزهري قال حدثني محمد بن جعفر بن عمر بن علي بن ابي طالب عليه السلام وكان يلقب الأبله قال قال برصوما الزامر وذكر إبراهيم الموصلي وابن جامع فقال الموصلي بستان تجد فيه الحلو والحامض وطريا لم ينضح فتأكل منه من ذا وذا وابن جامع زق عسل إن فتحت فمه خرج عسل حلو وإن خرقت جنبه خرج عسل حلو وإن فتحت يده خرج عسل حلو كله جيد","topic":"ذكر ابن جامع وخبره ونسبه","topicNo":68,"sp":2,"spl":"طريقته في الغناء"},
{"id":"b68-4","bab":"الجزء 6","sec":"غنى عند الرشيد فأخطأ ثم أجاد","page":"ج6 ص312","text":"أخبرنا يحيى بن علي عن أبيه وحماد عن إبراهيم بن المهدي وكان إبراهيم يفضل ابن جامع ولا يقدم عليه أحدا وابن جامع يميل إليه قال كنا في مجلس الرشيد وقد غلب على ابن جامع النبيذ فغنى صوتا فأخطأ في أقسامه فالتفت إلي إبراهيم الموصلي فقال قد خري فيه وفهمت صدقه قال فقلت لإبن جامع يا أبا القاسم أعد الصوت وتحفظ فيه فانتبه وأعاده فأصاب فقال إبراهيم\n(أعلمه الرماية كل يوم ... فلما اشتد ساعده رماني)\nتنكر لميلي مع ابن جامع عليه فقلت للرشيد بعد أيام إن لي حاجة إليك قال وما هي قلت تسأل إبراهيم الموصلي أن يرضى غني ويعود إلى ما كان عليه فقال إنما هو عبدك وقال له قم إليه فقبل رأسه فقلت لا ينفعني رضاه في الظاهر دون الباطن فسله أن يصحح الرضا فقام إلي ليقبل راسي كما أمر فقال لي وقد أكب علي ليقبل رأسي أتعود قلت لا قال قد رضيت عنك رضا صحيحا وعاد إلى ما كان عليه وقال حماد عن أبي يحيى العبادي قال قدم حوراء غلام حماد الشعراني وكان أحد المغنين المجيدين قال حدثني بعض أصحابنا قال كنا في دار أمير المؤمنين الرشيد فصاح بالمغنين من فيكم يعرف\n(وكعبة نجران حتم عليك ... حتى تناخي بأبوابها)\nلشعر للأعشى فبدرهم إبراهيم الموصلي فقال أنا أغنيه وغناه فجاء بشىء عجيب فغضب ابن جامع وقال لزلزل دع العود أنا من جحاش وجرة لا أحتاج إلى بيطار ثم غنى الصوت فصاح إليه مسرور أحسنت يا أبا القاسم ثلاث مرات","topic":"ذكر ابن جامع وخبره ونسبه","topicNo":68,"sp":3,"spl":"غنى عند الرشيد فأخطأ ثم أجاد — نسبة هذا الصوت"},
{"id":"b68-5","bab":"الجزء 6","sec":"نسبة هذا الصوت","page":"ج6 ص313","text":"صوت\n(وكعبة نجران حتم عليك ... حتى تناخي بأبوابها)\n(نزور يزيد وعبد المسيح ... وقيسا هم خير أربابها)\n(وشاهدنا الجل والياسمين ... والمسمعات بقصابها)\n(وبربطنا دائم معمل ... فأي الثلاثة أزرى بها)\n(فلما التقينا على آلة ... ومدت إلي بأسبابها)\nالشعر للأعشى أعشى بني قيس بن ثعلبة وهؤلاء الذين ذكرهم أساقفة نجران وكان يزورهم ويمدحهم ويمدح العاقب والسيد وهما ملكا نجران ويقيم عندهما ما شاء يسقونه الخمر ويسمعونه الغناء الرومي فإذا انصرف أجزلوا صلته أخبرنا بذلك محمد بن العباس اليزيدي عن عمه عبيد الله عن محمد بن حبيب عن ابن الأعرابي وله أخبار كثيرة معهم تذكر في مواضعها إن شاء الله والغناء لحنين الحيري خفيف ثقيل بالوسطى في مجراها عن إسحاق في الأربعة الأول وذكر عمرو أنه لإبن محرز وذكر يونس أن فيها لحنا لمالك ولم يجنسه وذكر الهشامي أن في الخامس والسادس ثم الأول والثاني خفيف رمل بالوسطى ليحيى المكي","topic":"ذكر ابن جامع وخبره ونسبه","topicNo":68,"sp":3,"spl":"غنى عند الرشيد فأخطأ ثم أجاد — نسبة هذا الصوت"},
{"id":"b68-6","bab":"الجزء 6","sec":"استحضره الفضل بن الربيع لما ولي الهادي","page":"ج6 ص314","text":"وقال حماد عن مصعب بن عبد الله قال حدثني الطراز وكان بريد الفضل بن الربيع قال لما مات المهدي وملك موسى الهادي أعطاني الفضل دنانير وقال إلحق بمكة فأتني بابن جامع واحمله في قبة ولا تعلمن بذا أحدا ففعلت فأنزلته عندي واشتريت له جارية له وكان ابن جامع صاحب نساء فذكره موسى ذات ليلة وكان\nهو والحراني منقطعين إلى موسى أيام المهدي فضربهما المهدي وطردهما فقال لجلسائه أما فيكم أحد يرسل إلى ابن جامع وقد علمتم موقعة مني فقال له الفضل بن الربيع هو والله عندي يا أمير المؤمنين وقد فعلت الذي أردت وبعث إليه فأتي به في الليل فوصل الفضل تلك الليلة بعشرة آلاف دينار وولاه حجابته قال إسحاق عن بعض أصحابه كنا عند أمير المؤمنين الرشيد يوما فقال الغلام الذي على الستارة يابن جامع تغن ببيت السعدي\n(فلو سألت سراة الحي سلمى ... على أن قد تلون بي زماني)\n(لخبرها ذوو الأحساب عني ... وأعدائي فكل قد بلاني)\n(بذبي الذم عن حسبي بمالي ... وزبونات أشوس تيحان)\n(وأني لا أزال أخا حروب ... إذا لم أجن كنت مجن جاني)\nال فحرك ابن جامع رأسه وكان إذا اقترح عليه الخليفة شيئا قد أحسنه وأكمله طار فرحا فغنى به فأربد وجه إبراهيم لما سمعه منه وكذا كان ابن جامع أيضا يفعل فقال له صاحب الستارة أحسنت والله يا أميري أعد فأعاد فقال أنت في حلبة لا يلحقك أحد فيها أبدا ثم قال صاحب الستارة لإبراهيم تغن بهذا\nالشعر فتغنى فلما فرغ قال مرعى ولا كالسعدان أخطأت في موضع كذا وفي موضع كذا فقال نفي إبراهيم من أبيه إن كان يا أمير المؤمنين أخطأ حرفا وقد علمت أني أغفلت في هذين الموضعين قال إبراهيم فلما انصرفنا قلت لإبن جامع والله ما أعلم أن أحدا بقي في الأرض يعرف هذا الغناء معرفة أمير المؤمنين قال حق والله لهو إنسان يسمع الغناء منذ عشرين سنة مع هذا الذكاء الذي فيه قال إسحاق كان ابن جامع إذا تغنى في هذا الشعر صوت\n(من كان يبكي لما بي ... من طول سقم رسيس)\n(فالآن من قبل موتي ... لا عطر بعد عروس)\n(بنيتم في فؤادي ... أوكار طير النحوس)\n(قلبي فريس المنايا ... يا ويحه من فريس)\nلشعر لرجل من قريش والغناء لإبن جامع في طريقة الرمل لم يتغن في ذلك المجلس بغيره وكان إذا أراد أن يتغنى سأل أن يزمر عليه برصوما فلما كثر ذلك سألوه فيه فقال لا والله ولكنه إذا ابتدأت فغنيت في الشعر عرف الغرض الذي يصلح فما يجاوزه وكنت معه في راحة وذلك أن المغني إذاتغنى بزمر زامر فأكثر العمل على الزامر لأنه لا يقفو الأثر فإذا زمر برصوما فأنا في راحة وهو في تعب وإذا زمر علي غيره فهو في راحة وأنا في تعب فإن شككتم فاسألوا برصوما ومنصور زلزل فسألوهما عما قال فقالا صدق قال وحدثني علي بن أحمد الباهلي قال سمعت مصعب بن عبد الله يقول بلغ المهدي أن ابن جامع والموصلي يأتيان موسى فبعث إليهما فجيء بهما فضرب الموصلي ضربا مبرحا وقال له ابن جامع ارحم أمي فرق له وقال\nله قبحك الله رجل من قريش يغني وطرده فلما قام موسى وجه الفضل خلفه بريدا حتى جاء به فقال له موسى ما كان ليفعل هذا غيرك قال وحدثني الزبير بن بكار قال قال لي فلفلة تمنى يوما موسى أمير المؤمنين ابن جامع فدفع إلي الفضل بن الربيع خمسمائة دينار وقال امض حتى تحمل ابن جامع وبعث إليه بما يصلحه فمضيت فحملته فلما دخلنا أدخله الفضل الحمام وأصلح من شأنه ودخل على موسى فغناه فلم يعجبه فلما خرج قال له الفضل تركت الخفيف وغنيت الثقيل قال فأدخلني عليه أخرى فأدخله فغنى الخفيف فقال حاجتك فأعطاه ثلاثين ألف دينار قال وحدثني عبد الرحمن بن أيوب قال حدثنا أبو يحيى العبادي قال حدثني ابن أبي الرجال قال حدثني زلزل قال أبطأ إبراهيم الموصلي عن الرشيد فأمر مسرورا الخادم يسأل عنه وكان أمير المؤمنين قد صير أمر المغنين إليه فقيل له لم يأت بعد ثم جاء في آخر النهار فقعد بيني وبين برصوما فغنى صوتا له فأطربه وأطرب والله كل من كان في المجلس قال فقام ابن جامع من مجلسه فقعد بيني وبين برصوما ثم قال أما والله يا نبطي ما أحسن إبراهيم وما أحسن غيركما قال ثم غنى فنسينا أنفسنا والله لكأن العود كان في يده","topic":"ذكر ابن جامع وخبره ونسبه","topicNo":68,"sp":4,"spl":"استحضره الفضل بن الربيع لما ولي الهادي"},
{"id":"b68-7","bab":"الجزء 6","sec":"إبراهيم الموصلي يشهد له بجودة الإيقاع","page":"ج6 ص318","text":"قال وحدثني عمر بن شبة قال حدثني يحيى بن إبراهيم بن عثمان بن نهيك قال دعا أبي الرشيد يوما فأتاه ومعه جعفر بن يحيى فأقاما عنده وأتاهما ابن جامع فغناهما يومهما فلما كان الغد انصرف الرشيد وأقام جعفر قال فدخل\nعليهم إبراهيم الموصلي فسال جعفرا عن يومهم فأخبره وقال له لم يزل ابن جامع يغنينا إلا أنه كان يخرج من الإيقاع وهو في قوله يريد أن يطيب نفس إبراهيم الموصلي قال فقال له إبراهيم أتريد أن تطيب نفسي بما لا تطيب به لا والله ما ضرط ابن جامع منذ ثلاثين سنة إلا بإيقاع فكيف يخرج من الإيقاع قال وحدثني يحيى بن الحسن بن عبد الخالق قال حدثني أبي قال كان سبب عزل العثماني أن ابن جامع سأل الرشيد أن يأذن له في المهارشة بالديوك والكلاب ولا يحد في النبيذ فأذن له وكتب له بذلك كتابا إلى العثماني فلما وصل الكتاب قال كذبت أمير المؤمنين لا يحل ما حرم الله وهذا كتاب مزور والله لئن ثقفتك على حال من هذه الأحوال لأؤدبنك أدبك قال فحذره ابن جامع ووقع بين العثماني وحماد اليزيدي وهو على البريد ما يقع بين العمال فلما حج هارون قال حماد لإبن جامع أعني عليه حتى أعزله قال أفعل قال فابدأ أنت وقل إنه ظالم فاجر واستشهدني فقال له ابن جامع هذا لا يقبل في العثماني ويفهم أمير المؤمنين كذبنا ولكني أحتال من جهة ألطف من هذه قال فسأله هارون ابتداء فقال له يابن جامع كيف أميركم العثماني قال خير أمير وأعدله وأفضله وأقومه بحق لولا ضعف في عقله قال\nوما ضعفه قال قد أفنى الكلاب قال وما دعاه إلى إفنائها قال زعم أن كلبا دنا من عثمان بن عفان يوم ألقي على الكناس فأكل وجهه فغضب على الكلاب فهو يقتلها فقال هذا ضعيف اعزلوه فكان سبب عزله قال هارون بن محمد وحدثني الحسن بن محمد الغياثي قال حدثني أبي عن القطراني قال كان ابن جامع بارا بوالدته وكانت مقيمة بالمدينة وبمكة فدعاه إبراهيم بن المهدي وأظهر له كتابا إلى أمير المؤمنين فيه نعي والدته قال فجزع لذلك جزعا شديدا وجعل أصحابه يعزونه ويؤنسونه ثم جاؤوا بالطعام فلم يتركوه حتى طعم وشرب وسألوه الغناء فامتنع فقال له إبراهيم بن المهدي إنك ستبذل هذا لأمير المؤمنين فابذله لإخوانك فاندفع يغني صوت\n(كم بالدروب وأرض الروم من قدم ... ومن جماجم صرعى ما بها قبروا)\n(بقندهار ومن تقدر منيته ... بقندهار يرجم دونه الخبر)\nلشعر ليزيد بن مفرغ الحميري والغناء لإبن جامع رمل وفيه لإبن سريج\nخفيف رمل جميعا عن الهشامي قال وجعل إبراهيم يسترده حتى صلح له ثم قال لا والله ما كان مما خبرناك شيء إنما مزحنا بك قال ثم قال له رد الصوت فغناه فلم يكن من الغناء الأول في شيء فقال له إبراهيم خذه الآن علي فأداه إبراهيم على السماع الأول فقال له ابن جامع أحب أن تطرحه أنت على كذا أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثنا عبد الله بن أبي سعد قال حدثني علي بن الحسن الشيباني عن أحمد بن يحيى المكي قال كان أبي بين يدي الرشيد وابن جامع معه يغني بين يدي الرشيد فغناه\n(خليفة لا يخيب سائله ... عليه تاج الوقار معتدل)\nال وغنى من يتلوه وهوم ابن جامع سكرا ونعاسا فلما دار الغناء على أصحابه وصارت النوبة إليه حركه من بجنبه لنوبته فانتبه وهو يغني\n(اسلم وحييت أيها الطلل ... وإن عفتك الرياح والسبل)\nقال وهو يتلو البيت الأول فعجب أهل المجلس من ذكائه وفهمه وأعجب ذلك الرشيد","topic":"ذكر ابن جامع وخبره ونسبه","topicNo":68,"sp":5,"spl":"إبراهيم الموصلي يشهد له بجودة الإيقاع — نسبة هذا الصوت"},
{"id":"b68-8","bab":"الجزء 6","sec":"نسبة هذا الصوت","page":"ج6 ص321","text":"صوت\n(اسلم وحييت أيها الطلل ... وإن عفتك الرياح والسبل)\n(خليفة لا يخيب سائله ... عليه تاج الوقار معتدل)\nلشعر لأشجع أو لسلم الخاسر يمدح به موسى الهادي والغناء لإبن جامع ثقيل أول بالوسطى من رواية الهشامي وأحمد بن يحيى المكي","topic":"ذكر ابن جامع وخبره ونسبه","topicNo":68,"sp":5,"spl":"إبراهيم الموصلي يشهد له بجودة الإيقاع — نسبة هذا الصوت"},
{"id":"b68-9","bab":"الجزء 6","sec":"الرشيد يخبره بموت أمه كذبا ليحسن غناؤه","page":"ج6 ص322","text":"قال هارون وقد حدثني بهذا الخبر عبد الرحمن بن أيوب قال حدثني أحمد بن يحيى المكي قال كان ابن جامع أحسن ما يكون غناء إذا حزن صوته فأحب الرشيد أن يسمع ذلك على تلك الحال فقال للفضل بن الربيع ابعث خريطة فيها نعي أم ابن جامع وكان بارا بأمه ففعل فوردت الخريطة على أمير المؤمنين وهو في مجلس\nلهوه فقال يابن جامع جاء في هذه الخريطة نعي أمك فاندفع ابن جامع يغني بتلك الحرقة والحزن الذي في قلبه\n(كم بالدروب وأرض السند من قدم ... ومن جماجم صرعى ما بها قبروا)\n(بقندهار ومن تكتب منيته ... بقندهار يرجم دونه الخبر)\nال فوالله ما ملكنا أنفسنا وأريت الغلمان يضربون برؤوسهم الحيطان والأساطين قال هارون لا أشك أن ابن المكي قد حدث به عن رجل حضر ذلك فأغفله عبد الرحمن بن أيوب قال ثم غنى بعد ذلك\n(يا صاحب القبر الغريب ... )\nهو لحن قديم وفيه لحن لإبن المكي فقال له الرشيد أحسنت وأمر له بعشرة آلاف دينار","topic":"ذكر ابن جامع وخبره ونسبه","topicNo":68,"sp":6,"spl":"الرشيد يخبره بموت أمه كذبا ليحسن غناؤه — ابن جامع وأم جعفر","partial":1},
{"id":"b68-10","bab":"الجزء 6","sec":"نسبة هذا الصوت الأخير","page":"ج6 ص323","text":"صوت\n(يا صاحب القبر الغريب ... بالشام في طرف الكثيب)\n(بالحجر بين صفائح ... صم ترصف بالجبوب)\n(رصفا ولحد ممكن ... تحت العجاجة في القليب)\n(فإذا ذكرت أنينه ... ومغيبه تحت المغيب)\n(هاجت لواعج عبرة ... في الصدر دائمة الدبيب)\n(أسفا لحسن بلائه ... ولمصرع الشيخ الغريب)\n(أقبلت أطلب طبه ... والموت يعضل بالطبيب)\nلشعر لمكين العذري يرثي أباه وقيل إنه لرجل خرج بإبنه إلى الشأم هربا به من جارية هويها فمات هناك والغناء لحكم الوادي رمل في مجرى البنصر وقيل إن الشعر لسلامة ترثي الوليد بن يزيد","topic":"ذكر ابن جامع وخبره ونسبه","topicNo":68,"sp":6,"spl":"الرشيد يخبره بموت أمه كذبا ليحسن غناؤه — ابن جامع وأم جعفر"},
{"id":"b68-11","bab":"الجزء 6","sec":"ابن جامع وأم جعفر","page":"ج6 ص324","text":"أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثنا عبد الله بن أبي سعد قال حدثني الحسن بن محمد قال حدثنا أحمد بن الخليل بن مالك قال حدثني عبد الله بن علي بن عيسى بن ماهان قال سمعت يزيد يحدث أن أم جعفر بلغها أن الرشيد جالس وحده ليس معه أحد من الندماء ولا المسامرين فأرسلت إليه يا أمير المؤمنين إني لم أرك منذ ثلاث وهذا اليوم الرابع فأرسل إليها عندي ابن جامع فأرسلت إليه أنت تعلم أني لا أتهنأ بشرب ولا سماع ولا غيرهما إلا أن تشركني فيه فما كان عليك أن أشركك في الذي أنت فيه فأرسل إليها إني سائر إليك الساعة ثم قام وأخذ بيد ابن جامع وقال لحسين الخادم امض إليها فأعلمها أني قد جئت وأقبل الرشيد فلما نظر\nإلى الخدم والوصائف قد استقبلوه علم أنها قد قامت تستقبله فوجه إليها إن معي ابن جامع فعدلت إلى بعض المقاصير وجاء الرشيد وصير ابن جامع في بعض المواضع التي يسمع منه فيها ولا يكون حاضرا معهم وجاءت أم جعفر فدخلت على الرشيد وأهوت لتنكب على يده فأجلسها إلى جانبه فاعتنقها واعتنقته ثم أمر ابن جامع أن يغني فاندفع فغنى صوت\n(ما رعدت رعدة ولا برقت ... لكنها أنشئت لنا خلقه)\n(الماء يجري على نظام له ... لو يجد الماء مخرقا خرقه)\n(بتنا وباتت على نمارقها ... حتى بدا الصبح عينها أرقه)\n(أن قيل إن الرحيل بعد غد ... والدار بعد الجميع مفترقه)\nلشعر لعبيد بن الأبرص والغناء لإبن جامع ثاني ثقيل من أصوات قليلات الأشباه عن إسحاق وفيه لإبن محرز ثقيل أول بالبنصر عن عمرو بن بانة وذكر يونس أن فيه لحنا لمعبد ولم يجنسه وفي لحكم هزج بالوسطى عن عمرو والهشامي ولمخارق في هذه الأبيات رمل بالبنصر عن الهشامي وذكر حبش أن الثقيل الأول للغريض وذكر الهشامي أن لمتيم فيها ثاني ثقيل بالوسطى قال فقالت أم جعفر للرشيد ما أحسن ما اشتهيت والله يا أمير المؤمنين ثم قالت\nلمسلم خادمها ادفع إلى ابن جامع لكل بيت مائة ألف درهم فقال الرشيد غلبتنا يا بنت أبي الفضل وسبقتنا إلى بر ضيفنا وجليسنا فلما خرج حمل إليها مكان كل درهم دينارا","topic":"ذكر ابن جامع وخبره ونسبه","topicNo":68,"sp":6,"spl":"الرشيد يخبره بموت أمه كذبا ليحسن غناؤه — ابن جامع وأم جعفر"},
{"id":"b68-12","bab":"الجزء 6","sec":"يشتري الصوت بثلاثة دراهم ويعوضها بثلاثة آلاف","page":"ج6 ص326","text":"أخبرنا أحمد بن عبيد الله بن عمار قال أخبرني يعقوب بن إسرائيل مولى المنصور قال حدثني محمد بن ضوين الصلصال التيمي قال حدثني إسماعيل بن جامع السهمي قال ضمني الدهر ضما شديدا بمكة فانتقلت منها بعيالي إلى المدينة فأصبحت يوما وما أملك إلا ثلاثة دراهم فهي في كمي إذا أنا بجارية حميراء على رقتبها جرة تريد الركي تسعى بين يدي وترنم بصوت شجي تقول\n(شكونا إلى أحبابنا طول ليلنا ... فقالوا لنا ما أقصر الليل عندنا)\n(وذاك لأن النوم يغشى عيونهم ... سراعا وما يغشى لنا النوم أعينا)\n(إذا ما دنا الليل المضر لذي الهوى ... جزعنا وهم يستبشرون إذا دنا)\n(فلو أنهم كانوا يلاقون مثل ما ... نلاقي لكانوا في المضاجع مثلنا)\nال فأخذ الغناء بقلبي ولم يدر لي منه حرف فقلت يا جارية ما أدري أوجهك أحسن أم غناؤك فلو شئت أعدت قالت حبا وكرامة ثم أسندت ظهرها إلى جدار قرب منها ورفعت إحدى رجليها فوضعتها على الأخرى ووضعت الجرة على ساقيها ثم انبعثت تغنيه فوالله ما دار لي منه حرف فقلت أحسنت فلو شئت أعدتيه مرة أخرى ففطنت وكلحت وقالت ما أعجب أمركم أحدكم لا يزال يجيء إلى الجارية عليها الضريبة فيشغلها فضربت بيدي إلى الثلاثة الدراهم فدفعتها إليها وقلت أقيمي بها وجهك اليوم إلى أن نلتقي قال فأخذتها\nكالكارهة وقالت أنت الآن تريد أن تأخذ مني صوتا أحسبك ستأخذ به ألف دينار وألف دينار وألف دينار قال وانبعثت تغني فأعملت فكري في غنائها حتى دار لي الصوت وفهمته وانصرفت مسرورا إلى منزلي أردده حتى خف على لساني ثم إني خرجت أريد بغداد فدخلتها فنزل بي المكاري على باب محول فبقيت لا أدري أين أتوجه ولا من أقصد فذهبت أمشي مع الناس حتى أتيت الجسر فعبرت معهم ثم انتهيت إلى شارع المدينة فرأيت مسجدا بالقرب من دار الفضل بن الربيع مرتفعا فقلت مسجد قوم سراة فدخلته وحضرت صلاة المغرب وأقمت بمكاني حتى صليت العشاء الأخرة على جوع وتعب وانصرف أهل المسجد وبقي رجل يصلي خلفه جماعة خدم وخول ينتظرون فراغه فصلى مليا ثم انصرف فراني فقال أحسبك غريبا قلت أجل قال فمتى كنت في هذه المدينة قلت دخلتها آنفا وليس لي بها منزل ولا معرفة وليست صناعتي من الصنائع التي يمت بها إلى أهل الخير قال وما صناعتك قلت أتغنى قال فوثب مبادرا ووكل بي بعض من معه فسألت الموكل بي عنه فقال هذا سلام الأبرش قال وإذا رسول قد جاء في طلبي فانتهى بي إلى قصر من قصور الخلافة وجاوز بي مقصورة إلى مقصورة ثم أدخلت مقصورة في آخر الدهليز ودعا بطعام فأتيت بمائدة عليها من طعام الملوك فأكلت حتى امتلأت فإني لكذلك إذ سمعت ركضا في الدهليز وقائلا يقول أين الرجل قيل هو هذا قال ادعوا له بغسول وخلعة وطيب ففعل ذلك بي فحملت على دابة إلى دار\nالخلافة وعرفتها بالحرس والتكبير والنيران فجاوزت مقاصير عدة حتى صرت إلى دار قوراء فيها أسرة في وسطها قد أضيف بعضها إلى بعض فأمرني الرجل بالصعود فصعدت وإذا رجل جالس عن يمينه ثلاث جوار في حجورهن العيدان وفي حجر الرجل عود فرحب الرجل بي وإذا مجالس حياله كان فيها قوم قد قاموا عنها فلم ألبث أن خرج خادم من وراء الستر فقال للرجل تغن فانبعث يغني بصوت لي وهو\n(لم تمش ميلا ولم تركب على قتب ... ولم تر الشمس إلا دونها الكلل)\n(تمشي الهوينى كأن الريح ترجعها ... مشي اليعافير في جيآتها الوهل)\nغنى بغير إصابة وأوتار مختلفة ودساتين مختلفة ثم عاد الخادم إلى الجارية التي تلي الرجل فقال لها تغني فغنت أيضا بصوت لي كانت فيه أحسن حالا من الرجل وهو قوله\n(يا دار أضحت خلاء لا أنيس بها ... إلا الظباء وإلا الناشط الفرد)\n(أين الذين إذا ما زرتهم جذلوا ... وطار عن قلبي التشواق والكمد)\nثم عاد إلى الثانية وأحسبه أغفلها وما تغنت به ثم عاد الخادم إلى الجارية التي تليها فانبعثت تغني بصوت الحكم الوادي وهو\n(فوالله ما أدري أيغلبني الهوى ... إذا جد وشك البين أم أنا غالبه)\n(فإن أستطع أغلب وإن يغلب الهوى ... فمثل الذي لاقيت يغلب صاحبه)\nال ثم عاد الخادم إلى الجارية الثالثة فغنت بصوت لحنين وهو قوله\n(مررنا على قيسية عامرية ... لها بشر صافي الأديم هجان)\n(فقالت وألقت جانب الستر دونها ... من آية أرض أو من الرجلان)\n(فقلت لها أما تميم فأسرتي ... هديت وأما صاحبي فيمان)","topic":"ذكر ابن جامع وخبره ونسبه","topicNo":68,"sp":7,"spl":"يشتري الصوت بثلاثة دراهم ويعوضها بثلاثة آلاف"},
{"id":"b68-13","bab":"الجزء 6","sec":"يشتري الصوت بثلاثة دراهم ويعوضها بثلاثة آلاف","page":"ج6 ص326","text":"(رفيقان ضم السفر بيني وبينه ... وقد يلتقي الشتى فيأتلفان)\nم عاد إلى الرجل فغنى صوتا فشبه فيه والشعر لعمر بن أبي ربيعة وهو قوله\n(أمسى بأسماء هذا القلب معمودا ... إذا أقول صحا يعتاده عيدا)\n(كأن أحور من غزلان ذي بقر ... أعارها شبه العينين والجيدا)\n(بمشرق كشعاع الشمس بهجته ... ومسبكر على لباتها سودا)\nثم عاد إلى الجارية فتغنت بصوت لحكم الوادي\n(تعيرنا أنا قليل عديدنا ... فقلت لها إن الكرم قليل)\n(وما ضرنا أنا قليل وجارنا ... عزيز وجار الأكثرين ذليل)\n(وإنا لقوم ما نرى القتل سبة ... إذا ما رأته عامر وسلول)\n(يقرب حب الموت آجالنا لنا ... وتكرهه آجالهم فتطول)\nتغنت الثانية\n(وددتك لما كان ودك خالصا ... وأعرضت لما صرت نهبا مقسما)\n(ولا يلبث الحوض الجديد بناؤه ... إذا كثر الوراد أن يتهدما)\nتغنت الثالثة بشعر الخنساء\n(وما كر إلا كان أول طاعن ... ولا أبصرته الخيل إلا اقشعرت)\n(فيدرك ثأرا وهو لم يخطه الغنى ... فمثل أخي يوما به العين قرت)\n(فلست أرزا بعده برزية ... فأذكره إلا سلت وتجلت)\nغنى الرجل في الدور الثالث\n(لحى الله صعلوكا مناه وهمه ... من الدهر أن يلقى لبوسا ومطعما)\n(ينام الضحى حتى إذا ليله انتهى ... تنبه مثلوج الفؤاد مورما)\n(ولكن صعلوكا يساور همه ... ويمضي على الهيجاء ليثا مقدما)\n(فذلك إن يلق الكريهة يلقها ... كريما وإن يستغن يوما فربما)\nال وتغنت الجارية\n(إذا كنت ربا للقلوص فلا يكن ... رفيقك يمشي خلفها غير راكب)\n(أنخها فأردفه فإن حملتكما ... فذاك وإن كان العقاب فعاقب)\nقال وتغنت الجارية بشعر عمرو بن معد يكرب\n(ألم تر لما ضمني البلد القفر ... سمعت نداء يصدع القلب يا عمرو)\n(اغثنا فإنا عصبة مذحجية ... نزار على وفر وليس لنا وفر)\nال وتغنت الثالثة بشعر عمر بن أبي ربيعة\n(فلما تواقفنا وسلمت اسفرت ... وجوه زهاها الحسن أن تنقنعا)\n(تبالهن بالعرفان لما عرفنني ... وقلن امرؤ باغ اكل وأوضعا)\n(ولما تنازعن الأحاديث قلن لي ... أخفت علينا أن نغر ونخدعا)\nقال وتوقعت مجيء الخادم إلي فقلت للرجل بأبي أنت خذ العود فشد وتر كذا وارفع الطبقة وحط دستان كذ ففعل ما أمرته وخرج الخادم فقال لي تغن عافاك الله فتغنيت بصوت الرجل الأول على غير ما غناه فإذا جماعة من الخدم يحضرون حتى استندوا إلى الأسرة وقالوا ويحك لمن هذا الغناء قلت لي فانصرفوا عني بتلك السرعة وخرج إلي الخادم وقال كذبت هذا الغناء لإبن جامع ودار الدور فلما انتهى الغناء إلي قلت للجارية التي تلي الرجل خذي العود فعلمت ما أريد فسوت العود على غنائها للصوت الثاني فتغنيت به فخرجت إلي الجماعة الأولى من الخدم فقالوا ويحك لمن هذا قلت لي فرجعوا وخرج الخادم فتغنيت بصوت لي فلا يعرف إلا بي وسقوني فتزيدت وهو\n(عوجي علي فسلمي جبر ... فيم الصدود وأنتم سفر)\n(ما نلتقي إلا ثلاث منى ... حتى يفرق بيننا الدهر)\nال فتزلزلت والله الدار عليهم وخرج الخادم فقال ويحك لمن هذا الغناء قلت لي فرجع ثم خرج فقال كذبت هذا غناء ابن جامع فقلت فأنا إسماعيل بن جامع فما شعرت إلا وأمير المؤمنين وجعفر بن يحيى قد أقبلا من وراء الستر الذي كان يخرج منه الخادم فقال لي الفضل بن الربيع هذا أمير المؤمنين قد أقبل إليك فلما صعد السرير وثبت قائما فقال لي أبن جامع قلت ابن جامع جعلني الله فداك يا أمير المؤمنين قال ويحك متى كنت في هذه البلدة قلت آنفا دخلتها في الوقت الذي علم بي أمير المؤمنين قال اجلس ويحك يابن جامع ومضى هو وجعفر فجلسا في بعض تلك المجالس وقال لي أبشر وابسط أملك فدعوت له ثم قال غنني يابن جامع فخطر بقلبي صوت الجارية الحميراء فأمرت الرجل بإصلاح العود على ما أردت من الطبقة فعرف ما أردت فوزن العود وزنا وتعاهده حتى استقامت الأوتار وأخذت الدساتين مواضعها وانبعثت أغني بصوت الجارية الحميراء فنظر الرشيد إلى جعفر وقال","topic":"ذكر ابن جامع وخبره ونسبه","topicNo":68,"sp":8,"spl":"يشتري الصوت بثلاثة دراهم ويعوضها بثلاثة آلاف"},
{"id":"b68-14","bab":"الجزء 6","sec":"يشتري الصوت بثلاثة دراهم ويعوضها بثلاثة آلاف","page":"ج6 ص326","text":"أسمعت كذا قط فقال لا والله ما خرق مسامعي قط مثله فرفع الرشيد رأسه إلى خادم بالقرب منه فدعا بكيس فيه ألف دينار فجاء به فرمى به إلي فصيرته تحت فخذي ودعوت لأمير المؤمنين فقال يابن جامع رد على أمير المؤمنين هذا الصوت فرددته وتزيدت فيه فقال له جعفر يا سيدي أما تراه كيف يتزيد في الغناء هذا خلاف ما سمعناه أولا وإن كان الأمر في اللحن واحدا قال فرفع الرشيد رأسه إلى ذلك الخادم فدعا بكيس آخر فيه ألف دينار فجاءني به فصيرته تحت فخذي وقال تغن يا إسماعيل ما حضرك فجعلت أقصد الصوت بعد الصوت مما كان يبلغني أنه يشتري عليه الجواري فأغنيه فلم أزل أفعل ذلك إلى أن عسعس الليل فقال أتعبناك يا إسماعيل هذه الليلة بغنائك فاعد على أمير المؤمنين الصوت يعني صوت الجارية فتغنيت فدعا الخادم وأمره فأحضر كيسا ثالثا فيه ألف دينار قال فذكرت ما كانت الجارية قالت لي فتبسمت ولحظني فقال يابن الفاعلة مم تبسمت فجثوت على ركبتي وقلت يا أمير المؤمنين الصدق منجاة فقال لي بانتهار قل فقصصت عليه خبر الجارية فلما استوعبه قال صدقت قد يكون هذا وقام ونزلت من السرير ولا أدري أين أقصد فابتدرني فراشان فصارا بي إلى دار قد أمر بها أمير المؤمنين ففرشت وأعد فيها جميع ما يكون في مثلها من ألة جلساء الملوك وندمائهم من الخدم ومن كل ألة وخول إلى جوار ووصفاء فدخلتها فقيرا وأصبحت من جلة أهلها ومياسيرهم وذكر لي هذا الخبر عبد الله بن الربيع عن أبي حفص الشيباني عن محمد بن القاسم عن إسماعيل بن جامع قال ضمني الدهر بمكة ضما شديدا فانتقلت إلى المدينة فبينا أنا يوما جالس مع بعض أهلها نتحدث إذ قال لي رجل حضرنا والله لقد بلغنا يابن جامع أن\nالخليفة قد ذكرك وأنت في هذا البلد ضائع فقلت والله ما بي نهوض قال بعضهم فنحن ننهضك فاحتلت في شيء وشخصت إلى العراق فقدمت بغداد ونزلت عن بغل كنت أكتريته ثم ذكر باقي الحديث نحو الذي قبله في المعاني ولم يذكر خبر السوداء التي أخذ الصوت عنها وأحسبه غلط في إدخاله هذه الحكاية ها هنا ولتلك خبر آخر نذكره ها هنا قال في هذا الخبر إن الدور دار مرة أخرى حتى صار إلي فخرج الخادم فقال غن أيها الرجل فقلت ما أنتظر الآن ثم اندفعت أغني بصوت لي وهو\n(فلو كان لي قلبان عشت بواحد ... وخلفت قلبا في هواك يعذب)\n(ولكنما أحيا بقلب مروع ... فلا العيش يصفوا لي ولا الموت يقرب)\n(تعلمت أسباب الرضا خوف سخطها ... وعلمها حبي لها كيف تغضب)\n(ولي ألف وجه قد عرفت مكانه ... ولكن بلا قلب إلى أين أذهب)\nخرج الرشيد حينئذ","topic":"ذكر ابن جامع وخبره ونسبه","topicNo":68,"sp":9,"spl":"يشتري الصوت بثلاثة دراهم ويعوضها بثلاثة آلاف"},
{"id":"b68-15","bab":"الجزء 6","sec":"نسبة ما في هذه الأصوات من الأغاني","page":"ج6 ص334","text":"صوت\n(شكونا إلى أحبابنا طول ليلنا ... فقالوا لنا ما أقصر الليل عندنا)\n(وذاك لأن النوم يغشى عيونهم ... سراعا وما يغشى لنا النوم أعينا)\n(إذا ما دنا الليل المضر بذي الهوى ... جزعنا وهم يستبشرون إذا دنا)\n(فلو أنهم كانوا يلاقون مثل ما ... نلاقي لكانوا في المضاجع مثلنا)\nروضه من الطويل وذكر الهشامي أن الغناء لإبن جامع هزج بالوسطى وفي\nالخبر أنه أخذه عن سوداء لقيها بمكة ومنها صوت\n(يا دار أضحت خلاء لا أنيس بها ... إلا الظباء وإلا الناشط الفرد)\n(أين الذين إذا مازرتهم جذلوا ... وطار عن قلبي التشواق والكمد)\nي هذا الصوت لحن لإبن سريج خفيف ثقيل أول بالوسطى من رواية حبش ولحن ابن جامع رمل ومنها صوت\n(لم تمش ميلا ولم تركب على جمل ... ولم تر الشمس إلا دونها الكلل)\n(أقول للركب في درنا وقد ثملوا ... شيموا وكيف يشيم الشارب الثمل)\nالشعر للأعشى والغناء لإبن سريج رمل بالبنصر وقد كتب فيما يغني فيه من قصيدة الأعشى التي أولها\n(ودع هريرة إن الركب مرتحل ... )\nمنها صوت\n(مررنا على قيسية عامرية ... لها بشر صافي الأديم هجان)\n(فقالت وألقت جانب الستر دونها ... من آية أرض أو من الرجلان)\n(فقلت لها أما تميم فأسرتي ... هديت وأما صاحبي فيماني)\n(رفيقان ضم السفر بيني وبينه ... وقد يلتقي الشتى فيأتلفان)\nناه ابن سريج خفيف رمل بالبنصر ومنها صوت\n(أمسى بأسماء هذا القلب معمودا ... إذا أقول صحا يعتاده عيدا)\n(أجري على موعد منها فتخلفني ... فما أمل ولا توفي المواعيدا)\n(كأنني حين أمسي لا تكلمني ... ذو بغية يبتغي ما ليس موجودا)\nلشعر لعمر بن أبي ربيعة والغناء للغريض خفيف ثقيل أول بالوسطى وله فيه ثقيل أول بالبنصر وذكر عمرو بن بانة أن لمعبد فيه ثقيلا أول بالوسطى على مذهب إسحاق ومنها صوت\n(فوالله ما أدري أيغلبني الهوى ... إذا جد وشك البين أم أنا غالبه)\n(فإن أستطع أغلب وإن يغلب الهوى ... فمثل الذي لاقيت يغلب صاحبه)\nروضه من الطويل الشعر لإبن ميادة والغناء للحجبي خفيف ثقيل بالبنصر من رواية حبش ومنها صوت\n(تعيرنا أنا قليل عديدنا ... فقلت لها إن الكرام قليل)\n(وما ضرنا أنا قليل وجارنا ... عزيز وجار الأكثرين ذليل)\n(وإنا لقوم ما نرى القتل سبة ... إذا ما رأته عامر وسلول)\n(يقرب حب الموت آجالنا لنا ... وتكرهه آجالهم فتطول)\nروضه من مقبوض الطويل والشعر للسموءل بن عادياء اليهودي والغناء لحكم الوادي ومنها صوت\n(وددتك لما كان ودك خالصا ... وأعرضت لما صار نهبا مقسما)\n(ولن يلبث الحوض الجديد بناؤه ... على كثرة الواربد أن يتهدما)\nروضه من الطويل وفيه خفيف ثقيل قديم لأهل مكة وفيه لعريب ثقيل أول ومنها صوت\n(وما كر إلا كان أول طاعن ... ولا أبصرته الخيل إلا اقشعرت)\n(فيدرك ثأرا ثم لم يخطه الغنى ... فمثل أخي يوما به العين قرت)\n(فإن طلبوا وترا بدا بتراتهم ... ويصبر يحميهم إذا الخيل ولت)\nعروضه من الطويل الشعر للخنساء والغناء لإبن سريج ثقيل أول بالبنصر وذكر علي بن يحيى أنه لمعبد في هذه الطريقة ومنها صوت\n(لحا الله صعلوكا مناه وهمه ... من الدهر أن يلقى لبوسا ومطعما)\n(ينام الضحى حتى إذا ليله انتهى ... تنبه مثلوج الفؤاد مورما)\n(ولكن صعلوكا يساور همه ... ويمضي على الهيجاء ليثا مصمما)\n(فذلك إن يلق الكريهة يلقها ... كريما وإن يستغن يوما فربما)\nروضه من الطويل الشعر يقال إنه لعروة بن الورد ويقال إنه لحاتم الطائي وهو الصحيح والغناء لطويس خفيف رمل بالبنصر ومنها\nصوت\n(إذا كنت ربا للقلوص فلا يكن ... رفيقك يمشي خلفها غير راكب)\n(أنخها فأردفه فإن حملتكما ... فذاك وإن كان العقاب فعاقب)\nروضه من الطويل والشعر لحاتم طيء ومنها صوت\n(ألم تر لما ضمني البلد القفر ... سمعت نداء يصدع القلب يا عمرو)\n(أغثنا فإنا عصبة مذحجية ... نزار على وفر وليس لنا وفر)\nروضه من الطويل الشعر لعمرو بن معد يكرب والغناء لحنين رمل بالوسطى عن حبش ومنها صوت\n(فلما تواقفنا وسلمت أقبلت ... وجوه زهاها الحسن أن تتقنعا)\n(تبالهن بالعرفان لما رأينني ... وقلن امرؤ باغ أكل وأوضعا)\n(ولما تنازعن الأحاديث قلن لي ... أخفت علينا أن نغر ونخدعا)\n(وقربن أسباب الهوى لمتيم ... يقيس ذراعا كلما قسن إصبعا)","topic":"ذكر ابن جامع وخبره ونسبه","topicNo":68,"sp":10,"spl":"نسبة ما في هذه الأصوات من الأغاني","partial":1},
{"id":"b68-16","bab":"الجزء 6","sec":"نسبة ما في هذه الأصوات من الأغاني","page":"ج6 ص334","text":"روضه من الطويل الشعر لعمر بن أبي ربيعة والغناء لإبن سريج والغريض ومالك ومعبد وابن جامع في عدة ألحان قد كتبت مع الخبر في موضع غير هذا ومنها صوت\n(عوجي علي فسلمي جبر ... فيم الصدود وأنتم سفر)\n(ما نلتقي إلا ثلاث منى ... حتى يفرق بيننا النفر)\n(الحول ثم الحول يتبعه ... ما الدهر إلا الحول والشهر)\nلشر للعرجي والغناء للأبجر ثقيل أول عن الهشامي ويقال إنه لإبن محرز ويقال بل لحنه فيه غير لحن الأبجر وفيه رمل يقال إنه لإبن جامع وهو القول الصحيح وذكر حبش أنه لإبن سريج وأن لحن ابن جامع خفيف رمل ومنها صوت\n(فلو كان لي قلبان عشت بواحد ... وخلفت قلبا في هواك يعذب)\n(ولكنما أحيا بقلب مروع ... فلا العيش يصفو لي ولا الموت يقرب)\n(تعلمت أسباب الرضا خوف هجرها ... وعلمها حبي لها كيف تعضب)\n(ولي ألف وجه قد عرفت مكانه ... ولكن بلا قلب إلى أين أذهب)\nروضه من الطويل الشعر لعمرو الوراق والغناء لإبن جامع خفيف\nرمل ويقال إنه لعبد الله بن العباس وفيه لعريب ثقيل أول وفيه لرذاذ خفيف ثقيل وفيه هزج يقال إنه لعريب ويقال إنه لنمرة ويقال إنه لأبي فارة ويقال إنه لإبن جامع حدثني مصعب الزبيري قال قدم علينا ابن جامع المدينة قدمة في أيام الرشيد فسمعته يوما يغني في بعض بساتين المدينة\n(ومالي لا أبكي وأندب ناقتي ... إذا صدر الرعيان ورد المناهل)\n(وكنت إذا ما اشتد شوقي رحلتها ... فسارت بمحزون كثير البلابل)\nكان رجلا صيتا فكاد صوته يذهب بي كل مذهب وما سمعت قبله ولا بعده مثله","topic":"ذكر ابن جامع وخبره ونسبه","topicNo":68,"sp":11,"spl":"نسبة ما في هذه الأصوات من الأغاني — ذكر أخبار هذه الأصوات المتفرقة في الأخبار وإنما افردته"},
{"id":"b68-17","bab":"الجزء 6","sec":"نسبة هذا الصوت","page":"ج6 ص341","text":"صوت\n(ومالي لا أبكي وأندب ناقتي ... إذا صدر الرعيان ورد المناهل)\n(وكنت إذا ما اشتد شوقي رحلتها ... فسارت بمحزون كثير البلابل)\nلغناء لإبن جامع خفيف ثقيل بالسبابة في مجرى الوسطى عن الهشامي وابن المكي أخبرني وكيع قال حدثني هارون بن محمد الزيات قال حدثني حماد بن\nإسحاق عن أبيه عن الفضل بن الربيع عن أبيه قال كنت في خمسين وصيفا أهدوا للمنصور ففرقنا في خدمته فصرت إلى ياسر صاحب وضوئه فكنت أراه يفعل شيئا أعلم أنه خطأ يعطيه الإبريق في آخر المستراح ويقف مكانه لا يبرح وقال لي يوما كن مكاني في آخر المستراح فكنت أعطيه الإبريق وأخرج مبادرا فإذا سمعت حركته بادرت إليه فقال لي ما أخفك على قلبي يا غلام ويحك ثم دخل قصرا من تلك القصور فرأى حيطانه مملوءة من الشعر المكتوب عليها فبينا هو يقرأ ما فيه إذا هو بكتاب مفرد فقرأه فإذا هو\n(ومالي لا أبكي وأندب ناقتي ... إذا صدر الرعيان نحو المناهل)\n(وكنت إذا ما اشتد شوقي رحلتها ... فسارت بمحزون طويل البلابل)\nتحته مكتوب آه آه فلم يدر ما هو وفطنت له فقلت يا أمير المؤمنين قد عرفت ما هو فقال قل فقلت قال الشعر ثم تأوه فقال آه آه فكتب تأوهه وتنفسه وتأسفه فقال مالك قاتلك الله قد أعتقتك ووليتك مكان ياسر","topic":"ذكر ابن جامع وخبره ونسبه","topicNo":68,"sp":11,"spl":"نسبة ما في هذه الأصوات من الأغاني — ذكر أخبار هذه الأصوات المتفرقة في الأخبار وإنما افردته"}]);
window.__BOOK__['p03'].push([{"id":"b68-18","bab":"الجزء 6","sec":"ذكر أخبار هذه الأصوات المتفرقة في الأخبار وإنما افردتها عنها لئلا","page":"ج6 ص341","text":"تنقطع","topic":"ذكر ابن جامع وخبره ونسبه","topicNo":68,"sp":11,"spl":"نسبة ما في هذه الأصوات من الأغاني — ذكر أخبار هذه الأصوات المتفرقة في الأخبار وإنما افردته"},
{"id":"b68-19","bab":"الجزء 6","sec":"خبر","page":"ج6 ص342","text":"(أمسى بأسماء هذا القلب معمودا ... )\nخبرني الحسين بن يحيى قال حماد قرأت على أبي وذكر جعفر بن سعيد عن عبد الرحمن بن سليمان المكي قال حدثني المخزومي يعني الحارث بن خالد قال بلغني أن الغريض خرج مع نسوة من أهل مكة من أهل الشرف ليلا إلى\nبعض المتحدثات من نواحي مكة وكانت ليلة مقمرة فاشتقت إليهن وإلى مجالستهن وإلى حديثهن وخفت على نفسي لجناية كنت أطالب بها وكان عمر مهيبا معظما لا يقدم عليه سلطان ولا غيره وكان مني قريبا فأتيته فقلت له إن فلانة وفلانة وفلانة حتى سميتهن كلهن قد بعثنني وهن يقرأن عليك السلام وقلن تشوقن إليك في ليلتنا هذه لصوت أنشدناه فويسقك الغريض وكان الغريض يغني هذا الصوت فيجيده وكان ابن أبي ربيعة به معجبا وكان كثيرا ما يسأل الغريض أن يغنيه وهو قوله\n(أمسى بأسماء هذا القلب معمودا ... إذا أقول صحا يعتاده عيدا)\n(كأن أحور من غزلان ذي نفر ... أهدي لها شبه العينين والجيدا)\n(قامت تراءى وقد جد الرحيل بنا ... لتنكأ القرح من قلب قد اصطيدا)\n( كأنني يوم أمسي لا تكلمني ... ذو بغية يبتغي ما ليس موجودا أجري على موعد منها فتخلفني ... فما أمل وما توفي المواعيدا قد طال مطلي لو أن اليأس ينفعني ... أو أن أصادف من تلقائها جودا فليس تبذل لي عفوا وأكرمها ... من أن ترى عندنا في الحرص تشديدا\nلما أخبرته الخبر قال لقد أزعجتني في وقت كانت الدعة أحب فيه إلي ولكن صوت الغريض وحديث النسوة ليس له مترك ولا عنه محيص فدعا بثيابه فلبسها وقال امض فمضينا نمشي العجل حتى قربنا منهن فقال لي عمر خفض عليك مشيك ففعلت حتى وقفنا عليهن وهن في أطيب حديث وأحسن مجلس فسلمنا فتهيبننا وتخفرن منا فقال الغريض لا عليكن هذا ابن أبي ربيعة والحارث بن خالد جاءا متشوقين إلى حديثكن وغنائي فقالت فلانة\nوعليك السلام يا بن أبي ربيعة والله ما تم مجلسنا إلا بك فجلسنا غير بعيد وأخذن عليهن جلابيهن وتقنعن بأخمرتهن وأقبلن علينا بوجوههن وقلن لعمر كيف أحسست بنا وقد أخفينا أمرنا فقال هذا الفاسق جاءني برسالتكن وكنت وقيذا من علة وجدتها فأسرعت الإجابة ورجوت منكن على ذلك حسن الإثابة فرددن عليه قد وجب أجرك ولم يخب سعيك ووافق منا الحارث إرادة فحدثهن بما قلت له من قصة غناء الغريض فقال النسوة والله ما كان ذلك كذلك ولقد نبهتنا على صوت حسن يا غريض هاته فاندفع الغريض يغني ويقول\n(أمسى بأسماء هذا القلب معمودا ... إذا أقول صحا يعتاده عيدا)\nتى أتى على الشعر كله إلى آخره فكل استحسنه وأقبل علي ابن أبي ربيعة فجزاني الخير وكذلك النسوة فلم نزل بأنعم ليلة وأطيبها حتى بدأ القمر يغيب فقمنا جيمعا وأخذ النسوة طريقا ونحن طريقا وأخذ الغريض معنا وقال عمر في ذلك صوت\n(هل عند رسم برامة خبر ... أم لا فأي الأشياء تنتظر)\n(قد ذكرتني الديار إذ درست ... والشوق مما يهيجه الذكر)\n(ممشى رسول إلي يخبرني ... عنهم عشاء ببعض ما ائتمروا)\n(ومجلس النسوة الثلاث لدى الخيمات ... حتى تبلج السحر)\n(فيهن هند والهم ذكرتها ... تلك التي لا يرى لها خطر)\n(ثم انطلقنا وعندنا ولنا ... فيهن لو طال ليلنا وطر)\n(وقولها للفتاة إذ أزف البين ... أغاد أم رائح عمر)\n(عجلان لم يقض بعض حاجته ... هلا تأنى يوما فينتظر)\n(الله جار له وإن نزحت ... دار به أو بدا له سفر)\nناه الغريض ثقيلا أول بإطلاق الوتر في مجرى البنصر وفيه لإبن سريج رمل بالوسطى وفيه لعبد الرحيم الدفاف ثقيل أول بالبنصر في البيتين الأولين وبعدهما\n(هل من رسول إلي يخبرني ... بعد عشاء ببعض ما ائتمروا)\n(يوم ظللنا وعندنا ولنا ... فيهن لو طال يومنا وطر)\nلما كانت الليلة القابلة بعث إلي عمر فأتيته وإذا الغريض عنده فقال له عمر هات فاندفع يغني\n(هل عند رسم برامة خبر ... أم لا فأي الأشياء تنتظر)\n(ومجلس النسوة الثلاث لدى الخيمات ... حتى تبلج السحر)\nقلت في نفسي هذا والله صفة ما كنا فيه فسكت حتى فرغ الغريض من الشعر كله فقلت يا أبا الخطاب جعلت فداك هذا والله صفة ما كنا فيه البارحة مع النسوة فقال إن ذلك ليقال وذكر أحمد بن الحارث عن المدائني عن علي بن مجاهد قال إن موسى بن مصعب كان على الموصل فاستعمل رجلا من أهل حران\nعلى كورة باهذرا وهي أجل كور الموصل فابطأ عليه الخراج فكتب إليه\n(هل عند رسم برامة خبر ... أم لا فأي الأشياء تنتظر)","topic":"ذكر ابن جامع وخبره ونسبه","topicNo":68,"sp":12,"spl":"خبر","partialRef":{"sid":"b68-13","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b68-20","bab":"الجزء 6","sec":"خبر","page":"ج6 ص342","text":"حمل ما عندك يا ماص بظر أمه وإلا فقد أمرت رسولي بشدك وثاقا ويأتي بك فخرج الرجل وأخذ ما كان معه من الخراج فلحق بحران وكتب إليه يا عاض بظر أمه إلي تكتب بمثل هذا\n(وإذا أهل بلدة أنكروني ... عرفتني الدوية الملساء)\nلما قرأ موسى كتابه ضحك وقال أحسن يعلم الله الجواب ولا والله لا أطلبه أبدا وفي غير هذه الرواية أنه كتب إليه في آخر رقعة\n(إن الخليط الأولى تهوى قد أئتمروا ... للبين ثم أجدوا السير فانشمروا)\nا بن الزانية والسلام ثم هرب فلم يطلبه أخبرنا الحسين بن يحيى عن حماد قال قال أبي غناني رجل من أهل المدينة لحن الغريض\n(هل عند رسم برامة خبر ... أم لا فأي الأشياء تنتظر)\nسألته أن يلقيه علي فقال لا إلا بألف درهم فلم أسمح له بذلك ومضى فلم ألقه فوالله يا بني ما ندمت على شيء قط ندمي على ذلك ولوددت أني وجدته الآن فأخذته منه كما سمعته وأخذ مني ألف دينار مكان الألف درهم","topic":"ذكر ابن جامع وخبره ونسبه","topicNo":68,"sp":13,"spl":"خبر — خبر"},
{"id":"b68-21","bab":"الجزء 6","sec":"خبر","page":"ج6 ص346","text":"(تعيرنا أنا قليل عديدنا ... )\nلشعر لشريح بن السموءل بن عادياء ويقال إن للسموءل وكان من يهود يثرب وهو الذي يضرب به المثل في الوفاء فيقال أوفي في السموءل وكان السبب في ذلك فيما ذكر ابن الكلبي وأبو عبيدة وحدثني به محمد بن العباس اليزيدي قال حدثنا سليمان بن أبي شيخ قال حدثنا يحيى بن سعيد الأموي عن محمد بن السائب الكلبي قال","topic":"ذكر ابن جامع وخبره ونسبه","topicNo":68,"sp":13,"spl":"خبر — خبر","partialRef":{"sid":"b68-13","gi":2,"vi":0,"side":0},"partial":1},
{"id":"b68-22","bab":"الجزء 6","sec":"وفاء السموءل","page":"ج6 ص347","text":"كان امرؤ القيس بن حجر أودع السموءل بن عادياء أدراعا فأتاه الحارث بن ظالم ويقال الحارث بن أبي شمر الغساني ليأخذها منه فتحصن منه السموءل فأخذ ابنا له غلاما وناداه إما أن تسلم الأدراع وإما أن قتلت ابنك فأبى السموءل أن يسلم الأدراع إليه فضرب الحارث وسط الغلام بالسيف فقطعه أثنين فقال السموءل\n(وفيت بأدرع الكندي إني ... إذا ما خان أقوام وفيت)\n(وأوصى عاديا يوما بألا ... تهدم يا سموءل ما بنيت)\n(بنى لي عاديا حصنا حصينا ... وماء كلما شئت استقيت)\nفي هذه القصيدة يقول صوت\n(أعاذلتي ألا لا تعذليني ... فكم من أمر عاذلة عصيت)\n(دعيني وارشدي إن كنت أغوى ... ولا تغوي زعمت كما غويت)\n(أعاذل قد طلبت اللوم حتى ... لو أني منته لقد انتهيت)\n(وصفراء المعاصم قد دعتني ... إلى وصل فقلت لها أبيت)\n(وزق قد جررت إلى الندامى ... وزق قد شربت وقد سقيت)\n(وحتى لو يكون فتى أناس ... بكى من عذل عاذلة بكيت)\nروضه من الوافر والشعر للسموءل بن عادياء والغناء لإبن محرز في الأول والثاني والرابع والخامس خفيف ثقيل أول بالسبابة في مجرى الوسطى وغنى فيها مالك خفيف ثقيل بالبنصر في الأول والثاني وغنى دحمان ايضا في الأول والثاني والرابع والخامس رملا بالوسطى وغنى عبد الرحيم الدفاف في الأول والثاني رملا بالبنصر وفي هذه الأبيات لإبن سريج لحن في الرابع وما بعده ثم في سائر الأبيات لحن ذكره يونس ولم ينسبه ولإبراهيم الموصلي فيها لحن غير منسوب أيضا حدثني محمد بن العباس اليزيدي قال حدثني سليمان بن ابي شيخ قال حدثنا يحيى بن سعيد الأموي قال حدثني محمد بن السائب الكلبي قال هجا الأعشى رجلا من كلب فقال\n(بنو الشهر الحرام فلست منهم ... ولست من الكرام بني عبيد)\n(ولا من رهط جبار بن قرط ... ولا من رهط حارثة بن زيد)\nال وهؤلاء كلهم من كلب فقال الكلبي أنا لا أبالك أشرف من هؤلاء قال فسبه الناس بعد بهجاء الأعشى وكان متغيظا عليه فأغار الكلبي على قوم قد بات بهم الأعشى فأسر منهم نفرا وأسرا الأعشى وهو لا يعرفه فجاء حتى نزل بشريح بن السموءل بن عادياء الغساني صاحب تيماء بحصنه الذي يقال\nله الأبلق فمر شريح بالأعشى فنادى به الأعشى بقوله\n(شريح لا تتركني بعد ما علقت ... حبالك اليوم بعد القد أظفاري)\n(قد جلت ما بين بانقيا إلى عدن ... فطال في العجم تردادي وتسياري)\n(فكان أكرمهم عهدا وأوثقهم ... عقدا أبوك بعرف غير إنكار)\n(كالغيث ما استمطروه جاد وابله ... وفي الشدائد كالمستأسد الضاري)\n(كن كالسموءل إذ طاف الهمام به ... في جحفل كسواد الليل جرار)\n(إذ سامه خطتي خسف فقال له ... قل ما تشاء فإني سامع حار)\n(فقال غدر وثكل أنت بينهما ... فأختر وما فيهما حظ لمختار)\n(فشك غير طويل ثم قال له ... أقتل أسيرك إني مانع جاري)\n(وسوف يعقبنيه إن ظفرت به ... رب كريم وبيض ذات أطهار)\n(لاسرهن لدينا ذاهب هدرا ... وحافظات إذا استودعن أسراري)\n(فاختار أدراعه كي لا يسب بها ... ولم يكن وعده فيها بختار)\nقال فجاء شريح إلى الكلبي فقال له هب لي هذا الأسير المضرور فقال هو لك فأطلقه وقال له أقم عندي حتى أكرمك وأحبوك فقال له الأعشى إن من تمام صنيعك إلي أن تعطيني ناقة ناجية وتخليني الساعة قال فأعطاه ناقة\nفركبها ومضى من ساعته وبلغ الكلبي أن الذي وهب لشريح هو الأعشى فأرسل إلى شريح ابعث إلي بالأسير الذي وهبت لك حتى أحبوه وأعطيه فقال قد مضى فأرسل الكلبي في أثره فلم يلحقه وأما خبر\n(وما كر إلا كان أول طاعن ... )\nالشعر للخنساء فإنه خبر يطول لذكر ما فيه من الوقائع وهو يأتي فيما بعد هذا مفردا عن المائة الصوت المختارة في أخبار الخنساء","topic":"ذكر ابن جامع وخبره ونسبه","topicNo":68,"sp":14,"spl":"وفاء السموءل","partialRef":{"sid":"b68-13","gi":4,"vi":0,"side":0},"partial":1},
{"id":"b68-23","bab":"الجزء 6","sec":"رجع الخبر إلى قصة ابن جامع","page":"ج6 ص350","text":"وأما خبر الجارية التي أخذ عنها ابن جامع الصوت وما حكيناه من أنه وقع في حكاية محمد بن ضوين الصلصال فيها خطأ فأخبرنا بخبرها الحسين بن يحيى عن حماد بن إسحاق عن عبد الله بن أبي محمد العامري قال حدثني عكاشة اليزيدي بجرجان قال حدثني إسماعيل بن جامع قال بينا أنا في غرفة لي باليمن وأنا مشرف على مشرعة إذ أقبلت أمة سوداء على ظهرها قربة فملأتها ووضعتها على المشرعة لتستريح وجلست فغنت صوت\n(فردي مصاب القلب أنت قتلته ... ولا تبعدي فيما تجشمت كلثما)\nيروى ولا تتركيه هائم القلب مغرما\n(إلى الله أشكو بخلها وسماحتي ... لها عسل مني وتبذل علقما)\n(أبى الله أن أمسي ولا تذكرينني ... وعيناي من ذكراك قد ذرفت دما)\n(أبيت فما تنفك لي منك حاجة ... رمي الله بالحب الذي كان أظلما)\nناه سياط ثقيل أول بالبنصر على مذهب إسحاق من رواية عمر بن بانة قال ثم أخذت قربتها لتمضي فاستفزني من شهوة الصوت ما لا قوام لي به فنزلت إليها فقلت لها أعيديه فقالت أنا عنك في شغل بخراجي قلت وكم هو قالت درهمان في كل يوم قلت فهذان درهمان ورديه علي حتى آخذه منك وأعطيتها درهمين فقالت أما الآن فنعم فجلست فلم تبرح حتى أخذته منها وانصرفت فلهوت يومي به وأصحبت من غد لا أذكر منه حرفا فإذا أنا بالسوداء قد طلعت ففعلت كفعلها بالأمس فلما وضعت القربة تغنت غيره فعدوت في أثرها وقلت يا جارية بحقي عليك ردي علي الصوت فقد ذهبت عني منه نغمة فقالت لا والله ما مثلك تذهب عنه نغمة أنت تقيس أوله على آخره ولكنك قد أنسيته ولست أفعل إلا بدرهمين آخرين فدفعتهما إليها وأعادته علي حتى أخذته ثانية ثم قالت إنك تستكثر فيه أربعة دراهم وكأني بك قد أصبت به أربعة آلاف دينار فكنت عند هارون يوما وهو على سريره فقال من غناني فأطربني فله ألف دينار وقدامه أكياس في كل كيس ألف دينار فغنى القوم وغنيت فلم يطرب حتى دار الغناء إلي ثانية فغنيت صوت السوداء فرمى إلي بكيس فيه ألف دينار ثم قال أعده فغنيته فرمى إلي بثان ثم قال أعده فرمى إلي بثالث وأمسك فضحكت فقال ما يضحكك فقلت لهذا الصوت حديث عجيب يا أمير المؤمنين فقال وما هو فحدثته به وقصصت عليه القصة فرمى إلي برابع وقال لا نكذب قولها","topic":"ذكر ابن جامع وخبره ونسبه","topicNo":68,"sp":15,"spl":"رجع الخبر إلى قصة ابن جامع — خبر"},
{"id":"b68-24","bab":"الجزء 6","sec":"خبر","page":"ج6 ص351","text":"(عوجي علي فسلمي جبر ... )\nلشعر للعرجي وقد ذكرنا نسبة الصوت","topic":"ذكر ابن جامع وخبره ونسبه","topicNo":68,"sp":15,"spl":"رجع الخبر إلى قصة ابن جامع — خبر","partialRef":{"sid":"b6-21","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b68-25","bab":"الجزء 6","sec":"عمر بن عبد العزيز وأحد المخنثين","page":"ج6 ص352","text":"أخبرني الحسين بن يحيى عن حماد عن أبيه عن الواقدي عن ابن أبي الزناد قال حدثني محمد بن إسحاق قال قيل لعمر بن عبد العزيز إن بالمدينة مخنثا قد أفسد نساءها فكتب إلى عامله بالمدينة أن يحمله فأدخل عليه فإذا خضيب اللحية والأطراف معتجر بسبنية قد حمل دفا في خريطته فلما وقف بين يدي عمر صعد بصره فيه وصوبه وقال سوأة لهذه الشيبة وهذه القامة أتحفظ القرآن قال لا والله يا أبانا قال قبحك الله وأشار إليه من حضره فقالوا اسكت فسكت فقال له عمر أتقرأ من المفصل شيئا قال وما المفصل قال ويلك أتقرأ من القرآن شيئا قل نعم أقرأ ( الحمدلله\nوأخطىء فيها في موضعين أو ثلاثة وأقرأ ( قل أعوذ برب الناس\nوأخطىء فيها وأقرأ ( قل هو الله أحد\nمثل الماء الجاري قال ضعوه في الحبس ووكلوا به معلما يعلمه القرآن وما يجب عليه من حدود الطهارة والصلاة وأجروا عليه في كل يوم ثلاثة دراهم وعلى معلمه ثلاثة دراهم أخر ولا يخرج من الحبس حتى يحفظ القرآن أجمع فكان كلما علم سورة نسي التي قبلها فبعث رسولا إلى عمر يا أمير المؤمنين وجه إلي من يحمل إليك ما أتعلمه أولا فأولا فإني لا أقدر على حمله جملة واحدة فيئس عمر من فلاحه وقال ما أرى هذه الدراهم إلا ضائعة ولو أطعمناها جائعا أو أعطيناها محتاجا أو كسوناها عريانا لكان أصلح ثم دعا به فلما وقف بين يديه قال له اقرأ ( قل يأيها الكافرون\nقال أسأل الله العافية أدخلت يدك في الجراب فأخرجت شر ما فيه وأصعبه فأمر\nبه فوجئت عنقه ونفاه فاندفع يغني وقد توجهوا به\n(عوجي علي فسلمي جبر ... فيم الوقوف وأنتم سفر)\n(ما نلتقي إلا ثلاث منى ... حتى يفرق بيننا النفر)\nلما سمع الموكلون به حسن ترنمه خلوه وقالوا له اذهب حيث شئت مصاحبا بعد استماعهم منه طرائف غنائه سائر يومهم وليلتهم أخبرني الحسين قال قال حماد قرأت على أبي عن المدائني قال أحج خالد بن عبد الله ابنه محمدا وأصحبه رزاما مولاه وأعطاه مالا وقال إذا دخلت المدينة فاصرفه فيما أحببت فلما صرنا بالمدينة سأل محمد عن جارية حاذقة فقيل عند محمد بن عمران التيمي القاضي فصلينا الظهر في المسجد ثم ملنا إليه فاستأذنا عليه فأذن لنا وقد انصرف من المسجد وهو قاعد على لبد ونعلاه في آخر اللبد فسلمنا عليه فرد ونسب محمدا فانتسب له فقال خيرا ثم قال هل من حاجة فلجلج فقال كأنك ذكرت فلانة يا جارية اخرجي فخرجت فإذا أحسن الناس ثم تغنت فإذا أحذق الناس فجعل الشيخ يذهب مع حركاتها ويجيء إلى أن غنت قوله\n(عوجي علي فسلمي جبر ... )\nلما بلغت\n(حتى يفرق بيننا النفر ... )\nثب الشيخ إلى نعله فعلقها في أذنه وجثا على ركبتيه وأخذ بطرف أذنه والنعل فيها\nوجعل يقول أهدوني أنا بدنة أهدوني أنا بدنة ثم أقبل عليهم فقال كم قيل لكم إنها تساوي قالوا ستمائة دينار قال هي وحق القبر خير من ستة آلاف دينار والله لا يملكها علي أحد أبدا فانصرفوا إذا شئتم أخبرنا وسواسة بن الموصلي وهو أحمد بن إسماعيل بن إبراهيم الموصلي قال حدثني حماد بن إسحاق قال وجدت في كتب أبي عن عثمان بن حفص الثقفي عن أبن عم لعمارة بن حمزة قال حدثني سليم الحساب عن داود المكي قال كنا في حلقة ابن جريج وهو يحدثنا وعنده ابن المبارك وجماعة من العراقيين إذ مر به ابن تيزن قال حماد ويقال ابن بيرن وقد ائتزر بمئزرة على صدره وهي إزرة الشطار عندنا فدعاه ابن جريج فقال له إني مستعجل وقد وعدت أصحابا لي فلا أقدر أن أحتبس عنهم فأقسم عليه حتى أتاه فجلس وقال له ما تريد قال أحب أن تسمعني قال أنا أجيئك إلى المنزل فلم تجلسني مع هؤلاء الثقلاء قال أسألك أن تفعل قال امرأته طالق إن غناك فوق ثلاثة أصوات قال ويحك ما أعجلك باليمين قال أكره أن أحتبس عن أصحابي فالتفت ابن جريج إلى أصحابه فقال إعقلوا رحمكم الله ثم قال له\nغنني الصوت الذي أخبرتني أن ابن سريج غناه في اليوم الثالث من أيام منى على جمرة العقبة فقطع الطريق على الذاهب والجائي حتى تكسرت المحامل فغناه\n(عوجي علي فسلمي جبر ... )\nقال ابن جريج أحسنت والله ثلاث مرات ويحك أعده قال أمن الثلاثة فإني قد حلفت قال أعده فأعاده فقال أحسنت أعده من الثلاثة فأعاده وقام فمضى فقال ابن جريج لأصحابه لعلكم أنكرتم ما فعلت قالوا إنا لننكره بالعراق قال فما تقولون في الرجر يعني الحداء قالوا لا بأس به قال فما الفرق بينهما","topic":"ذكر ابن جامع وخبره ونسبه","topicNo":68,"sp":16,"spl":"عمر بن عبد العزيز وأحد المخنثين","partialRef":{"sid":"b6-21","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b68-26","bab":"الجزء 6","sec":"أحسن الناس حلوقا في الغناء","page":"ج6 ص355","text":"وذكر هارون بن محمد بن عبد الملك عن أبي أيوب المديني قال ثلاثة من المغنين كانوا أحسن الناس حلوقا ابن تيزن وابن عائشة وابن أبي الكنات\nصوت من المائة المختارة\n(سقاني فرواني كميتا مدامة ... على ظمأ مني سلام بن مشكم)\n(تخيرته أهل المدينة واحدا ... سواهم فلم أغبن ولم أتندم)\nروضه من الطويل والشعر لأبي سفيان بن حرب والغناء لسليمان أخي بابويه الكوفي مولى الأشاعثة خفيف رمل بالسبابة في مجرى الوسطى","topic":"ذكر ابن جامع وخبره ونسبه","topicNo":68,"sp":17,"spl":"أحسن الناس حلوقا في الغناء"},
{"id":"b69-1","bab":"الجزء 6","sec":"ذكر ابي سفيان وأخباره ونسبه","page":"ج6 ص357","text":"هو صخر بن حرب بن أمية بن عبد شمس بن عبد مناف وأم حرب بن أمية بنت أبي همهمة بن عبد العزى بن عامر بن عميرة بن وديعة بن الحارث بن فهر بن مالك بن النضر بن كنانة وأم أبي سفيان صفية بنت حزن بن بجير بن الهزم بن رويبة بن عبد الله بن هلال بن عامر بن صعصعة وهي عمة ميمونة أم المؤمنين وأم الفضل بنت الحارث بن حزن أم بني العباس بن عبد المطلب وقد مضى ذكر أكثر أخبار ولد أمية والفرق بين الأعياص والعنابس منهم وجمل من أخبارهم في أول هذا الكتاب وكان حرب بن أمية قائد بني أمية ومن مالأهم في يوم عكاظ ويقال إن سبب وفاته أن الجن قتلته وقتلت مرداس بن أبي عامر السلمي لإحراقهما شجر القرية وازدراعهما إياها وهذا شيء قد ذكرته العرب في أشعارها وتواترت الروايات بذكره فذكرته والله أعلم أخبرني الطوسي والحرمي بن أبي العلاء قالا حدثنا الزبير بن بكار قال\nحدثني عمي مصعب وأخبرنا محمد بن الحسين بن دريد عن عمه عن العباس بن هشام عن أبيه وذكره أبو عبيدة وأبو عمرو الشيباني أن حرب بن أمية لما انصرف من حرب عكاظ هو وإخوته مر بالقريه وهي إذ ذاك غيضة شجر ملتف لا يرام فقال له مرداس بن أبي عامر أما ترى هذا الموضع قال بلى قال نعم المزدرع هو فهل لك أن نكون شريكين فيه ونحرق هذه الغيضة ثم نزدرعه بعد ذلك قال نعم فأضرما النار في الغيضة فلما استطارت وعلا لهبها سمع من الغيضة أنين وضجيج كثير ثم ظهرت منها حيات بيض تطير حتى قطعتها وخرجت منها وقال مرداس بن أبي عامر في ذلك\n(إني انتخبت لها حربا وإخوته ... إني بحبل وثيق العقد دساس)\n(إني أقوم قبل الأمر حجته ... كيما يقال ولي الأمر مرداس)\nال فسمعوا هاتفا يقول لما احترقت الغيضة\n(ويل لحرب فارسا ... مطاعنا مخالسا)\n(ويل لعمرو فارسا ... إذ لبسوا القوانسا)\n(لنقتلن بقتله ... جحاجحا عنابسا)\nلم يلبث حرب بن أمية ومرداس بن أبي عامر أن ماتا فأما مرداس فدفن بالقربة ثم ادعاها بعد ذلك كليب بن أبي عهمة السلمي ثم الظفري فقال في ذلك عباس بن مرداس\n(أكليب مالك كل يوم ظالما ... والظلم أنكد وجهه ملعون)\nلمعيون الذي أصابته العين وقيل المعيون الحسن المنظر فيما تراه العين ولا عقل له\n(فإذا رجعت إلى نسائك فادهن ... إن المسالم رأسه مدهون)\n(وافعل بقومك ما أراد بوائل ... يوم الغدير سميك المطعون)\n(وإخال أنك سوف تلقى مثلها ... في صفحتيك سنانها المسنون)\n(إن القرية قد تبين أمرها ... إن كان ينفع عندك التبيين)\n(حيث انطلقت تخطها لي ظالما ... وأبو يزيد بجوها مدفون)\nبو يزيد مرداس بن أبي عامر","topic":"ذكر ابي سفيان وأخباره ونسبه","topicNo":69,"sp":0,"spl":"ذكر ابي سفيان وأخباره ونسبه"},
{"id":"b69-2","bab":"الجزء 6","sec":"منزلته في قريش","page":"ج6 ص359","text":"وكان أبو سفيان سيدا من سادات قريش في الجاهلية ورأسا من رؤوس الأحزاب وعلى رسول الله في حياته وكهفا للمنافقين في أيامه وأسلم يوم الفتح وله في إسلامه أخبار نذكرها هنا وكان تاجرا يجهز التجار بماله وأموال قريش إلى أرض العجم وشهد مع رسول الله مشاهدة الفتح وفقئت عينه يوم الطائف فلم يزل أعور إلى يوم اليرموك ففقئت عينه الأخرى يومئذ فعمي أخبرنا الطوسي والحرمي قالا حدثنا الزبير بن بكار قال حدثني علي بن صالح عن جدي عبد الله بن مصعب عن إسحاق بن يحيى المكي عن أبي الهيثم عمن أخبره أنه سمع أبا سفيان يمازح رسول الله في بيت بنته أم حبيبة ويقول والله إن هو إلا أن تركتك فتركتك العرب فما انتطحت جماء ولا ذات قرن ورسول\nالله يضحك ويقول أنت تقول ذاك يا أبا حنظلة قال الزبير وحدثني عمي مصعب أن رسول الله تزوج أم حبيبة بنت أبي سفيان وأبو سفيان يومئذ مشرك يحارب رسول الله وقيل له إن محمدا قد نكح ابنتك فقال ذلك الفحل لا يقدع أنفه واسم أم حبيبة رملة وقيل هند والصحيح رملة أخبرنا محمد بن العباس اليزيدي قال حدثنا أحمد بن الحارث الخزاز قال حدثنا المدائني عن مسلمة بن محارب عن عثمان بن عبد الرحمن بن جوشن قال أذن رسول الله يوما للناس فأبطأ بإذن أبي سفيان فلما دخل قال يا رسول الله ما أذنت لي حتى كدت تأذن للحجارة فقال له يا أبا سفيان كل الصيد في جوف الفرا حدثنا محمد بن العباس قال حدثنا الخليل بن أسد النوشجاني قال حدثنا عطاء بن مصعب قال حدثني سفيان بن عيينة عن جعفر بن يحيى البرمكي قال أذن رسول الله للناس فكان آخر من دخل عليه أبا سفيان بن حرب فقال يارسول الله لقد أذنت للناس قبلي حتى ظننت أن حجارة الخندمة ليؤذن\nلها قبلي فقال رسول الله أما والله إنك والناس لكما قال الأول كل الصيد في بطن الفرا أي كل شيء لهؤلاء من المنزلة فإن لك وحدك مثل ما لهم كلهم","topic":"ذكر ابي سفيان وأخباره ونسبه","topicNo":69,"sp":1,"spl":"منزلته في قريش"},
{"id":"b69-3","bab":"الجزء 6","sec":"عند هرقل","page":"ج6 ص361","text":"حدثني عمر بن إسماعيل بن أبي غيلان الثقفي قال حدثنا داود بن عمرو الضبي قال حدثنا المثنى بن زرعة أبو راشد عن محمد بن إسحاق قال حدثني الزهري عن عبد الله بن عبد الله عن عتبة عن ابن عباس قال حدثني أبو سفيان بن حرب قال كنا قوما تجارا وكانت الحرب بيننا وبين رسول الله قد حصرتنا حتى نهكت أموالنا فلما كانت الهدنة هدنة الحديبية بيننا وبين رسول الله خرجت في نفر من قريش إلى الشأم وكان وجه متجرنا منه غزة فقدمناها حين ظهر هرقل على من كان بأرضه من الفرس فأخرجهم منها وانتزع منهم صليبه الأعظم وكانوا قد استلبوه إياه فلما بلغه ذلك منهم وبلغه أن صليبه قد استنقذ منهم وكانت حمص منزله خرج منها يمشي على قدميه شكرا لله حين رد عليه ما رد ليصلي في بيت المقدس تبسط له البسط وتلقى عليها الرياحين فلما انتهى إلى إيلياء فقضى فيها صلاته وكان معه بطارقته وأشراف الروم أصبح ذات غدوة مهموما يقلب طرفه إلى السماء فقال له بطارقته والله لكأنك أصبحت الغداة مهموما فقال أجل رأيت البارحة أن ملك الختان ظاهر فقالوا أيها الملك ما نعمل أمة تختتن إلا اليهود وهم في سلطانك وتحت يدك فابعث إلى كل من\nلك عليه سلطان في بلادك فمره فليضرب أعناق من تحت يدك منهم من يهود واسترح من هذا الهم فوالله إنهم لفي ذلك من رأيهم يدبرونه إذ أتاه رسول صاحب بصرى برجل من العرب يقوده وكانت الملوك تتهادى الأخبار بينهم فقال أيها الملك إن هذا رجل من العرب من أهل الشاء والإبل يحدث عن أمر حدث فاسأله فلما انتهى به إلى هرقل رسول صاحب بصرى قال هرقل لمن جاء به سله عن هذا الحديث الذي كان ببلده فسأله فقال خرج بين أظهرنا رجل يزعم أنه نبي وقد اتبعه ناس فصدقوه وخالفه آخرون وقد كانت بينهم ملاحم في مواطن كثيرة وتركتهم على ذلك فلما أخبره الخبر قال جردوه فإذا هو مختون فقال هذا والله النبي الذي الذي رأيت لا ما تقولون أعطوه ثيابه وينطلق ثم دعا صاحب شرطته فقال له اقلب الشأم ظهرا لبطن حتى تأتيني برجل من قولم هذا الرجل فإنا لبغزة إذ هجم علينا صاحب شرطته فقال أنتم من قوم الحجاز قلنا نعم قال انطلقوا إلى الملك فانطلقوا بنا فلما انتهينا إليه قال أنتم من رهط هذا الرجل الذي بالحجاز قلنا نعم قال فأيكم أمس به رحما قال قلت أنا قال أبو سفيان وايم الله ما رأيت رجلا أرى أنه أنكر من ذلك الأغلف يعني هرقل ثم قال أدنه فأقعدني بين يديه وأقعد أصحابي خلفي وقال إني سأسأله فإن كذب فردوا عليه قال فوالله لقد علمت أن لو كذبت ما ردوا علي ولكني كنت أمرأ سيدا أتبرم عن الكذب وعرفت أن أيسر ما في ذلك إن أنا كذبته أن يحفظوه علي ثم يحدثوا به عني فلم أكذبه قال أخبرني عن هذا الرجل الذي خرج بين أظهركم","topic":"ذكر ابي سفيان وأخباره ونسبه","topicNo":69,"sp":2,"spl":"عند هرقل"},
{"id":"b69-4","bab":"الجزء 6","sec":"عند هرقل","page":"ج6 ص361","text":"يدعي ما يدعي فجعلت أزهد له شأنه وأصغر له أموره وأقول له أيها الملك ما يهمك من شأنه إن أمره دون ما بلغك فجعل لا يلتفت إلى ذلك مني ثم قال أنبئني فيما أسألك عنه من شأنه قال قلت سل عما بدا لك قال كيف نسبه فيكم قلت محض هو أوسطنا نسبا قال أخبرن هل كان أحد من أهل بيته يقول ما يقول فهو يتشبه به قال قلت لا قال هل كان له فيكم ملك فسلبتموه إياه فجاء بهذا الحديث لتردوا عليه ملكه قال قلت لا قال أخبرني عن أتباعه منكم من هم قال قلت الضعفاء والمساكين والأحداث من الغلمان والنساء فأما ذوو الأسنان من الأشراف من قومه فلم يتبعه منهم أحد قال فأخبرني عمن يتبعه أيحبه ويلزمه أم يقليه ويفارقه قال قلت قلما يتبعه أحد فيفارقه قال فأخبرني كيف الحرب بينكم وبينه قال قلت سجال يدال علينا وندال عليه قال فأخبرني هل يغدر فلم أجد شيئا سألني عنه أغتمز فيه غيرها قال قلت لا ونحن منه في مدة ولا نأمن غدره قال فوالله ما التفت إليها مني ثم كرر علي الحديث فقال سألتك عن نسبه فيكم فزعمت أنه محض من أوسطكم نسبا فكذلك يأخذ الله النبي لا يأخذه إلا من أوسط قومه نسبا وسألتك هل كان أحد من أهل بيته يقول مثل قوله فهو يتشبه به فزعمت أن لا وسألتك هل كان له ملك فيكم فسلبتموه إياه فجاء بهذا الحديث يطلب ملكه فزعمت أن لا وسألتك عن أتباعه فزعمت أنهم الضعفاء والأحداث والمساكين والنساء وكذلك أتباع الأنبياء في كل زمان وسألتك عمن يتبعه أيحبه ويلزمه أم يقليه ويفارقه فزعمت أنه لا يتبعه أحد فيفارقه فكذلك حلاوة الإيمان لا تدخل قلب رجل فتخرج منه وسألتك عن الحرب بينكم وبينه فزعمت أنها سجال تدالون عليه ويدال عليكم وكذلك حرب الأنبياء ولهم تكون العاقبة وسألتك هل يغدر فزعمت أن لا فلئن كنت صدقتني عنه فليغلبن علي ما تحت قدمي هاتين ولوددت أني عنده\nفأغسل قدميه انطلق لشأنك فقمت من عنده وأنا أضرب بإحدى يدي على الأخرى وأقول يالعباد الله لقد أمر أمر ابن أبي كبشة أصبحت ملوك بني الأصفر يهابونه في ملكهم وسلطانهم","topic":"ذكر ابي سفيان وأخباره ونسبه","topicNo":69,"sp":3,"spl":"عند هرقل"},
{"id":"b69-5","bab":"الجزء 6","sec":"كتاب النبي إلى هرقل","page":"ج6 ص364","text":"قال ابن إسحاق فقدم عليه كتاب رسول الله مع دحية ابن خليفة الكلبي فيه ( بسم الله الرحمن الرحيم من محمد رسول الله إلى هرقل عظيم الروم السلام على من اتبع الهدى أما بعد فأسلم تسلم يؤتك الله أجرك مرتين وإن تتول فإن إثم الأكابر عليك\nقال ابن شهاب فأخبرني أسقف النصارى في زمن عبد الملك زعم أنه أدرك ذلك من أمر رسول الله وأمر هرقل وعقله قال فلما قدم عليه كتاب رسول الله من قبل دحية بن خليفة أخذه هرقل فجعله بين فخذيه وخاصرته ثم كتب إلى رجل برومية كان يقرأ العبرانية ما تقرأونه فذكر له أمره ووصف له شأنه وأخبره بما جاء به منه فكتب إليه صاحب رومية إنه النبي الذي كنا ننتظره لا شك فيه فاتبعه وصدقه قال فأمر هرقل ببطارقة الروم فجمعوا له في دسكرة\nملكه وأمر بها فأغلقت عليهم أبوابها ثم اطلع عليهم من علية وخافهم على نفسه فقال يا معشر الروم قد جمعتكم لخبر أتاني كتاب هذا الرجل يدعو إلى دينه فوالله إنه النبي الذي كنا ننتظره ونجده في كتابنا فهلم فلنبايعه ولنصدقه فتسلم لنا دنيانا وآخرتنا قال فنخرت الروم نخرة رجل واحد وابتدروا أبواب الدسكرة ليخرجوا فوجدوها قد أغلقت دونهم فقال كروهم علي وخافهم على نفسه فكروهم عليه فقال يا معشر الروم إنما قلت لكم المقالة التي قلت لأنظر كيف صلابتكم في دينكم في هذا الأمر الذي قد حدث فقد رأيت منكم الذي أسر به فخروا سجدا وأمر بأبواب الدسكرة ففتحت لهم فانطلقوا أخبرني الحسن بن علي قال حدثني محمد بن زكريا الغلابي قال حدثني أبو بكر الهذلي عن عكرمة عن ابن عباس قال قال لي العباس خرجت في تجارة إلى اليمن في ركب منهم أبو سفيان بن حرب فقدمت اليمن فكنت أصنع يوما طعاما وأنصرف بأبي سفيان وبالنفر ويصنع أبو سفيان يوما فيفعل مثل ذلك فقال لي في يومي الذي كنت أصنع فيه هل لك يا ابا الفضل أن تنصرف إلى بيتي وترسل إلي غدائك فقلت نعم فانصرفت أنا والنفر إلى بيته وأرسلت إلى الغداء فلما تغدى القوم قاموا واحتبسني فقال لي هل علمت يا أبا الفضل أن ابن أخيك يزعم أنه رسول الله قلت وأي بني أخي قال أبو سفيان إياي تكتم واي بني أخيك ينبغي له أن يقول هذا إلا رجل واحد قلت وأيهم هو على ذلك قال محمد بن عبد الله قلت ما فعل قال بلى قد فعل ثم أخرج إلي كتابا من ابنه حنظلة بن أبي سفيان إني أخبرك أن محمدا قام بالأبطح\nغدوة فقال أنا رسول الله أدعوكم إلى الله قال قلت يا أبا حنظلة لعله صادق قال مهلا يا أبا الفضل فوالله ما أحب أن تقول مثل هذا وإني لأخشى أن تكون على بصر من هذا الأمر وقال الحسن بن علي في روايته على بصيرة من هذا الحديث ثم قال يا بني عبد المطلب إنه والله ما برحت قريش تزعم أن لكم يمنة وشؤمة كل واحدة منهما عامة فنشدتك الله يا أبا الفضل هل سمعت ذلك قلت نعم قال فهذه والله إذا شؤمتكم قلت فلعلها يمنتنا فما كان بعد ذلك إلا ليال حتى قدم عبد الله بن حذافة السهمي بالخبر وهو مؤمن ففشا ذلك في مجالس أهل اليمن يتحدث به فيها وكان أبو سفيان يجلس إلى حبر من أحبار اليمن فقال له اليهودي ما هذا الخبر الذي بلغني قال هو ما سمعت قال أين فيكم عم هذا الرجل الذي قال ما قال قال أبو سفيان صدقوا وأنا عمه قال اليهودي أأخو أبيه قال نعم قال حدثني عنه قال لا تسألني فما كنت أحسب أن يدعي هذا الأمر أبدا وما أحب أن أعيبه وغيره خير منه قال اليهودي فليس به أذى ولا بأس على يهود وتوراة موسى منه قال العباس فتأدى إلي الخبر فحميت وخرجت حتى أجلس إلى ذلك المجلس من غد وفيه أبو سفيان والحبر فقلت للحبر بلغني أنك سألت ابن عمي هذا عن رجل منا يزعم أنه رسول الله فأخبرك أنه عمه وليس بعمه ولكنه ابن عمه وأنا عمه أخو أبيه فقال أأخو أبيه قلت أخو أبيه فأقبل على أبي سفيان فقال أصدق قال نعم صدق قال فقلت سلني عنه فإن كذبت فليردد علي فأقبل علي فقال أنشدك الله هل فشت لإبن أخيك صبوة أو سفهة قال قلت لا وإله عبد المطلب ولا كذب ولا خان وإن كان اسمه عند قريش الأمين قال فهل كتب بيده قال عباس فظننت أنه","topic":"ذكر ابي سفيان وأخباره ونسبه","topicNo":69,"sp":4,"spl":"كتاب النبي إلى هرقل"},
{"id":"b69-6","bab":"الجزء 6","sec":"كتاب النبي إلى هرقل","page":"ج6 ص364","text":"خير له أن يكتب بيده فأردت أن أقولها ثم ذكرت مكان أبي سفيان وأنه مكذبي وراد علي فقلت لا يكتب فذهب الحبر وترك رداءه وجعل يصيح ذبحت يهود قتلت يهود قال العباس فلما رجعنا إلى منزلنا قال أبو سفيان يا أبا الفضل إن اليهودي لفزع من ابن أخيك قال قلت قد رأيت ما رأيت فهل لك يا أبا سفيان أن تؤمن به فإن إن حقا كنت قد سبقت وإن كان باطلا فمعك غيرك من أكفائك قال لا والله ما أومن به حتى أرى تطلع من كداء وهو جبل بمكة قال قلت ما تقول قال كلمة والله جاءت على فمي ما ألقيت لها بالا إلا أني أعلم أن الله لا يترك خيلا تطلع من كداء قال العباس فلما فتح رسول الله مكة ونظرنا إلى الخيل قد طلعت من كداء قلت يا أبا سفيان أتذكر الكلمة قال لي والله إني لذاكرها فالحمد لله الذي هداني للإسلام","topic":"ذكر ابي سفيان وأخباره ونسبه","topicNo":69,"sp":5,"spl":"كتاب النبي إلى هرقل"},
{"id":"b69-7","bab":"الجزء 6","sec":"إسلامه في غزاة الفتح","page":"ج6 ص367","text":"حدثنا محمد بن جرير الطبري قال حدثنا البغوي قال حدثنا الغلابي أبو كريب محمد بن العلاء قال حدثنا يونس بن بكير عن محمد بن إسحاق قال حدثني الحسين بن عبيد الله بن العباس عن عكرمة عن ابن عباس قال لما نزل رسول الله مر الظهران يعني في غزاة الفتح قال العباس بن عبد المطلب وقد خرج رسول الله من المدينة يا صباح قريش والله لئن\nبغتها رسول الله إنها لهلاك قريش آخر الدهر فجلس على بغلة رسول الله البيضاء وقال أخرج إلى الأراك لعلي أرى حطابا أو صاحب لبن أو داخلا يدخل مكة فيخبرهم بمكان رسول الله فيستأمنونه فوالله إني لأطوف في الأراك ألتمس ما خرجت له إذ سمعت صوت أبي سفيان وحكيم بن حزام وبديل بن ورقاء يتجسسون الخبر عن رسول الله فسمعت أبا سفيان وهو يقول والله ما رأيت كالليلة قط نيرانا فقال بديل بن ورقاء هذه والله نيران خزاعة حمشتها الحرب فقال أبو سفيان خزاعة ألأم من ذلك وأذل فعرفت صوته فقلت أبا حنظلة فقال أبا الفضل قلت نعم فقال لبيك فداؤك أبي وأمي فما وراءك فقلت هذا رسول الله قد دلف إليكم بما لا قبل لكم به بعشرة آلاف من المسلمين قال فما تأمرني فقلت تركب عجز هذه البغلة فأستأمن لك رسول الله فوالله لئن ظفر بك ليضربن عنقك فردفني فخرجت به أركض بغلة رسول الله نحو رسول الله فكلما مررت بنار من نيران المسلمين فنظروا إلي قالوا عم رسول الله على بغلة رسول الله حتى مررنا بنار عمر بن الخطاب رضي الله تعالى عنه فقال أبو سفيان الحمد لله الذي أمكن منك بغير عقد ولا عهد ثم اشتد نحو النبي وركضت البغلة وقد أردفت أبا سفيان قال العباس حتى اقتحمت على باب القبة وسبقت عمر بما تسبق به الدابة البطيئة\nالرجل البطيء فدخل عمر على رسول الله فقال يا رسول الله هذا أبو سفيان قد أمكن الله منه بغير عهد ولا عقد فدعني أضرب عنقه قلت يا رسول الله إني قد أجرته ثم جلست إلى رسول الله وأخذت برأسه وقلت والله لا يناجيه اليوم أحد دوني فلما أكثر فيه عمر قلت مهلا يا عمر فوالله ما تصنع هذا إلا لأنه رجل من عبد مناف ولو كان من بني عدي بن كعب ما قلت هذا قال مهلا يا عباس فوالله لإسلامك يوم أسلمت كان أحب إلي من إسلام الخطاب لو أسلم وذلك لأني أعلم أن إسلامك أحب إلى رسول الله من إسلام الخطاب لو أسلم فقال رسول الله ( اذهب فقد أمناه حتى تغدو به علي الغداة\nفرجع به إلى منزله فلما أصبح غدا به على رسول الله فلما رآه قال ( ويحك أبا سفيان ألم يأن لك أن تعلم أن لا إله إلا الله\nفقال بأبي أنت وأمي ما أوصلك وأحلمك وأكرمك والله لقد ظننت أن لو كان مع الله غيره لقد أغنى عني شيئا فقال ( ويحك تشهد بشهادة الحق قبل والله أن تضرب عنقك\nقال فتشهد فقال رسول الله للعباس من حين تشهد أبو سفيان ( انصرف يا عباس فاحتبسه عند خطم الجبل بمضيق الوادي حتى يمر عليه جنود الله\nفقلت يا رسول الله إن أبا سفيان رجل يحب الفخر فاجعل له شيئا يكون في قومه فقال ( نعم من دخل دار أبي سفيان فهو آمن ومن دخل المسجد فهو آمن ومن أغلق عليه بابه فهو آمن\nخرجت به حتى أجلسته عند خطم الجبل بمضيق الوادي فمرت عليه القبائل فجعل يقول من هؤلاء فأقول سليم فيقول ما لي ولسليم ثم تمر به قبيلة فيقول من هؤلاء فأقول أسلم فيقول ما لي ولأسلم وتمر به جهينة فيقول من هؤلاء فأقول جهينة فيقول ما لي ولجهينة حتى مر رسول الله في الخضراء كتيبة رسول الله من المهاجرين والأنصار في الحديد لا يرى منهم إلا الحدق فقال من هؤلاء يا أبا الفضل فقلت هذا رسول الله في المهاجرين والأنصار فقال يا أبا الفضل لقد أصبح ملك ابن أخيك عظيما فقلت ويحك إنها النبوة قال نعم إذا فقلت الحق الآن بقومك فحذرهم فخرج سريعا حتى أتى مكة فصرخ في المسجد يا معشر قريش هذا محمد قد جاءكم بما لا قبل لكم به قالوا فمه قال من دخل داري فهو آمن فقالوا\nويحك ما تغني عنا دارك قال ومن دخل المسجد فهو آمن ومن أغلق عليه بابه فهو آمن","topic":"ذكر ابي سفيان وأخباره ونسبه","topicNo":69,"sp":6,"spl":"إسلامه في غزاة الفتح"},
{"id":"b69-8","bab":"الجزء 6","sec":"عدم إخلاصه الإسلام","page":"ج6 ص370","text":"حدثنا محمد بن جرير وأحمد بن الجعد قالا حدثنا محمد بن حميد قال حدثنا سلمة بن الفضل عن محمد بن إسحاق عن يحى بن عباد عن عبد الله بن الزبير قال لما كان يوم اليرموك خلفني أبي فأخذت فرسا له وخرجت فرأيت جماعة من الخلفاء فيهم أبو سفيان بن حرب فوقفت معه فكانت الروم إذا هزمت المسلمين قال أبو سفيان إيه بني الأصفر فإذا كشفهم المسلمون قال أبو سفيان\n(وبنو الأصفر الكرام ملوك الروم ... لم يبق منهم مذكور)\nلما فتح الله على المسلمين حدثت أبي فقال قاتله الله يأبى إلا نفاقا أولسنا خيرا له من بني الأصفر ثم كان يأخذ بيدي فيطوف على أصحاب رسول الله يقول حدثهم فأحدثهم فيعجبون من نفاقه حدثني أحمد بن الجعد قال حدثني ابن حميد قال حدثنا جرير عن عمرو بن ثابت عن الحسن قال دخل أبو سفيان على عثمان بعد أن كف بصره فقال هل علينا من عين فقال له عثمان لا فقال يا عثمان إن الأمر أمر عالمية والملك ملك جاهلية فاجعل أوتاد الأرض بني أمية حدثني محمد بن حيان الباهلي قال حدثنا عمر بن علي الفلاس قال حدثنا سهل بن يوسف عن مالك بن مغول عن أشعث بن أبي الشعثاء عن ميسرة الهمداني عن أبي الأبجر الأكبر قال جاء أبو سفيان إلى علي بن أبي طالب رضي الله عنه فقال يا أبا الحسن\nما بال هذا الأمر في أضعف قريش وأقلها فوالله لئن شئت لأملأنها عليهم خيلا ورجلا فقال له علي بن أبي طالب رضي الله عنه يا أبا سفيان طالما عاديت الله ورسوله فما ضرهم ذلك شيئا إنا وجدنا أبا بكر لها أهلا أخبرنا محمد بن العباس اليزيدي قال حدثنا الرياشي قال أنشدني ابن عائشة لأبي سفيان بن حرب لما ولي أبو بكر قال\n(وأضحت قريش بعد عز ومنعة ... خضوعا لتيم لا بضرب القواضب)\n(فيا لهف نفسي للذي ظفرت به ... وما زال منها فائزا بالغرائب)\nحدثني أحمد بن الجعد قال حدثني محمد بن حميد قال حدثنا جرير عن عمرو بن ثابت عن الحسن قال لما ولي عثمان الخلافة دخل عليه أبو سفيان فقال يا معشر بني أمية إن الخلافة صارت في تيم وعدي حتى طمعت فيها وقد صارت إليكم فتلقفوها بينكم تلقف الكرة فوالله ما من جنة ولا نار هذا أو نحوه فصاح به عثمان قم عني فعل الله بك وفعل ولأبي سفيان أخبار من هذا الجنس ونحوه كثيرة يطول ذكرها وفيما ذكرت منها مقنع والأبيات التي فيها الغناء يقولها في سلام بن مشكم اليهودي ويكنى أبا غنم وكان نزل عليه في غزوة السويق فقراه وأحسن ضيافته فقال أبو سفيان فيه\n(سقاني فرواني كميتا مدامة ... على ظمأ مني سلام بن مشكم)\n(تخيرته أهل المدينة واحدا ... سواهم فلم أغبن ولم أتندم)\n(فلما تقضى الليل قلت ولم أكن ... لأفرحه أبشر بعرف ومغنم)\n(وإن أبا غنم يجود وداره ... بيثرب مأوى كل أبيض خضرم)","topic":"ذكر ابي سفيان وأخباره ونسبه","topicNo":69,"sp":7,"spl":"عدم إخلاصه الإسلام"},
{"id":"b69-9","bab":"الجزء 6","sec":"ذكر الخبر عن غزوة السويق ونزول أبي سفيان على سلام بن مشكم","page":"ج6 ص373","text":"كانت هذه الغزاة بعد وقعة بدر وذلك أن أبا سفيان نذر ألا يمس رأسه ماء من جنابة ولا يشرب خمرا حتى يغزو رسول الله فخرج في عدة من قومه ولم يصنع شيئا فعيرته قريش بذلك وقالوا إنما خرجتم تشربون السويق فسميت غزوة السويق حدثنا محمد بن جرير قرأته عليه قال حدثنا محمد بن حميد قال حدثنا سلمة بن الفضل عن محمد بن إسحاق عن محمد بن جعفر بن الزبير ويزيد بن رومان عن عبيد الله بن كعب بن مالك وكان من أعلم الأنصار قال كان أبو سفيان حين رجع إلى مكة ورجع قبل قريش من بدر نذر ألا يمس ماء من جنابة حتى يغزو محمدا فخرج في مائتي راكب من قريش ليبر يمينه فسلك النجدية حتى نزل بصدر قناة إلى جبل يقال له تيت من المدينة على بريد أو نحوه ثم خرج من الليل حتى أتى بني النضير تحت الليل فأتى حيي بن أخطب بيثرب فدق عليه بابه فأبى أن يفتح له وخافه وانصرف إلى سلام بن\nمشكم وكان سيد بني النضير في زمانه ذلك وصاحب كنزهم فاستأذن عليه فأذن له فقراه وسقاه ونظر له خبر الناس ثم خرج في عقب ليلته حتى جاء أصحابه فبعث رجالا من قريش إلى المدينة فأتوا ناحية منها يقال لها العريض فحرقوا في أصوار من نخل لها أتوا رجلا من الأنصار وحليفا له في حرث لهما فقتلوهما ثم انصرفوا راجعين فنذر بهم الناس فخرج رسول الله في طلبهم حتى بلغ قرقرة الكدر ثم انصرف راجعا وقد فاته أبو سفيان وأصحابه وقد رأوا من مزاود القوم ما قد طرحوه في الحرث يتخففون منه للنجاء فقال المسلمون حين رجع بهم رسول الله أنطمع أن تكون غزوة قال نعم وقد كان أبو سفيان قال وهو يتجهز خارجا من مكة إلى المدينة أبياتا من شعر يحرض فيها قريشا فقال\n(كروا على يثرب وجمعهم ... فإن ما جمعوا لكم نفل)\n(إن يك يوم القليب كان لهم ... فإن ما بعده لكم دول)\n(آليت لا أقرب النساء ولا ... يمس رأسي وجلدي الغسل)\n(حتى تبيدوا قبائل الأوس والخزرج ... إن الفؤاد مشتعل)\nأجابه كعب بن مالك\n(يا لهف أم المسبحين على ... جيش ابن حرب بالحرة الفشل)\n(أتطرحون الرجال من سنم الظهر ... ترقى في قنة الجبل)\n(جاؤوا بجمع لو قيس منزله ... ما كان إلا كمعرس الدئل)\n(عار من النصر والثراء ومن ... نجدة أهل البطحاء والأسل)\nخبرني الحسن بن علي الخفاف قال أخبرنا الحارث بن أبي أسامة قال حدثنا سليمان بن سعد عن الواقدي أن غزوة السويق كانت في ذي القعدة من سنة ثنتين من الهجرة حدثني عمي قال حدثنا الحارث بن أبي أسامة قال حدثنا ابن سعد عن الواقدي عن أبي الزناد عن عبد الله بن الحارث قال شرب حسان بن ثابت يوما مع سلام بن مشكم وكان له نديما معهم كعب بن أسد وعبد الله بن أبي وقيس بن الخطيم فأسرع الشراب فيهم\nوكانوا في موادعة وقد وضعت الحرب أوزارها بينهم فقال قيس بن الخطيم لحسان تعال أشاربك فتشاربا في إناء عظيم فأبقى حسان من الإناء شيئا فقال له قيس اشرب فقال حسان وعرف الشر في وجهه أو خيرا من ذلك أجعل لك الغلبة قال لا إلا أن تشربه فأبى حسان وقال له سلام بن مشكم يا أبا يزيد لا تكرهه على ما لا يشتهي إنما دعوته لإكرامه ولم تدعه لتستخف به وتسيء مجالسته فقال له قيس أفتدعوني أنت على أن تسيء مجالستي فقال له سلام ما في هذا سوء مجالسة وما حملت عليك إلا لأنك مني وأني حليفك وليست عليك غضاضة في هذا وهذا رجل من الخزرج قد أكرمته وأدخلته منزلي فيجب أن تكرم لي من أكرمته ولعمري إن في الصحو لما تكتفون به من حروبكم فافترقوا وآلى سلام بن مشكم على نفسه ألا يشرب سنة وقد بلغ هذا من نديمه وكان كريما صوت","topic":"ذكر ابي سفيان وأخباره ونسبه","topicNo":69,"sp":8,"spl":"ذكر الخبر عن غزوة السويق ونزول أبي سفيان على سلام بن مشكم — من المائة المختارة"},
{"id":"b69-10","bab":"الجزء 6","sec":"من المائة المختارة","page":"ج6 ص376","text":"(من مبلغ عني أبا كامل ... أني إذا ما غاب كالهامل)\n(قد زادني شوقا إلى قربه ... مع ما بدا من رأيه الفاضل)\nالشعر للوليد بن يزيد والغناء لأبي كامل ولحنه المختار من الثقيل الأول\nبإطلاق الوتر في مجرى البنصر عن إسحاق وذكر حبش أن لأبي كامل فيه أيضا لحنا من خفيف الثقيل الثاني بالوسطى","topic":"ذكر ابي سفيان وأخباره ونسبه","topicNo":69,"sp":8,"spl":"ذكر الخبر عن غزوة السويق ونزول أبي سفيان على سلام بن مشكم — من المائة المختارة"}]);